BEGIN;

DO $preflight$
DECLARE
  v_bytes bytea;
  v_uuid text;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = 'pgcrypto' AND n.nspname = 'extensions'
  ) THEN
    RAISE EXCEPTION 'opportunity_v3 preflight: pgcrypto must be installed in extensions';
  END IF;
  IF to_regprocedure('extensions.digest(bytea,text)') IS NULL THEN
    RAISE EXCEPTION 'opportunity_v3 preflight: extensions.digest(bytea,text) unavailable';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role' AND rolbypassrls) THEN
    RAISE EXCEPTION 'opportunity_v3 preflight: service_role must exist with BYPASSRLS';
  END IF;
  v_bytes := substring(extensions.digest(
    decode(replace('6ba7b810-9dad-11d1-80b4-00c04fd430c8','-',''),'hex')
      || convert_to('www.widgets.com','utf8'), 'sha1') FROM 1 FOR 16);
  v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
  v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
  v_uuid := substr(encode(v_bytes,'hex'),1,8)||'-'||substr(encode(v_bytes,'hex'),9,4)||'-'
    ||substr(encode(v_bytes,'hex'),13,4)||'-'||substr(encode(v_bytes,'hex'),17,4)||'-'||substr(encode(v_bytes,'hex'),21,12);
  IF v_uuid <> '21f7f8de-8051-5b89-8680-0195ef798b6a' THEN
    RAISE EXCEPTION 'opportunity_v3 preflight: UUIDv5 DNS vector mismatch';
  END IF;
  v_bytes := substring(extensions.digest(
    decode(replace('7ad3ec9e-4db5-5e8a-b9a4-eab35ddc1a21','-',''),'hex')
      || convert_to(repeat('0',64),'utf8'), 'sha1') FROM 1 FOR 16);
  v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
  v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
  v_uuid := substr(encode(v_bytes,'hex'),1,8)||'-'||substr(encode(v_bytes,'hex'),9,4)||'-'
    ||substr(encode(v_bytes,'hex'),13,4)||'-'||substr(encode(v_bytes,'hex'),17,4)||'-'||substr(encode(v_bytes,'hex'),21,12);
  IF v_uuid <> '5a7bd9c3-2aa1-5dd0-9e18-b4e4d3401e69' THEN
    RAISE EXCEPTION 'opportunity_v3 preflight: UUIDv5 job vector mismatch';
  END IF;
  v_bytes := substring(extensions.digest(
    decode(replace('51689af8-f3fe-5d1e-a18f-c667ddee224a','-',''),'hex')
      || convert_to('["00000000-0000-0000-0000-000000000000","rows",0]','utf8'), 'sha1') FROM 1 FOR 16);
  v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
  v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
  v_uuid := substr(encode(v_bytes,'hex'),1,8)||'-'||substr(encode(v_bytes,'hex'),9,4)||'-'
    ||substr(encode(v_bytes,'hex'),13,4)||'-'||substr(encode(v_bytes,'hex'),17,4)||'-'||substr(encode(v_bytes,'hex'),21,12);
  IF v_uuid <> '9b46c201-57ed-59cc-987c-98da5efc80ad' THEN
    RAISE EXCEPTION 'opportunity_v3 preflight: UUIDv5 page vector mismatch';
  END IF;
END
$preflight$;

DO $rpc_owner$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='opportunity_v3_rpc_owner') THEN
    CREATE ROLE opportunity_v3_rpc_owner NOLOGIN NOBYPASSRLS;
  END IF;
  IF EXISTS (
    SELECT 1 FROM pg_roles
    WHERE rolname='opportunity_v3_rpc_owner' AND (rolcanlogin OR rolbypassrls)
  ) THEN
    RAISE EXCEPTION 'opportunity_v3 preflight: opportunity_v3_rpc_owner attributes invalid';
  END IF;
END
$rpc_owner$;

-- Managed PostgreSQL administrators commonly have CREATEROLE without SUPERUSER.
-- PostgreSQL requires SET membership in a target role before transferring object
-- ownership to it. Keep the managed migration administrator as a member of this
-- NOLOGIN owner role so idempotent reapplication and administrator-owned helper
-- functions retain the same closed table authority; no application role is added.
GRANT opportunity_v3_rpc_owner TO CURRENT_USER;

GRANT USAGE, CREATE ON SCHEMA public TO opportunity_v3_rpc_owner;
GRANT USAGE ON SCHEMA extensions TO opportunity_v3_rpc_owner;
GRANT EXECUTE ON FUNCTION extensions.digest(bytea,text) TO opportunity_v3_rpc_owner;
GRANT EXECUTE ON FUNCTION extensions.gen_random_uuid() TO opportunity_v3_rpc_owner;
GRANT EXECUTE ON FUNCTION extensions.gen_random_bytes(integer) TO opportunity_v3_rpc_owner;

DO $types$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'opportunity_mode_v3') THEN
    CREATE TYPE opportunity_mode_v3 AS ENUM ('source_scan','enrich_rank','label_outcomes','shadow_evaluate');
    CREATE TYPE opportunity_run_purpose_v3 AS ENUM ('ad_hoc_shadow','production_shadow_daily','backtest_daily_primary','outcome_label_daily','shadow_evaluation_daily');
    CREATE TYPE opportunity_run_status_v3 AS ENUM ('preparing','running','success','failed','converged');
    CREATE TYPE opportunity_job_status_v3 AS ENUM ('queued','leased','succeeded','retryable','failed','cancelled');
    CREATE TYPE opportunity_job_stage_v3 AS ENUM ('authority_manifest','input_manifest_pages','seal_inputs','source_documents','shallow_enrich','deep_research','portfolio_allocate','project','label','evaluate','finalize');
    CREATE TYPE opportunity_manifest_status_v3 AS ENUM ('building','complete','failed');
    CREATE TYPE opportunity_manifest_kind_v3 AS ENUM ('source_eligible','source_identity_allowlist','publisher_verification_allowlist','instrument_roster','alias_authority','taxonomy_assignment','peer_reviewer_allowlist','peer_authority','source_dataset','candidate_financial','factor_scoring_reference','sector_scoring_reference','sector_valuation_reference','bias_reference','technical_history_reference','reported_pe_reference','market_reference','mover_price_reference','sector_benchmark','outcome_input','evaluation_input','link_audit_sample','link_audit_resolution');
    CREATE TYPE opportunity_horizon_v3 AS ENUM ('momentum_5_20d','swing_20_60d','thesis_120_250d');
    CREATE TYPE opportunity_outcome_maturity_v3 AS ENUM ('session_20','session_60','session_120','session_250');
    CREATE TYPE opportunity_engine_warning_v3 AS ENUM ('connector_degraded','market_incomplete','sector_cycle_unknown','source_audit_pending','prior_lineage_missing','valuation_missing','shadow_only');
    CREATE TYPE internal_principal_role_v3 AS ENUM ('opportunity_runner','source_reviewer','identity_reviewer','publisher_reviewer','peer_reviewer_admin','peer_reviewer','valuation_reviewer','model_reviewer','link_reviewer','link_adjudicator');
    CREATE TYPE authority_status_v3 AS ENUM ('active','inactive');
    CREATE TYPE source_class_v3 AS ENUM ('official','public_research','curated_thesis','community');
    CREATE TYPE source_acquisition_status_v3 AS ENUM ('complete','invalid_utf8','required_field_missing','content_overflow');
  END IF;
END
$types$;

