    CREATE TYPE price_observation_input_v3 AS (stock_id uuid,exchange stock_exchange_v3,session_id date,session_authority_id uuid,raw_open double precision,raw_high double precision,raw_low double precision,raw_close double precision,volume double precision,turnover_twd double precision,provider price_provider_v3,source_timestamp timestamptz,collected_at timestamptz,source_ref text);
