    CREATE TYPE corporate_action_event_input_v3 AS (symbol text,event_kind corporate_action_kind_v3,pre_action_reference_price double precision,post_action_reference_price double precision,feed_identity text,source_row_ref text);
    CREATE TYPE corporate_action_snapshot_input_v3 AS (exchange stock_exchange_v3,session_id date,session_authority_id uuid,corporate_action_version text,provider official_roster_provider_v3,collected_at timestamptz,feed_evidence corporate_action_feed_evidence_input_v3[],declared_event_count integer,events corporate_action_event_input_v3[]);
    CREATE TYPE exchange_reported_pe_input_v3 AS (stock_id uuid,exchange stock_exchange_v3,session_date date,close double precision,reported_pe double precision,published_at timestamptz,source_timestamp timestamptz,collected_at timestamptz,source_ref text);
    CREATE TYPE price_authority_input_v3 AS (kind price_authority_kind_v3,raw_price price_observation_input_v3,corporate_action_snapshot corporate_action_snapshot_input_v3,exchange_reported_pe exchange_reported_pe_input_v3);
    CREATE TYPE market_observation_input_v3 AS (fact_key market_fact_key_v3,scope_key market_scope_key_v3,session_id date,session_authority_id uuid,value double precision,unit market_unit_v3,provider market_provider_v3,provider_identity text,breadth_numerator_count integer,breadth_observed_count integer,breadth_eligible_count integer,breadth_roster_manifest_id uuid,breadth_roster_manifest_hash text,observed_at timestamptz,collected_at timestamptz,source_ref text,provider_revision text);
