    CREATE TYPE financial_fact_input_v3 AS (stock_id uuid,fact_key financial_fact_key_v3,period_start date,period_end date,duration_kind financial_duration_kind_v3,value double precision,unit financial_unit_v3,provider financial_provider_v3,authority_tier financial_authority_tier_v3,estimate_kind financial_estimate_kind_v3,estimate_horizon financial_estimate_horizon_v3,filing_published_at timestamptz,source_timestamp timestamptz,collected_at timestamptz,filing_restatement_id text,source_ref text);
    CREATE TYPE opportunity_manifest_row_input_v3 AS (row_ordinal bigint,identity_key text,terminal_code text,payload_canonical bytea,payload_json jsonb,payload_hash text);
    CREATE TYPE opportunity_job_counts_v3 AS (manifest_row_count bigint,connector_accounting_count integer,source_document_count integer,claim_count integer,mention_count integer,candidate_count integer,deep_success_candidate_count integer,deep_failure_candidate_count integer,market_snapshot_count integer,sector_snapshot_count integer,score_snapshot_count integer,outcome_count integer,public_projection_count integer,detail_projection_count integer,evaluation_result_count integer,warning_count integer);
  END IF;
END
$composite_types$;

CREATE TABLE IF NOT EXISTS internal_principal_role_bindings_v3 (
  binding_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  principal_id uuid NOT NULL,
  role internal_principal_role_v3 NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  status authority_status_v3 NOT NULL,
  configuration_hash text NOT NULL CHECK (configuration_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (valid_to IS NULL OR valid_to > valid_from)
);
CREATE INDEX IF NOT EXISTS internal_principal_role_bindings_v3_lookup
  ON internal_principal_role_bindings_v3 (principal_id, role, recorded_at DESC, binding_id);

CREATE TABLE IF NOT EXISTS internal_principal_nonces_v3 (
  principal_id uuid NOT NULL,
  nonce text NOT NULL CHECK (nonce ~ '^[0-9a-f]{16,64}$'),
  request_timestamp timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (principal_id, nonce)
);
CREATE INDEX IF NOT EXISTS internal_principal_nonces_v3_expiry
  ON internal_principal_nonces_v3 (recorded_at, principal_id, nonce);

CREATE TABLE IF NOT EXISTS opportunity_rpc_audit_v3 (
  audit_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  function_name opportunity_rpc_function_name_v3 NOT NULL,
  caller_principal_id uuid NOT NULL,
  subject_kind opportunity_rpc_subject_kind_v3 NOT NULL,
  subject_id uuid,
  input_hash text NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
  disposition opportunity_rpc_audit_disposition_v3 NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS opportunity_rpc_audit_v3_function_time
  ON opportunity_rpc_audit_v3 (function_name, recorded_at DESC, audit_id);

CREATE TABLE IF NOT EXISTS source_identity_authorities_v3 (
  authority_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  source_identity_id uuid NOT NULL REFERENCES source_entities(id) ON DELETE RESTRICT,
  source_key source_key_v3 NOT NULL,
  source_class source_class_v3 NOT NULL,
  distribution_identity text NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  status authority_status_v3 NOT NULL,
  approved_at timestamptz NOT NULL,
  approving_principal_id uuid NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (authority_id, source_identity_id, source_key),
  CHECK (valid_to IS NULL OR valid_to > valid_from)
);
CREATE INDEX IF NOT EXISTS source_identity_authorities_v3_stream
  ON source_identity_authorities_v3 (source_identity_id, recorded_at DESC, authority_id);

CREATE TABLE IF NOT EXISTS source_revision_family_registry_v3 (
  source_key source_key_v3 NOT NULL,
  revision_family_key text NOT NULL CHECK (revision_family_key ~ '^[0-9a-f]{64}$'),
  approved_source_identity_id uuid NOT NULL REFERENCES source_entities(id) ON DELETE RESTRICT,
  stable_connector_document_id text NOT NULL,
  registered_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (source_key, revision_family_key),
  UNIQUE (source_key, approved_source_identity_id, stable_connector_document_id)
);

CREATE TABLE IF NOT EXISTS opportunity_authority_stream_registry_v3 (
  family authority_stream_family_v3 NOT NULL,
  stream_key_hash text NOT NULL CHECK (stream_key_hash ~ '^[0-9a-f]{64}$'),
  stream_key_canonical bytea NOT NULL CHECK (octet_length(stream_key_canonical) BETWEEN 1 AND 4096),
  registered_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (family, stream_key_hash),
  UNIQUE (family, stream_key_canonical),
  CHECK (stream_key_hash = encode(extensions.digest(stream_key_canonical, 'sha256'), 'hex'))
);
CREATE INDEX IF NOT EXISTS opportunity_authority_stream_registry_v3_lookup
  ON opportunity_authority_stream_registry_v3 (family, stream_key_hash, stream_key_canonical);

CREATE TABLE IF NOT EXISTS source_document_revisions_v3 (
  revision_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  revision_family_key text NOT NULL CHECK (revision_family_key ~ '^[0-9a-f]{64}$'),
  source_key source_key_v3 NOT NULL,
  source_identity_authority_id uuid NOT NULL,
  approved_source_identity_id uuid NOT NULL REFERENCES source_entities(id) ON DELETE RESTRICT,
  stable_connector_document_id text NOT NULL,
  canonical_url_candidate text,
  published_at timestamptz,
  collected_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  adapter_version text NOT NULL CHECK (adapter_version = 'source-adapter-v3.3'),
  acquisition_status source_acquisition_status_v3 NOT NULL,
  raw_field_payload jsonb,
  raw_code_point_count integer NOT NULL CHECK (raw_code_point_count BETWEEN 0 AND 100001),
  raw_field_payload_algorithm_version text NOT NULL,
  ingestion_content_revision_sha256 text,
  canonical_content_algorithm_version text NOT NULL,
  ingestion_canonical_content_hash_v3 text,
  supersedes_revision_id uuid REFERENCES source_document_revisions_v3(revision_id) ON DELETE RESTRICT,
  FOREIGN KEY (source_identity_authority_id, approved_source_identity_id, source_key)
    REFERENCES source_identity_authorities_v3(authority_id, source_identity_id, source_key) ON DELETE RESTRICT,
  FOREIGN KEY (source_key, revision_family_key)
    REFERENCES source_revision_family_registry_v3(source_key, revision_family_key) ON DELETE RESTRICT,
  CHECK (
    (acquisition_status = 'complete' AND raw_field_payload IS NOT NULL
      AND ingestion_content_revision_sha256 ~ '^[0-9a-f]{64}$'
      AND ingestion_canonical_content_hash_v3 ~ '^[0-9a-f]{64}$'
      AND raw_code_point_count <= 100000)
    OR
    (acquisition_status <> 'complete' AND raw_field_payload IS NULL
      AND ingestion_content_revision_sha256 IS NULL
      AND ingestion_canonical_content_hash_v3 IS NULL)
  ),
  CHECK (collected_at <= recorded_at),
  CHECK (raw_field_payload_algorithm_version = 'raw-field-payload-v3.0'),
  CHECK (canonical_content_algorithm_version = 'canonical-content-v3.0'),
  CHECK (
    (acquisition_status = 'content_overflow' AND raw_code_point_count = 100001)
    OR (acquisition_status <> 'content_overflow' AND raw_code_point_count <= 100000)
  )
);
CREATE INDEX IF NOT EXISTS source_document_revisions_v3_stream
  ON source_document_revisions_v3 (source_key, revision_family_key, recorded_at DESC, revision_id);

CREATE TABLE IF NOT EXISTS stock_instruments_v3 (
  instrument_authority_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  symbol text NOT NULL CHECK (symbol ~ '^[0-9]{4}$'),
  exchange stock_exchange_v3 NOT NULL,
  instrument_type instrument_type_v3 NOT NULL,
  listing_status listing_status_v3 NOT NULL,
  official_legal_name text NOT NULL CHECK (char_length(official_legal_name) BETWEEN 2 AND 120),
  official_short_name text CHECK (official_short_name IS NULL OR char_length(official_short_name) BETWEEN 2 AND 40),
  official_name text GENERATED ALWAYS AS (
    CASE WHEN official_short_name IS NOT NULL THEN official_short_name
         WHEN char_length(official_legal_name) <= 40 THEN official_legal_name END
  ) STORED,
  provider official_roster_provider_v3 NOT NULL,
  source_timestamp timestamptz NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  roster_version text NOT NULL CHECK (roster_version = 'tw-instrument-roster-v3.0'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (valid_to IS NULL OR valid_to > valid_from),
  CHECK (
    (exchange='TWSE' AND provider='twse')
    OR (exchange='TPEX' AND provider='tpex')
  )
);
CREATE INDEX IF NOT EXISTS stock_instruments_v3_stream
  ON stock_instruments_v3 (stock_id, recorded_at DESC, instrument_authority_id);
CREATE UNIQUE INDEX IF NOT EXISTS stock_instruments_v3_immutable_identity
  ON stock_instruments_v3 (
    stock_id,symbol,exchange,instrument_type,listing_status,official_legal_name,
    official_short_name,provider,source_timestamp,valid_from,valid_to,roster_version
  ) NULLS NOT DISTINCT;

CREATE TABLE IF NOT EXISTS stock_sector_assignments_v3 (
  assignment_authority_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  market tw_market_v3 NOT NULL,
  official_industry_code text NOT NULL,
  canonical_sector_key canonical_sector_key_v3 NOT NULL,
  provider official_roster_provider_v3 NOT NULL,
  source_timestamp timestamptz NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  taxonomy_version text NOT NULL CHECK (taxonomy_version = 'tw-sector-taxonomy-v3.0'),
  status authority_status_v3 NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (valid_to IS NULL OR valid_to > valid_from),
  CHECK (
    (market='TWSE' AND provider='twse')
    OR (market='TPEX' AND provider='tpex')
  ),
  CHECK (
    canonical_sector_key = CASE official_industry_code
      WHEN '01' THEN 'cement'::canonical_sector_key_v3
      WHEN '02' THEN 'food'::canonical_sector_key_v3
      WHEN '03' THEN 'plastics'::canonical_sector_key_v3
      WHEN '04' THEN 'textile'::canonical_sector_key_v3
      WHEN '05' THEN 'electrical_machinery'::canonical_sector_key_v3
      WHEN '06' THEN 'electrical_cable'::canonical_sector_key_v3
      WHEN '08' THEN 'glass_ceramic'::canonical_sector_key_v3
      WHEN '09' THEN 'paper_pulp'::canonical_sector_key_v3
      WHEN '10' THEN 'steel'::canonical_sector_key_v3
      WHEN '11' THEN 'rubber'::canonical_sector_key_v3
      WHEN '12' THEN 'auto'::canonical_sector_key_v3
      WHEN '14' THEN 'construction'::canonical_sector_key_v3
      WHEN '15' THEN 'shipping_transport'::canonical_sector_key_v3
      WHEN '16' THEN 'tourism'::canonical_sector_key_v3
      WHEN '17' THEN 'finance_insurance'::canonical_sector_key_v3
      WHEN '18' THEN 'department_store'::canonical_sector_key_v3
      WHEN '20' THEN 'other'::canonical_sector_key_v3
      WHEN '21' THEN 'chemical'::canonical_sector_key_v3
      WHEN '22' THEN 'biotech_medical'::canonical_sector_key_v3
      WHEN '23' THEN 'oil_gas_electricity'::canonical_sector_key_v3
      WHEN '24' THEN 'semiconductor'::canonical_sector_key_v3
      WHEN '25' THEN 'computer_peripheral'::canonical_sector_key_v3
      WHEN '26' THEN 'optoelectronics'::canonical_sector_key_v3
      WHEN '27' THEN 'communications_network'::canonical_sector_key_v3
      WHEN '28' THEN 'electronic_components'::canonical_sector_key_v3
      WHEN '29' THEN 'electronic_distribution'::canonical_sector_key_v3
      WHEN '30' THEN 'information_service'::canonical_sector_key_v3
      WHEN '31' THEN 'other_electronics'::canonical_sector_key_v3
      WHEN '32' THEN 'green_energy_environment'::canonical_sector_key_v3
      WHEN '33' THEN 'digital_cloud'::canonical_sector_key_v3
      WHEN '34' THEN 'sports_leisure'::canonical_sector_key_v3
      WHEN '35' THEN 'home_living'::canonical_sector_key_v3
      ELSE 'unknown'::canonical_sector_key_v3
    END
  )
);
CREATE INDEX IF NOT EXISTS stock_sector_assignments_v3_stream
  ON stock_sector_assignments_v3 (
    stock_id,market,recorded_at DESC,assignment_authority_id
  );
CREATE UNIQUE INDEX IF NOT EXISTS stock_sector_assignments_v3_immutable_identity
  ON stock_sector_assignments_v3 (
    stock_id,market,official_industry_code,canonical_sector_key,provider,
    source_timestamp,valid_from,valid_to,taxonomy_version,status
  ) NULLS NOT DISTINCT;

CREATE TABLE IF NOT EXISTS opportunity_financial_facts_v3 (
  fact_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  fact_key financial_fact_key_v3 NOT NULL,
  period_start date,
  period_end date NOT NULL,
  duration_kind financial_duration_kind_v3 NOT NULL,
  value double precision NOT NULL CHECK (value > '-Infinity'::double precision AND value < 'Infinity'::double precision),
  unit financial_unit_v3 NOT NULL,
  provider financial_provider_v3 NOT NULL,
  authority_tier financial_authority_tier_v3 NOT NULL,
  estimate_kind financial_estimate_kind_v3 NOT NULL,
  estimate_horizon financial_estimate_horizon_v3 NOT NULL,
  filing_published_at timestamptz NOT NULL,
  source_timestamp timestamptz NOT NULL,
  collected_at timestamptz NOT NULL,
  filing_restatement_id text,
  source_ref text NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (
    filing_published_at <= source_timestamp
    AND source_timestamp <= collected_at
    AND collected_at <= recorded_at
  ),
  CHECK (
    (estimate_kind='reported' AND estimate_horizon='reported_period'
      AND fact_key<>'broker_target_price')
    OR
    (estimate_kind='analyst_estimate'
      AND estimate_horizon='next_twelve_months'
      AND fact_key IN (
        'quarterly_diluted_eps','quarterly_ebitda','quarterly_revenue',
        'book_value_per_share'
      ))
    OR
    (estimate_kind='broker_consensus' AND estimate_horizon='target_12m'
      AND fact_key='broker_target_price')
  )
);
DROP INDEX IF EXISTS opportunity_financial_facts_v3_point_in_time;
CREATE INDEX opportunity_financial_facts_v3_point_in_time
  ON opportunity_financial_facts_v3 (
    stock_id,fact_key,period_end DESC,filing_published_at DESC,
    source_timestamp DESC,collected_at DESC,recorded_at DESC
  );
CREATE INDEX IF NOT EXISTS opportunity_financial_facts_v3_full_roster
  ON opportunity_financial_facts_v3 (
    fact_key,period_end DESC,source_timestamp DESC,recorded_at,stock_id
  );
CREATE UNIQUE INDEX IF NOT EXISTS opportunity_financial_facts_v3_immutable_identity
  ON opportunity_financial_facts_v3 (
    stock_id,fact_key,period_start,period_end,duration_kind,value,unit,provider,
    authority_tier,estimate_kind,estimate_horizon,
    filing_published_at,source_timestamp,collected_at,
    filing_restatement_id,source_ref
  ) NULLS NOT DISTINCT;

CREATE TABLE IF NOT EXISTS publisher_verification_authorities_v3 (
  authority_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  publisher_identity_id uuid NOT NULL REFERENCES source_entities(id) ON DELETE RESTRICT,
  source_class source_class_v3 NOT NULL,
  domains text[] NOT NULL,
  feed_identity text,
  institution_identity text,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  approved_at timestamptz NOT NULL,
  approving_principal_id uuid NOT NULL,
  status authority_status_v3 NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (valid_to IS NULL OR valid_to > valid_from),
  CHECK (source_class <> 'public_research' OR institution_identity IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS publisher_verification_authorities_v3_stream
  ON publisher_verification_authorities_v3 (publisher_identity_id, recorded_at DESC, authority_id);

CREATE TABLE IF NOT EXISTS stock_aliases_v3 (
  alias_authority_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  normalized_alias text NOT NULL CHECK (char_length(normalized_alias) BETWEEN 2 AND 40),
  source alias_source_v3 NOT NULL,
  source_timestamp timestamptz NOT NULL,
  approved_by_principal_id uuid NOT NULL,
  approved_at timestamptz NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  status authority_status_v3 NOT NULL,
  normalization_version text NOT NULL CHECK (normalization_version = 'entity-link-v3.1'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (valid_to IS NULL OR valid_to > valid_from)
);
CREATE INDEX IF NOT EXISTS stock_aliases_v3_lookup
  ON stock_aliases_v3 (normalized_alias, stock_id, recorded_at DESC);
CREATE INDEX IF NOT EXISTS stock_aliases_v3_stream
  ON stock_aliases_v3 (
    stock_id,normalized_alias,source,recorded_at DESC,alias_authority_id
  );

CREATE TABLE IF NOT EXISTS stock_peer_relationship_reviewers_v3 (
  reviewer_authority_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  reviewer_principal_id uuid NOT NULL,
  approving_principal_id uuid NOT NULL,
  approved_at timestamptz NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  status authority_status_v3 NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (valid_to IS NULL OR valid_to > valid_from)
);
CREATE INDEX IF NOT EXISTS stock_peer_relationship_reviewers_v3_stream
  ON stock_peer_relationship_reviewers_v3 (
    reviewer_principal_id,recorded_at DESC,reviewer_authority_id
  );

CREATE TABLE IF NOT EXISTS stock_peer_relationships_v3 (
  relationship_authority_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  supplier_instrument_authority_id uuid NOT NULL REFERENCES stock_instruments_v3(instrument_authority_id) ON DELETE RESTRICT,
  supplier_stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  customer_instrument_authority_id uuid NOT NULL REFERENCES stock_instruments_v3(instrument_authority_id) ON DELETE RESTRICT,
  customer_stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  relationship_kind text NOT NULL CHECK (relationship_kind = 'supply_chain'),
  source_timestamp timestamptz NOT NULL,
  approved_at timestamptz NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  status authority_status_v3 NOT NULL,
  evidence_ref text NOT NULL CHECK (char_length(evidence_ref) BETWEEN 1 AND 120),
  reviewer_principal_id uuid NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (supplier_stock_id <> customer_stock_id),
  CHECK (valid_to IS NULL OR valid_to > valid_from)
);
CREATE INDEX IF NOT EXISTS stock_peer_relationships_v3_stream
  ON stock_peer_relationships_v3 (
    supplier_stock_id,customer_stock_id,relationship_kind,
    recorded_at DESC,relationship_authority_id
  );

CREATE TABLE IF NOT EXISTS valuation_verifications_v3 (
  verification_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  symbol text NOT NULL CHECK (symbol ~ '^[0-9]{4}$'),
  input_hash text NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
  decision valuation_verification_decision_v3 NOT NULL,
  reason_codes text[] NOT NULL,
  evidence_refs text[] NOT NULL CHECK (cardinality(evidence_refs) BETWEEN 2 AND 8),
  rationale text NOT NULL CHECK (char_length(rationale) BETWEEN 1 AND 500),
  valuation_computed_at timestamptz NOT NULL,
  review_timestamp timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  reviewer_principal_id uuid NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (valuation_computed_at <= review_timestamp),
  CHECK (expires_at = review_timestamp + interval '30 days')
);
CREATE INDEX IF NOT EXISTS valuation_verifications_v3_selection
  ON valuation_verifications_v3 (symbol,input_hash,review_timestamp DESC,recorded_at DESC,reviewer_principal_id,verification_id);

CREATE TABLE IF NOT EXISTS tw_trading_sessions_v3 (
  session_authority_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  session_id date NOT NULL,
  market tw_market_v3 NOT NULL,
  open_at timestamptz NOT NULL,
  close_at timestamptz NOT NULL,
  status trading_session_status_v3 NOT NULL,
  provider official_roster_provider_v3 NOT NULL,
  source_timestamp timestamptz NOT NULL,
  collected_at timestamptz NOT NULL,
  source_ref text NOT NULL CHECK (char_length(source_ref) BETWEEN 1 AND 120),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (open_at < close_at),
  CHECK (source_timestamp <= collected_at AND collected_at <= recorded_at),
  CHECK ((open_at AT TIME ZONE 'Asia/Taipei')::date = session_id),
  CHECK ((close_at AT TIME ZONE 'Asia/Taipei')::date = session_id),
  CHECK (
    (market='TWSE' AND provider='twse')
    OR (market='TPEX' AND provider='tpex')
  ),
  UNIQUE (
    market,session_id,open_at,close_at,status,provider,
    source_timestamp,collected_at,source_ref
  )
);
DROP INDEX IF EXISTS tw_trading_sessions_v3_cutoff;
CREATE INDEX IF NOT EXISTS tw_trading_sessions_v3_stream
  ON tw_trading_sessions_v3 (market,session_id,recorded_at DESC,session_authority_id);
CREATE INDEX IF NOT EXISTS tw_trading_sessions_v3_recorded
  ON tw_trading_sessions_v3 (recorded_at,market,session_id);
CREATE INDEX IF NOT EXISTS tw_trading_sessions_v3_completed
  ON tw_trading_sessions_v3 (status,close_at DESC,recorded_at);

CREATE TABLE IF NOT EXISTS opportunity_price_observations_v3 (
  observation_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  exchange stock_exchange_v3 NOT NULL,
  session_id date NOT NULL,
  session_authority_id uuid NOT NULL REFERENCES tw_trading_sessions_v3(session_authority_id) ON DELETE RESTRICT,
  raw_open double precision NOT NULL CHECK (raw_open > 0 AND raw_open < 'Infinity'::double precision),
  raw_high double precision NOT NULL CHECK (raw_high > 0 AND raw_high < 'Infinity'::double precision),
  raw_low double precision NOT NULL CHECK (raw_low > 0 AND raw_low < 'Infinity'::double precision),
  raw_close double precision NOT NULL CHECK (raw_close > 0 AND raw_close < 'Infinity'::double precision),
  volume double precision NOT NULL CHECK (volume >= 0 AND volume < 'Infinity'::double precision),
  turnover_twd double precision NOT NULL CHECK (turnover_twd >= 0 AND turnover_twd < 'Infinity'::double precision),
  provider price_provider_v3 NOT NULL,
  source_timestamp timestamptz NOT NULL,
  collected_at timestamptz NOT NULL,
  source_ref text NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (raw_low <= raw_open AND raw_low <= raw_close AND raw_high >= raw_open AND raw_high >= raw_close),
  CHECK (source_timestamp <= collected_at)
);
CREATE INDEX IF NOT EXISTS opportunity_price_observations_v3_stream
  ON opportunity_price_observations_v3
    (stock_id,exchange,session_id,session_authority_id,provider,
      source_timestamp DESC,collected_at DESC,recorded_at DESC,source_ref,observation_id);
CREATE INDEX IF NOT EXISTS opportunity_price_observations_v3_session
  ON opportunity_price_observations_v3
    (session_id,session_authority_id,stock_id,provider,recorded_at DESC,observation_id);

CREATE TABLE IF NOT EXISTS opportunity_exchange_reported_pe_v3 (
  reported_pe_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  exchange stock_exchange_v3 NOT NULL,
  session_date date NOT NULL,
  close double precision NOT NULL CHECK(close>0 AND close<'Infinity'::double precision),
  reported_pe double precision NOT NULL CHECK(reported_pe>'-Infinity'::double precision AND reported_pe<'Infinity'::double precision),
  published_at timestamptz NOT NULL,source_timestamp timestamptz NOT NULL,collected_at timestamptz NOT NULL,
  source_ref text NOT NULL CHECK(char_length(source_ref) BETWEEN 1 AND 120),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK(published_at<=source_timestamp AND source_timestamp<=collected_at AND collected_at<=recorded_at),
  UNIQUE(stock_id,exchange,session_date,close,reported_pe,published_at,source_timestamp,collected_at,source_ref)
);
CREATE INDEX IF NOT EXISTS opportunity_exchange_reported_pe_v3_stock_session
  ON opportunity_exchange_reported_pe_v3(stock_id,exchange,session_date DESC,published_at DESC,source_timestamp DESC,collected_at DESC,recorded_at DESC,source_ref);
CREATE INDEX IF NOT EXISTS opportunity_exchange_reported_pe_v3_session_roster
  ON opportunity_exchange_reported_pe_v3(session_date,stock_id,published_at DESC,source_timestamp DESC,collected_at DESC,recorded_at DESC,source_ref);

CREATE TABLE IF NOT EXISTS opportunity_stock_flow_observations_v3 (
  observation_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  exchange stock_exchange_v3 NOT NULL,
  session_id date NOT NULL,
  session_authority_id uuid NOT NULL
    REFERENCES tw_trading_sessions_v3(session_authority_id) ON DELETE RESTRICT,
  fact_key stock_flow_fact_key_v3 NOT NULL,
  value double precision NOT NULL
    CHECK (value > '-Infinity'::double precision AND value < 'Infinity'::double precision),
  unit stock_flow_unit_v3 NOT NULL,
  provider stock_flow_provider_v3 NOT NULL,
  source_timestamp timestamptz NOT NULL,
  collected_at timestamptz NOT NULL,
  source_ref text NOT NULL CHECK (char_length(source_ref) BETWEEN 1 AND 120),
  provider_revision text NOT NULL CHECK (char_length(provider_revision) BETWEEN 1 AND 120),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (source_timestamp <= collected_at),
  CHECK (
    (fact_key='sbl_short_balance_shares' AND unit='shares')
    OR
    (fact_key IN (
      'foreign_net_twd','trust_net_twd','margin_financing_balance_twd'
    ) AND unit='TWD')
  ),
  CHECK (
    provider='finmind'
    OR provider::text=lower(exchange::text)
  )
);
CREATE INDEX IF NOT EXISTS opportunity_stock_flow_observations_v3_stream
  ON opportunity_stock_flow_observations_v3
    (stock_id,exchange,fact_key,session_id DESC,provider,
      source_timestamp DESC,collected_at DESC,recorded_at DESC,source_ref,observation_id);
CREATE INDEX IF NOT EXISTS opportunity_stock_flow_observations_v3_session
  ON opportunity_stock_flow_observations_v3
    (session_id,session_authority_id,stock_id,fact_key,provider,
      recorded_at DESC,observation_id);

CREATE TABLE IF NOT EXISTS opportunity_corporate_action_snapshots_v3 (
  snapshot_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  exchange stock_exchange_v3 NOT NULL,
  session_id date NOT NULL,
  session_authority_id uuid NOT NULL REFERENCES tw_trading_sessions_v3(session_authority_id) ON DELETE RESTRICT,
  corporate_action_version text NOT NULL CHECK (corporate_action_version = 'tw-corporate-action-v3.1'),
  provider official_roster_provider_v3 NOT NULL,
  collected_at timestamptz NOT NULL,
  declared_event_count integer NOT NULL CHECK (declared_event_count BETWEEN 0 AND 20000),
  dataset_hash text NOT NULL CHECK (dataset_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (exchange, session_id, session_authority_id, corporate_action_version, collected_at, dataset_hash)
);
CREATE INDEX IF NOT EXISTS opportunity_corporate_action_snapshots_v3_stream
  ON opportunity_corporate_action_snapshots_v3
    (exchange, session_id, session_authority_id, corporate_action_version, collected_at DESC, recorded_at DESC, snapshot_id);
CREATE INDEX IF NOT EXISTS opportunity_corporate_action_snapshots_v3_cutoff
  ON opportunity_corporate_action_snapshots_v3 (exchange, session_id DESC, recorded_at, snapshot_id);

CREATE TABLE IF NOT EXISTS opportunity_corporate_action_feed_evidence_v3 (
  snapshot_id uuid NOT NULL REFERENCES opportunity_corporate_action_snapshots_v3(snapshot_id) ON DELETE RESTRICT,
  feed_ordinal integer NOT NULL CHECK (feed_ordinal BETWEEN 0 AND 2),
  feed_identity text NOT NULL,
  response_byte_count integer NOT NULL CHECK (response_byte_count BETWEEN 0 AND 8388608),
  response_sha256 text NOT NULL CHECK (response_sha256 ~ '^[0-9a-f]{64}$'),
  parsed_row_count integer NOT NULL CHECK (parsed_row_count BETWEEN 0 AND 20000),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (snapshot_id, feed_ordinal),
  UNIQUE (snapshot_id, feed_identity)
);

CREATE TABLE IF NOT EXISTS opportunity_corporate_action_events_v3 (
  snapshot_id uuid NOT NULL REFERENCES opportunity_corporate_action_snapshots_v3(snapshot_id) ON DELETE RESTRICT,
  event_ordinal integer NOT NULL CHECK (event_ordinal >= 0),
  symbol text NOT NULL CHECK (symbol ~ '^[0-9]{4}$'),
  event_kind corporate_action_kind_v3 NOT NULL,
  pre_action_reference_price double precision NOT NULL CHECK (pre_action_reference_price > 0 AND pre_action_reference_price < 'Infinity'::double precision),
  post_action_reference_price double precision NOT NULL CHECK (post_action_reference_price > 0 AND post_action_reference_price < 'Infinity'::double precision),
  feed_identity text NOT NULL,
  source_row_ref text NOT NULL CHECK (char_length(source_row_ref) BETWEEN 1 AND 120),
  daily_adjustment_factor double precision GENERATED ALWAYS AS
    (post_action_reference_price / pre_action_reference_price) STORED,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (snapshot_id, event_ordinal),
  UNIQUE (snapshot_id, symbol)
);
CREATE INDEX IF NOT EXISTS opportunity_corporate_action_events_v3_symbol
  ON opportunity_corporate_action_events_v3 (snapshot_id, symbol, event_ordinal);

CREATE TABLE IF NOT EXISTS opportunity_market_observations_v3 (
  observation_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  fact_key market_fact_key_v3 NOT NULL,
  scope_key market_scope_key_v3 NOT NULL,
  session_id date,
  session_authority_id uuid REFERENCES tw_trading_sessions_v3(session_authority_id) ON DELETE RESTRICT,
  value double precision NOT NULL CHECK (value > '-Infinity'::double precision AND value < 'Infinity'::double precision),
  unit market_unit_v3 NOT NULL,
  provider market_provider_v3 NOT NULL,
  provider_identity text,
  authority_date date NOT NULL,
  provider_session_date date,
  breadth_numerator_count integer,
  breadth_observed_count integer,
  breadth_eligible_count integer,
  breadth_roster_manifest_id uuid,
  breadth_roster_manifest_hash text,
  observed_at timestamptz NOT NULL,
  collected_at timestamptz NOT NULL,
  source_ref text NOT NULL,
  provider_revision text NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (observed_at <= collected_at AND collected_at <= recorded_at),
  CHECK ((session_id IS NULL) = (session_authority_id IS NULL)),
  CHECK (
    (scope_key IN ('TAIEX','OTC','TWSE_ACTIVE_COMMON','TPEX_ACTIVE_COMMON')
      AND session_id IS NOT NULL AND authority_date=session_id)
    OR
    (scope_key IN ('TAIFEX','SOX','NASDAQ','USD_TWD')
      AND session_id IS NULL)
  ),
  CHECK (fact_key NOT IN ('taiex_close','otc_close') OR value>0),
  CHECK (
    (provider='global_allowlisted' AND provider_identity IS NOT NULL
      AND provider_session_date=authority_date)
    OR
    (provider<>'global_allowlisted' AND provider_identity IS NULL
      AND provider_session_date IS NULL)
  ),
  CHECK (
    (fact_key IN ('above_ma20','above_ma60')
      AND breadth_numerator_count IS NOT NULL
      AND breadth_observed_count IS NOT NULL
      AND breadth_eligible_count IS NOT NULL
      AND breadth_roster_manifest_id IS NOT NULL
      AND breadth_roster_manifest_hash ~ '^[0-9a-f]{64}$'
      AND 0<=breadth_numerator_count
      AND breadth_numerator_count<=breadth_observed_count
      AND breadth_observed_count<=breadth_eligible_count
      AND breadth_eligible_count<=20000)
    OR
    (fact_key NOT IN ('above_ma20','above_ma60')
      AND breadth_numerator_count IS NULL
      AND breadth_observed_count IS NULL
      AND breadth_eligible_count IS NULL
      AND breadth_roster_manifest_id IS NULL
      AND breadth_roster_manifest_hash IS NULL)
  )
);
CREATE INDEX IF NOT EXISTS opportunity_market_observations_v3_selection
  ON opportunity_market_observations_v3
    (fact_key,scope_key,observed_at DESC,recorded_at,observation_id);
CREATE INDEX IF NOT EXISTS opportunity_market_observations_v3_stream
  ON opportunity_market_observations_v3
    (fact_key,scope_key,authority_date,provider,provider_identity,
      recorded_at DESC,observation_id);
CREATE INDEX IF NOT EXISTS opportunity_market_observations_v3_history
  ON opportunity_market_observations_v3
    (fact_key,scope_key,provider,provider_identity,authority_date DESC,
      recorded_at DESC,observation_id);
CREATE INDEX IF NOT EXISTS opportunity_market_observations_v3_session
  ON opportunity_market_observations_v3
    (session_id,session_authority_id,fact_key,provider,recorded_at DESC,observation_id);
CREATE INDEX IF NOT EXISTS opportunity_market_observations_v3_breadth
  ON opportunity_market_observations_v3
    (breadth_roster_manifest_id,fact_key,scope_key,session_id);
CREATE INDEX IF NOT EXISTS opportunity_market_observations_v3_global_history
  ON opportunity_market_observations_v3
    (provider,provider_identity,provider_session_date DESC,recorded_at DESC,observation_id)
  WHERE provider='global_allowlisted';

CREATE TABLE IF NOT EXISTS opportunity_manifests_v3 (
  manifest_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  manifest_kind opportunity_manifest_kind_v3 NOT NULL,
  contract_version text NOT NULL,
  source_cutoff timestamptz,
  header_canonical bytea NOT NULL CHECK (octet_length(header_canonical) <= 3145728),
  header_json jsonb NOT NULL,
  status opportunity_manifest_status_v3 NOT NULL DEFAULT 'building',
  row_count bigint CHECK (row_count IS NULL OR row_count >= 0),
  root_canonical bytea CHECK (root_canonical IS NULL OR octet_length(root_canonical) <= 3145728),
  root_json jsonb,
  manifest_hash text CHECK (manifest_hash IS NULL OR manifest_hash ~ '^[0-9a-f]{64}$'),
  failure_code opportunity_manifest_failure_code_v3,
  created_at timestamptz NOT NULL DEFAULT statement_timestamp(),
  terminal_at timestamptz,
  recorded_at timestamptz NOT NULL DEFAULT statement_timestamp(),
  CHECK (created_at=recorded_at),
  CHECK (
    (status='building' AND row_count IS NULL AND root_canonical IS NULL
      AND root_json IS NULL AND manifest_hash IS NULL
      AND failure_code IS NULL AND terminal_at IS NULL)
    OR
    (status='complete' AND row_count IS NOT NULL AND row_count>=0
      AND root_canonical IS NOT NULL AND root_json IS NOT NULL
      AND manifest_hash IS NOT NULL AND failure_code IS NULL
      AND terminal_at IS NOT NULL)
    OR
    (status='failed' AND row_count IS NULL AND root_canonical IS NULL
      AND root_json IS NULL AND manifest_hash IS NULL
      AND failure_code IS NOT NULL AND terminal_at IS NOT NULL)
  )
);
CREATE UNIQUE INDEX IF NOT EXISTS opportunity_manifests_v3_complete_manifest_hash
  ON opportunity_manifests_v3 (manifest_kind,manifest_hash)
  WHERE status='complete';
DO $market_breadth_manifest_fk$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname='opportunity_market_observations_v3_breadth_manifest_fk'
  ) THEN
    ALTER TABLE opportunity_market_observations_v3
      ADD CONSTRAINT opportunity_market_observations_v3_breadth_manifest_fk
      FOREIGN KEY (breadth_roster_manifest_id)
      REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT;
  END IF;
END
$market_breadth_manifest_fk$;
CREATE TABLE IF NOT EXISTS opportunity_manifest_pages_v3 (
  page_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  manifest_id uuid NOT NULL REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  section_key opportunity_manifest_section_key_v3 NOT NULL,
  page_ordinal integer NOT NULL CHECK (page_ordinal >= 0),
  first_row_ordinal bigint NOT NULL CHECK (first_row_ordinal >= 0),
  row_count integer NOT NULL CHECK (row_count BETWEEN 1 AND 2000),
  first_identity text NOT NULL,
  last_identity text NOT NULL,
  page_canonical bytea NOT NULL CHECK (octet_length(page_canonical) <= 786432),
  page_json jsonb NOT NULL,
  page_hash text NOT NULL CHECK (page_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (manifest_id, section_key, page_ordinal),
  UNIQUE (manifest_id, section_key, first_row_ordinal),
  UNIQUE (manifest_id, page_id, section_key)
);
CREATE TABLE IF NOT EXISTS opportunity_manifest_rows_v3 (
  manifest_id uuid NOT NULL REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  page_id uuid NOT NULL,
  section_key opportunity_manifest_section_key_v3 NOT NULL,
  row_ordinal bigint NOT NULL CHECK (row_ordinal >= 0),
  identity_key text NOT NULL,
  terminal_code text,
  lookup_symbol text,
  lookup_session date,
  payload_json jsonb NOT NULL,
  payload_canonical bytea NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (manifest_id, section_key, row_ordinal),
  UNIQUE (manifest_id, section_key, identity_key),
  UNIQUE (page_id, row_ordinal),
  FOREIGN KEY (manifest_id,page_id,section_key)
    REFERENCES opportunity_manifest_pages_v3(manifest_id,page_id,section_key)
    ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX IF NOT EXISTS opportunity_manifest_pages_v3_lookup
  ON opportunity_manifest_pages_v3 (manifest_id,section_key,page_ordinal,page_hash);
CREATE INDEX IF NOT EXISTS opportunity_manifest_rows_v3_symbol_session
  ON opportunity_manifest_rows_v3 (
    manifest_id,section_key,lookup_symbol,lookup_session,row_ordinal
  );
CREATE INDEX IF NOT EXISTS opportunity_manifest_rows_v3_session
  ON opportunity_manifest_rows_v3 (
    manifest_id,section_key,lookup_session,row_ordinal
  );

CREATE OR REPLACE FUNCTION validate_opportunity_manifest_lifecycle_v3()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_manifest_id uuid;
  v_status public.opportunity_manifest_status_v3;
BEGIN
  IF TG_TABLE_NAME='opportunity_manifests_v3' THEN
    IF TG_OP='DELETE' THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    IF OLD.status<>'building' THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    IF NEW.manifest_id<>OLD.manifest_id
      OR NEW.manifest_kind<>OLD.manifest_kind
      OR NEW.contract_version<>OLD.contract_version
      OR NEW.source_cutoff IS DISTINCT FROM OLD.source_cutoff
      OR NEW.header_canonical<>OLD.header_canonical
      OR NEW.header_json<>OLD.header_json
      OR NEW.created_at<>OLD.created_at
      OR NEW.recorded_at<>OLD.recorded_at
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    IF NEW.status='complete' AND (
      NEW.root_canonical IS NULL
      OR encode(extensions.digest(NEW.root_canonical,'sha256'),'hex')<>NEW.manifest_hash
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME='opportunity_manifest_pages_v3' THEN
    v_manifest_id:=CASE WHEN TG_OP='DELETE' THEN OLD.manifest_id ELSE NEW.manifest_id END;
  ELSE
    v_manifest_id:=CASE WHEN TG_OP='DELETE' THEN OLD.manifest_id ELSE NEW.manifest_id END;
  END IF;
  SELECT status INTO STRICT v_status
  FROM public.opportunity_manifests_v3 WHERE manifest_id=v_manifest_id;
  RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
END
$fn$;

DROP TRIGGER IF EXISTS opportunity_manifests_v3_lifecycle
  ON opportunity_manifests_v3;
CREATE TRIGGER opportunity_manifests_v3_lifecycle
BEFORE UPDATE OR DELETE ON opportunity_manifests_v3
FOR EACH ROW EXECUTE FUNCTION validate_opportunity_manifest_lifecycle_v3();
DROP TRIGGER IF EXISTS opportunity_manifest_pages_v3_immutable
  ON opportunity_manifest_pages_v3;
CREATE TRIGGER opportunity_manifest_pages_v3_immutable
BEFORE UPDATE OR DELETE ON opportunity_manifest_pages_v3
FOR EACH ROW EXECUTE FUNCTION validate_opportunity_manifest_lifecycle_v3();
DROP TRIGGER IF EXISTS opportunity_manifest_rows_v3_immutable
  ON opportunity_manifest_rows_v3;
CREATE TRIGGER opportunity_manifest_rows_v3_immutable
BEFORE UPDATE OR DELETE ON opportunity_manifest_rows_v3
FOR EACH ROW EXECUTE FUNCTION validate_opportunity_manifest_lifecycle_v3();

CREATE OR REPLACE FUNCTION validate_opportunity_manifest_page_rows_v3()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_page public.opportunity_manifest_pages_v3%ROWTYPE;
  v_manifest public.opportunity_manifests_v3%ROWTYPE;
  v_count bigint; v_min bigint; v_max bigint; v_first text; v_last text;
  v_expected_symbol text; v_expected_session date; v_expected_terminal text;
  v_status text; v_valid_to timestamptz; v_row public.opportunity_manifest_rows_v3%ROWTYPE;
BEGIN
  IF TG_TABLE_NAME='opportunity_manifest_rows_v3' THEN
    v_row:=NEW;
    SELECT * INTO STRICT v_page
    FROM public.opportunity_manifest_pages_v3 WHERE page_id=NEW.page_id;
    IF NEW.row_ordinal<>v_page.first_row_ordinal+v_page.row_count-1 THEN
      RETURN NEW;
    END IF;
  ELSE
    v_page:=NEW;
  END IF;
  SELECT * INTO STRICT v_manifest
  FROM public.opportunity_manifests_v3 WHERE manifest_id=v_page.manifest_id;
  IF v_page.page_canonical<>convert_to(regexp_replace(v_page.page_json::text,', ', ',', 'g'),'utf8')
    OR encode(extensions.digest(v_page.page_canonical,'sha256'),'hex')<>v_page.page_hash
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch'; END IF;
  SELECT count(*),min(row_ordinal),max(row_ordinal),
    (array_agg(identity_key ORDER BY row_ordinal))[1],
    (array_agg(identity_key ORDER BY row_ordinal DESC))[1]
  INTO v_count,v_min,v_max,v_first,v_last
  FROM public.opportunity_manifest_rows_v3 WHERE page_id=v_page.page_id;
  IF v_count<>v_page.row_count OR v_min<>v_page.first_row_ordinal
    OR v_max<>v_page.first_row_ordinal+v_page.row_count-1
    OR v_max-v_min+1<>v_count OR v_first<>v_page.first_identity
    OR v_last<>v_page.last_identity
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
  FOR v_row IN
    SELECT * FROM public.opportunity_manifest_rows_v3
    WHERE page_id=v_page.page_id ORDER BY row_ordinal
  LOOP
    IF v_row.payload_canonical<>convert_to(
        regexp_replace(v_row.payload_json::text,', ', ',', 'g'),'utf8')
      OR encode(extensions.digest(v_row.payload_canonical,'sha256'),'hex')<>v_row.payload_hash
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch'; END IF;
    v_expected_symbol:=NULL; v_expected_session:=NULL; v_expected_terminal:=NULL;
    IF v_manifest.manifest_kind='sector_benchmark' AND v_row.section_key='entry_rows' THEN
      v_expected_symbol:=v_row.payload_json->>0;
      SELECT (pair->>1)::date INTO v_expected_session
      FROM jsonb_array_elements(v_manifest.header_json) pair
      WHERE pair->>0='entrySession';
    ELSIF v_manifest.manifest_kind='sector_benchmark' AND v_row.section_key='evaluation_rows' THEN
      v_expected_session:=(v_row.payload_json->>0)::date;
      v_expected_symbol:=v_row.payload_json->>3;
    ELSIF v_manifest.manifest_kind='sector_benchmark' AND v_row.section_key='session_conservation' THEN
      v_expected_session:=(v_row.payload_json->>0)::date;
    END IF;
    v_status:=CASE v_manifest.manifest_kind
      WHEN 'source_identity_allowlist' THEN v_row.payload_json->>7
      WHEN 'publisher_verification_allowlist' THEN v_row.payload_json->>10
      WHEN 'instrument_roster' THEN v_row.payload_json->>5
      WHEN 'alias_authority' THEN v_row.payload_json->>9
      WHEN 'taxonomy_assignment' THEN v_row.payload_json->>10
      WHEN 'peer_reviewer_allowlist' THEN v_row.payload_json->>5
      ELSE NULL END;
    v_valid_to:=CASE v_manifest.manifest_kind
      WHEN 'source_identity_allowlist' THEN (v_row.payload_json->>6)::timestamptz
      WHEN 'publisher_verification_allowlist' THEN (v_row.payload_json->>7)::timestamptz
      WHEN 'instrument_roster' THEN (v_row.payload_json->>10)::timestamptz
      WHEN 'alias_authority' THEN (v_row.payload_json->>8)::timestamptz
      WHEN 'taxonomy_assignment' THEN (v_row.payload_json->>8)::timestamptz
      WHEN 'peer_reviewer_allowlist' THEN (v_row.payload_json->>4)::timestamptz
      ELSE NULL END;
    IF v_status IS NOT NULL THEN
      v_expected_terminal:=CASE
        WHEN v_status='active'
          AND (v_valid_to IS NULL OR v_manifest.source_cutoff<v_valid_to)
        THEN 'effective_active' ELSE 'revoked_or_expired' END;
    END IF;
    IF v_row.lookup_symbol IS DISTINCT FROM v_expected_symbol
      OR v_row.lookup_session IS DISTINCT FROM v_expected_session
      OR v_row.terminal_code IS DISTINCT FROM v_expected_terminal
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure',
      DETAIL=format(
        'kind=%s section=%s ordinal=%s terminal=%s expected=%s symbol=%s expectedSymbol=%s session=%s expectedSession=%s',
        v_manifest.manifest_kind,v_row.section_key,v_row.row_ordinal,v_row.terminal_code,
        v_expected_terminal,v_row.lookup_symbol,v_expected_symbol,
        v_row.lookup_session,v_expected_session
      ); END IF;
  END LOOP;
  IF octet_length(v_page.page_canonical)
      +coalesce((SELECT sum(octet_length(payload_canonical))
        FROM public.opportunity_manifest_rows_v3 WHERE page_id=v_page.page_id),0)>3145728
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
  RETURN NEW;
END
$fn$;

DROP TRIGGER IF EXISTS opportunity_manifest_page_rows_v3_page_check
  ON opportunity_manifest_pages_v3;
CREATE CONSTRAINT TRIGGER opportunity_manifest_page_rows_v3_page_check
AFTER INSERT ON opportunity_manifest_pages_v3
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION validate_opportunity_manifest_page_rows_v3();
DROP TRIGGER IF EXISTS opportunity_manifest_page_rows_v3_row_check
  ON opportunity_manifest_rows_v3;
CREATE CONSTRAINT TRIGGER opportunity_manifest_page_rows_v3_row_check
AFTER INSERT ON opportunity_manifest_rows_v3
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION validate_opportunity_manifest_page_rows_v3();

CREATE TABLE IF NOT EXISTS opportunity_assistive_artifact_registrations_v3 (
  registration_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  artifact_ref text NOT NULL UNIQUE CHECK (char_length(artifact_ref) BETWEEN 1 AND 120),
  artifact_hash text NOT NULL CHECK (artifact_hash ~ '^[0-9a-f]{64}$'),
  artifact_kind assistive_artifact_kind_v3 NOT NULL,
  license_id text NOT NULL CHECK (license_id IN ('apache-2.0','mit','bsd-3-clause','cc-by-4.0','proprietary-internal-eval')),
  license_evidence_ref text NOT NULL CHECK (char_length(license_evidence_ref) BETWEEN 1 AND 120),
  training_cutoff timestamptz NOT NULL,
  evaluation_manifest_id uuid NOT NULL REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  comparison_baseline_key text NOT NULL CHECK (comparison_baseline_key ~ '^[0-9a-f]{64}$'),
  oos_precision_at_20 double precision NOT NULL CHECK (oos_precision_at_20 BETWEEN 0 AND 1),
  oos_ndcg_at_20 double precision NOT NULL CHECK (oos_ndcg_at_20 BETWEEN 0 AND 1),
  oos_worst_decile_mae20_pct double precision NOT NULL CHECK (oos_worst_decile_mae20_pct BETWEEN -100 AND 0),
  status assistive_artifact_status_v3 NOT NULL,
  supersedes_registration_id uuid REFERENCES opportunity_assistive_artifact_registrations_v3(registration_id) ON DELETE RESTRICT,
  registered_by_principal_id uuid NOT NULL,
  registered_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (training_cutoff <= registered_at),
  CHECK (registered_at = recorded_at)
);

CREATE TABLE IF NOT EXISTS opportunity_runs (
  run_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  preparation_key text NOT NULL CHECK (preparation_key ~ '^[0-9a-f]{64}$'),
  logical_key text CHECK (logical_key IS NULL OR logical_key ~ '^[0-9a-f]{64}$'),
  attempt integer NOT NULL CHECK (attempt BETWEEN 1 AND 5),
  mode opportunity_mode_v3 NOT NULL,
  run_purpose opportunity_run_purpose_v3 NOT NULL,
  trading_date date,
  source_cutoff timestamptz NOT NULL,
  comparison_contract_key text NOT NULL CHECK (comparison_contract_key ~ '^[0-9a-f]{64}$'),
  evaluation_dataset_lock_hash text CHECK (evaluation_dataset_lock_hash IS NULL OR evaluation_dataset_lock_hash ~ '^[0-9a-f]{64}$'),
  upstream_run_id uuid REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  selected_mover_audit_id uuid,
  supersedes_run_id uuid REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  canonical_run_id uuid REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  status opportunity_run_status_v3 NOT NULL,
  failure_code opportunity_failure_code_v3,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  sealed_at timestamptz,
  terminal_at timestamptz,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK (sealed_at IS NULL OR created_at <= sealed_at),
  CHECK (terminal_at IS NULL OR created_at <= terminal_at)
);
CREATE UNIQUE INDEX IF NOT EXISTS opportunity_runs_one_active_preparation_v3
  ON opportunity_runs (preparation_key) WHERE status IN ('preparing','running');
CREATE UNIQUE INDEX IF NOT EXISTS opportunity_runs_one_success_logical_v3
  ON opportunity_runs (logical_key) WHERE status='success';
CREATE INDEX IF NOT EXISTS opportunity_runs_projection_v3
  ON opportunity_runs (run_purpose, comparison_contract_key, source_cutoff DESC, terminal_at DESC, run_id);

CREATE TABLE IF NOT EXISTS opportunity_run_inputs (
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  input_run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  input_role opportunity_run_input_role_v3 NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (run_id, input_run_id, input_role),
  CHECK (run_id <> input_run_id)
);

CREATE TABLE IF NOT EXISTS opportunity_run_manifest_inputs (
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  manifest_id uuid NOT NULL REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  input_role opportunity_manifest_kind_v3 NOT NULL,
  ordinal integer NOT NULL CHECK (ordinal >= 0),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (run_id, input_role, ordinal),
  UNIQUE (run_id, manifest_id, input_role)
);

CREATE TABLE IF NOT EXISTS source_publication_verifications_v3 (
  verification_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  source_run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  source_cutoff timestamptz NOT NULL,
  revision_id uuid NOT NULL REFERENCES source_document_revisions_v3(revision_id) ON DELETE RESTRICT,
  publisher_manifest_id uuid NOT NULL REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  publisher_identity_id uuid NOT NULL REFERENCES source_entities(id) ON DELETE RESTRICT,
  institution_identity text,
  canonical_document_id text NOT NULL,
  canonical_content_hash text NOT NULL CHECK (canonical_content_hash ~ '^[0-9a-f]{64}$'),
  published_at timestamptz,
  collected_at timestamptz NOT NULL,
  evidence_ref text NOT NULL CHECK (char_length(evidence_ref) BETWEEN 1 AND 120),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (source_run_id, revision_id, publisher_manifest_id),
  CHECK (collected_at <= source_cutoff),
  CHECK (published_at IS NULL OR published_at <= collected_at)
);

CREATE TABLE IF NOT EXISTS opportunity_mover_audits_v3 (
  audit_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  session_id date NOT NULL,
  audited_session_authority_hash text NOT NULL CHECK (audited_session_authority_hash ~ '^[0-9a-f]{64}$'),
  previous_session_authority_hash text NOT NULL CHECK (previous_session_authority_hash ~ '^[0-9a-f]{64}$'),
  recent_session_plan_hash text NOT NULL CHECK (recent_session_plan_hash ~ '^[0-9a-f]{64}$'),
  source_cutoff timestamptz NOT NULL,
  audit_window_closes_at timestamptz NOT NULL,
  source_collection_cutoff timestamptz NOT NULL,
  status opportunity_mover_audit_status_v3 NOT NULL,
  mover_count integer NOT NULL CHECK (mover_count BETWEEN 0 AND 20),
  eligible_universe_count integer NOT NULL CHECK (eligible_universe_count >= mover_count),
  recall_pct double precision CHECK (recall_pct IS NULL OR recall_pct BETWEEN 0 AND 100),
  price_manifest_id uuid NOT NULL REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  source_dataset_manifest_id uuid NOT NULL REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  upstream_source_run_id uuid NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT opportunity_mover_audits_v3_upstream_source_run_fk
    FOREIGN KEY (upstream_source_run_id) REFERENCES opportunity_runs(run_id)
      ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
  UNIQUE (session_id, audited_session_authority_hash, source_cutoff, price_manifest_id, source_dataset_manifest_id),
  CHECK (source_collection_cutoff = LEAST(source_cutoff, audit_window_closes_at)),
  CHECK (
    (status = 'pending' AND source_cutoff < audit_window_closes_at AND recall_pct IS NULL)
    OR
    (status = 'matured' AND source_cutoff >= audit_window_closes_at
      AND ((mover_count = 0 AND recall_pct IS NULL) OR (mover_count > 0 AND recall_pct IS NOT NULL)))
  )
);

CREATE TABLE IF NOT EXISTS opportunity_mover_audit_symbols_v3 (
  audit_id uuid NOT NULL REFERENCES opportunity_mover_audits_v3(audit_id) ON DELETE RESTRICT,
  rank integer NOT NULL CHECK (rank BETWEEN 1 AND 20),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  symbol text NOT NULL CHECK (symbol ~ '^[0-9]{4}$'),
  one_session_return_pct double precision NOT NULL CHECK (one_session_return_pct > '-Infinity'::double precision AND one_session_return_pct < 'Infinity'::double precision),
  turnover_twd double precision NOT NULL CHECK (turnover_twd >= 20000000 AND turnover_twd < 'Infinity'::double precision),
  end_price_ref text NOT NULL,
  prior_price_ref text NOT NULL,
  corporate_action_version text NOT NULL,
  later_mentioned boolean NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (audit_id, rank),
  UNIQUE (audit_id, symbol)
);

DO $mover_run_fk$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'opportunity_runs_selected_mover_audit_fk'
  ) THEN
    ALTER TABLE opportunity_runs
      ADD CONSTRAINT opportunity_runs_selected_mover_audit_fk
      FOREIGN KEY (selected_mover_audit_id) REFERENCES opportunity_mover_audits_v3(audit_id)
      ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;
  END IF;
END
$mover_run_fk$;

CREATE TABLE IF NOT EXISTS opportunity_run_jobs_v3 (
  job_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  stage opportunity_job_stage_v3 NOT NULL,
  shard_key text NOT NULL,
  input_hash text NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
  status opportunity_job_status_v3 NOT NULL DEFAULT 'queued',
  attempt integer NOT NULL DEFAULT 0 CHECK (attempt BETWEEN 0 AND 5),
  owner_token_hash text CHECK (owner_token_hash IS NULL OR owner_token_hash ~ '^[0-9a-f]{64}$'),
  attempt_started_at timestamptz,
  lease_expires_at timestamptz,
  heartbeat_at timestamptz,
  output_kind opportunity_job_output_kind_v3,
  output_hash text CHECK (output_hash IS NULL OR output_hash ~ '^[0-9a-f]{64}$'),
  output_manifest_id uuid REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  output_counts opportunity_job_counts_v3,
  failure_code opportunity_failure_code_v3,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  terminal_at timestamptz,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (run_id, job_id),
  UNIQUE (run_id, stage, shard_key, input_hash)
);
CREATE INDEX IF NOT EXISTS opportunity_run_jobs_v3_queue
  ON opportunity_run_jobs_v3 (status, stage, lease_expires_at, run_id);

CREATE TABLE IF NOT EXISTS opportunity_job_payloads_v3 (
  job_id uuid PRIMARY KEY,
  run_id uuid NOT NULL,
  payload_kind opportunity_job_payload_kind_v3 NOT NULL,
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  FOREIGN KEY (run_id, job_id) REFERENCES opportunity_run_jobs_v3(run_id, job_id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS opportunity_job_results_v3 (
  job_id uuid PRIMARY KEY,
  run_id uuid NOT NULL,
  output_kind opportunity_job_output_kind_v3 NOT NULL,
  output_canonical bytea NOT NULL CHECK (octet_length(output_canonical) <= 3145728),
  output_json jsonb NOT NULL,
  output_hash text NOT NULL CHECK (output_hash ~ '^[0-9a-f]{64}$'),
  output_counts opportunity_job_counts_v3 NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  FOREIGN KEY (run_id, job_id) REFERENCES opportunity_run_jobs_v3(run_id, job_id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS opportunity_job_staging_v3 (
  job_id uuid NOT NULL REFERENCES opportunity_run_jobs_v3(job_id) ON DELETE RESTRICT,
  attempt integer NOT NULL CHECK (attempt BETWEEN 1 AND 5),
  output_kind opportunity_job_output_kind_v3 NOT NULL,
  output_canonical bytea NOT NULL CHECK (octet_length(output_canonical) <= 3145728),
  output_json jsonb NOT NULL,
  output_hash text NOT NULL CHECK (output_hash ~ '^[0-9a-f]{64}$'),
  output_counts opportunity_job_counts_v3 NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (job_id, attempt)
);

CREATE TABLE IF NOT EXISTS opportunity_run_warning_facts_v3 (
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  warning opportunity_engine_warning_v3 NOT NULL CHECK (warning <> 'shadow_only'),
  producing_job_id uuid NOT NULL,
  evidence_ref text NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (run_id, warning, producing_job_id),
  FOREIGN KEY (run_id, producing_job_id) REFERENCES opportunity_run_jobs_v3(run_id,job_id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS opportunity_source_connector_accounting (
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  source_key source_key_v3 NOT NULL,
  eligible_document_count integer NOT NULL CHECK (eligible_document_count >= 0),
  selected_document_count integer NOT NULL CHECK (selected_document_count >= 0),
  deferred_due_scan_cap_count integer NOT NULL CHECK (deferred_due_scan_cap_count >= 0),
  duplicate_document_count integer NOT NULL CHECK (duplicate_document_count >= 0),
  expired_document_count integer NOT NULL CHECK (expired_document_count >= 0),
  parse_failure_count integer NOT NULL CHECK (parse_failure_count >= 0),
  processed_no_claim_count integer NOT NULL CHECK (processed_no_claim_count >= 0),
  processed_with_claims_count integer NOT NULL CHECK (processed_with_claims_count >= 0),
  unique_claim_count integer NOT NULL CHECK (unique_claim_count >= 0),
  duplicate_claim_count integer NOT NULL CHECK (duplicate_claim_count >= 0),
  linked_new_count integer NOT NULL CHECK (linked_new_count >= 0),
  linked_refresh_count integer NOT NULL CHECK (linked_refresh_count >= 0),
  linked_duplicate_claim_count integer NOT NULL CHECK (linked_duplicate_claim_count >= 0),
  ambiguous_symbol_count integer NOT NULL CHECK (ambiguous_symbol_count >= 0),
  rejected_low_confidence_count integer NOT NULL CHECK (rejected_low_confidence_count >= 0),
  unsupported_instrument_count integer NOT NULL CHECK (unsupported_instrument_count >= 0),
  mention_reason_counts jsonb NOT NULL CHECK (jsonb_typeof(mention_reason_counts) = 'object'),
  linked_candidate_count integer NOT NULL CHECK (linked_candidate_count >= 0),
  status opportunity_source_connector_status_v3 NOT NULL,
  failure_reason opportunity_failure_code_v3,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (run_id, source_key),
  CHECK (selected_document_count + deferred_due_scan_cap_count = eligible_document_count),
  CHECK (
    duplicate_document_count + expired_document_count + parse_failure_count
      + processed_no_claim_count + processed_with_claims_count = selected_document_count
  )
);

CREATE TABLE IF NOT EXISTS opportunity_source_document_outcomes (
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  source_key source_key_v3 NOT NULL,
  revision_id uuid NOT NULL REFERENCES source_document_revisions_v3(revision_id) ON DELETE RESTRICT,
  selection_ordinal integer NOT NULL CHECK (selection_ordinal >= 0),
  canonical_document_id text,
  effective_at timestamptz NOT NULL,
  outcome opportunity_document_outcome_v3 NOT NULL,
  content_hash text CHECK (content_hash IS NULL OR content_hash ~ '^[0-9a-f]{64}$'),
  extracted_claim_count integer NOT NULL CHECK (extracted_claim_count >= 0),
  raw_mention_count integer NOT NULL CHECK (raw_mention_count >= 0),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (run_id, source_key, revision_id),
  UNIQUE (run_id, source_key, selection_ordinal)
);

CREATE TABLE IF NOT EXISTS opportunity_source_claims (
  claim_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  revision_id uuid NOT NULL REFERENCES source_document_revisions_v3(revision_id) ON DELETE RESTRICT,
  claim_ordinal integer NOT NULL CHECK (claim_ordinal >= 0),
  canonical_claim_id text NOT NULL,
  outcome opportunity_claim_outcome_v3 NOT NULL,
  canonical_prior_claim_id uuid REFERENCES opportunity_source_claims(claim_id) ON DELETE RESTRICT,
  evidence_root_id text NOT NULL,
  effective_at timestamptz NOT NULL,
  claim_confidence double precision NOT NULL CHECK (claim_confidence BETWEEN 0 AND 1),
  source_ref text NOT NULL CHECK (char_length(source_ref) BETWEEN 1 AND 120),
  verification_tier opportunity_evidence_verification_tier_v3 NOT NULL,
  claim_evidence_stance opportunity_claim_evidence_stance_v3 NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (run_id, revision_id, claim_ordinal)
);

CREATE TABLE IF NOT EXISTS opportunity_source_mentions (
  mention_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  revision_id uuid NOT NULL REFERENCES source_document_revisions_v3(revision_id) ON DELETE RESTRICT,
  claim_ordinal integer NOT NULL,
  mention_ordinal integer NOT NULL CHECK (mention_ordinal >= 0),
  normalized_token text NOT NULL CHECK (char_length(normalized_token) BETWEEN 2 AND 40),
  start_offset integer NOT NULL,
  end_offset integer NOT NULL,
  review_context text NOT NULL CHECK (char_length(review_context) BETWEEN 2 AND 96 AND octet_length(review_context) <= 384),
  review_mention_start_offset integer NOT NULL,
  review_mention_end_offset integer NOT NULL,
  link_mode opportunity_link_mode_v3 NOT NULL,
  stock_id uuid REFERENCES stocks(id) ON DELETE RESTRICT,
  symbol text CHECK (symbol IS NULL OR symbol ~ '^[0-9]{4}$'),
  outcome opportunity_mention_outcome_v3 NOT NULL,
  reason opportunity_mention_reason_v3 NOT NULL,
  confidence double precision NOT NULL CHECK (confidence BETWEEN 0 AND 1),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  FOREIGN KEY (run_id, revision_id, claim_ordinal)
    REFERENCES opportunity_source_claims(run_id, revision_id, claim_ordinal) ON DELETE RESTRICT,
  UNIQUE (run_id, revision_id, claim_ordinal, mention_ordinal),
  CHECK (0 <= start_offset AND start_offset < end_offset AND end_offset <= 100000),
  CHECK (0 <= review_mention_start_offset
    AND review_mention_start_offset < review_mention_end_offset
    AND review_mention_end_offset <= char_length(review_context)),
  CHECK (
    (outcome IN ('linked_new','linked_refresh','linked_duplicate_claim') AND stock_id IS NOT NULL AND symbol IS NOT NULL)
    OR
    (outcome NOT IN ('linked_new','linked_refresh','linked_duplicate_claim') AND stock_id IS NULL AND symbol IS NULL)
  )
);

CREATE TABLE IF NOT EXISTS opportunity_candidate_snapshots (
  candidate_snapshot_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  symbol text NOT NULL CHECK (symbol ~ '^[0-9]{4}$'),
  direct_source boolean NOT NULL,
  candidate_origin opportunity_candidate_origin_v3 NOT NULL,
  anchor_claim_id uuid REFERENCES opportunity_source_claims(claim_id) ON DELETE RESTRICT,
  shallow_status opportunity_shallow_status_v3 NOT NULL,
  deep_status opportunity_deep_status_v3 NOT NULL,
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (run_id, symbol),
  CHECK (
    (candidate_origin = 'direct_candidate' AND direct_source AND anchor_claim_id IS NOT NULL)
    OR
    (candidate_origin = 'comparison_only' AND NOT direct_source AND anchor_claim_id IS NULL)
  ),
  CHECK (candidate_origin <> 'comparison_only' OR deep_status <> 'succeeded')
);

CREATE TABLE IF NOT EXISTS opportunity_market_context_snapshots (
  market_snapshot_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  run_id uuid NOT NULL UNIQUE REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  contract_version text NOT NULL CHECK (contract_version = 'market-context-v3.6'),
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE IF NOT EXISTS opportunity_sector_cycle_snapshots (
  sector_snapshot_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  canonical_sector_key canonical_sector_key_v3 NOT NULL,
  contract_version text NOT NULL CHECK (contract_version = 'sector-cycle-v3.0'),
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (run_id, canonical_sector_key)
);

CREATE TABLE IF NOT EXISTS opportunity_score_snapshots (
  score_snapshot_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  symbol text NOT NULL,
  horizon opportunity_horizon_v3 NOT NULL,
  rank integer NOT NULL CHECK (rank BETWEEN 1 AND 20),
  score double precision NOT NULL CHECK (score BETWEEN 0 AND 100),
  score_confidence double precision NOT NULL CHECK (score_confidence BETWEEN 0 AND 1),
  available_weight double precision NOT NULL CHECK (available_weight BETWEEN 0 AND 100),
  payload_canonical bytea NOT NULL,
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (run_id, symbol, horizon)
);

CREATE TABLE IF NOT EXISTS opportunity_shallow_candidate_results_v3 (
  job_id uuid NOT NULL REFERENCES opportunity_run_jobs_v3(job_id) ON DELETE RESTRICT,
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  candidate_ordinal integer NOT NULL CHECK (candidate_ordinal >= 0),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  symbol text NOT NULL CHECK (symbol ~ '^[0-9]{4}$'),
  direct_source boolean NOT NULL,
  candidate_origin opportunity_candidate_origin_v3 NOT NULL,
  anchor_claim_id uuid REFERENCES opportunity_source_claims(claim_id) ON DELETE RESTRICT,
  canonical_sector_key canonical_sector_key_v3 NOT NULL,
  shallow_status opportunity_shallow_status_v3 NOT NULL,
  failure_code opportunity_failure_code_v3,
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (job_id,candidate_ordinal),
  UNIQUE (run_id,symbol),
  CHECK (
    (candidate_origin='direct_candidate' AND direct_source AND anchor_claim_id IS NOT NULL)
    OR
    (candidate_origin='comparison_only' AND NOT direct_source AND anchor_claim_id IS NULL)
  ),
  CHECK (
    (shallow_status='failed' AND failure_code IS NOT NULL)
    OR
    (shallow_status<>'failed' AND failure_code IS NULL)
  )
);

CREATE TABLE IF NOT EXISTS opportunity_deep_candidate_results_v3 (
  job_id uuid NOT NULL REFERENCES opportunity_run_jobs_v3(job_id) ON DELETE RESTRICT,
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  candidate_ordinal integer NOT NULL CHECK (candidate_ordinal >= 0),
  stock_id uuid NOT NULL REFERENCES stocks(id) ON DELETE RESTRICT,
  symbol text NOT NULL CHECK (symbol ~ '^[0-9]{4}$'),
  anchor_claim_id uuid NOT NULL REFERENCES opportunity_source_claims(claim_id) ON DELETE RESTRICT,
  canonical_sector_key canonical_sector_key_v3 NOT NULL,
  deep_status opportunity_deep_status_v3 NOT NULL CHECK (deep_status IN ('failed','succeeded')),
  failure_code opportunity_failure_code_v3,
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (job_id,candidate_ordinal),
  UNIQUE (run_id,symbol),
  CHECK (
    (deep_status='failed' AND failure_code IS NOT NULL)
    OR
    (deep_status='succeeded' AND failure_code IS NULL)
  )
);

CREATE TABLE IF NOT EXISTS opportunity_portfolio_allocations_v3 (
  job_id uuid NOT NULL REFERENCES opportunity_run_jobs_v3(job_id) ON DELETE RESTRICT,
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  allocation_ordinal integer NOT NULL CHECK (allocation_ordinal BETWEEN 0 AND 19),
  symbol text NOT NULL CHECK (symbol ~ '^[0-9]{4}$'),
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL CHECK (jsonb_typeof(payload_json)='object'),
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (job_id,allocation_ordinal),
  UNIQUE (run_id,symbol)
);

CREATE TABLE IF NOT EXISTS opportunity_evaluation_results_v3 (
  run_id uuid PRIMARY KEY REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  job_id uuid NOT NULL UNIQUE REFERENCES opportunity_run_jobs_v3(job_id) ON DELETE RESTRICT,
  status text NOT NULL CHECK (status IN ('pass','fail')),
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL CHECK (jsonb_typeof(payload_json)='object'),
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE IF NOT EXISTS opportunity_outcomes (
  outcome_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  score_snapshot_id uuid NOT NULL REFERENCES opportunity_score_snapshots(score_snapshot_id) ON DELETE RESTRICT,
  maturity_horizon opportunity_outcome_maturity_v3 NOT NULL,
  entry_session date NOT NULL,
  entry_session_authority_hash text NOT NULL CHECK (entry_session_authority_hash ~ '^[0-9a-f]{64}$'),
  maturity_session date NOT NULL,
  maturity_session_authority_hash text NOT NULL CHECK (maturity_session_authority_hash ~ '^[0-9a-f]{64}$'),
  entry_price_ref text NOT NULL,
  outcome_price_ref text NOT NULL,
  sector_benchmark_manifest_id uuid NOT NULL REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  return_pct double precision NOT NULL CHECK (return_pct > '-Infinity'::double precision AND return_pct < 'Infinity'::double precision),
  sector_relative_return_pct double precision NOT NULL CHECK (sector_relative_return_pct > '-Infinity'::double precision AND sector_relative_return_pct < 'Infinity'::double precision),
  mfe_pct double precision NOT NULL CHECK (mfe_pct > '-Infinity'::double precision AND mfe_pct < 'Infinity'::double precision),
  mae_pct double precision NOT NULL CHECK (mae_pct > '-Infinity'::double precision AND mae_pct < 'Infinity'::double precision),
  sector_relative_mfe_pct double precision CHECK (sector_relative_mfe_pct IS NULL OR (sector_relative_mfe_pct > '-Infinity'::double precision AND sector_relative_mfe_pct < 'Infinity'::double precision)),
  payload_canonical bytea NOT NULL,
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (score_snapshot_id, maturity_horizon)
);

CREATE TABLE IF NOT EXISTS opportunity_link_audit_samples (
  sample_manifest_id uuid NOT NULL REFERENCES opportunity_manifests_v3(manifest_id) ON DELETE RESTRICT,
  sample_id text NOT NULL CHECK (sample_id ~ '^[0-9a-f]{64}$'),
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  claim_id uuid NOT NULL,
  mention_id uuid NOT NULL,
  connector text NOT NULL,
  link_mode opportunity_link_mode_v3 NOT NULL,
  outcome_family opportunity_link_outcome_family_v3 NOT NULL,
  mention_ordinal integer NOT NULL CHECK (mention_ordinal >= 0),
  selection_ordinal integer NOT NULL CHECK (selection_ordinal >= 0),
  selection_hash text NOT NULL CHECK (selection_hash ~ '^[0-9a-f]{64}$'),
  evidence_ref text NOT NULL,
  review_context text NOT NULL CHECK (char_length(review_context) BETWEEN 2 AND 96 AND octet_length(review_context) <= 384),
  review_mention_start_offset integer NOT NULL,
  review_mention_end_offset integer NOT NULL,
  normalized_token text NOT NULL,
  engine_outcome opportunity_mention_outcome_v3 NOT NULL,
  engine_reason opportunity_mention_reason_v3 NOT NULL,
  engine_canonical_symbol text,
  review_evidence_hash text NOT NULL CHECK (review_evidence_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (sample_manifest_id, sample_id),
  CHECK (review_mention_start_offset >= 0 AND review_mention_end_offset > review_mention_start_offset)
);

CREATE TABLE IF NOT EXISTS opportunity_link_audit_labels (
  sample_manifest_id uuid NOT NULL,
  sample_id text NOT NULL,
  label_role link_audit_label_role_v3 NOT NULL,
  canonical_symbol text,
  no_link boolean NOT NULL,
  reviewer_principal_id uuid NOT NULL,
  submitted_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  label_hash text NOT NULL CHECK (label_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (sample_manifest_id,sample_id,label_role),
  UNIQUE (sample_manifest_id,sample_id,reviewer_principal_id),
  FOREIGN KEY (sample_manifest_id,sample_id)
    REFERENCES opportunity_link_audit_samples(sample_manifest_id,sample_id) ON DELETE RESTRICT,
  CHECK ((no_link AND canonical_symbol IS NULL) OR (NOT no_link AND canonical_symbol ~ '^[0-9]{4}$'))
);

CREATE TABLE IF NOT EXISTS opportunity_public_projections_v3 (
  run_id uuid PRIMARY KEY REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  contract_version text NOT NULL CHECK (contract_version = 'source-led-opportunity-v3.6'),
  acceptance_version text NOT NULL CHECK (acceptance_version = '1.44.6'),
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE IF NOT EXISTS opportunity_detail_projections_v3 (
  run_id uuid NOT NULL REFERENCES opportunity_runs(run_id) ON DELETE RESTRICT,
  symbol text NOT NULL,
  contract_version text NOT NULL CHECK (contract_version = 'opportunity-detail-v3.3'),
  payload_canonical bytea NOT NULL CHECK (octet_length(payload_canonical) <= 3145728),
  payload_json jsonb NOT NULL,
  payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (run_id, symbol)
);

CREATE OR REPLACE FUNCTION select_opportunity_public_projection_v3(
  request_cutoff timestamptz
) RETURNS TABLE(
  availability text,
  unavailable_reason text,
  selected_run_id uuid,
  warnings opportunity_engine_warning_v3[],
  payload_canonical bytea,
  payload_json jsonb,
  payload_hash text
)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
WITH created AS MATERIALIZED (
  SELECT r.*,
    CASE
      WHEN r.terminal_at IS NOT NULL AND r.terminal_at <= $1 THEN r.status
      ELSE 'running'::public.opportunity_run_status_v3
    END AS status_at_cutoff
  FROM public.opportunity_runs r
  WHERE r.mode='enrich_rank'
    AND r.created_at <= $1
    AND r.source_cutoff <= $1
),
matching AS MATERIALIZED (
  SELECT *
  FROM created
  WHERE run_purpose='production_shadow_daily'
    AND comparison_contract_key='ebaa6dbdaa7dd55bb261187008f51e930919e7c0cfe07732d531e01267e67c41'
),
successes AS MATERIALIZED (
  SELECT matching.*
  FROM matching
  JOIN public.opportunity_public_projections_v3 projection USING(run_id)
  WHERE status_at_cutoff='success'
    AND projection.recorded_at <= $1
  ORDER BY matching.source_cutoff DESC,matching.terminal_at DESC,matching.run_id ASC
  LIMIT 2
),
success_choice AS (
  SELECT s.*
  FROM successes s
  WHERE NOT EXISTS (
    SELECT 1
    FROM successes other
    WHERE other.run_id<>s.run_id
      AND other.source_cutoff=s.source_cutoff
      AND other.terminal_at=s.terminal_at
  )
  ORDER BY s.source_cutoff DESC,s.terminal_at DESC,s.run_id ASC
  LIMIT 1
),
active_choice AS (
  SELECT *
  FROM matching
  WHERE status_at_cutoff='running'
  ORDER BY source_cutoff DESC,created_at DESC,run_id ASC
  LIMIT 1
),
failed_choice AS (
  SELECT *
  FROM matching
  WHERE status_at_cutoff='failed'
  ORDER BY source_cutoff DESC,terminal_at DESC,run_id ASC
  LIMIT 1
),
decision AS (
  SELECT
    CASE
      WHEN NOT EXISTS (SELECT 1 FROM created) THEN 'cold_start'
      WHEN NOT EXISTS (SELECT 1 FROM matching) THEN 'no_matching_success'
      WHEN (SELECT count(*) FROM successes)=2
        AND (SELECT min(source_cutoff)=max(source_cutoff) AND min(terminal_at)=max(terminal_at) FROM successes)
        THEN 'latest_matching_failed'
      WHEN EXISTS (SELECT 1 FROM success_choice) THEN NULL
      WHEN EXISTS (SELECT 1 FROM active_choice) THEN 'matching_run_in_progress'
      WHEN EXISTS (SELECT 1 FROM failed_choice) THEN 'latest_matching_failed'
      WHEN EXISTS (SELECT 1 FROM matching WHERE status_at_cutoff='success')
        THEN 'latest_matching_failed'
      ELSE 'no_matching_success'
    END AS reason,
    COALESCE(
      (SELECT run_id FROM success_choice),
      (SELECT run_id FROM active_choice),
      (SELECT run_id FROM failed_choice)
    ) AS selected_run_id
),
selected_warnings AS (
  SELECT f.warning
  FROM decision d
  JOIN public.opportunity_run_warning_facts_v3 f ON f.run_id=d.selected_run_id
  JOIN public.opportunity_run_jobs_v3 j
    ON j.run_id=f.run_id AND j.job_id=f.producing_job_id
  WHERE (d.reason IS NULL OR d.reason IN ('matching_run_in_progress','latest_matching_failed'))
    AND f.recorded_at <= $1
    AND j.status='succeeded'
    AND j.terminal_at <= $1
  GROUP BY f.warning
)
SELECT
  CASE WHEN d.reason IS NULL THEN 'available' ELSE 'unavailable' END,
  d.reason,
  CASE WHEN d.reason IS NULL THEN d.selected_run_id ELSE NULL END,
  ARRAY(
    SELECT warning
    FROM (
      SELECT warning FROM selected_warnings
      UNION
      SELECT 'shadow_only'::public.opportunity_engine_warning_v3
    ) ordered
    ORDER BY warning
  ),
  p.payload_canonical,
  p.payload_json,
  p.payload_hash
FROM decision d
LEFT JOIN public.opportunity_public_projections_v3 p
  ON d.reason IS NULL AND p.run_id=d.selected_run_id
$fn$;

CREATE OR REPLACE FUNCTION enforce_opportunity_candidate_anchor_v3()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
BEGIN
  IF NEW.candidate_origin='direct_candidate' AND NOT EXISTS (
    SELECT 1
    FROM public.opportunity_source_claims c
    JOIN public.opportunity_source_mentions m
      ON m.run_id=c.run_id AND m.revision_id=c.revision_id AND m.claim_ordinal=c.claim_ordinal
    WHERE c.claim_id=NEW.anchor_claim_id
      AND c.run_id=(
        SELECT r.upstream_run_id FROM public.opportunity_runs r WHERE r.run_id=NEW.run_id
      )
      AND m.stock_id=NEW.stock_id
      AND m.symbol=NEW.symbol
      AND m.outcome IN ('linked_new','linked_refresh','linked_duplicate_claim')
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
  END IF;
  RETURN NEW;
END
$fn$;

DO $candidate_anchor_trigger$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='opportunity_candidate_anchor_v3' AND NOT tgisinternal) THEN
    CREATE CONSTRAINT TRIGGER opportunity_candidate_anchor_v3
    AFTER INSERT OR UPDATE ON opportunity_candidate_snapshots
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION enforce_opportunity_candidate_anchor_v3();
  END IF;
END
$candidate_anchor_trigger$;

CREATE OR REPLACE FUNCTION enforce_opportunity_detail_evidence_v3()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_item jsonb;
  v_count integer;
  v_stock_id uuid;
  v_expected_evidence_count integer;
  v_horizon text;
  v_horizon_ordinal integer := 0;
  v_card_matches integer;
  v_source_run_id uuid;
BEGIN
  SELECT r.upstream_run_id INTO STRICT v_source_run_id
  FROM public.opportunity_runs r WHERE r.run_id=NEW.run_id;
  SELECT c.stock_id INTO STRICT v_stock_id
  FROM public.opportunity_candidate_snapshots c
  WHERE c.run_id=NEW.run_id AND c.symbol=NEW.symbol
    AND c.candidate_origin='direct_candidate' AND c.deep_status='succeeded';
  IF NEW.payload_json->>'runId'<>NEW.run_id::text
    OR NEW.payload_json->>'symbol'<>NEW.symbol
    OR (NEW.payload_json->>'sourceCutoff')::timestamptz<>(
      SELECT r.source_cutoff FROM public.opportunity_runs r WHERE r.run_id=NEW.run_id
    )
    OR jsonb_typeof(NEW.payload_json->'sourceEvidence')<>'array'
    OR jsonb_typeof(NEW.payload_json->'horizonDetails')<>'array'
    OR jsonb_array_length(NEW.payload_json->'horizonDetails')<>3
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  v_count:=jsonb_array_length(NEW.payload_json->'sourceEvidence');
  IF v_count NOT BETWEEN 1 AND 12 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  IF (
    SELECT count(DISTINCT value->>'ref') FROM jsonb_array_elements(NEW.payload_json->'sourceEvidence')
  ) <> v_count THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  SELECT LEAST(12,count(DISTINCT c.source_ref))::integer INTO v_expected_evidence_count
  FROM public.opportunity_source_claims c
  JOIN public.opportunity_source_mentions m
    ON m.run_id=c.run_id AND m.revision_id=c.revision_id AND m.claim_ordinal=c.claim_ordinal
  WHERE c.run_id=v_source_run_id AND m.stock_id=v_stock_id AND m.symbol=NEW.symbol
    AND m.outcome IN ('linked_new','linked_refresh','linked_duplicate_claim');
  IF v_count<>v_expected_evidence_count THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(NEW.payload_json->'sourceEvidence') LOOP
    IF 1 <> (
      SELECT count(*)
      FROM public.opportunity_source_claims c
      JOIN public.source_document_revisions_v3 r ON r.revision_id=c.revision_id
      JOIN public.opportunity_run_manifest_inputs source_identity_binding
        ON source_identity_binding.run_id=NEW.run_id
        AND source_identity_binding.input_role='source_identity_allowlist'
        AND source_identity_binding.ordinal=0
      JOIN public.opportunity_manifest_rows_v3 source_identity_row
        ON source_identity_row.manifest_id=source_identity_binding.manifest_id
        AND source_identity_row.section_key='rows'
        AND (source_identity_row.payload_json->>0)::uuid=r.source_identity_authority_id
        AND (source_identity_row.payload_json->>1)::uuid=r.approved_source_identity_id
        AND source_identity_row.payload_json->>2=r.source_key::text
      JOIN public.opportunity_source_mentions m
        ON m.run_id=c.run_id AND m.revision_id=c.revision_id AND m.claim_ordinal=c.claim_ordinal
      WHERE c.run_id=v_source_run_id
        AND m.stock_id=v_stock_id
        AND m.symbol=NEW.symbol
        AND m.outcome IN ('linked_new','linked_refresh','linked_duplicate_claim')
        AND c.source_ref=v_item->>'ref'
        AND r.source_key::text=v_item->>'sourceKey'
        AND source_identity_row.payload_json->>3=v_item->>'sourceClass'
        AND c.effective_at=(v_item->>'effectiveAt')::timestamptz
        AND m.reason::text=v_item->>'linkReason'
        AND c.verification_tier::text=v_item->>'verificationTier'
        AND c.claim_evidence_stance::text=v_item->>'stance'
    ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  END LOOP;
  FOR v_item IN SELECT value FROM jsonb_array_elements(NEW.payload_json->'horizonDetails') LOOP
    v_horizon := (ARRAY['momentum_5_20d','swing_20_60d','thesis_120_250d'])[v_horizon_ordinal+1];
    IF v_item->>'horizon'<>v_horizon
      OR jsonb_typeof(v_item->'factors')<>'array'
      OR jsonb_array_length(v_item->'factors')<>6
      OR (SELECT array_agg(value->>'key' ORDER BY ordinal)
          FROM jsonb_array_elements(v_item->'factors') WITH ORDINALITY AS f(value,ordinal))
        <> ARRAY['priceVolume','chip','catalyst','marketSector','fundamental','valuation']
      OR 1 <> (
        SELECT count(*) FROM public.opportunity_score_snapshots s
        WHERE s.run_id=NEW.run_id AND s.stock_id=v_stock_id AND s.symbol=NEW.symbol
          AND s.horizon::text=v_horizon
          AND s.rank=(v_item->>'rank')::integer
          AND s.score=(v_item->>'score')::double precision
          AND s.score_confidence=(v_item->>'scoreConfidence')::double precision
          AND s.available_weight=(v_item->>'availableWeight')::double precision
      )
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
    v_horizon_ordinal := v_horizon_ordinal+1;
  END LOOP;
  SELECT count(*) INTO v_card_matches
  FROM public.opportunity_public_projections_v3 p
  CROSS JOIN LATERAL jsonb_array_elements(
    COALESCE(p.payload_json->'actionableNow','[]'::jsonb)
      || COALESCE(p.payload_json->'waitingForTrigger','[]'::jsonb)
      || COALESCE(p.payload_json->'valuationReview','[]'::jsonb)
  ) AS cards(card)
  WHERE p.run_id=NEW.run_id AND cards.card->>'symbol'=NEW.symbol
    AND cards.card=NEW.payload_json->'card';
  IF v_card_matches<>1 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  RETURN NEW;
EXCEPTION WHEN no_data_found OR too_many_rows OR invalid_text_representation OR datetime_field_overflow THEN
  RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
END
$fn$;

DO $detail_evidence_trigger$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='opportunity_detail_evidence_v3' AND NOT tgisinternal) THEN
    CREATE CONSTRAINT TRIGGER opportunity_detail_evidence_v3
    AFTER INSERT OR UPDATE ON opportunity_detail_projections_v3
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION enforce_opportunity_detail_evidence_v3();
  END IF;
END
$detail_evidence_trigger$;

CREATE OR REPLACE FUNCTION opportunity_candidate_plan_v3_internal(
  requested_run_id uuid,requested_phase text
) RETURNS TABLE(
  candidate_ordinal integer,
  stock_id uuid,
  symbol text,
  anchor_claim_id uuid,
  source_key source_key_v3,
  canonical_sector_key canonical_sector_key_v3,
  priority_score double precision
)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_cutoff timestamptz; v_upstream uuid;
BEGIN
  IF requested_phase NOT IN ('active','shallow','deep') THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
  END IF;
  SELECT run.source_cutoff,run.upstream_run_id INTO STRICT v_cutoff,v_upstream
  FROM public.opportunity_runs run
  WHERE run.run_id=requested_run_id AND run.mode='enrich_rank';
  IF requested_phase='deep' THEN
    RETURN QUERY
    WITH eligible AS MATERIALIZED (
      SELECT shallow.stock_id,shallow.symbol,shallow.anchor_claim_id,
        revision.source_key,shallow.canonical_sector_key,
        greatest(0,least(100,
          0.60*(shallow.payload_json->>5)::double precision+
          0.20*(shallow.payload_json->>6)::double precision+
          0.10*(shallow.payload_json->>7)::double precision+
          0.10*(shallow.payload_json->>8)::double precision
        )) AS priority_score
      FROM public.opportunity_shallow_candidate_results_v3 shallow
      JOIN public.opportunity_source_claims claim
        ON claim.claim_id=shallow.anchor_claim_id
      JOIN public.source_document_revisions_v3 revision
        ON revision.revision_id=claim.revision_id
      WHERE shallow.run_id=requested_run_id
        AND shallow.direct_source
        AND shallow.candidate_origin='direct_candidate'
        AND shallow.shallow_status='succeeded'
        AND shallow.symbol IN (
          SELECT symbol_value.value
          FROM public.opportunity_run_manifest_inputs input
          JOIN public.opportunity_manifests_v3 manifest
            ON manifest.manifest_id=input.manifest_id
            AND manifest.manifest_kind='candidate_financial'
            AND manifest.status='complete'
          CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
          CROSS JOIN LATERAL jsonb_array_elements_text(pair->1) symbol_value(value)
          WHERE input.run_id=requested_run_id
            AND input.input_role='candidate_financial' AND input.ordinal=0
            AND pair->>0='orderedSymbols'
        )
      ORDER BY priority_score DESC,shallow.symbol
      LIMIT 31
    ), parameters AS (
      SELECT least(20,count(*))::integer AS target,
        count(DISTINCT eligible.canonical_sector_key)::integer AS group_count
      FROM eligible
    ), quota AS (
      SELECT eligible.*,
        row_number() OVER (
          PARTITION BY eligible.canonical_sector_key
          ORDER BY eligible.priority_score DESC,eligible.symbol
        ) AS group_ordinal,
        parameters.target,parameters.group_count
      FROM eligible CROSS JOIN parameters
    ), selected AS (
      SELECT quota.*
      FROM quota
      WHERE quota.group_ordinal<=ceil(
        quota.target*greatest(0.35,1.0/greatest(1,quota.group_count))
      )
      ORDER BY quota.priority_score DESC,quota.symbol
      LIMIT 20
    )
    SELECT (row_number() OVER (
        ORDER BY selected.priority_score DESC,selected.symbol
      )-1)::integer,
      selected.stock_id,selected.symbol,selected.anchor_claim_id,
      selected.source_key,selected.canonical_sector_key,selected.priority_score
    FROM selected ORDER BY selected.priority_score DESC,selected.symbol;
    RETURN;
  END IF;
  RETURN QUERY
  WITH dependencies AS MATERIALIZED (
    SELECT
      min(input.manifest_id::text) FILTER (
        WHERE input.input_role='source_identity_allowlist'
      )::uuid AS source_identity_manifest_id,
      min(input.manifest_id::text) FILTER (
        WHERE input.input_role='taxonomy_assignment'
      )::uuid AS taxonomy_manifest_id
    FROM public.opportunity_run_manifest_inputs input
    JOIN public.opportunity_manifests_v3 manifest
      ON manifest.manifest_id=input.manifest_id
      AND manifest.status='complete'
    WHERE input.run_id=requested_run_id
      AND input.ordinal=0
      AND input.input_role IN (
        'source_identity_allowlist','taxonomy_assignment'
      )
    HAVING count(*)=2
  ), ranked_anchor AS MATERIALIZED (
    SELECT DISTINCT ON (mention.symbol)
      mention.stock_id,mention.symbol,claim.claim_id,revision.source_key,
      coalesce(sector.canonical_sector_key,'unknown'::public.canonical_sector_key_v3)
        AS canonical_sector_key,
      greatest(0,least(100,
        100*CASE authority_row.payload_json->>3
          WHEN 'official' THEN 1.0
          WHEN 'public_research' THEN 0.8
          WHEN 'curated_thesis' THEN 0.6
          ELSE 0.4 END*
        claim.claim_confidence*mention.confidence*
        greatest(0,1-extract(epoch FROM (v_cutoff-claim.effective_at))/
          CASE authority_row.payload_json->>3
            WHEN 'official' THEN 3024000.0
            WHEN 'public_research' THEN 604800.0
            WHEN 'curated_thesis' THEN 604800.0
            ELSE 259200.0 END)
      )) AS priority_score
    FROM public.opportunity_source_mentions mention
    JOIN public.opportunity_source_claims claim
      ON claim.run_id=mention.run_id
      AND claim.revision_id=mention.revision_id
      AND claim.claim_ordinal=mention.claim_ordinal
    JOIN public.source_document_revisions_v3 revision
      ON revision.revision_id=claim.revision_id
    CROSS JOIN dependencies dependency
    JOIN public.opportunity_manifest_rows_v3 authority_row
      ON authority_row.manifest_id=dependency.source_identity_manifest_id
      AND authority_row.section_key='rows'
      AND (authority_row.payload_json->>0)::uuid=revision.source_identity_authority_id
      AND (authority_row.payload_json->>1)::uuid=revision.approved_source_identity_id
      AND authority_row.payload_json->>2=revision.source_key::text
      AND authority_row.payload_json->>7='active'
      AND (authority_row.payload_json->>5)::timestamptz<=v_cutoff
      AND (
        authority_row.payload_json->6='null'::jsonb
        OR v_cutoff<(authority_row.payload_json->>6)::timestamptz
      )
    LEFT JOIN LATERAL (
      SELECT (taxonomy_row.payload_json->>4)::public.canonical_sector_key_v3
        AS canonical_sector_key
      FROM public.opportunity_manifest_rows_v3 taxonomy_row
      WHERE taxonomy_row.manifest_id=dependency.taxonomy_manifest_id
        AND taxonomy_row.section_key='rows'
        AND (taxonomy_row.payload_json->>1)::uuid=mention.stock_id
        AND taxonomy_row.payload_json->>10='active'
        AND (taxonomy_row.payload_json->>7)::timestamptz<=v_cutoff
        AND (
          taxonomy_row.payload_json->8='null'::jsonb
          OR v_cutoff<(taxonomy_row.payload_json->>8)::timestamptz
        )
      ORDER BY taxonomy_row.row_ordinal
      LIMIT 2
    ) sector ON true
    WHERE mention.run_id=v_upstream
      AND mention.outcome IN ('linked_new','linked_refresh','linked_duplicate_claim')
      AND claim.effective_at<=v_cutoff
    ORDER BY mention.symbol,priority_score DESC,claim.effective_at DESC,
      revision.source_key,claim.claim_id,authority_row.row_ordinal
  ), active AS MATERIALIZED (
    SELECT ranked_anchor.*
    FROM ranked_anchor
    ORDER BY priority_score DESC,claim_id,symbol
    LIMIT 60
    ), parameters AS (
      SELECT least(30,count(*))::integer AS target,
        count(DISTINCT active.source_key)::integer AS group_count
      FROM active
  ), quota AS (
    SELECT active.*,
      row_number() OVER (
        PARTITION BY active.source_key
        ORDER BY active.priority_score DESC,active.claim_id,active.symbol
      ) AS group_ordinal,
      parameters.target,parameters.group_count
    FROM active CROSS JOIN parameters
  ), selected AS (
    SELECT quota.*
    FROM quota
      WHERE requested_phase='active' OR quota.group_ordinal<=ceil(
        quota.target*greatest(0.40,1.0/greatest(1,quota.group_count))
      )
      ORDER BY quota.priority_score DESC,quota.claim_id,quota.symbol
    LIMIT CASE requested_phase WHEN 'active' THEN 60 ELSE 30 END
  )
  SELECT (row_number() OVER (
      ORDER BY selected.priority_score DESC,selected.claim_id,selected.symbol
    )-1)::integer,
    selected.stock_id,selected.symbol,selected.claim_id,
    selected.source_key,selected.canonical_sector_key,selected.priority_score
  FROM selected ORDER BY priority_score DESC,claim_id,symbol;
END
$fn$;

CREATE OR REPLACE FUNCTION opportunity_raise_pt409_v3_internal(requested_message text)
RETURNS integer
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
BEGIN
  RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE=requested_message;
END
$fn$;

CREATE OR REPLACE FUNCTION opportunity_authority_selected_stream_count_v3_internal(
  requested_family public.authority_stream_family_v3,
  requested_cutoff timestamptz
) RETURNS bigint
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_registry_count bigint := 0;
  v_stream_count bigint := 0;
  v_semantic_count bigint := 0;
  v_selected_count bigint := 0;
  v_bound bigint := 0;
  v_overflow text := 'identity_manifest_overflow';
BEGIN
  IF requested_family='discovery_identity' THEN
    v_bound:=10000;
    WITH bounded_registry AS MATERIALIZED (
      SELECT stream_key_hash,stream_key_canonical
      FROM public.opportunity_authority_stream_registry_v3
      WHERE family='discovery_identity'
      ORDER BY stream_key_hash,stream_key_canonical LIMIT 10001
    ), raw AS MATERIALIZED (
      SELECT registry.stream_key_hash,authority.*
      FROM bounded_registry registry
      CROSS JOIN LATERAL (
        SELECT retained.*
        FROM public.source_identity_authorities_v3 retained
        WHERE retained.source_identity_id=(
          convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
        )::uuid
        ORDER BY retained.recorded_at DESC,retained.authority_id LIMIT 65
      ) authority
    ), raw_counts AS MATERIALIZED (
      SELECT stream_key_hash,count(*) retained_count FROM raw GROUP BY stream_key_hash
    ), cutoff_rows AS MATERIALIZED (
      SELECT * FROM raw
      WHERE recorded_at<=requested_cutoff
        AND approved_at<=requested_cutoff
        AND valid_from<=requested_cutoff
    ), greatest_times AS MATERIALIZED (
      SELECT stream_key_hash,max(recorded_at) greatest_recorded_at
      FROM cutoff_rows GROUP BY stream_key_hash
    ), greatest AS MATERIALIZED (
      SELECT cutoff_rows.*
      FROM cutoff_rows JOIN greatest_times USING(stream_key_hash)
      WHERE cutoff_rows.recorded_at=greatest_times.greatest_recorded_at
    ), tie_stats AS MATERIALIZED (
      SELECT stream_key_hash,count(DISTINCT jsonb_build_array(
        source_identity_id,source_key,source_class,distribution_identity,
        valid_from,valid_to,status,approved_at,approving_principal_id
      )) semantic_count,min(authority_id::text)::uuid retained_id
      FROM greatest GROUP BY stream_key_hash
    ), selected AS MATERIALIZED (
      SELECT greatest.*
      FROM greatest JOIN tie_stats USING(stream_key_hash)
      WHERE greatest.authority_id=tie_stats.retained_id
    )
    SELECT (SELECT count(*) FROM bounded_registry),
      coalesce((SELECT max(retained_count) FROM raw_counts),0),
      coalesce((SELECT max(semantic_count) FROM tie_stats),0),
      (SELECT count(*) FROM selected)
    INTO v_registry_count,v_stream_count,v_semantic_count,v_selected_count;
  ELSIF requested_family='publisher_verification' THEN
    v_bound:=10000;
    WITH bounded_registry AS MATERIALIZED (
      SELECT stream_key_hash,stream_key_canonical
      FROM public.opportunity_authority_stream_registry_v3
      WHERE family='publisher_verification'
      ORDER BY stream_key_hash,stream_key_canonical LIMIT 10001
    ), raw AS MATERIALIZED (
      SELECT registry.stream_key_hash,authority.*
      FROM bounded_registry registry
      CROSS JOIN LATERAL (
        SELECT retained.*
        FROM public.publisher_verification_authorities_v3 retained
        WHERE retained.publisher_identity_id=(
          convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
        )::uuid
        ORDER BY retained.recorded_at DESC,retained.authority_id LIMIT 65
      ) authority
    ), raw_counts AS MATERIALIZED (
      SELECT stream_key_hash,count(*) retained_count FROM raw GROUP BY stream_key_hash
    ), cutoff_rows AS MATERIALIZED (
      SELECT * FROM raw
      WHERE recorded_at<=requested_cutoff
        AND approved_at<=requested_cutoff
        AND valid_from<=requested_cutoff
    ), greatest_times AS MATERIALIZED (
      SELECT stream_key_hash,max(recorded_at) greatest_recorded_at
      FROM cutoff_rows GROUP BY stream_key_hash
    ), greatest AS MATERIALIZED (
      SELECT cutoff_rows.*
      FROM cutoff_rows JOIN greatest_times USING(stream_key_hash)
      WHERE cutoff_rows.recorded_at=greatest_times.greatest_recorded_at
    ), tie_stats AS MATERIALIZED (
      SELECT stream_key_hash,count(DISTINCT jsonb_build_array(
        publisher_identity_id,source_class,domains,feed_identity,institution_identity,
        valid_from,valid_to,approved_at,approving_principal_id,status
      )) semantic_count,min(authority_id::text)::uuid retained_id
      FROM greatest GROUP BY stream_key_hash
    ), selected AS MATERIALIZED (
      SELECT greatest.*
      FROM greatest JOIN tie_stats USING(stream_key_hash)
      WHERE greatest.authority_id=tie_stats.retained_id
    )
    SELECT (SELECT count(*) FROM bounded_registry),
      coalesce((SELECT max(retained_count) FROM raw_counts),0),
      coalesce((SELECT max(semantic_count) FROM tie_stats),0),
      (SELECT count(*) FROM selected)
    INTO v_registry_count,v_stream_count,v_semantic_count,v_selected_count;
  ELSIF requested_family='instrument_roster' THEN
    v_bound:=20000; v_overflow:='roster_volume_exceeded';
    WITH bounded_registry AS MATERIALIZED (
      SELECT stream_key_hash,stream_key_canonical
      FROM public.opportunity_authority_stream_registry_v3
      WHERE family='instrument_roster'
      ORDER BY stream_key_hash,stream_key_canonical LIMIT 20001
    ), raw AS MATERIALIZED (
      SELECT registry.stream_key_hash,authority.*
      FROM bounded_registry registry
      CROSS JOIN LATERAL (
        SELECT retained.*
        FROM public.stock_instruments_v3 retained
        WHERE retained.stock_id=(
          convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
        )::uuid
        ORDER BY retained.recorded_at DESC,retained.instrument_authority_id LIMIT 65
      ) authority
    ), raw_counts AS MATERIALIZED (
      SELECT stream_key_hash,count(*) retained_count FROM raw GROUP BY stream_key_hash
    ), cutoff_rows AS MATERIALIZED (
      SELECT * FROM raw
      WHERE recorded_at<=requested_cutoff
        AND source_timestamp<=requested_cutoff
        AND valid_from<=requested_cutoff
    ), greatest_times AS MATERIALIZED (
      SELECT stream_key_hash,max(recorded_at) greatest_recorded_at
      FROM cutoff_rows GROUP BY stream_key_hash
    ), greatest AS MATERIALIZED (
      SELECT cutoff_rows.*
      FROM cutoff_rows JOIN greatest_times USING(stream_key_hash)
      WHERE cutoff_rows.recorded_at=greatest_times.greatest_recorded_at
    ), tie_stats AS MATERIALIZED (
      SELECT stream_key_hash,count(DISTINCT jsonb_build_array(
        stock_id,symbol,exchange,instrument_type,listing_status,official_legal_name,
        official_short_name,provider,source_timestamp,valid_from,valid_to,roster_version
      )) semantic_count,min(instrument_authority_id::text)::uuid retained_id
      FROM greatest GROUP BY stream_key_hash
    ), selected AS MATERIALIZED (
      SELECT greatest.*
      FROM greatest JOIN tie_stats USING(stream_key_hash)
      WHERE greatest.instrument_authority_id=tie_stats.retained_id
    )
    SELECT (SELECT count(*) FROM bounded_registry),
      coalesce((SELECT max(retained_count) FROM raw_counts),0),
      coalesce((SELECT max(semantic_count) FROM tie_stats),0),
      (SELECT count(*) FROM selected)
    INTO v_registry_count,v_stream_count,v_semantic_count,v_selected_count;
  ELSIF requested_family='stock_alias' THEN
    v_bound:=100000;
    WITH bounded_registry AS MATERIALIZED (
      SELECT stream_key_hash,stream_key_canonical
      FROM public.opportunity_authority_stream_registry_v3
      WHERE family='stock_alias'
      ORDER BY stream_key_hash,stream_key_canonical LIMIT 100001
    ), decoded_registry AS MATERIALIZED (
      SELECT stream_key_hash,
        (convert_from(stream_key_canonical,'utf8')::jsonb->>1)::uuid stock_id,
        convert_from(stream_key_canonical,'utf8')::jsonb->>2 normalized_alias,
        (convert_from(stream_key_canonical,'utf8')::jsonb->>3)::public.alias_source_v3 source
      FROM bounded_registry
    ), raw AS MATERIALIZED (
      SELECT registry.stream_key_hash,authority.*
      FROM decoded_registry registry
      CROSS JOIN LATERAL (
        SELECT retained.*
        FROM public.stock_aliases_v3 retained
        WHERE retained.stock_id=registry.stock_id
          AND retained.normalized_alias=registry.normalized_alias
          AND retained.source=registry.source
        ORDER BY retained.recorded_at DESC,retained.alias_authority_id LIMIT 65
      ) authority
    ), raw_counts AS MATERIALIZED (
      SELECT stream_key_hash,count(*) retained_count FROM raw GROUP BY stream_key_hash
    ), cutoff_rows AS MATERIALIZED (
      SELECT * FROM raw
      WHERE recorded_at<=requested_cutoff
        AND source_timestamp<=requested_cutoff
        AND approved_at<=requested_cutoff
        AND valid_from<=requested_cutoff
    ), greatest_times AS MATERIALIZED (
      SELECT stream_key_hash,max(recorded_at) greatest_recorded_at
      FROM cutoff_rows GROUP BY stream_key_hash
    ), greatest AS MATERIALIZED (
      SELECT cutoff_rows.*
      FROM cutoff_rows JOIN greatest_times USING(stream_key_hash)
      WHERE cutoff_rows.recorded_at=greatest_times.greatest_recorded_at
    ), tie_stats AS MATERIALIZED (
      SELECT stream_key_hash,count(DISTINCT jsonb_build_array(
        stock_id,normalized_alias,source,source_timestamp,approved_by_principal_id,
        approved_at,valid_from,valid_to,status,normalization_version
      )) semantic_count,min(alias_authority_id::text)::uuid retained_id
      FROM greatest GROUP BY stream_key_hash
    ), selected AS MATERIALIZED (
      SELECT greatest.*
      FROM greatest JOIN tie_stats USING(stream_key_hash)
      WHERE greatest.alias_authority_id=tie_stats.retained_id
    )
    SELECT (SELECT count(*) FROM bounded_registry),
      coalesce((SELECT max(retained_count) FROM raw_counts),0),
      coalesce((SELECT max(semantic_count) FROM tie_stats),0),
      (SELECT count(*) FROM selected)
    INTO v_registry_count,v_stream_count,v_semantic_count,v_selected_count;
  ELSIF requested_family='sector_assignment' THEN
    v_bound:=20000; v_overflow:='roster_volume_exceeded';
    WITH bounded_registry AS MATERIALIZED (
      SELECT stream_key_hash,stream_key_canonical
      FROM public.opportunity_authority_stream_registry_v3
      WHERE family='sector_assignment'
      ORDER BY stream_key_hash,stream_key_canonical LIMIT 20001
    ), decoded_registry AS MATERIALIZED (
      SELECT stream_key_hash,
        (convert_from(stream_key_canonical,'utf8')::jsonb->>1)::uuid stock_id,
        (convert_from(stream_key_canonical,'utf8')::jsonb->>2)::public.tw_market_v3 market
      FROM bounded_registry
    ), raw AS MATERIALIZED (
      SELECT registry.stream_key_hash,authority.*
      FROM decoded_registry registry
      CROSS JOIN LATERAL (
        SELECT retained.*
        FROM public.stock_sector_assignments_v3 retained
        WHERE retained.stock_id=registry.stock_id
          AND retained.market=registry.market
        ORDER BY retained.recorded_at DESC,retained.assignment_authority_id LIMIT 65
      ) authority
    ), raw_counts AS MATERIALIZED (
      SELECT stream_key_hash,count(*) retained_count FROM raw GROUP BY stream_key_hash
    ), cutoff_rows AS MATERIALIZED (
      SELECT * FROM raw
      WHERE recorded_at<=requested_cutoff
        AND source_timestamp<=requested_cutoff
        AND valid_from<=requested_cutoff
    ), greatest_times AS MATERIALIZED (
      SELECT stream_key_hash,max(recorded_at) greatest_recorded_at
      FROM cutoff_rows GROUP BY stream_key_hash
    ), greatest AS MATERIALIZED (
      SELECT cutoff_rows.*
      FROM cutoff_rows JOIN greatest_times USING(stream_key_hash)
      WHERE cutoff_rows.recorded_at=greatest_times.greatest_recorded_at
    ), tie_stats AS MATERIALIZED (
      SELECT stream_key_hash,count(DISTINCT jsonb_build_array(
        stock_id,market,official_industry_code,canonical_sector_key,provider,
        source_timestamp,valid_from,valid_to,taxonomy_version,status
      )) semantic_count,min(assignment_authority_id::text)::uuid retained_id
      FROM greatest GROUP BY stream_key_hash
    ), selected AS MATERIALIZED (
      SELECT greatest.*
      FROM greatest JOIN tie_stats USING(stream_key_hash)
      WHERE greatest.assignment_authority_id=tie_stats.retained_id
    )
    SELECT (SELECT count(*) FROM bounded_registry),
      coalesce((SELECT max(retained_count) FROM raw_counts),0),
      coalesce((SELECT max(semantic_count) FROM tie_stats),0),
      (SELECT count(*) FROM selected)
    INTO v_registry_count,v_stream_count,v_semantic_count,v_selected_count;
  ELSIF requested_family='peer_reviewer' THEN
    v_bound:=1000;
    WITH bounded_registry AS MATERIALIZED (
      SELECT stream_key_hash,stream_key_canonical
      FROM public.opportunity_authority_stream_registry_v3
      WHERE family='peer_reviewer'
      ORDER BY stream_key_hash,stream_key_canonical LIMIT 1001
    ), raw AS MATERIALIZED (
      SELECT registry.stream_key_hash,authority.*
      FROM bounded_registry registry
      CROSS JOIN LATERAL (
        SELECT retained.*
        FROM public.stock_peer_relationship_reviewers_v3 retained
        WHERE retained.reviewer_principal_id=(
          convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
        )::uuid
        ORDER BY retained.recorded_at DESC,retained.reviewer_authority_id LIMIT 65
      ) authority
    ), raw_counts AS MATERIALIZED (
      SELECT stream_key_hash,count(*) retained_count FROM raw GROUP BY stream_key_hash
    ), cutoff_rows AS MATERIALIZED (
      SELECT * FROM raw
      WHERE recorded_at<=requested_cutoff
        AND approved_at<=requested_cutoff
        AND valid_from<=requested_cutoff
    ), greatest_times AS MATERIALIZED (
      SELECT stream_key_hash,max(recorded_at) greatest_recorded_at
      FROM cutoff_rows GROUP BY stream_key_hash
    ), greatest AS MATERIALIZED (
      SELECT cutoff_rows.*
      FROM cutoff_rows JOIN greatest_times USING(stream_key_hash)
      WHERE cutoff_rows.recorded_at=greatest_times.greatest_recorded_at
    ), tie_stats AS MATERIALIZED (
      SELECT stream_key_hash,count(DISTINCT jsonb_build_array(
        reviewer_principal_id,approving_principal_id,approved_at,
        valid_from,valid_to,status
      )) semantic_count,min(reviewer_authority_id::text)::uuid retained_id
      FROM greatest GROUP BY stream_key_hash
    ), selected AS MATERIALIZED (
      SELECT greatest.*
      FROM greatest JOIN tie_stats USING(stream_key_hash)
      WHERE greatest.reviewer_authority_id=tie_stats.retained_id
    )
    SELECT (SELECT count(*) FROM bounded_registry),
      coalesce((SELECT max(retained_count) FROM raw_counts),0),
      coalesce((SELECT max(semantic_count) FROM tie_stats),0),
      (SELECT count(*) FROM selected)
    INTO v_registry_count,v_stream_count,v_semantic_count,v_selected_count;
  ELSIF requested_family='peer_relationship' THEN
    v_bound:=100000;
    WITH bounded_registry AS MATERIALIZED (
      SELECT stream_key_hash,stream_key_canonical
      FROM public.opportunity_authority_stream_registry_v3
      WHERE family='peer_relationship'
      ORDER BY stream_key_hash,stream_key_canonical LIMIT 100001
    ), decoded_registry AS MATERIALIZED (
      SELECT stream_key_hash,
        (convert_from(stream_key_canonical,'utf8')::jsonb->>1)::uuid supplier_stock_id,
        (convert_from(stream_key_canonical,'utf8')::jsonb->>2)::uuid customer_stock_id
      FROM bounded_registry
    ), raw AS MATERIALIZED (
      SELECT registry.stream_key_hash,authority.*
      FROM decoded_registry registry
      CROSS JOIN LATERAL (
        SELECT retained.*
        FROM public.stock_peer_relationships_v3 retained
        WHERE retained.supplier_stock_id=registry.supplier_stock_id
          AND retained.customer_stock_id=registry.customer_stock_id
          AND retained.relationship_kind='supply_chain'
        ORDER BY retained.recorded_at DESC,retained.relationship_authority_id LIMIT 65
      ) authority
    ), raw_counts AS MATERIALIZED (
      SELECT stream_key_hash,count(*) retained_count FROM raw GROUP BY stream_key_hash
    ), cutoff_rows AS MATERIALIZED (
      SELECT * FROM raw
      WHERE recorded_at<=requested_cutoff
        AND source_timestamp<=requested_cutoff
        AND approved_at<=requested_cutoff
        AND valid_from<=requested_cutoff
    ), greatest_times AS MATERIALIZED (
      SELECT stream_key_hash,max(recorded_at) greatest_recorded_at
      FROM cutoff_rows GROUP BY stream_key_hash
    ), greatest AS MATERIALIZED (
      SELECT cutoff_rows.*
      FROM cutoff_rows JOIN greatest_times USING(stream_key_hash)
      WHERE cutoff_rows.recorded_at=greatest_times.greatest_recorded_at
    ), tie_stats AS MATERIALIZED (
      SELECT stream_key_hash,count(DISTINCT jsonb_build_array(
        supplier_instrument_authority_id,supplier_stock_id,
        customer_instrument_authority_id,customer_stock_id,relationship_kind,
        source_timestamp,approved_at,valid_from,valid_to,status,evidence_ref,
        reviewer_principal_id
      )) semantic_count,min(relationship_authority_id::text)::uuid retained_id
      FROM greatest GROUP BY stream_key_hash
    ), selected AS MATERIALIZED (
      SELECT greatest.*
      FROM greatest JOIN tie_stats USING(stream_key_hash)
      WHERE greatest.relationship_authority_id=tie_stats.retained_id
    )
    SELECT (SELECT count(*) FROM bounded_registry),
      coalesce((SELECT max(retained_count) FROM raw_counts),0),
      coalesce((SELECT max(semantic_count) FROM tie_stats),0),
      (SELECT count(*) FROM selected)
    INTO v_registry_count,v_stream_count,v_semantic_count,v_selected_count;
  ELSE
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
  END IF;

  IF v_registry_count>v_bound OR v_stream_count>64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE=v_overflow;
  END IF;
  IF v_semantic_count>1 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='authority_revision_conflict';
  END IF;
  RETURN coalesce(v_selected_count,0);
END
$fn$;

CREATE OR REPLACE FUNCTION opportunity_peer_authority_header_counts_v3_internal(
  requested_run_id uuid,
  requested_cutoff timestamptz
) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
WITH guard AS MATERIALIZED (
  SELECT public.opportunity_authority_selected_stream_count_v3_internal(
    'peer_relationship',requested_cutoff
  ) AS selected_stream_count
), dependencies AS MATERIALIZED (
  SELECT
    min(input.manifest_id::text) FILTER (
      WHERE input.input_role='instrument_roster'
    )::uuid AS roster_manifest_id,
    min(input.manifest_id::text) FILTER (
      WHERE input.input_role='peer_reviewer_allowlist'
    )::uuid AS reviewer_manifest_id
  FROM public.opportunity_run_manifest_inputs input
  WHERE input.run_id=requested_run_id
), bounded_registry AS MATERIALIZED (
  SELECT stream_key_hash,stream_key_canonical
  FROM public.opportunity_authority_stream_registry_v3
  WHERE family='peer_relationship'
  ORDER BY stream_key_hash,stream_key_canonical LIMIT 100001
), decoded_registry AS MATERIALIZED (
  SELECT stream_key_hash,
    (convert_from(stream_key_canonical,'utf8')::jsonb->>1)::uuid supplier_stock_id,
    (convert_from(stream_key_canonical,'utf8')::jsonb->>2)::uuid customer_stock_id
  FROM bounded_registry
), raw AS MATERIALIZED (
  SELECT registry.stream_key_hash,relationship.*
  FROM decoded_registry registry
  CROSS JOIN LATERAL (
    SELECT retained.*
    FROM public.stock_peer_relationships_v3 retained
    WHERE retained.supplier_stock_id=registry.supplier_stock_id
      AND retained.customer_stock_id=registry.customer_stock_id
      AND retained.relationship_kind='supply_chain'
    ORDER BY retained.recorded_at DESC,retained.relationship_authority_id LIMIT 65
  ) relationship
), latest AS MATERIALIZED (
  SELECT DISTINCT ON (raw.stream_key_hash) raw.*
  FROM raw
  WHERE raw.recorded_at<=requested_cutoff
    AND raw.source_timestamp<=requested_cutoff
    AND raw.approved_at<=requested_cutoff
    AND raw.valid_from<=requested_cutoff
  ORDER BY raw.stream_key_hash,raw.recorded_at DESC,raw.relationship_authority_id
), classified AS MATERIALIZED (
  SELECT latest.*,
    supplier.symbol AS roster_supplier,
    customer.symbol AS roster_customer,
    CASE
      WHEN latest.source_timestamp>latest.approved_at THEN 'source_after_approval'
      WHEN latest.status<>'active' THEN 'inactive_status'
      WHEN latest.valid_from>requested_cutoff THEN 'not_yet_valid'
      WHEN latest.valid_to IS NOT NULL AND latest.valid_to<=requested_cutoff THEN 'expired'
      WHEN latest.supplier_stock_id=latest.customer_stock_id THEN 'self_edge'
      WHEN supplier.symbol IS NULL THEN 'ineligible_supplier'
      WHEN customer.symbol IS NULL THEN 'ineligible_customer'
      WHEN NOT EXISTS (
        SELECT 1
        FROM dependencies dependency
        JOIN public.opportunity_manifest_rows_v3 reviewer
          ON reviewer.manifest_id=dependency.reviewer_manifest_id
          AND reviewer.section_key='rows'
        WHERE reviewer.payload_json->>1=latest.reviewer_principal_id::text
          AND reviewer.payload_json->>5='active'
          AND (reviewer.payload_json->>3)::timestamptz<=requested_cutoff
          AND (
            reviewer.payload_json->>4 IS NULL
            OR requested_cutoff<(reviewer.payload_json->>4)::timestamptz
          )
      ) THEN 'reviewer_not_allowed'
      WHEN NOT EXISTS (
        SELECT 1 FROM public.source_publication_verifications_v3 verification
        WHERE verification.evidence_ref=latest.evidence_ref
          AND verification.recorded_at<=requested_cutoff
          AND verification.collected_at<=requested_cutoff
      ) THEN 'unverified_evidence'
      ELSE NULL
    END AS exclusion_reason
  FROM latest CROSS JOIN dependencies
  LEFT JOIN LATERAL (
    SELECT row.payload_json->>2 AS symbol
    FROM public.opportunity_manifest_rows_v3 row
    WHERE row.manifest_id=dependencies.roster_manifest_id
      AND row.section_key='rows'
      AND (row.payload_json->>1)::uuid=latest.supplier_stock_id
      AND row.payload_json->>4='common_stock'
      AND row.payload_json->>5='active'
      AND (row.payload_json->>9)::timestamptz<=requested_cutoff
      AND (row.payload_json->>10 IS NULL OR requested_cutoff<(row.payload_json->>10)::timestamptz)
    ORDER BY row.row_ordinal LIMIT 2
  ) supplier ON true
  LEFT JOIN LATERAL (
    SELECT row.payload_json->>2 AS symbol
    FROM public.opportunity_manifest_rows_v3 row
    WHERE row.manifest_id=dependencies.roster_manifest_id
      AND row.section_key='rows'
      AND (row.payload_json->>1)::uuid=latest.customer_stock_id
      AND row.payload_json->>4='common_stock'
      AND row.payload_json->>5='active'
      AND (row.payload_json->>9)::timestamptz<=requested_cutoff
      AND (row.payload_json->>10 IS NULL OR requested_cutoff<(row.payload_json->>10)::timestamptz)
    ORDER BY row.row_ordinal LIMIT 2
  ) customer ON true
), reason_counts AS MATERIALIZED (
  SELECT
    count(*)::bigint AS scanned_row_count,
    count(*) FILTER (WHERE exclusion_reason='source_after_approval')::bigint
      AS source_after_approval,
    count(*) FILTER (WHERE exclusion_reason='inactive_status')::bigint
      AS inactive_status,
    count(*) FILTER (WHERE exclusion_reason='not_yet_valid')::bigint
      AS not_yet_valid,
    count(*) FILTER (WHERE exclusion_reason='expired')::bigint
      AS expired,
    count(*) FILTER (WHERE exclusion_reason='self_edge')::bigint
      AS self_edge,
    count(*) FILTER (WHERE exclusion_reason='ineligible_supplier')::bigint
      AS ineligible_supplier,
    count(*) FILTER (WHERE exclusion_reason='ineligible_customer')::bigint
      AS ineligible_customer,
    count(*) FILTER (WHERE exclusion_reason='reviewer_not_allowed')::bigint
      AS reviewer_not_allowed,
    count(*) FILTER (WHERE exclusion_reason='unverified_evidence')::bigint
      AS unverified_evidence
  FROM classified
)
SELECT CASE WHEN reason_counts.scanned_row_count<>guard.selected_stream_count
  THEN to_jsonb(public.opportunity_raise_pt409_v3_internal('conservation_failure'))
  ELSE jsonb_build_object(
    'scannedRowCount',reason_counts.scanned_row_count,
    'exclusionReasonCounts',jsonb_build_object(
      'source_after_approval',reason_counts.source_after_approval,
      'inactive_status',reason_counts.inactive_status,
      'not_yet_valid',reason_counts.not_yet_valid,
      'expired',reason_counts.expired,
      'self_edge',reason_counts.self_edge,
      'ineligible_supplier',reason_counts.ineligible_supplier,
      'ineligible_customer',reason_counts.ineligible_customer,
      'reviewer_not_allowed',reason_counts.reviewer_not_allowed,
      'unverified_evidence',reason_counts.unverified_evidence
    )
  ) END
FROM reason_counts CROSS JOIN guard
$fn$;

CREATE OR REPLACE FUNCTION enqueue_next_opportunity_job_v3_internal(
  requested_run_id uuid, predecessor_job_id uuid
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_run public.opportunity_runs%ROWTYPE;
  v_predecessor public.opportunity_run_jobs_v3%ROWTYPE;
  v_predecessor_payload public.opportunity_job_payloads_v3%ROWTYPE;
  v_kind public.opportunity_manifest_kind_v3;
  v_next_kind public.opportunity_manifest_kind_v3;
  v_contract text;
  v_ordinal integer := 0;
  v_next_ordinal integer := 0;
  v_source_ordinal integer;
  v_source_key public.source_key_v3;
  v_dataset_manifest_id uuid;
  v_revision_row jsonb;
  v_revision_id uuid;
  v_revision_selection_ordinal integer;
  v_revision_raw_code_point_count integer;
  v_audited_session date;
  v_audited_session_hash text;
  v_previous_session date;
  v_previous_session_hash text;
  v_recent_session_plan_hash text;
  v_stage public.opportunity_job_stage_v3;
  v_section public.opportunity_manifest_section_key_v3;
  v_next_section public.opportunity_manifest_section_key_v3;
  v_section_count bigint;
  v_payload_kind public.opportunity_job_payload_kind_v3;
  v_shard text;
  v_manifest_id uuid;
  v_body jsonb;
  v_payload jsonb;
  v_payload_text text;
  v_payload_hash text;
  v_input_hash text;
  v_input_text text;
  v_selected_count bigint;
  v_registered_count bigint;
  v_canonical_sector public.canonical_sector_key_v3;
  v_entry_session date;
  v_entry_session_hash text;
  v_benchmark_input_run_id uuid;
  v_roster_manifest_hash text;
  v_taxonomy_manifest_hash text;
  v_bytes bytea;
  v_hex text;
  v_job_id uuid;
  v_predecessor_hashes jsonb := '[]'::jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(requested_run_id::text,0));
  SELECT * INTO STRICT v_run FROM public.opportunity_runs WHERE run_id=requested_run_id FOR UPDATE;
  IF predecessor_job_id IS NULL THEN
    IF v_run.status<>'preparing' OR EXISTS (
      SELECT 1 FROM public.opportunity_run_jobs_v3 WHERE run_id=requested_run_id
    ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
    SELECT kind,contract_version INTO v_kind,v_contract FROM (VALUES
      ('source_scan'::public.opportunity_mode_v3,'source_identity_allowlist'::public.opportunity_manifest_kind_v3,'source-identity-allowlist-v3.1'),
      ('enrich_rank'::public.opportunity_mode_v3,'peer_reviewer_allowlist'::public.opportunity_manifest_kind_v3,'peer-reviewer-allowlist-v3.0'),
      ('label_outcomes'::public.opportunity_mode_v3,'outcome_input'::public.opportunity_manifest_kind_v3,'source-led-eval-v3.7'),
      ('shadow_evaluate'::public.opportunity_mode_v3,'evaluation_input'::public.opportunity_manifest_kind_v3,'source-led-eval-v3.7')
    ) AS initial(mode,kind,contract_version) WHERE mode=v_run.mode;
    IF v_run.mode='label_outcomes' AND EXISTS (
      SELECT 1
      FROM public.opportunity_run_inputs binding
      JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
      JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
      JOIN LATERAL (
        SELECT assignment.canonical_sector_key
        FROM public.stock_sector_assignments_v3 assignment
        WHERE assignment.stock_id=score.stock_id
          AND assignment.recorded_at<=v_run.source_cutoff
          AND assignment.source_timestamp<=v_run.source_cutoff
          AND assignment.valid_from<=v_run.source_cutoff
          AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
          AND assignment.status='active'
        ORDER BY assignment.recorded_at DESC,assignment.assignment_authority_id
        LIMIT 1
      ) sector ON sector.canonical_sector_key<>'unknown'
      JOIN LATERAL (
        SELECT session.session_id
        FROM public.opportunity_effective_taiwan_sessions_v3 session
        WHERE session.session_id>input.trading_date
          AND session.canonical_cutoff<=v_run.source_cutoff
        ORDER BY session.session_id LIMIT 1
      ) entry_session ON true
      WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
    ) THEN
      v_kind:='sector_benchmark';
      v_contract:='sector-benchmark-v3.1';
    END IF;
    IF v_kind='source_identity_allowlist' THEN
      SELECT count(*) INTO v_registered_count FROM (
        SELECT stream_key_hash
        FROM public.opportunity_authority_stream_registry_v3
        WHERE family='discovery_identity'
        ORDER BY stream_key_hash,stream_key_canonical LIMIT 10001
      ) bounded_registry;
      IF v_registered_count>10000 OR EXISTS (
        SELECT 1
        FROM public.opportunity_authority_stream_registry_v3 registry
        CROSS JOIN LATERAL (
          SELECT count(*) AS retained_count FROM (
            SELECT authority_id
            FROM public.source_identity_authorities_v3 authority
            WHERE authority.source_identity_id=(
              convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
            )::uuid
            ORDER BY authority.recorded_at DESC,authority.authority_id LIMIT 65
          ) bounded
        ) stream
        WHERE registry.family='discovery_identity' AND stream.retained_count>64
      ) THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
      END IF;
      v_selected_count := public.opportunity_authority_selected_stream_count_v3_internal(
        'discovery_identity',v_run.source_cutoff
      );
      IF v_selected_count>10000 THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
      END IF;
    ELSIF v_kind='peer_reviewer_allowlist' THEN
      SELECT count(*) INTO v_registered_count FROM (
        SELECT stream_key_hash
        FROM public.opportunity_authority_stream_registry_v3
        WHERE family='peer_reviewer'
        ORDER BY stream_key_hash,stream_key_canonical LIMIT 1001
      ) bounded_registry;
      IF v_registered_count>1000 OR EXISTS (
        SELECT 1
        FROM public.opportunity_authority_stream_registry_v3 registry
        CROSS JOIN LATERAL (
          SELECT count(*) AS retained_count FROM (
            SELECT reviewer_authority_id
            FROM public.stock_peer_relationship_reviewers_v3 authority
            WHERE authority.reviewer_principal_id=(
              convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
            )::uuid
            ORDER BY authority.recorded_at DESC,authority.reviewer_authority_id LIMIT 65
          ) bounded
        ) stream
        WHERE registry.family='peer_reviewer' AND stream.retained_count>64
      ) THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
      END IF;
      v_selected_count := public.opportunity_authority_selected_stream_count_v3_internal(
        'peer_reviewer',v_run.source_cutoff
      );
      IF v_selected_count>1000 THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
      END IF;
    END IF;
    v_stage := CASE WHEN v_kind IN (
      'source_identity_allowlist','publisher_verification_allowlist','instrument_roster','alias_authority',
      'taxonomy_assignment','peer_reviewer_allowlist','peer_authority'
    ) THEN 'authority_manifest' ELSE 'input_manifest_pages' END;
    v_payload_kind := 'manifest_header';
    v_shard := v_kind::text||':0:header';
    v_input_text := format('["%s","%s",0,"%s"]',requested_run_id,v_kind,v_contract);
    v_bytes := substring(extensions.digest(
      decode(replace('51689af8-f3fe-5d1e-a18f-c667ddee224a','-',''),'hex')
        || convert_to(v_input_text,'utf8'),'sha1') FROM 1 FOR 16);
    v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
    v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
    v_hex := encode(v_bytes,'hex');
    v_manifest_id := (substr(v_hex,1,8)||'-'||substr(v_hex,9,4)||'-'||substr(v_hex,13,4)||'-'
      ||substr(v_hex,17,4)||'-'||substr(v_hex,21,12))::uuid;
    v_body := jsonb_build_array(
      0,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
      CASE
        WHEN v_kind='source_identity_allowlist' THEN jsonb_build_array(
          jsonb_build_array('rowCount',
            public.opportunity_authority_selected_stream_count_v3_internal(
              'discovery_identity',v_run.source_cutoff
            )),
          jsonb_build_array('sourceCutoff',v_run.source_cutoff)
        )
        WHEN v_kind='peer_reviewer_allowlist' THEN jsonb_build_array(
          jsonb_build_array('rowCount',
            public.opportunity_authority_selected_stream_count_v3_internal(
              'peer_reviewer',v_run.source_cutoff
            )),
          jsonb_build_array('sourceCutoff',v_run.source_cutoff)
        )
        WHEN v_kind='sector_benchmark' THEN (
          WITH benchmark_pairs AS (
            SELECT sector.canonical_sector_key,entry.session_id,
              min(input.run_id::text)::uuid AS input_run_id,
              min(entry.taiwan_session_authority_hash) AS entry_session_authority_hash
            FROM public.opportunity_run_inputs binding
            JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
            JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
            JOIN LATERAL (
              SELECT assignment.canonical_sector_key
              FROM public.stock_sector_assignments_v3 assignment
              WHERE assignment.stock_id=score.stock_id
                AND assignment.recorded_at<=v_run.source_cutoff
                AND assignment.source_timestamp<=v_run.source_cutoff
                AND assignment.valid_from<=v_run.source_cutoff
                AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                AND assignment.status='active'
              ORDER BY assignment.recorded_at DESC,assignment.assignment_authority_id
              LIMIT 1
            ) sector ON sector.canonical_sector_key<>'unknown'
            JOIN LATERAL (
              SELECT session.session_id,session.taiwan_session_authority_hash
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>input.trading_date
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id LIMIT 1
            ) entry ON true
            WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
            GROUP BY sector.canonical_sector_key,entry.session_id
            ORDER BY sector.canonical_sector_key,entry.session_id
            OFFSET 0 LIMIT 1
          )
          SELECT jsonb_build_array(
            jsonb_build_array('canonicalSector',pair.canonical_sector_key),
            jsonb_build_array('corporateActionVersion','tw-corporate-action-v3.1'),
            jsonb_build_array('entrySession',pair.session_id),
            jsonb_build_array('entrySessionAuthorityHash',pair.entry_session_authority_hash),
            jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
            jsonb_build_array('rosterManifestHash',(
              SELECT manifest.manifest_hash
              FROM public.opportunity_run_manifest_inputs manifest_binding
              JOIN public.opportunity_manifests_v3 manifest
                ON manifest.manifest_id=manifest_binding.manifest_id
              WHERE manifest_binding.run_id=pair.input_run_id
                AND manifest_binding.input_role='instrument_roster'
                AND manifest_binding.ordinal=0 AND manifest.status='complete'
            )),
            jsonb_build_array('sourceCutoff',v_run.source_cutoff),
            jsonb_build_array('taxonomyAssignmentManifestHash',(
              SELECT manifest.manifest_hash
              FROM public.opportunity_run_manifest_inputs manifest_binding
              JOIN public.opportunity_manifests_v3 manifest
                ON manifest.manifest_id=manifest_binding.manifest_id
              WHERE manifest_binding.run_id=pair.input_run_id
                AND manifest_binding.input_role='taxonomy_assignment'
                AND manifest_binding.ordinal=0 AND manifest.status='complete'
            )),
            jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
              convert_to(regexp_replace(jsonb_build_array(
                'sector-benchmark-calendar-window-v3.4',
                coalesce((SELECT jsonb_agg(jsonb_build_array(
                  session.session_id,session.taiwan_session_authority_hash
                ) ORDER BY session.session_id)
                FROM (
                  SELECT session_id,taiwan_session_authority_hash
                  FROM public.opportunity_effective_taiwan_sessions_v3
                  WHERE session_id>=pair.session_id
                    AND canonical_cutoff<=v_run.source_cutoff
                  ORDER BY session_id LIMIT 250
                ) session),'[]'::jsonb)
              )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'))
          )
          FROM benchmark_pairs pair
        )
        WHEN v_kind='outcome_input' THEN jsonb_build_array(
          jsonb_build_array('comparisonContractKey',v_run.comparison_contract_key),
          jsonb_build_array('evaluationDatasetLockHash',v_run.evaluation_dataset_lock_hash),
          jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
          jsonb_build_array('runPurpose',v_run.run_purpose),
          jsonb_build_array('sourceCutoff',v_run.source_cutoff),
          jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
            convert_to(regexp_replace(jsonb_build_array(
              'outcome-calendar-window-v3.4',
              coalesce((SELECT jsonb_agg(jsonb_build_array(
                session_id,taiwan_session_authority_hash
              ) ORDER BY session_id)
              FROM (
                SELECT session_id,taiwan_session_authority_hash
                FROM public.opportunity_effective_taiwan_sessions_v3
                WHERE canonical_cutoff<=v_run.source_cutoff
                ORDER BY session_id DESC LIMIT 252
              ) sessions),'[]'::jsonb)
            )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'))
        )
        WHEN v_kind='evaluation_input' THEN jsonb_build_array(
          jsonb_build_array('backtestCount',(
            SELECT count(*) FROM (
              SELECT input.trading_date
              FROM public.opportunity_run_inputs binding
              JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
              WHERE binding.run_id=v_run.run_id AND binding.input_role='evaluation_enrich'
                AND input.run_purpose='backtest_daily_primary'
                AND EXISTS (
                  SELECT 1
                  FROM public.opportunity_run_inputs outcome_binding
                  JOIN public.opportunity_run_inputs outcome_source
                    ON outcome_source.run_id=outcome_binding.input_run_id
                    AND outcome_source.input_run_id=input.run_id
                    AND outcome_source.input_role='outcome_enrich'
                  WHERE outcome_binding.run_id=v_run.run_id
                    AND outcome_binding.input_role='evaluation_outcome'
                )
                AND (
                  SELECT count(*)
                  FROM public.opportunity_score_snapshots score
                  JOIN public.opportunity_outcomes outcome
                    ON outcome.score_snapshot_id=score.score_snapshot_id
                    AND outcome.maturity_horizon='session_20'
                  WHERE score.run_id=input.run_id
                )>=10
              ORDER BY input.trading_date DESC,input.run_id
              LIMIT 120
            ) qualifying_backtest
          )),
          jsonb_build_array('comparisonContractKey',v_run.comparison_contract_key),
          jsonb_build_array('evaluationCutoff',v_run.source_cutoff),
          jsonb_build_array('evaluationDatasetLockHash',v_run.evaluation_dataset_lock_hash),
          jsonb_build_array('liveCount',(
            SELECT count(*) FROM (
              SELECT input.trading_date
              FROM public.opportunity_run_inputs binding
              JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
              WHERE binding.run_id=v_run.run_id AND binding.input_role='evaluation_enrich'
                AND input.run_purpose='production_shadow_daily'
                AND EXISTS (
                  SELECT 1
                  FROM public.opportunity_run_inputs outcome_binding
                  JOIN public.opportunity_run_inputs outcome_source
                    ON outcome_source.run_id=outcome_binding.input_run_id
                    AND outcome_source.input_run_id=input.run_id
                    AND outcome_source.input_role='outcome_enrich'
                  WHERE outcome_binding.run_id=v_run.run_id
                    AND outcome_binding.input_role='evaluation_outcome'
                )
                AND (
                  SELECT count(*)
                  FROM public.opportunity_score_snapshots score
                  JOIN public.opportunity_outcomes outcome
                    ON outcome.score_snapshot_id=score.score_snapshot_id
                    AND outcome.maturity_horizon='session_20'
                  WHERE score.run_id=input.run_id
                )>=10
              ORDER BY (
                SELECT max(outcome.maturity_session)
                FROM public.opportunity_score_snapshots score
                JOIN public.opportunity_outcomes outcome
                  ON outcome.score_snapshot_id=score.score_snapshot_id
                  AND outcome.maturity_horizon='session_20'
                WHERE score.run_id=input.run_id
              ) DESC,input.trading_date DESC,input.run_id
              LIMIT 20
            ) qualifying_live
          )),
          jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
          jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
            convert_to(regexp_replace(jsonb_build_array(
              'evaluation-calendar-window-v3.4',
              coalesce((SELECT jsonb_agg(jsonb_build_array(
                session_id,taiwan_session_authority_hash
              ) ORDER BY session_id)
              FROM (
                SELECT session_id,taiwan_session_authority_hash
                FROM public.opportunity_effective_taiwan_sessions_v3
                WHERE canonical_cutoff<=v_run.source_cutoff
                ORDER BY session_id DESC LIMIT 252
              ) sessions),'[]'::jsonb)
            )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'))
        )
        ELSE NULL
      END
    );
    IF v_body->5 IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
  ELSE
    SELECT * INTO v_predecessor FROM public.opportunity_run_jobs_v3
    WHERE job_id=predecessor_job_id AND run_id=requested_run_id AND status='succeeded'
    FOR SHARE;
    SELECT * INTO v_predecessor_payload FROM public.opportunity_job_payloads_v3
    WHERE job_id=predecessor_job_id AND run_id=requested_run_id;
    IF v_predecessor.job_id IS NULL OR v_predecessor_payload.job_id IS NULL
      OR v_predecessor.output_hash IS NULL OR v_run.status IN ('failed','converged','success') THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    v_predecessor_hashes := jsonb_build_array(v_predecessor.output_hash);
    IF v_run.status='preparing' AND v_predecessor_payload.payload_kind='manifest_header' THEN
      v_body := v_predecessor_payload.payload_json->5;
      v_ordinal := (v_body->>0)::integer;
      v_kind := (v_body->>2)::public.opportunity_manifest_kind_v3;
      v_contract := v_body->>3;
      v_manifest_id := (v_body->>1)::uuid;
      v_stage := v_predecessor.stage;
      IF v_kind='source_dataset' THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':connector_roots:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'connector_roots',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='peer_authority' THEN
        IF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'selected_rows',0,1
          )
        ) THEN v_next_section:='selected_rows';
        ELSIF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
          )
        ) THEN v_next_section:='excluded_rows';
        ELSE v_next_section:=NULL;
        END IF;
        IF v_next_section IS NULL THEN
          v_payload_kind := 'manifest_root';
          v_shard := v_kind::text||':'||v_ordinal||':root';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
          );
        ELSE
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            v_next_section,0,0,NULL,NULL,NULL
          );
        END IF;
      ELSIF v_kind='candidate_financial' THEN
        IF EXISTS (
          SELECT 1
          FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'selected_facts',0,1
          )
        ) THEN
          v_next_section:='selected_facts';
        ELSIF EXISTS (
          SELECT 1
          FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'excluded_facts',0,1
          )
        ) THEN
          v_next_section:='excluded_facts';
        ELSE
          v_next_section:='conservation';
        END IF;
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          v_next_section,0,0,NULL,NULL,NULL
        );
      ELSIF v_kind IN ('bias_reference','technical_history_reference','reported_pe_reference') THEN
        SELECT candidate.section_key INTO v_next_section
        FROM (VALUES
          ('bias_reference'::public.opportunity_manifest_kind_v3,1,'current_rows'::public.opportunity_manifest_section_key_v3),
          ('bias_reference',2,'excluded_rows'),('bias_reference',3,'sector_rows'),
          ('bias_reference',4,'conservation'),
          ('technical_history_reference',1,'market_benchmark_rows'),
          ('technical_history_reference',2,'raw_adjusted_rows'),
          ('technical_history_reference',3,'history_rows'),
          ('technical_history_reference',4,'excluded_rows'),
          ('technical_history_reference',5,'conservation'),
          ('reported_pe_reference',1,'own_history_rows'),
          ('reported_pe_reference',2,'sector_current_rows'),
          ('reported_pe_reference',3,'excluded_rows'),
          ('reported_pe_reference',4,'sector_rows'),
          ('reported_pe_reference',5,'conservation')
        ) candidate(kind,section_ordinal,section_key)
        WHERE candidate.kind=v_kind AND EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,candidate.section_key,0,1
          )
        )
        ORDER BY candidate.section_ordinal LIMIT 1;
        IF v_next_section IS NULL THEN
          RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END IF;
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          v_next_section,0,0,NULL,NULL,NULL
        );
      ELSIF v_kind IN (
        'factor_scoring_reference','sector_valuation_reference','mover_price_reference',
        'market_reference'
      ) THEN
        IF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'included_rows',0,1
          )
        ) THEN v_next_section:='included_rows';
        ELSIF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
          )
        ) THEN v_next_section:='excluded_rows';
        ELSE v_next_section:='conservation';
        END IF;
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          v_next_section,0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='sector_scoring_reference' THEN
        SELECT candidate.section_key INTO v_next_section
        FROM (VALUES
          (1,'market_benchmark_rows'::public.opportunity_manifest_section_key_v3),
          (2,'sector_aggregate_rows'::public.opportunity_manifest_section_key_v3),
          (3,'sector_aggregate_exclusions'::public.opportunity_manifest_section_key_v3),
          (4,'aggregate_evidence_rows'::public.opportunity_manifest_section_key_v3),
          (5,'sector_excess_included_rows'::public.opportunity_manifest_section_key_v3),
          (6,'sector_excess_excluded_rows'::public.opportunity_manifest_section_key_v3),
          (7,'conservation'::public.opportunity_manifest_section_key_v3)
        ) candidate(section_ordinal,section_key)
        WHERE EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,candidate.section_key,0,1
          )
        )
        ORDER BY candidate.section_ordinal LIMIT 1;
        IF v_next_section IS NULL THEN
          v_payload_kind := 'manifest_root';
          v_shard := v_kind::text||':'||v_ordinal||':root';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
          );
        ELSE
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            v_next_section,0,0,NULL,NULL,NULL
          );
        END IF;
      ELSIF v_kind IN ('link_audit_sample','link_audit_resolution') THEN
        IF v_kind='link_audit_sample' THEN
          IF EXISTS (
            SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
              requested_run_id,v_manifest_id,v_kind,'strata',0,1
            )
          ) THEN v_next_section:='strata';
          ELSIF EXISTS (
            SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
              requested_run_id,v_manifest_id,v_kind,'samples',0,1
            )
          ) THEN v_next_section:='samples';
          ELSE v_next_section:=NULL;
          END IF;
        ELSE
          IF EXISTS (
            SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
              requested_run_id,v_manifest_id,v_kind,'resolved_rows',0,1
            )
          ) THEN v_next_section:='resolved_rows';
          ELSIF EXISTS (
            SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
              requested_run_id,v_manifest_id,v_kind,'unresolved_rows',0,1
            )
          ) THEN v_next_section:='unresolved_rows';
          ELSE v_next_section:=NULL;
          END IF;
        END IF;
        IF v_next_section IS NULL THEN
          v_payload_kind := 'manifest_root';
          v_shard := v_kind::text||':'||v_ordinal||':root';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
          );
        ELSE
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            v_next_section,0,0,NULL,NULL,NULL
          );
        END IF;
      ELSIF v_kind='evaluation_input' THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':attempt_roster:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'attempt_roster',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='sector_benchmark' AND EXISTS (
        SELECT 1
        FROM public.stock_sector_assignments_v3 assignment
        JOIN public.stock_instruments_v3 instrument ON instrument.stock_id=assignment.stock_id
        JOIN public.opportunity_price_observations_v3 observation
          ON observation.stock_id=assignment.stock_id
        WHERE assignment.canonical_sector_key=(
            SELECT (pair->>1)::public.canonical_sector_key_v3
            FROM jsonb_array_elements(v_body->5) pair
            WHERE pair->>0='canonicalSector'
          )
          AND assignment.recorded_at<=v_run.source_cutoff
          AND assignment.source_timestamp<=v_run.source_cutoff
          AND assignment.valid_from<=v_run.source_cutoff
          AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
          AND assignment.status='active'
          AND instrument.recorded_at<=v_run.source_cutoff
          AND instrument.source_timestamp<=v_run.source_cutoff
          AND instrument.valid_from<=v_run.source_cutoff
          AND (instrument.valid_to IS NULL OR v_run.source_cutoff<instrument.valid_to)
          AND instrument.instrument_type='common_stock'
          AND instrument.listing_status='active'
          AND observation.session_id=(
            SELECT (pair->>1)::date
            FROM jsonb_array_elements(v_body->5) pair
            WHERE pair->>0='entrySession'
          )
          AND observation.source_timestamp<=v_run.source_cutoff
          AND observation.collected_at<=v_run.source_cutoff
          AND observation.recorded_at<=v_run.source_cutoff
      ) THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':entry_rows:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'entry_rows',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='sector_benchmark' THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':session_conservation:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'session_conservation',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='outcome_input' AND EXISTS (
        SELECT 1
        FROM public.opportunity_run_inputs binding
        JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
        JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
        CROSS JOIN (VALUES (20),(60),(120),(250)) maturity(session_count)
        JOIN LATERAL (
          SELECT session.session_id
          FROM public.opportunity_effective_taiwan_sessions_v3 session
          WHERE session.session_id>input.trading_date
            AND session.canonical_cutoff<=v_run.source_cutoff
          ORDER BY session.session_id
          LIMIT 1
        ) entry_session ON true
        JOIN LATERAL (
          SELECT session.session_id
          FROM public.opportunity_effective_taiwan_sessions_v3 session
          WHERE session.session_id>=entry_session.session_id
            AND session.canonical_cutoff<=v_run.source_cutoff
          ORDER BY session.session_id
          OFFSET maturity.session_count-1
          LIMIT 1
        ) maturity_session ON true
        JOIN LATERAL (
          SELECT observation.source_ref
          FROM public.opportunity_price_observations_v3 observation
          WHERE observation.stock_id=score.stock_id
            AND observation.session_id=entry_session.session_id
            AND observation.source_timestamp<=v_run.source_cutoff
            AND observation.collected_at<=v_run.source_cutoff
            AND observation.recorded_at<=v_run.source_cutoff
          ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
            observation.recorded_at DESC,observation.observation_id
          LIMIT 1
        ) entry_price ON true
        JOIN LATERAL (
          SELECT observation.source_ref
          FROM public.opportunity_price_observations_v3 observation
          WHERE observation.stock_id=score.stock_id
            AND observation.session_id=maturity_session.session_id
            AND observation.source_timestamp<=v_run.source_cutoff
            AND observation.collected_at<=v_run.source_cutoff
            AND observation.recorded_at<=v_run.source_cutoff
          ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
            observation.recorded_at DESC,observation.observation_id
          LIMIT 1
        ) maturity_price ON true
        JOIN LATERAL (
          SELECT benchmark.manifest_id
          FROM public.stock_sector_assignments_v3 assignment
          JOIN public.opportunity_run_manifest_inputs benchmark_binding
            ON benchmark_binding.run_id=v_run.run_id
            AND benchmark_binding.input_role='sector_benchmark'
          JOIN public.opportunity_manifests_v3 benchmark
            ON benchmark.manifest_id=benchmark_binding.manifest_id
            AND benchmark.status='complete'
          WHERE assignment.stock_id=score.stock_id
            AND assignment.recorded_at<=v_run.source_cutoff
            AND assignment.source_timestamp<=v_run.source_cutoff
            AND assignment.valid_from<=v_run.source_cutoff
            AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
            AND assignment.status='active'
            AND EXISTS (
              SELECT 1 FROM jsonb_array_elements(benchmark.header_json) pair
              WHERE pair->>0='canonicalSector'
                AND pair->>1=assignment.canonical_sector_key::text
            )
            AND EXISTS (
              SELECT 1 FROM jsonb_array_elements(benchmark.header_json) pair
              WHERE pair->>0='entrySession'
                AND (pair->>1)::date=entry_session.session_id
            )
            AND EXISTS (
              SELECT 1 FROM public.opportunity_manifest_rows_v3 conservation
              WHERE conservation.manifest_id=benchmark.manifest_id
                AND conservation.section_key='session_conservation'
                AND conservation.payload_json->>0=maturity_session.session_id::text
                AND conservation.payload_json->>5='available'
            )
          ORDER BY benchmark_binding.ordinal
          LIMIT 1
        ) benchmark ON true
        WHERE binding.run_id=v_run.run_id
          AND binding.input_role='outcome_enrich'
          AND NOT EXISTS (
            SELECT 1 FROM public.opportunity_outcomes outcome
            WHERE outcome.score_snapshot_id=score.score_snapshot_id
          )
      ) THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':input_rows:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'input_rows',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='outcome_input' AND EXISTS (
        SELECT 1
        FROM public.opportunity_run_inputs binding
        JOIN public.opportunity_score_snapshots score ON score.run_id=binding.input_run_id
        WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
      ) THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':excluded_rows:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'excluded_rows',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind IN (
        'source_identity_allowlist','publisher_verification_allowlist','instrument_roster',
        'alias_authority','taxonomy_assignment','peer_reviewer_allowlist','source_eligible'
      ) AND EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_body->5) pair
        WHERE pair->>0 IN ('rowCount','eligibleCount') AND (pair->>1)::bigint>0
      ) THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':rows:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'rows',0,0,NULL,NULL,NULL
        );
      ELSE
        v_payload_kind := 'manifest_root';
        v_shard := v_kind::text||':'||v_ordinal||':root';
        v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff);
      END IF;
    ELSIF v_run.status='preparing' AND v_predecessor_payload.payload_kind='manifest_page' THEN
      v_body := v_predecessor_payload.payload_json->5;
      v_ordinal := (v_body->>0)::integer;
      v_kind := (v_body->>2)::public.opportunity_manifest_kind_v3;
      v_contract := v_body->>3;
      v_manifest_id := (v_body->>1)::uuid;
      v_stage := v_predecessor.stage;
      IF v_kind='source_dataset' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        SELECT CASE v_section
          WHEN 'connector_roots' THEN count(*)
          WHEN 'selected_revision_rows' THEN coalesce(sum(least(1000,m.row_count)),0)
          WHEN 'connector_conservation' THEN count(*)
          ELSE 0
        END INTO v_section_count
        FROM public.opportunity_run_manifest_inputs i
        JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
        WHERE i.run_id=requested_run_id AND i.input_role='source_eligible';
        IF (v_body->>7)::bigint+2000<v_section_count THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          v_next_section:=CASE v_section
            WHEN 'connector_roots' THEN CASE WHEN (
              SELECT coalesce(sum(least(1000,m.row_count)),0)
              FROM public.opportunity_run_manifest_inputs i
              JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
              WHERE i.run_id=requested_run_id AND i.input_role='source_eligible'
            )>0 THEN 'selected_revision_rows'::public.opportunity_manifest_section_key_v3
              ELSE 'connector_conservation'::public.opportunity_manifest_section_key_v3 END
            WHEN 'selected_revision_rows' THEN 'connector_conservation'::public.opportunity_manifest_section_key_v3
            ELSE NULL
          END;
          IF v_next_section IS NOT NULL THEN
            v_payload_kind := 'manifest_page';
            v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          ELSE
            v_payload_kind := 'manifest_root';
            v_shard := v_kind::text||':'||v_ordinal||':root';
            v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff);
          END IF;
        END IF;
      ELSIF v_kind IN (
        'peer_authority','factor_scoring_reference','sector_valuation_reference',
        'sector_scoring_reference','mover_price_reference','market_reference',
        'bias_reference','technical_history_reference','reported_pe_reference',
        'link_audit_sample','link_audit_resolution'
      ) THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        IF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,v_section,
            (v_body->>7)::integer+2000,1
          )
        ) THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          v_next_section:=CASE
            WHEN v_kind='peer_authority' AND v_section='selected_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='factor_scoring_reference' AND v_section='included_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='factor_scoring_reference'
              AND v_section IN ('included_rows','excluded_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='sector_valuation_reference' AND v_section='included_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='sector_valuation_reference'
              AND v_section IN ('included_rows','excluded_rows')
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'aggregate_rows',0,1
                )
              ) THEN 'aggregate_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='sector_valuation_reference'
              AND v_section IN ('included_rows','excluded_rows','aggregate_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='mover_price_reference' AND v_section='included_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='mover_price_reference'
              AND v_section IN ('included_rows','excluded_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='market_reference' AND v_section='included_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='market_reference'
              AND v_section IN ('included_rows','excluded_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='bias_reference' AND v_section='current_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1))
              THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='bias_reference' AND v_section IN ('current_rows','excluded_rows')
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'sector_rows',0,1))
              THEN 'sector_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='bias_reference' AND v_section IN ('current_rows','excluded_rows','sector_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section='market_benchmark_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'raw_adjusted_rows',0,1))
              THEN 'raw_adjusted_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section='market_benchmark_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1))
              THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section='market_benchmark_rows'
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section='raw_adjusted_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'history_rows',0,1))
              THEN 'history_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section IN ('raw_adjusted_rows','history_rows')
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1))
              THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section IN ('raw_adjusted_rows','history_rows','excluded_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='reported_pe_reference' AND v_section='own_history_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'sector_current_rows',0,1))
              THEN 'sector_current_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='reported_pe_reference' AND v_section IN ('own_history_rows','sector_current_rows')
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1))
              THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='reported_pe_reference' AND v_section IN ('own_history_rows','sector_current_rows','excluded_rows')
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'sector_rows',0,1))
              THEN 'sector_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='reported_pe_reference' AND v_section IN ('own_history_rows','sector_current_rows','excluded_rows','sector_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='link_audit_sample' AND v_section='strata'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'samples',0,1
                )
              ) THEN 'samples'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='link_audit_resolution' AND v_section='resolved_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'unresolved_rows',0,1
                )
              ) THEN 'unresolved_rows'::public.opportunity_manifest_section_key_v3
            ELSE NULL
          END;
          IF v_kind='sector_scoring_reference' THEN
            SELECT candidate.section_key INTO v_next_section
            FROM (VALUES
              (1,'market_benchmark_rows'::public.opportunity_manifest_section_key_v3),
              (2,'sector_aggregate_rows'::public.opportunity_manifest_section_key_v3),
              (3,'sector_aggregate_exclusions'::public.opportunity_manifest_section_key_v3),
              (4,'aggregate_evidence_rows'::public.opportunity_manifest_section_key_v3),
              (5,'sector_excess_included_rows'::public.opportunity_manifest_section_key_v3),
              (6,'sector_excess_excluded_rows'::public.opportunity_manifest_section_key_v3),
              (7,'conservation'::public.opportunity_manifest_section_key_v3)
            ) candidate(section_ordinal,section_key)
            WHERE candidate.section_ordinal>(
              SELECT current.section_ordinal FROM (VALUES
                (1,'market_benchmark_rows'::public.opportunity_manifest_section_key_v3),
                (2,'sector_aggregate_rows'::public.opportunity_manifest_section_key_v3),
                (3,'sector_aggregate_exclusions'::public.opportunity_manifest_section_key_v3),
                (4,'aggregate_evidence_rows'::public.opportunity_manifest_section_key_v3),
                (5,'sector_excess_included_rows'::public.opportunity_manifest_section_key_v3),
                (6,'sector_excess_excluded_rows'::public.opportunity_manifest_section_key_v3),
                (7,'conservation'::public.opportunity_manifest_section_key_v3)
              ) current(section_ordinal,section_key)
              WHERE current.section_key=v_section
            )
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,candidate.section_key,0,1
                )
              )
            ORDER BY candidate.section_ordinal LIMIT 1;
          END IF;
          IF v_next_section IS NULL THEN
            v_payload_kind := 'manifest_root';
            v_shard := v_kind::text||':'||v_ordinal||':root';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
            );
          ELSE
            v_payload_kind := 'manifest_page';
            v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          END IF;
        END IF;
      ELSIF v_kind='candidate_financial' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        IF EXISTS (
          SELECT 1
          FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,v_section,
            (v_body->>7)::integer+2000,1
          )
        ) THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          v_next_section:=CASE v_section
            WHEN 'selected_facts' THEN
              CASE WHEN EXISTS (
                SELECT 1
                FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_facts',0,1
                )
              ) THEN 'excluded_facts'::public.opportunity_manifest_section_key_v3
              ELSE 'conservation'::public.opportunity_manifest_section_key_v3 END
            WHEN 'excluded_facts' THEN 'conservation'::public.opportunity_manifest_section_key_v3
            ELSE NULL
          END;
          IF v_next_section IS NULL THEN
            v_payload_kind := 'manifest_root';
            v_shard := v_kind::text||':'||v_ordinal||':root';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
            );
          ELSE
            v_payload_kind := 'manifest_page';
            v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          END IF;
        END IF;
      ELSIF v_kind='sector_benchmark' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        SELECT CASE v_section
          WHEN 'entry_rows' THEN (
            SELECT count(*)
            FROM (
              SELECT DISTINCT instrument.stock_id
              FROM public.stock_instruments_v3 instrument
              JOIN public.stock_sector_assignments_v3 assignment
                ON assignment.stock_id=instrument.stock_id
              WHERE instrument.recorded_at<=v_run.source_cutoff
                AND instrument.source_timestamp<=v_run.source_cutoff
                AND instrument.valid_from<=v_run.source_cutoff
                AND (instrument.valid_to IS NULL OR v_run.source_cutoff<instrument.valid_to)
                AND instrument.instrument_type='common_stock'
                AND instrument.listing_status='active'
                AND assignment.recorded_at<=v_run.source_cutoff
                AND assignment.source_timestamp<=v_run.source_cutoff
                AND assignment.valid_from<=v_run.source_cutoff
                AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                AND assignment.status='active'
                AND assignment.canonical_sector_key=(
                  SELECT (pair->>1)::public.canonical_sector_key_v3
                  FROM public.opportunity_manifests_v3 manifest
                  CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                  WHERE manifest.manifest_id=v_manifest_id AND pair->>0='canonicalSector'
                )
                AND EXISTS (
                  SELECT 1
                  FROM public.opportunity_price_observations_v3 observation
                  WHERE observation.stock_id=instrument.stock_id
                    AND observation.session_id=(
                      SELECT (pair->>1)::date
                      FROM public.opportunity_manifests_v3 manifest
                      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                      WHERE manifest.manifest_id=v_manifest_id AND pair->>0='entrySession'
                    )
                    AND observation.source_timestamp<=v_run.source_cutoff
                    AND observation.collected_at<=v_run.source_cutoff
                    AND observation.recorded_at<=v_run.source_cutoff
                )
            ) entry_population
          )
          WHEN 'evaluation_rows' THEN (
            SELECT count(*)
            FROM public.opportunity_manifest_rows_v3 entry
            JOIN public.stock_instruments_v3 instrument ON instrument.symbol=entry.payload_json->>0
            JOIN public.opportunity_effective_taiwan_sessions_v3 session
              ON session.session_id>=(
                SELECT (pair->>1)::date
                FROM public.opportunity_manifests_v3 manifest
                CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                WHERE manifest.manifest_id=v_manifest_id AND pair->>0='entrySession'
              )
              AND session.canonical_cutoff<=v_run.source_cutoff
            WHERE entry.manifest_id=v_manifest_id AND entry.section_key='entry_rows'
              AND EXISTS (
                SELECT 1
                FROM public.opportunity_price_observations_v3 observation
                WHERE observation.stock_id=instrument.stock_id
                  AND observation.session_id=session.session_id
                  AND observation.source_timestamp<=v_run.source_cutoff
                  AND observation.collected_at<=v_run.source_cutoff
                  AND observation.recorded_at<=v_run.source_cutoff
              )
          )
          WHEN 'session_conservation' THEN (
            SELECT count(*)
            FROM (
              SELECT session.session_id
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>=(
                SELECT (pair->>1)::date
                FROM public.opportunity_manifests_v3 manifest
                CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                WHERE manifest.manifest_id=v_manifest_id AND pair->>0='entrySession'
              )
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id LIMIT 250
            ) bounded_sessions
          )
          ELSE 0
        END INTO v_section_count;
        IF (v_body->>7)::bigint+2000<v_section_count THEN
          v_payload_kind:='manifest_page';
          v_shard:=v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body:=jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          v_next_section:=CASE v_section
            WHEN 'entry_rows' THEN CASE WHEN EXISTS (
              SELECT 1 FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key='entry_rows'
            ) THEN 'evaluation_rows'::public.opportunity_manifest_section_key_v3
              ELSE 'session_conservation'::public.opportunity_manifest_section_key_v3 END
            WHEN 'evaluation_rows' THEN 'session_conservation'::public.opportunity_manifest_section_key_v3
            ELSE NULL
          END;
          IF v_next_section IS NULL THEN
            v_payload_kind:='manifest_root';
            v_shard:=v_kind::text||':'||v_ordinal||':root';
            v_body:=jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
            );
          ELSE
            v_payload_kind:='manifest_page';
            v_shard:=v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body:=jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          END IF;
        END IF;
      ELSIF v_kind='outcome_input' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        IF v_section='conservation' THEN
          SELECT 4*count(*) INTO v_section_count
          FROM public.opportunity_run_inputs binding
          WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich';
        ELSE
          WITH planned AS (
            SELECT score.score_snapshot_id,
              entry_price.source_ref AS entry_price_ref,
              maturity_price.source_ref AS maturity_price_ref,
              benchmark.manifest_id AS benchmark_manifest_id
            FROM public.opportunity_run_inputs binding
            JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
            JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
            CROSS JOIN (VALUES
              ('session_20'::public.opportunity_outcome_maturity_v3,20),
              ('session_60'::public.opportunity_outcome_maturity_v3,60),
              ('session_120'::public.opportunity_outcome_maturity_v3,120),
              ('session_250'::public.opportunity_outcome_maturity_v3,250)
            ) maturity(maturity_horizon,session_count)
            JOIN LATERAL (
              SELECT session.session_id
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>input.trading_date
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id LIMIT 1
            ) entry_session ON true
            JOIN LATERAL (
              SELECT session.session_id
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>=entry_session.session_id
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id
              OFFSET maturity.session_count-1 LIMIT 1
            ) maturity_session ON true
            LEFT JOIN LATERAL (
              SELECT observation.source_ref
              FROM public.opportunity_price_observations_v3 observation
              WHERE observation.stock_id=score.stock_id
                AND observation.session_id=entry_session.session_id
                AND observation.source_timestamp<=v_run.source_cutoff
                AND observation.collected_at<=v_run.source_cutoff
                AND observation.recorded_at<=v_run.source_cutoff
              ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
                observation.recorded_at DESC,observation.observation_id LIMIT 1
            ) entry_price ON true
            LEFT JOIN LATERAL (
              SELECT observation.source_ref
              FROM public.opportunity_price_observations_v3 observation
              WHERE observation.stock_id=score.stock_id
                AND observation.session_id=maturity_session.session_id
                AND observation.source_timestamp<=v_run.source_cutoff
                AND observation.collected_at<=v_run.source_cutoff
                AND observation.recorded_at<=v_run.source_cutoff
              ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
                observation.recorded_at DESC,observation.observation_id LIMIT 1
            ) maturity_price ON true
            LEFT JOIN LATERAL (
              SELECT manifest.manifest_id
              FROM public.stock_sector_assignments_v3 assignment
              JOIN public.opportunity_run_manifest_inputs benchmark_binding
                ON benchmark_binding.run_id=v_run.run_id
                AND benchmark_binding.input_role='sector_benchmark'
              JOIN public.opportunity_manifests_v3 manifest
                ON manifest.manifest_id=benchmark_binding.manifest_id
                AND manifest.status='complete'
              WHERE assignment.stock_id=score.stock_id
                AND assignment.recorded_at<=v_run.source_cutoff
                AND assignment.source_timestamp<=v_run.source_cutoff
                AND assignment.valid_from<=v_run.source_cutoff
                AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                AND assignment.status='active'
                AND EXISTS (
                  SELECT 1 FROM jsonb_array_elements(manifest.header_json) pair
                  WHERE pair->>0='canonicalSector'
                    AND pair->>1=assignment.canonical_sector_key::text
                )
                AND EXISTS (
                  SELECT 1 FROM jsonb_array_elements(manifest.header_json) pair
                  WHERE pair->>0='entrySession'
                    AND (pair->>1)::date=entry_session.session_id
                )
                AND EXISTS (
                  SELECT 1 FROM public.opportunity_manifest_rows_v3 conservation
                  WHERE conservation.manifest_id=manifest.manifest_id
                    AND conservation.section_key='session_conservation'
                    AND conservation.payload_json->>0=maturity_session.session_id::text
                    AND conservation.payload_json->>5='available'
                )
              ORDER BY benchmark_binding.ordinal LIMIT 1
            ) benchmark ON true
            WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
              AND NOT EXISTS (
                SELECT 1 FROM public.opportunity_outcomes outcome
                WHERE outcome.score_snapshot_id=score.score_snapshot_id
                  AND outcome.maturity_horizon=maturity.maturity_horizon
              )
          )
          SELECT CASE v_section
            WHEN 'input_rows' THEN count(*) FILTER (
              WHERE entry_price_ref IS NOT NULL AND maturity_price_ref IS NOT NULL
                AND benchmark_manifest_id IS NOT NULL
            )
            ELSE count(*) FILTER (
              WHERE entry_price_ref IS NULL OR maturity_price_ref IS NULL
                OR benchmark_manifest_id IS NULL
            )
          END INTO v_section_count
          FROM planned;
        END IF;
        IF (v_body->>7)::bigint+2000<v_section_count THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSIF v_section='input_rows' AND (
          SELECT count(*) FROM public.opportunity_run_inputs binding
          JOIN public.opportunity_score_snapshots score ON score.run_id=binding.input_run_id
          WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
        )>v_section_count THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':excluded_rows:0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            'excluded_rows',0,0,NULL,NULL,NULL
          );
        ELSIF v_section IN ('input_rows','excluded_rows') AND EXISTS (
          SELECT 1 FROM public.opportunity_run_inputs binding
          WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
        ) THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':conservation:0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            'conservation',0,0,NULL,NULL,NULL
          );
        ELSE
          v_payload_kind := 'manifest_root';
          v_shard := v_kind::text||':'||v_ordinal||':root';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
          );
        END IF;
      ELSIF v_kind='evaluation_input' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        SELECT CASE v_section
          WHEN 'attempt_roster' THEN 252
          WHEN 'backtest_rows' THEN coalesce((
            SELECT (pair->>1)::bigint
            FROM public.opportunity_manifests_v3 manifest,
              LATERAL jsonb_array_elements(manifest.header_json) pair
            WHERE manifest.manifest_id=v_manifest_id AND pair->>0='backtestCount'
          ),0)
          WHEN 'live_rows' THEN coalesce((
            SELECT (pair->>1)::bigint
            FROM public.opportunity_manifests_v3 manifest,
              LATERAL jsonb_array_elements(manifest.header_json) pair
            WHERE manifest.manifest_id=v_manifest_id AND pair->>0='liveCount'
          ),0)
          WHEN 'cohort_rows' THEN (
            SELECT count(*)
            FROM public.opportunity_manifest_rows_v3 selected_date
            JOIN public.opportunity_score_snapshots score
              ON score.run_id=(selected_date.payload_json->>2)::uuid
              AND score.horizon='swing_20_60d'
            JOIN public.opportunity_outcomes outcome
              ON outcome.score_snapshot_id=score.score_snapshot_id
              AND outcome.maturity_horizon='session_20'
            WHERE selected_date.manifest_id=v_manifest_id
              AND selected_date.section_key IN ('backtest_rows','live_rows')
          )
          WHEN 'conservation' THEN (
            SELECT count(*)
            FROM public.opportunity_manifest_rows_v3 selected_date
            WHERE selected_date.manifest_id=v_manifest_id
              AND selected_date.section_key IN ('backtest_rows','live_rows')
          )
          ELSE 0
        END INTO v_section_count;
        IF (v_body->>7)::bigint+2000<v_section_count THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          IF v_section='attempt_roster' AND EXISTS (
            SELECT 1 FROM jsonb_array_elements(
              (SELECT header_json FROM public.opportunity_manifests_v3
                WHERE manifest_id=v_manifest_id)
            ) pair
            WHERE pair->>0='backtestCount' AND (pair->>1)::integer>0
          ) THEN
            v_next_section:='backtest_rows';
          ELSIF v_section IN ('attempt_roster','backtest_rows') AND EXISTS (
            SELECT 1 FROM jsonb_array_elements(
              (SELECT header_json FROM public.opportunity_manifests_v3
                WHERE manifest_id=v_manifest_id)
            ) pair
            WHERE pair->>0='liveCount' AND (pair->>1)::integer>0
          ) THEN
            v_next_section:='live_rows';
          ELSIF v_section IN ('backtest_rows','live_rows') THEN
            v_next_section:='cohort_rows';
          ELSIF v_section='cohort_rows' THEN
            v_next_section:='conservation';
          ELSE
            v_next_section:=NULL;
          END IF;
          IF v_next_section IS NULL THEN
            v_payload_kind := 'manifest_root';
            v_shard := v_kind::text||':'||v_ordinal||':root';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
            );
          ELSE
            v_payload_kind := 'manifest_page';
            v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          END IF;
        END IF;
      ELSIF v_kind IN (
        'source_identity_allowlist','publisher_verification_allowlist','instrument_roster',
        'alias_authority','taxonomy_assignment','peer_reviewer_allowlist','source_eligible'
      ) AND (
        SELECT (pair->>1)::bigint
        FROM public.opportunity_manifests_v3 m,
          LATERAL jsonb_array_elements(m.header_json) pair
        WHERE m.manifest_id=v_manifest_id AND pair->>0 IN ('rowCount','eligibleCount')
      ) > (v_body->>7)::bigint + 2000 THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':rows:'||((v_body->>6)::integer+1);
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'rows',(v_body->>6)::integer+1,(v_body->>7)::integer+2000,
          (SELECT page_id FROM public.opportunity_manifest_pages_v3
            WHERE manifest_id=v_manifest_id AND section_key='rows'
              AND page_ordinal=(v_body->>6)::integer),
          (SELECT page_hash FROM public.opportunity_manifest_pages_v3
            WHERE manifest_id=v_manifest_id AND section_key='rows'
              AND page_ordinal=(v_body->>6)::integer),
          (SELECT identity_key FROM public.opportunity_manifest_rows_v3
            WHERE manifest_id=v_manifest_id AND section_key='rows'
            ORDER BY row_ordinal DESC LIMIT 1)
        );
      ELSE
        v_payload_kind := 'manifest_root';
        v_shard := v_kind::text||':'||v_ordinal||':root';
        v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff);
      END IF;
    ELSIF v_run.status='preparing' AND v_predecessor_payload.payload_kind='manifest_root' THEN
      v_kind := (v_predecessor_payload.payload_json->5->>2)::public.opportunity_manifest_kind_v3;
      v_ordinal := (v_predecessor_payload.payload_json->5->>0)::integer;
      v_next_kind := NULL;
      IF v_run.mode='source_scan' THEN
        CASE v_kind
          WHEN 'source_identity_allowlist' THEN v_next_kind := 'publisher_verification_allowlist'; v_contract := 'source-publisher-allowlist-v3.0';
          WHEN 'publisher_verification_allowlist' THEN v_next_kind := 'instrument_roster'; v_contract := 'tw-instrument-roster-v3.0';
          WHEN 'instrument_roster' THEN v_next_kind := 'alias_authority'; v_contract := 'alias-normalization-v3.0';
          WHEN 'alias_authority' THEN v_next_kind := 'taxonomy_assignment'; v_contract := 'tw-sector-taxonomy-v3.0';
          WHEN 'taxonomy_assignment' THEN v_next_kind := 'source_eligible'; v_contract := 'source-adapter-v3.3';
          WHEN 'source_eligible' THEN
            IF v_ordinal < 10 THEN
              v_next_kind := 'source_eligible'; v_next_ordinal := v_ordinal + 1; v_contract := 'source-adapter-v3.3';
            ELSE
              v_next_kind := 'source_dataset'; v_contract := 'source-dataset-v3.3';
            END IF;
          WHEN 'source_dataset' THEN v_next_kind := NULL;
          ELSE RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END CASE;
      ELSIF v_run.mode='enrich_rank' THEN
        CASE v_kind
          WHEN 'peer_reviewer_allowlist' THEN v_next_kind := 'peer_authority'; v_contract := 'peer-authority-v3.0';
          WHEN 'peer_authority' THEN v_next_kind := 'sector_valuation_reference'; v_contract := 'opportunity-financial-inputs-v3.0';
          WHEN 'sector_valuation_reference' THEN v_next_kind := 'candidate_financial'; v_contract := 'candidate-financial-v3.0';
          WHEN 'candidate_financial' THEN v_next_kind := 'factor_scoring_reference'; v_contract := 'opportunity-features-v3.1';
          WHEN 'factor_scoring_reference' THEN v_next_kind := 'sector_scoring_reference'; v_contract := 'sector-reference-v3.1';
          WHEN 'sector_scoring_reference' THEN
            v_next_kind := 'bias_reference'; v_contract := 'opportunity-factor-correctness-v3.11.6';
          WHEN 'bias_reference' THEN
            v_next_kind := 'technical_history_reference'; v_contract := 'opportunity-factor-correctness-v3.11.6';
          WHEN 'technical_history_reference' THEN
            v_next_kind := 'reported_pe_reference'; v_contract := 'opportunity-financial-inputs-v3.3';
          WHEN 'reported_pe_reference' THEN
            IF NOT EXISTS (
              SELECT 1 FROM public.opportunity_effective_taiwan_sessions_v3 s
              WHERE s.canonical_cutoff<=v_run.source_cutoff
            ) THEN
              RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
            END IF;
            v_next_kind := 'mover_price_reference'; v_contract := 'mover-audit-price-v3.3';
          WHEN 'mover_price_reference' THEN
            IF EXISTS (
              SELECT 1 FROM public.opportunity_effective_taiwan_sessions_v3 s
              WHERE s.canonical_cutoff<=v_run.source_cutoff
              ORDER BY s.session_id DESC OFFSET v_ordinal+1 LIMIT 1
            ) AND v_ordinal<4 THEN
              v_next_kind := 'mover_price_reference'; v_next_ordinal:=v_ordinal+1;
              v_contract := 'mover-audit-price-v3.3';
            ELSE
              v_next_kind := 'market_reference'; v_contract := 'market-context-v3.6';
            END IF;
          WHEN 'market_reference' THEN v_next_kind := NULL;
          ELSE RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END CASE;
      ELSIF v_run.mode='label_outcomes' THEN
        IF v_kind='sector_benchmark' THEN
          IF EXISTS (
            SELECT 1
            FROM (
              SELECT DISTINCT sector.canonical_sector_key,entry.session_id
              FROM public.opportunity_run_inputs binding
              JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
              JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
              JOIN LATERAL (
                SELECT assignment.canonical_sector_key
                FROM public.stock_sector_assignments_v3 assignment
                WHERE assignment.stock_id=score.stock_id
                  AND assignment.recorded_at<=v_run.source_cutoff
                  AND assignment.source_timestamp<=v_run.source_cutoff
                  AND assignment.valid_from<=v_run.source_cutoff
                  AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                  AND assignment.status='active'
                ORDER BY assignment.recorded_at DESC,assignment.assignment_authority_id
                LIMIT 1
              ) sector ON sector.canonical_sector_key<>'unknown'
              JOIN LATERAL (
                SELECT session.session_id
                FROM public.opportunity_effective_taiwan_sessions_v3 session
                WHERE session.session_id>input.trading_date
                  AND session.canonical_cutoff<=v_run.source_cutoff
                ORDER BY session.session_id LIMIT 1
              ) entry ON true
              WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
              ORDER BY sector.canonical_sector_key,entry.session_id
              OFFSET v_ordinal+1 LIMIT 1
            ) next_pair
          ) THEN
            v_next_kind:='sector_benchmark';
            v_next_ordinal:=v_ordinal+1;
            v_contract:='sector-benchmark-v3.1';
          ELSE
            v_next_kind:='outcome_input';
            v_next_ordinal:=0;
            v_contract:='source-led-eval-v3.7';
          END IF;
        ELSIF v_kind<>'outcome_input' THEN
          RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END IF;
      ELSIF v_run.mode='shadow_evaluate' THEN
        CASE v_kind
          WHEN 'evaluation_input' THEN v_next_kind := 'link_audit_sample'; v_contract := 'source-led-eval-v3.7';
          WHEN 'link_audit_sample' THEN v_next_kind := 'link_audit_resolution'; v_contract := 'source-led-eval-v3.7';
          WHEN 'link_audit_resolution' THEN v_next_kind := NULL;
          ELSE RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END CASE;
      END IF;
      IF v_next_kind IS NOT NULL THEN
        v_kind := v_next_kind;
        v_ordinal := v_next_ordinal;
        IF v_kind='publisher_verification_allowlist' THEN
          SELECT count(*) INTO v_registered_count FROM (
            SELECT stream_key_hash
            FROM public.opportunity_authority_stream_registry_v3
            WHERE family='publisher_verification'
            ORDER BY stream_key_hash,stream_key_canonical LIMIT 10001
          ) bounded_registry;
          IF v_registered_count>10000 OR EXISTS (
            SELECT 1
            FROM public.opportunity_authority_stream_registry_v3 registry
            CROSS JOIN LATERAL (
              SELECT count(*) retained_count FROM (
                SELECT authority_id
                FROM public.publisher_verification_authorities_v3 authority
                WHERE authority.publisher_identity_id=(
                  convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
                )::uuid
                ORDER BY authority.recorded_at DESC,authority.authority_id LIMIT 65
              ) bounded
            ) stream
            WHERE registry.family='publisher_verification' AND stream.retained_count>64
          ) THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
          END IF;
          v_selected_count := public.opportunity_authority_selected_stream_count_v3_internal(
            'publisher_verification',v_run.source_cutoff
          );
          IF v_selected_count>10000 THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
          END IF;
        ELSIF v_kind='instrument_roster' THEN
          SELECT count(*) INTO v_registered_count FROM (
            SELECT stream_key_hash
            FROM public.opportunity_authority_stream_registry_v3
            WHERE family='instrument_roster'
            ORDER BY stream_key_hash,stream_key_canonical LIMIT 20001
          ) bounded_registry;
          IF v_registered_count>20000 OR EXISTS (
            SELECT 1
            FROM public.opportunity_authority_stream_registry_v3 registry
            CROSS JOIN LATERAL (
              SELECT count(*) retained_count FROM (
                SELECT instrument_authority_id FROM public.stock_instruments_v3 authority
                WHERE authority.stock_id=(
                  convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
                )::uuid
                ORDER BY authority.recorded_at DESC,authority.instrument_authority_id LIMIT 65
              ) bounded
            ) stream
            WHERE registry.family='instrument_roster' AND stream.retained_count>64
          ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='roster_volume_exceeded'; END IF;
        ELSIF v_kind='alias_authority' THEN
          SELECT count(*) INTO v_registered_count FROM (
            SELECT stream_key_hash
            FROM public.opportunity_authority_stream_registry_v3
            WHERE family='stock_alias'
            ORDER BY stream_key_hash,stream_key_canonical LIMIT 100001
          ) bounded_registry;
          IF v_registered_count>100000 OR EXISTS (
            SELECT 1
            FROM public.opportunity_authority_stream_registry_v3 registry
            CROSS JOIN LATERAL (
              SELECT count(*) retained_count FROM (
                SELECT alias_authority_id FROM public.stock_aliases_v3 authority
                WHERE authority.stock_id=(
                    convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
                  )::uuid
                  AND authority.normalized_alias=
                    convert_from(registry.stream_key_canonical,'utf8')::jsonb->>2
                  AND authority.source=(
                    convert_from(registry.stream_key_canonical,'utf8')::jsonb->>3
                  )::public.alias_source_v3
                ORDER BY authority.recorded_at DESC,authority.alias_authority_id LIMIT 65
              ) bounded
            ) stream
            WHERE registry.family='stock_alias' AND stream.retained_count>64
          ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow'; END IF;
        ELSIF v_kind='taxonomy_assignment' THEN
          SELECT count(*) INTO v_registered_count FROM (
            SELECT stream_key_hash
            FROM public.opportunity_authority_stream_registry_v3
            WHERE family='sector_assignment'
            ORDER BY stream_key_hash,stream_key_canonical LIMIT 20001
          ) bounded_registry;
          IF v_registered_count>20000 OR EXISTS (
            SELECT 1
            FROM public.opportunity_authority_stream_registry_v3 registry
            CROSS JOIN LATERAL (
              SELECT count(*) retained_count FROM (
                SELECT assignment_authority_id FROM public.stock_sector_assignments_v3 authority
                WHERE authority.stock_id=(
                    convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
                  )::uuid
                  AND authority.market=(
                    convert_from(registry.stream_key_canonical,'utf8')::jsonb->>2
                  )::public.tw_market_v3
                ORDER BY authority.recorded_at DESC,authority.assignment_authority_id LIMIT 65
              ) bounded
            ) stream
            WHERE registry.family='sector_assignment' AND stream.retained_count>64
          ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='roster_volume_exceeded'; END IF;
        ELSIF v_kind='peer_authority' THEN
          SELECT count(*) INTO v_registered_count FROM (
            SELECT stream_key_hash
            FROM public.opportunity_authority_stream_registry_v3
            WHERE family='peer_relationship'
            ORDER BY stream_key_hash,stream_key_canonical LIMIT 100001
          ) bounded_registry;
          IF v_registered_count>100000 OR EXISTS (
            SELECT 1
            FROM public.opportunity_authority_stream_registry_v3 registry
            CROSS JOIN LATERAL (
              SELECT count(*) retained_count FROM (
                SELECT relationship_authority_id
                FROM public.stock_peer_relationships_v3 authority
                WHERE authority.supplier_stock_id=(
                    convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
                  )::uuid
                  AND authority.customer_stock_id=(
                    convert_from(registry.stream_key_canonical,'utf8')::jsonb->>2
                  )::uuid
                ORDER BY authority.recorded_at DESC,authority.relationship_authority_id LIMIT 65
              ) bounded
            ) stream
            WHERE registry.family='peer_relationship' AND stream.retained_count>64
          ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow'; END IF;
          v_selected_count := public.opportunity_authority_selected_stream_count_v3_internal(
            'peer_relationship',v_run.source_cutoff
          );
          IF v_selected_count>100000 THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
          END IF;
        END IF;
        v_stage := CASE WHEN v_kind IN (
          'source_identity_allowlist','publisher_verification_allowlist','instrument_roster','alias_authority',
          'taxonomy_assignment','peer_reviewer_allowlist','peer_authority'
        ) THEN 'authority_manifest' ELSE 'input_manifest_pages' END;
        v_payload_kind := 'manifest_header';
        v_shard := v_kind::text||':'||v_ordinal||':header';
        v_input_text := format('["%s","%s",%s,"%s"]',requested_run_id,v_kind,v_ordinal,v_contract);
        v_bytes := substring(extensions.digest(
          decode(replace('51689af8-f3fe-5d1e-a18f-c667ddee224a','-',''),'hex')
            || convert_to(v_input_text,'utf8'),'sha1') FROM 1 FOR 16);
        v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
        v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
        v_hex := encode(v_bytes,'hex');
        v_manifest_id := (substr(v_hex,1,8)||'-'||substr(v_hex,9,4)||'-'||substr(v_hex,13,4)||'-'
          ||substr(v_hex,17,4)||'-'||substr(v_hex,21,12))::uuid;
        IF v_kind='sector_benchmark' THEN
          WITH benchmark_pairs AS (
            SELECT sector.canonical_sector_key,entry.session_id,
              min(input.run_id::text)::uuid AS input_run_id,
              min(entry.taiwan_session_authority_hash) AS entry_session_authority_hash
            FROM public.opportunity_run_inputs binding
            JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
            JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
            JOIN LATERAL (
              SELECT assignment.canonical_sector_key
              FROM public.stock_sector_assignments_v3 assignment
              WHERE assignment.stock_id=score.stock_id
                AND assignment.recorded_at<=v_run.source_cutoff
                AND assignment.source_timestamp<=v_run.source_cutoff
                AND assignment.valid_from<=v_run.source_cutoff
                AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                AND assignment.status='active'
              ORDER BY assignment.recorded_at DESC,assignment.assignment_authority_id
              LIMIT 1
            ) sector ON sector.canonical_sector_key<>'unknown'
            JOIN LATERAL (
              SELECT session.session_id,session.taiwan_session_authority_hash
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>input.trading_date
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id LIMIT 1
            ) entry ON true
            WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
            GROUP BY sector.canonical_sector_key,entry.session_id
            ORDER BY sector.canonical_sector_key,entry.session_id
            OFFSET v_ordinal LIMIT 1
          )
          SELECT pair.canonical_sector_key,pair.session_id,
            pair.entry_session_authority_hash,pair.input_run_id
          INTO STRICT v_canonical_sector,v_entry_session,v_entry_session_hash,
            v_benchmark_input_run_id
          FROM benchmark_pairs pair;
          SELECT manifest.manifest_hash INTO STRICT v_roster_manifest_hash
          FROM public.opportunity_run_manifest_inputs binding
          JOIN public.opportunity_manifests_v3 manifest ON manifest.manifest_id=binding.manifest_id
          WHERE binding.run_id=v_benchmark_input_run_id
            AND binding.input_role='instrument_roster' AND binding.ordinal=0
            AND manifest.status='complete';
          SELECT manifest.manifest_hash INTO STRICT v_taxonomy_manifest_hash
          FROM public.opportunity_run_manifest_inputs binding
          JOIN public.opportunity_manifests_v3 manifest ON manifest.manifest_id=binding.manifest_id
          WHERE binding.run_id=v_benchmark_input_run_id
            AND binding.input_role='taxonomy_assignment' AND binding.ordinal=0
            AND manifest.status='complete';
          v_body:=jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('canonicalSector',v_canonical_sector),
              jsonb_build_array('corporateActionVersion','tw-corporate-action-v3.1'),
              jsonb_build_array('entrySession',v_entry_session),
              jsonb_build_array('entrySessionAuthorityHash',v_entry_session_hash),
              jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
              jsonb_build_array('rosterManifestHash',v_roster_manifest_hash),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('taxonomyAssignmentManifestHash',v_taxonomy_manifest_hash),
              jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
                convert_to(regexp_replace(jsonb_build_array(
                  'sector-benchmark-calendar-window-v3.4',
                  coalesce((SELECT jsonb_agg(jsonb_build_array(
                    session.session_id,session.taiwan_session_authority_hash
                  ) ORDER BY session.session_id)
                  FROM (
                    SELECT session_id,taiwan_session_authority_hash
                    FROM public.opportunity_effective_taiwan_sessions_v3
                    WHERE session_id>=v_entry_session
                      AND canonical_cutoff<=v_run.source_cutoff
                    ORDER BY session_id LIMIT 250
                  ) session),'[]'::jsonb)
                )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'))
            ));
        ELSIF v_kind='source_eligible' THEN
          v_source_key := (ARRAY[
            'bulltalk','earnings_call','instagram','investanchors','mops_material_event','podcast',
            'ptt','public_broker_research','telegram','threads','youtube'
          ]::public.source_key_v3[])[v_ordinal+1];
          SELECT count(*) INTO v_registered_count
          FROM (
            SELECT registry.revision_family_key
            FROM public.source_revision_family_registry_v3 registry
            WHERE registry.source_key=v_source_key
            ORDER BY registry.revision_family_key
            LIMIT 1000001
          ) bounded_registry;
          IF v_registered_count>1000000 THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
          END IF;
          IF EXISTS (
            SELECT 1
            FROM (
              SELECT registry.revision_family_key
              FROM public.source_revision_family_registry_v3 registry
              WHERE registry.source_key=v_source_key
              ORDER BY registry.revision_family_key
              LIMIT 1000001
            ) bounded_registry
            CROSS JOIN LATERAL (
              SELECT revision.revision_id
              FROM public.source_document_revisions_v3 revision
              WHERE revision.source_key=v_source_key
                AND revision.revision_family_key=bounded_registry.revision_family_key
              ORDER BY revision.recorded_at DESC,revision.revision_id
              OFFSET 64 LIMIT 1
            ) overflow_revision
          ) THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
          END IF;
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('eligibleCount',(
                WITH bounded_registry AS (
                  SELECT registry.revision_family_key
                  FROM public.source_revision_family_registry_v3 registry
                  WHERE registry.source_key=v_source_key
                  ORDER BY registry.revision_family_key
                  LIMIT 1000001
                )
                SELECT count(*) FROM (
                  SELECT selected.* FROM (
                    SELECT d.*,row_number() OVER (
                      PARTITION BY d.revision_family_key
                      ORDER BY d.recorded_at DESC,d.revision_id
                    ) AS revision_rank
                    FROM bounded_registry registry
                    CROSS JOIN LATERAL (
                      SELECT revision.*
                      FROM public.source_document_revisions_v3 revision
                      WHERE revision.source_key=v_source_key
                        AND revision.revision_family_key=registry.revision_family_key
                      ORDER BY revision.recorded_at DESC,revision.revision_id
                      LIMIT 65
                    ) d
                    WHERE d.recorded_at<=v_run.source_cutoff
                      AND d.collected_at<=v_run.source_cutoff
                      AND (d.published_at IS NULL OR d.published_at<=v_run.source_cutoff)
                  ) selected WHERE selected.revision_rank=1
                ) eligible
              )),
              jsonb_build_array('registeredFamilyCount',(
                SELECT v_registered_count
              )),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('sourceKey',v_source_key)
            ));
        ELSIF v_kind='source_dataset' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('aliasManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='alias_authority' AND ordinal=0))),
              jsonb_build_array('instrumentRosterManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='instrument_roster' AND ordinal=0))),
              jsonb_build_array('publisherVerificationAllowlistManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='publisher_verification_allowlist' AND ordinal=0))),
              jsonb_build_array('publisherVerificationPolicyHash','d85307ccc475b54460d5d9bb415cdf4b8574bf796bde38b7fdf66543721a99ff'),
              jsonb_build_array('sourceAdapterRegistryHash','d663b2a49538c7eec6f5c91a4100d6e8a0250106c970e077a91db0ce8bd56131'),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('sourceFunnelPolicyHash','ee5acd1cdde88fff9efc3b18d360624e9e7768d85f7c232b200df560205556ef'),
              jsonb_build_array('sourceIdentityAllowlistManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='source_identity_allowlist' AND ordinal=0))),
              jsonb_build_array('taxonomyAssignmentManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='taxonomy_assignment' AND ordinal=0))),
              jsonb_build_array('taxonomyMapHash','83f06426b8dae88f83d0610600000e529b6ad09249cee411c7ea2e89dab9a862')
            ));
        ELSIF v_kind='mover_price_reference' THEN
          SELECT s.session_id,s.taiwan_session_authority_hash INTO STRICT
            v_audited_session,v_audited_session_hash
          FROM public.opportunity_effective_taiwan_sessions_v3 s
          WHERE s.canonical_cutoff<=v_run.source_cutoff
          ORDER BY s.session_id DESC OFFSET v_ordinal LIMIT 1;
          SELECT s.session_id,s.taiwan_session_authority_hash
          INTO v_previous_session,v_previous_session_hash
          FROM public.opportunity_effective_taiwan_sessions_v3 s
          WHERE s.session_id<v_audited_session
          ORDER BY s.session_id DESC LIMIT 1;
          IF v_previous_session_hash IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
          END IF;
          SELECT encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
            'recent-session-plan-v3.4',
            coalesce(jsonb_agg(jsonb_build_array(s.session_id,s.taiwan_session_authority_hash)
              ORDER BY s.session_id DESC),'[]'::jsonb)
          )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex')
          INTO v_recent_session_plan_hash
          FROM (
            SELECT session_id,taiwan_session_authority_hash
            FROM public.opportunity_effective_taiwan_sessions_v3
            WHERE canonical_cutoff<=v_run.source_cutoff
            ORDER BY session_id DESC LIMIT 6
          ) s;
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('auditedSession',v_audited_session),
              jsonb_build_array('auditedSessionAuthorityHash',v_audited_session_hash),
              jsonb_build_array('corporateActionVersion','corporate-action-v3.0'),
              jsonb_build_array('instrumentRosterManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='instrument_roster' AND ordinal=0))),
              jsonb_build_array('previousSession',v_previous_session),
              jsonb_build_array('previousSessionAuthorityHash',v_previous_session_hash),
              jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
              jsonb_build_array('recentSessionPlanHash',v_recent_session_plan_hash)
              ,jsonb_build_array('rosterCount',(SELECT count(*)
                FROM public.opportunity_run_manifest_inputs input
                JOIN public.opportunity_manifest_rows_v3 row
                  ON row.manifest_id=input.manifest_id
                  AND row.section_key='rows'
                WHERE input.run_id=requested_run_id
                  AND input.input_role='instrument_roster'
                  AND input.ordinal=0
                  AND row.terminal_code='effective_active'
                  AND row.payload_json->>4='common_stock'))
              ,jsonb_build_array('sourceCutoff',v_run.source_cutoff)
            ));
        ELSIF v_kind='market_reference' THEN
          IF v_run.selected_mover_audit_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
          END IF;
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('moverAuditId',v_run.selected_mover_audit_id),
              jsonb_build_array('moverPriceReferenceManifestHash',(SELECT manifest_hash
