              jsonb_build_array('tradingCalendarWindowHash',(SELECT recent_session_plan_hash
                FROM public.opportunity_mover_audits_v3
                WHERE audit_id=v_run.selected_mover_audit_id))
            ));
        ELSIF v_kind='publisher_verification_allowlist' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
