              jsonb_build_array('rosterManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='instrument_roster' AND ordinal=0))),
              jsonb_build_array('scannedRowCount',(
                public.opportunity_peer_authority_header_counts_v3_internal(
                  requested_run_id,v_run.source_cutoff
                )->>'scannedRowCount')::bigint),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff)
            ));
        ELSIF v_kind='sector_valuation_reference' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('financialContractVersion','opportunity-financial-inputs-v3.0'),
              jsonb_build_array('methodVersion','sector-valuation-method-v3.0'),
              jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
              jsonb_build_array('rosterManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='instrument_roster' AND ordinal=0))),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('taxonomyAssignmentManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='taxonomy_assignment' AND ordinal=0))),
              jsonb_build_array('taxonomyMapHash','83f06426b8dae88f83d0610600000e529b6ad09249cee411c7ea2e89dab9a862')
            ));
        ELSIF v_kind='candidate_financial' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('financialContractVersion','opportunity-financial-inputs-v3.0'),
              jsonb_build_array('orderedSymbols',coalesce((
                SELECT jsonb_agg(plan.symbol ORDER BY plan.candidate_ordinal)
                FROM public.opportunity_candidate_plan_v3_internal(
                  requested_run_id,'shallow'
                ) plan
                WHERE plan.candidate_ordinal<20
              ),'[]'::jsonb)),
              jsonb_build_array('sectorValuationReferenceManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='sector_valuation_reference' AND ordinal=0))),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff)
            ));
        ELSIF v_kind='factor_scoring_reference' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('coverageDecisions','[]'::jsonb),
              jsonb_build_array('featureVersion','opportunity-features-v3.1'),
              jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
              jsonb_build_array('providerFieldAllowlistHash','fe78e0f8c5b0846f822f72c6b2356cac35ed5c00dd0bcd06f9a75b7c5b21d3f7'),
              jsonb_build_array('rosterManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='instrument_roster' AND ordinal=0))),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('taxonomyAssignmentManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='taxonomy_assignment' AND ordinal=0))),
              jsonb_build_array('taxonomyMapHash','83f06426b8dae88f83d0610600000e529b6ad09249cee411c7ea2e89dab9a862'),
              jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
                convert_to('factor-calendar-window-v3.4','utf8'),'sha256'),'hex'))
            ));
        ELSIF v_kind='sector_scoring_reference' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('corporateActionVersion','corporate-action-v3.0'),
              jsonb_build_array('financialContractHash',encode(extensions.digest(
                convert_to('opportunity-financial-inputs-v3.0','utf8'),'sha256'),'hex')),
              jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
              jsonb_build_array('providerFieldAllowlistHash','fe78e0f8c5b0846f822f72c6b2356cac35ed5c00dd0bcd06f9a75b7c5b21d3f7'),
              jsonb_build_array('rosterManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='instrument_roster' AND ordinal=0))),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('taxonomyAssignmentManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='taxonomy_assignment' AND ordinal=0))),
              jsonb_build_array('taxonomyMapHash','83f06426b8dae88f83d0610600000e529b6ad09249cee411c7ea2e89dab9a862'),
              jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
                convert_to('sector-calendar-window-v3.4','utf8'),'sha256'),'hex'))
            ));
        ELSIF v_kind='bias_reference' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('asOfSession',(SELECT session_id FROM public.opportunity_effective_taiwan_sessions_v3
                WHERE canonical_cutoff<=v_run.source_cutoff ORDER BY session_id DESC LIMIT 1)),
              jsonb_build_array('corporateActionVersion','tw-corporate-action-v3.1'),
              jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
              jsonb_build_array('rosterManifestHash',(SELECT manifest_hash FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                SELECT manifest_id FROM public.opportunity_run_manifest_inputs WHERE run_id=requested_run_id AND input_role='instrument_roster' AND ordinal=0))),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('taxonomyAssignmentManifestHash',(SELECT manifest_hash FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                SELECT manifest_id FROM public.opportunity_run_manifest_inputs WHERE run_id=requested_run_id AND input_role='taxonomy_assignment' AND ordinal=0))),
              jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(convert_to(
                regexp_replace(jsonb_build_array('bias-calendar-window-v3.11.3',coalesce((SELECT jsonb_agg(jsonb_build_array(session_id,taiwan_session_authority_hash) ORDER BY session_id)
                  FROM (SELECT session_id,taiwan_session_authority_hash FROM public.opportunity_effective_taiwan_sessions_v3
                    WHERE canonical_cutoff<=v_run.source_cutoff ORDER BY session_id DESC LIMIT 120) sessions),'[]'::jsonb))::text,', ', ',','g'),'utf8'),'sha256'),'hex'))
            ));
        ELSIF v_kind='technical_history_reference' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('asOfSession',(SELECT session_id FROM public.opportunity_effective_taiwan_sessions_v3
                WHERE canonical_cutoff<=v_run.source_cutoff ORDER BY session_id DESC LIMIT 1)),
              jsonb_build_array('biasReferenceManifestHash',(SELECT manifest_hash FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                SELECT manifest_id FROM public.opportunity_run_manifest_inputs WHERE run_id=requested_run_id AND input_role='bias_reference' AND ordinal=0))),
              jsonb_build_array('corporateActionVersion','tw-corporate-action-v3.1'),
              jsonb_build_array('orderedDeepSymbols',coalesce((SELECT jsonb_agg(plan.symbol ORDER BY plan.candidate_ordinal)
                FROM public.opportunity_candidate_plan_v3_internal(requested_run_id,'shallow') plan WHERE plan.candidate_ordinal<20),'[]'::jsonb)),
              jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(convert_to('technical-history-calendar-v3.11.3','utf8'),'sha256'),'hex'))
            ));
        ELSIF v_kind='reported_pe_reference' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('asOfSession',(SELECT session_id FROM public.opportunity_effective_taiwan_sessions_v3
                WHERE canonical_cutoff<=v_run.source_cutoff ORDER BY session_id DESC LIMIT 1)),
              jsonb_build_array('financialContractVersion','opportunity-financial-inputs-v3.3'),
              jsonb_build_array('orderedDeepSymbols',coalesce((SELECT jsonb_agg(plan.symbol ORDER BY plan.candidate_ordinal)
                FROM public.opportunity_candidate_plan_v3_internal(requested_run_id,'shallow') plan WHERE plan.candidate_ordinal<20),'[]'::jsonb)),
              jsonb_build_array('rosterManifestHash',(SELECT manifest_hash FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                SELECT manifest_id FROM public.opportunity_run_manifest_inputs WHERE run_id=requested_run_id AND input_role='instrument_roster' AND ordinal=0))),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('taxonomyAssignmentManifestHash',(SELECT manifest_hash FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                SELECT manifest_id FROM public.opportunity_run_manifest_inputs WHERE run_id=requested_run_id AND input_role='taxonomy_assignment' AND ordinal=0))),
              jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(convert_to('reported-pe-calendar-v3.11.3','utf8'),'sha256'),'hex'))
            ));
        ELSIF v_kind='outcome_input' THEN
          v_body:=jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('comparisonContractKey',v_run.comparison_contract_key),
              jsonb_build_array('evaluationDatasetLockHash',v_run.evaluation_dataset_lock_hash),
              jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
              jsonb_build_array('runPurpose',v_run.run_purpose),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
                convert_to(regexp_replace(jsonb_build_array(
                  'outcome-calendar-window-v3.4',
                  coalesce((SELECT jsonb_agg(jsonb_build_array(
                    session.session_id,session.taiwan_session_authority_hash
                  ) ORDER BY session.session_id)
                  FROM (
                    SELECT session_id,taiwan_session_authority_hash
                    FROM public.opportunity_effective_taiwan_sessions_v3
                    WHERE canonical_cutoff<=v_run.source_cutoff
                    ORDER BY session_id DESC LIMIT 252
                  ) session),'[]'::jsonb)
                )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'))
            ));
        ELSIF v_kind='link_audit_sample' THEN
          SELECT jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('allocationVersion','link-audit-hamilton-v3.0'),
              jsonb_build_array('evaluationManifestHash',stats.evaluation_manifest_hash),
              jsonb_build_array('populationCount',stats.population_count),
              jsonb_build_array('sampleSize',least(400,stats.population_count)),
              jsonb_build_array('stratumCount',stats.stratum_count)
            )
          ) INTO v_body
          FROM (
            WITH evaluation_manifest AS (
              SELECT manifest.manifest_id,manifest.manifest_hash
              FROM public.opportunity_run_manifest_inputs input
              JOIN public.opportunity_manifests_v3 manifest
                ON manifest.manifest_id=input.manifest_id
                AND manifest.status='complete'
              WHERE input.run_id=requested_run_id
                AND input.input_role='evaluation_input' AND input.ordinal=0
            ), supplying_runs AS (
              SELECT DISTINCT (row.payload_json->>2)::uuid AS enrich_run_id
              FROM evaluation_manifest manifest
              JOIN public.opportunity_manifest_rows_v3 row
                ON row.manifest_id=manifest.manifest_id
                AND row.section_key IN ('backtest_rows','live_rows')
            ), population AS (
              SELECT mention.run_id,claim.claim_id,mention.mention_ordinal,
                revision.source_key,mention.link_mode,
                CASE
                  WHEN mention.outcome IN (
                    'linked_new','linked_refresh','linked_duplicate_claim'
                  ) THEN 'linked'
                  WHEN mention.outcome='ambiguous_symbol' THEN 'ambiguous'
                  WHEN mention.outcome='rejected_low_confidence' THEN 'rejected'
                  ELSE 'unsupported'
                END AS outcome_family
              FROM supplying_runs supplying
              JOIN public.opportunity_runs enrich ON enrich.run_id=supplying.enrich_run_id
              JOIN public.opportunity_source_mentions mention
                ON mention.run_id=enrich.upstream_run_id
              JOIN public.opportunity_source_claims claim
                ON claim.run_id=mention.run_id
                AND claim.revision_id=mention.revision_id
                AND claim.claim_ordinal=mention.claim_ordinal
              JOIN public.source_document_revisions_v3 revision
                ON revision.revision_id=mention.revision_id
              WHERE mention.recorded_at<=v_run.source_cutoff
                AND claim.recorded_at<=v_run.source_cutoff
            )
            SELECT
              (SELECT manifest_hash FROM evaluation_manifest) AS evaluation_manifest_hash,
              count(*)::integer AS population_count,
              count(DISTINCT (source_key,link_mode,outcome_family))::integer AS stratum_count
            FROM population
          ) stats;
        ELSIF v_kind='link_audit_resolution' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('evaluationCutoff',v_run.source_cutoff),
              jsonb_build_array('resolvedCount',(
                SELECT count(*) FROM public.opportunity_link_audit_samples sample
                WHERE sample.sample_manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id
                    AND input_role='link_audit_sample' AND ordinal=0
                ) AND (
                  EXISTS (
                    SELECT 1
                    FROM public.opportunity_link_audit_labels one
                    JOIN public.opportunity_link_audit_labels two
                      ON two.sample_manifest_id=one.sample_manifest_id
                      AND two.sample_id=one.sample_id
                      AND two.label_role='reviewer_2'
                    WHERE one.sample_manifest_id=sample.sample_manifest_id
                      AND one.sample_id=sample.sample_id
                      AND one.label_role='reviewer_1'
                      AND one.recorded_at<=v_run.source_cutoff
                      AND two.recorded_at<=v_run.source_cutoff
                      AND one.canonical_symbol IS NOT DISTINCT FROM two.canonical_symbol
                      AND one.no_link=two.no_link
                  ) OR EXISTS (
                    SELECT 1 FROM public.opportunity_link_audit_labels adjudication
                    WHERE adjudication.sample_manifest_id=sample.sample_manifest_id
                      AND adjudication.sample_id=sample.sample_id
                      AND adjudication.label_role='adjudicator'
                      AND adjudication.recorded_at<=v_run.source_cutoff
                  )
                )
              )),
              jsonb_build_array('sampleManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='link_audit_sample' AND ordinal=0))),
              jsonb_build_array('sampleManifestId',(SELECT manifest_id
                FROM public.opportunity_run_manifest_inputs
                WHERE run_id=requested_run_id AND input_role='link_audit_sample' AND ordinal=0)),
              jsonb_build_array('unresolvedCount',(
                SELECT count(*) FROM public.opportunity_link_audit_samples sample
                WHERE sample.sample_manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id
                    AND input_role='link_audit_sample' AND ordinal=0
                ) AND NOT (
                  EXISTS (
                    SELECT 1
                    FROM public.opportunity_link_audit_labels one
                    JOIN public.opportunity_link_audit_labels two
                      ON two.sample_manifest_id=one.sample_manifest_id
                      AND two.sample_id=one.sample_id
                      AND two.label_role='reviewer_2'
                    WHERE one.sample_manifest_id=sample.sample_manifest_id
                      AND one.sample_id=sample.sample_id
                      AND one.label_role='reviewer_1'
                      AND one.recorded_at<=v_run.source_cutoff
                      AND two.recorded_at<=v_run.source_cutoff
                      AND one.canonical_symbol IS NOT DISTINCT FROM two.canonical_symbol
                      AND one.no_link=two.no_link
                  ) OR EXISTS (
                    SELECT 1 FROM public.opportunity_link_audit_labels adjudication
                    WHERE adjudication.sample_manifest_id=sample.sample_manifest_id
                      AND adjudication.sample_id=sample.sample_id
                      AND adjudication.label_role='adjudicator'
                      AND adjudication.recorded_at<=v_run.source_cutoff
                  )
                )
              ))
            ));
        ELSE
          RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END IF;
      ELSE
        v_stage := 'seal_inputs';
        v_payload_kind := 'seal';
        v_shard := 'seal';
        v_body := jsonb_build_array(
          coalesce((SELECT jsonb_agg(jsonb_build_array(input_role,input_run_id) ORDER BY input_role,input_run_id)
            FROM public.opportunity_run_inputs WHERE run_id=requested_run_id),'[]'::jsonb),
          coalesce((SELECT jsonb_agg(jsonb_build_array(input_role,ordinal,manifest_id) ORDER BY input_role,ordinal)
            FROM public.opportunity_run_manifest_inputs WHERE run_id=requested_run_id),'[]'::jsonb)
        );
      END IF;
    ELSIF v_run.status='running' THEN
      IF v_run.mode='source_scan' AND v_predecessor_payload.payload_kind='seal' THEN
        v_source_ordinal := 0;
        v_source_key := 'bulltalk';
        v_stage := 'source_documents';
        SELECT manifest_id INTO STRICT v_dataset_manifest_id
        FROM public.opportunity_run_manifest_inputs
        WHERE run_id=requested_run_id AND input_role='source_dataset' AND ordinal=0;
        SELECT mr.payload_json,mr.row_ordinal::integer,(mr.payload_json->>16)::uuid,d.raw_code_point_count
        INTO v_revision_row,v_revision_selection_ordinal,v_revision_id,v_revision_raw_code_point_count
        FROM public.opportunity_manifest_rows_v3 mr
        JOIN public.source_document_revisions_v3 d ON d.revision_id=(mr.payload_json->>16)::uuid
        WHERE mr.manifest_id=v_dataset_manifest_id AND mr.section_key='selected_revision_rows'
          AND mr.payload_json->>0=v_source_key::text
        ORDER BY mr.row_ordinal LIMIT 1;
        IF FOUND THEN
          v_payload_kind := 'source_parse_batch';
          v_shard := 'source_parse_batch:'||v_revision_selection_ordinal;
          v_body := jsonb_build_array(
            v_dataset_manifest_id,v_source_key,v_revision_selection_ordinal,
            v_revision_selection_ordinal+1,
            jsonb_build_array(jsonb_build_array(
              v_revision_id,v_revision_selection_ordinal,v_revision_raw_code_point_count
            ))
          );
        ELSE
          v_payload_kind := 'source_connector_summary';
          v_shard := 'source_connector_summary:0';
          v_body := jsonb_build_array(v_dataset_manifest_id,v_source_key);
        END IF;
      ELSIF v_run.mode='source_scan' AND v_predecessor_payload.payload_kind='source_parse_batch' THEN
        v_dataset_manifest_id := (v_predecessor_payload.payload_json->5->>0)::uuid;
        v_source_key := (v_predecessor_payload.payload_json->5->>1)::public.source_key_v3;
        v_source_ordinal := array_position(ARRAY[
          'bulltalk','earnings_call','instagram','investanchors','mops_material_event','podcast',
          'ptt','public_broker_research','telegram','threads','youtube'
        ]::public.source_key_v3[],v_source_key)-1;
        v_stage := 'source_documents';
        v_revision_selection_ordinal := (v_predecessor_payload.payload_json->5->>2)::integer;
        SELECT mr.payload_json,mr.row_ordinal::integer,(mr.payload_json->>16)::uuid,d.raw_code_point_count
        INTO v_revision_row,v_revision_selection_ordinal,v_revision_id,v_revision_raw_code_point_count
        FROM public.opportunity_manifest_rows_v3 mr
        JOIN public.source_document_revisions_v3 d ON d.revision_id=(mr.payload_json->>16)::uuid
        WHERE mr.manifest_id=v_dataset_manifest_id AND mr.section_key='selected_revision_rows'
          AND mr.payload_json->>0=v_source_key::text
          AND mr.row_ordinal>(v_predecessor_payload.payload_json->5->>2)::integer
        ORDER BY mr.row_ordinal LIMIT 1;
        IF FOUND THEN
          v_payload_kind := 'source_parse_batch';
          v_shard := 'source_parse_batch:'||v_revision_selection_ordinal;
          v_body := jsonb_build_array(
            v_dataset_manifest_id,v_source_key,v_revision_selection_ordinal,
            v_revision_selection_ordinal+1,
            jsonb_build_array(jsonb_build_array(
              v_revision_id,v_revision_selection_ordinal,v_revision_raw_code_point_count
            ))
          );
        ELSE
          v_payload_kind := 'source_connector_summary';
          v_shard := 'source_connector_summary:'||v_source_ordinal;
          v_body := jsonb_build_array(v_dataset_manifest_id,v_source_key);
        END IF;
      ELSIF v_run.mode='source_scan' AND v_predecessor_payload.payload_kind='source_connector_summary' THEN
        v_source_key := (v_predecessor_payload.payload_json->5->>1)::public.source_key_v3;
        v_dataset_manifest_id := (v_predecessor_payload.payload_json->5->>0)::uuid;
        v_source_ordinal := array_position(ARRAY[
          'bulltalk','earnings_call','instagram','investanchors','mops_material_event','podcast',
          'ptt','public_broker_research','telegram','threads','youtube'
        ]::public.source_key_v3[],v_source_key);
        IF v_source_ordinal < 11 THEN
          v_source_key := (ARRAY[
            'bulltalk','earnings_call','instagram','investanchors','mops_material_event','podcast',
            'ptt','public_broker_research','telegram','threads','youtube'
          ]::public.source_key_v3[])[v_source_ordinal+1];
          v_stage := 'source_documents';
          SELECT mr.payload_json,mr.row_ordinal::integer,(mr.payload_json->>16)::uuid,d.raw_code_point_count
          INTO v_revision_row,v_revision_selection_ordinal,v_revision_id,v_revision_raw_code_point_count
          FROM public.opportunity_manifest_rows_v3 mr
          JOIN public.source_document_revisions_v3 d ON d.revision_id=(mr.payload_json->>16)::uuid
          WHERE mr.manifest_id=v_dataset_manifest_id AND mr.section_key='selected_revision_rows'
            AND mr.payload_json->>0=v_source_key::text
          ORDER BY mr.row_ordinal LIMIT 1;
          IF FOUND THEN
            v_payload_kind := 'source_parse_batch';
            v_shard := 'source_parse_batch:'||v_revision_selection_ordinal;
            v_body := jsonb_build_array(
              v_dataset_manifest_id,v_source_key,v_revision_selection_ordinal,
              v_revision_selection_ordinal+1,
              jsonb_build_array(jsonb_build_array(
                v_revision_id,v_revision_selection_ordinal,v_revision_raw_code_point_count
              ))
            );
          ELSE
            v_payload_kind := 'source_connector_summary';
            v_shard := 'source_connector_summary:'||v_source_ordinal;
            v_body := jsonb_build_array(v_dataset_manifest_id,v_source_key);
          END IF;
        ELSE
          v_stage := 'finalize'; v_payload_kind := 'finalize'; v_shard := 'finalize';
        END IF;
      ELSIF v_run.mode='enrich_rank' AND v_predecessor_payload.payload_kind='seal' THEN
        v_stage := 'shallow_enrich';
        v_payload_kind := 'market_context_snapshot';
        v_shard := 'market_context_snapshot:0';
        v_body := jsonb_build_array(
          (SELECT manifest_id FROM public.opportunity_run_manifest_inputs
            WHERE run_id=requested_run_id AND input_role='market_reference' AND ordinal=0),
          '[]'::jsonb
        );
      ELSIF v_run.mode='enrich_rank' AND v_predecessor_payload.payload_kind='market_context_snapshot' THEN
        IF EXISTS (
          SELECT 1 FROM public.opportunity_candidate_plan_v3_internal(
            requested_run_id,'shallow'
          ) LIMIT 1
        ) THEN
          v_stage := 'shallow_enrich';
          v_payload_kind := 'shallow_candidate_batch';
          v_shard := 'shallow_candidate_batch:0';
          v_body := jsonb_build_array(
            0,least(5,(SELECT count(*) FROM
              public.opportunity_candidate_plan_v3_internal(requested_run_id,'shallow'))),
            (SELECT coalesce(jsonb_agg(symbol ORDER BY candidate_ordinal),'[]'::jsonb)
              FROM public.opportunity_candidate_plan_v3_internal(requested_run_id,'shallow')
              WHERE candidate_ordinal<5),
            (SELECT coalesce(jsonb_agg(i.manifest_id ORDER BY i.input_role,i.ordinal),'[]'::jsonb)
              FROM public.opportunity_run_manifest_inputs i WHERE i.run_id=requested_run_id)
          );
        ELSE
          v_stage := 'portfolio_allocate';
          v_payload_kind := 'portfolio_allocation_batch';
          v_shard := 'portfolio_allocation_batch:0';
          v_body := jsonb_build_array('[]'::jsonb,'[]'::jsonb);
        END IF;
      ELSIF v_run.mode='enrich_rank' AND v_predecessor_payload.payload_kind='shallow_candidate_batch' THEN
        IF (v_predecessor_payload.payload_json->5->>1)::integer < (
          SELECT count(*) FROM public.opportunity_candidate_plan_v3_internal(
            requested_run_id,'shallow'
          )
        ) THEN
          v_stage := 'shallow_enrich';
          v_payload_kind := 'shallow_candidate_batch';
          v_ordinal := (v_predecessor_payload.payload_json->5->>1)::integer/5;
          v_shard := 'shallow_candidate_batch:'||v_ordinal;
          v_body := jsonb_build_array(
            (v_predecessor_payload.payload_json->5->>1)::integer,
            least((v_predecessor_payload.payload_json->5->>1)::integer+5,(
              SELECT count(*) FROM public.opportunity_candidate_plan_v3_internal(
                requested_run_id,'shallow'
              )
            )),
            (SELECT coalesce(jsonb_agg(symbol ORDER BY candidate_ordinal),'[]'::jsonb)
              FROM public.opportunity_candidate_plan_v3_internal(requested_run_id,'shallow')
              WHERE candidate_ordinal>=(v_predecessor_payload.payload_json->5->>1)::integer
                AND candidate_ordinal<(v_predecessor_payload.payload_json->5->>1)::integer+5),
            (SELECT coalesce(jsonb_agg(i.manifest_id ORDER BY i.input_role,i.ordinal),'[]'::jsonb)
              FROM public.opportunity_run_manifest_inputs i WHERE i.run_id=requested_run_id)
          );
        ELSIF EXISTS (
          SELECT 1 FROM public.opportunity_shallow_candidate_results_v3 s
          WHERE s.run_id=requested_run_id AND s.shallow_status='succeeded'
        ) THEN
          v_stage := 'deep_research';
          v_payload_kind := 'sector_cycle_batch';
          v_shard := 'sector_cycle_batch:0';
          v_body := jsonb_build_array(
            0,
            least(5,(SELECT count(DISTINCT s.canonical_sector_key)
              FROM public.opportunity_shallow_candidate_results_v3 s
              WHERE s.run_id=requested_run_id AND s.shallow_status='succeeded')),
            (SELECT coalesce(jsonb_agg(canonical_sector_key ORDER BY canonical_sector_key),'[]'::jsonb)
              FROM (
                SELECT DISTINCT s.canonical_sector_key
                FROM public.opportunity_shallow_candidate_results_v3 s
                WHERE s.run_id=requested_run_id AND s.shallow_status='succeeded'
                ORDER BY s.canonical_sector_key LIMIT 5
              ) sectors),
            (SELECT manifest_id FROM public.opportunity_run_manifest_inputs
              WHERE run_id=requested_run_id AND input_role='sector_scoring_reference' AND ordinal=0)
          );
        ELSE
          v_stage := 'portfolio_allocate';
          v_payload_kind := 'portfolio_allocation_batch';
          v_shard := 'portfolio_allocation_batch:0';
          v_body := jsonb_build_array('[]'::jsonb,'[]'::jsonb);
        END IF;
      ELSIF v_run.mode='enrich_rank' AND v_predecessor_payload.payload_kind='sector_cycle_batch' THEN
        IF (v_predecessor_payload.payload_json->5->>1)::integer < (
          SELECT count(DISTINCT s.canonical_sector_key)
          FROM public.opportunity_shallow_candidate_results_v3 s
          WHERE s.run_id=requested_run_id AND s.shallow_status='succeeded'
        ) THEN
          v_stage := 'deep_research';
          v_payload_kind := 'sector_cycle_batch';
          v_ordinal := (v_predecessor_payload.payload_json->5->>1)::integer/5;
          v_shard := 'sector_cycle_batch:'||v_ordinal;
          v_body := jsonb_build_array(
            (v_predecessor_payload.payload_json->5->>1)::integer,
            least((v_predecessor_payload.payload_json->5->>1)::integer+5,(
              SELECT count(DISTINCT s.canonical_sector_key)
              FROM public.opportunity_shallow_candidate_results_v3 s
              WHERE s.run_id=requested_run_id AND s.shallow_status='succeeded'
            )),
            (SELECT coalesce(jsonb_agg(canonical_sector_key ORDER BY canonical_sector_key),'[]'::jsonb)
              FROM (
                SELECT DISTINCT s.canonical_sector_key
                FROM public.opportunity_shallow_candidate_results_v3 s
                WHERE s.run_id=requested_run_id AND s.shallow_status='succeeded'
                ORDER BY s.canonical_sector_key
                OFFSET (v_predecessor_payload.payload_json->5->>1)::integer LIMIT 5
              ) sectors),
            (SELECT manifest_id FROM public.opportunity_run_manifest_inputs
              WHERE run_id=requested_run_id AND input_role='sector_scoring_reference' AND ordinal=0)
          );
        ELSIF EXISTS (
          SELECT 1 FROM public.opportunity_candidate_plan_v3_internal(
            requested_run_id,'deep'
          ) LIMIT 1
        ) THEN
          v_stage := 'deep_research';
          v_payload_kind := 'deep_candidate_batch';
          v_shard := 'deep_candidate_batch:0';
          v_body := jsonb_build_array(
            0,least(5,(SELECT count(*) FROM
              public.opportunity_candidate_plan_v3_internal(requested_run_id,'deep'))),
            (SELECT coalesce(jsonb_agg(symbol ORDER BY candidate_ordinal),'[]'::jsonb)
              FROM public.opportunity_candidate_plan_v3_internal(requested_run_id,'deep')
              WHERE candidate_ordinal<5),
            (SELECT coalesce(jsonb_agg(i.manifest_id ORDER BY i.input_role,i.ordinal),'[]'::jsonb)
              FROM public.opportunity_run_manifest_inputs i WHERE i.run_id=requested_run_id)
          );
        ELSE
          v_stage := 'portfolio_allocate';
          v_payload_kind := 'portfolio_allocation_batch';
          v_shard := 'portfolio_allocation_batch:0';
          v_body := jsonb_build_array('[]'::jsonb,'[]'::jsonb);
        END IF;
      ELSIF v_run.mode='enrich_rank' AND v_predecessor_payload.payload_kind='deep_candidate_batch' THEN
        IF (v_predecessor_payload.payload_json->5->>1)::integer < (
          SELECT count(*) FROM public.opportunity_candidate_plan_v3_internal(
            requested_run_id,'deep'
          )
        ) THEN
          v_stage := 'deep_research';
          v_payload_kind := 'deep_candidate_batch';
          v_ordinal := (v_predecessor_payload.payload_json->5->>1)::integer/5;
          v_shard := 'deep_candidate_batch:'||v_ordinal;
          v_body := jsonb_build_array(
            (v_predecessor_payload.payload_json->5->>1)::integer,
            least((v_predecessor_payload.payload_json->5->>1)::integer+5,(
              SELECT count(*) FROM public.opportunity_candidate_plan_v3_internal(
                requested_run_id,'deep'
              )
            )),
            (SELECT coalesce(jsonb_agg(symbol ORDER BY candidate_ordinal),'[]'::jsonb)
              FROM public.opportunity_candidate_plan_v3_internal(requested_run_id,'deep')
              WHERE candidate_ordinal>=(v_predecessor_payload.payload_json->5->>1)::integer
                AND candidate_ordinal<(v_predecessor_payload.payload_json->5->>1)::integer+5),
            (SELECT coalesce(jsonb_agg(i.manifest_id ORDER BY i.input_role,i.ordinal),'[]'::jsonb)
              FROM public.opportunity_run_manifest_inputs i WHERE i.run_id=requested_run_id)
          );
        ELSE
          v_stage := 'portfolio_allocate';
          v_payload_kind := 'portfolio_allocation_batch';
          v_shard := 'portfolio_allocation_batch:0';
          v_body := jsonb_build_array(
            (SELECT coalesce(jsonb_agg(d.symbol ORDER BY d.candidate_ordinal),'[]'::jsonb)
              FROM public.opportunity_deep_candidate_results_v3 d
              WHERE d.run_id=requested_run_id AND d.deep_status='succeeded'),
            (SELECT coalesce(jsonb_agg(DISTINCT d.job_id ORDER BY d.job_id),'[]'::jsonb)
              FROM public.opportunity_deep_candidate_results_v3 d
              WHERE d.run_id=requested_run_id AND d.deep_status='succeeded')
          );
        END IF;
      ELSIF v_run.mode='enrich_rank' AND v_predecessor_payload.payload_kind='portfolio_allocation_batch' THEN
        v_stage := 'project';
        v_payload_kind := 'projection_bundle';
        v_shard := 'projection_bundle:0';
        v_body := jsonb_build_array(
          (SELECT coalesce(jsonb_agg(plan.symbol ORDER BY plan.candidate_ordinal),'[]'::jsonb)
            FROM public.opportunity_candidate_plan_v3_internal(
              requested_run_id,'active'
            ) plan),
          (SELECT job_id FROM public.opportunity_run_jobs_v3
            WHERE run_id=requested_run_id AND output_kind='market_context_snapshot' ORDER BY created_at LIMIT 1),
          (SELECT coalesce(jsonb_agg(job_id ORDER BY created_at,job_id),'[]'::jsonb)
            FROM public.opportunity_run_jobs_v3
            WHERE run_id=requested_run_id AND output_kind='sector_cycle_batch'),
          (SELECT coalesce(jsonb_agg(job_id ORDER BY created_at,job_id),'[]'::jsonb)
            FROM public.opportunity_run_jobs_v3
            WHERE run_id=requested_run_id AND output_kind='deep_candidate_batch'),
          predecessor_job_id,'verified-change-brief-v3.0'
        );
      ELSIF v_run.mode='enrich_rank' AND v_predecessor_payload.payload_kind='projection_bundle' THEN
        v_stage := 'finalize'; v_payload_kind := 'finalize'; v_shard := 'finalize';
      ELSIF v_run.mode='label_outcomes' AND v_predecessor_payload.payload_kind='seal' THEN
        SELECT manifest_id INTO STRICT v_dataset_manifest_id
        FROM public.opportunity_run_manifest_inputs
        WHERE run_id=requested_run_id AND input_role='outcome_input' AND ordinal=0;
        IF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_rows_v3
          WHERE manifest_id=v_dataset_manifest_id AND section_key='input_rows'
        ) THEN
          v_stage := 'label';
          v_payload_kind := 'outcome_batch';
          v_shard := 'outcome_batch:0';
          v_body := jsonb_build_array(
            v_dataset_manifest_id,0,least(200,(SELECT count(*) FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_dataset_manifest_id AND section_key='input_rows'))
          );
        ELSE
          v_stage := 'finalize'; v_payload_kind := 'finalize'; v_shard := 'finalize';
        END IF;
      ELSIF v_run.mode='label_outcomes' AND v_predecessor_payload.payload_kind='outcome_batch' THEN
        v_dataset_manifest_id := (v_predecessor_payload.payload_json->5->>0)::uuid;
        IF (v_predecessor_payload.payload_json->5->>2)::integer < (
          SELECT count(*) FROM public.opportunity_manifest_rows_v3
          WHERE manifest_id=v_dataset_manifest_id AND section_key='input_rows'
        ) THEN
          v_stage := 'label';
          v_payload_kind := 'outcome_batch';
          v_ordinal := (v_predecessor_payload.payload_json->5->>2)::integer/200;
          v_shard := 'outcome_batch:'||v_ordinal;
          v_body := jsonb_build_array(
            v_dataset_manifest_id,
            (v_predecessor_payload.payload_json->5->>2)::integer,
            least((v_predecessor_payload.payload_json->5->>2)::integer+200,(
              SELECT count(*) FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_dataset_manifest_id AND section_key='input_rows'
            ))
          );
        ELSE
          v_stage := 'finalize'; v_payload_kind := 'finalize'; v_shard := 'finalize';
        END IF;
      ELSIF v_run.mode='shadow_evaluate' AND v_predecessor_payload.payload_kind='seal' THEN
        v_stage := 'evaluate';
        v_payload_kind := 'evaluation_bundle';
        v_shard := 'evaluation_bundle:0';
        v_body := jsonb_build_array(
          (SELECT manifest_id FROM public.opportunity_run_manifest_inputs
            WHERE run_id=requested_run_id AND input_role='evaluation_input' AND ordinal=0),
          (SELECT manifest_id FROM public.opportunity_run_manifest_inputs
            WHERE run_id=requested_run_id AND input_role='link_audit_sample' AND ordinal=0),
          (SELECT manifest_id FROM public.opportunity_run_manifest_inputs
            WHERE run_id=requested_run_id AND input_role='link_audit_resolution' AND ordinal=0),
          jsonb_build_array('official_only','source_led','hybrid')
        );
      ELSIF v_run.mode='shadow_evaluate' AND v_predecessor_payload.payload_kind='evaluation_bundle' THEN
        v_stage := 'finalize'; v_payload_kind := 'finalize'; v_shard := 'finalize';
      ELSE
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      END IF;
      IF v_payload_kind='finalize' THEN
        v_body := jsonb_build_array(
          coalesce((SELECT jsonb_agg(job_id ORDER BY created_at,job_id)
            FROM public.opportunity_run_jobs_v3 WHERE run_id=requested_run_id AND status='succeeded'),'[]'::jsonb),
          coalesce((SELECT jsonb_agg(output_hash ORDER BY created_at,job_id)
            FROM public.opportunity_run_jobs_v3 WHERE run_id=requested_run_id AND status='succeeded'),'[]'::jsonb)
        );
      END IF;
    ELSE
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
  END IF;
  v_payload := jsonb_build_array('opportunity-job-payload-v3.3',v_payload_kind,requested_run_id,v_stage,v_shard,v_body);
  v_payload_text := regexp_replace(v_payload::text, ', ', ',', 'g');
  v_payload_hash := encode(extensions.digest(convert_to(v_payload_text,'utf8'),'sha256'),'hex');
  v_input_text := regexp_replace(jsonb_build_array(
    'opportunity-job-input-v3.3',requested_run_id,v_stage,v_shard,v_payload_hash,v_predecessor_hashes
  )::text, ', ', ',', 'g');
  v_input_hash := encode(extensions.digest(convert_to(v_input_text,'utf8'),'sha256'),'hex');
  v_bytes := substring(extensions.digest(
    decode(replace('7ad3ec9e-4db5-5e8a-b9a4-eab35ddc1a21','-',''),'hex')
      || convert_to(v_input_hash,'utf8'),'sha1') FROM 1 FOR 16);
  v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
  v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
  v_hex := encode(v_bytes,'hex');
  v_job_id := (substr(v_hex,1,8)||'-'||substr(v_hex,9,4)||'-'||substr(v_hex,13,4)||'-'
    ||substr(v_hex,17,4)||'-'||substr(v_hex,21,12))::uuid;
  INSERT INTO public.opportunity_run_jobs_v3(job_id,run_id,stage,shard_key,input_hash)
  VALUES(v_job_id,requested_run_id,v_stage,v_shard,v_input_hash)
  ON CONFLICT(run_id,stage,shard_key,input_hash) DO NOTHING;
  INSERT INTO public.opportunity_job_payloads_v3(job_id,run_id,payload_kind,payload_canonical,payload_json,payload_hash)
  VALUES(v_job_id,requested_run_id,v_payload_kind,convert_to(v_payload_text,'utf8'),v_payload,v_payload_hash)
  ON CONFLICT(job_id) DO NOTHING;
  RETURN v_job_id;
END
$fn$;

CREATE OR REPLACE FUNCTION derive_manifest_page_descriptor_v3_internal(
  requested_manifest_id uuid, requested_section_key opportunity_manifest_section_key_v3,
  requested_page_ordinal integer, requested_first_row_ordinal bigint
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_bytes bytea; v_hex text; v_page_id uuid; v_name text;
BEGIN
  IF requested_page_ordinal<0 OR requested_first_row_ordinal<0 OR NOT EXISTS (
    SELECT 1 FROM public.opportunity_manifests_v3
    WHERE manifest_id=requested_manifest_id AND status='building'
  ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  v_name := format('["%s","%s",%s]',requested_manifest_id,requested_section_key,requested_page_ordinal);
  v_bytes := substring(extensions.digest(
    decode(replace('51689af8-f3fe-5d1e-a18f-c667ddee224a','-',''),'hex')
      || convert_to(v_name,'utf8'),'sha1') FROM 1 FOR 16);
  v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
  v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
  v_hex := encode(v_bytes,'hex');
  v_page_id := (substr(v_hex,1,8)||'-'||substr(v_hex,9,4)||'-'||substr(v_hex,13,4)||'-'
    ||substr(v_hex,17,4)||'-'||substr(v_hex,21,12))::uuid;
  RETURN jsonb_build_array(v_page_id,requested_manifest_id,requested_section_key,requested_page_ordinal,requested_first_row_ordinal);
END
$fn$;

CREATE OR REPLACE VIEW opportunity_run_status_read_v3
WITH (security_invoker = true, security_barrier = true)
AS SELECT run_id, status, failure_code, canonical_run_id FROM opportunity_runs;

CREATE OR REPLACE FUNCTION opportunity_raise_pt409_v3_internal(requested_message text)
RETURNS integer
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
BEGIN
  RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE=requested_message;
END
$fn$;

CREATE OR REPLACE VIEW opportunity_effective_taiwan_sessions_v3
WITH (security_invoker = true, security_barrier = true)
AS
WITH candidate_dates AS MATERIALIZED (
  SELECT DISTINCT session.session_id,
    (session.session_id::timestamp + time '16:00:00')
      AT TIME ZONE 'Asia/Taipei' AS canonical_cutoff
  FROM tw_trading_sessions_v3 session
  WHERE (session.session_id::timestamp + time '16:00:00')
      AT TIME ZONE 'Asia/Taipei' <= statement_timestamp()
), bounded AS MATERIALIZED (
  SELECT candidate.session_id,candidate.canonical_cutoff,market.market,
    session.session_authority_id,session.open_at,session.close_at,session.status,
    session.provider,session.source_timestamp,session.collected_at,
    session.source_ref,session.recorded_at
  FROM candidate_dates candidate
  CROSS JOIN (VALUES
    ('TWSE'::public.tw_market_v3),('TPEX'::public.tw_market_v3)
  ) market(market)
  CROSS JOIN LATERAL (
    SELECT retained.*
    FROM public.tw_trading_sessions_v3 retained
    WHERE retained.session_id=candidate.session_id
      AND retained.market=market.market
      AND retained.source_timestamp<=candidate.canonical_cutoff
      AND retained.collected_at<=candidate.canonical_cutoff
      AND retained.recorded_at<=candidate.canonical_cutoff
    ORDER BY retained.recorded_at DESC,retained.session_authority_id
    LIMIT 1025
  ) session
), stream_stats AS MATERIALIZED (
  SELECT bounded.session_id,bounded.canonical_cutoff,bounded.market,
    count(*) AS retained_count,max(bounded.recorded_at) AS greatest_recorded_at
  FROM bounded
  GROUP BY bounded.session_id,bounded.canonical_cutoff,bounded.market
), greatest AS MATERIALIZED (
  SELECT bounded.*
  FROM bounded
  JOIN stream_stats stats USING(session_id,canonical_cutoff,market)
  WHERE bounded.recorded_at=stats.greatest_recorded_at
), resolved AS MATERIALIZED (
  SELECT greatest.session_id,greatest.canonical_cutoff,greatest.market,
    max(stream_stats.retained_count) AS retained_count,
    count(DISTINCT jsonb_build_array(
      greatest.session_id,greatest.market,greatest.open_at,greatest.close_at,
      greatest.status,greatest.provider,greatest.source_timestamp,
      greatest.collected_at,greatest.source_ref
    )) AS semantic_count,
    (array_agg(greatest.session_authority_id
      ORDER BY greatest.session_authority_id))[1] AS session_authority_id,
    min(greatest.open_at) AS open_at,min(greatest.close_at) AS close_at,
    min(greatest.status::text)::public.trading_session_status_v3 AS status,
    min(greatest.source_timestamp) AS source_timestamp,
    min(greatest.collected_at) AS collected_at,
    min(greatest.source_ref) AS source_ref,
    min(greatest.recorded_at) AS recorded_at
  FROM greatest
  JOIN stream_stats USING(session_id,canonical_cutoff,market)
  GROUP BY greatest.session_id,greatest.canonical_cutoff,greatest.market
), paired AS (
  SELECT twse.session_id,twse.open_at,twse.close_at,twse.canonical_cutoff,
    twse.status AS twse_status,tpex.status AS tpex_status,
    twse.open_at=tpex.open_at AND twse.close_at=tpex.close_at AS schedule_matches,
    twse.retained_count AS twse_retained_count,
    tpex.retained_count AS tpex_retained_count,
    twse.semantic_count AS twse_semantic_count,
    tpex.semantic_count AS tpex_semantic_count,
    encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
      'tw-trading-session-v3.0',
      jsonb_build_array(
        twse.session_id,twse.open_at,twse.close_at,
        jsonb_build_array(
          twse.session_authority_id,twse.source_timestamp,twse.collected_at,
          twse.source_ref,twse.recorded_at
        ),
        jsonb_build_array(
          tpex.session_authority_id,tpex.source_timestamp,tpex.collected_at,
          tpex.source_ref,tpex.recorded_at
        )
      )
    )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex')
      AS taiwan_session_authority_hash
  FROM resolved twse
  JOIN resolved tpex
    ON tpex.session_id=twse.session_id
    AND tpex.canonical_cutoff=twse.canonical_cutoff
    AND tpex.market='TPEX'
  WHERE twse.market='TWSE'
)
SELECT session_id,open_at,close_at,taiwan_session_authority_hash,canonical_cutoff
FROM paired
WHERE CASE
  WHEN twse_retained_count>1024 OR tpex_retained_count>1024
  THEN public.opportunity_raise_pt409_v3_internal('bound_violation')
  WHEN twse_semantic_count<>1 OR tpex_semantic_count<>1
  THEN public.opportunity_raise_pt409_v3_internal('authority_revision_conflict')
  WHEN twse_status='completed' AND tpex_status='completed' AND NOT schedule_matches
  THEN public.opportunity_raise_pt409_v3_internal('authority_revision_conflict')
  WHEN twse_status='completed' AND tpex_status='completed' AND schedule_matches
  THEN 1 ELSE 0 END=1;

CREATE OR REPLACE FUNCTION opportunity_market_zscore_v3_internal(
  requested_fact public.market_fact_key_v3,
  requested_scope public.market_scope_key_v3,
  requested_provider public.market_provider_v3,
  requested_provider_identity text,
  requested_authority_date date,
  requested_value double precision,
  requested_source_cutoff timestamptz
) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
WITH newest_dates AS MATERIALIZED (
  SELECT DISTINCT observation.authority_date
  FROM public.opportunity_market_observations_v3 observation
  WHERE observation.fact_key=requested_fact
    AND observation.scope_key=requested_scope
    AND observation.provider=requested_provider
    AND observation.provider_identity IS NOT DISTINCT FROM requested_provider_identity
    AND observation.authority_date<requested_authority_date
    AND observation.observed_at<=requested_source_cutoff
    AND observation.collected_at<=requested_source_cutoff
    AND observation.recorded_at<=requested_source_cutoff
  ORDER BY observation.authority_date DESC
  LIMIT 512
), raw_history AS MATERIALIZED (
  SELECT observation.*
  FROM public.opportunity_market_observations_v3 observation
  WHERE observation.fact_key=requested_fact
    AND observation.scope_key=requested_scope
    AND observation.provider=requested_provider
    AND observation.provider_identity IS NOT DISTINCT FROM requested_provider_identity
    AND observation.authority_date IN (SELECT authority_date FROM newest_dates)
    AND observation.observed_at<=requested_source_cutoff
    AND observation.collected_at<=requested_source_cutoff
    AND observation.recorded_at<=requested_source_cutoff
  ORDER BY observation.authority_date DESC,observation.recorded_at DESC,
    observation.observation_id
  LIMIT 32769
), ranked AS (
  SELECT raw_history.*,
    dense_rank() OVER (
      PARTITION BY authority_date
      ORDER BY observed_at DESC,collected_at DESC,recorded_at DESC,source_ref
    ) AS authority_rank
  FROM raw_history
), resolved AS (
  SELECT authority_date,min(CASE
    WHEN requested_fact IN (
      'margin_change_5d','put_call_ratio','taiwan_vix','usd_twd_return_5d'
    ) THEN -value ELSE value END) AS value
  FROM ranked
  WHERE authority_rank=1
  GROUP BY authority_date
  HAVING count(DISTINCT CASE
    WHEN requested_fact IN (
      'margin_change_5d','put_call_ratio','taiwan_vix','usd_twd_return_5d'
    ) THEN -value ELSE value END)=1
  ORDER BY authority_date DESC
  LIMIT 252
), statistics AS (
  SELECT count(*)::integer AS history_count,avg(value) AS mean_value,
    stddev_pop(value) AS population_deviation
  FROM resolved
), normalized AS (
  SELECT history_count,mean_value,population_deviation,
    CASE
      WHEN history_count<60 THEN NULL
      WHEN population_deviation>0
        THEN (requested_value-mean_value)/population_deviation
      WHEN requested_value=mean_value THEN 0
      WHEN requested_value>mean_value THEN 10
      ELSE -10
    END AS zscore
  FROM statistics
)
SELECT jsonb_build_object(
  'status',CASE WHEN history_count<60 THEN 'missing' ELSE 'fresh' END,
  'reason',CASE
    WHEN history_count<60 THEN 'insufficient_history'
    WHEN population_deviation=0 THEN 'zero_variance'
    ELSE NULL END,
  'historyCount',history_count,
  'score',CASE WHEN zscore IS NULL THEN NULL
    ELSE greatest(0,least(100,50+15*zscore)) END
)
FROM normalized
$fn$;

CREATE OR REPLACE FUNCTION opportunity_global_observation_v3_internal(
  requested_fact public.market_fact_key_v3,
  requested_scope public.market_scope_key_v3,
  requested_provider_identity text,
  requested_source_cutoff timestamptz
) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
WITH raw_dates AS MATERIALIZED (
  SELECT observation.*
  FROM public.opportunity_market_observations_v3 observation
  WHERE observation.fact_key=requested_fact
    AND observation.scope_key=requested_scope
    AND observation.provider='global_allowlisted'
    AND observation.provider_identity=requested_provider_identity
    AND observation.observed_at<=requested_source_cutoff
    AND observation.collected_at<=requested_source_cutoff
    AND observation.recorded_at<=requested_source_cutoff
  ORDER BY observation.provider_session_date DESC,observation.recorded_at DESC,
    observation.observation_id
  LIMIT 193
), ranked AS (
  SELECT raw_dates.*,
    dense_rank() OVER (
      PARTITION BY provider_session_date
      ORDER BY observed_at DESC,collected_at DESC,recorded_at DESC,source_ref
    ) AS authority_rank,
    dense_rank() OVER (ORDER BY provider_session_date DESC) AS date_rank
  FROM raw_dates
), resolved AS (
  SELECT provider_session_date,min(value) AS value,max(observed_at) AS observed_at,
    min(source_ref) AS source_ref
  FROM ranked
  WHERE date_rank<=3 AND authority_rank=1
  GROUP BY provider_session_date
  HAVING count(DISTINCT value)=1
  ORDER BY provider_session_date DESC
), selectable AS (
  SELECT * FROM resolved ORDER BY provider_session_date DESC LIMIT 2
)
SELECT coalesce((
  SELECT jsonb_build_object(
    'status',CASE
      WHEN requested_source_cutoff-observed_at<=interval '96 hours' THEN 'fresh'
      ELSE 'stale' END,
    'value',CASE
      WHEN requested_source_cutoff-observed_at<=interval '96 hours' THEN value
      ELSE NULL END,
    'observedAt',observed_at,
    'sourceRef',source_ref,
    'providerSessionDate',provider_session_date
  )
  FROM selectable
  ORDER BY provider_session_date DESC
  LIMIT 1
),jsonb_build_object(
  'status','missing','value',NULL,'observedAt',NULL,'sourceRef',NULL,
  'providerSessionDate',NULL
))
$fn$;

CREATE OR REPLACE FUNCTION opportunity_adjusted_price_evidence_v3_internal(
  requested_observation_id uuid,
  requested_anchor_session date,
  requested_source_cutoff timestamptz
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_observation public.opportunity_price_observations_v3%ROWTYPE;
  v_symbol text;
  v_session_count integer;
  v_action_days jsonb;
  v_factor double precision;
  v_evidence jsonb;
BEGIN
  SELECT * INTO STRICT v_observation
  FROM public.opportunity_price_observations_v3 observation
  WHERE observation.observation_id=requested_observation_id
    AND observation.source_timestamp<=requested_source_cutoff
    AND observation.collected_at<=requested_source_cutoff
    AND observation.recorded_at<=requested_source_cutoff;
  IF v_observation.session_id>requested_anchor_session THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_anchor_session'; END IF;
  SELECT selected.symbol INTO STRICT v_symbol
  FROM (
    SELECT instrument.symbol,row_number() OVER (
      PARTITION BY instrument.stock_id
      ORDER BY instrument.recorded_at DESC,instrument.source_timestamp DESC,
        instrument.instrument_authority_id
    ) AS authority_rank
    FROM public.stock_instruments_v3 instrument
    WHERE instrument.stock_id=v_observation.stock_id
      AND instrument.exchange=v_observation.exchange
      AND instrument.recorded_at<=requested_source_cutoff
      AND instrument.source_timestamp<=requested_source_cutoff
      AND instrument.valid_from<=requested_source_cutoff
      AND (instrument.valid_to IS NULL OR requested_source_cutoff<instrument.valid_to)
  ) selected
  WHERE selected.authority_rank=1;
  WITH bounded_sessions AS MATERIALIZED (
    SELECT session.session_id
    FROM public.opportunity_effective_taiwan_sessions_v3 session
    WHERE session.session_id>v_observation.session_id
      AND session.session_id<=requested_anchor_session
      AND session.canonical_cutoff<=requested_source_cutoff
    ORDER BY session.session_id
    LIMIT 253
  )
  SELECT count(*) INTO v_session_count FROM bounded_sessions;
  IF v_session_count=253 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
  WITH bounded_sessions AS MATERIALIZED (
    SELECT session.session_id
    FROM public.opportunity_effective_taiwan_sessions_v3 session
    WHERE session.session_id>v_observation.session_id
      AND session.session_id<=requested_anchor_session
      AND session.canonical_cutoff<=requested_source_cutoff
    ORDER BY session.session_id
    LIMIT 253
  ), resolved AS (
    SELECT bounded_sessions.session_id,exchange_session.session_authority_id,
      snapshot.snapshot_id,snapshot.dataset_hash,
      CASE WHEN event.snapshot_id IS NULL THEN NULL ELSE jsonb_build_array(
        event.event_kind,event.pre_action_reference_price,event.post_action_reference_price,
        event.feed_identity,event.source_row_ref
      ) END AS event_json,
      coalesce(event.daily_adjustment_factor,1.0) AS daily_factor
    FROM bounded_sessions
    JOIN LATERAL (
      SELECT session.session_authority_id
      FROM public.tw_trading_sessions_v3 session
      WHERE session.session_id=bounded_sessions.session_id
        AND session.market::text=v_observation.exchange::text
        AND session.status='completed'
        AND session.recorded_at<=requested_source_cutoff
        AND session.source_timestamp<=requested_source_cutoff
      ORDER BY session.recorded_at DESC,session.source_timestamp DESC,
        session.session_authority_id
      LIMIT 1
    ) exchange_session ON true
    JOIN LATERAL (
      SELECT candidate.snapshot_id,candidate.dataset_hash
      FROM public.opportunity_corporate_action_snapshots_v3 candidate
      WHERE candidate.exchange=v_observation.exchange
        AND candidate.session_id=bounded_sessions.session_id
        AND candidate.session_authority_id=exchange_session.session_authority_id
        AND candidate.corporate_action_version='tw-corporate-action-v3.1'
        AND candidate.collected_at<=requested_source_cutoff
        AND candidate.recorded_at<=requested_source_cutoff
        AND NOT EXISTS (
          SELECT 1
          FROM public.opportunity_corporate_action_snapshots_v3 tied
          WHERE tied.exchange=candidate.exchange
            AND tied.session_id=candidate.session_id
            AND tied.session_authority_id=candidate.session_authority_id
            AND tied.corporate_action_version=candidate.corporate_action_version
            AND tied.collected_at=candidate.collected_at
            AND tied.recorded_at=candidate.recorded_at
            AND tied.dataset_hash<>candidate.dataset_hash
        )
      ORDER BY candidate.collected_at DESC,candidate.recorded_at DESC,candidate.snapshot_id
      LIMIT 1
    ) snapshot ON true
    LEFT JOIN public.opportunity_corporate_action_events_v3 event
      ON event.snapshot_id=snapshot.snapshot_id AND event.symbol=v_symbol
  )
  SELECT
    coalesce(jsonb_agg(jsonb_build_array(
      session_id,session_authority_id,snapshot_id,dataset_hash,event_json,daily_factor
    ) ORDER BY session_id),'[]'::jsonb),
    coalesce(exp(sum(ln(daily_factor))),1.0)
  INTO v_action_days,v_factor
  FROM resolved;
  IF jsonb_array_length(v_action_days)<>v_session_count
    OR v_factor<=0 OR v_factor='Infinity'::double precision
  THEN RETURN NULL; END IF;
  v_evidence:=jsonb_build_array(
    'adjusted-price-evidence-v3.1',requested_anchor_session,
    v_observation.observation_id,v_observation.source_ref,
    v_observation.session_authority_id,v_observation.raw_open,v_observation.raw_high,
    v_observation.raw_low,v_observation.raw_close,v_action_days,v_factor,
    v_observation.raw_open*v_factor,v_observation.raw_high*v_factor,
    v_observation.raw_low*v_factor,v_observation.raw_close*v_factor
  );
  RETURN jsonb_build_object(
    'evidence',v_evidence,
    'ref',encode(extensions.digest(convert_to(
      regexp_replace(v_evidence::text,', ', ',', 'g'),'utf8'
    ),'sha256'),'hex')
  );
END
$fn$;

CREATE OR REPLACE FUNCTION opportunity_levenshtein_v3_internal(
  left_value text,right_value text
) RETURNS integer
LANGUAGE plpgsql IMMUTABLE STRICT SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  left_length integer:=char_length(left_value);
  right_length integer:=char_length(right_value);
  previous_row integer[];
  current_row integer[];
  left_index integer;
  right_index integer;
  substitution_cost integer;
BEGIN
  IF left_length>40 OR right_length>40 THEN
    RETURN 41;
  END IF;
  previous_row:=ARRAY(
    SELECT value FROM generate_series(0,right_length) value ORDER BY value
  );
  FOR left_index IN 1..left_length LOOP
    current_row:=ARRAY[left_index];
    FOR right_index IN 1..right_length LOOP
      substitution_cost:=CASE
        WHEN substr(left_value,left_index,1)=substr(right_value,right_index,1)
        THEN 0 ELSE 1 END;
      current_row:=array_append(current_row,least(
        current_row[right_index]+1,
        previous_row[right_index+1]+1,
        previous_row[right_index]+substitution_cost
      ));
    END LOOP;
    previous_row:=current_row;
  END LOOP;
  RETURN previous_row[right_length+1];
END
$fn$;

CREATE OR REPLACE FUNCTION opportunity_manifest_native_rows_v3_internal(
  requested_run_id uuid,
  requested_manifest_id uuid,
  requested_kind opportunity_manifest_kind_v3,
  requested_section opportunity_manifest_section_key_v3,
  requested_offset integer,
  requested_limit integer
) RETURNS TABLE(
  native_ordinal bigint,
  terminal_code text,
  native_row jsonb
)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_cutoff timestamptz;
  v_symbol_count integer;
BEGIN
  IF requested_offset<0 OR requested_limit NOT BETWEEN 1 AND 2001 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  SELECT run.source_cutoff INTO STRICT v_cutoff
  FROM public.opportunity_runs run
  JOIN public.opportunity_manifests_v3 manifest
    ON manifest.manifest_id=requested_manifest_id
    AND manifest.manifest_kind=requested_kind
    AND manifest.source_cutoff=run.source_cutoff
  WHERE run.run_id=requested_run_id;

  IF requested_kind='candidate_financial' THEN
    SELECT count(*) INTO v_symbol_count
    FROM (
      SELECT symbol_value.value
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      CROSS JOIN LATERAL jsonb_array_elements_text(pair->1) symbol_value(value)
      WHERE manifest.manifest_id=requested_manifest_id
        AND pair->>0='orderedSymbols'
      ORDER BY symbol_value.value
      LIMIT 21
    ) bounded_symbols;
    IF v_symbol_count>20 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='deep_candidate_bound_exceeded';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM (
        SELECT instrument.stock_id,fact.observation_family,
          count(*) AS selected_count
        FROM (
          SELECT DISTINCT (roster.payload_json->>1)::uuid AS stock_id
          FROM public.opportunity_manifests_v3 manifest
          CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
          CROSS JOIN LATERAL jsonb_array_elements_text(pair->1) symbol_value(value)
          JOIN public.opportunity_run_manifest_inputs roster_binding
            ON roster_binding.run_id=requested_run_id
            AND roster_binding.input_role='instrument_roster'
            AND roster_binding.ordinal=0
          JOIN public.opportunity_manifest_rows_v3 roster
            ON roster.manifest_id=roster_binding.manifest_id
            AND roster.section_key='rows'
            AND roster.payload_json->>2=symbol_value.value
          WHERE manifest.manifest_id=requested_manifest_id
            AND pair->>0='orderedSymbols'
          ORDER BY (roster.payload_json->>1)::uuid
          LIMIT 21
        ) instrument
        CROSS JOIN LATERAL (
          (
            SELECT 'analyst_estimate'::text AS observation_family
            FROM public.opportunity_financial_facts_v3 candidate
            JOIN public.source_publication_verifications_v3 verification
              ON verification.evidence_ref=candidate.source_ref
              AND verification.recorded_at<=v_cutoff
              AND verification.collected_at<=v_cutoff
              AND verification.institution_identity IS NOT NULL
            WHERE candidate.stock_id=instrument.stock_id
              AND candidate.fact_key IN (
                'quarterly_diluted_eps','quarterly_ebitda','quarterly_revenue',
                'book_value_per_share'
              )
              AND candidate.estimate_kind='analyst_estimate'
              AND candidate.recorded_at<=v_cutoff
              AND candidate.filing_published_at<=v_cutoff
              AND candidate.source_timestamp<=v_cutoff
              AND candidate.collected_at<=v_cutoff
            ORDER BY candidate.source_timestamp DESC,
              verification.institution_identity,candidate.source_ref,candidate.fact_id
            LIMIT 101
          )
          UNION ALL
          (
            SELECT 'broker_consensus'::text AS observation_family
            FROM public.opportunity_financial_facts_v3 candidate
            JOIN public.source_publication_verifications_v3 verification
              ON verification.evidence_ref=candidate.source_ref
              AND verification.recorded_at<=v_cutoff
              AND verification.collected_at<=v_cutoff
              AND verification.institution_identity IS NOT NULL
            WHERE candidate.stock_id=instrument.stock_id
              AND candidate.fact_key='broker_target_price'
              AND candidate.estimate_kind='broker_consensus'
              AND candidate.recorded_at<=v_cutoff
              AND candidate.filing_published_at<=v_cutoff
              AND candidate.source_timestamp<=v_cutoff
              AND candidate.collected_at<=v_cutoff
            ORDER BY candidate.source_timestamp DESC,
              verification.institution_identity,candidate.source_ref,candidate.fact_id
            LIMIT 101
          )
        ) fact
        GROUP BY instrument.stock_id,fact.observation_family
      ) bounded_public_research
      WHERE bounded_public_research.selected_count>100
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    RETURN QUERY
    WITH symbols AS MATERIALIZED (
      SELECT symbol_value.value AS symbol,
        (symbol_value.ordinal-1)::integer AS symbol_ordinal
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      CROSS JOIN LATERAL jsonb_array_elements_text(pair->1)
        WITH ORDINALITY symbol_value(value,ordinal)
      WHERE manifest.manifest_id=requested_manifest_id
        AND pair->>0='orderedSymbols'
      ORDER BY symbol_value.ordinal
      LIMIT 21
    ), instruments AS MATERIALIZED (
      SELECT symbol.symbol,symbol.symbol_ordinal,instrument.stock_id
      FROM symbols symbol
      JOIN LATERAL (
        SELECT selected.stock_id
        FROM (
          SELECT authority.stock_id,authority.listing_status,authority.instrument_type,
            authority.valid_to,row_number() OVER (
              PARTITION BY authority.stock_id
              ORDER BY authority.recorded_at DESC,authority.source_timestamp DESC,
                authority.instrument_authority_id
            ) AS authority_rank
          FROM public.stock_instruments_v3 authority
          WHERE authority.symbol=symbol.symbol
            AND authority.recorded_at<=v_cutoff
            AND authority.source_timestamp<=v_cutoff
            AND authority.valid_from<=v_cutoff
        ) selected
        WHERE selected.authority_rank=1
          AND selected.listing_status='active'
          AND selected.instrument_type='common_stock'
          AND (selected.valid_to IS NULL OR v_cutoff<selected.valid_to)
        ORDER BY selected.stock_id
        LIMIT 2
      ) instrument ON true
    ), raw_facts AS MATERIALIZED (
      SELECT instrument.symbol,instrument.symbol_ordinal,fact.*
      FROM instruments instrument
      CROSS JOIN LATERAL (
        (
          SELECT observation.*
          FROM public.opportunity_financial_facts_v3 observation
          WHERE observation.stock_id=instrument.stock_id
            AND observation.fact_key='monthly_revenue'
            AND observation.estimate_kind='reported'
            AND observation.recorded_at<=v_cutoff
            AND observation.filing_published_at<=v_cutoff
            AND observation.source_timestamp<=v_cutoff
            AND observation.collected_at<=v_cutoff
          ORDER BY observation.period_end DESC,observation.filing_published_at DESC,
            observation.source_timestamp DESC,observation.collected_at DESC,
            observation.recorded_at DESC,observation.fact_id
          LIMIT 17
        )
        UNION ALL
        (
          SELECT observation.*
          FROM public.opportunity_financial_facts_v3 observation
          JOIN public.source_publication_verifications_v3 verification
            ON verification.evidence_ref=observation.source_ref
            AND verification.recorded_at<=v_cutoff
            AND verification.collected_at<=v_cutoff
            AND verification.institution_identity IS NOT NULL
          WHERE observation.stock_id=instrument.stock_id
            AND observation.fact_key IN (
              'quarterly_diluted_eps','quarterly_ebitda','quarterly_revenue',
              'book_value_per_share'
            )
            AND observation.estimate_kind='analyst_estimate'
            AND observation.recorded_at<=v_cutoff
            AND observation.filing_published_at<=v_cutoff
            AND observation.source_timestamp<=v_cutoff
            AND observation.collected_at<=v_cutoff
          ORDER BY observation.source_timestamp DESC,
            verification.institution_identity,observation.source_ref,
            observation.fact_id
          LIMIT 101
        )
        UNION ALL
        (
          SELECT observation.*
          FROM public.opportunity_financial_facts_v3 observation
          JOIN public.source_publication_verifications_v3 verification
            ON verification.evidence_ref=observation.source_ref
            AND verification.recorded_at<=v_cutoff
            AND verification.collected_at<=v_cutoff
            AND verification.institution_identity IS NOT NULL
          WHERE observation.stock_id=instrument.stock_id
            AND observation.fact_key='broker_target_price'
            AND observation.estimate_kind='broker_consensus'
            AND observation.recorded_at<=v_cutoff
            AND observation.filing_published_at<=v_cutoff
            AND observation.source_timestamp<=v_cutoff
            AND observation.collected_at<=v_cutoff
          ORDER BY observation.source_timestamp DESC,
            verification.institution_identity,observation.source_ref,
            observation.fact_id
          LIMIT 101
        )
        UNION ALL
        (
          SELECT observation.*
          FROM (VALUES
            ('quarterly_revenue'::public.financial_fact_key_v3),
            ('quarterly_gross_profit'::public.financial_fact_key_v3),
            ('quarterly_operating_income'::public.financial_fact_key_v3),
            ('quarterly_net_income'::public.financial_fact_key_v3),
            ('quarterly_diluted_eps'::public.financial_fact_key_v3),
            ('quarterly_ebitda'::public.financial_fact_key_v3)
          ) requested_fact(fact_key)
          CROSS JOIN LATERAL (
            SELECT candidate.*
            FROM public.opportunity_financial_facts_v3 candidate
            WHERE candidate.stock_id=instrument.stock_id
              AND candidate.fact_key=requested_fact.fact_key
              AND candidate.estimate_kind='reported'
              AND candidate.recorded_at<=v_cutoff
              AND candidate.filing_published_at<=v_cutoff
              AND candidate.source_timestamp<=v_cutoff
              AND candidate.collected_at<=v_cutoff
            ORDER BY candidate.period_end DESC,candidate.filing_published_at DESC,
              candidate.source_timestamp DESC,candidate.collected_at DESC,
              candidate.recorded_at DESC,candidate.fact_id
            LIMIT 13
          ) observation
        )
        UNION ALL
        (
          SELECT observation.*
          FROM (VALUES
            ('pe_multiple'::public.financial_fact_key_v3),
            ('pb_multiple'::public.financial_fact_key_v3),
            ('ev_ebitda_multiple'::public.financial_fact_key_v3),
            ('ev_sales_multiple'::public.financial_fact_key_v3)
          ) requested_fact(fact_key)
          CROSS JOIN LATERAL (
            SELECT candidate.*
            FROM public.opportunity_financial_facts_v3 candidate
            WHERE candidate.stock_id=instrument.stock_id
              AND candidate.fact_key=requested_fact.fact_key
              AND candidate.estimate_kind='reported'
              AND candidate.recorded_at<=v_cutoff
              AND candidate.filing_published_at<=v_cutoff
              AND candidate.source_timestamp<=v_cutoff
              AND candidate.collected_at<=v_cutoff
            ORDER BY candidate.period_end DESC,candidate.filing_published_at DESC,
              candidate.source_timestamp DESC,candidate.collected_at DESC,
              candidate.recorded_at DESC,candidate.fact_id
            LIMIT 21
          ) observation
        )
        UNION ALL
        (
          SELECT observation.*
          FROM (VALUES
            ('quarterly_operating_expense'::public.financial_fact_key_v3),
            ('quarterly_non_operating_income'::public.financial_fact_key_v3),
            ('quarterly_pretax_income'::public.financial_fact_key_v3),
            ('quarterly_income_tax_expense'::public.financial_fact_key_v3),
            ('quarterly_noncontrolling_interest'::public.financial_fact_key_v3),
            ('quarterly_net_income_attributable_to_common'::public.financial_fact_key_v3),
            ('diluted_weighted_average_shares'::public.financial_fact_key_v3),
            ('cash_and_equivalents'::public.financial_fact_key_v3),
            ('total_debt'::public.financial_fact_key_v3),
            ('total_equity'::public.financial_fact_key_v3),
            ('total_assets'::public.financial_fact_key_v3),
            ('invested_capital'::public.financial_fact_key_v3),
            ('net_asset_value'::public.financial_fact_key_v3),
            ('operating_cash_flow'::public.financial_fact_key_v3),
            ('capital_expenditure'::public.financial_fact_key_v3),
            ('interest_expense'::public.financial_fact_key_v3),
            ('shares_outstanding'::public.financial_fact_key_v3),
            ('depreciation_amortization'::public.financial_fact_key_v3),
            ('diluted_shares'::public.financial_fact_key_v3),
            ('roe'::public.financial_fact_key_v3),
            ('net_debt'::public.financial_fact_key_v3)
          ) requested_fact(fact_key)
          CROSS JOIN LATERAL (
            SELECT candidate.*
            FROM public.opportunity_financial_facts_v3 candidate
            WHERE candidate.stock_id=instrument.stock_id
              AND candidate.fact_key=requested_fact.fact_key
              AND candidate.estimate_kind='reported'
              AND candidate.recorded_at<=v_cutoff
              AND candidate.filing_published_at<=v_cutoff
              AND candidate.source_timestamp<=v_cutoff
              AND candidate.collected_at<=v_cutoff
            ORDER BY candidate.period_end DESC,candidate.filing_published_at DESC,
              candidate.source_timestamp DESC,candidate.collected_at DESC,
              candidate.recorded_at DESC,candidate.fact_id
            LIMIT 2
          ) observation
        )
        UNION ALL
        (
          SELECT observation.*
          FROM public.opportunity_financial_facts_v3 observation
          WHERE observation.stock_id=instrument.stock_id
            AND observation.fact_key='book_value_per_share'
            AND observation.estimate_kind='reported'
            AND observation.recorded_at<=v_cutoff
            AND observation.filing_published_at<=v_cutoff
            AND observation.source_timestamp<=v_cutoff
            AND observation.collected_at<=v_cutoff
          ORDER BY observation.period_end DESC,observation.filing_published_at DESC,
            observation.source_timestamp DESC,observation.collected_at DESC,
            observation.recorded_at DESC,observation.fact_id
          LIMIT 10
        )
      ) fact
    ), normalized AS (
      SELECT raw_facts.*,verification.institution_identity,
        CASE unit
          WHEN 'TWD_thousand' THEN value*1000
          WHEN 'TWD_million' THEN value*1000000
          WHEN 'thousand_shares' THEN value*1000
          ELSE value
        END AS normalized_value,
        CASE unit
          WHEN 'TWD_thousand' THEN 'TWD'
          WHEN 'TWD_million' THEN 'TWD'
          WHEN 'thousand_shares' THEN 'share'
          ELSE unit::text
        END AS normalized_unit,
        dense_rank() OVER (
          PARTITION BY symbol,fact_key,period_start,period_end,duration_kind,
            estimate_kind,estimate_horizon,coalesce(verification.institution_identity,'')
          ORDER BY
            CASE authority_tier WHEN 'official_filing' THEN 0 ELSE 1 END,
            filing_published_at DESC,source_timestamp DESC,collected_at DESC,
            recorded_at DESC,coalesce(filing_restatement_id,'') DESC
        ) AS precedence_rank
      FROM raw_facts
      LEFT JOIN LATERAL (
        SELECT candidate.institution_identity
        FROM public.source_publication_verifications_v3 candidate
        WHERE candidate.evidence_ref=raw_facts.source_ref
          AND candidate.recorded_at<=v_cutoff
          AND candidate.collected_at<=v_cutoff
        ORDER BY candidate.recorded_at DESC,candidate.verification_id
        LIMIT 1
      ) verification ON true
    ), top_rows AS (
      SELECT normalized.*,
        count(*) OVER (
          PARTITION BY symbol,fact_key,period_start,period_end,duration_kind,
            estimate_kind,estimate_horizon,coalesce(institution_identity,'')
        ) AS tied_count
      FROM normalized
      WHERE precedence_rank=1
    ), conflicts AS (
      SELECT symbol,fact_key,period_start,period_end,duration_kind,
        estimate_kind,estimate_horizon,institution_identity,
        count(DISTINCT jsonb_build_array(normalized_value,normalized_unit)) AS value_count
      FROM top_rows
      GROUP BY symbol,fact_key,period_start,period_end,duration_kind,
        estimate_kind,estimate_horizon,institution_identity
    ), terminal_head AS (
      SELECT DISTINCT ON (
        top.symbol,top.fact_key,top.period_start,top.period_end,top.duration_kind
        ,top.estimate_kind,top.estimate_horizon,top.institution_identity
      )
        top.*,conflict.value_count
      FROM top_rows top
      JOIN conflicts conflict USING(
        symbol,fact_key,period_start,period_end,duration_kind,
        estimate_kind,estimate_horizon,institution_identity
      )
      ORDER BY top.symbol,top.fact_key,top.period_start,top.period_end,
        top.duration_kind,top.estimate_kind,top.estimate_horizon,
        top.institution_identity,top.source_ref
    ), terminal AS (
      SELECT terminal_head.*,
        row_number() OVER (
          PARTITION BY terminal_head.symbol,terminal_head.fact_key,
            terminal_head.estimate_kind,terminal_head.estimate_horizon,
            terminal_head.institution_identity
          ORDER BY terminal_head.period_end DESC,
            terminal_head.period_start DESC NULLS LAST,
            terminal_head.duration_kind,terminal_head.source_ref
        ) AS history_rank
      FROM terminal_head
    ), bounded AS (
      SELECT terminal.*,
        CASE
          WHEN fact_key='monthly_revenue' THEN history_rank<=16
          WHEN fact_key IN (
            'quarterly_revenue','quarterly_gross_profit','quarterly_operating_income',
            'quarterly_net_income','quarterly_diluted_eps','quarterly_ebitda'
          ) THEN history_rank<=12
          WHEN fact_key IN (
            'pe_multiple','pb_multiple','ev_ebitda_multiple','ev_sales_multiple'
          ) THEN history_rank<=20
          WHEN fact_key='broker_target_price' THEN history_rank<=100
          WHEN fact_key IN (
            'quarterly_diluted_eps','quarterly_ebitda','quarterly_revenue',
            'book_value_per_share'
          ) AND estimate_kind<>'reported' THEN history_rank<=100
          WHEN fact_key='book_value_per_share' THEN history_rank<=9
          ELSE history_rank<=1
        END AS within_history_bound
      FROM terminal
    ), rows_by_section AS (
      SELECT 'selected_facts'::public.opportunity_manifest_section_key_v3 AS section_key,
        symbol_ordinal,fact_key,period_end,period_start,duration_kind,source_ref,
        NULL::text AS reason,
        jsonb_build_array(
          symbol,fact_key,period_start,period_end,duration_kind,
          normalized_value,normalized_unit,authority_tier,filing_published_at,
          source_timestamp,collected_at,recorded_at,source_ref,filing_restatement_id,
          estimate_kind,estimate_horizon,institution_identity,
          CASE WHEN estimate_kind='reported' THEN 'reported_fact'
            ELSE 'eligible_verified_estimate' END
        ) AS row_payload
      FROM bounded
      WHERE within_history_bound AND value_count=1
      UNION ALL
      SELECT 'excluded_facts',symbol_ordinal,fact_key,period_end,period_start,
        duration_kind,source_ref,'conflicting_point_in_time_fact',
        jsonb_build_array(
          symbol,fact_key,period_start,period_end,duration_kind,
          normalized_value,normalized_unit,authority_tier,filing_published_at,
          source_timestamp,collected_at,recorded_at,source_ref,filing_restatement_id,
          estimate_kind,estimate_horizon,institution_identity,
          CASE WHEN estimate_kind='reported' THEN 'reported_fact'
            ELSE 'eligible_verified_estimate' END,
          'conflicting_point_in_time_fact'
        )
      FROM bounded
      WHERE within_history_bound AND value_count>1
    ), candidate_conservation AS (
      SELECT symbol.symbol_ordinal,
        jsonb_build_array(
          symbol.symbol,
          count(rows_by_section.row_payload),
          count(*) FILTER (WHERE rows_by_section.section_key='selected_facts'),
          count(*) FILTER (WHERE rows_by_section.section_key='excluded_facts'),
          jsonb_build_object(
            'conflicting_point_in_time_fact',
            count(*) FILTER (WHERE rows_by_section.reason='conflicting_point_in_time_fact'),
            'invalid_unit',0
          )
        ) AS row_payload
      FROM symbols symbol
      LEFT JOIN rows_by_section ON rows_by_section.symbol_ordinal=symbol.symbol_ordinal
      GROUP BY symbol.symbol_ordinal,symbol.symbol
    ), ordered AS (
      SELECT row_number() OVER (
          ORDER BY symbol_ordinal,fact_key,period_end DESC,period_start,
            duration_kind,source_ref
        )-1 AS ordinal,section_key,reason,row_payload
      FROM rows_by_section
      WHERE section_key=requested_section
      UNION ALL
      SELECT row_number() OVER (ORDER BY symbol_ordinal)-1,
        'conservation'::public.opportunity_manifest_section_key_v3,NULL,row_payload
      FROM candidate_conservation
      WHERE requested_section='conservation'
    )
    SELECT ordered.ordinal::bigint,ordered.reason,ordered.row_payload
    FROM ordered
    ORDER BY ordered.ordinal
    OFFSET requested_offset
    LIMIT requested_limit;
    RETURN;
  ELSIF requested_kind='peer_authority' THEN
    SELECT count(*) INTO v_symbol_count
    FROM (
      SELECT registry.stream_key_hash
      FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='peer_relationship'
      ORDER BY registry.stream_key_hash,registry.stream_key_canonical
      LIMIT 100001
    ) bounded_registry;
    IF v_symbol_count>100000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.opportunity_authority_stream_registry_v3 registry
      CROSS JOIN LATERAL (
        SELECT count(*) AS retained_count
        FROM (
          SELECT relationship.relationship_authority_id
          FROM public.stock_peer_relationships_v3 relationship
          WHERE relationship.supplier_stock_id=(
              convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
            )::uuid
            AND relationship.customer_stock_id=(
              convert_from(registry.stream_key_canonical,'utf8')::jsonb->>2
            )::uuid
            AND relationship.relationship_kind='supply_chain'
          ORDER BY relationship.recorded_at DESC,relationship.relationship_authority_id
          LIMIT 65
        ) bounded
      ) stream
      WHERE registry.family='peer_relationship' AND stream.retained_count>64
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    IF EXISTS (
      WITH bounded_registry AS MATERIALIZED (
        SELECT stream_key_hash,stream_key_canonical
        FROM public.opportunity_authority_stream_registry_v3
        WHERE family='peer_relationship'
        ORDER BY stream_key_hash,stream_key_canonical LIMIT 100001
      ), raw AS MATERIALIZED (
        SELECT registry.stream_key_hash,relationship.*
        FROM bounded_registry registry
        CROSS JOIN LATERAL (
          SELECT retained.*
          FROM public.stock_peer_relationships_v3 retained
          WHERE retained.supplier_stock_id=(
              convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
            )::uuid
            AND retained.customer_stock_id=(
              convert_from(registry.stream_key_canonical,'utf8')::jsonb->>2
            )::uuid
            AND retained.relationship_kind='supply_chain'
          ORDER BY retained.recorded_at DESC,retained.relationship_authority_id LIMIT 65
        ) relationship
      ), greatest_time AS (
        SELECT stream_key_hash,max(recorded_at) AS recorded_at
        FROM raw
        WHERE recorded_at<=v_cutoff AND source_timestamp<=v_cutoff
          AND approved_at<=v_cutoff AND valid_from<=v_cutoff
        GROUP BY stream_key_hash
      )
      SELECT 1
      FROM raw JOIN greatest_time USING(stream_key_hash,recorded_at)
      GROUP BY stream_key_hash
      HAVING count(DISTINCT jsonb_build_array(
        supplier_instrument_authority_id,supplier_stock_id,
        customer_instrument_authority_id,customer_stock_id,relationship_kind,
        source_timestamp,approved_at,valid_from,valid_to,status,evidence_ref,
        reviewer_principal_id
      ))>1
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='authority_revision_conflict';
    END IF;
    RETURN QUERY
    WITH bounded_registry AS MATERIALIZED (
      SELECT stream_key_hash,stream_key_canonical
      FROM public.opportunity_authority_stream_registry_v3
      WHERE family='peer_relationship'
      ORDER BY stream_key_hash,stream_key_canonical LIMIT 100001
    ), raw AS MATERIALIZED (
      SELECT registry.stream_key_hash,relationship.*
      FROM bounded_registry registry
      CROSS JOIN LATERAL (
        SELECT retained.*
        FROM public.stock_peer_relationships_v3 retained
        WHERE retained.supplier_stock_id=(
            convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
          )::uuid
          AND retained.customer_stock_id=(
            convert_from(registry.stream_key_canonical,'utf8')::jsonb->>2
          )::uuid
          AND retained.relationship_kind='supply_chain'
        ORDER BY retained.recorded_at DESC,retained.relationship_authority_id LIMIT 65
      ) relationship
    ), dependencies AS (
      SELECT
        min(input.manifest_id::text) FILTER (WHERE input.input_role='instrument_roster')::uuid
          AS roster_manifest_id,
        min(input.manifest_id::text) FILTER (
          WHERE input.input_role='peer_reviewer_allowlist'
        )::uuid AS reviewer_manifest_id
      FROM public.opportunity_run_manifest_inputs input
      WHERE input.run_id=requested_run_id
    ), latest AS MATERIALIZED (
      SELECT DISTINCT ON (raw.stream_key_hash) raw.*
      FROM raw
      WHERE raw.recorded_at<=v_cutoff AND raw.source_timestamp<=v_cutoff
        AND raw.approved_at<=v_cutoff AND raw.valid_from<=v_cutoff
      ORDER BY raw.stream_key_hash,raw.recorded_at DESC,raw.relationship_authority_id
    ), classified AS (
      SELECT latest.*,supplier.instrument_authority_id AS supplier_authority_id,
        supplier.symbol AS roster_supplier,
        customer.instrument_authority_id AS customer_authority_id,
        customer.symbol AS roster_customer,
        CASE
          WHEN latest.source_timestamp>latest.approved_at THEN 'source_after_approval'
          WHEN latest.status<>'active' THEN 'inactive_status'
          WHEN latest.valid_from>v_cutoff THEN 'not_yet_valid'
          WHEN latest.valid_to IS NOT NULL AND latest.valid_to<=v_cutoff THEN 'expired'
          WHEN latest.supplier_stock_id=latest.customer_stock_id THEN 'self_edge'
          WHEN supplier.symbol IS NULL THEN 'ineligible_supplier'
          WHEN customer.symbol IS NULL THEN 'ineligible_customer'
          WHEN NOT EXISTS (
            SELECT 1
            FROM dependencies dependency
            JOIN public.opportunity_manifest_rows_v3 reviewer
              ON reviewer.manifest_id=dependency.reviewer_manifest_id
              AND reviewer.section_key='rows'
            WHERE reviewer.payload_json->>1=latest.reviewer_principal_id::text
              AND reviewer.payload_json->>5='active'
              AND (reviewer.payload_json->>3)::timestamptz<=v_cutoff
              AND (
                reviewer.payload_json->>4 IS NULL
                OR v_cutoff<(reviewer.payload_json->>4)::timestamptz
              )
          ) THEN 'reviewer_not_allowed'
          WHEN NOT EXISTS (
            SELECT 1 FROM public.source_publication_verifications_v3 verification
            WHERE verification.evidence_ref=latest.evidence_ref
              AND verification.recorded_at<=v_cutoff
              AND verification.collected_at<=v_cutoff
          ) THEN 'unverified_evidence'
          ELSE NULL
        END AS exclusion_reason
      FROM latest CROSS JOIN dependencies
      LEFT JOIN LATERAL (
        SELECT (row.payload_json->>0)::uuid AS instrument_authority_id,
          row.payload_json->>2 AS symbol
        FROM public.opportunity_manifest_rows_v3 row
        WHERE row.manifest_id=dependencies.roster_manifest_id
          AND row.section_key='rows'
          AND (row.payload_json->>1)::uuid=latest.supplier_stock_id
          AND row.payload_json->>4='common_stock'
          AND row.payload_json->>5='active'
          AND (row.payload_json->>9)::timestamptz<=v_cutoff
          AND (row.payload_json->>10 IS NULL OR v_cutoff<(row.payload_json->>10)::timestamptz)
        ORDER BY row.row_ordinal LIMIT 2
      ) supplier ON true
      LEFT JOIN LATERAL (
        SELECT (row.payload_json->>0)::uuid AS instrument_authority_id,
          row.payload_json->>2 AS symbol
        FROM public.opportunity_manifest_rows_v3 row
        WHERE row.manifest_id=dependencies.roster_manifest_id
          AND row.section_key='rows'
          AND (row.payload_json->>1)::uuid=latest.customer_stock_id
          AND row.payload_json->>4='common_stock'
          AND row.payload_json->>5='active'
          AND (row.payload_json->>9)::timestamptz<=v_cutoff
          AND (row.payload_json->>10 IS NULL OR v_cutoff<(row.payload_json->>10)::timestamptz)
        ORDER BY row.row_ordinal LIMIT 2
      ) customer ON true
    ), payloads AS (
      SELECT classified.*,
        jsonb_build_array(
          relationship_authority_id,supplier_instrument_authority_id,
          supplier_stock_id,roster_supplier,customer_instrument_authority_id,
          customer_stock_id,roster_customer,'supply_chain',source_timestamp,
          approved_at,valid_from,valid_to,status,evidence_ref,
          reviewer_principal_id,recorded_at
        ) AS selected_payload,
        jsonb_build_array(
          relationship_authority_id,supplier_instrument_authority_id,
          supplier_stock_id,roster_supplier,customer_instrument_authority_id,
          customer_stock_id,roster_customer,'supply_chain',source_timestamp,
          approved_at,valid_from,valid_to,status,evidence_ref,
          reviewer_principal_id,recorded_at,exclusion_reason
        ) AS excluded_payload
      FROM classified
    ), native AS (
      SELECT 'selected_rows'::public.opportunity_manifest_section_key_v3 AS section_key,
        row_number() OVER (
          ORDER BY roster_supplier,roster_customer,source_timestamp DESC,
            approved_at DESC,recorded_at DESC,evidence_ref,relationship_authority_id
        )-1 AS ordinal,NULL::text AS reason,selected_payload AS payload
      FROM payloads WHERE exclusion_reason IS NULL
      UNION ALL
      SELECT 'excluded_rows',row_number() OVER (
          ORDER BY exclusion_reason,relationship_authority_id
        )-1,exclusion_reason,excluded_payload
      FROM payloads WHERE exclusion_reason IS NOT NULL
    )
    SELECT native.ordinal::bigint,native.reason,native.payload
    FROM native WHERE native.section_key=requested_section
    ORDER BY native.ordinal OFFSET requested_offset LIMIT requested_limit;
    RETURN;
  ELSIF requested_kind='sector_valuation_reference' THEN
    RETURN QUERY
    WITH header AS (
      SELECT
        max(pair->>1) FILTER (WHERE pair->>0='rosterManifestHash') AS roster_hash,
        max(pair->>1) FILTER (WHERE pair->>0='taxonomyAssignmentManifestHash')
          AS taxonomy_hash
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      WHERE manifest.manifest_id=requested_manifest_id
    ), dependencies AS (
      SELECT
        min(input.manifest_id::text) FILTER (
          WHERE input.input_role='instrument_roster'
        )::uuid AS roster_manifest_id,
        min(input.manifest_id::text) FILTER (
          WHERE input.input_role='taxonomy_assignment'
        )::uuid AS taxonomy_manifest_id
      FROM public.opportunity_run_manifest_inputs input
      WHERE input.run_id=requested_run_id
    ), roster AS MATERIALIZED (
      SELECT (row.payload_json->>1)::uuid AS stock_id,row.payload_json->>2 AS symbol
      FROM dependencies dependency
      JOIN public.opportunity_manifest_rows_v3 row
        ON row.manifest_id=dependency.roster_manifest_id AND row.section_key='rows'
      WHERE row.payload_json->>4='common_stock' AND row.payload_json->>5='active'
        AND (row.payload_json->>9)::timestamptz<=v_cutoff
        AND (row.payload_json->>10 IS NULL OR v_cutoff<(row.payload_json->>10)::timestamptz)
      ORDER BY row.payload_json->>2
      LIMIT 20001
    ), sectors AS MATERIALIZED (
      SELECT roster.*,coalesce(sector.canonical_sector,'unknown') AS canonical_sector
      FROM roster
      LEFT JOIN LATERAL (
        SELECT row.payload_json->>4 AS canonical_sector
        FROM dependencies dependency
        JOIN public.opportunity_manifest_rows_v3 row
          ON row.manifest_id=dependency.taxonomy_manifest_id AND row.section_key='rows'
        WHERE (row.payload_json->>1)::uuid=roster.stock_id
          AND row.payload_json->>10='active'
          AND (row.payload_json->>7)::timestamptz<=v_cutoff
          AND (row.payload_json->>8 IS NULL OR v_cutoff<(row.payload_json->>8)::timestamptz)
        ORDER BY row.row_ordinal LIMIT 2
      ) sector ON true
    ), methods AS (
      SELECT * FROM (VALUES
        (1,'pe','pe_multiple'::public.financial_fact_key_v3),
        (2,'pb_roe','pb_multiple'::public.financial_fact_key_v3),
        (3,'ev_ebitda','ev_ebitda_multiple'::public.financial_fact_key_v3),
        (4,'ev_sales','ev_sales_multiple'::public.financial_fact_key_v3)
      ) method(method_ordinal,method,fact_key)
    ), observations AS MATERIALIZED (
      SELECT sector.stock_id,sector.symbol,sector.canonical_sector,method.*,
        selected.value,selected.source_timestamp,selected.recorded_at,
        selected.source_ref,selected.filing_restatement_id,selected.value_count,
        roe.value AS roe
      FROM sectors sector CROSS JOIN methods method
      LEFT JOIN LATERAL (
        SELECT ranked.*,count(*) OVER () AS value_count
        FROM (
          SELECT fact.*,dense_rank() OVER (
            ORDER BY CASE fact.authority_tier WHEN 'official_filing' THEN 0 ELSE 1 END,
              fact.filing_published_at DESC,fact.source_timestamp DESC,
              fact.collected_at DESC,fact.recorded_at DESC,
              coalesce(fact.filing_restatement_id,'') DESC
          ) AS precedence_rank
          FROM public.opportunity_financial_facts_v3 fact
          WHERE fact.stock_id=sector.stock_id AND fact.fact_key=method.fact_key
            AND fact.filing_published_at<=v_cutoff AND fact.source_timestamp<=v_cutoff
            AND fact.collected_at<=v_cutoff AND fact.recorded_at<=v_cutoff
          ORDER BY fact.period_end DESC,fact.filing_published_at DESC,
            fact.source_timestamp DESC,fact.recorded_at DESC,fact.fact_id
          LIMIT 101
        ) ranked
        WHERE ranked.precedence_rank=1
        ORDER BY ranked.source_ref LIMIT 1
      ) selected ON true
      LEFT JOIN LATERAL (
        SELECT fact.value
        FROM public.opportunity_financial_facts_v3 fact
        WHERE fact.stock_id=sector.stock_id AND fact.fact_key='roe'
          AND fact.filing_published_at<=v_cutoff AND fact.source_timestamp<=v_cutoff
          AND fact.collected_at<=v_cutoff AND fact.recorded_at<=v_cutoff
        ORDER BY CASE fact.authority_tier WHEN 'official_filing' THEN 0 ELSE 1 END,
          fact.period_end DESC,fact.filing_published_at DESC,fact.source_timestamp DESC,
          fact.recorded_at DESC,fact.fact_id
        LIMIT 1
      ) roe ON true
    ), terminal AS (
      SELECT observations.*,
        CASE
          WHEN canonical_sector='unknown' THEN 'unknown_sector'
          WHEN value_count>1 THEN 'provider_conflict'
          WHEN value IS NULL THEN 'missing_observation'
          WHEN NOT (value>'-Infinity'::double precision AND value<'Infinity'::double precision)
            THEN 'non_finite_value'
          WHEN value<=0 THEN 'non_positive_multiple'
          WHEN method='pb_roe' AND (roe IS NULL OR roe<=0) THEN 'missing_positive_roe'
          ELSE NULL
        END AS exclusion_reason
      FROM observations
    ), included AS MATERIALIZED (
      SELECT terminal.*
      FROM terminal WHERE exclusion_reason IS NULL
    ), aggregate_values AS (
      SELECT canonical_sector,method,count(*)::integer AS included_count,
        percentile_cont(0.10) WITHIN GROUP (ORDER BY value) AS p10,
        percentile_cont(0.50) WITHIN GROUP (ORDER BY value) AS p50,
        percentile_cont(0.90) WITHIN GROUP (ORDER BY value) AS p90
      FROM included GROUP BY canonical_sector,method
    ), native AS (
      SELECT 'included_rows'::public.opportunity_manifest_section_key_v3 AS section_key,
        row_number() OVER (
          ORDER BY method_ordinal,canonical_sector,symbol,source_timestamp,recorded_at,source_ref
        )-1 AS ordinal,NULL::text AS reason,
        jsonb_build_array(
          symbol,canonical_sector,method,value,
          CASE WHEN method='pb_roe' THEN roe ELSE NULL END,
          source_timestamp,recorded_at,source_ref,filing_restatement_id,
          (SELECT roster_hash FROM header),(SELECT taxonomy_hash FROM header)
        ) AS payload
      FROM included
      UNION ALL
      SELECT 'excluded_rows',row_number() OVER (
          ORDER BY exclusion_reason,method_ordinal,canonical_sector,symbol
        )-1,exclusion_reason,
        jsonb_build_array(
          symbol,canonical_sector,method,exclusion_reason,
          source_timestamp,recorded_at,source_ref
        )
      FROM terminal WHERE exclusion_reason IS NOT NULL
      UNION ALL
      SELECT 'aggregate_rows',row_number() OVER (
          ORDER BY canonical_sector,method
        )-1,NULL,
        jsonb_build_array(canonical_sector,method,included_count,p10,p50,p90)
      FROM aggregate_values
      UNION ALL
      SELECT 'conservation',method_ordinal-1,NULL,
        jsonb_build_array(
          method,(SELECT count(*) FROM sectors),
          count(*) FILTER (WHERE exclusion_reason IS NULL),
          count(*) FILTER (WHERE exclusion_reason IS NOT NULL),
          jsonb_build_object(
            'unknown_sector',count(*) FILTER (WHERE exclusion_reason='unknown_sector'),
            'provider_conflict',count(*) FILTER (WHERE exclusion_reason='provider_conflict'),
            'missing_observation',count(*) FILTER (WHERE exclusion_reason='missing_observation'),
            'non_finite_value',count(*) FILTER (WHERE exclusion_reason='non_finite_value'),
            'non_positive_multiple',count(*) FILTER (
              WHERE exclusion_reason='non_positive_multiple'
            ),
            'missing_positive_roe',count(*) FILTER (
              WHERE exclusion_reason='missing_positive_roe'
            )
          )
        )
      FROM methods JOIN terminal USING(method_ordinal,method,fact_key)
      GROUP BY method_ordinal,method
    )
    SELECT native.ordinal::bigint,native.reason,native.payload
    FROM native WHERE native.section_key=requested_section
    ORDER BY native.ordinal OFFSET requested_offset LIMIT requested_limit;
    RETURN;
  ELSIF requested_kind='factor_scoring_reference' THEN
    SELECT count(*) INTO v_symbol_count
    FROM (
      SELECT (row.payload_json->>1)::uuid AS stock_id
      FROM public.opportunity_run_manifest_inputs input
      JOIN public.opportunity_manifest_rows_v3 row
        ON row.manifest_id=input.manifest_id AND row.section_key='rows'
      WHERE input.run_id=requested_run_id
        AND input.input_role='instrument_roster' AND input.ordinal=0
        AND row.payload_json->>4='common_stock'
        AND row.payload_json->>5='active'
        AND (row.payload_json->>9)::timestamptz<=v_cutoff
        AND (
          row.payload_json->10='null'::jsonb
          OR v_cutoff<(row.payload_json->>10)::timestamptz
        )
      ORDER BY row.payload_json->>2,(row.payload_json->>1)::uuid
      LIMIT 20001
    ) bounded_roster;
    IF v_symbol_count>20000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='roster_volume_exceeded';
    END IF;
    RETURN QUERY
    WITH header AS (
      SELECT
        max(pair->>1) FILTER (WHERE pair->>0='rosterManifestHash') AS roster_hash,
        max(pair->>1) FILTER (WHERE pair->>0='taxonomyAssignmentManifestHash')
          AS taxonomy_hash
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      WHERE manifest.manifest_id=requested_manifest_id
    ), dependencies AS MATERIALIZED (
      SELECT
        min(input.manifest_id::text) FILTER (
          WHERE input.input_role='instrument_roster'
        )::uuid AS roster_manifest_id,
        min(input.manifest_id::text) FILTER (
          WHERE input.input_role='taxonomy_assignment'
        )::uuid AS taxonomy_manifest_id
      FROM public.opportunity_run_manifest_inputs input
      JOIN public.opportunity_manifests_v3 manifest
        ON manifest.manifest_id=input.manifest_id
        AND manifest.status='complete'
      WHERE input.run_id=requested_run_id
        AND input.ordinal=0
        AND input.input_role IN ('instrument_roster','taxonomy_assignment')
      HAVING count(*)=2
    ), roster AS MATERIALIZED (
      SELECT (instrument.payload_json->>1)::uuid AS stock_id,
        instrument.payload_json->>2 AS symbol,
        (instrument.payload_json->>3)::public.stock_exchange_v3 AS exchange,
        coalesce(sector.canonical_sector_key,'unknown'::public.canonical_sector_key_v3)
          AS canonical_sector_key
      FROM dependencies dependency
      JOIN public.opportunity_manifest_rows_v3 instrument
        ON instrument.manifest_id=dependency.roster_manifest_id
        AND instrument.section_key='rows'
      LEFT JOIN LATERAL (
        SELECT (taxonomy.payload_json->>4)::public.canonical_sector_key_v3
          AS canonical_sector_key
        FROM public.opportunity_manifest_rows_v3 taxonomy
        WHERE taxonomy.manifest_id=dependency.taxonomy_manifest_id
          AND taxonomy.section_key='rows'
          AND (taxonomy.payload_json->>1)::uuid=(instrument.payload_json->>1)::uuid
          AND taxonomy.payload_json->>10='active'
          AND (taxonomy.payload_json->>7)::timestamptz<=v_cutoff
          AND (
            taxonomy.payload_json->8='null'::jsonb
            OR v_cutoff<(taxonomy.payload_json->>8)::timestamptz
          )
        ORDER BY taxonomy.row_ordinal
        LIMIT 2
      ) sector ON true
      WHERE instrument.payload_json->>4='common_stock'
        AND instrument.payload_json->>5='active'
        AND (instrument.payload_json->>9)::timestamptz<=v_cutoff
        AND (
          instrument.payload_json->10='null'::jsonb
          OR v_cutoff<(instrument.payload_json->>10)::timestamptz
        )
      ORDER BY instrument.payload_json->>2
      LIMIT 20000
    ), feature_keys AS (
      SELECT * FROM (VALUES
        (1,'volume_ratio_20d'),(2,'ma20_slope_5d'),
        (3,'foreign_net_5d_over_turnover_5d'),(4,'trust_net_5d_over_turnover_5d'),
        (5,'margin_balance_change_5d_over_turnover_5d'),
        (6,'sbl_short_balance_change_5d_over_turnover_5d'),
        (7,'monthly_revenue_yoy'),(8,'revenue_yoy_acceleration_3m'),
        (9,'quarterly_eps_yoy'),(10,'operating_margin_yoy_delta'),
        (11,'avg_turnover_20d'),(12,'zero_volume_sessions_20d')
      ) feature(feature_ordinal,feature_key)
    ), price_history AS MATERIALIZED (
      SELECT roster.stock_id,history.observation_count,history.slope_observation_count,
        history.average_turnover,history.turnover_5d,
        history.zero_volume_count,history.volume_ratio_20d,history.ma20_slope_5d,
        history.latest_close,history.observed_at,history.source_ref,
        history.price_evidence
      FROM roster
      LEFT JOIN LATERAL (
        SELECT count(*) FILTER (WHERE selected.history_rank<=20)::integer
            AS observation_count,
          count(selected.adjusted_close)::integer AS slope_observation_count,
          avg(selected.turnover_twd) FILTER (
            WHERE selected.history_rank<=20
          )::double precision AS average_turnover,
          sum(selected.turnover_twd) FILTER (
            WHERE selected.history_rank<=5
          )::double precision AS turnover_5d,
          count(*) FILTER (
            WHERE selected.history_rank<=20 AND selected.volume=0
          )::double precision AS zero_volume_count,
          max(selected.volume) FILTER (WHERE selected.history_rank=1)
            / nullif(avg(selected.volume) FILTER (
              WHERE selected.history_rank BETWEEN 2 AND 21
            ),0) AS volume_ratio_20d,
          (
            avg(selected.adjusted_close) FILTER (
              WHERE selected.history_rank BETWEEN 1 AND 20
            )
            / nullif(avg(selected.adjusted_close) FILTER (
              WHERE selected.history_rank BETWEEN 6 AND 25
            ),0)-1
          )*100 AS ma20_slope_5d,
          max(selected.adjusted_close) FILTER (WHERE selected.history_rank=1)
            AS latest_close,
          max(selected.source_timestamp) AS observed_at,
          encode(extensions.digest(convert_to(regexp_replace(jsonb_agg(
            jsonb_build_array(
              selected.session_id,selected.observation_id,selected.source_ref,
              selected.price_ref
            ) ORDER BY selected.history_rank
          )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex') AS source_ref,
          jsonb_agg(selected.price_evidence ORDER BY selected.history_rank)
            FILTER (WHERE selected.price_evidence IS NOT NULL)
            AS price_evidence
        FROM (
          SELECT ranked.*,
            (adjusted.payload->'evidence'->>14)::double precision
              AS adjusted_close,
            adjusted.payload->'evidence' AS price_evidence,
            adjusted.payload->>'ref' AS price_ref
          FROM (
            SELECT terminal.*,
              row_number() OVER (ORDER BY terminal.session_id DESC) AS history_rank,
              max(terminal.session_id) OVER () AS anchor_session
            FROM (
            SELECT DISTINCT ON (price.session_id)
              price.observation_id,price.session_id,price.turnover_twd,price.volume,
              price.source_timestamp,price.source_ref
            FROM public.opportunity_price_observations_v3 price
            WHERE price.stock_id=roster.stock_id
              AND price.exchange=roster.exchange
              AND price.source_timestamp<=v_cutoff
              AND price.collected_at<=v_cutoff
              AND price.recorded_at<=v_cutoff
            ORDER BY price.session_id DESC,
              CASE WHEN price.provider::text=lower(roster.exchange::text)
                THEN 0 ELSE 1 END,
              price.source_timestamp DESC,price.collected_at DESC,
              price.recorded_at DESC,price.source_ref,price.observation_id
            LIMIT 25
            ) terminal
          ) ranked
          LEFT JOIN LATERAL (
            SELECT public.opportunity_adjusted_price_evidence_v3_internal(
              ranked.observation_id,ranked.anchor_session,v_cutoff
            ) AS payload
          ) adjusted ON true
        ) selected
      ) history ON true
    ), chip_history AS MATERIALIZED (
      SELECT roster.stock_id,feature.feature_key,selected.observed_at,
        CASE
          WHEN feature.feature_key='sbl_short_balance_change_5d_over_turnover_5d'
          THEN encode(extensions.digest(convert_to(regexp_replace(
            jsonb_build_array(selected.source_ref,history.source_ref)::text,
            ', ', ',', 'g'
          ),'utf8'),'sha256'),'hex')
          ELSE selected.source_ref
        END AS source_ref,
        CASE feature.feature_key
          WHEN 'foreign_net_5d_over_turnover_5d' THEN
            CASE WHEN selected.foreign_count=5
              THEN 100.0*selected.foreign_net_5d/nullif(history.turnover_5d,0) END
          WHEN 'trust_net_5d_over_turnover_5d' THEN
            CASE WHEN selected.trust_count=5
              THEN 100.0*selected.trust_net_5d/nullif(history.turnover_5d,0) END
          WHEN 'margin_balance_change_5d_over_turnover_5d' THEN
            CASE WHEN selected.margin_count=6
              THEN 100.0*selected.margin_change_5d/nullif(history.turnover_5d,0) END
          WHEN 'sbl_short_balance_change_5d_over_turnover_5d' THEN
            CASE WHEN selected.sbl_count=6
              THEN 100.0*selected.sbl_change_5d*history.latest_close
                /nullif(history.turnover_5d,0) END
        END AS value
      FROM roster
      JOIN price_history history ON history.stock_id=roster.stock_id
      CROSS JOIN (VALUES
        ('foreign_net_5d_over_turnover_5d'),
        ('trust_net_5d_over_turnover_5d'),
        ('margin_balance_change_5d_over_turnover_5d'),
        ('sbl_short_balance_change_5d_over_turnover_5d')
      ) feature(feature_key)
      LEFT JOIN LATERAL (
        WITH ranked_sessions AS MATERIALIZED (
          SELECT session.session_id,session.session_authority_id,
            row_number() OVER (ORDER BY session.session_id DESC) AS session_rank
          FROM (
            SELECT DISTINCT ON (authority.session_id)
              authority.session_id,authority.session_authority_id
            FROM public.tw_trading_sessions_v3 authority
            WHERE authority.market::text=roster.exchange::text
              AND authority.status='completed'
              AND authority.close_at<=v_cutoff
              AND authority.source_timestamp<=v_cutoff
              AND authority.collected_at<=v_cutoff
              AND authority.recorded_at<=v_cutoff
            ORDER BY authority.session_id DESC,authority.recorded_at DESC,
              authority.source_timestamp DESC,authority.session_authority_id
            LIMIT 6
          ) session
        ), terminal AS MATERIALIZED (
          SELECT selected.*,expected.session_rank
          FROM ranked_sessions expected
          JOIN LATERAL (
            SELECT DISTINCT ON (observation.fact_key)
              observation.fact_key,observation.value,observation.source_timestamp,
              observation.source_ref,observation.provider,observation.recorded_at
            FROM public.opportunity_stock_flow_observations_v3 observation
            WHERE observation.stock_id=roster.stock_id
              AND observation.exchange=roster.exchange
              AND observation.session_id=expected.session_id
              AND observation.session_authority_id=expected.session_authority_id
              AND observation.source_timestamp<=v_cutoff
              AND observation.collected_at<=v_cutoff
              AND observation.recorded_at<=v_cutoff
            ORDER BY observation.fact_key,
              CASE WHEN observation.provider::text=lower(roster.exchange::text)
                THEN 0 ELSE 1 END,
              observation.source_timestamp DESC,observation.collected_at DESC,
              observation.recorded_at DESC,observation.source_ref,
              observation.observation_id
          ) selected ON true
        )
        SELECT
          count(*) FILTER (
            WHERE fact_key='foreign_net_twd' AND session_rank<=5
          )::integer AS foreign_count,
          sum(value) FILTER (
            WHERE fact_key='foreign_net_twd' AND session_rank<=5
          )::double precision AS foreign_net_5d,
          count(*) FILTER (
            WHERE fact_key='trust_net_twd' AND session_rank<=5
          )::integer AS trust_count,
          sum(value) FILTER (
            WHERE fact_key='trust_net_twd' AND session_rank<=5
          )::double precision AS trust_net_5d,
          count(*) FILTER (
            WHERE fact_key='margin_financing_balance_twd'
          )::integer AS margin_count,
          max(value) FILTER (
            WHERE fact_key='margin_financing_balance_twd' AND session_rank=1
          ) - max(value) FILTER (
            WHERE fact_key='margin_financing_balance_twd' AND session_rank=6
          ) AS margin_change_5d,
          count(*) FILTER (
            WHERE fact_key='sbl_short_balance_shares'
          )::integer AS sbl_count,
          max(value) FILTER (
            WHERE fact_key='sbl_short_balance_shares' AND session_rank=1
          ) - max(value) FILTER (
            WHERE fact_key='sbl_short_balance_shares' AND session_rank=6
          ) AS sbl_change_5d,
          max(source_timestamp) AS observed_at,
          encode(extensions.digest(convert_to(regexp_replace(jsonb_agg(
            jsonb_build_array(fact_key,session_rank,provider,source_ref)
            ORDER BY fact_key,session_rank,provider,source_ref
          )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex') AS source_ref
        FROM terminal
      ) selected ON true
    ), financial_history AS MATERIALIZED (
      SELECT roster.stock_id,computed.monthly_revenue_yoy,
        computed.revenue_yoy_acceleration_3m,computed.quarterly_eps_yoy,
        computed.operating_margin_yoy_delta,computed.monthly_count,
        computed.quarterly_eps_count,computed.margin_period_count,
        computed.monthly_observed_at,computed.quarterly_observed_at,
        computed.monthly_source_ref,computed.quarterly_source_ref
      FROM roster
      LEFT JOIN LATERAL (
        WITH monthly AS MATERIALIZED (
          SELECT selected.*,
            row_number() OVER (ORDER BY selected.period_end DESC) AS history_rank
          FROM (
            SELECT DISTINCT ON (fact.period_end)
              fact.period_end,
              CASE fact.unit
                WHEN 'TWD_thousand' THEN fact.value*1000
                WHEN 'TWD_million' THEN fact.value*1000000
                ELSE fact.value END AS normalized_value,
              fact.source_timestamp,fact.source_ref
            FROM public.opportunity_financial_facts_v3 fact
            WHERE fact.stock_id=roster.stock_id
              AND fact.fact_key='monthly_revenue'
              AND fact.recorded_at<=v_cutoff
              AND fact.filing_published_at<=v_cutoff
              AND fact.source_timestamp<=v_cutoff
              AND fact.collected_at<=v_cutoff
            ORDER BY fact.period_end DESC,
              CASE fact.authority_tier WHEN 'official_filing' THEN 0 ELSE 1 END,
              fact.filing_published_at DESC,fact.source_timestamp DESC,
              fact.collected_at DESC,fact.recorded_at DESC,
              coalesce(fact.filing_restatement_id,'') DESC,
              fact.source_ref,fact.fact_id
            LIMIT 16
          ) selected
        ), monthly_yoy AS MATERIALIZED (
          SELECT current.history_rank,
            100*(current.normalized_value/prior.normalized_value-1) AS yoy,
            current.source_timestamp,current.source_ref
          FROM monthly current
          JOIN monthly prior ON prior.history_rank=current.history_rank+12
          WHERE current.history_rank<=4 AND prior.normalized_value>0
        ), quarterly AS MATERIALIZED (
          SELECT selected.*,
            row_number() OVER (
              PARTITION BY selected.fact_key ORDER BY selected.period_end DESC
            ) AS history_rank
          FROM (
            SELECT DISTINCT ON (fact.fact_key,fact.period_end)
              fact.fact_key,fact.period_end,
              CASE fact.unit
                WHEN 'TWD_thousand' THEN fact.value*1000
                WHEN 'TWD_million' THEN fact.value*1000000
                ELSE fact.value END AS normalized_value,
              fact.source_timestamp,fact.source_ref
            FROM public.opportunity_financial_facts_v3 fact
            WHERE fact.stock_id=roster.stock_id
              AND fact.fact_key IN (
                'quarterly_revenue','quarterly_operating_income',
                'quarterly_diluted_eps'
              )
              AND fact.recorded_at<=v_cutoff
              AND fact.filing_published_at<=v_cutoff
              AND fact.source_timestamp<=v_cutoff
              AND fact.collected_at<=v_cutoff
            ORDER BY fact.fact_key,fact.period_end DESC,
              CASE fact.authority_tier WHEN 'official_filing' THEN 0 ELSE 1 END,
              fact.filing_published_at DESC,fact.source_timestamp DESC,
              fact.collected_at DESC,fact.recorded_at DESC,
              coalesce(fact.filing_restatement_id,'') DESC,
              fact.source_ref,fact.fact_id
            LIMIT 18
          ) selected
        )
        SELECT
          max(monthly_yoy.yoy) FILTER (WHERE monthly_yoy.history_rank=1)
            AS monthly_revenue_yoy,
          max(monthly_yoy.yoy) FILTER (WHERE monthly_yoy.history_rank=1)
            - avg(monthly_yoy.yoy) FILTER (
              WHERE monthly_yoy.history_rank BETWEEN 2 AND 4
            ) AS revenue_yoy_acceleration_3m,
          100*(
            max(quarterly.normalized_value) FILTER (
              WHERE quarterly.fact_key='quarterly_diluted_eps'
                AND quarterly.history_rank=1
            )
            / nullif(max(quarterly.normalized_value) FILTER (
              WHERE quarterly.fact_key='quarterly_diluted_eps'
                AND quarterly.history_rank=5
            ),0)-1
          ) AS quarterly_eps_yoy,
          100*(
            max(quarterly.normalized_value) FILTER (
              WHERE quarterly.fact_key='quarterly_operating_income'
                AND quarterly.history_rank=1
            )
            / nullif(max(quarterly.normalized_value) FILTER (
              WHERE quarterly.fact_key='quarterly_revenue'
                AND quarterly.history_rank=1
            ),0)
            - max(quarterly.normalized_value) FILTER (
              WHERE quarterly.fact_key='quarterly_operating_income'
                AND quarterly.history_rank=5
            )
            / nullif(max(quarterly.normalized_value) FILTER (
              WHERE quarterly.fact_key='quarterly_revenue'
                AND quarterly.history_rank=5
            ),0)
          ) AS operating_margin_yoy_delta,
          (SELECT count(*) FROM monthly_yoy)::integer AS monthly_count,
          (SELECT count(*) FROM quarterly
            WHERE fact_key='quarterly_diluted_eps')::integer
            AS quarterly_eps_count,
          count(DISTINCT quarterly.period_end) FILTER (
            WHERE quarterly.fact_key IN (
              'quarterly_revenue','quarterly_operating_income'
            )
          )::integer AS margin_period_count,
          (SELECT max(source_timestamp) FROM monthly_yoy) AS monthly_observed_at,
          max(quarterly.source_timestamp) AS quarterly_observed_at,
          (SELECT min(source_ref) FROM monthly_yoy) AS monthly_source_ref,
          min(quarterly.source_ref) AS quarterly_source_ref
        FROM monthly_yoy FULL JOIN quarterly ON true
      ) computed ON true
    ), terminal AS (
      SELECT feature.feature_ordinal,feature.feature_key,roster.symbol,
        roster.canonical_sector_key,
        CASE WHEN feature.feature_key IN (
          'monthly_revenue_yoy','revenue_yoy_acceleration_3m'
        ) THEN financial.monthly_observed_at
          WHEN feature.feature_key IN (
            'quarterly_eps_yoy','operating_margin_yoy_delta'
          ) THEN financial.quarterly_observed_at
          WHEN feature.feature_key IN (
            'foreign_net_5d_over_turnover_5d',
            'trust_net_5d_over_turnover_5d',
            'margin_balance_change_5d_over_turnover_5d',
            'sbl_short_balance_change_5d_over_turnover_5d'
          ) THEN chip.observed_at
          ELSE history.observed_at END AS observed_at,
        CASE WHEN feature.feature_key IN (
          'monthly_revenue_yoy','revenue_yoy_acceleration_3m'
        ) THEN financial.monthly_source_ref
          WHEN feature.feature_key IN (
            'quarterly_eps_yoy','operating_margin_yoy_delta'
          ) THEN financial.quarterly_source_ref
          WHEN feature.feature_key IN (
            'foreign_net_5d_over_turnover_5d',
            'trust_net_5d_over_turnover_5d',
            'margin_balance_change_5d_over_turnover_5d',
            'sbl_short_balance_change_5d_over_turnover_5d'
          ) THEN chip.source_ref
          ELSE history.source_ref END AS source_ref,
        CASE
          WHEN feature.feature_key IN (
            'ma20_slope_5d','sbl_short_balance_change_5d_over_turnover_5d'
          ) THEN history.price_evidence
          ELSE NULL
        END AS price_evidence,
        CASE feature.feature_key
          WHEN 'volume_ratio_20d' THEN
            CASE WHEN history.observation_count=20 THEN history.volume_ratio_20d END
          WHEN 'ma20_slope_5d' THEN
            CASE WHEN history.slope_observation_count=25 THEN history.ma20_slope_5d END
          WHEN 'avg_turnover_20d' THEN
            CASE WHEN history.observation_count=20 THEN history.average_turnover END
          WHEN 'zero_volume_sessions_20d' THEN
            CASE WHEN history.observation_count=20 THEN history.zero_volume_count END
          WHEN 'foreign_net_5d_over_turnover_5d' THEN chip.value
          WHEN 'trust_net_5d_over_turnover_5d' THEN chip.value
          WHEN 'margin_balance_change_5d_over_turnover_5d' THEN chip.value
          WHEN 'sbl_short_balance_change_5d_over_turnover_5d' THEN chip.value
          WHEN 'monthly_revenue_yoy' THEN
            CASE WHEN financial.monthly_count>=1
              THEN financial.monthly_revenue_yoy END
          WHEN 'revenue_yoy_acceleration_3m' THEN
            CASE WHEN financial.monthly_count=4
              THEN financial.revenue_yoy_acceleration_3m END
          WHEN 'quarterly_eps_yoy' THEN
            CASE WHEN financial.quarterly_eps_count>=5
              THEN financial.quarterly_eps_yoy END
          WHEN 'operating_margin_yoy_delta' THEN
            CASE WHEN financial.margin_period_count>=2
              THEN financial.operating_margin_yoy_delta END
          ELSE NULL
        END AS value,
        CASE
          WHEN feature.feature_key IN (
            'volume_ratio_20d','ma20_slope_5d',
            'avg_turnover_20d','zero_volume_sessions_20d'
          )
            AND (
              CASE WHEN feature.feature_key='ma20_slope_5d'
                THEN coalesce(history.slope_observation_count,0)<25
                ELSE coalesce(history.observation_count,0)<20
              END
            ) THEN 'insufficient_history'
          WHEN feature.feature_key IN (
            'volume_ratio_20d','ma20_slope_5d',
            'avg_turnover_20d','zero_volume_sessions_20d'
          ) AND (
            CASE feature.feature_key
              WHEN 'volume_ratio_20d' THEN history.volume_ratio_20d
              WHEN 'ma20_slope_5d' THEN history.ma20_slope_5d
              WHEN 'avg_turnover_20d' THEN history.average_turnover
              ELSE history.zero_volume_count
            END
          ) IS NULL THEN 'non_positive_denominator'
          WHEN feature.feature_key IN (
            'volume_ratio_20d','ma20_slope_5d',
            'avg_turnover_20d','zero_volume_sessions_20d'
          )
            THEN NULL
          WHEN feature.feature_key IN (
            'foreign_net_5d_over_turnover_5d',
            'trust_net_5d_over_turnover_5d',
            'margin_balance_change_5d_over_turnover_5d',
            'sbl_short_balance_change_5d_over_turnover_5d'
          ) AND chip.value IS NULL THEN 'missing_observation'
          WHEN feature.feature_key IN (
            'foreign_net_5d_over_turnover_5d',
            'trust_net_5d_over_turnover_5d',
            'margin_balance_change_5d_over_turnover_5d',
            'sbl_short_balance_change_5d_over_turnover_5d'
          ) THEN NULL
          WHEN feature.feature_key='monthly_revenue_yoy'
            AND coalesce(financial.monthly_count,0)<1 THEN 'insufficient_history'
          WHEN feature.feature_key='revenue_yoy_acceleration_3m'
            AND coalesce(financial.monthly_count,0)<4 THEN 'insufficient_history'
          WHEN feature.feature_key='quarterly_eps_yoy'
            AND coalesce(financial.quarterly_eps_count,0)<5 THEN 'insufficient_history'
          WHEN feature.feature_key='operating_margin_yoy_delta'
            AND coalesce(financial.margin_period_count,0)<2 THEN 'insufficient_history'
          WHEN feature.feature_key IN (
            'monthly_revenue_yoy','revenue_yoy_acceleration_3m'
          ) AND financial.monthly_observed_at<v_cutoff-interval '45 days'
            THEN 'stale_observation'
          WHEN feature.feature_key IN (
            'quarterly_eps_yoy','operating_margin_yoy_delta'
          ) AND financial.quarterly_observed_at<v_cutoff-interval '135 days'
            THEN 'stale_observation'
          WHEN feature.feature_key IN (
            'monthly_revenue_yoy','revenue_yoy_acceleration_3m',
            'quarterly_eps_yoy','operating_margin_yoy_delta'
          ) THEN NULL
          ELSE 'missing_observation'
        END AS reason
      FROM feature_keys feature CROSS JOIN roster
      LEFT JOIN price_history history ON history.stock_id=roster.stock_id
      LEFT JOIN chip_history chip ON chip.stock_id=roster.stock_id
        AND chip.feature_key=feature.feature_key
      LEFT JOIN financial_history financial ON financial.stock_id=roster.stock_id
    ), native AS (
      SELECT 'included_rows'::public.opportunity_manifest_section_key_v3 AS section_key,
        row_number() OVER (
          ORDER BY terminal.feature_ordinal,terminal.symbol
        )-1 AS ordinal,NULL::text AS reason,
        jsonb_build_array(
          terminal.feature_key,terminal.symbol,terminal.canonical_sector_key,
          terminal.value,terminal.observed_at,terminal.source_ref,
          'official',(SELECT roster_hash FROM header),(SELECT taxonomy_hash FROM header),
          terminal.price_evidence
        ) AS payload
      FROM terminal WHERE terminal.value IS NOT NULL
      UNION ALL
      SELECT 'excluded_rows',row_number() OVER (
          ORDER BY terminal.feature_ordinal,terminal.symbol
        )-1,
        terminal.reason,jsonb_build_array(
          terminal.feature_key,terminal.symbol,terminal.reason,
          terminal.observed_at,terminal.source_ref
        )
      FROM terminal WHERE terminal.value IS NULL
      UNION ALL
      SELECT 'conservation',feature.feature_ordinal-1,NULL,
        jsonb_build_array(
          feature.feature_key,(SELECT count(*) FROM roster),
          count(*) FILTER (WHERE terminal.value IS NOT NULL),
          count(*) FILTER (WHERE terminal.value IS NULL),
          jsonb_build_object(
            'provider_conflict',0,'future_observation',0,'stale_observation',0,
            'insufficient_history',count(*) FILTER (
              WHERE terminal.reason='insufficient_history'
            ),
            'missing_observation',count(*) FILTER (
              WHERE terminal.reason='missing_observation'
            ),
            'non_finite_value',0,'non_positive_denominator',0
          )
        )
      FROM feature_keys feature
      LEFT JOIN terminal ON terminal.feature_key=feature.feature_key
      GROUP BY feature.feature_ordinal,feature.feature_key
    )
    SELECT native.ordinal::bigint,native.reason,native.payload
    FROM native WHERE native.section_key=requested_section
    ORDER BY native.ordinal OFFSET requested_offset LIMIT requested_limit;
    RETURN;
  ELSIF requested_kind='bias_reference' THEN
    RETURN QUERY
    WITH header AS MATERIALIZED (
      SELECT max((pair->>1)::date) FILTER (WHERE pair->>0='asOfSession') AS as_of_session
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      WHERE manifest.manifest_id=requested_manifest_id
    ), dependencies AS MATERIALIZED (
      SELECT min(input.manifest_id::text) FILTER (WHERE input.input_role='instrument_roster')::uuid AS roster_id,
        min(input.manifest_id::text) FILTER (WHERE input.input_role='taxonomy_assignment')::uuid AS taxonomy_id
      FROM public.opportunity_run_manifest_inputs input
      WHERE input.run_id=requested_run_id AND input.ordinal=0
    ), roster AS MATERIALIZED (
      SELECT (row.payload_json->>1)::uuid AS stock_id,row.payload_json->>2 AS symbol,
        (row.payload_json->>3)::public.stock_exchange_v3 AS exchange,
        coalesce(sector.canonical_sector,'unknown') AS canonical_sector
      FROM dependencies dependency
      JOIN public.opportunity_manifest_rows_v3 row ON row.manifest_id=dependency.roster_id
        AND row.section_key='rows' AND row.terminal_code='effective_active'
      LEFT JOIN LATERAL (
        SELECT taxonomy.payload_json->>4 AS canonical_sector
        FROM public.opportunity_manifest_rows_v3 taxonomy
        WHERE taxonomy.manifest_id=dependency.taxonomy_id AND taxonomy.section_key='rows'
          AND taxonomy.terminal_code='effective_active'
          AND taxonomy.payload_json->>1=row.payload_json->>1
        ORDER BY taxonomy.row_ordinal LIMIT 1
      ) sector ON true
      WHERE row.payload_json->>4='common_stock'
      ORDER BY canonical_sector,row.payload_json->>2,row.payload_json->>1
      LIMIT 20001
    ), selected AS MATERIALIZED (
      SELECT roster.*,history.observation_count,history.ma20,history.atr14,
        history.adjusted_close,history.price_ref
      FROM roster
      CROSS JOIN header
      LEFT JOIN LATERAL (
        SELECT count(*)::integer AS observation_count,
          avg((sample.evidence#>>'{evidence,14}')::double precision) FILTER (WHERE sample.history_rank<=20) AS ma20,
          avg(greatest(
            (sample.evidence#>>'{evidence,12}')::double precision-(sample.evidence#>>'{evidence,13}')::double precision,
            abs((sample.evidence#>>'{evidence,12}')::double precision-lag_close),
            abs((sample.evidence#>>'{evidence,13}')::double precision-lag_close)
          )) FILTER (WHERE sample.history_rank<=14) AS atr14,
          max((sample.evidence#>>'{evidence,14}')::double precision) FILTER (WHERE sample.history_rank=1) AS adjusted_close,
          max(sample.evidence->>'ref') FILTER (WHERE sample.history_rank=1) AS price_ref
        FROM (
          SELECT terminal.*,adjusted.payload AS evidence,
            lag((adjusted.payload#>>'{evidence,14}')::double precision) OVER (ORDER BY terminal.session_id) AS lag_close
          FROM (
            SELECT chosen.*,row_number() OVER (ORDER BY chosen.session_id DESC) AS history_rank,
              max(chosen.session_id) OVER () AS anchor_session
            FROM (
              SELECT DISTINCT ON (price.session_id) price.*
              FROM public.opportunity_price_observations_v3 price
              WHERE price.stock_id=roster.stock_id AND price.exchange=roster.exchange
                AND price.session_id<=header.as_of_session AND price.recorded_at<=v_cutoff
                AND price.source_timestamp<=v_cutoff AND price.collected_at<=v_cutoff
              ORDER BY price.session_id DESC,price.source_timestamp DESC,price.collected_at DESC,
                price.recorded_at DESC,price.source_ref,price.observation_id
              LIMIT 120
            ) chosen
          ) terminal
          LEFT JOIN LATERAL (SELECT public.opportunity_adjusted_price_evidence_v3_internal(
            terminal.observation_id,terminal.anchor_session,v_cutoff) AS payload) adjusted ON true
        ) sample
      ) history ON true
    ), included AS MATERIALIZED (
      SELECT *,100.0*(adjusted_close/nullif(ma20,0)-1.0) AS bias20_pct,
        (adjusted_close-ma20)/nullif(atr14,0) AS bias20_atr
      FROM selected WHERE observation_count=120 AND ma20>0 AND atr14>0 AND adjusted_close>0
        AND price_ref IS NOT NULL
    ), sector_aggregate AS MATERIALIZED (
      SELECT canonical_sector,count(*)::integer AS member_count,
        percentile_cont(0.10) WITHIN GROUP (ORDER BY bias20_pct) AS p10,
        percentile_cont(0.25) WITHIN GROUP (ORDER BY bias20_pct) AS p25,
        percentile_cont(0.50) WITHIN GROUP (ORDER BY bias20_pct) AS p50,
        percentile_cont(0.75) WITHIN GROUP (ORDER BY bias20_pct) AS p75,
        percentile_cont(0.90) WITHIN GROUP (ORDER BY bias20_pct) AS p90
      FROM included GROUP BY canonical_sector
    ), rows_by_section AS (
      SELECT 'current_rows'::public.opportunity_manifest_section_key_v3 AS section_key,
        canonical_sector AS sort_a,symbol AS sort_b,
        jsonb_build_array(stock_id,symbol,canonical_sector,header.as_of_session,bias20_pct,bias20_atr,
          ma20,atr14,price_ref,'tw-corporate-action-v3.1') AS payload,
        NULL::text AS terminal_code
      FROM included CROSS JOIN header
      UNION ALL
      SELECT 'excluded_rows',canonical_sector,symbol,
        jsonb_build_array(stock_id,symbol,CASE WHEN observation_count<120 THEN 'insufficient_technical_history'
          ELSE 'invalid_adjusted_history' END),
        CASE WHEN observation_count<120 THEN 'insufficient_technical_history' ELSE 'invalid_adjusted_history' END
      FROM selected WHERE NOT (observation_count=120 AND ma20>0 AND atr14>0 AND adjusted_close>0 AND price_ref IS NOT NULL)
      UNION ALL
      SELECT 'sector_rows',canonical_sector,'',jsonb_build_array(canonical_sector,header.as_of_session,
        member_count,p10,p25,p50,p75,p90),NULL
      FROM sector_aggregate CROSS JOIN header
      UNION ALL
      SELECT 'conservation','1','',jsonb_build_array('roster_count',(SELECT count(*) FROM roster)),NULL
      UNION ALL
      SELECT 'conservation','2','',jsonb_build_array('included_count',(SELECT count(*) FROM included)),NULL
      UNION ALL
      SELECT 'conservation','3','',jsonb_build_array('excluded_count',(SELECT count(*) FROM selected)-(SELECT count(*) FROM included)),NULL
    ), ordered AS (
      SELECT rows_by_section.section_key,rows_by_section.terminal_code,rows_by_section.payload,
        row_number() OVER (PARTITION BY section_key ORDER BY sort_a,sort_b,payload::text)-1 AS ordinal
      FROM rows_by_section
    )
    SELECT ordered.ordinal,ordered.terminal_code,ordered.payload FROM ordered
    WHERE ordered.section_key=requested_section AND ordered.ordinal>=requested_offset
    ORDER BY ordered.ordinal LIMIT requested_limit;
  ELSIF requested_kind='technical_history_reference' THEN
    RETURN QUERY
    WITH header AS MATERIALIZED (
      SELECT max((pair->>1)::date) FILTER (WHERE pair->>0='asOfSession') AS as_of_session,
        (max((pair->1)::text) FILTER (WHERE pair->>0='orderedDeepSymbols'))::jsonb AS symbols
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      WHERE manifest.manifest_id=requested_manifest_id
    ), symbols AS MATERIALIZED (
      SELECT value AS symbol,(ordinal-1)::integer AS symbol_ordinal
      FROM header CROSS JOIN LATERAL jsonb_array_elements_text(header.symbols) WITH ORDINALITY item(value,ordinal)
      ORDER BY ordinal LIMIT 21
    ), instruments AS MATERIALIZED (
      SELECT symbols.*,instrument.stock_id,instrument.exchange
      FROM symbols
      LEFT JOIN LATERAL (
        SELECT selected.stock_id,selected.exchange
        FROM public.stock_instruments_v3 selected
        WHERE selected.symbol=symbols.symbol AND selected.instrument_type='common_stock'
          AND selected.listing_status='active' AND selected.recorded_at<=v_cutoff
          AND selected.source_timestamp<=v_cutoff AND selected.valid_from<=v_cutoff
          AND (selected.valid_to IS NULL OR v_cutoff<selected.valid_to)
        ORDER BY selected.recorded_at DESC,selected.source_timestamp DESC,selected.instrument_authority_id
        LIMIT 1
      ) instrument ON true
    ), terminal_prices AS MATERIALIZED (
      SELECT instrument.symbol,instrument.symbol_ordinal,instrument.stock_id,instrument.exchange,
        price.observation_id,price.session_id,price.volume,
        row_number() OVER (PARTITION BY instrument.symbol ORDER BY price.session_id)-1 AS chronological_ordinal,
        count(price.observation_id) OVER (PARTITION BY instrument.symbol) AS observation_count
      FROM instruments instrument CROSS JOIN header
      LEFT JOIN LATERAL (
        SELECT bounded.* FROM (
          SELECT DISTINCT ON (candidate.session_id) candidate.*
          FROM public.opportunity_price_observations_v3 candidate
          WHERE candidate.stock_id=instrument.stock_id AND candidate.exchange=instrument.exchange
            AND candidate.session_id<header.as_of_session AND candidate.recorded_at<=v_cutoff
            AND candidate.source_timestamp<=v_cutoff AND candidate.collected_at<=v_cutoff
          ORDER BY candidate.session_id DESC,candidate.source_timestamp DESC,candidate.collected_at DESC,
            candidate.recorded_at DESC,candidate.source_ref,candidate.observation_id
          LIMIT 877
        ) bounded ORDER BY bounded.session_id
      ) price ON true
    ), blocked AS MATERIALIZED (
      SELECT symbol,symbol_ordinal,max(observation_count)::integer AS observation_count
      FROM terminal_prices GROUP BY symbol,symbol_ordinal
      HAVING max(observation_count)<371 OR count(observation_id)=0
    ), owner_rows AS MATERIALIZED (
      SELECT terminal_prices.*,
        (((observation_count-1)/132)-((observation_count-1-chronological_ordinal)/132))::integer AS block_ordinal
      FROM terminal_prices WHERE symbol NOT IN (SELECT symbol FROM blocked)
    ), block_definitions AS MATERIALIZED (
      SELECT symbol,block_ordinal,min(chronological_ordinal) AS owner_start_ordinal,
        max(chronological_ordinal) AS owner_end_ordinal,max(session_id) AS anchor_session
      FROM owner_rows GROUP BY symbol,block_ordinal
    ), block_members AS MATERIALIZED (
      SELECT price.*,definition.block_ordinal,definition.owner_start_ordinal,
        definition.owner_end_ordinal,definition.anchor_session,
        row_number() OVER (PARTITION BY price.symbol,definition.block_ordinal ORDER BY price.session_id)-1 AS within_block
      FROM block_definitions definition
      JOIN terminal_prices price ON price.symbol=definition.symbol
        AND price.chronological_ordinal BETWEEN greatest(0,definition.owner_start_ordinal-120)
          AND definition.owner_end_ordinal
    ), adjusted AS MATERIALIZED (
      SELECT block_members.*,price.payload,
        (price.payload#>>'{evidence,11}')::double precision AS adjusted_open,
        (price.payload#>>'{evidence,12}')::double precision AS adjusted_high,
        (price.payload#>>'{evidence,13}')::double precision AS adjusted_low,
        (price.payload#>>'{evidence,14}')::double precision AS adjusted_close,
        block_members.volume/nullif((price.payload#>>'{evidence,10}')::double precision,0) AS adjusted_volume
      FROM block_members
      LEFT JOIN LATERAL (SELECT public.opportunity_adjusted_price_evidence_v3_internal(
        block_members.observation_id,block_members.anchor_session,v_cutoff) AS payload) price ON true
    ), invalid_symbols AS MATERIALIZED (
      SELECT DISTINCT symbol FROM adjusted WHERE payload IS NULL OR adjusted_open<=0 OR adjusted_high<=0
        OR adjusted_low<=0 OR adjusted_close<=0 OR adjusted_volume IS NULL OR adjusted_volume<0
    ), valid AS MATERIALIZED (
      SELECT adjusted.*,
        avg(adjusted_close) OVER (PARTITION BY symbol,block_ordinal ORDER BY session_id ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS ma20,
        avg(adjusted_close) OVER (PARTITION BY symbol,block_ordinal ORDER BY session_id ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS ma60,
        avg(adjusted_close) OVER (PARTITION BY symbol,block_ordinal ORDER BY session_id ROWS BETWEEN 119 PRECEDING AND CURRENT ROW) AS ma120,
        avg(greatest(adjusted_high-adjusted_low,
          abs(adjusted_high-lag_close),abs(adjusted_low-lag_close))) OVER (
            PARTITION BY symbol,block_ordinal ORDER BY session_id ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS atr14
      FROM (
        SELECT adjusted.*,lag(adjusted_close) OVER (PARTITION BY symbol,block_ordinal ORDER BY session_id) AS lag_close
        FROM adjusted WHERE symbol NOT IN (SELECT symbol FROM invalid_symbols)
      ) adjusted
    ), benchmark_ranked AS MATERIALIZED (
      SELECT observation.session_id,observation.value,observation.source_ref,
        row_number() OVER (PARTITION BY observation.session_id ORDER BY observation.observed_at DESC,
          observation.collected_at DESC,observation.recorded_at DESC,observation.source_ref,observation.observation_id) AS precedence
      FROM public.opportunity_market_observations_v3 observation CROSS JOIN header
      WHERE observation.fact_key='taiex_close' AND observation.scope_key='TAIEX'
        AND observation.session_id<header.as_of_session AND observation.value>0
        AND observation.observed_at<=v_cutoff AND observation.collected_at<=v_cutoff
        AND observation.recorded_at<=v_cutoff
    ), benchmark AS MATERIALIZED (
      SELECT selected.* FROM (
        SELECT * FROM benchmark_ranked WHERE precedence=1 ORDER BY session_id DESC LIMIT 122
      ) selected ORDER BY selected.session_id
    ), rows_by_section AS (
      SELECT 'market_benchmark_rows'::public.opportunity_manifest_section_key_v3 AS section_key,
        -1 AS sort_a,row_number() OVER (ORDER BY session_id)::integer AS sort_b,
        jsonb_build_array(session_id,value,source_ref) AS payload,NULL::text AS terminal_code
      FROM benchmark
      UNION ALL
      SELECT 'raw_adjusted_rows',
        symbol_ordinal AS sort_a,chronological_ordinal AS sort_b,
        jsonb_build_array(symbol,block_ordinal,anchor_session,within_block,session_id,
          adjusted_open,adjusted_high,adjusted_low,adjusted_close,payload->'evidence',adjusted_volume) AS payload,
        NULL::text AS terminal_code
      FROM valid
      UNION ALL
      SELECT 'history_rows',symbol_ordinal,chronological_ordinal,
        jsonb_build_array(symbol,chronological_ordinal-119,session_id,
          100.0*(adjusted_close/nullif(ma20,0)-1.0),100.0*(adjusted_close/nullif(ma60,0)-1.0),
          100.0*(adjusted_close/nullif(ma120,0)-1.0),(adjusted_close-ma20)/nullif(atr14,0)),NULL
      FROM valid WHERE chronological_ordinal BETWEEN owner_start_ordinal AND owner_end_ordinal
        AND within_block>=119 AND ma20>0 AND ma60>0 AND ma120>0 AND atr14>0
      UNION ALL
      SELECT 'excluded_rows',symbol_ordinal,0,jsonb_build_array(symbol,'insufficient_technical_history',observation_count),
        'insufficient_technical_history' FROM blocked
      UNION ALL
      SELECT 'excluded_rows',instrument.symbol_ordinal,0,jsonb_build_array(instrument.symbol,'invalid_adjusted_history',0),
        'invalid_adjusted_history' FROM instruments instrument WHERE instrument.symbol IN (SELECT symbol FROM invalid_symbols)
      UNION ALL
      SELECT 'conservation',1,0,jsonb_build_array('planned_symbol_count',(SELECT count(*) FROM symbols)),NULL
      UNION ALL
      SELECT 'conservation',2,0,jsonb_build_array('terminal_symbol_count',(SELECT count(DISTINCT symbol) FROM valid)
        +(SELECT count(*) FROM blocked)+(SELECT count(*) FROM invalid_symbols)),NULL
    ), ordered AS (
      SELECT rows_by_section.section_key,rows_by_section.terminal_code,rows_by_section.payload,
        row_number() OVER (PARTITION BY section_key ORDER BY sort_a,sort_b,payload::text)-1 AS ordinal
      FROM rows_by_section
    )
    SELECT ordered.ordinal,ordered.terminal_code,ordered.payload FROM ordered
    WHERE ordered.section_key=requested_section AND ordered.ordinal>=requested_offset
    ORDER BY ordered.ordinal LIMIT requested_limit;
  ELSIF requested_kind='reported_pe_reference' THEN
    RETURN QUERY
    WITH header AS MATERIALIZED (
      SELECT max((pair->>1)::date) FILTER (WHERE pair->>0='asOfSession') AS as_of_session,
        (max((pair->1)::text) FILTER (WHERE pair->>0='orderedDeepSymbols'))::jsonb AS symbols
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      WHERE manifest.manifest_id=requested_manifest_id
    ), dependencies AS MATERIALIZED (
      SELECT min(input.manifest_id::text) FILTER (WHERE input.input_role='instrument_roster')::uuid AS roster_id,
        min(input.manifest_id::text) FILTER (WHERE input.input_role='taxonomy_assignment')::uuid AS taxonomy_id
      FROM public.opportunity_run_manifest_inputs input
      WHERE input.run_id=requested_run_id AND input.ordinal=0
    ), deep_symbols AS MATERIALIZED (
      SELECT value AS symbol,(ordinal-1)::integer AS symbol_ordinal
      FROM header CROSS JOIN LATERAL jsonb_array_elements_text(header.symbols) WITH ORDINALITY item(value,ordinal)
      ORDER BY ordinal LIMIT 21
    ), roster AS MATERIALIZED (
      SELECT (row.payload_json->>1)::uuid AS stock_id,row.payload_json->>2 AS symbol,
        row.payload_json->>3 AS exchange,coalesce(sector.canonical_sector,'unknown') AS canonical_sector
      FROM dependencies dependency
      JOIN public.opportunity_manifest_rows_v3 row ON row.manifest_id=dependency.roster_id
        AND row.section_key='rows' AND row.terminal_code='effective_active'
      LEFT JOIN LATERAL (
        SELECT taxonomy.payload_json->>4 AS canonical_sector
        FROM public.opportunity_manifest_rows_v3 taxonomy
        WHERE taxonomy.manifest_id=dependency.taxonomy_id AND taxonomy.section_key='rows'
          AND taxonomy.terminal_code='effective_active' AND taxonomy.payload_json->>1=row.payload_json->>1
        ORDER BY taxonomy.row_ordinal LIMIT 1
      ) sector ON true
      WHERE row.payload_json->>4='common_stock'
      ORDER BY canonical_sector,row.payload_json->>2,row.payload_json->>1 LIMIT 20001
    ), own_history AS MATERIALIZED (
      SELECT roster.stock_id,roster.symbol,roster.exchange,fact.session_date AS session,
        session.session_authority_id,fact.reported_pe,price.adjusted_close AS close,
        fact.source_ref,fact.published_at AS filing_published_at,fact.source_timestamp,fact.collected_at,fact.recorded_at,
        deep.symbol_ordinal,
        row_number() OVER (PARTITION BY roster.symbol ORDER BY fact.session_date DESC,fact.source_timestamp DESC,fact.reported_pe_id) AS history_rank
      FROM deep_symbols deep
      JOIN roster ON roster.symbol=deep.symbol
      JOIN public.opportunity_exchange_reported_pe_v3 fact ON fact.stock_id=roster.stock_id
        AND fact.exchange::text=roster.exchange AND fact.reported_pe>0
        AND fact.session_date<=(SELECT as_of_session FROM header)
        AND fact.recorded_at<=v_cutoff AND fact.published_at<=v_cutoff
        AND fact.source_timestamp<=v_cutoff AND fact.collected_at<=v_cutoff
      JOIN LATERAL (
        SELECT selected.session_authority_id FROM public.tw_trading_sessions_v3 selected
        WHERE selected.session_id=fact.session_date AND selected.market::text=roster.exchange
          AND selected.status='completed' AND selected.recorded_at<=v_cutoff AND selected.source_timestamp<=v_cutoff
        ORDER BY selected.recorded_at DESC,selected.source_timestamp DESC,selected.session_authority_id LIMIT 1
      ) session ON true
      JOIN LATERAL (
        SELECT (adjusted.payload#>>'{evidence,14}')::double precision AS adjusted_close
        FROM public.opportunity_price_observations_v3 observation
        CROSS JOIN LATERAL (SELECT public.opportunity_adjusted_price_evidence_v3_internal(
          observation.observation_id,fact.session_date,v_cutoff) AS payload) adjusted
        WHERE observation.stock_id=roster.stock_id AND observation.session_id=fact.session_date
          AND observation.session_authority_id=session.session_authority_id AND adjusted.payload IS NOT NULL
          AND observation.recorded_at<=v_cutoff ORDER BY observation.source_timestamp DESC,
          observation.collected_at DESC,observation.recorded_at DESC,observation.observation_id LIMIT 1
      ) price ON true
    ), own_bounded AS MATERIALIZED (
      SELECT * FROM own_history WHERE history_rank<=1260
    ), current_plane AS MATERIALIZED (
      SELECT roster.*,pe.reported_pe,pe.source_ref AS pe_source_ref,pe.recorded_at AS pe_recorded_at,
        price.adjusted_close AS close,price.session_authority_id,
        shares.value AS shares_outstanding,shares.period_end AS shares_period_end,
        shares.source_ref AS shares_source_ref,shares.source_timestamp AS shares_source_timestamp
      FROM roster CROSS JOIN header
      LEFT JOIN LATERAL (
        SELECT fact.reported_pe,fact.source_ref,fact.recorded_at
        FROM public.opportunity_exchange_reported_pe_v3 fact
        WHERE fact.stock_id=roster.stock_id AND fact.exchange::text=roster.exchange
          AND fact.reported_pe>0 AND fact.session_date=header.as_of_session
          AND fact.recorded_at<=v_cutoff AND fact.published_at<=v_cutoff
          AND fact.source_timestamp<=v_cutoff AND fact.collected_at<=v_cutoff
        ORDER BY fact.published_at DESC,fact.source_timestamp DESC,fact.collected_at DESC,
          fact.recorded_at DESC,fact.source_ref,fact.reported_pe_id LIMIT 1
      ) pe ON true
      LEFT JOIN LATERAL (
        SELECT (adjusted.payload#>>'{evidence,14}')::double precision AS adjusted_close,
          observation.session_authority_id
        FROM public.opportunity_price_observations_v3 observation
        CROSS JOIN LATERAL (SELECT public.opportunity_adjusted_price_evidence_v3_internal(
          observation.observation_id,header.as_of_session,v_cutoff) AS payload) adjusted
        WHERE observation.stock_id=roster.stock_id AND observation.session_id=header.as_of_session
          AND observation.recorded_at<=v_cutoff AND observation.source_timestamp<=v_cutoff
          AND observation.collected_at<=v_cutoff AND adjusted.payload IS NOT NULL
        ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
          observation.recorded_at DESC,observation.observation_id LIMIT 1
      ) price ON true
      LEFT JOIN LATERAL (
        SELECT fact.value,fact.period_end,fact.source_ref,fact.source_timestamp
        FROM public.opportunity_financial_facts_v3 fact
        WHERE fact.stock_id=roster.stock_id AND fact.fact_key='shares_outstanding'
          AND fact.estimate_kind='reported' AND fact.value>0 AND fact.period_end<=header.as_of_session
          AND fact.recorded_at<=v_cutoff AND fact.filing_published_at<=v_cutoff
          AND fact.source_timestamp<=v_cutoff AND fact.collected_at<=v_cutoff
        ORDER BY fact.period_end DESC,fact.filing_published_at DESC,fact.source_timestamp DESC,
          fact.recorded_at DESC,fact.fact_id LIMIT 1
      ) shares ON true
    ), sector_eligible AS MATERIALIZED (
      SELECT * FROM current_plane WHERE reported_pe>0 AND close>0 AND shares_outstanding>0
    ), sector_aggregate AS MATERIALIZED (
      SELECT canonical_sector,count(*)::integer AS member_count,
        percentile_cont(0.25) WITHIN GROUP (ORDER BY reported_pe) AS p25,
        percentile_cont(0.50) WITHIN GROUP (ORDER BY reported_pe) AS p50,
        percentile_cont(0.75) WITHIN GROUP (ORDER BY reported_pe) AS p75,
        sum(reported_pe*close*shares_outstanding)/nullif(sum(close*shares_outstanding),0) AS cap_weighted
      FROM sector_eligible GROUP BY canonical_sector HAVING count(*)>=8
    ), deep_counts AS MATERIALIZED (
      SELECT deep.symbol,deep.symbol_ordinal,count(own_bounded.stock_id)::integer AS own_count
      FROM deep_symbols deep LEFT JOIN own_bounded ON own_bounded.symbol=deep.symbol
      GROUP BY deep.symbol,deep.symbol_ordinal
    ), rows_by_section AS (
      SELECT 'own_history_rows'::public.opportunity_manifest_section_key_v3 AS section_key,
        symbol_ordinal AS sort_a,history_rank AS sort_b,
        jsonb_build_array(stock_id,symbol,exchange,session,session_authority_id,reported_pe,close,
          source_ref,filing_published_at,source_timestamp,collected_at,recorded_at) AS payload,NULL::text AS terminal_code
      FROM own_bounded
      UNION ALL
      SELECT 'sector_current_rows',row_number() OVER (ORDER BY canonical_sector,symbol,stock_id)::integer,0,
        jsonb_build_array(stock_id,symbol,canonical_sector,exchange,header.as_of_session,session_authority_id,
          reported_pe,close,shares_outstanding,shares_period_end,shares_source_ref,shares_source_timestamp,
          pe_source_ref,pe_recorded_at),NULL
      FROM sector_eligible CROSS JOIN header
      UNION ALL
      SELECT 'excluded_rows',symbol_ordinal,0,jsonb_build_array(symbol,'insufficient_reported_pe_history',own_count),
        'insufficient_reported_pe_history' FROM deep_counts WHERE own_count<252
      UNION ALL
      SELECT 'excluded_rows',20001+row_number() OVER (ORDER BY canonical_sector,symbol)::integer,0,
        jsonb_build_array(symbol,CASE WHEN reported_pe IS NULL THEN 'reported_pe_unavailable'
          WHEN close IS NULL THEN 'price_unavailable' ELSE 'shares_unavailable' END),
        CASE WHEN reported_pe IS NULL THEN 'reported_pe_unavailable'
          WHEN close IS NULL THEN 'price_unavailable' ELSE 'shares_unavailable' END
      FROM current_plane WHERE NOT (reported_pe>0 AND close>0 AND shares_outstanding>0)
      UNION ALL
      SELECT 'sector_rows',row_number() OVER (ORDER BY canonical_sector)::integer,0,
        jsonb_build_array(canonical_sector,header.as_of_session,member_count,p25,p50,p75,cap_weighted),NULL
      FROM sector_aggregate CROSS JOIN header
      UNION ALL
      SELECT 'conservation',1,0,jsonb_build_array('deep_symbol_count',(SELECT count(*) FROM deep_symbols)),NULL
      UNION ALL
      SELECT 'conservation',2,0,jsonb_build_array('roster_count',(SELECT count(*) FROM roster)),NULL
      UNION ALL
      SELECT 'conservation',3,0,jsonb_build_array('sector_eligible_count',(SELECT count(*) FROM sector_eligible)),NULL
    ), ordered AS (
      SELECT rows_by_section.section_key,rows_by_section.terminal_code,rows_by_section.payload,
        row_number() OVER (PARTITION BY section_key ORDER BY sort_a,sort_b,payload::text)-1 AS ordinal
      FROM rows_by_section
    )
    SELECT ordered.ordinal,ordered.terminal_code,ordered.payload FROM ordered
    WHERE ordered.section_key=requested_section AND ordered.ordinal>=requested_offset
    ORDER BY ordered.ordinal LIMIT requested_limit;
  ELSIF requested_kind='market_reference' THEN
    RETURN QUERY
    WITH candidates AS (
      SELECT symbol.value AS symbol,(symbol.ordinal-1)::integer AS symbol_ordinal
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      CROSS JOIN LATERAL jsonb_array_elements_text(pair->1)
        WITH ORDINALITY symbol(value,ordinal)
      WHERE manifest.manifest_id=requested_manifest_id
        AND pair->>0='orderedCandidateSymbols'
      ORDER BY symbol.ordinal LIMIT 21
    ), candidate_keys AS (
      SELECT * FROM (VALUES
        (1,'sector_excess_return_5d'),(2,'sector_excess_return_20d'),
        (3,'volume_ratio_20d'),(4,'ma20_slope_5d'),
        (5,'foreign_net_5d_over_turnover_5d'),
        (6,'trust_net_5d_over_turnover_5d'),
        (7,'margin_balance_change_5d_over_turnover_5d'),
        (8,'sbl_short_balance_change_5d_over_turnover_5d'),
        (9,'monthly_revenue_yoy'),(10,'revenue_yoy_acceleration_3m'),
        (11,'quarterly_eps_yoy'),(12,'operating_margin_yoy_delta'),
        (13,'avg_turnover_20d'),(14,'zero_volume_sessions_20d')
      ) key(key_ordinal,input_key)
    ), market_keys AS (
      SELECT * FROM (VALUES
        (1,'taiex_close','TAIEX'),(2,'taiex_ma20','TAIEX'),(3,'taiex_ma60','TAIEX'),
        (4,'otc_close','OTC'),(5,'otc_ma20','OTC'),(6,'otc_ma60','OTC'),
        (7,'active_common_above_ma20_pct','TW_ACTIVE_COMMON'),
        (8,'active_common_above_ma60_pct','TW_ACTIVE_COMMON'),
        (9,'foreign_cash_net_5d','TW_ACTIVE_COMMON'),
        (10,'investment_trust_net_5d','TW_ACTIVE_COMMON'),
        (11,'aggregate_margin_balance_change_5d','TW_ACTIVE_COMMON'),
        (12,'foreign_index_futures_net_oi','TAIFEX'),
        (13,'put_call_ratio','TAIFEX'),(14,'taiwan_vix','TAIFEX'),
        (15,'sox_return_5d','SOX'),(16,'nasdaq_return_5d','NASDAQ'),
        (17,'usd_twd_return_5d','USD_TWD')
      ) key(key_ordinal,input_key,scope_key)
    ), sector_keys AS (
      SELECT * FROM (VALUES
        (1,'sector_return_5d'),(2,'sector_return_20d'),(3,'sector_return_60d'),
        (4,'sector_excess_return_20d'),(5,'sector_excess_return_60d'),
        (6,'sector_ad_breadth_20d'),(7,'sector_revenue_yoy_median'),
        (8,'sector_eps_yoy_median'),(9,'sector_revenue_acceleration_median'),
        (10,'sector_operating_margin_delta_median')
      ) key(key_ordinal,input_key)
    ), dependency_keys AS (
      SELECT * FROM (VALUES
        (1,'candidate_financial'),(2,'factor_scoring_reference'),
        (3,'sector_scoring_reference'),(4,'sector_valuation_reference'),
        (5,'peer_authority'),(6,'mover_price_reference')
      ) dependency(key_ordinal,input_key)
    ), dependencies AS MATERIALIZED (
      SELECT key.key_ordinal,key.input_key,manifest.manifest_id,manifest.manifest_hash
      FROM dependency_keys key
      JOIN public.opportunity_run_manifest_inputs input
        ON input.run_id=requested_run_id
        AND input.input_role=key.input_key::public.opportunity_manifest_kind_v3
        AND (
          key.input_key<>'mover_price_reference' OR input.ordinal=0
        )
      JOIN public.opportunity_manifests_v3 manifest
        ON manifest.manifest_id=input.manifest_id AND manifest.status='complete'
    ), candidate_sectors AS (
      SELECT DISTINCT coalesce(row.payload_json->>2,sector_row.payload_json->>2)
        AS canonical_sector
      FROM candidates candidate
      JOIN public.opportunity_run_manifest_inputs input
        ON input.run_id=requested_run_id
        AND input.input_role='factor_scoring_reference' AND input.ordinal=0
      LEFT JOIN public.opportunity_manifest_rows_v3 row
        ON row.manifest_id=input.manifest_id AND row.section_key='included_rows'
        AND row.payload_json->>1=candidate.symbol
      LEFT JOIN public.opportunity_run_manifest_inputs sector_binding
        ON sector_binding.run_id=requested_run_id
        AND sector_binding.input_role='sector_scoring_reference'
        AND sector_binding.ordinal=0
      LEFT JOIN public.opportunity_manifest_rows_v3 sector_row
        ON sector_row.manifest_id=sector_binding.manifest_id
        AND sector_row.section_key IN (
          'sector_excess_included_rows','sector_excess_excluded_rows'
        )
        AND sector_row.payload_json->>1=candidate.symbol
      WHERE coalesce(row.payload_json->>2,sector_row.payload_json->>2)<>'unknown'
    ), expected AS MATERIALIZED (
      SELECT 1 AS family_ordinal,'candidate_factor' AS input_family,
        key.key_ordinal,key.input_key,candidate.symbol AS scope_key,
        candidate.symbol
      FROM candidate_keys key CROSS JOIN candidates candidate
      UNION ALL
      SELECT 2,'market_context',key_ordinal,input_key,scope_key,NULL
      FROM market_keys
      UNION ALL
      SELECT 3,'sector_context',key.key_ordinal,key.input_key,
        sector.canonical_sector,NULL
      FROM sector_keys key CROSS JOIN candidate_sectors sector
    ), candidate_available AS MATERIALIZED (
      SELECT expected.*, percentile.score AS value,
        row.payload_json->>4 AS observed_at,row.payload_json->>5 AS source_ref,
        row.payload_json->>6 AS authority_tier,dependency.manifest_hash
      FROM expected
      JOIN dependencies dependency
        ON dependency.input_key='factor_scoring_reference'
      JOIN public.opportunity_manifest_rows_v3 row
        ON row.manifest_id=dependency.manifest_id
        AND row.section_key='included_rows'
        AND row.payload_json->>0=expected.input_key
        AND row.payload_json->>1=expected.symbol
      JOIN LATERAL (
        WITH population AS MATERIALIZED (
          SELECT (reference.payload_json->>3)::double precision AS value
          FROM public.opportunity_manifest_rows_v3 reference
          WHERE reference.manifest_id=dependency.manifest_id
            AND reference.section_key='included_rows'
            AND reference.payload_json->>0=expected.input_key
          ORDER BY (reference.payload_json->>3)::double precision,
            reference.payload_json->>1
          LIMIT 20001
        ), bounds AS (
          SELECT percentile_cont(0.01) WITHIN GROUP (ORDER BY value) AS low,
            percentile_cont(0.99) WITHIN GROUP (ORDER BY value) AS high,
            count(*)::double precision AS population_count
          FROM population
        ), winsorized AS (
          SELECT greatest(bounds.low,least(bounds.high,population.value)) AS value,
            greatest(bounds.low,least(
              bounds.high,(row.payload_json->>3)::double precision
            )) AS candidate_value,bounds.population_count
          FROM population CROSS JOIN bounds
        )
        SELECT round((100.0*(
          count(*) FILTER (WHERE value<candidate_value)
          +0.5*count(*) FILTER (WHERE value=candidate_value)
        )/nullif(max(population_count),0))::numeric,2)::double precision AS score
        FROM winsorized
      ) percentile ON percentile.score IS NOT NULL
      WHERE expected.input_family='candidate_factor'
        AND expected.input_key NOT IN (
          'sector_excess_return_5d','sector_excess_return_20d'
        )
        AND EXISTS (
          SELECT 1
          FROM public.opportunity_manifest_rows_v3 conservation
          WHERE conservation.manifest_id=dependency.manifest_id
            AND conservation.section_key='conservation'
            AND conservation.payload_json->>0=expected.input_key
            AND (conservation.payload_json->>2)::integer>=500
            AND (conservation.payload_json->>2)::double precision
              /nullif((conservation.payload_json->>1)::double precision,0)>=0.80
        )
      UNION ALL
      SELECT expected.*, (row.payload_json->>3)::double precision,
        row.payload_json->>4,row.payload_json->>5,'derived_manifest',
        dependency.manifest_hash
      FROM expected
      JOIN dependencies dependency
        ON dependency.input_key='sector_scoring_reference'
      JOIN public.opportunity_manifest_rows_v3 row
        ON row.manifest_id=dependency.manifest_id
        AND row.section_key='sector_excess_included_rows'
        AND row.payload_json->>0=expected.input_key
        AND row.payload_json->>1=expected.symbol
      WHERE expected.input_family='candidate_factor'
        AND expected.input_key IN (
          'sector_excess_return_5d','sector_excess_return_20d'
        )
    ), market_mapping AS (
      SELECT * FROM (VALUES
        ('taiex_close','taiex_close'::public.market_fact_key_v3,'TAIEX'),
        ('otc_close','otc_close'::public.market_fact_key_v3,'OTC'),
        ('foreign_cash_net_5d','foreign_cash_5d'::public.market_fact_key_v3,
          'TW_ACTIVE_COMMON'),
        ('investment_trust_net_5d','trust_cash_5d'::public.market_fact_key_v3,
          'TW_ACTIVE_COMMON'),
        ('aggregate_margin_balance_change_5d','margin_change_5d'::public.market_fact_key_v3,
          'TW_ACTIVE_COMMON'),
        ('foreign_index_futures_net_oi','foreign_futures_oi'::public.market_fact_key_v3,
          'TAIFEX'),
        ('put_call_ratio','put_call_ratio'::public.market_fact_key_v3,'TAIFEX'),
        ('taiwan_vix','taiwan_vix'::public.market_fact_key_v3,'TAIFEX'),
        ('sox_return_5d','sox_return_5d'::public.market_fact_key_v3,'SOX'),
        ('nasdaq_return_5d','nasdaq_return_5d'::public.market_fact_key_v3,'NASDAQ'),
        ('usd_twd_return_5d','usd_twd_return_5d'::public.market_fact_key_v3,'USD_TWD')
      ) mapping(input_key,fact_key,scope_key)
    ), market_available AS MATERIALIZED (
      SELECT expected.*,
        CASE
          WHEN expected.input_key IN (
            'foreign_cash_net_5d','investment_trust_net_5d',
            'aggregate_margin_balance_change_5d','foreign_index_futures_net_oi',
            'put_call_ratio','taiwan_vix','sox_return_5d',
            'nasdaq_return_5d','usd_twd_return_5d'
          )
          THEN (
            public.opportunity_market_zscore_v3_internal(
              observation.fact_key,observation.scope_key,observation.provider,
              observation.provider_identity,observation.authority_date,
              CASE
                WHEN expected.input_key IN (
                  'aggregate_margin_balance_change_5d','put_call_ratio',
                  'taiwan_vix','usd_twd_return_5d'
                ) THEN -observation.value
                ELSE observation.value
              END,
              v_cutoff
            )->>'score'
          )::double precision
          ELSE observation.value
        END AS value,
        observation.observed_at::text,
        observation.source_ref,
        CASE observation.provider
          WHEN 'finmind' THEN 'finmind_mirror'
          WHEN 'node_twstock' THEN 'node_twstock_mirror'
          ELSE 'official' END AS authority_tier,
        NULL::text AS manifest_hash
      FROM expected
      JOIN market_mapping mapping
        ON mapping.input_key=expected.input_key
        AND mapping.scope_key=expected.scope_key
      JOIN LATERAL (
        SELECT selected.*
        FROM public.opportunity_market_observations_v3 selected
        WHERE selected.fact_key=mapping.fact_key
          AND selected.observed_at<=v_cutoff
          AND selected.collected_at<=v_cutoff
          AND selected.recorded_at<=v_cutoff
          AND (
            expected.scope_key='TW_ACTIVE_COMMON'
            OR selected.scope_key::text=expected.scope_key
          )
        ORDER BY selected.authority_date DESC,
          CASE selected.provider
            WHEN 'twse' THEN 0 WHEN 'tpex' THEN 0
            WHEN 'taifex' THEN 0 WHEN 'global_allowlisted' THEN 0
            WHEN 'finmind' THEN 1 ELSE 2 END,
          selected.observed_at DESC,selected.recorded_at DESC,
          selected.source_ref,selected.observation_id
        LIMIT 1
      ) observation ON true
      WHERE expected.input_family='market_context'
      UNION ALL
      SELECT expected.*,average.value,average.observed_at,average.source_ref,
        average.authority_tier,NULL::text
      FROM expected
      JOIN LATERAL (
        SELECT avg(history.value)::double precision AS value,
          max(history.observed_at)::text AS observed_at,
          min(history.source_ref) AS source_ref,
          CASE min(history.provider::text)
            WHEN 'finmind' THEN 'finmind_mirror'
            WHEN 'node_twstock' THEN 'node_twstock_mirror'
            ELSE 'official' END AS authority_tier,
          count(*)::integer AS observation_count
        FROM (
          SELECT selected.value,selected.observed_at,selected.source_ref,
            selected.provider
          FROM public.opportunity_market_observations_v3 selected
          WHERE selected.fact_key=CASE
              WHEN expected.input_key LIKE 'taiex_%'
                THEN 'taiex_close'::public.market_fact_key_v3
              ELSE 'otc_close'::public.market_fact_key_v3 END
            AND selected.scope_key::text=expected.scope_key
            AND selected.observed_at<=v_cutoff
            AND selected.collected_at<=v_cutoff
            AND selected.recorded_at<=v_cutoff
          ORDER BY selected.authority_date DESC,selected.recorded_at DESC,
            selected.observation_id
          LIMIT CASE WHEN expected.input_key LIKE '%ma20' THEN 20 ELSE 60 END
        ) history
      ) average ON average.observation_count=
        CASE WHEN expected.input_key LIKE '%ma20' THEN 20 ELSE 60 END
      WHERE expected.input_family='market_context'
        AND expected.input_key IN ('taiex_ma20','taiex_ma60','otc_ma20','otc_ma60')
    ), sector_available AS MATERIALIZED (
      SELECT expected.*,(row.payload_json->>2)::double precision AS value,
        row.payload_json->>3 AS observed_at,row.payload_json->>4 AS source_ref,
        'derived_manifest' AS authority_tier,dependency.manifest_hash
      FROM expected
      JOIN dependencies dependency
        ON dependency.input_key='sector_scoring_reference'
      JOIN public.opportunity_manifest_rows_v3 row
        ON row.manifest_id=dependency.manifest_id
        AND row.section_key='sector_aggregate_rows'
        AND row.payload_json->>0=expected.input_key
        AND row.payload_json->>1=expected.scope_key
      WHERE expected.input_family='sector_context'
    ), available AS MATERIALIZED (
      SELECT * FROM candidate_available
      UNION ALL SELECT * FROM market_available
      UNION ALL SELECT * FROM sector_available
    ), native AS (
      SELECT 'included_rows'::public.opportunity_manifest_section_key_v3 AS section_key,
        row_number() OVER (
          ORDER BY family_ordinal,key_ordinal,scope_key,symbol NULLS FIRST
        )-1 AS ordinal,NULL::text AS reason,
        jsonb_build_array(
          input_family,input_key,scope_key,symbol,'number',value,NULL,
          observed_at,source_ref,authority_tier,manifest_hash
        ) AS payload
      FROM available
      UNION ALL
      SELECT 'included_rows',
        (SELECT count(*) FROM available)+row_number() OVER (ORDER BY key_ordinal)-1,
        NULL,
        jsonb_build_array(
          'dependency_manifest',input_key,'run',NULL,'manifest_ref',NULL,
          manifest_id::text,NULL,NULL,NULL,manifest_hash
        ) AS payload
      FROM dependencies
      UNION ALL
      SELECT 'excluded_rows',row_number() OVER (
          ORDER BY family_ordinal,key_ordinal,scope_key,symbol NULLS FIRST
        )-1,'missing_observation',
        jsonb_build_array(
          input_family,input_key,scope_key,symbol,'missing_observation',NULL,NULL
        )
      FROM expected
      WHERE NOT EXISTS (
        SELECT 1 FROM available
        WHERE available.input_family=expected.input_family
          AND available.input_key=expected.input_key
          AND available.scope_key=expected.scope_key
          AND available.symbol IS NOT DISTINCT FROM expected.symbol
      )
      UNION ALL
      SELECT 'conservation',row_number() OVER (
          ORDER BY expected.family_ordinal,expected.key_ordinal
        )-1,NULL,
        jsonb_build_array(
          expected.input_family,expected.input_key,count(*),
          count(*) FILTER (WHERE available.input_key IS NOT NULL),
          count(*) FILTER (WHERE available.input_key IS NULL),
          jsonb_build_object(
            'provider_conflict',0,'future_observation',0,'stale_observation',0,
            'insufficient_coverage',0,'insufficient_history',0,
            'missing_observation',count(*) FILTER (
              WHERE available.input_key IS NULL
            ),'non_finite_value',0,
            'non_positive_denominator',0
          )
        )
      FROM expected
      LEFT JOIN available
        ON available.input_family=expected.input_family
        AND available.input_key=expected.input_key
        AND available.scope_key=expected.scope_key
        AND available.symbol IS NOT DISTINCT FROM expected.symbol
      GROUP BY expected.family_ordinal,expected.key_ordinal,
        expected.input_family,expected.input_key
      UNION ALL
      SELECT 'conservation',64+key_ordinal,NULL,
        jsonb_build_array(
          'dependency_manifest',input_key,1,1,0,
          jsonb_build_object(
            'provider_conflict',0,'future_observation',0,'stale_observation',0,
            'insufficient_coverage',0,'insufficient_history',0,
            'missing_observation',0,'non_finite_value',0,
            'non_positive_denominator',0
          )
        )
      FROM dependencies
    )
    SELECT native.ordinal::bigint,native.reason,native.payload
    FROM native WHERE native.section_key=requested_section
    ORDER BY native.ordinal OFFSET requested_offset LIMIT requested_limit;
    RETURN;
  ELSIF requested_kind='mover_price_reference' THEN
    RETURN QUERY
    WITH header AS (
      SELECT
        max((pair->>1)::date) FILTER (WHERE pair->>0='auditedSession')
          AS audited_session,
        max(pair->>1) FILTER (WHERE pair->>0='auditedSessionAuthorityHash')
          AS audited_hash,
        max((pair->>1)::date) FILTER (WHERE pair->>0='previousSession')
          AS previous_session,
        max(pair->>1) FILTER (WHERE pair->>0='previousSessionAuthorityHash')
          AS previous_hash
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      WHERE manifest.manifest_id=requested_manifest_id
    ), dependency AS (
      SELECT min(input.manifest_id::text)::uuid AS roster_manifest_id
      FROM public.opportunity_run_manifest_inputs input
      WHERE input.run_id=requested_run_id AND input.input_role='instrument_roster'
    ), roster AS MATERIALIZED (
      SELECT (row.payload_json->>1)::uuid AS stock_id,row.payload_json->>2 AS symbol,
        (row.payload_json->>3)::public.stock_exchange_v3 AS exchange
      FROM dependency
      JOIN public.opportunity_manifest_rows_v3 row
        ON row.manifest_id=dependency.roster_manifest_id AND row.section_key='rows'
      WHERE row.payload_json->>4='common_stock' AND row.payload_json->>5='active'
        AND (row.payload_json->>9)::timestamptz<=v_cutoff
        AND (row.payload_json->>10 IS NULL OR v_cutoff<(row.payload_json->>10)::timestamptz)
      ORDER BY row.payload_json->>2
      LIMIT 20001
    ), authorities AS MATERIALIZED (
      SELECT roster.*,header.*,
        audited.session_authority_id AS audited_authority_id,
        previous.session_authority_id AS previous_authority_id
      FROM roster CROSS JOIN header
      LEFT JOIN LATERAL (
        SELECT session.session_authority_id
        FROM public.tw_trading_sessions_v3 session
        WHERE session.session_id=header.audited_session
          AND session.market::text=roster.exchange::text
          AND session.status='completed'
          AND session.source_timestamp<=v_cutoff
          AND session.collected_at<=v_cutoff
          AND session.recorded_at<=v_cutoff
        ORDER BY session.recorded_at DESC,session.source_timestamp DESC,
          session.session_authority_id
        LIMIT 2
      ) audited ON true
      LEFT JOIN LATERAL (
        SELECT session.session_authority_id
        FROM public.tw_trading_sessions_v3 session
        WHERE session.session_id=header.previous_session
          AND session.market::text=roster.exchange::text
          AND session.status='completed'
          AND session.source_timestamp<=v_cutoff
          AND session.collected_at<=v_cutoff
          AND session.recorded_at<=v_cutoff
        ORDER BY session.recorded_at DESC,session.source_timestamp DESC,
          session.session_authority_id
        LIMIT 2
      ) previous ON true
    ), resolved AS MATERIALIZED (
      SELECT authority.*,
        ending.*,prior.*,
        action.snapshot_id,action.dataset_hash,action.event_tuple,action.daily_factor,
        action.action_days
      FROM authorities authority
      LEFT JOIN LATERAL (
        SELECT price.observation_id,price.raw_open AS end_open,
          price.raw_high AS end_high,price.raw_low AS end_low,
          price.raw_close AS end_close,price.turnover_twd,
          price.source_ref AS end_source_ref,price.source_timestamp AS end_source_timestamp
        FROM public.opportunity_price_observations_v3 price
        WHERE price.stock_id=authority.stock_id AND price.exchange=authority.exchange
          AND price.session_id=authority.audited_session
          AND price.session_authority_id=authority.audited_authority_id
          AND price.provider IN (
            CASE authority.exchange WHEN 'TWSE' THEN 'twse'::public.price_provider_v3
              ELSE 'tpex'::public.price_provider_v3 END,
            'finmind'::public.price_provider_v3
          )
          AND price.source_timestamp<=v_cutoff AND price.collected_at<=v_cutoff
          AND price.recorded_at<=v_cutoff
        ORDER BY CASE
            WHEN price.provider::text=lower(authority.exchange::text) THEN 0 ELSE 1 END,
          price.source_timestamp DESC,price.collected_at DESC,price.recorded_at DESC,
          price.source_ref,price.observation_id
        LIMIT 1
      ) ending ON true
      LEFT JOIN LATERAL (
        SELECT price.observation_id AS prior_observation_id,
          price.raw_open AS prior_open,price.raw_high AS prior_high,
          price.raw_low AS prior_low,price.raw_close AS prior_close,
          price.source_ref AS prior_source_ref,
          price.source_timestamp AS prior_source_timestamp
        FROM public.opportunity_price_observations_v3 price
        WHERE price.stock_id=authority.stock_id AND price.exchange=authority.exchange
          AND price.session_id=authority.previous_session
          AND price.session_authority_id=authority.previous_authority_id
          AND price.provider IN (
            CASE authority.exchange WHEN 'TWSE' THEN 'twse'::public.price_provider_v3
              ELSE 'tpex'::public.price_provider_v3 END,
            'finmind'::public.price_provider_v3
          )
          AND price.source_timestamp<=v_cutoff AND price.collected_at<=v_cutoff
          AND price.recorded_at<=v_cutoff
        ORDER BY CASE
            WHEN price.provider::text=lower(authority.exchange::text) THEN 0 ELSE 1 END,
          price.source_timestamp DESC,price.collected_at DESC,price.recorded_at DESC,
          price.source_ref,price.observation_id
        LIMIT 1
      ) prior ON true
      LEFT JOIN LATERAL (
        SELECT snapshot.snapshot_id,snapshot.dataset_hash,
          coalesce(event.daily_adjustment_factor,1::double precision) AS daily_factor,
          CASE WHEN event.snapshot_id IS NULL THEN NULL ELSE jsonb_build_array(
            event.event_kind,event.pre_action_reference_price,
            event.post_action_reference_price,event.feed_identity,event.source_row_ref
          ) END AS event_tuple,
          jsonb_build_array(jsonb_build_array(
            authority.audited_session,authority.audited_authority_id,
            snapshot.snapshot_id,snapshot.dataset_hash,
            CASE WHEN event.snapshot_id IS NULL THEN NULL ELSE jsonb_build_array(
              event.event_kind,event.pre_action_reference_price,
              event.post_action_reference_price,event.feed_identity,event.source_row_ref
            ) END,
            coalesce(event.daily_adjustment_factor,1::double precision)
          )) AS action_days
        FROM public.opportunity_corporate_action_snapshots_v3 snapshot
        LEFT JOIN public.opportunity_corporate_action_events_v3 event
          ON event.snapshot_id=snapshot.snapshot_id AND event.symbol=authority.symbol
        WHERE snapshot.exchange=authority.exchange
          AND snapshot.session_id=authority.audited_session
          AND snapshot.session_authority_id=authority.audited_authority_id
          AND snapshot.collected_at<=v_cutoff AND snapshot.recorded_at<=v_cutoff
          AND (SELECT count(*) FROM public.opportunity_corporate_action_feed_evidence_v3 feed
            WHERE feed.snapshot_id=snapshot.snapshot_id)=3
          AND (SELECT count(*) FROM public.opportunity_corporate_action_events_v3 member
            WHERE member.snapshot_id=snapshot.snapshot_id)=snapshot.declared_event_count
        ORDER BY snapshot.collected_at DESC,snapshot.recorded_at DESC,snapshot.snapshot_id
        LIMIT 1
      ) action ON true
    ), evidence AS MATERIALIZED (
      SELECT resolved.*,
        jsonb_build_array(
          'adjusted-price-evidence-v3.1',audited_session,observation_id,
          end_source_ref,audited_authority_id,end_open,end_high,end_low,end_close,
          '[]'::jsonb,1,end_open,end_high,end_low,end_close
        ) AS end_evidence,
        jsonb_build_array(
          'adjusted-price-evidence-v3.1',audited_session,prior_observation_id,
          prior_source_ref,previous_authority_id,prior_open,prior_high,prior_low,prior_close,
          action_days,daily_factor,prior_open*daily_factor,prior_high*daily_factor,
          prior_low*daily_factor,prior_close*daily_factor
        ) AS prior_evidence
      FROM resolved
    ), terminal AS (
      SELECT evidence.*,
        encode(extensions.digest(convert_to(regexp_replace(
          end_evidence::text,', ', ',', 'g'),'utf8'),'sha256'),'hex') AS end_price_ref,
        encode(extensions.digest(convert_to(regexp_replace(
          prior_evidence::text,', ', ',', 'g'),'utf8'),'sha256'),'hex') AS prior_price_ref,
        CASE
          WHEN audited_authority_id IS NULL OR previous_authority_id IS NULL
            THEN 'calendar_authority_mismatch'
          WHEN observation_id IS NULL THEN 'missing_current_close'
          WHEN prior_observation_id IS NULL THEN 'missing_previous_close'
          WHEN snapshot_id IS NULL THEN 'missing_corporate_action_snapshot'
          WHEN turnover_twd IS NULL THEN 'missing_turnover'
          WHEN prior_close*daily_factor<=0 THEN 'non_positive_previous_close'
          WHEN turnover_twd<20000000 THEN 'turnover_below_20000000'
          ELSE NULL
        END AS exclusion_reason
      FROM evidence
    ), native AS (
      SELECT 'included_rows'::public.opportunity_manifest_section_key_v3 AS section_key,
        row_number() OVER (ORDER BY symbol)-1 AS ordinal,NULL::text AS reason,
        jsonb_build_array(
          symbol,stock_id,audited_session,audited_hash,previous_session,previous_hash,
          audited_authority_id,previous_authority_id,end_close,prior_close*daily_factor,
          turnover_twd,end_evidence,prior_evidence,end_price_ref,prior_price_ref,
          end_source_timestamp,prior_source_timestamp,'tw-corporate-action-v3.1'
        ) AS payload
      FROM terminal WHERE exclusion_reason IS NULL
      UNION ALL
      SELECT 'excluded_rows',row_number() OVER (
          ORDER BY exclusion_reason,symbol
        )-1,exclusion_reason,
        jsonb_build_array(
          symbol,stock_id,exclusion_reason,audited_session,audited_hash,
          previous_session,previous_hash,
          CASE WHEN observation_id IS NULL THEN NULL ELSE end_price_ref END,
          CASE WHEN prior_observation_id IS NULL THEN NULL ELSE prior_price_ref END
        )
      FROM terminal WHERE exclusion_reason IS NOT NULL
      UNION ALL
      SELECT 'conservation',0,NULL,
        jsonb_build_array(
          count(*),count(*) FILTER (WHERE exclusion_reason IS NULL),
          count(*) FILTER (WHERE exclusion_reason IS NOT NULL),
          jsonb_build_object(
            'calendar_authority_mismatch',count(*) FILTER (
              WHERE exclusion_reason='calendar_authority_mismatch'
            ),
            'provider_conflict',0,'future_observation',0,
            'missing_current_close',count(*) FILTER (
              WHERE exclusion_reason='missing_current_close'
            ),
            'missing_previous_close',count(*) FILTER (
              WHERE exclusion_reason='missing_previous_close'
            ),
            'missing_corporate_action_snapshot',count(*) FILTER (
              WHERE exclusion_reason='missing_corporate_action_snapshot'
            ),
            'missing_turnover',count(*) FILTER (WHERE exclusion_reason='missing_turnover'),
            'non_finite_value',0,
            'non_positive_previous_close',count(*) FILTER (
              WHERE exclusion_reason='non_positive_previous_close'
            ),
            'turnover_below_20000000',count(*) FILTER (
              WHERE exclusion_reason='turnover_below_20000000'
            )
          )
        )
      FROM terminal
    )
    SELECT native.ordinal::bigint,native.reason,native.payload
    FROM native WHERE native.section_key=requested_section
    ORDER BY native.ordinal OFFSET requested_offset LIMIT requested_limit;
    RETURN;
  ELSIF requested_kind='sector_scoring_reference' THEN
    RETURN QUERY
    WITH dependencies AS (
      SELECT
        min(input.manifest_id::text) FILTER (
          WHERE input.input_role='instrument_roster'
        )::uuid AS roster_manifest_id,
        min(input.manifest_id::text) FILTER (
          WHERE input.input_role='taxonomy_assignment'
        )::uuid AS taxonomy_manifest_id,
        min(input.manifest_id::text) FILTER (
          WHERE input.input_role='factor_scoring_reference'
        )::uuid AS factor_manifest_id
      FROM public.opportunity_run_manifest_inputs input
      WHERE input.run_id=requested_run_id
    ), roster AS MATERIALIZED (
      SELECT (row.payload_json->>1)::uuid AS stock_id,row.payload_json->>2 AS symbol
      FROM dependencies dependency
      JOIN public.opportunity_manifest_rows_v3 row
        ON row.manifest_id=dependency.roster_manifest_id AND row.section_key='rows'
      WHERE row.payload_json->>4='common_stock' AND row.payload_json->>5='active'
        AND (row.payload_json->>9)::timestamptz<=v_cutoff
        AND (row.payload_json->>10 IS NULL OR v_cutoff<(row.payload_json->>10)::timestamptz)
      ORDER BY row.payload_json->>2
      LIMIT 20001
    ), constituents AS MATERIALIZED (
      SELECT roster.*,coalesce(sector.canonical_sector,'unknown') AS canonical_sector
      FROM roster
      LEFT JOIN LATERAL (
        SELECT row.payload_json->>4 AS canonical_sector
        FROM dependencies dependency
        JOIN public.opportunity_manifest_rows_v3 row
          ON row.manifest_id=dependency.taxonomy_manifest_id AND row.section_key='rows'
        WHERE (row.payload_json->>1)::uuid=roster.stock_id
          AND row.payload_json->>10='active'
          AND (row.payload_json->>7)::timestamptz<=v_cutoff
          AND (row.payload_json->>8 IS NULL OR v_cutoff<(row.payload_json->>8)::timestamptz)
        ORDER BY row.row_ordinal LIMIT 2
      ) sector ON true
    ), aggregate_keys AS (
      SELECT * FROM (VALUES
        (1,'sector_return_5d'),(2,'sector_return_20d'),(3,'sector_return_60d'),
        (4,'sector_excess_return_20d'),(5,'sector_excess_return_60d'),
        (6,'sector_ad_breadth_20d'),(7,'sector_revenue_yoy_median'),
        (8,'sector_eps_yoy_median'),(9,'sector_revenue_acceleration_median'),
        (10,'sector_operating_margin_delta_median')
      ) key(key_ordinal,aggregate_key)
    ), sectors AS (
      SELECT DISTINCT canonical_sector
      FROM constituents WHERE canonical_sector<>'unknown'
    ), price_features AS MATERIALIZED (
      SELECT constituent.stock_id,constituent.symbol,constituent.canonical_sector,
        prices.observed_at,prices.source_ref,
        prices.return_5d,prices.return_20d,prices.return_60d,
        CASE WHEN prices.return_20d IS NULL OR prices.return_20d=0 THEN NULL
          WHEN prices.return_20d>0 THEN 1.0 ELSE 0.0 END AS breadth_20d
      FROM constituents constituent
      LEFT JOIN LATERAL (
        WITH selected_raw AS MATERIALIZED (
          SELECT selected.*,
            row_number() OVER (ORDER BY selected.session_id DESC) AS history_rank,
            max(selected.session_id) OVER () AS anchor_session
          FROM (
            SELECT DISTINCT ON (price.session_id)
              price.observation_id,price.session_id,price.source_timestamp,
              price.source_ref
            FROM public.opportunity_price_observations_v3 price
            WHERE price.stock_id=constituent.stock_id
              AND price.source_timestamp<=v_cutoff
              AND price.collected_at<=v_cutoff
              AND price.recorded_at<=v_cutoff
            ORDER BY price.session_id DESC,price.source_timestamp DESC,
              price.collected_at DESC,price.recorded_at DESC,
              price.source_ref,price.observation_id
            LIMIT 61
          ) selected
        ), adjusted AS MATERIALIZED (
          SELECT selected_raw.*,
            public.opportunity_adjusted_price_evidence_v3_internal(
              selected_raw.observation_id,selected_raw.anchor_session,v_cutoff
            ) AS payload
          FROM selected_raw
        )
        SELECT
          max(source_timestamp) AS observed_at,
          min(payload->>'ref') AS source_ref,
          100.0*(max((payload#>>'{evidence,14}')::double precision)
            FILTER (WHERE history_rank=1)
            /nullif(max((payload#>>'{evidence,14}')::double precision)
              FILTER (WHERE history_rank=6),0)-1.0) AS return_5d,
          100.0*(max((payload#>>'{evidence,14}')::double precision)
            FILTER (WHERE history_rank=1)
            /nullif(max((payload#>>'{evidence,14}')::double precision)
              FILTER (WHERE history_rank=21),0)-1.0) AS return_20d,
          100.0*(max((payload#>>'{evidence,14}')::double precision)
            FILTER (WHERE history_rank=1)
            /nullif(max((payload#>>'{evidence,14}')::double precision)
              FILTER (WHERE history_rank=61),0)-1.0) AS return_60d
        FROM adjusted
        WHERE payload IS NOT NULL
      ) prices ON true
    ), evidence AS MATERIALIZED (
      SELECT key.key_ordinal,key.aggregate_key,constituent.canonical_sector,
        constituent.symbol,
        jsonb_build_array(
          constituent.symbol,
          CASE WHEN factor.payload_json IS NOT NULL
            THEN (factor.payload_json->>3)::double precision ELSE NULL END,
          factor.payload_json->>4,factor.payload_json->>5,
          CASE WHEN factor.payload_json IS NULL
            THEN 'missing_observation' ELSE NULL END
        ) AS evidence
      FROM aggregate_keys key JOIN constituents constituent
        ON constituent.canonical_sector<>'unknown'
      CROSS JOIN dependencies dependency
      LEFT JOIN public.opportunity_manifest_rows_v3 factor
        ON factor.manifest_id=dependency.factor_manifest_id
        AND factor.section_key='included_rows'
        AND factor.payload_json->>1=constituent.symbol
        AND factor.payload_json->>0=CASE key.aggregate_key
          WHEN 'sector_revenue_yoy_median' THEN 'monthly_revenue_yoy'
          WHEN 'sector_eps_yoy_median' THEN 'quarterly_eps_yoy'
          WHEN 'sector_revenue_acceleration_median'
            THEN 'revenue_yoy_acceleration_3m'
          WHEN 'sector_operating_margin_delta_median'
            THEN 'operating_margin_yoy_delta'
          ELSE NULL END
      WHERE key.aggregate_key IN (
        'sector_revenue_yoy_median','sector_eps_yoy_median',
        'sector_revenue_acceleration_median',
        'sector_operating_margin_delta_median'
      )
      UNION ALL
      SELECT key.key_ordinal,key.aggregate_key,price.canonical_sector,
        price.symbol,
        jsonb_build_array(
          price.symbol,
          CASE key.aggregate_key
            WHEN 'sector_return_5d' THEN price.return_5d
            WHEN 'sector_return_20d' THEN price.return_20d
            WHEN 'sector_return_60d' THEN price.return_60d
            ELSE price.breadth_20d END,
          price.observed_at,price.source_ref,
          CASE
            WHEN key.aggregate_key='sector_return_5d'
              AND price.return_5d IS NULL THEN 'insufficient_history'
            WHEN key.aggregate_key='sector_return_20d'
              AND price.return_20d IS NULL THEN 'insufficient_history'
            WHEN key.aggregate_key='sector_return_60d'
              AND price.return_60d IS NULL THEN 'insufficient_history'
            WHEN key.aggregate_key='sector_ad_breadth_20d'
              AND price.breadth_20d IS NULL THEN 'insufficient_history'
            ELSE NULL END
        )
      FROM aggregate_keys key JOIN price_features price
        ON price.canonical_sector<>'unknown'
      WHERE key.aggregate_key IN (
        'sector_return_5d','sector_return_20d','sector_return_60d',
        'sector_ad_breadth_20d'
      )
      UNION ALL
      SELECT key.key_ordinal,key.aggregate_key,constituent.canonical_sector,
        constituent.symbol,
        jsonb_build_array(constituent.symbol,NULL,NULL,NULL,'missing_observation')
      FROM aggregate_keys key JOIN constituents constituent
        ON constituent.canonical_sector='unknown'
      WHERE key.aggregate_key IN ('sector_return_20d','sector_return_60d')
    ), evidence_hashes AS (
      SELECT aggregate_key,canonical_sector,
        encode(extensions.digest(convert_to(regexp_replace(
          jsonb_agg(evidence ORDER BY symbol)::text,', ', ',', 'g'
        ),'utf8'),'sha256'),'hex') AS evidence_hash,
        count(*)::integer AS constituent_count
      FROM evidence GROUP BY aggregate_key,canonical_sector
    ), aggregate_stats AS MATERIALIZED (
      SELECT key.key_ordinal,key.aggregate_key,sector.canonical_sector,
        count(constituent.symbol)::integer AS frozen_count,
        count(*) FILTER (
          WHERE evidence.evidence->>4 IS NULL
        )::integer AS included_count,
        CASE WHEN key.aggregate_key='sector_ad_breadth_20d'
          THEN 100.0*avg((evidence.evidence->>1)::double precision)
            FILTER (WHERE evidence.evidence->>4 IS NULL
              AND evidence.evidence->>1 IS NOT NULL)
          WHEN key.aggregate_key IN (
            'sector_return_5d','sector_return_20d','sector_return_60d'
          ) THEN avg((evidence.evidence->>1)::double precision)
            FILTER (WHERE evidence.evidence->>4 IS NULL)
          ELSE percentile_cont(0.50) WITHIN GROUP (
            ORDER BY (evidence.evidence->>1)::double precision
          ) FILTER (WHERE evidence.evidence->>4 IS NULL) END AS median_value,
        coalesce(hash.evidence_hash,encode(extensions.digest(convert_to(
          '[]','utf8'),'sha256'),'hex')) AS evidence_hash
      FROM aggregate_keys key CROSS JOIN sectors sector
      LEFT JOIN constituents constituent
        ON constituent.canonical_sector=sector.canonical_sector
      LEFT JOIN evidence
        ON evidence.aggregate_key=key.aggregate_key
        AND evidence.canonical_sector=sector.canonical_sector
        AND evidence.symbol=constituent.symbol
      LEFT JOIN evidence_hashes hash
        ON hash.aggregate_key=key.aggregate_key
        AND hash.canonical_sector=sector.canonical_sector
      GROUP BY key.key_ordinal,key.aggregate_key,sector.canonical_sector,
        hash.evidence_hash
    ), market_benchmarks AS MATERIALIZED (
      SELECT horizon,
        count(*)::integer AS frozen_count,
        count(value)::integer AS included_count,
        avg(value)::double precision AS benchmark_return,
        max(observed_at) AS observed_at,
        min(source_ref) AS source_ref,
        encode(extensions.digest(convert_to(regexp_replace(
          coalesce(jsonb_agg(jsonb_build_array(symbol,value,source_ref)
            ORDER BY symbol),'[]'::jsonb)::text,', ', ',', 'g'
        ),'utf8'),'sha256'),'hex') AS evidence_hash
      FROM (
        SELECT symbol,observed_at,source_ref,'20d' AS horizon,
          return_20d AS value FROM price_features
        UNION ALL
        SELECT symbol,observed_at,source_ref,'60d',return_60d
          FROM price_features
      ) population
      GROUP BY horizon
    ), aggregate_base_included AS MATERIALIZED (
      SELECT stats.*
      FROM aggregate_stats stats
      WHERE stats.aggregate_key NOT IN (
          'sector_excess_return_20d','sector_excess_return_60d'
        )
        AND stats.frozen_count>=5
        AND stats.included_count>=ceil(
          CASE WHEN stats.aggregate_key IN (
            'sector_return_5d','sector_return_20d','sector_return_60d',
            'sector_ad_breadth_20d'
          ) THEN 0.80 ELSE 0.60 END * stats.frozen_count
        )
    ), aggregate_included AS MATERIALIZED (
      SELECT * FROM aggregate_base_included
      UNION ALL
      SELECT
        CASE source.aggregate_key
          WHEN 'sector_return_20d' THEN 4 ELSE 5 END AS key_ordinal,
        CASE source.aggregate_key
          WHEN 'sector_return_20d' THEN 'sector_excess_return_20d'
          ELSE 'sector_excess_return_60d' END AS aggregate_key,
        source.canonical_sector,source.frozen_count,source.included_count,
        source.median_value-market.benchmark_return AS median_value,
        encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
          source.evidence_hash,market.evidence_hash
        )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex') AS evidence_hash
      FROM aggregate_base_included source
      JOIN market_benchmarks market
        ON market.horizon=CASE source.aggregate_key
          WHEN 'sector_return_20d' THEN '20d' ELSE '60d' END
        AND market.frozen_count>=500
        AND market.included_count>=ceil(0.80*market.frozen_count)
      WHERE source.aggregate_key IN ('sector_return_20d','sector_return_60d')
    ), aggregate_exclusions AS (
      SELECT stats.*,
        CASE
          WHEN stats.frozen_count<5 THEN 'insufficient_constituents'
          WHEN stats.aggregate_key IN (
            'sector_return_5d','sector_return_20d','sector_return_60d',
            'sector_ad_breadth_20d'
          ) THEN 'insufficient_endpoint_coverage'
          WHEN stats.aggregate_key IN (
            'sector_excess_return_20d','sector_excess_return_60d'
          ) THEN 'missing_market_benchmark'
          ELSE 'insufficient_financial_coverage'
        END AS exclusion_reason
      FROM aggregate_stats stats
      WHERE NOT EXISTS (
        SELECT 1 FROM aggregate_included included
        WHERE included.aggregate_key=stats.aggregate_key
          AND included.canonical_sector=stats.canonical_sector
      )
    ), excess_keys AS (
      SELECT * FROM (VALUES
        (1,'sector_excess_return_5d'),(2,'sector_excess_return_20d')
      ) feature(feature_ordinal,feature_key)
    ), excess_population AS MATERIALIZED (
      SELECT feature.feature_ordinal,feature.feature_key,
        constituent.symbol,constituent.canonical_sector,
        CASE feature.feature_key
          WHEN 'sector_excess_return_5d' THEN price.return_5d
          ELSE price.return_20d END-sector.median_value AS excess_return,
        price.observed_at,price.source_ref,sector.evidence_hash
      FROM excess_keys feature CROSS JOIN constituents constituent
      LEFT JOIN price_features price ON price.stock_id=constituent.stock_id
      LEFT JOIN aggregate_included sector
        ON sector.canonical_sector=constituent.canonical_sector
        AND sector.aggregate_key=CASE feature.feature_key
          WHEN 'sector_excess_return_5d' THEN 'sector_return_5d'
          ELSE 'sector_return_20d' END
    ), native AS (
      SELECT 'market_benchmark_rows'::public.opportunity_manifest_section_key_v3
          AS section_key,
        CASE horizon WHEN '20d' THEN 0 ELSE 1 END AS ordinal,NULL::text AS reason,
        jsonb_build_array(
          horizon,benchmark_return,observed_at,source_ref,frozen_count,
          included_count,round(100.0*included_count/nullif(frozen_count,0),2),
          evidence_hash,NULL
        ) AS payload
      FROM market_benchmarks
      WHERE frozen_count>=500
        AND included_count>=ceil(0.80*frozen_count)
      UNION ALL
      SELECT 'market_benchmark_rows',
        CASE horizon WHEN '20d' THEN 0 ELSE 1 END,
        'insufficient_endpoint_coverage',
        jsonb_build_array(
          horizon,NULL,observed_at,source_ref,frozen_count,included_count,
          round(100.0*included_count/nullif(frozen_count,0),2),
          evidence_hash,'insufficient_endpoint_coverage'
        )
      FROM market_benchmarks
      WHERE frozen_count<500
        OR included_count<ceil(0.80*frozen_count)
      UNION ALL
      SELECT 'sector_aggregate_rows',
        row_number() OVER (
          ORDER BY key_ordinal,canonical_sector
        )-1,NULL,
        jsonb_build_array(
          aggregate_key,canonical_sector,median_value,v_cutoff,NULL,
          frozen_count,included_count,
          round(100.0*included_count/nullif(frozen_count,0),2),
          evidence_hash
        )
      FROM aggregate_included
      UNION ALL
      SELECT 'sector_aggregate_exclusions',
        row_number() OVER (
          ORDER BY key_ordinal,canonical_sector
        )-1,exclusion_reason,
        jsonb_build_array(
          aggregate_key,canonical_sector,NULL,v_cutoff,NULL,NULL,
          frozen_count,included_count,
          round(100.0*included_count/nullif(frozen_count,0),2),
          evidence_hash,exclusion_reason
        )
      FROM aggregate_exclusions
      UNION ALL
      SELECT 'aggregate_evidence_rows',
        row_number() OVER (
          ORDER BY key_ordinal,canonical_sector,symbol
        )-1,evidence->>4,
        jsonb_build_array(aggregate_key,canonical_sector,evidence)
      FROM evidence
      UNION ALL
      SELECT 'sector_excess_included_rows',
        row_number() OVER (
          ORDER BY feature_ordinal,symbol
        )-1,NULL,
        jsonb_build_array(
          feature_key,symbol,canonical_sector,excess_return,
          observed_at,source_ref,evidence_hash
        )
      FROM excess_population
      WHERE excess_return IS NOT NULL AND canonical_sector<>'unknown'
      UNION ALL
      SELECT 'sector_excess_excluded_rows',
        row_number() OVER (
          ORDER BY feature_ordinal,symbol
        )-1,
        CASE WHEN canonical_sector='unknown'
          THEN 'unknown_sector'
          WHEN observed_at IS NULL THEN 'insufficient_stock_endpoint_coverage'
          ELSE 'insufficient_sector_endpoint_coverage' END,
        jsonb_build_array(
          feature_key,symbol,canonical_sector,
          CASE WHEN canonical_sector='unknown'
            THEN 'unknown_sector'
            WHEN observed_at IS NULL THEN 'insufficient_stock_endpoint_coverage'
            ELSE 'insufficient_sector_endpoint_coverage' END,
          NULL,NULL,NULL,NULL
        )
      FROM excess_population
      WHERE excess_return IS NULL OR canonical_sector='unknown'
      UNION ALL
      SELECT 'conservation',key.key_ordinal-1,NULL,
        jsonb_build_array(
          key.aggregate_key,(SELECT count(*) FROM sectors),
          (SELECT count(*) FROM aggregate_included
            WHERE aggregate_key=key.aggregate_key),
          (SELECT count(*) FROM aggregate_exclusions
            WHERE aggregate_key=key.aggregate_key),
          jsonb_build_object(
            'provider_conflict',0,'future_observation',0,
            'insufficient_constituents',(SELECT count(*) FROM aggregate_exclusions
              WHERE aggregate_key=key.aggregate_key
                AND exclusion_reason='insufficient_constituents'),
            'insufficient_endpoint_coverage',(SELECT count(*) FROM aggregate_exclusions
              WHERE aggregate_key=key.aggregate_key
                AND exclusion_reason='insufficient_endpoint_coverage'),
            'missing_market_benchmark',(SELECT count(*) FROM aggregate_exclusions
              WHERE aggregate_key=key.aggregate_key
                AND exclusion_reason='missing_market_benchmark'),
            'insufficient_financial_coverage',(SELECT count(*) FROM aggregate_exclusions
              WHERE aggregate_key=key.aggregate_key
                AND exclusion_reason='insufficient_financial_coverage'),
            'stale_observation',0,'missing_observation',0,
            'non_finite_value',0,'non_positive_denominator',0
          ),
          CASE WHEN key.aggregate_key IN (
            'sector_return_20d','sector_return_60d'
          ) THEN (SELECT count(*) FROM constituents)
          ELSE (SELECT count(*) FROM constituents WHERE canonical_sector<>'unknown') END,
          (SELECT count(*) FROM evidence WHERE key_ordinal=key.key_ordinal)
        )
      FROM aggregate_keys key
    )
    SELECT native.ordinal::bigint,native.reason,native.payload
    FROM native WHERE native.section_key=requested_section
    ORDER BY native.ordinal OFFSET requested_offset LIMIT requested_limit;
    RETURN;
  ELSIF requested_kind='link_audit_sample' THEN
    RETURN QUERY
    WITH manifest_header AS (
      SELECT
        max(pair->>1) FILTER (WHERE pair->>0='evaluationManifestHash')
          AS evaluation_manifest_hash
      FROM public.opportunity_manifests_v3 manifest
      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
      WHERE manifest.manifest_id=requested_manifest_id
    ), evaluation_manifest AS (
      SELECT input.manifest_id
      FROM public.opportunity_run_manifest_inputs input
      JOIN public.opportunity_manifests_v3 manifest
        ON manifest.manifest_id=input.manifest_id
        AND manifest.status='complete'
      WHERE input.run_id=requested_run_id
        AND input.input_role='evaluation_input' AND input.ordinal=0
    ), supplying_runs AS (
      SELECT DISTINCT (row.payload_json->>2)::uuid AS enrich_run_id
      FROM evaluation_manifest manifest
      JOIN public.opportunity_manifest_rows_v3 row
        ON row.manifest_id=manifest.manifest_id
        AND row.section_key IN ('backtest_rows','live_rows')
    ), population AS MATERIALIZED (
      SELECT mention.run_id,claim.claim_id,mention.mention_id,mention.mention_ordinal,
        revision.source_key::text AS connector,mention.link_mode::text AS link_mode,
        CASE
          WHEN mention.outcome IN (
            'linked_new','linked_refresh','linked_duplicate_claim'
          ) THEN 'linked'
          WHEN mention.outcome='ambiguous_symbol' THEN 'ambiguous'
          WHEN mention.outcome='rejected_low_confidence' THEN 'rejected'
          ELSE 'unsupported'
        END AS outcome_family,
        claim.source_ref,mention.review_context,
        mention.review_mention_start_offset,mention.review_mention_end_offset,
        mention.normalized_token,mention.outcome::text AS engine_outcome,
        mention.reason::text AS engine_reason,mention.symbol AS engine_symbol,
        encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
          'link-audit-selection-v3.0',mention.run_id,claim.claim_id,
          mention.mention_ordinal
        )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex') AS selection_hash
      FROM supplying_runs supplying
      JOIN public.opportunity_runs enrich ON enrich.run_id=supplying.enrich_run_id
      JOIN public.opportunity_source_mentions mention
        ON mention.run_id=enrich.upstream_run_id
      JOIN public.opportunity_source_claims claim
        ON claim.run_id=mention.run_id
        AND claim.revision_id=mention.revision_id
        AND claim.claim_ordinal=mention.claim_ordinal
      JOIN public.source_document_revisions_v3 revision
        ON revision.revision_id=mention.revision_id
      WHERE mention.recorded_at<=v_cutoff AND claim.recorded_at<=v_cutoff
    ), stratum_counts AS (
      SELECT connector,link_mode,outcome_family,count(*)::integer AS population_count
      FROM population GROUP BY connector,link_mode,outcome_family
    ), totals AS (
      SELECT least(400,coalesce(sum(population_count),0))::integer AS sample_size,
        count(*)::integer AS stratum_count
      FROM stratum_counts
    ), bases AS (
      SELECT counts.*,totals.sample_size,totals.stratum_count,
        least(counts.population_count,
          CASE WHEN totals.stratum_count=0 THEN 0
            ELSE floor(totals.sample_size::numeric/totals.stratum_count)::integer END
        ) AS base_allocation
      FROM stratum_counts counts CROSS JOIN totals
    ), remaining AS (
      SELECT bases.*,
        greatest(0,bases.population_count-bases.base_allocation) AS residual_count,
        bases.sample_size-sum(bases.base_allocation) OVER () AS remaining_seats
      FROM bases
    ), shares AS (
      SELECT remaining.*,
        CASE WHEN sum(residual_count) OVER ()=0 THEN 0::numeric
          ELSE remaining_seats::numeric*residual_count/sum(residual_count) OVER ()
        END AS ideal_share
      FROM remaining
    ), apportioned AS (
      SELECT shares.*,
        floor(ideal_share)::integer AS floor_share,
        row_number() OVER (
          ORDER BY ideal_share-floor(ideal_share) DESC,
            connector,link_mode,outcome_family
        ) AS remainder_rank,
        remaining_seats-sum(floor(ideal_share)::integer) OVER () AS leftover
      FROM shares
    ), allocations AS (
      SELECT connector,link_mode,outcome_family,population_count,
        base_allocation+floor_share+
          CASE WHEN remainder_rank<=leftover AND residual_count>floor_share THEN 1 ELSE 0 END
          AS allocated_count
      FROM apportioned
    ), ranked AS (
      SELECT population.*,
        allocation.population_count,allocation.allocated_count,
        row_number() OVER (
          PARTITION BY population.connector,population.link_mode,population.outcome_family
          ORDER BY population.selection_hash,population.run_id,
            population.claim_id,population.mention_ordinal
        ) AS selection_ordinal
      FROM population
      JOIN allocations allocation USING(connector,link_mode,outcome_family)
    ), sampled AS (
      SELECT ranked.*,
        jsonb_build_array(
          connector,source_ref,review_context,review_mention_start_offset,
          review_mention_end_offset,normalized_token,link_mode,engine_outcome,
          engine_reason,engine_symbol
        ) AS review_evidence
      FROM ranked WHERE selection_ordinal<=allocated_count
    ), native AS (
      SELECT 'strata'::public.opportunity_manifest_section_key_v3 AS section_key,
        row_number() OVER (ORDER BY connector,link_mode,outcome_family)-1 AS ordinal,
        NULL::text AS reason,
        jsonb_build_array(
          connector,link_mode,outcome_family,population_count,allocated_count
        ) AS payload
      FROM allocations
      UNION ALL
      SELECT 'samples',
        row_number() OVER (
          ORDER BY connector,link_mode,outcome_family,selection_hash,
            run_id,claim_id,mention_ordinal
        )-1,NULL,
        jsonb_build_array(
          encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
            'link-audit-sample-v3.0',
            (SELECT evaluation_manifest_hash FROM manifest_header),
            run_id,claim_id,mention_ordinal
          )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex'),
          connector,link_mode,outcome_family,run_id,claim_id,mention_ordinal,
          selection_hash,review_evidence,
          encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
            'link-audit-review-evidence-v3.0',run_id,claim_id,mention_ordinal,
            review_evidence
          )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex')
        )
      FROM sampled
    )
    SELECT native.ordinal::bigint,native.reason,native.payload
    FROM native WHERE native.section_key=requested_section
    ORDER BY native.ordinal OFFSET requested_offset LIMIT requested_limit;
    RETURN;
  ELSIF requested_kind='link_audit_resolution' THEN
    RETURN QUERY
    WITH samples AS (
      SELECT sample.*
      FROM public.opportunity_link_audit_samples sample
      WHERE sample.sample_manifest_id=(
        SELECT input.manifest_id
        FROM public.opportunity_run_manifest_inputs input
        WHERE input.run_id=requested_run_id
          AND input.input_role='link_audit_sample' AND input.ordinal=0
      )
    ), labels AS (
      SELECT label.* FROM public.opportunity_link_audit_labels label
      JOIN samples sample USING(sample_manifest_id,sample_id)
      WHERE label.recorded_at<=v_cutoff
    ), pivoted AS (
      SELECT sample.sample_id,
        max(label.canonical_symbol) FILTER (WHERE label.label_role='reviewer_1') AS one_symbol,
        bool_or(label.no_link) FILTER (WHERE label.label_role='reviewer_1') AS one_no_link,
        max(label.label_hash) FILTER (WHERE label.label_role='reviewer_1') AS one_hash,
        max(label.recorded_at) FILTER (WHERE label.label_role='reviewer_1') AS one_at,
        max(label.canonical_symbol) FILTER (WHERE label.label_role='reviewer_2') AS two_symbol,
        bool_or(label.no_link) FILTER (WHERE label.label_role='reviewer_2') AS two_no_link,
        max(label.label_hash) FILTER (WHERE label.label_role='reviewer_2') AS two_hash,
        max(label.recorded_at) FILTER (WHERE label.label_role='reviewer_2') AS two_at,
        max(label.canonical_symbol) FILTER (WHERE label.label_role='adjudicator') AS final_symbol,
        bool_or(label.no_link) FILTER (WHERE label.label_role='adjudicator') AS final_no_link,
        max(label.label_hash) FILTER (WHERE label.label_role='adjudicator') AS final_hash,
        max(label.recorded_at) FILTER (WHERE label.label_role='adjudicator') AS final_at
      FROM samples sample LEFT JOIN labels label USING(sample_manifest_id,sample_id)
      GROUP BY sample.sample_id
    ), classified AS (
      SELECT pivoted.*,
        CASE
          WHEN one_hash IS NOT NULL AND two_hash IS NOT NULL
            AND one_symbol IS NOT DISTINCT FROM two_symbol
            AND one_no_link IS NOT DISTINCT FROM two_no_link
          THEN 'reviewer_agreement'
          WHEN final_hash IS NOT NULL THEN 'terminal_adjudication'
          ELSE NULL
        END AS resolution_kind
      FROM pivoted
    ), native AS (
      SELECT 'resolved_rows'::public.opportunity_manifest_section_key_v3 AS section_key,
        row_number() OVER (ORDER BY sample_id)-1 AS ordinal,NULL::text AS reason,
        jsonb_build_array(
          sample_id,resolution_kind,
          CASE resolution_kind WHEN 'reviewer_agreement' THEN one_symbol ELSE final_symbol END,
          CASE resolution_kind WHEN 'reviewer_agreement' THEN one_no_link ELSE final_no_link END,
          CASE resolution_kind
            WHEN 'reviewer_agreement' THEN jsonb_build_array(one_hash,two_hash)
            ELSE jsonb_build_array(one_hash,two_hash,final_hash)
          END,
          greatest(one_at,two_at,final_at)
        ) AS payload
      FROM classified WHERE resolution_kind IS NOT NULL
      UNION ALL
      SELECT 'unresolved_rows',
        row_number() OVER (ORDER BY sample_id)-1,NULL,
        jsonb_build_array(
          sample_id,
          CASE
            WHEN one_hash IS NULL THEN 'missing_reviewer_1'
            WHEN two_hash IS NULL THEN 'missing_reviewer_2'
            ELSE 'reviewer_disagreement_pending_adjudication'
          END,
          CASE
            WHEN one_hash IS NULL THEN '[]'::jsonb
            WHEN two_hash IS NULL THEN jsonb_build_array(one_hash)
            ELSE jsonb_build_array(one_hash,two_hash)
          END
        )
      FROM classified WHERE resolution_kind IS NULL
    )
    SELECT native.ordinal::bigint,native.reason,native.payload
    FROM native WHERE native.section_key=requested_section
    ORDER BY native.ordinal OFFSET requested_offset LIMIT requested_limit;
    RETURN;
  END IF;

  RETURN;
END
$fn$;

CREATE OR REPLACE VIEW opportunity_worker_read_units_v3
WITH (security_invoker = false, security_barrier = true)
AS
WITH units AS (
  SELECT j.job_id,j.run_id,j.input_hash,p.payload_kind,
    CASE p.payload_kind
      WHEN 'manifest_page' THEN 'manifest_page_rows'::public.opportunity_worker_read_kind_v3
      WHEN 'manifest_root' THEN 'manifest_root_pages'::public.opportunity_worker_read_kind_v3
      WHEN 'source_parse_batch' THEN 'source_parse_rows'::public.opportunity_worker_read_kind_v3
      WHEN 'source_connector_summary' THEN 'source_connector_accounting'::public.opportunity_worker_read_kind_v3
      WHEN 'market_context_snapshot' THEN 'market_context_rows'::public.opportunity_worker_read_kind_v3
      WHEN 'shallow_candidate_batch' THEN 'shallow_candidate_rows'::public.opportunity_worker_read_kind_v3
      WHEN 'sector_cycle_batch' THEN 'sector_cycle_rows'::public.opportunity_worker_read_kind_v3
      WHEN 'deep_candidate_batch' THEN 'deep_candidate_rows'::public.opportunity_worker_read_kind_v3
      WHEN 'portfolio_allocation_batch' THEN 'portfolio_rows'::public.opportunity_worker_read_kind_v3
      WHEN 'projection_bundle' THEN 'projection_rows'::public.opportunity_worker_read_kind_v3
      WHEN 'outcome_batch' THEN 'outcome_computation_rows'::public.opportunity_worker_read_kind_v3
      WHEN 'evaluation_bundle' THEN 'evaluation_computation_summary'::public.opportunity_worker_read_kind_v3
    END AS read_kind,
    CASE p.payload_kind
      WHEN 'manifest_page' THEN jsonb_build_array(
        CASE WHEN (p.payload_json->5->>6)::integer=0 THEN NULL ELSE (
          SELECT jsonb_build_array(
            mp.page_id,mp.page_hash,
            (SELECT mr.payload_json
             FROM public.opportunity_manifest_rows_v3 mr
             WHERE mr.manifest_id=mp.manifest_id AND mr.section_key=mp.section_key
             ORDER BY mr.row_ordinal DESC LIMIT 1)
          )
          FROM public.opportunity_manifest_pages_v3 mp
          WHERE mp.manifest_id=(p.payload_json->5->>1)::uuid
            AND mp.section_key=(p.payload_json->5->>5)::public.opportunity_manifest_section_key_v3
            AND mp.page_ordinal=(p.payload_json->5->>6)::integer-1
        ) END,
        CASE
          WHEN p.payload_json->5->>2='source_identity_allowlist'
            AND p.payload_json->5->>5='rows'
          THEN (
            WITH bounded_registry AS MATERIALIZED (
              SELECT registry.stream_key_hash,registry.stream_key_canonical
              FROM public.opportunity_authority_stream_registry_v3 registry
              WHERE registry.family='discovery_identity'
              ORDER BY registry.stream_key_hash,registry.stream_key_canonical
              LIMIT 10001
            ), raw AS MATERIALIZED (
              SELECT registry.stream_key_hash,registry.stream_key_canonical,a.*
              FROM bounded_registry registry
              CROSS JOIN LATERAL (
                SELECT retained.*
                FROM public.source_identity_authorities_v3 retained
                WHERE retained.source_identity_id=(
                  convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
                )::uuid
                ORDER BY retained.recorded_at DESC,retained.authority_id
                LIMIT 65
              ) a
            ), raw_counts AS MATERIALIZED (
              SELECT stream_key_hash,count(*) AS retained_count
              FROM raw GROUP BY stream_key_hash
            ), cutoff_rows AS MATERIALIZED (
              SELECT raw.*
              FROM raw
              WHERE raw.recorded_at<=r.source_cutoff
                AND raw.approved_at<=r.source_cutoff
                AND raw.valid_from<=r.source_cutoff
            ), greatest_times AS MATERIALIZED (
              SELECT stream_key_hash,max(recorded_at) AS greatest_recorded_at
              FROM cutoff_rows GROUP BY stream_key_hash
            ), greatest AS MATERIALIZED (
              SELECT cutoff_rows.*
              FROM cutoff_rows JOIN greatest_times USING(stream_key_hash)
              WHERE cutoff_rows.recorded_at=greatest_times.greatest_recorded_at
            ), tie_stats AS MATERIALIZED (
              SELECT stream_key_hash,
                count(DISTINCT jsonb_build_array(
                  source_identity_id,source_key,source_class,distribution_identity,
                  valid_from,valid_to,status,approved_at,approving_principal_id
                )) AS semantic_count,
                min(authority_id::text)::uuid AS retained_id
              FROM greatest GROUP BY stream_key_hash
            ), selected AS MATERIALIZED (
              SELECT greatest.*
              FROM greatest JOIN tie_stats USING(stream_key_hash)
              WHERE greatest.authority_id=tie_stats.retained_id
            ), guard AS (
              SELECT
                (SELECT count(*) FROM bounded_registry) AS registry_count,
                coalesce((SELECT max(retained_count) FROM raw_counts),0) AS stream_count,
                coalesce((SELECT max(semantic_count) FROM tie_stats),0) AS semantic_count
            )
            SELECT CASE
