                  OFFSET (p.payload_json->5->>7)::integer LIMIT 2001
                ) selected
              ),'[]'::jsonb)
            END FROM guard
          )
          WHEN p.payload_json->5->>2='source_eligible'
            AND p.payload_json->5->>5='rows'
          THEN coalesce((
            SELECT jsonb_agg(jsonb_build_array(
              d.source_key,d.revision_family_key,d.source_identity_authority_id,
              d.approved_source_identity_id,d.stable_connector_document_id,
              d.canonical_url_candidate,d.published_at,d.collected_at,d.recorded_at,
              d.adapter_version,d.acquisition_status,d.raw_field_payload_algorithm_version,
              d.ingestion_content_revision_sha256,d.canonical_content_algorithm_version,
              d.ingestion_canonical_content_hash_v3,d.supersedes_revision_id,d.revision_id
            ) ORDER BY d.published_at DESC NULLS LAST,d.collected_at DESC,
              d.stable_connector_document_id,d.revision_id)
            FROM (
              WITH source_context AS (
                SELECT (pair->>1)::public.source_key_v3 AS source_key
                FROM public.opportunity_manifests_v3 m,
                  LATERAL jsonb_array_elements(m.header_json) pair
                WHERE m.manifest_id=(p.payload_json->5->>1)::uuid
                  AND pair->>0='sourceKey'
              ), bounded_registry AS (
                SELECT registry.source_key,registry.revision_family_key
                FROM public.source_revision_family_registry_v3 registry
                JOIN source_context context ON context.source_key=registry.source_key
                ORDER BY registry.revision_family_key
                LIMIT 1000001
              )
              SELECT selected.* FROM (
                SELECT d.*,row_number() OVER (
                  PARTITION BY d.revision_family_key
                  ORDER BY d.recorded_at DESC,d.revision_id
                ) AS revision_rank
                FROM bounded_registry registry
                CROSS JOIN LATERAL (
                  SELECT revision.*
                  FROM public.source_document_revisions_v3 revision
                  WHERE revision.source_key=registry.source_key
                    AND revision.revision_family_key=registry.revision_family_key
                  ORDER BY revision.recorded_at DESC,revision.revision_id
                  LIMIT 65
                ) d
                WHERE d.recorded_at<=r.source_cutoff AND d.collected_at<=r.source_cutoff
                  AND (d.published_at IS NULL OR d.published_at<=r.source_cutoff)
              ) selected
              WHERE selected.revision_rank=1
              ORDER BY selected.published_at DESC NULLS LAST,selected.collected_at DESC,
                selected.stable_connector_document_id,selected.revision_id
              OFFSET (p.payload_json->5->>7)::integer LIMIT 2001
            ) d
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='source_dataset'
            AND p.payload_json->5->>5='connector_roots'
          THEN coalesce((
            SELECT jsonb_agg(jsonb_build_array(
              source_key,registered_family_count,eligible_count,manifest_hash
            ) ORDER BY source_key)
            FROM (
              SELECT m.manifest_hash,
                max(pair->>1) FILTER (WHERE pair->>0='sourceKey') AS source_key,
                max((pair->>1)::bigint) FILTER (WHERE pair->>0='registeredFamilyCount')
                  AS registered_family_count,
                max((pair->>1)::bigint) FILTER (WHERE pair->>0='eligibleCount')
                  AS eligible_count
              FROM public.opportunity_run_manifest_inputs i
              JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
              CROSS JOIN LATERAL jsonb_array_elements(m.header_json) pair
              WHERE i.run_id=j.run_id AND i.input_role='source_eligible'
              GROUP BY m.manifest_id,m.manifest_hash
              ORDER BY source_key
              OFFSET (p.payload_json->5->>7)::integer LIMIT 2001
            ) roots
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='source_dataset'
            AND p.payload_json->5->>5='selected_revision_rows'
          THEN coalesce((
            SELECT jsonb_agg(payload_json ORDER BY
              source_key,effective_at,canonical_document_id,row_ordinal)
            FROM (
              SELECT m.source_key,mr.row_ordinal,mr.payload_json,
                coalesce(
                  (mr.payload_json->>6)::timestamptz,
                  (mr.payload_json->>7)::timestamptz
                ) AS effective_at,
                encode(extensions.digest(convert_to(regexp_replace(
                  jsonb_build_array(
                    mr.payload_json->>0,mr.payload_json->>3,
                    coalesce(mr.payload_json->>5,mr.payload_json->>4)
                  )::text, ', ', ',', 'g'
                ),'utf8'),'sha256'),'hex') AS canonical_document_id
              FROM (
                SELECT i.manifest_id,
                  max(pair->>1) FILTER (WHERE pair->>0='sourceKey') AS source_key
                FROM public.opportunity_run_manifest_inputs i
                JOIN public.opportunity_manifests_v3 manifest ON manifest.manifest_id=i.manifest_id
                CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                WHERE i.run_id=j.run_id AND i.input_role='source_eligible'
                GROUP BY i.manifest_id
              ) m
              JOIN public.opportunity_manifest_rows_v3 mr ON mr.manifest_id=m.manifest_id
              WHERE mr.section_key='rows' AND mr.row_ordinal<1000
              ORDER BY m.source_key,effective_at,canonical_document_id,mr.row_ordinal
              OFFSET (p.payload_json->5->>7)::integer LIMIT 2001
            ) selected
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='source_dataset'
            AND p.payload_json->5->>5='connector_conservation'
          THEN coalesce((
            SELECT jsonb_agg(jsonb_build_array(
              source_key,registered_family_count,eligible_count,
              least(1000,eligible_count),greatest(0,eligible_count-1000)
            ) ORDER BY source_key)
            FROM (
              SELECT
                max(pair->>1) FILTER (WHERE pair->>0='sourceKey') AS source_key,
                max((pair->>1)::bigint) FILTER (WHERE pair->>0='registeredFamilyCount')
                  AS registered_family_count,
                max((pair->>1)::bigint) FILTER (WHERE pair->>0='eligibleCount')
                  AS eligible_count
              FROM public.opportunity_run_manifest_inputs i
              JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
              CROSS JOIN LATERAL jsonb_array_elements(m.header_json) pair
              WHERE i.run_id=j.run_id AND i.input_role='source_eligible'
              GROUP BY m.manifest_id
              ORDER BY source_key
              OFFSET (p.payload_json->5->>7)::integer LIMIT 2001
            ) conservation
          ),'[]'::jsonb)
          WHEN (
            p.payload_json->5->>2='candidate_financial'
              AND p.payload_json->5->>5 IN (
                'selected_facts','excluded_facts','conservation'
              )
          ) OR (
            p.payload_json->5->>2='peer_authority'
              AND p.payload_json->5->>5 IN ('selected_rows','excluded_rows')
          ) OR (
            p.payload_json->5->>2='factor_scoring_reference'
              AND p.payload_json->5->>5 IN (
                'included_rows','excluded_rows','conservation'
              )
          ) OR (
            p.payload_json->5->>2='sector_valuation_reference'
              AND p.payload_json->5->>5 IN (
                'included_rows','excluded_rows','aggregate_rows','conservation'
              )
          ) OR (
            p.payload_json->5->>2='sector_scoring_reference'
              AND p.payload_json->5->>5 IN (
                'market_benchmark_rows','sector_aggregate_rows',
                'sector_aggregate_exclusions','aggregate_evidence_rows',
                'sector_excess_included_rows','sector_excess_excluded_rows','conservation'
              )
          ) OR (
            p.payload_json->5->>2='bias_reference'
              AND p.payload_json->5->>5 IN (
                'current_rows','excluded_rows','sector_rows','conservation'
              )
          ) OR (
            p.payload_json->5->>2='technical_history_reference'
              AND p.payload_json->5->>5 IN (
                'raw_adjusted_rows','history_rows','excluded_rows','conservation'
              )
          ) OR (
            p.payload_json->5->>2='reported_pe_reference'
              AND p.payload_json->5->>5 IN (
                'own_history_rows','sector_current_rows','excluded_rows','sector_rows','conservation'
              )
          ) OR (
            p.payload_json->5->>2='mover_price_reference'
              AND p.payload_json->5->>5 IN (
                'included_rows','excluded_rows','conservation'
              )
          ) OR (
            p.payload_json->5->>2='market_reference'
              AND p.payload_json->5->>5 IN (
                'included_rows','excluded_rows','conservation'
              )
          ) OR (
            p.payload_json->5->>2='link_audit_sample'
              AND p.payload_json->5->>5 IN ('strata','samples')
          ) OR (
            p.payload_json->5->>2='link_audit_resolution'
              AND p.payload_json->5->>5 IN ('resolved_rows','unresolved_rows')
          )
          THEN coalesce((
            SELECT jsonb_agg(native.native_row ORDER BY native.native_ordinal)
            FROM public.opportunity_manifest_native_rows_v3_internal(
              j.run_id,
              (p.payload_json->5->>1)::uuid,
              (p.payload_json->5->>2)::public.opportunity_manifest_kind_v3,
              (p.payload_json->5->>5)::public.opportunity_manifest_section_key_v3,
              (p.payload_json->5->>7)::integer,
              2001
            ) native
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='sector_benchmark'
            AND p.payload_json->5->>5='entry_rows'
          THEN coalesce((
            WITH benchmark_header AS (
              SELECT
                max((pair->>1)::public.canonical_sector_key_v3)
                  FILTER (WHERE pair->>0='canonicalSector') AS canonical_sector,
                max((pair->>1)::date)
                  FILTER (WHERE pair->>0='entrySession') AS entry_session,
                max(pair->>1)
                  FILTER (WHERE pair->>0='entrySessionAuthorityHash') AS entry_session_hash
              FROM public.opportunity_manifests_v3 manifest
              CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
              WHERE manifest.manifest_id=(p.payload_json->5->>1)::uuid
            ), constituents AS (
              SELECT selected_instrument.stock_id,selected_instrument.symbol,
                selected_instrument.exchange,header.entry_session,header.entry_session_hash
              FROM benchmark_header header
              JOIN LATERAL (
                SELECT selected.*
                FROM (
                  SELECT instrument.*,row_number() OVER (
                    PARTITION BY instrument.stock_id
                    ORDER BY instrument.recorded_at DESC,
                      instrument.source_timestamp DESC,instrument.instrument_authority_id
                  ) AS authority_rank
                  FROM public.stock_instruments_v3 instrument
                  WHERE instrument.recorded_at<=r.source_cutoff
                    AND instrument.source_timestamp<=r.source_cutoff
                    AND instrument.valid_from<=r.source_cutoff
                ) selected
                WHERE selected.authority_rank=1
                  AND selected.instrument_type='common_stock'
                  AND selected.listing_status='active'
                  AND (selected.valid_to IS NULL OR r.source_cutoff<selected.valid_to)
              ) selected_instrument ON true
              JOIN LATERAL (
                SELECT selected.canonical_sector_key
                FROM (
                  SELECT assignment.*,row_number() OVER (
                    PARTITION BY assignment.stock_id
                    ORDER BY assignment.recorded_at DESC,
                      assignment.source_timestamp DESC,assignment.assignment_authority_id
                  ) AS authority_rank
                  FROM public.stock_sector_assignments_v3 assignment
                  WHERE assignment.stock_id=selected_instrument.stock_id
                    AND assignment.recorded_at<=r.source_cutoff
                    AND assignment.source_timestamp<=r.source_cutoff
                    AND assignment.valid_from<=r.source_cutoff
                ) selected
                WHERE selected.authority_rank=1
                  AND selected.status='active'
                  AND (selected.valid_to IS NULL OR r.source_cutoff<selected.valid_to)
              ) sector ON sector.canonical_sector_key=header.canonical_sector
            )
            SELECT jsonb_agg(row_payload ORDER BY symbol)
            FROM (
              SELECT constituent.symbol,
                jsonb_build_array(
                  constituent.symbol,
                  price.session_authority_id,
                  price.raw_close,
                  price.source_ref,
                  price.source_timestamp,
                  'tw-corporate-action-v3.1'
                ) AS row_payload
              FROM constituents constituent
              JOIN LATERAL (
                SELECT observation.session_authority_id,observation.raw_close,
                  observation.source_ref,observation.source_timestamp
                FROM public.opportunity_price_observations_v3 observation
                WHERE observation.stock_id=constituent.stock_id
                  AND observation.exchange=constituent.exchange
                  AND observation.session_id=constituent.entry_session
                  AND observation.source_timestamp<=r.source_cutoff
                  AND observation.collected_at<=r.source_cutoff
                  AND observation.recorded_at<=r.source_cutoff
                  AND observation.provider IN (
                    CASE constituent.exchange
                      WHEN 'TWSE' THEN 'twse'::public.price_provider_v3
                      ELSE 'tpex'::public.price_provider_v3 END,
                    'finmind'::public.price_provider_v3
                  )
                ORDER BY
                  CASE
                    WHEN observation.provider::text=lower(constituent.exchange::text) THEN 0
                    ELSE 1
                  END,
                  observation.source_timestamp DESC,observation.collected_at DESC,
                  observation.recorded_at DESC,observation.source_ref,observation.observation_id
                LIMIT 1
              ) price ON true
              ORDER BY constituent.symbol
              OFFSET (p.payload_json->5->>7)::integer
              LIMIT 2001
            ) selected_rows
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='sector_benchmark'
            AND p.payload_json->5->>5='evaluation_rows'
          THEN coalesce((
            WITH entry_constituents AS (
              SELECT instrument.stock_id,instrument.exchange,entry.payload_json->>0 AS symbol,
                (SELECT (pair->>1)::date
                 FROM public.opportunity_manifests_v3 manifest
                 CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                 WHERE manifest.manifest_id=entry.manifest_id
                   AND pair->>0='entrySession') AS entry_session
              FROM public.opportunity_manifest_rows_v3 entry
              JOIN public.stock_instruments_v3 instrument
                ON instrument.instrument_authority_id=(entry.payload_json->>1)::uuid
                OR instrument.symbol=entry.payload_json->>0
              WHERE entry.manifest_id=(p.payload_json->5->>1)::uuid
                AND entry.section_key='entry_rows'
            )
            SELECT jsonb_agg(row_payload ORDER BY session_id,symbol)
            FROM (
              SELECT session.session_id,constituent.symbol,
                jsonb_build_array(
                  session.session_id,session.taiwan_session_authority_hash,
                  price.session_authority_id,constituent.symbol,price.raw_close,
                  price.source_ref,price.source_timestamp
                ) AS row_payload
              FROM entry_constituents constituent
              JOIN public.opportunity_effective_taiwan_sessions_v3 session
                ON session.session_id>=constituent.entry_session
                AND session.canonical_cutoff<=r.source_cutoff
              JOIN LATERAL (
                SELECT observation.session_authority_id,observation.raw_close,
                  observation.source_ref,observation.source_timestamp
                FROM public.opportunity_price_observations_v3 observation
                WHERE observation.stock_id=constituent.stock_id
                  AND observation.exchange=constituent.exchange
                  AND observation.session_id=session.session_id
                  AND observation.source_timestamp<=r.source_cutoff
                  AND observation.collected_at<=r.source_cutoff
                  AND observation.recorded_at<=r.source_cutoff
                ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
                  observation.recorded_at DESC,observation.source_ref,observation.observation_id
                LIMIT 1
              ) price ON true
              ORDER BY session.session_id,constituent.symbol
              OFFSET (p.payload_json->5->>7)::integer
              LIMIT 2001
            ) selected_rows
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='sector_benchmark'
            AND p.payload_json->5->>5='session_conservation'
          THEN coalesce((
            SELECT jsonb_agg(jsonb_build_array(
              session.session_id,session.taiwan_session_authority_hash,
              frozen.frozen_count,qualified.qualified_count,
              CASE WHEN frozen.frozen_count=0 THEN 0
                ELSE round(100.0*qualified.qualified_count/frozen.frozen_count,2) END,
              CASE WHEN frozen.frozen_count>=5
                AND qualified.qualified_count>=ceil(0.8*frozen.frozen_count)
                THEN 'available' ELSE 'insufficient_sector_benchmark' END
            ) ORDER BY session.session_id)
            FROM (
              SELECT effective.session_id,effective.taiwan_session_authority_hash
              FROM public.opportunity_effective_taiwan_sessions_v3 effective
              WHERE effective.session_id>=(
                SELECT (pair->>1)::date
                FROM public.opportunity_manifests_v3 manifest
                CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                WHERE manifest.manifest_id=(p.payload_json->5->>1)::uuid
                  AND pair->>0='entrySession'
              )
                AND effective.canonical_cutoff<=r.source_cutoff
              ORDER BY effective.session_id
              OFFSET (p.payload_json->5->>7)::integer
              LIMIT 251
            ) session
            CROSS JOIN LATERAL (
              SELECT count(*)::integer AS frozen_count
              FROM public.opportunity_manifest_rows_v3 entry
              WHERE entry.manifest_id=(p.payload_json->5->>1)::uuid
                AND entry.section_key='entry_rows'
            ) frozen
            CROSS JOIN LATERAL (
              SELECT count(*)::integer AS qualified_count
              FROM public.opportunity_manifest_rows_v3 evaluation
              WHERE evaluation.manifest_id=(p.payload_json->5->>1)::uuid
                AND evaluation.section_key='evaluation_rows'
                AND evaluation.payload_json->>0=session.session_id::text
            ) qualified
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='outcome_input'
            AND p.payload_json->5->>5='input_rows'
          THEN coalesce((
            SELECT jsonb_agg(planned.row_payload ORDER BY
              planned.input_run_id,planned.score_snapshot_id,planned.maturity_ordinal)
            FROM (
              SELECT input.run_id AS input_run_id,score.score_snapshot_id,
                maturity.maturity_ordinal,
                jsonb_build_array(
                  input.run_id,score.score_snapshot_id,score.payload_hash,score.symbol,
                  score.horizon,score.rank,maturity.maturity_horizon,
                  entry_session.session_id,entry_session.taiwan_session_authority_hash,
                  maturity_session.session_id,maturity_session.taiwan_session_authority_hash,
                  entry_price.source_ref,maturity_price.source_ref,benchmark.manifest_hash
                ) AS row_payload
              FROM public.opportunity_run_inputs binding
              JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
              JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
              CROSS JOIN (VALUES
                ('session_20'::public.opportunity_outcome_maturity_v3,20,0),
                ('session_60'::public.opportunity_outcome_maturity_v3,60,1),
                ('session_120'::public.opportunity_outcome_maturity_v3,120,2),
                ('session_250'::public.opportunity_outcome_maturity_v3,250,3)
              ) maturity(maturity_horizon,session_count,maturity_ordinal)
              JOIN LATERAL (
                SELECT session.session_id,session.taiwan_session_authority_hash
                FROM public.opportunity_effective_taiwan_sessions_v3 session
                WHERE session.session_id>input.trading_date
                  AND session.canonical_cutoff<=r.source_cutoff
                ORDER BY session.session_id LIMIT 1
              ) entry_session ON true
              JOIN LATERAL (
                SELECT session.session_id,session.taiwan_session_authority_hash
                FROM public.opportunity_effective_taiwan_sessions_v3 session
                WHERE session.session_id>=entry_session.session_id
                  AND session.canonical_cutoff<=r.source_cutoff
                ORDER BY session.session_id
                OFFSET maturity.session_count-1 LIMIT 1
              ) maturity_session ON true
              JOIN LATERAL (
                SELECT adjusted.payload->>'ref' AS source_ref
                FROM public.opportunity_price_observations_v3 observation
                CROSS JOIN LATERAL (
                  SELECT public.opportunity_adjusted_price_evidence_v3_internal(
                    observation.observation_id,maturity_session.session_id,r.source_cutoff
                  ) AS payload
                ) adjusted
                WHERE observation.stock_id=score.stock_id
                  AND observation.session_id=entry_session.session_id
                  AND observation.source_timestamp<=r.source_cutoff
                  AND observation.collected_at<=r.source_cutoff
                  AND observation.recorded_at<=r.source_cutoff
                  AND adjusted.payload IS NOT NULL
                ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
                  observation.recorded_at DESC,observation.observation_id LIMIT 1
              ) entry_price ON true
              JOIN LATERAL (
                SELECT adjusted.payload->>'ref' AS source_ref
                FROM public.opportunity_price_observations_v3 observation
                CROSS JOIN LATERAL (
                  SELECT public.opportunity_adjusted_price_evidence_v3_internal(
                    observation.observation_id,maturity_session.session_id,r.source_cutoff
                  ) AS payload
                ) adjusted
                WHERE observation.stock_id=score.stock_id
                  AND observation.session_id=maturity_session.session_id
                  AND observation.source_timestamp<=r.source_cutoff
                  AND observation.collected_at<=r.source_cutoff
                  AND observation.recorded_at<=r.source_cutoff
                  AND adjusted.payload IS NOT NULL
                ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
                  observation.recorded_at DESC,observation.observation_id LIMIT 1
              ) maturity_price ON true
              JOIN LATERAL (
                SELECT manifest.manifest_id,manifest.manifest_hash
                FROM public.stock_sector_assignments_v3 assignment
                JOIN public.opportunity_run_manifest_inputs benchmark_binding
                  ON benchmark_binding.run_id=j.run_id
                  AND benchmark_binding.input_role='sector_benchmark'
                JOIN public.opportunity_manifests_v3 manifest
                  ON manifest.manifest_id=benchmark_binding.manifest_id
                  AND manifest.status='complete'
                WHERE assignment.stock_id=score.stock_id
                  AND assignment.recorded_at<=r.source_cutoff
                  AND assignment.source_timestamp<=r.source_cutoff
                  AND assignment.valid_from<=r.source_cutoff
                  AND (assignment.valid_to IS NULL OR r.source_cutoff<assignment.valid_to)
                  AND assignment.status='active'
                  AND EXISTS (
                    SELECT 1 FROM jsonb_array_elements(manifest.header_json) pair
                    WHERE pair->>0='canonicalSector'
                      AND pair->>1=assignment.canonical_sector_key::text
                  )
                  AND EXISTS (
                    SELECT 1 FROM jsonb_array_elements(manifest.header_json) pair
                    WHERE pair->>0='entrySession'
                      AND (pair->>1)::date=entry_session.session_id
                  )
                  AND EXISTS (
                    SELECT 1 FROM public.opportunity_manifest_rows_v3 conservation
                    WHERE conservation.manifest_id=manifest.manifest_id
                      AND conservation.section_key='session_conservation'
                      AND conservation.payload_json->>0=maturity_session.session_id::text
                      AND conservation.payload_json->>5='available'
                  )
                ORDER BY benchmark_binding.ordinal LIMIT 1
              ) benchmark ON true
              WHERE binding.run_id=j.run_id AND binding.input_role='outcome_enrich'
                AND NOT EXISTS (
                  SELECT 1 FROM public.opportunity_outcomes outcome
                  WHERE outcome.score_snapshot_id=score.score_snapshot_id
                    AND outcome.maturity_horizon=maturity.maturity_horizon
                )
              ORDER BY input.run_id,score.score_snapshot_id,maturity.maturity_ordinal
              OFFSET (p.payload_json->5->>7)::integer LIMIT 2001
            ) planned
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='outcome_input'
            AND p.payload_json->5->>5='excluded_rows'
          THEN coalesce((
            SELECT jsonb_agg(planned.row_payload ORDER BY
              planned.input_run_id,planned.score_snapshot_id,planned.maturity_ordinal)
            FROM (
              SELECT
                input.run_id AS input_run_id,
                score.score_snapshot_id,
                maturity.maturity_ordinal,
                jsonb_build_array(
                  input.run_id,
                  score.score_snapshot_id,
                  score.payload_hash,
                  score.symbol,
                  score.horizon,
                  score.rank,
                  maturity.maturity_horizon,
                  CASE
                    WHEN entry_price.source_ref IS NULL THEN 'missing_entry_price'
                    WHEN maturity_price.source_ref IS NULL THEN 'missing_outcome_price'
                    ELSE 'missing_sector_benchmark'
                  END,
                  entry_session.session_id,
                  entry_session.taiwan_session_authority_hash,
                  maturity_session.session_id,
                  maturity_session.taiwan_session_authority_hash,
                  entry_price.source_ref,
                  maturity_price.source_ref,
                  benchmark.manifest_hash
                ) AS row_payload
              FROM public.opportunity_run_inputs binding
              JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
              JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
              CROSS JOIN (VALUES
                ('session_20'::public.opportunity_outcome_maturity_v3,20,0),
                ('session_60'::public.opportunity_outcome_maturity_v3,60,1),
                ('session_120'::public.opportunity_outcome_maturity_v3,120,2),
                ('session_250'::public.opportunity_outcome_maturity_v3,250,3)
              ) maturity(maturity_horizon,session_count,maturity_ordinal)
              JOIN LATERAL (
                SELECT session.session_id,session.taiwan_session_authority_hash
                FROM public.opportunity_effective_taiwan_sessions_v3 session
                WHERE session.session_id>input.trading_date
                  AND session.canonical_cutoff<=r.source_cutoff
                ORDER BY session.session_id
                LIMIT 1
              ) entry_session ON true
              JOIN LATERAL (
                SELECT session.session_id,session.taiwan_session_authority_hash
                FROM public.opportunity_effective_taiwan_sessions_v3 session
                WHERE session.session_id>=entry_session.session_id
                  AND session.canonical_cutoff<=r.source_cutoff
                ORDER BY session.session_id
                OFFSET maturity.session_count-1
                LIMIT 1
              ) maturity_session ON true
              LEFT JOIN LATERAL (
                SELECT adjusted.payload->>'ref' AS source_ref
                FROM public.opportunity_price_observations_v3 observation
                CROSS JOIN LATERAL (
                  SELECT public.opportunity_adjusted_price_evidence_v3_internal(
                    observation.observation_id,maturity_session.session_id,r.source_cutoff
                  ) AS payload
                ) adjusted
                WHERE observation.stock_id=score.stock_id
                  AND observation.session_id=entry_session.session_id
                  AND observation.source_timestamp<=r.source_cutoff
                  AND observation.collected_at<=r.source_cutoff
                  AND observation.recorded_at<=r.source_cutoff
                  AND adjusted.payload IS NOT NULL
                ORDER BY observation.recorded_at DESC,observation.observation_id
                LIMIT 1
              ) entry_price ON true
              LEFT JOIN LATERAL (
                SELECT adjusted.payload->>'ref' AS source_ref
                FROM public.opportunity_price_observations_v3 observation
                CROSS JOIN LATERAL (
                  SELECT public.opportunity_adjusted_price_evidence_v3_internal(
                    observation.observation_id,maturity_session.session_id,r.source_cutoff
                  ) AS payload
                ) adjusted
                WHERE observation.stock_id=score.stock_id
                  AND observation.session_id=maturity_session.session_id
                  AND observation.source_timestamp<=r.source_cutoff
                  AND observation.collected_at<=r.source_cutoff
                  AND observation.recorded_at<=r.source_cutoff
                  AND adjusted.payload IS NOT NULL
                ORDER BY observation.recorded_at DESC,observation.observation_id
                LIMIT 1
              ) maturity_price ON true
              LEFT JOIN LATERAL (
                SELECT manifest.manifest_hash
                FROM public.stock_sector_assignments_v3 assignment
                JOIN public.opportunity_run_manifest_inputs benchmark_binding
                  ON benchmark_binding.run_id=j.run_id
                  AND benchmark_binding.input_role='sector_benchmark'
                JOIN public.opportunity_manifests_v3 manifest
                  ON manifest.manifest_id=benchmark_binding.manifest_id
                  AND manifest.status='complete'
                WHERE assignment.stock_id=score.stock_id
                  AND assignment.recorded_at<=r.source_cutoff
                  AND assignment.source_timestamp<=r.source_cutoff
                  AND assignment.valid_from<=r.source_cutoff
                  AND (assignment.valid_to IS NULL OR r.source_cutoff<assignment.valid_to)
                  AND assignment.status='active'
                  AND EXISTS (
                    SELECT 1 FROM jsonb_array_elements(manifest.header_json) pair
                    WHERE pair->>0='canonicalSector'
                      AND pair->>1=assignment.canonical_sector_key::text
                  )
                  AND EXISTS (
                    SELECT 1 FROM jsonb_array_elements(manifest.header_json) pair
                    WHERE pair->>0='entrySession'
                      AND (pair->>1)::date=entry_session.session_id
                  )
                  AND EXISTS (
                    SELECT 1 FROM public.opportunity_manifest_rows_v3 conservation
                    WHERE conservation.manifest_id=manifest.manifest_id
                      AND conservation.section_key='session_conservation'
                      AND conservation.payload_json->>0=maturity_session.session_id::text
                      AND conservation.payload_json->>5='available'
                  )
                ORDER BY benchmark_binding.ordinal LIMIT 1
              ) benchmark ON true
              WHERE binding.run_id=j.run_id
                AND binding.input_role='outcome_enrich'
                AND (
                  entry_price.source_ref IS NULL
                  OR maturity_price.source_ref IS NULL
                  OR benchmark.manifest_hash IS NULL
                )
                AND NOT EXISTS (
                  SELECT 1 FROM public.opportunity_outcomes outcome
                  WHERE outcome.score_snapshot_id=score.score_snapshot_id
                    AND outcome.maturity_horizon=maturity.maturity_horizon
                )
              ORDER BY input.run_id,score.score_snapshot_id,maturity.maturity_ordinal
              OFFSET (p.payload_json->5->>7)::integer
              LIMIT 2001
            ) planned
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='outcome_input'
            AND p.payload_json->5->>5='conservation'
          THEN coalesce((
            SELECT jsonb_agg(conservation.row_payload ORDER BY
              conservation.input_run_id,conservation.maturity_ordinal)
            FROM (
              SELECT input.run_id AS input_run_id,
                maturity.maturity_ordinal,
                jsonb_build_array(
                  input.run_id,
                  maturity.maturity_horizon,
                  counts.included_count+counts.excluded_count,
                  counts.included_count,
                  counts.excluded_count,
                  jsonb_build_object(
                    'calendar_authority_mismatch',counts.calendar_authority_mismatch,
                    'provider_conflict',counts.provider_conflict,
                    'future_observation',counts.future_observation,
                    'missing_entry_session',counts.missing_entry_session,
                    'missing_maturity_session',counts.missing_maturity_session,
                    'missing_entry_price',counts.missing_entry_price,
                    'missing_outcome_price',counts.missing_outcome_price,
                    'missing_sector_benchmark',counts.missing_sector_benchmark,
                    'non_finite_value',counts.non_finite_value,
                    'non_positive_entry_price',counts.non_positive_entry_price
                  )
                ) AS row_payload
              FROM public.opportunity_run_inputs binding
              JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
              CROSS JOIN (VALUES
                ('session_20'::public.opportunity_outcome_maturity_v3,0),
                ('session_60'::public.opportunity_outcome_maturity_v3,1),
                ('session_120'::public.opportunity_outcome_maturity_v3,2),
                ('session_250'::public.opportunity_outcome_maturity_v3,3)
              ) maturity(maturity_horizon,maturity_ordinal)
              CROSS JOIN LATERAL (
                SELECT
                  count(*) FILTER (WHERE row.section_key='input_rows') AS included_count,
                  count(*) FILTER (WHERE row.section_key='excluded_rows') AS excluded_count,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='calendar_authority_mismatch') AS calendar_authority_mismatch,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='provider_conflict') AS provider_conflict,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='future_observation') AS future_observation,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='missing_entry_session') AS missing_entry_session,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='missing_maturity_session') AS missing_maturity_session,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='missing_entry_price') AS missing_entry_price,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='missing_outcome_price') AS missing_outcome_price,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='missing_sector_benchmark') AS missing_sector_benchmark,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='non_finite_value') AS non_finite_value,
                  count(*) FILTER (WHERE row.section_key='excluded_rows'
                    AND row.payload_json->>7='non_positive_entry_price') AS non_positive_entry_price
                FROM public.opportunity_manifest_rows_v3 row
                WHERE row.manifest_id=(p.payload_json->5->>1)::uuid
                  AND row.section_key IN ('input_rows','excluded_rows')
                  AND row.payload_json->>0=input.run_id::text
                  AND row.payload_json->>6=maturity.maturity_horizon::text
              ) counts
              WHERE binding.run_id=j.run_id
                AND binding.input_role='outcome_enrich'
              ORDER BY input.run_id,maturity.maturity_ordinal
              OFFSET (p.payload_json->5->>7)::integer
              LIMIT 2001
            ) conservation
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='evaluation_input'
            AND p.payload_json->5->>5='attempt_roster'
          THEN coalesce((
            SELECT jsonb_agg(jsonb_build_array(
              session.session_id,
              session.taiwan_session_authority_hash,
              session.canonical_cutoff,
              'backtest_daily_primary',
              CASE
                WHEN success.run_id IS NOT NULL THEN 'success'
                WHEN failed.run_id IS NOT NULL THEN 'failed'
                ELSE 'unavailable'
              END,
              CASE WHEN failed.run_id IS NOT NULL THEN failed.run_id ELSE NULL END,
              success.run_id,
              failed.failure_code,
              failed.terminal_at
            ) ORDER BY session.session_id DESC)
            FROM (
              SELECT session_id,taiwan_session_authority_hash,canonical_cutoff
              FROM public.opportunity_effective_taiwan_sessions_v3
              WHERE canonical_cutoff<=r.source_cutoff
              ORDER BY session_id DESC
              LIMIT 252
            ) session
            LEFT JOIN LATERAL (
              SELECT candidate.run_id
              FROM public.opportunity_runs candidate
              JOIN public.opportunity_run_inputs binding
                ON binding.run_id=j.run_id
                AND binding.input_run_id=candidate.run_id
                AND binding.input_role='evaluation_enrich'
              WHERE candidate.mode='enrich_rank'
                AND candidate.run_purpose='backtest_daily_primary'
                AND candidate.trading_date=session.session_id
                AND candidate.status='success'
                AND candidate.terminal_at<=r.source_cutoff
                AND candidate.comparison_contract_key=r.comparison_contract_key
                AND candidate.evaluation_dataset_lock_hash=r.evaluation_dataset_lock_hash
              ORDER BY candidate.run_id
              LIMIT 1
            ) success ON true
            LEFT JOIN LATERAL (
              SELECT candidate.run_id,candidate.failure_code,candidate.terminal_at
              FROM public.opportunity_runs candidate
              WHERE candidate.mode='enrich_rank'
                AND candidate.run_purpose='backtest_daily_primary'
                AND candidate.trading_date=session.session_id
                AND candidate.status='failed'
                AND candidate.terminal_at<=r.source_cutoff
                AND candidate.comparison_contract_key=r.comparison_contract_key
                AND candidate.evaluation_dataset_lock_hash=r.evaluation_dataset_lock_hash
              ORDER BY candidate.terminal_at DESC,candidate.run_id
              LIMIT 1
            ) failed ON success.run_id IS NULL
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='evaluation_input'
            AND p.payload_json->5->>5 IN ('backtest_rows','live_rows')
          THEN coalesce((
            SELECT jsonb_agg(jsonb_build_array(
              qualifying.trading_date,
              qualifying.trading_date_authority_hash,
              qualifying.enrich_run_id,
              qualifying.outcome_run_id,
              qualifying.source_cutoff,
              qualifying.entry_session,
              qualifying.entry_session_authority_hash,
              qualifying.maturity_session,
              qualifying.maturity_session_authority_hash,
              qualifying.filtered_cohort_size,
              qualifying.outcome_input_manifest_hash,
              qualifying.sector_benchmark_manifest_hashes
            ) ORDER BY
              CASE WHEN p.payload_json->5->>5='backtest_rows'
                THEN qualifying.trading_date END ASC,
              CASE WHEN p.payload_json->5->>5='live_rows'
                THEN qualifying.maturity_session END DESC,
              CASE WHEN p.payload_json->5->>5='live_rows'
                THEN qualifying.trading_date END DESC
            )
            FROM (
              SELECT selected.*
              FROM (
                SELECT
                  input.trading_date,
                  trading_session.taiwan_session_authority_hash AS trading_date_authority_hash,
                  input.run_id AS enrich_run_id,
                  outcome_run.run_id AS outcome_run_id,
                  input.source_cutoff,
                  cohort.entry_session,
                  cohort.entry_session_authority_hash,
                  cohort.maturity_session,
                  cohort.maturity_session_authority_hash,
                  cohort.filtered_cohort_size,
                  outcome_manifest.manifest_hash AS outcome_input_manifest_hash,
                  cohort.sector_benchmark_manifest_hashes
                FROM public.opportunity_run_inputs binding
                JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
                JOIN public.opportunity_effective_taiwan_sessions_v3 trading_session
                  ON trading_session.session_id=input.trading_date
                JOIN LATERAL (
                  SELECT label.run_id
                  FROM public.opportunity_run_inputs outcome_binding
                  JOIN public.opportunity_runs label ON label.run_id=outcome_binding.input_run_id
                  JOIN public.opportunity_run_inputs outcome_source
                    ON outcome_source.run_id=label.run_id
                    AND outcome_source.input_run_id=input.run_id
                    AND outcome_source.input_role='outcome_enrich'
                  WHERE outcome_binding.run_id=j.run_id
                    AND outcome_binding.input_role='evaluation_outcome'
                    AND label.status='success'
                  ORDER BY label.source_cutoff DESC,label.run_id
                  LIMIT 1
                ) outcome_run ON true
                JOIN public.opportunity_run_manifest_inputs outcome_manifest_binding
                  ON outcome_manifest_binding.run_id=outcome_run.run_id
                  AND outcome_manifest_binding.input_role='outcome_input'
                  AND outcome_manifest_binding.ordinal=0
                JOIN public.opportunity_manifests_v3 outcome_manifest
                  ON outcome_manifest.manifest_id=outcome_manifest_binding.manifest_id
                  AND outcome_manifest.status='complete'
                JOIN LATERAL (
                  SELECT
                    min(outcome.entry_session) AS entry_session,
                    min(outcome.entry_session_authority_hash) AS entry_session_authority_hash,
                    max(outcome.maturity_session) AS maturity_session,
                    min(outcome.maturity_session_authority_hash) AS maturity_session_authority_hash,
                    count(*)::integer AS filtered_cohort_size,
                    coalesce(jsonb_agg(DISTINCT benchmark.manifest_hash
                      ORDER BY benchmark.manifest_hash),'[]'::jsonb)
                      AS sector_benchmark_manifest_hashes
                  FROM public.opportunity_score_snapshots score
                  JOIN public.opportunity_outcomes outcome
                    ON outcome.score_snapshot_id=score.score_snapshot_id
                    AND outcome.maturity_horizon='session_20'
                  JOIN public.opportunity_manifests_v3 benchmark
                    ON benchmark.manifest_id=outcome.sector_benchmark_manifest_id
                    AND benchmark.status='complete'
                  WHERE score.run_id=input.run_id
                  HAVING count(*)>=10
                    AND count(DISTINCT outcome.entry_session)=1
                    AND count(DISTINCT outcome.entry_session_authority_hash)=1
                    AND count(DISTINCT outcome.maturity_session)=1
                    AND count(DISTINCT outcome.maturity_session_authority_hash)=1
                ) cohort ON true
                WHERE binding.run_id=j.run_id
                  AND binding.input_role='evaluation_enrich'
                  AND input.run_purpose=CASE p.payload_json->5->>5
                    WHEN 'backtest_rows' THEN
                      'backtest_daily_primary'::public.opportunity_run_purpose_v3
                    ELSE 'production_shadow_daily'::public.opportunity_run_purpose_v3
                  END
                ORDER BY
                  CASE WHEN p.payload_json->5->>5='backtest_rows'
                    THEN input.trading_date END DESC,
                  CASE WHEN p.payload_json->5->>5='live_rows'
                    THEN cohort.maturity_session END DESC,
                  CASE WHEN p.payload_json->5->>5='live_rows'
                    THEN input.trading_date END DESC,
                  input.run_id
                LIMIT CASE p.payload_json->5->>5
                  WHEN 'backtest_rows' THEN 120 ELSE 20 END
              ) selected
              ORDER BY
                CASE WHEN p.payload_json->5->>5='backtest_rows'
                  THEN selected.trading_date END ASC,
                CASE WHEN p.payload_json->5->>5='live_rows'
                  THEN selected.maturity_session END DESC,
                CASE WHEN p.payload_json->5->>5='live_rows'
                  THEN selected.trading_date END DESC
            ) qualifying
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='evaluation_input'
            AND p.payload_json->5->>5='cohort_rows'
          THEN coalesce((
            SELECT jsonb_agg(jsonb_build_array(
              cohort.cohort_kind,
              cohort.trading_date,
              cohort.trading_date_authority_hash,
              cohort.symbol,
              cohort.v3_rank,
              NULL,
              cohort.entry_session,
              cohort.entry_session_authority_hash,
              cohort.maturity_session,
              cohort.maturity_session_authority_hash,
              cohort.entry_price_ref,
              cohort.outcome_price_ref,
              cohort.sector_benchmark_manifest_hash,
              cohort.return_pct,
              cohort.sector_relative_return_pct,
              cohort.mfe_pct,
              cohort.mae_pct,
              cohort.sector_relative_mfe_pct,
              least(
                CASE
                  WHEN cohort.sector_relative_mfe_pct>=15 THEN 3
                  WHEN cohort.sector_relative_mfe_pct>=10 THEN 2
                  WHEN cohort.sector_relative_mfe_pct>=5 THEN 1
                  ELSE 0
                END,
                CASE WHEN cohort.mae_pct < -12 THEN 1 ELSE 3 END
              )
            ) ORDER BY
              cohort.cohort_ordinal,cohort.trading_date,cohort.symbol
            )
            FROM (
              SELECT
                CASE selected_date.section_key
                  WHEN 'backtest_rows' THEN 'backtest' ELSE 'live' END AS cohort_kind,
                CASE selected_date.section_key
                  WHEN 'backtest_rows' THEN 0 ELSE 1 END AS cohort_ordinal,
                (selected_date.payload_json->>0)::date AS trading_date,
                selected_date.payload_json->>1 AS trading_date_authority_hash,
                score.symbol,
                score.rank AS v3_rank,
                outcome.entry_session,
                outcome.entry_session_authority_hash,
                outcome.maturity_session,
                outcome.maturity_session_authority_hash,
                outcome.entry_price_ref,
                outcome.outcome_price_ref,
                benchmark.manifest_hash AS sector_benchmark_manifest_hash,
                outcome.return_pct,
                outcome.sector_relative_return_pct,
                outcome.mfe_pct,
                outcome.mae_pct,
                outcome.sector_relative_mfe_pct
              FROM public.opportunity_manifest_rows_v3 selected_date
              JOIN public.opportunity_score_snapshots score
                ON score.run_id=(selected_date.payload_json->>2)::uuid
                AND score.horizon='swing_20_60d'
              JOIN public.opportunity_outcomes outcome
                ON outcome.score_snapshot_id=score.score_snapshot_id
                AND outcome.maturity_horizon='session_20'
              JOIN public.opportunity_manifests_v3 benchmark
                ON benchmark.manifest_id=outcome.sector_benchmark_manifest_id
                AND benchmark.status='complete'
              WHERE selected_date.manifest_id=(p.payload_json->5->>1)::uuid
                AND selected_date.section_key IN ('backtest_rows','live_rows')
              ORDER BY cohort_ordinal,trading_date,score.symbol
              OFFSET (p.payload_json->5->>7)::integer
              LIMIT 2001
            ) cohort
          ),'[]'::jsonb)
          WHEN p.payload_json->5->>2='evaluation_input'
            AND p.payload_json->5->>5='conservation'
          THEN coalesce((
            SELECT jsonb_agg(jsonb_build_array(
              CASE selected_date.section_key
                WHEN 'backtest_rows' THEN 'backtest' ELSE 'live' END,
              selected_date.payload_json->0,
              (selected_date.payload_json->>9)::integer,
              (selected_date.payload_json->>9)::integer,
              0,
              jsonb_build_object(
                'provider_conflict',0,
                'future_observation',0,
                'unsupported_instrument',0,
                'missing_entry_close',0,
                'missing_outcome_close',0,
                'missing_sector_benchmark',0,
                'non_finite_value',0,
                'non_positive_entry_price',0,
                'cohort_below_10',0
              ),
              true
            ) ORDER BY
              CASE selected_date.section_key
                WHEN 'backtest_rows' THEN 0 ELSE 1 END,
              (selected_date.payload_json->>0)::date
            )
            FROM public.opportunity_manifest_rows_v3 selected_date
            WHERE selected_date.manifest_id=(p.payload_json->5->>1)::uuid
              AND selected_date.section_key IN ('backtest_rows','live_rows')
          ),'[]'::jsonb)
          ELSE NULL
        END
      )
      WHEN 'manifest_root' THEN jsonb_build_array(
        (SELECT m.header_json FROM public.opportunity_manifests_v3 m
          WHERE m.manifest_id=(p.payload_json->5->>1)::uuid),
        (
          SELECT jsonb_agg(jsonb_build_array(
            spec.section_key,coalesce(row_totals.row_count,0),coalesce(page_totals.pages,'[]'::jsonb)
          ) ORDER BY spec.section_ordinal)
          FROM (VALUES
            ('source_eligible','rows',1),
            ('source_identity_allowlist','rows',1),
            ('publisher_verification_allowlist','rows',1),
            ('instrument_roster','rows',1),
            ('alias_authority','rows',1),
            ('taxonomy_assignment','rows',1),
            ('peer_reviewer_allowlist','rows',1),
            ('peer_authority','selected_rows',1),('peer_authority','excluded_rows',2),
            ('source_dataset','connector_roots',1),('source_dataset','selected_revision_rows',2),
              ('source_dataset','connector_conservation',3),
            ('candidate_financial','selected_facts',1),('candidate_financial','excluded_facts',2),
              ('candidate_financial','conservation',3),
            ('factor_scoring_reference','included_rows',1),('factor_scoring_reference','excluded_rows',2),
              ('factor_scoring_reference','conservation',3),
            ('sector_scoring_reference','market_benchmark_rows',1),
              ('sector_scoring_reference','sector_aggregate_rows',2),
              ('sector_scoring_reference','sector_aggregate_exclusions',3),
              ('sector_scoring_reference','aggregate_evidence_rows',4),
              ('sector_scoring_reference','sector_excess_included_rows',5),
              ('sector_scoring_reference','sector_excess_excluded_rows',6),
              ('sector_scoring_reference','conservation',7),
            ('sector_valuation_reference','included_rows',1),
              ('sector_valuation_reference','excluded_rows',2),
              ('sector_valuation_reference','aggregate_rows',3),
              ('sector_valuation_reference','conservation',4),
            ('bias_reference','current_rows',1),('bias_reference','excluded_rows',2),
              ('bias_reference','sector_rows',3),('bias_reference','conservation',4),
            ('technical_history_reference','market_benchmark_rows',1),
              ('technical_history_reference','raw_adjusted_rows',2),
              ('technical_history_reference','history_rows',3),
              ('technical_history_reference','excluded_rows',4),
              ('technical_history_reference','conservation',5),
            ('reported_pe_reference','own_history_rows',1),
              ('reported_pe_reference','sector_current_rows',2),
              ('reported_pe_reference','excluded_rows',3),
              ('reported_pe_reference','sector_rows',4),
              ('reported_pe_reference','conservation',5),
            ('market_reference','included_rows',1),('market_reference','excluded_rows',2),
              ('market_reference','conservation',3),
            ('mover_price_reference','included_rows',1),('mover_price_reference','excluded_rows',2),
              ('mover_price_reference','conservation',3),
            ('sector_benchmark','entry_rows',1),('sector_benchmark','evaluation_rows',2),
              ('sector_benchmark','session_conservation',3),
            ('outcome_input','input_rows',1),('outcome_input','excluded_rows',2),
              ('outcome_input','conservation',3),
            ('evaluation_input','attempt_roster',1),('evaluation_input','backtest_rows',2),
              ('evaluation_input','live_rows',3),('evaluation_input','cohort_rows',4),
              ('evaluation_input','exclusion_rows',5),('evaluation_input','conservation',6),
            ('link_audit_sample','strata',1),('link_audit_sample','samples',2),
            ('link_audit_resolution','resolved_rows',1),('link_audit_resolution','unresolved_rows',2)
          ) spec(kind,section_key,section_ordinal)
          LEFT JOIN LATERAL (
            SELECT count(*)::bigint AS row_count
            FROM public.opportunity_manifest_rows_v3 mr
            WHERE mr.manifest_id=(p.payload_json->5->>1)::uuid
              AND mr.section_key=spec.section_key::public.opportunity_manifest_section_key_v3
          ) row_totals ON true
          LEFT JOIN LATERAL (
            SELECT jsonb_agg(jsonb_build_array(
              mp.page_ordinal,first_row.row_ordinal,mp.row_count,
              first_row.identity_key,last_row.identity_key,mp.page_hash
            ) ORDER BY mp.page_ordinal) AS pages
            FROM public.opportunity_manifest_pages_v3 mp
            LEFT JOIN LATERAL (
              SELECT mr.row_ordinal,mr.identity_key
              FROM public.opportunity_manifest_rows_v3 mr
              WHERE mr.manifest_id=mp.manifest_id AND mr.section_key=mp.section_key
              ORDER BY mr.row_ordinal
              OFFSET (
                SELECT coalesce(sum(prior.row_count),0)::integer
                FROM public.opportunity_manifest_pages_v3 prior
                WHERE prior.manifest_id=mp.manifest_id
                  AND prior.section_key=mp.section_key
                  AND prior.page_ordinal<mp.page_ordinal
              ) LIMIT 1
            ) first_row ON true
            LEFT JOIN LATERAL (
              SELECT mr.identity_key
              FROM public.opportunity_manifest_rows_v3 mr
              WHERE mr.manifest_id=mp.manifest_id AND mr.section_key=mp.section_key
              ORDER BY mr.row_ordinal
              OFFSET (
                SELECT coalesce(sum(prior.row_count),0)::integer+mp.row_count-1
                FROM public.opportunity_manifest_pages_v3 prior
                WHERE prior.manifest_id=mp.manifest_id
                  AND prior.section_key=mp.section_key
                  AND prior.page_ordinal<mp.page_ordinal
              ) LIMIT 1
            ) last_row ON true
            WHERE mp.manifest_id=(p.payload_json->5->>1)::uuid
              AND mp.section_key=spec.section_key::public.opportunity_manifest_section_key_v3
          ) page_totals ON true
          WHERE spec.kind=p.payload_json->5->>2
        )
      )
      WHEN 'source_parse_batch' THEN (
        SELECT jsonb_build_array(
          d.revision_id,(p.payload_json->5->>2)::integer,d.source_key,
          d.approved_source_identity_id,d.stable_connector_document_id,
          d.canonical_url_candidate,d.published_at,d.collected_at,d.raw_field_payload,
          d.raw_code_point_count,d.adapter_version,d.acquisition_status,
          d.ingestion_canonical_content_hash_v3,
          source_identity.source_class,source_identity.distribution_identity,
          link_authority.authority_rows,deduplication.prior_rows
        )
        FROM public.source_document_revisions_v3 d
        JOIN LATERAL (
          SELECT
            identity_row.payload_json->>3 AS source_class,
            identity_row.payload_json->>4 AS distribution_identity
          FROM public.opportunity_run_manifest_inputs identity_binding
          JOIN public.opportunity_manifest_rows_v3 identity_row
            ON identity_row.manifest_id=identity_binding.manifest_id
            AND identity_row.section_key='rows'
          WHERE identity_binding.run_id=j.run_id
            AND identity_binding.input_role='source_identity_allowlist'
            AND identity_binding.ordinal=0
            AND (identity_row.payload_json->>0)::uuid=d.source_identity_authority_id
            AND (identity_row.payload_json->>1)::uuid=d.approved_source_identity_id
            AND identity_row.payload_json->>2=d.source_key::text
            AND identity_row.payload_json->>7='active'
            AND (identity_row.payload_json->>5)::timestamptz<=r.source_cutoff
            AND (
              identity_row.payload_json->6='null'::jsonb
              OR r.source_cutoff<(identity_row.payload_json->>6)::timestamptz
            )
          ORDER BY identity_row.row_ordinal
          LIMIT 1
        ) source_identity ON true
        JOIN LATERAL (
          WITH authority_manifests AS MATERIALIZED (
            SELECT input_role,manifest_id
            FROM public.opportunity_run_manifest_inputs
            WHERE run_id=j.run_id
              AND input_role IN (
                'instrument_roster','alias_authority','taxonomy_assignment'
              )
              AND ordinal=0
          ), roster AS MATERIALIZED (
            SELECT
              (row.payload_json->>1)::uuid AS stock_id,
              row.payload_json->>2 AS symbol,
              row.payload_json->>3 AS exchange,
              row.payload_json->>4 AS instrument_type,
              row.payload_json->>5 AS listing_status,
              row.payload_json->>6 AS official_name
            FROM authority_manifests binding
            JOIN public.opportunity_manifest_rows_v3 row
              ON row.manifest_id=binding.manifest_id
              AND row.section_key='rows'
            WHERE binding.input_role='instrument_roster'
              AND row.payload_json->>4='common_stock'
              AND row.payload_json->>5='active'
              AND (row.payload_json->>9)::timestamptz<=r.source_cutoff
              AND (
                row.payload_json->10='null'::jsonb
                OR r.source_cutoff<(row.payload_json->>10)::timestamptz
              )
          ), active_aliases AS MATERIALIZED (
            SELECT
              (row.payload_json->>2)::uuid AS stock_id,
              row.payload_json->>1 AS normalized_alias
            FROM authority_manifests binding
            JOIN public.opportunity_manifest_rows_v3 row
              ON row.manifest_id=binding.manifest_id
              AND row.section_key='rows'
            WHERE binding.input_role='alias_authority'
              AND row.payload_json->>9='active'
              AND char_length(row.payload_json->>1) BETWEEN 2 AND 40
              AND (row.payload_json->>7)::timestamptz<=r.source_cutoff
              AND (
                row.payload_json->8='null'::jsonb
                OR r.source_cutoff<(row.payload_json->>8)::timestamptz
              )
          ), active_taxonomy AS MATERIALIZED (
            SELECT
              (row.payload_json->>1)::uuid AS stock_id,
              row.payload_json->>2 AS market,
              row.payload_json->>4 AS canonical_sector_key
            FROM authority_manifests binding
            JOIN public.opportunity_manifest_rows_v3 row
              ON row.manifest_id=binding.manifest_id
              AND row.section_key='rows'
            WHERE binding.input_role='taxonomy_assignment'
              AND row.payload_json->>10='active'
              AND (row.payload_json->>7)::timestamptz<=r.source_cutoff
              AND (
                row.payload_json->8='null'::jsonb
                OR r.source_cutoff<(row.payload_json->>8)::timestamptz
              )
          ), eligible AS MATERIALIZED (
            SELECT roster.*,
              coalesce(alias_bundle.aliases,'[]'::jsonb) AS aliases,
              coalesce(sector.canonical_sector_key,'unknown') AS canonical_sector_key
            FROM roster
            LEFT JOIN LATERAL (
              SELECT jsonb_agg(DISTINCT alias.normalized_alias
                ORDER BY alias.normalized_alias) AS aliases
              FROM active_aliases alias
              WHERE alias.stock_id=roster.stock_id
            ) alias_bundle ON true
            LEFT JOIN LATERAL (
              SELECT taxonomy.canonical_sector_key
              FROM active_taxonomy taxonomy
              WHERE taxonomy.stock_id=roster.stock_id
              ORDER BY taxonomy.market,taxonomy.canonical_sector_key
              LIMIT 1
            ) sector ON true
            WHERE (
              roster.symbol~'^[0-9]{4}$'
              AND lower(d.raw_field_payload::text)
                ~ ('(^|[^0-9])'||roster.symbol||'([^0-9]|$)')
            ) OR (
              roster.official_name IS NOT NULL
              AND char_length(roster.official_name)>=2
              AND position(lower(roster.official_name)
                IN lower(d.raw_field_payload::text))>0
            ) OR EXISTS (
              SELECT 1
              FROM active_aliases alias
              WHERE alias.stock_id=roster.stock_id
                AND (
                  position(alias.normalized_alias
                    IN lower(d.raw_field_payload::text))>0
                  OR EXISTS (
                    SELECT 1
                    FROM regexp_matches(
                      lower(d.raw_field_payload::text),
                      '([[:alnum:]一-龥]{2,40})',
                      'g'
                    ) token
                    WHERE 1.0-(
                      public.opportunity_levenshtein_v3_internal(
                        alias.normalized_alias,token[1]
                      )::double precision
                      / greatest(
                          char_length(alias.normalized_alias),
                          char_length(token[1])
                        )
                    )>=0.50
                  )
                )
            )
            ORDER BY roster.symbol,roster.stock_id
            LIMIT 257
          ), bounded AS (
            SELECT eligible.*,
              count(*) OVER () AS candidate_count,
              count(*) OVER (PARTITION BY symbol) AS symbol_count
            FROM eligible
          )
          SELECT coalesce(jsonb_agg(jsonb_build_array(
            stock_id,symbol,exchange,instrument_type,listing_status,official_name,
            aliases,canonical_sector_key
          ) ORDER BY symbol,stock_id),'[]'::jsonb) AS authority_rows
          FROM bounded
          HAVING count(*)<=256 AND coalesce(max(symbol_count),1)=1
        ) link_authority ON true
        CROSS JOIN LATERAL (
          SELECT coalesce(jsonb_agg(jsonb_build_array(
            encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
              prior.payload_json->>0,prior.payload_json->>3,
              coalesce(prior.payload_json->>5,prior.payload_json->>4)
            )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'),
            CASE WHEN prior.payload_json->14='null'::jsonb THEN NULL ELSE prior.payload_json->>14 END
          ) ORDER BY prior.row_ordinal),'[]'::jsonb) AS prior_rows
          FROM public.opportunity_run_manifest_inputs dataset_binding
          JOIN public.opportunity_manifest_rows_v3 prior
            ON prior.manifest_id=dataset_binding.manifest_id
            AND prior.section_key='selected_revision_rows'
          WHERE dataset_binding.run_id=j.run_id
            AND dataset_binding.input_role='source_dataset'
            AND dataset_binding.ordinal=0
            AND prior.payload_json->>0=d.source_key::text
            AND prior.payload_json->>3=d.approved_source_identity_id::text
            AND prior.row_ordinal<(p.payload_json->5->>2)::integer
          HAVING count(*)<=999
        ) deduplication
        WHERE d.revision_id=(p.payload_json->5->4->0->>0)::uuid
          AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
          AND d.recorded_at<=r.source_cutoff
      )
      WHEN 'source_connector_summary' THEN jsonb_build_object(
          'sourceKey',p.payload_json->5->>1,
          'eligibleDocuments',(
            SELECT (pair->>1)::integer
            FROM public.opportunity_run_manifest_inputs i
            JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
            CROSS JOIN LATERAL jsonb_array_elements(m.header_json) pair
            WHERE i.run_id=j.run_id AND i.input_role='source_eligible'
              AND pair->>0='eligibleCount'
              AND EXISTS (
                SELECT 1 FROM jsonb_array_elements(m.header_json) source_pair
                WHERE source_pair->>0='sourceKey'
                  AND source_pair->>1=p.payload_json->5->>1
              )
          ),
          'selectedDocuments',(SELECT count(*) FROM public.opportunity_source_document_outcomes d
            WHERE d.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3),
          'deferredDueScanCap',greatest(0,(
            SELECT (pair->>1)::integer
            FROM public.opportunity_run_manifest_inputs i
            JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
            CROSS JOIN LATERAL jsonb_array_elements(m.header_json) pair
            WHERE i.run_id=j.run_id AND i.input_role='source_eligible'
              AND pair->>0='eligibleCount'
              AND EXISTS (
                SELECT 1 FROM jsonb_array_elements(m.header_json) source_pair
                WHERE source_pair->>0='sourceKey'
                  AND source_pair->>1=p.payload_json->5->>1
              )
          )-1000),
          'documentOutcomes',jsonb_build_object(
            'duplicate_document',(SELECT count(*) FROM public.opportunity_source_document_outcomes d
              WHERE d.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND d.outcome='duplicate_document'),
            'expired_document',(SELECT count(*) FROM public.opportunity_source_document_outcomes d
              WHERE d.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND d.outcome='expired_document'),
            'parse_failure',(SELECT count(*) FROM public.opportunity_source_document_outcomes d
              WHERE d.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND d.outcome='parse_failure'),
            'processed_no_claim',(SELECT count(*) FROM public.opportunity_source_document_outcomes d
              WHERE d.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND d.outcome='processed_no_claim'),
            'processed_with_claims',(SELECT count(*) FROM public.opportunity_source_document_outcomes d
              WHERE d.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND d.outcome='processed_with_claims')
          ),
          'extractedClaims',(SELECT count(*) FROM public.opportunity_source_claims c
            JOIN public.source_document_revisions_v3 d ON d.revision_id=c.revision_id
            WHERE c.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3),
          'claimOutcomes',jsonb_build_object(
            'unique_claim',(SELECT count(*) FROM public.opportunity_source_claims c
              JOIN public.source_document_revisions_v3 d ON d.revision_id=c.revision_id
              WHERE c.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND c.outcome='unique_claim'),
            'duplicate_claim',(SELECT count(*) FROM public.opportunity_source_claims c
              JOIN public.source_document_revisions_v3 d ON d.revision_id=c.revision_id
              WHERE c.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND c.outcome='duplicate_claim')
          ),
          'rawMentions',(SELECT count(*) FROM public.opportunity_source_mentions mention
            JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
            WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3),
          'mentionOutcomes',jsonb_build_object(
            'linked_new',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.outcome='linked_new'),
            'linked_refresh',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.outcome='linked_refresh'),
            'linked_duplicate_claim',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.outcome='linked_duplicate_claim'),
            'ambiguous_symbol',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.outcome='ambiguous_symbol'),
            'rejected_low_confidence',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.outcome='rejected_low_confidence'),
            'unsupported_instrument',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.outcome='unsupported_instrument')
          ),
          'mentionReasonCounts',jsonb_build_object(
            'explicit_ticker_context',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='explicit_ticker_context'),
            'exact_unique_alias_context',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='exact_unique_alias_context'),
            'ambiguous_number',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='ambiguous_number'),
            'ambiguous_alias',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='ambiguous_alias'),
            'fuzzy_below_auto_threshold',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='fuzzy_below_auto_threshold'),
            'below_min_confidence',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='below_min_confidence'),
            'inactive_or_unknown_symbol',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='inactive_or_unknown_symbol'),
            'missing_stock_context',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='missing_stock_context'),
            'unsupported_market',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='unsupported_market'),
            'non_common_stock',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='non_common_stock'),
            'unsupported_instrument_type',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='unsupported_instrument_type'),
            'duplicate_claim_link',(SELECT count(*) FROM public.opportunity_source_mentions mention
              JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
              WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
                AND mention.reason='duplicate_claim_link')
          ),
          'linkedCandidateCount',(SELECT count(DISTINCT mention.stock_id)
            FROM public.opportunity_source_mentions mention
            JOIN public.source_document_revisions_v3 d ON d.revision_id=mention.revision_id
            WHERE mention.run_id=j.run_id AND d.source_key=(p.payload_json->5->>1)::public.source_key_v3
              AND mention.outcome IN ('linked_new','linked_refresh','linked_duplicate_claim')),
          'status','ok','failureReason',NULL
      )
      WHEN 'market_context_snapshot' THEN (
        SELECT jsonb_build_array(
          coalesce(jsonb_agg(row.payload_json ORDER BY row.row_ordinal)
            FILTER (WHERE row.section_key='included_rows'),'[]'::jsonb),
          coalesce(jsonb_agg(row.payload_json ORDER BY row.row_ordinal)
            FILTER (WHERE row.section_key='excluded_rows'),'[]'::jsonb),
          coalesce(jsonb_agg(row.payload_json ORDER BY row.row_ordinal)
            FILTER (WHERE row.section_key='conservation'),'[]'::jsonb)
        )
        FROM public.opportunity_run_manifest_inputs binding
        JOIN public.opportunity_manifests_v3 manifest
          ON manifest.manifest_id=binding.manifest_id
          AND manifest.manifest_kind='market_reference'
          AND manifest.status='complete'
        LEFT JOIN public.opportunity_manifest_rows_v3 row
          ON row.manifest_id=manifest.manifest_id
          AND row.section_key IN (
            'included_rows','excluded_rows','conservation'
          )
        WHERE binding.run_id=j.run_id
          AND binding.input_role='market_reference'
          AND binding.ordinal=0
          AND binding.manifest_id=(p.payload_json->5->>0)::uuid
        HAVING count(*) FILTER (
          WHERE row.section_key IN ('included_rows','excluded_rows')
        )<=1024
          AND count(*) FILTER (WHERE row.section_key='conservation')<=64
      )
      WHEN 'shallow_candidate_batch' THEN jsonb_build_array(
        coalesce((
          SELECT jsonb_agg(jsonb_build_array(
            plan.candidate_ordinal,plan.stock_id,plan.symbol,true,'direct_candidate',
            plan.anchor_claim_id,plan.source_key,plan.canonical_sector_key,
            plan.priority_score,
            CASE WHEN claim.source_ref IS NULL
              THEN '[]'::jsonb ELSE jsonb_build_array(claim.source_ref) END
          ) ORDER BY requested.ordinal)
          FROM jsonb_array_elements_text(p.payload_json->5->2)
            WITH ORDINALITY requested(symbol,ordinal)
          JOIN public.opportunity_candidate_plan_v3_internal(j.run_id,'shallow') plan
            ON plan.symbol=requested.symbol
          JOIN public.opportunity_source_claims claim
            ON claim.claim_id=plan.anchor_claim_id
          WHERE requested.ordinal<=5
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(row.payload_json ORDER BY requested.ordinal,row.row_ordinal)
          FROM jsonb_array_elements_text(p.payload_json->5->2)
            WITH ORDINALITY requested(symbol,ordinal)
          JOIN public.opportunity_run_manifest_inputs binding
            ON binding.run_id=j.run_id
            AND binding.input_role='market_reference'
            AND binding.ordinal=0
          JOIN public.opportunity_manifest_rows_v3 row
            ON row.manifest_id=binding.manifest_id
            AND row.section_key='included_rows'
            AND row.payload_json->>0='candidate_factor'
            AND row.payload_json->>3=requested.symbol
          WHERE requested.ordinal<=5
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(row.payload_json ORDER BY sector_key,row.row_ordinal)
          FROM (
            SELECT DISTINCT plan.canonical_sector_key::text AS sector_key
            FROM jsonb_array_elements_text(p.payload_json->5->2)
              WITH ORDINALITY requested(symbol,ordinal)
            JOIN public.opportunity_candidate_plan_v3_internal(j.run_id,'shallow') plan
              ON plan.symbol=requested.symbol
            WHERE requested.ordinal<=5
          ) candidate_sector
          JOIN public.opportunity_run_manifest_inputs binding
            ON binding.run_id=j.run_id
            AND binding.input_role='sector_scoring_reference'
            AND binding.ordinal=0
          JOIN public.opportunity_manifest_rows_v3 row
            ON row.manifest_id=binding.manifest_id
            AND row.section_key='sector_aggregate_rows'
            AND row.payload_json->>1=candidate_sector.sector_key
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(peer_row ORDER BY candidate_ordinal,peer_ordinal)
          FROM (
            SELECT plan.candidate_ordinal,peer.peer_ordinal,peer.payload_json AS peer_row
            FROM jsonb_array_elements_text(p.payload_json->5->2)
              WITH ORDINALITY requested(symbol,ordinal)
            JOIN public.opportunity_candidate_plan_v3_internal(j.run_id,'shallow') plan
              ON plan.symbol=requested.symbol
            JOIN LATERAL (
              SELECT row.payload_json,
                row_number() OVER (ORDER BY row.row_ordinal)-1 AS peer_ordinal
              FROM public.opportunity_run_manifest_inputs binding
              JOIN public.opportunity_manifest_rows_v3 row
                ON row.manifest_id=binding.manifest_id
                AND row.section_key='selected_rows'
              WHERE binding.run_id=j.run_id
                AND binding.input_role='peer_authority'
                AND binding.ordinal=0
                AND (
                  row.payload_json->>3=plan.symbol
                  OR row.payload_json->>6=plan.symbol
                )
              ORDER BY row.row_ordinal
              LIMIT 3
            ) peer ON true
            WHERE requested.ordinal<=5
          ) bounded_peers
        ),'[]'::jsonb)
      )
      WHEN 'sector_cycle_batch' THEN coalesce((
        SELECT jsonb_agg(jsonb_build_array(
          requested.sector_key,
          jsonb_build_object(
            'asOf',r.source_cutoff,
            'breadth20d',sector_evidence.breadth20d,
            'epsLevel',sector_evidence.eps_level,
            'excess20d',sector_evidence.excess20d,
            'excess60d',sector_evidence.excess60d,
            'sectorReferenceCount',sector_evidence.sector_reference_count,
            'inputs',sector_evidence.inputs,
            'marginChange',sector_evidence.margin_change,
            'revenueChange',sector_evidence.revenue_change,
            'revenueLevel',sector_evidence.revenue_level
          )
        ) ORDER BY requested.ordinal)
        FROM jsonb_array_elements_text(p.payload_json->5->2)
          WITH ORDINALITY requested(sector_key,ordinal)
        LEFT JOIN LATERAL (
          SELECT
            max((reference.payload_json->>2)::double precision) FILTER (
              WHERE reference.payload_json->>0='sector_ad_breadth_20d'
            ) AS breadth20d,
            max((reference.payload_json->>2)::double precision) FILTER (
              WHERE reference.payload_json->>0='sector_eps_yoy_median'
            ) AS eps_level,
            max((reference.payload_json->>2)::double precision) FILTER (
              WHERE reference.payload_json->>0='sector_excess_return_20d'
            ) AS excess20d,
            max((reference.payload_json->>2)::double precision) FILTER (
              WHERE reference.payload_json->>0='sector_excess_return_60d'
            ) AS excess60d,
            max((reference.payload_json->>2)::double precision) FILTER (
              WHERE reference.payload_json->>0='sector_operating_margin_delta_median'
            ) AS margin_change,
            max((reference.payload_json->>2)::double precision) FILTER (
              WHERE reference.payload_json->>0='sector_revenue_acceleration_median'
            ) AS revenue_change,
            max((reference.payload_json->>2)::double precision) FILTER (
              WHERE reference.payload_json->>0='sector_revenue_yoy_median'
            ) AS revenue_level,
            max((reference.payload_json->>5)::integer) AS sector_reference_count,
            coalesce(jsonb_agg(DISTINCT reference.payload_json->>8)
              FILTER (WHERE reference.payload_json->>8 IS NOT NULL),'[]'::jsonb) AS inputs
          FROM public.opportunity_manifest_rows_v3 reference
          WHERE reference.manifest_id=(p.payload_json->5->>3)::uuid
            AND reference.section_key='sector_aggregate_rows'
            AND reference.payload_json->>1=requested.sector_key
        ) sector_evidence ON true
      ),'[]'::jsonb)
      WHEN 'deep_candidate_batch' THEN jsonb_build_array(
        coalesce((
          SELECT jsonb_agg(jsonb_build_array(
            shallow.candidate_ordinal,shallow.stock_id,shallow.symbol,
            shallow.direct_source,shallow.candidate_origin,shallow.anchor_claim_id,
            shallow.canonical_sector_key,r.source_cutoff,
            (shallow.payload_json->>5)::double precision,
            (shallow.payload_json->>6)::double precision,
            (shallow.payload_json->>7)::double precision,
            (shallow.payload_json->>8)::double precision,
            mover.current_price,mover.price_ref,
            market.payload_json,sector.payload_json,
            financial_manifest.manifest_hash,valuation_manifest.manifest_hash,
            prior_detail.payload_json#>>'{card,materialChangeHash}',
            prior_detail.payload_json#>>'{card,analysisGeneratedAt}'
          ) ORDER BY requested.ordinal)
          FROM jsonb_array_elements_text(p.payload_json->5->2)
            WITH ORDINALITY requested(symbol,ordinal)
          JOIN public.opportunity_shallow_candidate_results_v3 shallow
            ON shallow.run_id=j.run_id
            AND shallow.symbol=requested.symbol
            AND shallow.direct_source
            AND shallow.candidate_origin='direct_candidate'
            AND shallow.anchor_claim_id IS NOT NULL
            AND shallow.shallow_status='succeeded'
          LEFT JOIN public.opportunity_market_context_snapshots market
            ON market.run_id=j.run_id
          LEFT JOIN public.opportunity_sector_cycle_snapshots sector
            ON sector.run_id=j.run_id
            AND sector.canonical_sector_key=shallow.canonical_sector_key
          JOIN public.opportunity_run_manifest_inputs financial_binding
            ON financial_binding.run_id=j.run_id
            AND financial_binding.input_role='candidate_financial'
            AND financial_binding.ordinal=0
          JOIN public.opportunity_manifests_v3 financial_manifest
            ON financial_manifest.manifest_id=financial_binding.manifest_id
            AND financial_manifest.status='complete'
          JOIN public.opportunity_run_manifest_inputs valuation_binding
            ON valuation_binding.run_id=j.run_id
            AND valuation_binding.input_role='sector_valuation_reference'
            AND valuation_binding.ordinal=0
          JOIN public.opportunity_manifests_v3 valuation_manifest
            ON valuation_manifest.manifest_id=valuation_binding.manifest_id
            AND valuation_manifest.status='complete'
          LEFT JOIN LATERAL (
            SELECT prior_projection.payload_json
            FROM (
              SELECT candidate.run_id
              FROM public.opportunity_runs candidate
              WHERE candidate.mode='enrich_rank'
                AND candidate.status='success'
                AND candidate.comparison_contract_key=r.comparison_contract_key
                AND candidate.source_cutoff<r.source_cutoff
              ORDER BY candidate.source_cutoff DESC,candidate.terminal_at DESC,candidate.run_id
              LIMIT 1
            ) prior_owner
            LEFT JOIN public.opportunity_detail_projections_v3 prior_projection
              ON prior_projection.run_id=prior_owner.run_id
              AND prior_projection.symbol=shallow.symbol
          ) prior_detail ON true
          LEFT JOIN LATERAL (
            SELECT (row.payload_json->>8)::double precision AS current_price,
              row.payload_json->>13 AS price_ref
            FROM public.opportunity_run_manifest_inputs binding
            JOIN public.opportunity_manifest_rows_v3 row
              ON row.manifest_id=binding.manifest_id
              AND row.section_key='included_rows'
              AND row.payload_json->>0=shallow.symbol
            WHERE binding.run_id=j.run_id
              AND binding.input_role='mover_price_reference'
              AND binding.ordinal=0
            ORDER BY row.row_ordinal LIMIT 1
          ) mover ON true
          WHERE requested.ordinal<=5
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(fact.payload_json ORDER BY requested.ordinal,fact.row_ordinal)
          FROM jsonb_array_elements_text(p.payload_json->5->2)
            WITH ORDINALITY requested(symbol,ordinal)
          JOIN public.opportunity_run_manifest_inputs binding
            ON binding.run_id=j.run_id
            AND binding.input_role='candidate_financial'
            AND binding.ordinal=0
          JOIN public.opportunity_manifest_rows_v3 fact
            ON fact.manifest_id=binding.manifest_id
            AND fact.section_key='selected_facts'
            AND fact.payload_json->>0=requested.symbol
          WHERE requested.ordinal<=5
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(factor.payload_json ORDER BY requested.ordinal,factor.row_ordinal)
          FROM jsonb_array_elements_text(p.payload_json->5->2)
            WITH ORDINALITY requested(symbol,ordinal)
          JOIN public.opportunity_run_manifest_inputs binding
            ON binding.run_id=j.run_id
            AND binding.input_role='market_reference'
            AND binding.ordinal=0
          JOIN public.opportunity_manifest_rows_v3 factor
            ON factor.manifest_id=binding.manifest_id
            AND factor.section_key='included_rows'
            AND factor.payload_json->>0='candidate_factor'
            AND factor.payload_json->>3=requested.symbol
          WHERE requested.ordinal<=5
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(reference.payload_json
            ORDER BY candidate_sector.candidate_ordinal,reference.row_ordinal)
          FROM (
            SELECT shallow.candidate_ordinal,
              shallow.canonical_sector_key::text AS sector_key
            FROM jsonb_array_elements_text(p.payload_json->5->2)
              WITH ORDINALITY requested(symbol,ordinal)
            JOIN public.opportunity_shallow_candidate_results_v3 shallow
              ON shallow.run_id=j.run_id AND shallow.symbol=requested.symbol
              AND shallow.direct_source
              AND shallow.candidate_origin='direct_candidate'
              AND shallow.shallow_status='succeeded'
            WHERE requested.ordinal<=5
          ) candidate_sector
          JOIN public.opportunity_run_manifest_inputs binding
            ON binding.run_id=j.run_id
            AND binding.input_role='sector_valuation_reference'
            AND binding.ordinal=0
          JOIN public.opportunity_manifest_rows_v3 reference
            ON reference.manifest_id=binding.manifest_id
            AND reference.section_key='aggregate_rows'
            AND reference.payload_json->>0=candidate_sector.sector_key
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(jsonb_build_array(
            verification.verification_id,verification.symbol,
            verification.input_hash,verification.decision,
            verification.reason_codes,verification.evidence_refs,
            verification.valuation_computed_at,verification.review_timestamp,
            verification.expires_at,verification.reviewer_principal_id,
            verification.recorded_at
          ) ORDER BY requested.ordinal,verification.review_timestamp DESC,
            verification.recorded_at DESC,verification.verification_id)
          FROM jsonb_array_elements_text(p.payload_json->5->2)
            WITH ORDINALITY requested(symbol,ordinal)
          JOIN LATERAL (
            SELECT selected.*
            FROM public.valuation_verifications_v3 selected
            WHERE selected.symbol=requested.symbol
              AND selected.review_timestamp<=r.source_cutoff
              AND selected.recorded_at<=r.source_cutoff
            ORDER BY selected.review_timestamp DESC,
              selected.recorded_at DESC,selected.verification_id
            LIMIT 65
          ) verification ON true
          WHERE requested.ordinal<=5
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(evidence_row
            ORDER BY requested_ordinal,selection_ordinal,claim_ordinal,
              source_ref,evidence_root_id)
          FROM (
            SELECT requested.ordinal AS requested_ordinal,
              selected.selection_ordinal,selected.claim_ordinal,
              selected.source_ref,selected.evidence_root_id,
              jsonb_build_array(
                selected.selection_ordinal,selected.claim_ordinal,
                selected.source_ref,selected.evidence_root_id,
                selected.source_class,selected.source_key,selected.effective_at,
                selected.freshness,selected.verification_tier,
                selected.claim_evidence_stance,selected.run_id,
                selected.revision_id,selected.stock_id,selected.symbol,
                selected.mention_outcome,selected.claim_id,
                selected.evidence_confidence,selected.canonical_claim_id,
                selected.mention_reason
              ) AS evidence_row
            FROM jsonb_array_elements_text(p.payload_json->5->2)
              WITH ORDINALITY requested(symbol,ordinal)
            JOIN public.opportunity_shallow_candidate_results_v3 shallow
              ON shallow.run_id=j.run_id AND shallow.symbol=requested.symbol
              AND shallow.direct_source
              AND shallow.candidate_origin='direct_candidate'
              AND shallow.anchor_claim_id IS NOT NULL
              AND shallow.shallow_status='succeeded'
            JOIN LATERAL (
              SELECT DISTINCT ON (
                claim.revision_id,claim.claim_ordinal,
                mention.stock_id,mention.symbol
              )
                document.selection_ordinal,claim.claim_ordinal,claim.source_ref,
                claim.evidence_root_id,authority_row.payload_json->>3 AS source_class,revision.source_key,
                claim.effective_at,
                CASE
                  WHEN claim.effective_at>=r.source_cutoff-CASE authority_row.payload_json->>3
                    WHEN 'official' THEN interval '35 days'
                    WHEN 'public_research' THEN interval '7 days'
                    WHEN 'curated_thesis' THEN interval '7 days'
                    ELSE interval '3 days' END
                  THEN 'fresh' ELSE 'stale'
                END AS freshness,
                claim.verification_tier,claim.claim_evidence_stance,
                claim.run_id,claim.revision_id,mention.stock_id,
                mention.symbol,mention.outcome AS mention_outcome,
                claim.claim_id,claim.canonical_claim_id,mention.reason AS mention_reason,
                greatest(0,least(1,
                  CASE authority_row.payload_json->>3
                    WHEN 'official' THEN 1.0
                    WHEN 'public_research' THEN 0.8
                    WHEN 'curated_thesis' THEN 0.6
                    ELSE 0.4 END*
                  claim.claim_confidence*mention.confidence*
                  greatest(0,1-extract(epoch FROM (r.source_cutoff-claim.effective_at))/
                    CASE authority_row.payload_json->>3
                      WHEN 'official' THEN 3024000.0
                      WHEN 'public_research' THEN 604800.0
                      WHEN 'curated_thesis' THEN 604800.0
                      ELSE 259200.0 END)
                )) AS evidence_confidence
              FROM public.opportunity_source_claims claim
              JOIN public.opportunity_source_mentions mention
                ON mention.run_id=claim.run_id
                AND mention.revision_id=claim.revision_id
                AND mention.claim_ordinal=claim.claim_ordinal
                AND mention.stock_id=shallow.stock_id
                AND mention.symbol=shallow.symbol
                AND mention.outcome IN (
                  'linked_new','linked_refresh','linked_duplicate_claim'
                )
              JOIN public.opportunity_source_document_outcomes document
                ON document.run_id=claim.run_id
                AND document.revision_id=claim.revision_id
                AND document.outcome IN (
                  'processed_no_claim','processed_with_claims'
                )
              JOIN public.source_document_revisions_v3 revision
                ON revision.revision_id=claim.revision_id
              JOIN public.opportunity_run_manifest_inputs source_identity_binding
                ON source_identity_binding.run_id=j.run_id
                AND source_identity_binding.input_role='source_identity_allowlist'
                AND source_identity_binding.ordinal=0
              JOIN public.opportunity_manifest_rows_v3 authority_row
                ON authority_row.manifest_id=source_identity_binding.manifest_id
                AND authority_row.section_key='rows'
                AND (authority_row.payload_json->>0)::uuid=revision.source_identity_authority_id
                AND (authority_row.payload_json->>1)::uuid=revision.approved_source_identity_id
                AND authority_row.payload_json->>2=revision.source_key::text
                AND authority_row.payload_json->>7='active'
                AND (authority_row.payload_json->>5)::timestamptz<=r.source_cutoff
                AND (
                  authority_row.payload_json->6='null'::jsonb
                  OR r.source_cutoff<(authority_row.payload_json->>6)::timestamptz
                )
              WHERE claim.run_id=r.upstream_run_id
                AND claim.effective_at<=r.source_cutoff
              ORDER BY claim.revision_id,claim.claim_ordinal,
                mention.stock_id,mention.symbol,document.selection_ordinal,
                claim.source_ref,claim.evidence_root_id
              LIMIT 200
            ) selected ON true
            WHERE requested.ordinal<=5
          ) bounded_evidence
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_build_array(manifest.manifest_id,manifest.manifest_hash,coalesce((
            SELECT jsonb_agg(jsonb_build_array(native.section_key,native.payload_json) ORDER BY native.section_key,native.row_ordinal)
            FROM public.opportunity_manifest_rows_v3 native
            WHERE native.manifest_id=manifest.manifest_id AND (
              (native.section_key='current_rows' AND native.payload_json->>1 IN (SELECT value FROM jsonb_array_elements_text(p.payload_json->5->2)))
              OR (native.section_key='sector_rows' AND native.payload_json->>0 IN (
                SELECT shallow.canonical_sector_key::text FROM public.opportunity_shallow_candidate_results_v3 shallow
                WHERE shallow.run_id=j.run_id AND shallow.symbol IN (SELECT value FROM jsonb_array_elements_text(p.payload_json->5->2))))
              OR native.section_key='conservation')
          ),'[]'::jsonb))
          FROM public.opportunity_run_manifest_inputs binding JOIN public.opportunity_manifests_v3 manifest ON manifest.manifest_id=binding.manifest_id AND manifest.status='complete'
          WHERE binding.run_id=j.run_id AND binding.input_role='bias_reference' AND binding.ordinal=0
        ),'null'::jsonb),
        coalesce((
          SELECT jsonb_build_array(manifest.manifest_id,manifest.manifest_hash,coalesce((
            SELECT jsonb_agg(jsonb_build_array(native.section_key,native.payload_json) ORDER BY native.section_key,native.row_ordinal)
            FROM public.opportunity_manifest_rows_v3 native
            WHERE native.manifest_id=manifest.manifest_id AND (
              (native.payload_json->>0 IN (SELECT value FROM jsonb_array_elements_text(p.payload_json->5->2))
                AND native.section_key IN ('raw_adjusted_rows','history_rows','excluded_rows'))
              OR native.section_key='market_benchmark_rows'
            )
          ),'[]'::jsonb))
          FROM public.opportunity_run_manifest_inputs binding JOIN public.opportunity_manifests_v3 manifest ON manifest.manifest_id=binding.manifest_id AND manifest.status='complete'
          WHERE binding.run_id=j.run_id AND binding.input_role='technical_history_reference' AND binding.ordinal=0
        ),'null'::jsonb),
        coalesce((
          SELECT jsonb_build_array(manifest.manifest_id,manifest.manifest_hash,coalesce((
            SELECT jsonb_agg(jsonb_build_array(native.section_key,native.payload_json) ORDER BY native.section_key,native.row_ordinal)
            FROM public.opportunity_manifest_rows_v3 native
            WHERE native.manifest_id=manifest.manifest_id AND (
              (native.section_key IN ('own_history_rows','sector_current_rows') AND native.payload_json->>1 IN (SELECT value FROM jsonb_array_elements_text(p.payload_json->5->2)))
              OR (native.section_key='sector_rows' AND native.payload_json->>0 IN (
                SELECT shallow.canonical_sector_key::text FROM public.opportunity_shallow_candidate_results_v3 shallow
                WHERE shallow.run_id=j.run_id AND shallow.symbol IN (SELECT value FROM jsonb_array_elements_text(p.payload_json->5->2))))
              OR (native.section_key='excluded_rows' AND native.payload_json->>0 IN (SELECT value FROM jsonb_array_elements_text(p.payload_json->5->2)))
              OR native.section_key='conservation')
          ),'[]'::jsonb))
          FROM public.opportunity_run_manifest_inputs binding JOIN public.opportunity_manifests_v3 manifest ON manifest.manifest_id=binding.manifest_id AND manifest.status='complete'
          WHERE binding.run_id=j.run_id AND binding.input_role='reported_pe_reference' AND binding.ordinal=0
        ),'null'::jsonb)
      )
      WHEN 'portfolio_allocation_batch' THEN coalesce((
        SELECT jsonb_agg(jsonb_build_array(
          deep.symbol,
          deep.canonical_sector_key,
          (primary_score.value->>2)::double precision,
          (market.payload_json->>'newPositionBudgetPct')::double precision,
          deep.payload_json->8
        ) ORDER BY requested.ordinal)
        FROM jsonb_array_elements_text(p.payload_json->5->0)
          WITH ORDINALITY requested(symbol,ordinal)
        JOIN public.opportunity_deep_candidate_results_v3 deep
          ON deep.run_id=j.run_id AND deep.symbol=requested.symbol
          AND deep.deep_status='succeeded'
        JOIN public.opportunity_market_context_snapshots market
          ON market.run_id=j.run_id
          AND market.contract_version='market-context-v3.6'
          AND market.payload_json->>'contractVersion'=market.contract_version
          AND (market.payload_json->>'newPositionBudgetPct')::integer IN (0,15,35,60)
          AND market.payload_hash=encode(extensions.digest(market.payload_canonical,'sha256'),'hex')
        JOIN LATERAL (
          SELECT score.value
          FROM jsonb_array_elements(deep.payload_json->11) score(value)
          WHERE score.value->>0=deep.payload_json->8->>'primaryHorizon'
            AND jsonb_typeof(score.value)='array'
            AND jsonb_array_length(score.value)=6
            AND (SELECT count(*) FROM jsonb_array_elements(deep.payload_json->11) exact_score(value)
              WHERE exact_score.value->>0=deep.payload_json->8->>'primaryHorizon'
                AND jsonb_typeof(exact_score.value)='array'
                AND jsonb_array_length(exact_score.value)=6)=1
          LIMIT 1
        ) primary_score ON true
      ),'[]'::jsonb)
      WHEN 'projection_bundle' THEN jsonb_build_array(
        coalesce((
          SELECT jsonb_agg(jsonb_build_array(
            planned.stock_id,planned.symbol,true,'direct_candidate',
            planned.anchor_claim_id,coalesce(shallow.shallow_status::text,'deferred'),
            coalesce(deep.deep_status,'not_reached'::public.opportunity_deep_status_v3),
            CASE
              WHEN shallow.job_id IS NULL THEN jsonb_build_object(
                'state','deferred_before_shallow','reason','connector_cap'
              )
              WHEN shallow.shallow_status='failed' THEN jsonb_build_object(
                'state','shallow_failed','failureCode',shallow.failure_code
              )
              WHEN deep.deep_status='failed' THEN jsonb_build_object(
                'state','deep_failed','failureCode',deep.failure_code
              )
              WHEN deep.deep_status='succeeded' THEN jsonb_build_object(
                'state','deep_succeeded','deepResultJobId',deep.job_id
              )
              ELSE jsonb_build_object(
                'state','enriched_observation','shallowResultJobId',shallow.job_id
              )
            END
          ) ORDER BY requested.ordinal)
          FROM jsonb_array_elements_text(p.payload_json->5->0)
            WITH ORDINALITY requested(symbol,ordinal)
          JOIN public.opportunity_candidate_plan_v3_internal(j.run_id,'active') planned
            ON planned.symbol=requested.symbol
          LEFT JOIN public.opportunity_shallow_candidate_results_v3 shallow
            ON shallow.run_id=j.run_id AND shallow.symbol=planned.symbol
          LEFT JOIN public.opportunity_deep_candidate_results_v3 deep
            ON deep.run_id=j.run_id AND deep.symbol=planned.symbol
        ),'[]'::jsonb),
        coalesce((SELECT result.output_json->5 FROM public.opportunity_job_results_v3 result
          WHERE result.job_id=(p.payload_json->5->>1)::uuid),'{}'::jsonb),
        coalesce((SELECT jsonb_agg(result.output_json->5 ORDER BY result.job_id)
          FROM public.opportunity_job_results_v3 result
          WHERE result.job_id IN (
            SELECT value::text::uuid FROM jsonb_array_elements_text(p.payload_json->5->2)
          )),'[]'::jsonb),
        coalesce((SELECT jsonb_agg(result.output_json->5 ORDER BY result.job_id)
          FROM public.opportunity_job_results_v3 result
          WHERE result.job_id IN (
            SELECT value::text::uuid FROM jsonb_array_elements_text(p.payload_json->5->3)
          )),'[]'::jsonb),
        coalesce((SELECT result.output_json->5 FROM public.opportunity_job_results_v3 result
          WHERE result.job_id=(p.payload_json->5->>4)::uuid),'[]'::jsonb),
        coalesce((SELECT jsonb_build_object(
          'auditedSessionDate',a.session_id,
          'auditedCloseAt',(SELECT s.canonical_cutoff
            FROM public.opportunity_effective_taiwan_sessions_v3 s
            WHERE s.session_id=a.session_id
              AND s.taiwan_session_authority_hash=a.audited_session_authority_hash),
          'auditWindowClosesAt',a.audit_window_closes_at,
          'laterMentionedCount',(SELECT count(*) FROM public.opportunity_mover_audit_symbols_v3 s
            WHERE s.audit_id=a.audit_id AND s.later_mentioned),
          'maturity',a.status,
          'moverCount',a.mover_count,
          'sourceRunId',r.upstream_run_id,
          'sourceCollectionCutoff',a.source_collection_cutoff,
          'sourceRecallPct',a.recall_pct,
          'sourceFunnel',(
            SELECT jsonb_build_object(
              'eligibleDocuments',coalesce(sum(c.eligible_document_count),0),
              'selectedDocuments',coalesce(sum(c.selected_document_count),0),
              'deferredDueScanCap',coalesce(sum(c.deferred_due_scan_cap_count),0),
              'documentOutcomes',jsonb_build_object(
                'duplicate_document',coalesce(sum(c.duplicate_document_count),0),
                'expired_document',coalesce(sum(c.expired_document_count),0),
                'parse_failure',coalesce(sum(c.parse_failure_count),0),
                'processed_no_claim',coalesce(sum(c.processed_no_claim_count),0),
                'processed_with_claims',coalesce(sum(c.processed_with_claims_count),0)
              ),
              'extractedClaims',coalesce(sum(c.unique_claim_count+c.duplicate_claim_count),0),
              'claimOutcomes',jsonb_build_object(
                'unique_claim',coalesce(sum(c.unique_claim_count),0),
                'duplicate_claim',coalesce(sum(c.duplicate_claim_count),0)
              ),
              'rawMentions',coalesce(sum(
                c.linked_new_count+c.linked_refresh_count+c.linked_duplicate_claim_count+
                c.ambiguous_symbol_count+c.rejected_low_confidence_count+
                c.unsupported_instrument_count
              ),0),
              'mentionOutcomes',jsonb_build_object(
                'linked_new',coalesce(sum(c.linked_new_count),0),
                'linked_refresh',coalesce(sum(c.linked_refresh_count),0),
                'linked_duplicate_claim',coalesce(sum(c.linked_duplicate_claim_count),0),
                'ambiguous_symbol',coalesce(sum(c.ambiguous_symbol_count),0),
                'rejected_low_confidence',coalesce(sum(c.rejected_low_confidence_count),0),
                'unsupported_instrument',coalesce(sum(c.unsupported_instrument_count),0)
              ),
              'mentionReasonCounts',jsonb_build_object(
                'explicit_ticker_context',coalesce(sum((c.mention_reason_counts->>'explicit_ticker_context')::integer),0),
                'exact_unique_alias_context',coalesce(sum((c.mention_reason_counts->>'exact_unique_alias_context')::integer),0),
                'ambiguous_number',coalesce(sum((c.mention_reason_counts->>'ambiguous_number')::integer),0),
                'ambiguous_alias',coalesce(sum((c.mention_reason_counts->>'ambiguous_alias')::integer),0),
                'fuzzy_below_auto_threshold',coalesce(sum((c.mention_reason_counts->>'fuzzy_below_auto_threshold')::integer),0),
                'below_min_confidence',coalesce(sum((c.mention_reason_counts->>'below_min_confidence')::integer),0),
                'inactive_or_unknown_symbol',coalesce(sum((c.mention_reason_counts->>'inactive_or_unknown_symbol')::integer),0),
                'missing_stock_context',coalesce(sum((c.mention_reason_counts->>'missing_stock_context')::integer),0),
                'unsupported_market',coalesce(sum((c.mention_reason_counts->>'unsupported_market')::integer),0),
                'non_common_stock',coalesce(sum((c.mention_reason_counts->>'non_common_stock')::integer),0),
                'unsupported_instrument_type',coalesce(sum((c.mention_reason_counts->>'unsupported_instrument_type')::integer),0),
                'duplicate_claim_link',coalesce(sum((c.mention_reason_counts->>'duplicate_claim_link')::integer),0)
              ),
              'activeCandidateCount',(SELECT count(*)
                FROM public.opportunity_candidate_plan_v3_internal(j.run_id,'active')),
              'shallowPlannedCount',(SELECT count(*) FROM public.opportunity_shallow_candidate_results_v3 s
                WHERE s.run_id=j.run_id),
              'shallowSucceededCount',(SELECT count(*) FROM public.opportunity_shallow_candidate_results_v3 s
                WHERE s.run_id=j.run_id AND s.shallow_status='succeeded'),
              'shallowFailedCount',(SELECT count(*) FROM public.opportunity_shallow_candidate_results_v3 s
                WHERE s.run_id=j.run_id AND s.shallow_status='failed'),
              'deferredBeforeShallowCount',greatest(0,(SELECT count(*)
                FROM public.opportunity_candidate_plan_v3_internal(j.run_id,'active'))
                -(SELECT count(*) FROM public.opportunity_shallow_candidate_results_v3 s
                  WHERE s.run_id=j.run_id)),
              'deepPlannedCount',(SELECT count(*) FROM public.opportunity_deep_candidate_results_v3 d
                WHERE d.run_id=j.run_id),
              'deepSucceededCount',(SELECT count(*) FROM public.opportunity_deep_candidate_results_v3 d
                WHERE d.run_id=j.run_id AND d.deep_status='succeeded'),
              'deepFailedCount',(SELECT count(*) FROM public.opportunity_deep_candidate_results_v3 d
                WHERE d.run_id=j.run_id AND d.deep_status='failed'),
              'deferredBeforeDeepCount',greatest(0,(SELECT count(*)
                FROM public.opportunity_shallow_candidate_results_v3 s
                WHERE s.run_id=j.run_id AND s.candidate_origin='direct_candidate'
                  AND s.shallow_status='succeeded')
                -(SELECT count(*) FROM public.opportunity_deep_candidate_results_v3 d
                  WHERE d.run_id=j.run_id)),
              'quotaUnderfillReasons','[]'::jsonb,
              'connectorAccounting',coalesce((
                SELECT jsonb_agg(jsonb_build_object(
                  'sourceKey',accounting.source_key,
                  'eligibleDocuments',accounting.eligible_document_count,
                  'selectedDocuments',accounting.selected_document_count,
                  'deferredDueScanCap',accounting.deferred_due_scan_cap_count,
                  'documentOutcomes',jsonb_build_object(
                    'duplicate_document',accounting.duplicate_document_count,
                    'expired_document',accounting.expired_document_count,
                    'parse_failure',accounting.parse_failure_count,
                    'processed_no_claim',accounting.processed_no_claim_count,
                    'processed_with_claims',accounting.processed_with_claims_count
                  ),
                  'extractedClaims',accounting.unique_claim_count+accounting.duplicate_claim_count,
                  'claimOutcomes',jsonb_build_object(
                    'unique_claim',accounting.unique_claim_count,
                    'duplicate_claim',accounting.duplicate_claim_count
                  ),
                  'rawMentions',accounting.linked_new_count+accounting.linked_refresh_count+
                    accounting.linked_duplicate_claim_count+accounting.ambiguous_symbol_count+
                    accounting.rejected_low_confidence_count+accounting.unsupported_instrument_count,
                  'mentionOutcomes',jsonb_build_object(
                    'linked_new',accounting.linked_new_count,
                    'linked_refresh',accounting.linked_refresh_count,
                    'linked_duplicate_claim',accounting.linked_duplicate_claim_count,
                    'ambiguous_symbol',accounting.ambiguous_symbol_count,
                    'rejected_low_confidence',accounting.rejected_low_confidence_count,
                    'unsupported_instrument',accounting.unsupported_instrument_count
                  ),
                  'mentionReasonCounts',accounting.mention_reason_counts,
                  'linkedCandidateCount',accounting.linked_candidate_count,
                  'status',accounting.status,
                  'failureReason',accounting.failure_reason
                ) ORDER BY accounting.source_key)
                FROM public.opportunity_source_connector_accounting accounting
                WHERE accounting.run_id=r.upstream_run_id
              ),'[]'::jsonb)
            )
            FROM public.opportunity_source_connector_accounting c
            WHERE c.run_id=r.upstream_run_id
          ),
          'symbols',coalesce((SELECT jsonb_agg(s.symbol ORDER BY s.rank)
            FROM public.opportunity_mover_audit_symbols_v3 s WHERE s.audit_id=a.audit_id),'[]'::jsonb)
        ) FROM public.opportunity_mover_audits_v3 a
          WHERE a.audit_id=r.selected_mover_audit_id),'{}'::jsonb),
        coalesce((
          SELECT jsonb_agg(jsonb_build_array(
            j.run_id,
            deep.symbol,
            '/opportunity-v3/'||j.run_id::text||'/'||deep.symbol,
            anchor_evidence.value->>4,
            anchor_evidence.value->>6,
            r.source_cutoff,
            deep.payload_json->12,
            coalesce(change_items.items,'[]'::jsonb),
            deep.payload_json->>6,
            allocation.payload_json->>'primaryHorizon',
            CASE WHEN prior.payload_json IS NULL THEN NULL ELSE
              round(((current_score.value->>2)::numeric-
                (prior_score.value->>'score')::numeric),2)
            END,
            allocation.payload_json->>'newPositionAction',
            deep.payload_json->7->>'status',
            coalesce(deep.payload_json->7->'evidenceRefs','[]'::jsonb),
            CASE WHEN prior.payload_json IS NULL THEN NULL ELSE jsonb_build_array(
              prior_run.source_cutoff,
              prior.payload_json#>>'{card,sourceSummary,anchorEffectiveAt}',
              prior.payload_json#>>'{card,formalResearchStatus}',
              (prior.payload_json#>>'{card,sourceSummary,independentRootCount}')::integer,
              prior.payload_json#>>'{card,valuation,status}'
            ) END
          ) ORDER BY deep.symbol)
          FROM public.opportunity_deep_candidate_results_v3 deep
          JOIN public.opportunity_portfolio_allocations_v3 allocation
            ON allocation.run_id=deep.run_id AND allocation.symbol=deep.symbol
          JOIN LATERAL (
            SELECT score.value
            FROM jsonb_array_elements(deep.payload_json->11) score(value)
            WHERE score.value->>0=allocation.payload_json->>'primaryHorizon'
              AND jsonb_typeof(score.value)='array'
              AND jsonb_array_length(score.value)=6
              AND (SELECT count(*) FROM jsonb_array_elements(deep.payload_json->11) exact_score(value)
                WHERE exact_score.value->>0=allocation.payload_json->>'primaryHorizon'
                  AND jsonb_typeof(exact_score.value)='array'
                  AND jsonb_array_length(exact_score.value)=6)=1
            LIMIT 1
          ) current_score ON true
          JOIN LATERAL (
            SELECT evidence.value
            FROM jsonb_array_elements(deep.payload_json->12) evidence(value)
            WHERE evidence.value->>15=deep.payload_json->>4
              AND evidence.value->>7='fresh'
              AND evidence.value->>9='supports'
            ORDER BY (evidence.value->>0)::integer,(evidence.value->>1)::integer
            LIMIT 1
          ) anchor_evidence ON true
          LEFT JOIN LATERAL (
            SELECT prior_candidate.*
            FROM (
              SELECT candidate.run_id
              FROM public.opportunity_runs candidate
              WHERE candidate.mode='enrich_rank'
                AND candidate.status='success'
                AND candidate.comparison_contract_key=r.comparison_contract_key
                AND candidate.source_cutoff<r.source_cutoff
              ORDER BY candidate.source_cutoff DESC,candidate.terminal_at DESC,candidate.run_id
              LIMIT 1
            ) prior_owner
            LEFT JOIN public.opportunity_detail_projections_v3 prior_candidate
              ON prior_candidate.run_id=prior_owner.run_id
              AND prior_candidate.symbol=deep.symbol
          ) prior ON true
          LEFT JOIN public.opportunity_runs prior_run ON prior_run.run_id=prior.run_id
          LEFT JOIN LATERAL (
            SELECT detail.value
            FROM jsonb_array_elements(prior.payload_json->'horizonDetails') detail(value)
            WHERE detail.value->>'horizon'=allocation.payload_json->>'primaryHorizon'
            LIMIT 1
          ) prior_score ON prior.payload_json IS NOT NULL
          LEFT JOIN LATERAL (
            SELECT jsonb_agg(ordered.item ORDER BY ordered.priority,ordered.delta_abs DESC,ordered.factor_order) AS items
            FROM (
              SELECT candidate.item,candidate.priority,candidate.delta_abs,candidate.factor_order
              FROM (
                SELECT jsonb_build_object('code','candidate_state_changed',
                    'from',prior.payload_json#>>'{card,candidateState}',
                    'to',CASE allocation.payload_json->>'newPositionAction'
                      WHEN 'starter_now' THEN 'actionable_now' WHEN 'event_starter' THEN 'actionable_now'
                      WHEN 'wait_trigger' THEN 'waiting_trigger' WHEN 'valuation_review' THEN 'valuation_review'
                      ELSE 'avoid' END) AS item,1 AS priority,0::numeric AS delta_abs,0 AS factor_order
                WHERE prior.payload_json IS NOT NULL AND prior.payload_json#>>'{card,candidateState}' IS DISTINCT FROM
                  CASE allocation.payload_json->>'newPositionAction'
                    WHEN 'starter_now' THEN 'actionable_now' WHEN 'event_starter' THEN 'actionable_now'
                    WHEN 'wait_trigger' THEN 'waiting_trigger' WHEN 'valuation_review' THEN 'valuation_review'
                    ELSE 'avoid' END
                UNION ALL
                SELECT jsonb_build_object('code','new_position_action_changed',
                    'from',prior.payload_json#>>'{card,actionDecision,newPositionAction}',
                    'to',allocation.payload_json->>'newPositionAction'),2,0,0
                WHERE prior.payload_json IS NOT NULL AND prior.payload_json#>>'{card,actionDecision,newPositionAction}'
                  IS DISTINCT FROM allocation.payload_json->>'newPositionAction'
                UNION ALL
                SELECT jsonb_build_object('code','formal_status_changed',
                    'from',prior.payload_json#>>'{card,formalResearchStatus}',
                    'to',deep.payload_json->>6),3,0,0
                WHERE prior.payload_json IS NOT NULL AND prior.payload_json#>>'{card,formalResearchStatus}'
                  IS DISTINCT FROM deep.payload_json->>6
                UNION ALL
                SELECT jsonb_build_object('code','factor_contribution_changed','factor',factor_key,
                    'delta',round(((current_score.value->5->factor_key->>'contribution')::numeric-
                      (prior_factor.value->>'contribution')::numeric),2)),4,
                    abs(round(((current_score.value->5->factor_key->>'contribution')::numeric-
                      (prior_factor.value->>'contribution')::numeric),2)),factor_ordinal
                FROM unnest(ARRAY['priceVolume','chip','catalyst','marketSector','fundamental','valuation'])
                  WITH ORDINALITY factor(factor_key,factor_ordinal)
                JOIN LATERAL (
                  SELECT prior_factor_row.value
                  FROM jsonb_array_elements(prior_score.value->'factors') prior_factor_row(value)
                  WHERE prior_factor_row.value->>'key'=factor.factor_key
                  LIMIT 1
                ) prior_factor ON true
                WHERE prior.payload_json IS NOT NULL AND round(
                  (current_score.value->5->factor_key->>'contribution')::numeric-
                  (prior_factor.value->>'contribution')::numeric,2)<>0
              ) candidate
              ORDER BY candidate.priority,candidate.delta_abs DESC,candidate.factor_order
              LIMIT 3
            ) ordered
          ) change_items ON true
          WHERE deep.run_id=j.run_id
            AND deep.deep_status='succeeded'
            AND jsonb_array_length(deep.payload_json->12)>0
        ),'[]'::jsonb),
        coalesce((
          WITH prior_owner AS MATERIALIZED (
            SELECT prior_run.run_id
            FROM public.opportunity_runs prior_run
            WHERE prior_run.mode='enrich_rank' AND prior_run.status='success'
              AND prior_run.comparison_contract_key=r.comparison_contract_key
              AND prior_run.source_cutoff<r.source_cutoff
            ORDER BY prior_run.source_cutoff DESC,prior_run.terminal_at DESC,prior_run.run_id
            LIMIT 1
          ), current_rows AS (
            SELECT jsonb_build_array(
              'current',current_plan.symbol,
              CASE WHEN prior_plan.symbol IS NULL THEN 'new_source_evidence'
                WHEN prior_plan.anchor_claim_id IS DISTINCT FROM current_plan.anchor_claim_id THEN 'material_source_change'
                WHEN deep.payload_json->13->>'noChangeMessage' IS NOT NULL THEN 'unchanged'
                ELSE 'refreshed' END,
              NULL,anchor.effective_at,authority.payload_json->>3,
              current_plan.symbol||' 新來源證據已納入不可變研究漏斗，等待基本面、估值與技術面覆核。',
              jsonb_build_array(anchor.source_ref),
              CASE WHEN deep.payload_json->7->>'status'='normal' THEN 'review_required' ELSE 'pending' END,
              coalesce(deep.payload_json->13->'technicalDecision'->>'state','unavailable'),
              coalesce(deep.payload_json->13->>'researchMaturity','source_signal')
            ) AS value,0 AS kind_order,current_plan.symbol
            FROM public.opportunity_candidate_plan_v3_internal(j.run_id,'active') current_plan
            JOIN public.opportunity_source_claims anchor ON anchor.claim_id=current_plan.anchor_claim_id
            JOIN public.source_document_revisions_v3 revision ON revision.revision_id=anchor.revision_id
            JOIN public.opportunity_run_manifest_inputs authority_binding
              ON authority_binding.run_id=j.run_id AND authority_binding.input_role='source_identity_allowlist'
              AND authority_binding.ordinal=0
            JOIN public.opportunity_manifest_rows_v3 authority
              ON authority.manifest_id=authority_binding.manifest_id AND authority.section_key='rows'
              AND (authority.payload_json->>0)::uuid=revision.source_identity_authority_id
              AND (authority.payload_json->>1)::uuid=revision.approved_source_identity_id
              AND authority.payload_json->>2=revision.source_key::text AND authority.payload_json->>7='active'
            LEFT JOIN public.opportunity_deep_candidate_results_v3 deep
              ON deep.run_id=j.run_id AND deep.symbol=current_plan.symbol AND deep.deep_status='succeeded'
            LEFT JOIN LATERAL (
              SELECT prior.* FROM prior_owner owner
              JOIN public.opportunity_candidate_plan_v3_internal(owner.run_id,'active') prior
                ON prior.symbol=current_plan.symbol LIMIT 1
            ) prior_plan ON true
          ), exit_rows AS (
            SELECT jsonb_build_array('exit',prior_plan.symbol,'ranking_cap',NULL,NULL,NULL,NULL,
              '[]'::jsonb,NULL,NULL,NULL) AS value,1 AS kind_order,prior_plan.symbol
            FROM prior_owner owner
            CROSS JOIN LATERAL public.opportunity_candidate_plan_v3_internal(owner.run_id,'active') prior_plan
            WHERE NOT EXISTS (SELECT 1
              FROM public.opportunity_candidate_plan_v3_internal(j.run_id,'active') current_plan
              WHERE current_plan.symbol=prior_plan.symbol)
          )
          SELECT jsonb_agg(discovery.value ORDER BY discovery.kind_order,discovery.symbol)
          FROM (SELECT * FROM current_rows UNION ALL SELECT * FROM exit_rows) discovery
        ),'[]'::jsonb)
      )
      WHEN 'outcome_batch' THEN coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'scoreSnapshotId',score.score_snapshot_id,
          'maturityHorizon',mr.payload_json->>6,
          'entrySession',mr.payload_json->>7,
          'entrySessionAuthorityHash',mr.payload_json->>8,
          'maturitySession',mr.payload_json->>9,
          'maturitySessionAuthorityHash',mr.payload_json->>10,
          'entryPriceRef',mr.payload_json->>11,
          'outcomePriceRef',mr.payload_json->>12,
          'sectorBenchmarkManifestId',benchmark.manifest_id,
          'returnPct',100.0*(maturity_price.adjusted_close/entry_price.adjusted_close-1.0),
          'sectorRelativeReturnPct',
            100.0*(maturity_price.adjusted_close/entry_price.adjusted_close-1.0)
              -benchmark_maturity.return_pct,
          'mfePct',100.0*(path_price.maximum_high/entry_price.adjusted_close-1.0),
          'maePct',100.0*(path_price.minimum_low/entry_price.adjusted_close-1.0),
          'sectorRelativeMfePct',path_sector.maximum_relative_mfe_pct
        ) ORDER BY mr.row_ordinal)
        FROM public.opportunity_manifest_rows_v3 mr
        JOIN public.opportunity_score_snapshots score
          ON score.score_snapshot_id=(mr.payload_json->>1)::uuid
          AND score.run_id=(mr.payload_json->>0)::uuid
          AND score.payload_hash=mr.payload_json->>2
          AND score.symbol=mr.payload_json->>3
          AND score.horizon::text=mr.payload_json->>4
          AND score.rank=(mr.payload_json->>5)::integer
        JOIN public.opportunity_manifests_v3 benchmark
          ON benchmark.manifest_kind='sector_benchmark'
          AND benchmark.status='complete'
          AND benchmark.manifest_hash=mr.payload_json->>13
        JOIN LATERAL (
          SELECT (adjusted.payload#>>'{evidence,14}')::double precision AS adjusted_close
          FROM public.opportunity_price_observations_v3 observation
          JOIN public.tw_trading_sessions_v3 authority
            ON authority.session_authority_id=observation.session_authority_id
          CROSS JOIN LATERAL (
            SELECT public.opportunity_adjusted_price_evidence_v3_internal(
              observation.observation_id,(mr.payload_json->>9)::date,r.source_cutoff
            ) AS payload
          ) adjusted
          WHERE observation.stock_id=score.stock_id
            AND observation.session_id=(mr.payload_json->>7)::date
            AND adjusted.payload->>'ref'=mr.payload_json->>11
            AND observation.source_timestamp<=r.source_cutoff
            AND observation.collected_at<=r.source_cutoff
            AND observation.recorded_at<=r.source_cutoff
            AND authority.recorded_at<=r.source_cutoff
          ORDER BY observation.recorded_at DESC,observation.observation_id
          LIMIT 1
        ) entry_price ON true
        JOIN LATERAL (
          SELECT (adjusted.payload#>>'{evidence,14}')::double precision AS adjusted_close
          FROM public.opportunity_price_observations_v3 observation
          JOIN public.tw_trading_sessions_v3 authority
            ON authority.session_authority_id=observation.session_authority_id
          CROSS JOIN LATERAL (
            SELECT public.opportunity_adjusted_price_evidence_v3_internal(
              observation.observation_id,(mr.payload_json->>9)::date,r.source_cutoff
            ) AS payload
          ) adjusted
          WHERE observation.stock_id=score.stock_id
            AND observation.session_id=(mr.payload_json->>9)::date
            AND adjusted.payload->>'ref'=mr.payload_json->>12
            AND observation.source_timestamp<=r.source_cutoff
            AND observation.collected_at<=r.source_cutoff
            AND observation.recorded_at<=r.source_cutoff
            AND authority.recorded_at<=r.source_cutoff
          ORDER BY observation.recorded_at DESC,observation.observation_id
          LIMIT 1
        ) maturity_price ON true
        JOIN LATERAL (
          SELECT max((adjusted.payload#>>'{evidence,12}')::double precision)
              AS maximum_high,
            min((adjusted.payload#>>'{evidence,13}')::double precision)
              AS minimum_low
          FROM public.opportunity_price_observations_v3 observation
          CROSS JOIN LATERAL (
            SELECT public.opportunity_adjusted_price_evidence_v3_internal(
              observation.observation_id,(mr.payload_json->>9)::date,r.source_cutoff
            ) AS payload
          ) adjusted
          WHERE observation.stock_id=score.stock_id
            AND observation.session_id BETWEEN (mr.payload_json->>7)::date AND (mr.payload_json->>9)::date
            AND observation.source_timestamp<=r.source_cutoff
            AND observation.collected_at<=r.source_cutoff
            AND observation.recorded_at<=r.source_cutoff
        ) path_price ON path_price.maximum_high IS NOT NULL AND path_price.minimum_low IS NOT NULL
        JOIN LATERAL (
          SELECT 100.0*avg(
            (evaluation.payload_json->>4)::double precision/
            (entry.payload_json->>2)::double precision-1.0
          ) AS return_pct
          FROM public.opportunity_manifest_rows_v3 evaluation
          JOIN public.opportunity_manifest_rows_v3 entry
            ON entry.manifest_id=evaluation.manifest_id
            AND entry.section_key='entry_rows'
            AND entry.payload_json->>0=evaluation.payload_json->>3
          WHERE evaluation.manifest_id=benchmark.manifest_id
            AND evaluation.section_key='evaluation_rows'
            AND evaluation.payload_json->>0=mr.payload_json->>9
        ) benchmark_maturity ON benchmark_maturity.return_pct IS NOT NULL
        JOIN LATERAL (
          SELECT max(
            100.0*((adjusted.payload#>>'{evidence,12}')::double precision
              /entry_price.adjusted_close-1.0)-sector.return_pct
          ) AS maximum_relative_mfe_pct
          FROM public.opportunity_price_observations_v3 candidate
          CROSS JOIN LATERAL (
            SELECT public.opportunity_adjusted_price_evidence_v3_internal(
              candidate.observation_id,(mr.payload_json->>9)::date,r.source_cutoff
            ) AS payload
          ) adjusted
          JOIN LATERAL (
            SELECT 100.0*avg(
              (evaluation.payload_json->>4)::double precision/
              (entry.payload_json->>2)::double precision-1.0
            ) AS return_pct
            FROM public.opportunity_manifest_rows_v3 evaluation
            JOIN public.opportunity_manifest_rows_v3 entry
              ON entry.manifest_id=evaluation.manifest_id
              AND entry.section_key='entry_rows'
              AND entry.payload_json->>0=evaluation.payload_json->>3
            WHERE evaluation.manifest_id=benchmark.manifest_id
              AND evaluation.section_key='evaluation_rows'
              AND evaluation.payload_json->>0=candidate.session_id::text
          ) sector ON sector.return_pct IS NOT NULL
          WHERE candidate.stock_id=score.stock_id
            AND candidate.session_id BETWEEN (mr.payload_json->>7)::date AND (mr.payload_json->>9)::date
            AND candidate.source_timestamp<=r.source_cutoff
            AND candidate.collected_at<=r.source_cutoff
            AND candidate.recorded_at<=r.source_cutoff
        ) path_sector ON true
        WHERE mr.manifest_id=(p.payload_json->5->>0)::uuid
          AND mr.section_key='input_rows'
          AND mr.row_ordinal>=(p.payload_json->5->>1)::integer
          AND mr.row_ordinal<(p.payload_json->5->>2)::integer
      ),'[]'::jsonb)
      WHEN 'evaluation_bundle' THEN (
        SELECT jsonb_build_array(
          evaluation_manifest_hash,
          sample_manifest_hash,
          resolution_manifest_hash,
          ordered_inputs,
          backtest_count,
          live_count,
          CASE WHEN backtest_count=120 THEN v3_metrics ELSE NULL END,
          CASE WHEN backtest_count=120 THEN legacy_metrics ELSE NULL END,
          link_precision,
          link_recall,
          jsonb_build_array(
            population_count,
            encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
              'strategy-population-v3.0',population_identities
            )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'),
            greatest(0,population_count-400),
            least(population_count,400)
          ),
          (
            SELECT jsonb_agg(jsonb_build_object(
              'strategy',strategy.strategy,
              'selectedCandidateIds',stats.selected_ids,
              'excludedCandidateIdsAndReasons',stats.excluded_ids,
              'selectedCount',stats.selected_count,
              'verifiedChangePrecisionNumerator',stats.precision_numerator,
              'verifiedChangePrecisionDenominator',stats.selected_count,
              'verifiedChangePrecision',stats.precision_numerator::double precision
                /nullif(stats.selected_count,0),
              'contradictionCaptureNumerator',stats.contradiction_numerator,
              'contradictionCaptureDenominator',global_stats.contradiction_denominator,
              'contradictionCaptureRate',stats.contradiction_numerator::double precision
                /nullif(global_stats.contradiction_denominator,0),
              'timeToFirstVerifiedChangeMinutes',stats.median_minutes,
              'reviewerResolutionNumerator',reviewer_resolved_count,
              'reviewerResolutionDenominator',reviewer_total_count,
              'reviewerResolutionRate',reviewer_resolved_count::double precision
                /nullif(reviewer_total_count,0),
              'facts',CASE
                WHEN stats.selected_count=0
                  OR global_stats.contradiction_denominator=0
                  OR reviewer_total_count=0
                THEN jsonb_build_array('insufficient_product_value_evidence')
                ELSE '[]'::jsonb
              END,
              'preCapCandidateCount',population_count,
              'preCapOrderedIdentityHash',encode(extensions.digest(convert_to(
                regexp_replace(jsonb_build_array(
                  'strategy-population-v3.0',population_identities
                )::text, ', ', ',', 'g'),'utf8'
              ),'sha256'),'hex'),
              'deferredDueStrategyEvidenceCap',greatest(0,population_count-400),
              'retainedCandidateCount',least(population_count,400)
            ) ORDER BY strategy.ordinal)
            FROM (VALUES
              ('official_only',1),('source_led',2),('hybrid',3)
            ) strategy(strategy,ordinal)
            CROSS JOIN LATERAL (
              WITH classified AS MATERIALIZED (
                SELECT candidate.ordinal,candidate.value,
                  CASE
                    WHEN NOT (candidate.value->>5)::boolean
                      OR candidate.value->>8 IS NULL
                      OR candidate.value->>9 IS NULL
                      OR (candidate.value->>8)::timestamptz
                        <(candidate.value->>9)::timestamptz
                    THEN 'invalid_verified_change_input'
                    WHEN NOT (candidate.value->>2)::boolean
                    THEN 'missing_verified_evidence'
                    WHEN strategy.strategy='official_only'
                      AND NOT (candidate.value->>3)::boolean
                    THEN 'missing_official_or_research_evidence'
                    WHEN strategy.strategy='hybrid'
                      AND NOT (candidate.value->>3)::boolean
                      AND (candidate.value->>4)::integer<2
                    THEN 'insufficient_independent_source_classes'
                    ELSE NULL
                  END AS exclusion_reason
                FROM jsonb_array_elements(population_rows)
                  WITH ORDINALITY candidate(value,ordinal)
              )
              SELECT
                coalesce(jsonb_agg(jsonb_build_array(
                  value->>0,value->>1
                ) ORDER BY ordinal) FILTER (
                  WHERE exclusion_reason IS NULL
                ),'[]'::jsonb) AS selected_ids,
                coalesce(jsonb_agg(jsonb_build_array(
                  jsonb_build_array(value->>0,value->>1),exclusion_reason
                ) ORDER BY ordinal) FILTER (
                  WHERE exclusion_reason IS NOT NULL
                ),'[]'::jsonb) AS excluded_ids,
                count(*) FILTER (
                  WHERE exclusion_reason IS NULL
                )::integer AS selected_count,
                count(*) FILTER (
                  WHERE exclusion_reason IS NULL
                    AND (value->>6)::integer=0
                    AND value->>7 IN ('formal_watch','formal_candidate')
                )::integer AS precision_numerator,
                count(*) FILTER (
                  WHERE exclusion_reason IS NULL
                    AND (value->>6)::integer>0
                )::integer AS contradiction_numerator,
                round((
                  percentile_cont(0.5) WITHIN GROUP (
                    ORDER BY floor(extract(epoch FROM (
                      (value->>8)::timestamptz-(value->>9)::timestamptz
                    ))/60.0)
                  ) FILTER (WHERE exclusion_reason IS NULL)
                )::numeric,2)::double precision AS median_minutes
              FROM classified
            ) stats
            CROSS JOIN LATERAL (
              SELECT count(*) FILTER (
                WHERE (candidate->>5)::boolean
                  AND (candidate->>6)::integer>0
              )::integer AS contradiction_denominator
              FROM jsonb_array_elements(population_rows) candidate
            ) global_stats
          ),
          jsonb_build_object(
            'backtestDatesReady',backtest_count>=120,
            'liveDatesReady',live_count>=20,
            'v3MetricsReady',v3_metrics IS NOT NULL,
            'legacyMetricsReady',legacy_metrics IS NOT NULL,
            'precisionImprovementPassed',coalesce(
              ((v3_metrics->>'precisionAt20')::double precision
                -(legacy_metrics->>'precisionAt20')::double precision)
              /greatest(abs((legacy_metrics->>'precisionAt20')::double precision),0.01)
                >=0.10,false
            ),
            'ndcgImprovementPassed',coalesce(
              ((v3_metrics->>'ndcgAt20')::double precision
                -(legacy_metrics->>'ndcgAt20')::double precision)
              /greatest(abs((legacy_metrics->>'ndcgAt20')::double precision),0.01)
                >=0.10,false
            ),
            'maeGuardrailPassed',coalesce(
              (v3_metrics->>'worstDecileMae20Pct')::double precision
                >=(legacy_metrics->>'worstDecileMae20Pct')::double precision-2.0,
              false
            ),
            'linkPrecisionPassed',coalesce(link_precision>=0.95,false),
            'linkRecallPassed',coalesce(link_recall>=0.9,false),
            'acceptancePassed',backtest_count=120
              AND v3_metrics IS NOT NULL AND legacy_metrics IS NOT NULL,
            'securityPassed',reviewer_total_count>0
              AND reviewer_resolved_count=reviewer_total_count
              AND coalesce(link_precision>=0.95,false)
              AND coalesce(link_recall>=0.9,false),
            'operationsPassed',live_count=20,
            'promotionReady',
              backtest_count=120 AND live_count=20
              AND v3_metrics IS NOT NULL AND legacy_metrics IS NOT NULL
              AND coalesce(
                ((v3_metrics->>'precisionAt20')::double precision
                  -(legacy_metrics->>'precisionAt20')::double precision)
                /greatest(abs(
                  (legacy_metrics->>'precisionAt20')::double precision
                ),0.01)>=0.10,false
              )
              AND coalesce(
                ((v3_metrics->>'ndcgAt20')::double precision
                  -(legacy_metrics->>'ndcgAt20')::double precision)
                /greatest(abs(
                  (legacy_metrics->>'ndcgAt20')::double precision
                ),0.01)>=0.10,false
              )
              AND coalesce(
                (v3_metrics->>'worstDecileMae20Pct')::double precision
                  >=(legacy_metrics->>'worstDecileMae20Pct')::double precision-2.0,
                false
              )
              AND reviewer_total_count>0
              AND reviewer_resolved_count=reviewer_total_count
              AND coalesce(link_precision>=0.95,false)
              AND coalesce(link_recall>=0.9,false)
          ),
          to_jsonb(array_remove(ARRAY[
            CASE WHEN backtest_count<120 THEN 'insufficient_backtest_dates' END,
            CASE WHEN live_count<20 THEN 'insufficient_live_dates' END,
            CASE WHEN legacy_metrics IS NULL THEN 'legacy_baseline_unavailable' END,
            CASE WHEN v3_metrics IS NOT NULL AND legacy_metrics IS NOT NULL
              AND NOT coalesce(
                ((v3_metrics->>'precisionAt20')::double precision
                  -(legacy_metrics->>'precisionAt20')::double precision)
                /greatest(abs(
                  (legacy_metrics->>'precisionAt20')::double precision
                ),0.01)>=0.10,false
              )
              THEN 'precision_improvement_not_met' END,
            CASE WHEN v3_metrics IS NOT NULL AND legacy_metrics IS NOT NULL
              AND NOT coalesce(
                ((v3_metrics->>'ndcgAt20')::double precision
                  -(legacy_metrics->>'ndcgAt20')::double precision)
                /greatest(abs(
                  (legacy_metrics->>'ndcgAt20')::double precision
                ),0.01)>=0.10,false
              )
              THEN 'ndcg_improvement_not_met' END,
            CASE WHEN v3_metrics IS NOT NULL AND legacy_metrics IS NOT NULL
              AND NOT coalesce(
                (v3_metrics->>'worstDecileMae20Pct')::double precision
                  >=(legacy_metrics->>'worstDecileMae20Pct')::double precision-2.0,
                false
              )
              THEN 'mae_guardrail_not_met' END,
            CASE WHEN link_precision IS NULL THEN 'insufficient_link_precision_evidence' END,
            CASE WHEN link_recall IS NULL THEN 'insufficient_link_recall_evidence' END,
            CASE WHEN reviewer_total_count=0
              OR reviewer_resolved_count<>reviewer_total_count
              THEN 'security_evidence_unavailable' END,
            CASE WHEN live_count<20 THEN 'operations_evidence_unavailable' END
          ]::text[],NULL)),
          CASE WHEN
            backtest_count=120 AND live_count=20
            AND v3_metrics IS NOT NULL AND legacy_metrics IS NOT NULL
            AND coalesce(
              ((v3_metrics->>'precisionAt20')::double precision
                -(legacy_metrics->>'precisionAt20')::double precision)
              /greatest(abs(
                (legacy_metrics->>'precisionAt20')::double precision
              ),0.01)>=0.10,false
            )
            AND coalesce(
              ((v3_metrics->>'ndcgAt20')::double precision
                -(legacy_metrics->>'ndcgAt20')::double precision)
              /greatest(abs(
                (legacy_metrics->>'ndcgAt20')::double precision
              ),0.01)>=0.10,false
            )
            AND coalesce(
              (v3_metrics->>'worstDecileMae20Pct')::double precision
                >=(legacy_metrics->>'worstDecileMae20Pct')::double precision-2.0,
              false
            )
            AND reviewer_total_count>0
            AND reviewer_resolved_count=reviewer_total_count
            AND coalesce(link_precision>=0.95,false)
            AND coalesce(link_recall>=0.9,false)
          THEN 'pass' ELSE 'fail' END
        )
        FROM (
          SELECT
            evaluation.manifest_hash AS evaluation_manifest_hash,
            sample.manifest_hash AS sample_manifest_hash,
            resolution.manifest_hash AS resolution_manifest_hash,
            coalesce((
              SELECT jsonb_agg(jsonb_build_array(ri.input_run_id,im.manifest_id,m.manifest_hash)
                ORDER BY ri.input_role,ri.input_run_id,im.input_role,im.ordinal)
              FROM public.opportunity_run_inputs ri
              LEFT JOIN public.opportunity_run_manifest_inputs im ON im.run_id=ri.run_id
              LEFT JOIN public.opportunity_manifests_v3 m ON m.manifest_id=im.manifest_id
              WHERE ri.run_id=j.run_id
            ),'[]'::jsonb) AS ordered_inputs,
            (SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
              WHERE row.manifest_id=evaluation.manifest_id
                AND row.section_key='backtest_rows')::integer AS backtest_count,
            (SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
              WHERE row.manifest_id=evaluation.manifest_id
                AND row.section_key='live_rows')::integer AS live_count,
            (SELECT count(*) FROM public.opportunity_candidate_snapshots candidate
              JOIN (
                SELECT DISTINCT (selected.payload_json->>2)::uuid AS run_id
                FROM public.opportunity_manifest_rows_v3 selected
                WHERE selected.manifest_id=evaluation.manifest_id
                  AND selected.section_key IN ('backtest_rows','live_rows')
              ) supplying ON supplying.run_id=candidate.run_id
              WHERE candidate.direct_source
                AND candidate.candidate_origin='direct_candidate'
                AND candidate.anchor_claim_id IS NOT NULL
                AND candidate.deep_status='succeeded')::integer AS population_count,
            coalesce((
              SELECT jsonb_agg(
                jsonb_build_array(population.run_id,population.symbol)
                ORDER BY population.source_cutoff DESC,population.run_id,population.symbol
              )
              FROM (
                SELECT candidate.run_id,candidate.symbol,input.source_cutoff
                FROM public.opportunity_candidate_snapshots candidate
                JOIN (
                  SELECT DISTINCT (selected.payload_json->>2)::uuid AS run_id
                  FROM public.opportunity_manifest_rows_v3 selected
                  WHERE selected.manifest_id=evaluation.manifest_id
                    AND selected.section_key IN ('backtest_rows','live_rows')
                ) supplying ON supplying.run_id=candidate.run_id
                JOIN public.opportunity_runs input
                  ON input.run_id=candidate.run_id
                WHERE candidate.direct_source
                  AND candidate.candidate_origin='direct_candidate'
                  AND candidate.anchor_claim_id IS NOT NULL
                  AND candidate.deep_status='succeeded'
              ) population
            ),'[]'::jsonb) AS population_identities,
            coalesce((
              SELECT jsonb_agg(
                jsonb_build_array(
                  retained.run_id,retained.symbol,retained.has_verified_evidence,
                  retained.has_official_or_research_evidence,
                  retained.independent_source_class_count,retained.has_brief,
                  retained.contradiction_count,retained.formal_research_status,
                  retained.verified_at,retained.earliest_effective_at
                )
                ORDER BY retained.source_cutoff DESC,retained.run_id,retained.symbol
              )
              FROM (
                SELECT
                  candidate.run_id,
                  candidate.symbol,
                  input.source_cutoff,
                  evidence.has_verified_evidence,
                  evidence.has_official_or_research_evidence,
                  evidence.independent_source_class_count,
                  detail.payload_json->'verifiedChangeBrief'<>'null'::jsonb
                    AS has_brief,
                  CASE
                    WHEN detail.payload_json->'verifiedChangeBrief'='null'::jsonb
                    THEN 0
                    ELSE jsonb_array_length(
                      detail.payload_json->'verifiedChangeBrief'->'contradictions'
                    )
                  END AS contradiction_count,
                  detail.payload_json->'verifiedChangeBrief'
                    ->>'formalResearchStatus' AS formal_research_status,
                  detail.payload_json->'verifiedChangeBrief'
                    ->>'verifiedAt' AS verified_at,
                  evidence.earliest_effective_at
                FROM public.opportunity_candidate_snapshots candidate
                JOIN (
                  SELECT DISTINCT (selected.payload_json->>2)::uuid AS run_id
                  FROM public.opportunity_manifest_rows_v3 selected
                  WHERE selected.manifest_id=evaluation.manifest_id
                    AND selected.section_key IN ('backtest_rows','live_rows')
                ) supplying ON supplying.run_id=candidate.run_id
                JOIN public.opportunity_runs input
                  ON input.run_id=candidate.run_id
                JOIN public.opportunity_detail_projections_v3 detail
                  ON detail.run_id=candidate.run_id
                  AND detail.symbol=candidate.symbol
                JOIN LATERAL (
                  SELECT
                    count(*)>0 AS has_verified_evidence,
                    coalesce(bool_or(
                      row->>'sourceClass' IN ('official','public_research')
                      AND row->>'verificationTier'='publisher_verified'
                    ),false) AS has_official_or_research_evidence,
                    count(DISTINCT row->>'sourceClass')::integer
                      AS independent_source_class_count,
                    min((row->>'effectiveAt')::timestamptz)
                      AS earliest_effective_at
                  FROM jsonb_array_elements(
                    detail.payload_json->'sourceEvidence'
                  ) row
                ) evidence ON true
                WHERE candidate.direct_source
                  AND candidate.candidate_origin='direct_candidate'
                  AND candidate.anchor_claim_id IS NOT NULL
                  AND candidate.deep_status='succeeded'
                ORDER BY input.source_cutoff DESC,candidate.run_id,candidate.symbol
                LIMIT 400
              ) retained
            ),'[]'::jsonb) AS population_rows,
            (
              SELECT count(*)::integer
              FROM public.opportunity_manifest_rows_v3 row
              WHERE row.manifest_id=resolution.manifest_id
                AND row.section_key='resolved_rows'
            ) AS reviewer_resolved_count,
            (
              SELECT count(*)::integer
              FROM public.opportunity_manifest_rows_v3 row
              WHERE row.manifest_id=resolution.manifest_id
                AND row.section_key IN ('resolved_rows','unresolved_rows')
            ) AS reviewer_total_count,
            (
              WITH cohort AS (
                SELECT
                  row.payload_json->>1 AS trading_date,
                  row.payload_json->>3 AS symbol,
                  (row.payload_json->>4)::integer AS v3_rank,
                  (row.payload_json->>14)::double precision AS sector_relative_return_pct,
                  (row.payload_json->>15)::double precision AS mfe_pct,
                  (row.payload_json->>16)::double precision AS mae_pct,
                  (row.payload_json->>18)::integer AS relevance_grade
                FROM public.opportunity_manifest_rows_v3 row
                WHERE row.manifest_id=evaluation.manifest_id
                  AND row.section_key='cohort_rows'
                  AND row.payload_json->>0='backtest'
              ), ranked AS (
                SELECT cohort.*,
                  row_number() OVER (
                    PARTITION BY trading_date
                    ORDER BY relevance_grade DESC,symbol
                  ) AS ideal_rank
                FROM cohort
              ), per_date AS (
                SELECT trading_date,
                  count(*) FILTER (
                    WHERE v3_rank<=20
                      AND mfe_pct>=10
                      AND sector_relative_return_pct>=5
                      AND mae_pct>=-8
                  )::double precision/least(20,count(*)) AS precision_at_20,
                  CASE WHEN sum(
                    (power(2.0,relevance_grade)-1.0)/
                    (ln(ideal_rank+1.0)/ln(2.0))
                  )=0 THEN 0 ELSE
                    sum(
                      CASE WHEN v3_rank<=20 THEN
                        (power(2.0,relevance_grade)-1.0)/
                        (ln(v3_rank+1.0)/ln(2.0))
                      ELSE 0 END
                    )/sum(
                      (power(2.0,relevance_grade)-1.0)/
                      (ln(ideal_rank+1.0)/ln(2.0))
                    )
                  END AS ndcg_at_20,
                  percentile_cont(0.1) WITHIN GROUP (ORDER BY mae_pct)
                    AS worst_decile_mae20_pct
                FROM ranked
                GROUP BY trading_date
                HAVING count(*)>=10
              )
              SELECT CASE WHEN count(*)=120 THEN jsonb_build_object(
                'precisionAt20',avg(precision_at_20),
                'ndcgAt20',avg(ndcg_at_20),
                'worstDecileMae20Pct',avg(worst_decile_mae20_pct)
              ) ELSE NULL END
              FROM per_date
            ) AS v3_metrics,
            (
              WITH cohort AS (
                SELECT
                  row.payload_json->>1 AS trading_date,
                  row.payload_json->>3 AS symbol,
                  (row.payload_json->>5)::integer AS legacy_rank,
                  (row.payload_json->>14)::double precision AS sector_relative_return_pct,
                  (row.payload_json->>15)::double precision AS mfe_pct,
                  (row.payload_json->>16)::double precision AS mae_pct,
                  (row.payload_json->>18)::integer AS relevance_grade
                FROM public.opportunity_manifest_rows_v3 row
                WHERE row.manifest_id=evaluation.manifest_id
                  AND row.section_key='cohort_rows'
                  AND row.payload_json->>0='backtest'
              ), ranked AS (
                SELECT cohort.*,
                  row_number() OVER (
                    PARTITION BY trading_date
                    ORDER BY relevance_grade DESC,symbol
                  ) AS ideal_rank
                FROM cohort
                WHERE legacy_rank IS NOT NULL
              ), per_date AS (
                SELECT trading_date,
                  count(*) FILTER (
                    WHERE legacy_rank<=20
                      AND mfe_pct>=10
                      AND sector_relative_return_pct>=5
                      AND mae_pct>=-8
                  )::double precision/least(20,count(*)) AS precision_at_20,
                  CASE WHEN sum(
                    (power(2.0,relevance_grade)-1.0)/
                    (ln(ideal_rank+1.0)/ln(2.0))
                  )=0 THEN 0 ELSE
                    sum(
                      CASE WHEN legacy_rank<=20 THEN
                        (power(2.0,relevance_grade)-1.0)/
                        (ln(legacy_rank+1.0)/ln(2.0))
                      ELSE 0 END
                    )/sum(
                      (power(2.0,relevance_grade)-1.0)/
                      (ln(ideal_rank+1.0)/ln(2.0))
                    )
                  END AS ndcg_at_20,
                  percentile_cont(0.1) WITHIN GROUP (ORDER BY mae_pct)
                    AS worst_decile_mae20_pct
                FROM ranked
                GROUP BY trading_date
                HAVING count(*)>=10
              )
              SELECT CASE WHEN count(*)=120 THEN jsonb_build_object(
                'precisionAt20',avg(precision_at_20),
                'ndcgAt20',avg(ndcg_at_20),
                'worstDecileMae20Pct',avg(worst_decile_mae20_pct)
              ) ELSE NULL END
              FROM per_date
            ) AS legacy_metrics,
            (
              SELECT
                count(*) FILTER (
                  WHERE sample_row.payload_json->8->>7 IN (
                    'linked_new','linked_refresh','linked_duplicate_claim'
                  )
                    AND (resolution_row.payload_json->>3)::boolean=false
                    AND sample_row.payload_json->8->>9=resolution_row.payload_json->>2
                )::double precision/
                nullif(count(*) FILTER (
                  WHERE sample_row.payload_json->8->>7 IN (
                    'linked_new','linked_refresh','linked_duplicate_claim'
                  )
                ),0)
              FROM public.opportunity_manifest_rows_v3 sample_row
              JOIN public.opportunity_manifest_rows_v3 resolution_row
                ON resolution_row.manifest_id=resolution.manifest_id
                AND resolution_row.section_key='resolved_rows'
                AND resolution_row.payload_json->>0=sample_row.payload_json->>0
              WHERE sample_row.manifest_id=sample.manifest_id
                AND sample_row.section_key='samples'
            ) AS link_precision,
            (
              SELECT
                count(*) FILTER (
                  WHERE (resolution_row.payload_json->>3)::boolean=false
                    AND sample_row.payload_json->8->>9=resolution_row.payload_json->>2
                )::double precision/
                nullif(count(*) FILTER (
                  WHERE (resolution_row.payload_json->>3)::boolean=false
                ),0)
              FROM public.opportunity_manifest_rows_v3 sample_row
              JOIN public.opportunity_manifest_rows_v3 resolution_row
                ON resolution_row.manifest_id=resolution.manifest_id
                AND resolution_row.section_key='resolved_rows'
                AND resolution_row.payload_json->>0=sample_row.payload_json->>0
              WHERE sample_row.manifest_id=sample.manifest_id
                AND sample_row.section_key='samples'
            ) AS link_recall
          FROM public.opportunity_manifests_v3 evaluation
          JOIN public.opportunity_manifests_v3 sample
            ON sample.manifest_id=(p.payload_json->5->>1)::uuid
          JOIN public.opportunity_manifests_v3 resolution
            ON resolution.manifest_id=(p.payload_json->5->>2)::uuid
          WHERE evaluation.manifest_id=(p.payload_json->5->>0)::uuid
            AND evaluation.status='complete'
            AND sample.status='complete'
            AND resolution.status='complete'
        ) evaluation_inputs
      )
      ELSE NULL
    END AS read_body
  FROM public.opportunity_run_jobs_v3 j
  JOIN public.opportunity_job_payloads_v3 p USING(job_id,run_id)
  JOIN public.opportunity_runs r ON r.run_id=j.run_id
  WHERE j.status='leased'
    AND (
      p.payload_kind NOT IN ('deep_candidate_batch','portfolio_allocation_batch','projection_bundle')
      OR NOT EXISTS (
        SELECT 1
        FROM (
          SELECT count(*) OVER (
              PARTITION BY prior.source_cutoff,prior.terminal_at
            ) AS tie_count
          FROM public.opportunity_runs prior
          WHERE prior.mode='enrich_rank'
            AND prior.status='success'
            AND prior.comparison_contract_key=r.comparison_contract_key
            AND prior.source_cutoff<r.source_cutoff
          ORDER BY prior.source_cutoff DESC,prior.terminal_at DESC,prior.run_id
          LIMIT 1
        ) immediately_preceding
        WHERE immediately_preceding.tie_count>1
      )
    )
    AND p.payload_kind IN (
      'manifest_page','manifest_root','source_parse_batch','source_connector_summary',
      'market_context_snapshot','shallow_candidate_batch','sector_cycle_batch','deep_candidate_batch',
      'portfolio_allocation_batch','projection_bundle','outcome_batch','evaluation_bundle'
    )
), envelopes AS (
  SELECT job_id,input_hash,read_kind,
    jsonb_build_array('opportunity-worker-read-v3.4',read_kind,run_id,job_id,input_hash,read_body) AS read_json
  FROM units WHERE read_kind IS NOT NULL
)
SELECT job_id,input_hash,read_kind,
  convert_to(regexp_replace(read_json::text, ', ', ',', 'g'),'utf8') AS read_canonical,
  read_json,
  encode(extensions.digest(
    convert_to(regexp_replace(read_json::text, ', ', ',', 'g'),'utf8'),'sha256'
  ),'hex') AS read_hash
FROM envelopes;

CREATE OR REPLACE FUNCTION internal_principal_role_is_exact_v3_internal(
  principal_id uuid, required_role internal_principal_role_v3, authority_time timestamptz
) RETURNS boolean
LANGUAGE sql STABLE SET search_path = ''
AS $fn$
  WITH head AS MATERIALIZED (
    SELECT binding.recorded_at
    FROM public.internal_principal_role_bindings_v3 binding
    WHERE binding.principal_id=$1 AND binding.role=$2 AND binding.recorded_at<=$3
    ORDER BY binding.recorded_at DESC,binding.binding_id
    LIMIT 1
  ), variants AS MATERIALIZED (
    SELECT DISTINCT binding.valid_from,binding.valid_to,binding.status,binding.configuration_hash
    FROM public.internal_principal_role_bindings_v3 binding
    JOIN head ON head.recorded_at=binding.recorded_at
    WHERE binding.principal_id=$1 AND binding.role=$2
    ORDER BY binding.valid_from,binding.valid_to,binding.status,binding.configuration_hash
    LIMIT 2
  )
  SELECT count(*)=1
    AND bool_and(status='active')
    AND bool_and(valid_from<=$3)
    AND bool_and(valid_to IS NULL OR $3<valid_to)
  FROM variants
$fn$;

CREATE OR REPLACE FUNCTION consume_internal_nonce_v3(
  principal_id uuid, required_role internal_principal_role_v3,
  nonce text, request_timestamp timestamptz
) RETURNS TABLE(recorded_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_now timestamptz := clock_timestamp(); v_recorded timestamptz;
BEGIN
  IF $3 !~ '^[0-9a-f]{16,64}$' OR abs(extract(epoch FROM (v_now - $4))) > 300 THEN
    RAISE EXCEPTION USING ERRCODE='PT403', MESSAGE='authentication_rejected';
  END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($1,$2,v_now) THEN
    RAISE EXCEPTION USING ERRCODE='PT403', MESSAGE='principal_role_unavailable';
  END IF;
  INSERT INTO public.internal_principal_nonces_v3(principal_id,nonce,request_timestamp,recorded_at)
  VALUES($1,$3,$4,v_now) RETURNING internal_principal_nonces_v3.recorded_at INTO v_recorded;
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'consume_internal_nonce_v3',$1,'nonce',NULL,
    encode(extensions.digest(convert_to(jsonb_build_array($1,$2,$4)::text,'utf8'),'sha256'),'hex'),
    'consumed',v_now
  );
  RETURN QUERY SELECT v_recorded;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION USING ERRCODE='PT403', MESSAGE='authentication_rejected';
END
$fn$;

CREATE OR REPLACE FUNCTION purge_internal_nonces_v3(cutoff timestamptz,caller_principal uuid)
RETURNS TABLE(deleted integer)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_now timestamptz := clock_timestamp(); v_deleted integer;
BEGIN
  IF $1 > v_now - interval '24 hours' THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
  END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  DELETE FROM public.internal_principal_nonces_v3 n WHERE n.recorded_at < $1;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'purge_internal_nonces_v3',$2,'nonce_purge',NULL,
    encode(extensions.digest(convert_to(jsonb_build_array($1)::text,'utf8'),'sha256'),'hex'),'purged',v_now
  );
  RETURN QUERY SELECT v_deleted;
END
$fn$;

CREATE OR REPLACE FUNCTION append_source_document_revision_v3(
  input source_document_revision_input_v3,caller_principal uuid
) RETURNS TABLE(revision_id uuid,recorded_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_now timestamptz := clock_timestamp(); v_authority public.source_identity_authorities_v3%ROWTYPE;
  v_family text; v_revision uuid := extensions.gen_random_uuid(); v_registered_count bigint;
  v_existing uuid; v_existing_recorded timestamptz; v_field jsonb; v_segment jsonb;
  v_field_text text; v_field_key text; v_normalized text; v_segments jsonb;
  v_canonical_fields jsonb := '[]'::jsonb; v_measured_count integer := 0;
  v_expected_raw_hash text; v_expected_canonical_hash text;
  v_json_text text; v_compact_json text; v_character text;
  v_json_index integer; v_json_ordinal integer := 0;
  v_inside_string boolean; v_escaped boolean;
BEGIN
  SELECT * INTO v_authority FROM public.source_identity_authorities_v3 a
  WHERE a.authority_id=($1).source_identity_authority_id
    AND a.status='active' AND a.recorded_at<=v_now AND a.valid_from<=v_now
    AND (a.valid_to IS NULL OR v_now<a.valid_to)
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='authority_reference_unavailable'; END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF ($1).adapter_version<>'source-adapter-v3.3'
    OR ($1).raw_field_payload_algorithm_version<>'raw-field-payload-v3.0'
    OR ($1).canonical_content_algorithm_version<>'canonical-content-v3.0'
    OR (
      ($1).acquisition_status='content_overflow'
      AND ($1).raw_code_point_count<>100001
    )
    OR (
      ($1).acquisition_status<>'content_overflow'
      AND ($1).raw_code_point_count>100000
    )
    OR ($1).collected_at>v_now
    OR (($1).published_at IS NOT NULL AND ($1).published_at>($1).collected_at)
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  IF ($1).acquisition_status='complete' THEN
    IF ($1).raw_field_payload IS NULL
      OR jsonb_typeof(($1).raw_field_payload)<>'array'
      OR jsonb_array_length(($1).raw_field_payload)<>3
      OR ($1).ingestion_content_revision_sha256 IS NULL
      OR ($1).ingestion_canonical_content_hash_v3 IS NULL
    THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
    FOR v_field,v_field_key IN
      SELECT field.value,
        CASE field.ordinality
          WHEN 1 THEN 'title'
          WHEN 2 THEN 'summary'
          WHEN 3 THEN CASE WHEN v_authority.source_key IN ('earnings_call','podcast','youtube')
            THEN 'transcript' ELSE 'body' END
        END
      FROM jsonb_array_elements(($1).raw_field_payload)
        WITH ORDINALITY AS field(value,ordinality)
      ORDER BY field.ordinality
    LOOP
      IF v_field_key='transcript' THEN
        IF jsonb_typeof(v_field)<>'array' THEN
          RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
        END IF;
        FOR v_segment IN SELECT value FROM jsonb_array_elements(v_field)
        LOOP
          IF jsonb_typeof(v_segment)<>'array'
            OR jsonb_array_length(v_segment)<>3
            OR jsonb_typeof(v_segment->0)<>'number'
            OR (v_segment->>0)!~'^-?[0-9]+$'
            OR jsonb_typeof(v_segment->1)<>'string'
            OR jsonb_typeof(v_segment->2)<>'string'
          THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
          v_normalized:=normalize(replace(replace(
            CASE WHEN left(v_segment->>2,1)=chr(65279)
              THEN substr(v_segment->>2,2) ELSE v_segment->>2 END,
            E'\r\n',E'\n'),E'\r',E'\n'),NFKC);
          v_measured_count:=v_measured_count+char_length(v_normalized);
          IF v_measured_count>100000 THEN
            RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
          END IF;
        END LOOP;
        SELECT coalesce(jsonb_agg(jsonb_build_array(
          (segment.value->>0)::bigint,
          normalize(replace(replace(
            CASE WHEN left(segment.value->>2,1)=chr(65279)
              THEN substr(segment.value->>2,2) ELSE segment.value->>2 END,
            E'\r\n',E'\n'),E'\r',E'\n'),NFKC)
        ) ORDER BY (segment.value->>0)::bigint,segment.value->>1),'[]'::jsonb)
        INTO v_segments
        FROM jsonb_array_elements(v_field) AS segment(value);
        v_canonical_fields:=v_canonical_fields||
          jsonb_build_array(jsonb_build_array(v_field_key,v_segments));
      ELSE
        IF jsonb_typeof(v_field)<>'string' THEN
          RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
        END IF;
        v_field_text:=v_field#>>'{}';
        v_normalized:=normalize(replace(replace(
          CASE WHEN left(v_field_text,1)=chr(65279)
            THEN substr(v_field_text,2) ELSE v_field_text END,
          E'\r\n',E'\n'),E'\r',E'\n'),NFKC);
        v_measured_count:=v_measured_count+char_length(v_normalized);
        IF v_measured_count>100000 THEN
          RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
        END IF;
        v_canonical_fields:=v_canonical_fields||
          jsonb_build_array(jsonb_build_array(v_field_key,v_normalized));
      END IF;
    END LOOP;
    FOREACH v_json_text IN ARRAY ARRAY[
      '{"adapterVersion":'||to_jsonb(($1).adapter_version)::text||
        ',"fields":'||($1).raw_field_payload::text||
        ',"version":"raw-field-payload-v3.0"}',
      v_canonical_fields::text
    ] LOOP
      v_json_ordinal:=v_json_ordinal+1;
      v_compact_json:=''; v_json_index:=1; v_inside_string:=false; v_escaped:=false;
      WHILE v_json_index<=char_length(v_json_text) LOOP
        v_character:=substr(v_json_text,v_json_index,1);
        IF v_inside_string THEN
          v_compact_json:=v_compact_json||v_character;
          IF v_escaped THEN v_escaped:=false;
          ELSIF v_character=chr(92) THEN v_escaped:=true;
          ELSIF v_character='"' THEN v_inside_string:=false;
          END IF;
        ELSIF v_character='"' THEN
          v_inside_string:=true; v_compact_json:=v_compact_json||v_character;
        ELSIF v_character=',' AND substr(v_json_text,v_json_index+1,1)=' ' THEN
          v_compact_json:=v_compact_json||','; v_json_index:=v_json_index+1;
        ELSE
          v_compact_json:=v_compact_json||v_character;
        END IF;
        v_json_index:=v_json_index+1;
      END LOOP;
      IF v_inside_string OR v_escaped THEN
        RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
      END IF;
      IF v_json_ordinal=1 THEN
        v_expected_raw_hash:=encode(extensions.digest(convert_to(v_compact_json,'utf8'),'sha256'),'hex');
      ELSE
        v_expected_canonical_hash:=encode(extensions.digest(convert_to(v_compact_json,'utf8'),'sha256'),'hex');
      END IF;
    END LOOP;
    IF v_measured_count<>($1).raw_code_point_count
      OR v_expected_raw_hash<>($1).ingestion_content_revision_sha256
      OR v_expected_canonical_hash<>($1).ingestion_canonical_content_hash_v3
    THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  ELSIF ($1).raw_field_payload IS NOT NULL
    OR ($1).ingestion_content_revision_sha256 IS NOT NULL
    OR ($1).ingestion_canonical_content_hash_v3 IS NOT NULL
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  v_family := encode(extensions.digest(convert_to(jsonb_build_array(
    'source-revision-family-v3.3',v_authority.source_key,v_authority.source_identity_id,
    ($1).stable_connector_document_id
  )::text,'utf8'),'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(v_authority.source_key::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_family,0));
  IF NOT EXISTS (
    SELECT 1
    FROM public.source_revision_family_registry_v3 registry
    WHERE registry.source_key=v_authority.source_key
      AND registry.revision_family_key=v_family
  ) THEN
    SELECT count(*) INTO v_registered_count
    FROM (
      SELECT registry.revision_family_key
      FROM public.source_revision_family_registry_v3 registry
      WHERE registry.source_key=v_authority.source_key
      ORDER BY registry.revision_family_key
      LIMIT 1000001
    ) bounded_registry;
    IF v_registered_count>=1000000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
  END IF;
  INSERT INTO public.source_revision_family_registry_v3(
    source_key,revision_family_key,approved_source_identity_id,stable_connector_document_id,registered_at
  ) VALUES(v_authority.source_key,v_family,v_authority.source_identity_id,($1).stable_connector_document_id,v_now)
  ON CONFLICT(source_key,revision_family_key) DO NOTHING;
  IF ($1).supersedes_revision_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.source_document_revisions_v3 prior
    WHERE prior.revision_id=($1).supersedes_revision_id
      AND prior.source_key=v_authority.source_key
      AND prior.revision_family_key=v_family
      AND prior.recorded_at<v_now
  ) THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  SELECT retained.revision_id,retained.recorded_at INTO v_existing,v_existing_recorded
  FROM public.source_document_revisions_v3 retained
  WHERE retained.source_key=v_authority.source_key
    AND retained.revision_family_key=v_family
    AND retained.source_identity_authority_id=($1).source_identity_authority_id
    AND retained.canonical_url_candidate IS NOT DISTINCT FROM ($1).canonical_url_candidate
    AND retained.published_at IS NOT DISTINCT FROM ($1).published_at
    AND retained.collected_at=($1).collected_at
    AND retained.adapter_version=($1).adapter_version
    AND retained.acquisition_status=($1).acquisition_status
    AND retained.raw_field_payload IS NOT DISTINCT FROM ($1).raw_field_payload
    AND retained.raw_code_point_count=($1).raw_code_point_count
    AND retained.raw_field_payload_algorithm_version=($1).raw_field_payload_algorithm_version
    AND retained.ingestion_content_revision_sha256 IS NOT DISTINCT FROM ($1).ingestion_content_revision_sha256
    AND retained.canonical_content_algorithm_version=($1).canonical_content_algorithm_version
    AND retained.ingestion_canonical_content_hash_v3 IS NOT DISTINCT FROM ($1).ingestion_canonical_content_hash_v3
    AND retained.supersedes_revision_id IS NOT DISTINCT FROM ($1).supersedes_revision_id
  ORDER BY retained.revision_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_source_document_revision_v3',$2,'source_revision',v_existing,
      encode(extensions.digest(convert_to(jsonb_build_array(
        v_family,($1).ingestion_content_revision_sha256
      )::text,'utf8'),'sha256'),'hex'),'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  IF (SELECT count(*) FROM (
    SELECT 1 FROM public.source_document_revisions_v3 r
    WHERE r.source_key=v_authority.source_key AND r.revision_family_key=v_family
    ORDER BY r.recorded_at DESC,r.revision_id LIMIT 65
  ) bounded) >= 64 THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
  INSERT INTO public.source_document_revisions_v3(
    revision_id,revision_family_key,source_key,source_identity_authority_id,approved_source_identity_id,
    stable_connector_document_id,canonical_url_candidate,published_at,collected_at,adapter_version,
    acquisition_status,raw_field_payload,raw_code_point_count,raw_field_payload_algorithm_version,
    ingestion_content_revision_sha256,canonical_content_algorithm_version,
    ingestion_canonical_content_hash_v3,supersedes_revision_id,recorded_at
  ) VALUES(
    v_revision,v_family,v_authority.source_key,($1).source_identity_authority_id,v_authority.source_identity_id,
    ($1).stable_connector_document_id,($1).canonical_url_candidate,($1).published_at,($1).collected_at,
    ($1).adapter_version,($1).acquisition_status,($1).raw_field_payload,($1).raw_code_point_count,
    ($1).raw_field_payload_algorithm_version,($1).ingestion_content_revision_sha256,
    ($1).canonical_content_algorithm_version,($1).ingestion_canonical_content_hash_v3,
    ($1).supersedes_revision_id,v_now
  );
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_source_document_revision_v3',$2,'source_revision',v_revision,
    encode(extensions.digest(convert_to(jsonb_build_array(v_family,($1).ingestion_content_revision_sha256)::text,'utf8'),'sha256'),'hex'),
    'appended',v_now
  );
  RETURN QUERY SELECT v_revision,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION append_instrument_roster_authority_v3(
  input instrument_authority_input_v3,caller_principal uuid
) RETURNS TABLE(instrument_authority_id uuid,official_alias_authority_ids uuid[],recorded_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_aliases uuid[]:='{}'::uuid[]; v_alias uuid; v_existing uuid;
  v_existing_recorded timestamptz; v_registry_count integer; v_revision_count integer;
  v_stream_canonical bytea; v_stream_hash text; v_alias_canonical bytea;
  v_alias_hash text; v_alias_text text; v_alias_status public.authority_status_v3;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF ($1).roster_version<>'tw-instrument-roster-v3.0'
    OR (($1).exchange='TWSE') IS DISTINCT FROM (($1).provider='twse')
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  v_stream_canonical:=convert_to(regexp_replace(jsonb_build_array(
    'instrument_roster',($1).stock_id
  )::text,', ', ',', 'g'),'utf8');
  v_stream_hash:=encode(extensions.digest(v_stream_canonical,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|instrument_roster',0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_stream_hash,0));
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
    WHERE registry.family='instrument_roster'
      AND registry.stream_key_hash=v_stream_hash
      AND registry.stream_key_canonical=v_stream_canonical
  ) THEN
    SELECT count(*) INTO v_registry_count FROM (
      SELECT registry.stream_key_hash
      FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='instrument_roster'
      ORDER BY registry.stream_key_hash,registry.stream_key_canonical
      LIMIT 20001
    ) bounded;
    IF v_registry_count>=20000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    INSERT INTO public.opportunity_authority_stream_registry_v3(
      family,stream_key_hash,stream_key_canonical,registered_at
    ) VALUES('instrument_roster',v_stream_hash,v_stream_canonical,v_now);
  END IF;
  SELECT retained.instrument_authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.stock_instruments_v3 retained
  WHERE retained.stock_id=($1).stock_id
    AND retained.symbol=($1).symbol
    AND retained.exchange=($1).exchange
    AND retained.instrument_type=($1).instrument_type
    AND retained.listing_status=($1).listing_status
    AND retained.official_legal_name=($1).official_legal_name
    AND retained.official_short_name IS NOT DISTINCT FROM ($1).official_short_name
    AND retained.provider=($1).provider
    AND retained.source_timestamp=($1).source_timestamp
    AND retained.valid_from=($1).valid_from
    AND retained.valid_to IS NOT DISTINCT FROM ($1).valid_to
    AND retained.roster_version=($1).roster_version
  ORDER BY retained.instrument_authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_instrument_roster_authority_v3',$2,'instrument',v_existing,
      encode(extensions.digest(convert_to(jsonb_build_array(
        ($1).stock_id,($1).source_timestamp,($1).roster_version
      )::text,'utf8'),'sha256'),'hex'),'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_aliases,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.instrument_authority_id
    FROM public.stock_instruments_v3 retained
    WHERE retained.stock_id=($1).stock_id
    ORDER BY retained.recorded_at DESC,retained.instrument_authority_id
    LIMIT 65
  ) bounded;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.stock_instruments_v3(
    instrument_authority_id,stock_id,symbol,exchange,instrument_type,listing_status,
    official_legal_name,official_short_name,provider,source_timestamp,valid_from,valid_to,roster_version,recorded_at
  ) VALUES(v_id,($1).stock_id,($1).symbol,($1).exchange,($1).instrument_type,($1).listing_status,
    ($1).official_legal_name,($1).official_short_name,($1).provider,($1).source_timestamp,
    ($1).valid_from,($1).valid_to,($1).roster_version,v_now);
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|stock_alias',0));
  FOR v_alias_text,v_alias_status IN
    WITH normalized(alias,status) AS (
      SELECT btrim(regexp_replace(
          translate(
            regexp_replace(btrim(normalize(($1).official_legal_name,NFKC)),
              '[[:space:]]+',' ','g'),
            'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'
          ),
          '(股份有限公司|有限公司|公司)$',''
        )),
        CASE WHEN ($1).listing_status='active'
          THEN 'active'::public.authority_status_v3 ELSE 'inactive'::public.authority_status_v3 END
      UNION
      SELECT btrim(regexp_replace(
          translate(
            regexp_replace(btrim(normalize(($1).official_short_name,NFKC)),
              '[[:space:]]+',' ','g'),
            'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'
          ),
          '(股份有限公司|有限公司|公司)$',''
        )),
        CASE WHEN ($1).listing_status='active'
          THEN 'active'::public.authority_status_v3 ELSE 'inactive'::public.authority_status_v3 END
      WHERE ($1).official_short_name IS NOT NULL
    ), requested(alias,status) AS (
      SELECT alias,status FROM normalized
      WHERE char_length(alias) BETWEEN 2 AND 40
    ), latest_alias AS (
      SELECT DISTINCT ON (alias.normalized_alias)
        alias.normalized_alias,alias.status
      FROM public.stock_aliases_v3 alias
      WHERE alias.stock_id=($1).stock_id
        AND alias.source='official_roster_seed'
      ORDER BY alias.normalized_alias,alias.recorded_at DESC,alias.alias_authority_id
    ), revoked(alias,status) AS (
      SELECT latest_alias.normalized_alias,'inactive'::public.authority_status_v3
      FROM latest_alias
      WHERE latest_alias.status='active'
        AND NOT EXISTS (
          SELECT 1 FROM requested
          WHERE requested.alias=latest_alias.normalized_alias
            AND requested.status='active'
        )
    )
    SELECT alias,status FROM requested
    UNION
    SELECT alias,status FROM revoked
    ORDER BY alias,status
  LOOP
    v_alias_canonical:=convert_to(regexp_replace(jsonb_build_array(
      'stock_alias',($1).stock_id,v_alias_text,'official_roster_seed'
    )::text,', ', ',', 'g'),'utf8');
    v_alias_hash:=encode(extensions.digest(v_alias_canonical,'sha256'),'hex');
    PERFORM pg_advisory_xact_lock(hashtextextended(v_alias_hash,0));
    IF NOT EXISTS (
      SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='stock_alias'
        AND registry.stream_key_hash=v_alias_hash
        AND registry.stream_key_canonical=v_alias_canonical
    ) THEN
      SELECT count(*) INTO v_registry_count FROM (
        SELECT registry.stream_key_hash
        FROM public.opportunity_authority_stream_registry_v3 registry
        WHERE registry.family='stock_alias'
        ORDER BY registry.stream_key_hash,registry.stream_key_canonical
        LIMIT 100001
      ) bounded;
      IF v_registry_count>=100000 THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
      END IF;
      INSERT INTO public.opportunity_authority_stream_registry_v3(
        family,stream_key_hash,stream_key_canonical,registered_at
      ) VALUES('stock_alias',v_alias_hash,v_alias_canonical,v_now);
    END IF;
    SELECT count(*) INTO v_revision_count FROM (
      SELECT alias.alias_authority_id
      FROM public.stock_aliases_v3 alias
      WHERE alias.stock_id=($1).stock_id
        AND alias.normalized_alias=v_alias_text
        AND alias.source='official_roster_seed'
      ORDER BY alias.recorded_at DESC,alias.alias_authority_id
      LIMIT 65
    ) bounded;
    IF v_revision_count>=64 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    v_alias:=extensions.gen_random_uuid();
    INSERT INTO public.stock_aliases_v3(alias_authority_id,stock_id,normalized_alias,source,source_timestamp,
      approved_by_principal_id,approved_at,valid_from,valid_to,status,normalization_version,recorded_at)
    VALUES(v_alias,($1).stock_id,v_alias_text,'official_roster_seed',($1).source_timestamp,
      $2,v_now,($1).valid_from,($1).valid_to,v_alias_status,
      'entity-link-v3.1',v_now);
    v_aliases:=array_append(v_aliases,v_alias);
  END LOOP;
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_instrument_roster_authority_v3',$2,'instrument',v_id,
    encode(extensions.digest(convert_to(jsonb_build_array(
      ($1).stock_id,($1).source_timestamp,($1).roster_version
    )::text,'utf8'),'sha256'),'hex'),'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_aliases,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION append_stock_sector_assignment_v3(
  input sector_assignment_input_v3,caller_principal uuid
) RETURNS TABLE(assignment_authority_id uuid,recorded_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_existing uuid; v_existing_recorded timestamptz; v_registry_count integer;
  v_revision_count integer; v_stream_canonical bytea; v_stream_hash text;
  v_expected_sector public.canonical_sector_key_v3;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  v_expected_sector:=CASE ($1).official_industry_code
    WHEN '01' THEN 'cement' WHEN '02' THEN 'food' WHEN '03' THEN 'plastics'
    WHEN '04' THEN 'textile' WHEN '05' THEN 'electrical_machinery'
    WHEN '06' THEN 'electrical_cable' WHEN '08' THEN 'glass_ceramic'
    WHEN '09' THEN 'paper_pulp' WHEN '10' THEN 'steel' WHEN '11' THEN 'rubber'
    WHEN '12' THEN 'auto' WHEN '14' THEN 'construction'
    WHEN '15' THEN 'shipping_transport' WHEN '16' THEN 'tourism'
    WHEN '17' THEN 'finance_insurance' WHEN '18' THEN 'department_store'
    WHEN '20' THEN 'other' WHEN '21' THEN 'chemical'
    WHEN '22' THEN 'biotech_medical' WHEN '23' THEN 'oil_gas_electricity'
    WHEN '24' THEN 'semiconductor' WHEN '25' THEN 'computer_peripheral'
    WHEN '26' THEN 'optoelectronics' WHEN '27' THEN 'communications_network'
    WHEN '28' THEN 'electronic_components' WHEN '29' THEN 'electronic_distribution'
    WHEN '30' THEN 'information_service' WHEN '31' THEN 'other_electronics'
    WHEN '32' THEN 'green_energy_environment' WHEN '33' THEN 'digital_cloud'
    WHEN '34' THEN 'sports_leisure' WHEN '35' THEN 'home_living'
    ELSE 'unknown'
  END;
  IF ($1).taxonomy_version<>'tw-sector-taxonomy-v3.0'
    OR (($1).market='TWSE') IS DISTINCT FROM (($1).provider='twse')
    OR ($1).canonical_sector_key<>v_expected_sector
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  v_stream_canonical:=convert_to(regexp_replace(jsonb_build_array(
    'sector_assignment',($1).stock_id,($1).market
  )::text,', ', ',', 'g'),'utf8');
  v_stream_hash:=encode(extensions.digest(v_stream_canonical,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|sector_assignment',0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_stream_hash,0));
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
    WHERE registry.family='sector_assignment'
      AND registry.stream_key_hash=v_stream_hash
      AND registry.stream_key_canonical=v_stream_canonical
  ) THEN
    SELECT count(*) INTO v_registry_count FROM (
      SELECT registry.stream_key_hash
      FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='sector_assignment'
      ORDER BY registry.stream_key_hash,registry.stream_key_canonical
      LIMIT 20001
    ) bounded;
    IF v_registry_count>=20000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    INSERT INTO public.opportunity_authority_stream_registry_v3(
      family,stream_key_hash,stream_key_canonical,registered_at
    ) VALUES('sector_assignment',v_stream_hash,v_stream_canonical,v_now);
  END IF;
  SELECT retained.assignment_authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.stock_sector_assignments_v3 retained
  WHERE retained.stock_id=($1).stock_id
    AND retained.market=($1).market
    AND retained.official_industry_code=($1).official_industry_code
    AND retained.canonical_sector_key=($1).canonical_sector_key
    AND retained.provider=($1).provider
    AND retained.source_timestamp=($1).source_timestamp
    AND retained.valid_from=($1).valid_from
    AND retained.valid_to IS NOT DISTINCT FROM ($1).valid_to
    AND retained.taxonomy_version=($1).taxonomy_version
    AND retained.status=($1).status
  ORDER BY retained.assignment_authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_stock_sector_assignment_v3',$2,'sector_assignment',v_existing,
      encode(extensions.digest(convert_to(jsonb_build_array(
        ($1).stock_id,($1).market,($1).source_timestamp
      )::text,'utf8'),'sha256'),'hex'),'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.assignment_authority_id
    FROM public.stock_sector_assignments_v3 retained
    WHERE retained.stock_id=($1).stock_id AND retained.market=($1).market
    ORDER BY retained.recorded_at DESC,retained.assignment_authority_id
    LIMIT 65
  ) bounded;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.stock_sector_assignments_v3(
    assignment_authority_id,stock_id,market,official_industry_code,canonical_sector_key,provider,
    source_timestamp,valid_from,valid_to,taxonomy_version,status,recorded_at
  ) VALUES(v_id,($1).stock_id,($1).market,($1).official_industry_code,($1).canonical_sector_key,
    ($1).provider,($1).source_timestamp,($1).valid_from,($1).valid_to,($1).taxonomy_version,($1).status,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_stock_sector_assignment_v3',$2,'sector_assignment',v_id,
    encode(extensions.digest(convert_to(jsonb_build_array(
      ($1).stock_id,($1).market,($1).source_timestamp
    )::text,'utf8'),'sha256'),'hex'),'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION append_trading_session_v3(
  input trading_session_input_v3,caller_principal uuid
) RETURNS TABLE(session_authority_id uuid,recorded_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_existing uuid; v_existing_recorded timestamptz; v_revision_count integer;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF (($1).market='TWSE') IS DISTINCT FROM (($1).provider='twse')
    OR (($1).open_at AT TIME ZONE 'Asia/Taipei')::date<>($1).session_id
    OR (($1).close_at AT TIME ZONE 'Asia/Taipei')::date<>($1).session_id
    OR ($1).open_at>=($1).close_at
    OR ($1).source_timestamp>($1).collected_at
    OR ($1).collected_at>v_now
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(
    '|','trading_session',($1).market,($1).session_id
  ),0));
  SELECT retained.session_authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.tw_trading_sessions_v3 retained
  WHERE retained.market=($1).market
    AND retained.session_id=($1).session_id
    AND retained.open_at=($1).open_at
    AND retained.close_at=($1).close_at
    AND retained.status=($1).status
    AND retained.provider=($1).provider
    AND retained.source_timestamp=($1).source_timestamp
    AND retained.collected_at=($1).collected_at
    AND retained.source_ref=($1).source_ref
  ORDER BY retained.session_authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_trading_session_v3',$2,'trading_session',v_existing,
      encode(extensions.digest(convert_to(jsonb_build_array(
        ($1).market,($1).session_id,($1).source_timestamp
      )::text,'utf8'),'sha256'),'hex'),'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.session_authority_id
    FROM public.tw_trading_sessions_v3 retained
    WHERE retained.market=($1).market AND retained.session_id=($1).session_id
    ORDER BY retained.recorded_at DESC,retained.session_authority_id
    LIMIT 1025
  ) bounded;
  IF v_revision_count>=1024 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.tw_trading_sessions_v3(session_authority_id,session_id,market,open_at,close_at,status,
    provider,source_timestamp,collected_at,source_ref,recorded_at)
  VALUES(v_id,($1).session_id,($1).market,($1).open_at,($1).close_at,($1).status,
    ($1).provider,($1).source_timestamp,($1).collected_at,($1).source_ref,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_trading_session_v3',$2,'trading_session',v_id,
    encode(extensions.digest(convert_to(jsonb_build_array(
      ($1).market,($1).session_id,($1).source_timestamp
    )::text,'utf8'),'sha256'),'hex'),'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION append_market_observation_v3(
  input market_observation_input_v3,caller_principal uuid
) RETURNS TABLE(observation_id uuid,recorded_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_now timestamptz:=clock_timestamp();
  v_id uuid:=extensions.gen_random_uuid();
  v_authority_date date;
  v_provider_session_date date;
  v_existing uuid;
  v_revision_count integer;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF (($1).provider='global_allowlisted') IS DISTINCT FROM (($1).provider_identity IS NOT NULL)
    OR (($1).session_id IS NULL) IS DISTINCT FROM (($1).session_authority_id IS NULL)
    OR ($1).scope_key='TW_ACTIVE_COMMON'
    OR (
      (($1).scope_key IN ('TAIEX','OTC','TWSE_ACTIVE_COMMON','TPEX_ACTIVE_COMMON'))
      IS DISTINCT FROM (($1).session_id IS NOT NULL)
    )
    OR (
      ($1).fact_key IN ('taiex_close','otc_close')
      AND ($1).value<=0
    )
    OR ($1).observed_at>($1).collected_at
    OR ($1).collected_at>v_now
    OR NOT EXISTS (
      SELECT 1 FROM (VALUES
        ('taiex_close'::public.market_fact_key_v3,'TAIEX'::public.market_scope_key_v3,
          'index_points'::public.market_unit_v3,'twse'::public.market_provider_v3,NULL::text),
        ('taiex_close','TAIEX','index_points','finmind',NULL),
        ('taiex_close','TAIEX','index_points','node_twstock',NULL),
        ('otc_close','OTC','index_points','tpex',NULL),
        ('otc_close','OTC','index_points','finmind',NULL),
        ('otc_close','OTC','index_points','node_twstock',NULL),
        ('above_ma20','TWSE_ACTIVE_COMMON','percentage_points','twse',NULL),
        ('above_ma20','TWSE_ACTIVE_COMMON','percentage_points','finmind',NULL),
        ('above_ma20','TPEX_ACTIVE_COMMON','percentage_points','tpex',NULL),
        ('above_ma20','TPEX_ACTIVE_COMMON','percentage_points','finmind',NULL),
        ('above_ma60','TWSE_ACTIVE_COMMON','percentage_points','twse',NULL),
        ('above_ma60','TWSE_ACTIVE_COMMON','percentage_points','finmind',NULL),
        ('above_ma60','TPEX_ACTIVE_COMMON','percentage_points','tpex',NULL),
        ('above_ma60','TPEX_ACTIVE_COMMON','percentage_points','finmind',NULL),
        ('foreign_cash_5d','TWSE_ACTIVE_COMMON','TWD','twse',NULL),
        ('foreign_cash_5d','TWSE_ACTIVE_COMMON','TWD','finmind',NULL),
        ('foreign_cash_5d','TPEX_ACTIVE_COMMON','TWD','tpex',NULL),
        ('foreign_cash_5d','TPEX_ACTIVE_COMMON','TWD','finmind',NULL),
        ('trust_cash_5d','TWSE_ACTIVE_COMMON','TWD','twse',NULL),
        ('trust_cash_5d','TWSE_ACTIVE_COMMON','TWD','finmind',NULL),
        ('trust_cash_5d','TPEX_ACTIVE_COMMON','TWD','tpex',NULL),
        ('trust_cash_5d','TPEX_ACTIVE_COMMON','TWD','finmind',NULL),
        ('margin_change_5d','TWSE_ACTIVE_COMMON','TWD','twse',NULL),
        ('margin_change_5d','TWSE_ACTIVE_COMMON','TWD','finmind',NULL),
        ('margin_change_5d','TPEX_ACTIVE_COMMON','TWD','tpex',NULL),
        ('margin_change_5d','TPEX_ACTIVE_COMMON','TWD','finmind',NULL),
        ('foreign_futures_oi','TAIFEX','contracts','taifex',NULL),
        ('foreign_futures_oi','TAIFEX','contracts','finmind',NULL),
        ('put_call_ratio','TAIFEX','ratio','taifex',NULL),
        ('put_call_ratio','TAIFEX','ratio','finmind',NULL),
        ('taiwan_vix','TAIFEX','index_points','taifex',NULL),
        ('taiwan_vix','TAIFEX','index_points','finmind',NULL),
        ('sox_return_5d','SOX','percentage_points','global_allowlisted','stooq:sox:daily:v1'),
        ('nasdaq_return_5d','NASDAQ','percentage_points','global_allowlisted','stooq:nasdaq:daily:v1'),
        ('usd_twd_return_5d','USD_TWD','percentage_points','global_allowlisted','stooq:usd-twd:daily:v1')
      ) allowed(fact_key,scope_key,unit,provider,provider_identity)
      WHERE allowed.fact_key=($1).fact_key
        AND allowed.scope_key=($1).scope_key
        AND allowed.unit=($1).unit
        AND allowed.provider=($1).provider
        AND allowed.provider_identity IS NOT DISTINCT FROM ($1).provider_identity
    )
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  IF ($1).provider='global_allowlisted' THEN
    v_provider_session_date:=CASE ($1).fact_key
      WHEN 'usd_twd_return_5d' THEN (($1).observed_at AT TIME ZONE 'UTC')::date
      ELSE (($1).observed_at AT TIME ZONE 'America/New_York')::date
    END;
    v_authority_date:=v_provider_session_date;
    IF ($1).session_id IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
    END IF;
  ELSIF ($1).session_id IS NOT NULL THEN
    v_authority_date:=($1).session_id;
    IF NOT EXISTS (
      SELECT 1 FROM public.tw_trading_sessions_v3 session
      WHERE session.session_authority_id=($1).session_authority_id
        AND session.session_id=($1).session_id
        AND session.market=CASE
          WHEN ($1).scope_key IN ('TAIEX','TWSE_ACTIVE_COMMON')
            THEN 'TWSE'::public.tw_market_v3
          WHEN ($1).scope_key IN ('OTC','TPEX_ACTIVE_COMMON')
            THEN 'TPEX'::public.tw_market_v3
        END
        AND session.status='completed'
        AND session.recorded_at<=v_now
        AND NOT EXISTS (
          SELECT 1 FROM public.tw_trading_sessions_v3 newer
          WHERE newer.market=session.market
            AND newer.session_id=session.session_id
            AND newer.recorded_at<=v_now
            AND newer.recorded_at>=session.recorded_at
            AND newer.session_authority_id<>session.session_authority_id
        )
        AND EXISTS (
          SELECT 1 FROM public.tw_trading_sessions_v3 counterpart
          WHERE counterpart.session_id=session.session_id
            AND counterpart.market<>session.market
            AND counterpart.open_at=session.open_at
            AND counterpart.close_at=session.close_at
            AND counterpart.status='completed'
            AND counterpart.recorded_at<=v_now
            AND NOT EXISTS (
              SELECT 1 FROM public.tw_trading_sessions_v3 newer_counterpart
              WHERE newer_counterpart.market=counterpart.market
                AND newer_counterpart.session_id=counterpart.session_id
                AND newer_counterpart.recorded_at<=v_now
                AND newer_counterpart.recorded_at>=counterpart.recorded_at
                AND newer_counterpart.session_authority_id<>counterpart.session_authority_id
            )
        )
    ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='calendar_authority_mismatch'; END IF;
    IF ($1).fact_key IN ('taiex_close','otc_close') AND NOT EXISTS (
      SELECT 1 FROM public.tw_trading_sessions_v3 session
      WHERE session.session_authority_id=($1).session_authority_id
        AND session.close_at=($1).observed_at
    ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='calendar_authority_mismatch'; END IF;
  ELSE
    v_authority_date:=(($1).observed_at AT TIME ZONE 'Asia/Taipei')::date;
  END IF;
  IF ($1).fact_key IN ('above_ma20','above_ma60') THEN
    IF ($1).breadth_numerator_count IS NULL
      OR ($1).breadth_observed_count IS NULL
      OR ($1).breadth_observed_count<=0
      OR ($1).breadth_eligible_count IS NULL
      OR ($1).breadth_roster_manifest_id IS NULL
      OR ($1).breadth_roster_manifest_hash IS NULL
      OR ($1).value<>round(
        100.0*($1).breadth_numerator_count/($1).breadth_observed_count,2
      )::double precision
      OR NOT EXISTS (
        SELECT 1 FROM public.opportunity_manifests_v3 manifest
        WHERE manifest.manifest_id=($1).breadth_roster_manifest_id
          AND manifest.manifest_kind='instrument_roster'
          AND manifest.contract_version='tw-instrument-roster-v3.0'
          AND manifest.status='complete'
          AND manifest.manifest_hash=($1).breadth_roster_manifest_hash
      )
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  ELSIF num_nonnulls(
    ($1).breadth_numerator_count,($1).breadth_observed_count,($1).breadth_eligible_count,
    ($1).breadth_roster_manifest_id,($1).breadth_roster_manifest_hash
  )<>0 THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws('|',
    ($1).fact_key,($1).scope_key,v_authority_date,($1).provider,
    coalesce(($1).provider_identity,'')),0));
  SELECT observation.observation_id INTO v_existing
  FROM public.opportunity_market_observations_v3 observation
  WHERE observation.fact_key=($1).fact_key
    AND observation.scope_key=($1).scope_key
    AND observation.authority_date=v_authority_date
    AND observation.provider=($1).provider
    AND observation.provider_identity IS NOT DISTINCT FROM ($1).provider_identity
    AND observation.session_id IS NOT DISTINCT FROM ($1).session_id
    AND observation.session_authority_id IS NOT DISTINCT FROM ($1).session_authority_id
    AND observation.value=($1).value
    AND observation.unit=($1).unit
    AND observation.breadth_numerator_count IS NOT DISTINCT FROM ($1).breadth_numerator_count
    AND observation.breadth_observed_count IS NOT DISTINCT FROM ($1).breadth_observed_count
    AND observation.breadth_eligible_count IS NOT DISTINCT FROM ($1).breadth_eligible_count
    AND observation.breadth_roster_manifest_id IS NOT DISTINCT FROM ($1).breadth_roster_manifest_id
    AND observation.breadth_roster_manifest_hash IS NOT DISTINCT FROM ($1).breadth_roster_manifest_hash
    AND observation.observed_at=($1).observed_at
    AND observation.collected_at=($1).collected_at
    AND observation.source_ref=($1).source_ref
    AND observation.provider_revision=($1).provider_revision
  ORDER BY observation.observation_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN QUERY SELECT v_existing,(SELECT observation.recorded_at
      FROM public.opportunity_market_observations_v3 observation
      WHERE observation.observation_id=v_existing);
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count
  FROM (
    SELECT observation.observation_id
    FROM public.opportunity_market_observations_v3 observation
    WHERE observation.fact_key=($1).fact_key
      AND observation.scope_key=($1).scope_key
      AND observation.authority_date=v_authority_date
      AND observation.provider=($1).provider
      AND observation.provider_identity IS NOT DISTINCT FROM ($1).provider_identity
    ORDER BY observation.recorded_at DESC,observation.observation_id
    LIMIT 65
  ) bounded_revisions;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.opportunity_market_observations_v3(
    observation_id,fact_key,scope_key,session_id,session_authority_id,value,unit,provider,provider_identity,
    authority_date,provider_session_date,
    breadth_numerator_count,breadth_observed_count,breadth_eligible_count,breadth_roster_manifest_id,
    breadth_roster_manifest_hash,observed_at,collected_at,source_ref,provider_revision,recorded_at
  ) VALUES(v_id,($1).fact_key,($1).scope_key,($1).session_id,($1).session_authority_id,($1).value,
    ($1).unit,($1).provider,($1).provider_identity,v_authority_date,v_provider_session_date,
    ($1).breadth_numerator_count,($1).breadth_observed_count,
    ($1).breadth_eligible_count,($1).breadth_roster_manifest_id,($1).breadth_roster_manifest_hash,
    ($1).observed_at,($1).collected_at,($1).source_ref,($1).provider_revision,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_market_observation_v3',$2,'market_observation',v_id,
    encode(extensions.digest(convert_to(jsonb_build_array(
      ($1).fact_key,($1).scope_key,v_authority_date,($1).provider,($1).provider_identity,
      ($1).provider_revision
    )::text,'utf8'),'sha256'),'hex'),'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION append_stock_flow_observation_v3(
  input stock_flow_observation_input_v3,caller_principal uuid
) RETURNS TABLE(observation_id uuid,recorded_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_now timestamptz:=clock_timestamp();
  v_id uuid:=extensions.gen_random_uuid();
  v_existing uuid;
  v_revision_count integer;
  v_expected_owner text;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now) THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable';
  END IF;
  v_expected_owner:=lower(($1).exchange::text);
  IF ($1).provider::text NOT IN (v_expected_owner,'finmind')
    OR ($1).source_timestamp>($1).collected_at
    OR ($1).collected_at>v_now
    OR (
      ($1).fact_key='sbl_short_balance_shares' AND ($1).unit<>'shares'
    )
    OR (
      ($1).fact_key IN (
        'foreign_net_twd','trust_net_twd','margin_financing_balance_twd'
      ) AND ($1).unit<>'TWD'
    )
    OR NOT EXISTS (
      SELECT 1
      FROM public.tw_trading_sessions_v3 session
      WHERE session.session_authority_id=($1).session_authority_id
        AND session.session_id=($1).session_id
        AND session.market::text=($1).exchange::text
        AND session.status='completed'
        AND session.provider::text=v_expected_owner
        AND session.recorded_at<=v_now
    )
    OR NOT EXISTS (
      SELECT 1
      FROM public.stock_instruments_v3 instrument
      WHERE instrument.stock_id=($1).stock_id
        AND instrument.exchange=($1).exchange
        AND instrument.instrument_type='common_stock'
        AND instrument.listing_status='active'
        AND instrument.source_timestamp<=($1).source_timestamp
        AND instrument.recorded_at<=v_now
        AND instrument.valid_from<=($1).source_timestamp
        AND (
          instrument.valid_to IS NULL
          OR ($1).source_timestamp<instrument.valid_to
        )
      ORDER BY instrument.recorded_at DESC,instrument.instrument_authority_id
      LIMIT 1
    )
  THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    concat_ws('|',($1).stock_id,($1).exchange,($1).session_id,
      ($1).session_authority_id,($1).fact_key,($1).provider),0
  ));
  SELECT observation.observation_id INTO v_existing
  FROM public.opportunity_stock_flow_observations_v3 observation
  WHERE observation.stock_id=($1).stock_id
    AND observation.exchange=($1).exchange
    AND observation.session_id=($1).session_id
    AND observation.session_authority_id=($1).session_authority_id
    AND observation.fact_key=($1).fact_key
    AND observation.value=($1).value
    AND observation.unit=($1).unit
    AND observation.provider=($1).provider
    AND observation.source_timestamp=($1).source_timestamp
    AND observation.collected_at=($1).collected_at
    AND observation.source_ref=($1).source_ref
    AND observation.provider_revision=($1).provider_revision
  ORDER BY observation.observation_id
  LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN QUERY
    SELECT observation.observation_id,observation.recorded_at
    FROM public.opportunity_stock_flow_observations_v3 observation
    WHERE observation.observation_id=v_existing;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count
  FROM (
    SELECT observation.observation_id
    FROM public.opportunity_stock_flow_observations_v3 observation
    WHERE observation.stock_id=($1).stock_id
      AND observation.exchange=($1).exchange
      AND observation.session_id=($1).session_id
      AND observation.session_authority_id=($1).session_authority_id
      AND observation.fact_key=($1).fact_key
      AND observation.provider=($1).provider
    ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
      observation.recorded_at DESC,observation.source_ref,observation.observation_id
    LIMIT 65
  ) bounded_revisions;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.opportunity_stock_flow_observations_v3(
    observation_id,stock_id,exchange,session_id,session_authority_id,fact_key,
    value,unit,provider,source_timestamp,collected_at,source_ref,
    provider_revision,recorded_at
  ) VALUES(
    v_id,($1).stock_id,($1).exchange,($1).session_id,($1).session_authority_id,
    ($1).fact_key,($1).value,($1).unit,($1).provider,($1).source_timestamp,
    ($1).collected_at,($1).source_ref,($1).provider_revision,v_now
  );
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,
    disposition,recorded_at
  ) VALUES(
    'append_stock_flow_observation_v3',$2,'stock_flow_observation',v_id,
    encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
      ($1).stock_id,($1).exchange,($1).session_id,($1).session_authority_id,
      ($1).fact_key,($1).value,($1).unit,($1).provider,
      ($1).source_timestamp,($1).collected_at,($1).source_ref,
      ($1).provider_revision
    )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex'),
    'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION append_financial_fact_v3(
  input financial_fact_input_v3,caller_principal uuid
) RETURNS TABLE(fact_id uuid,recorded_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_now timestamptz:=clock_timestamp();
  v_id uuid:=extensions.gen_random_uuid();
  v_existing uuid;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF ($1).filing_published_at>($1).source_timestamp
    OR ($1).source_timestamp>($1).collected_at
    OR ($1).collected_at>v_now
    OR char_length(btrim(($1).source_ref)) NOT BETWEEN 1 AND 120
    OR ($1).source_ref<>btrim(($1).source_ref)
    OR (
      (($1).provider IN ('mops','twse','tpex')
        AND ($1).authority_tier<>'official_filing')
      OR (($1).provider='finmind' AND ($1).authority_tier<>'finmind_mirror')
    )
    OR (
      ($1).fact_key IN (
        'monthly_revenue','quarterly_revenue','quarterly_gross_profit',
        'quarterly_operating_income','quarterly_net_income','quarterly_ebitda',
        'depreciation_amortization','net_debt'
      ) AND ($1).unit NOT IN ('TWD','TWD_thousand','TWD_million')
    )
    OR (
      ($1).fact_key='diluted_shares'
      AND ($1).unit NOT IN ('share','thousand_shares')
    )
    OR (
      ($1).fact_key IN (
        'quarterly_diluted_eps','book_value_per_share','broker_target_price'
      )
      AND ($1).unit<>'TWD_per_share'
    )
    OR (($1).fact_key='roe' AND ($1).unit<>'percentage_points')
    OR (
      ($1).fact_key IN (
        'pe_multiple','pb_multiple','ev_ebitda_multiple','ev_sales_multiple'
      ) AND ($1).unit<>'dimensionless'
    )
    OR (
      ($1).duration_kind='instant' AND ($1).period_start IS NOT NULL
    )
    OR (
      ($1).duration_kind<>'instant'
      AND (($1).period_start IS NULL OR ($1).period_start>($1).period_end)
    )
    OR (
      ($1).estimate_kind='reported'
      AND (
        ($1).estimate_horizon<>'reported_period'
        OR ($1).fact_key='broker_target_price'
      )
    )
    OR (
      ($1).estimate_kind='analyst_estimate'
      AND (
        ($1).estimate_horizon<>'next_twelve_months'
        OR ($1).fact_key NOT IN (
          'quarterly_diluted_eps','quarterly_ebitda','quarterly_revenue',
          'book_value_per_share'
        )
      )
    )
    OR (
      ($1).estimate_kind='broker_consensus'
      AND (
        ($1).estimate_horizon<>'target_12m'
        OR ($1).fact_key<>'broker_target_price'
      )
    )
    OR (
      ($1).estimate_kind<>'reported'
      AND NOT EXISTS (
        SELECT 1
        FROM public.source_publication_verifications_v3 verification
        WHERE verification.evidence_ref=($1).source_ref
          AND verification.recorded_at<=v_now
          AND verification.collected_at<=v_now
          AND verification.institution_identity IS NOT NULL
      )
    )
  THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws('|',
    ($1).stock_id,($1).fact_key,coalesce(($1).period_start::text,''),
    ($1).period_end,($1).duration_kind
  ),0));
  SELECT fact.fact_id INTO v_existing
  FROM public.opportunity_financial_facts_v3 fact
  WHERE fact.stock_id=($1).stock_id
    AND fact.fact_key=($1).fact_key
    AND fact.period_start IS NOT DISTINCT FROM ($1).period_start
    AND fact.period_end=($1).period_end
    AND fact.duration_kind=($1).duration_kind
    AND fact.value=($1).value
    AND fact.unit=($1).unit
    AND fact.provider=($1).provider
    AND fact.authority_tier=($1).authority_tier
    AND fact.estimate_kind=($1).estimate_kind
    AND fact.estimate_horizon=($1).estimate_horizon
    AND fact.filing_published_at=($1).filing_published_at
    AND fact.source_timestamp=($1).source_timestamp
    AND fact.collected_at=($1).collected_at
    AND fact.filing_restatement_id IS NOT DISTINCT FROM ($1).filing_restatement_id
    AND fact.source_ref=($1).source_ref
  ORDER BY fact.fact_id
  LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN QUERY SELECT v_existing,fact.recorded_at
    FROM public.opportunity_financial_facts_v3 fact
    WHERE fact.fact_id=v_existing;
    RETURN;
  END IF;
  INSERT INTO public.opportunity_financial_facts_v3(
    fact_id,stock_id,fact_key,period_start,period_end,duration_kind,value,unit,provider,authority_tier,
    estimate_kind,estimate_horizon,filing_published_at,source_timestamp,collected_at,
    filing_restatement_id,source_ref,recorded_at
  ) VALUES(v_id,($1).stock_id,($1).fact_key,($1).period_start,($1).period_end,($1).duration_kind,
    ($1).value,($1).unit,($1).provider,($1).authority_tier,
    ($1).estimate_kind,($1).estimate_horizon,($1).filing_published_at,
    ($1).source_timestamp,($1).collected_at,($1).filing_restatement_id,($1).source_ref,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,
    disposition,recorded_at
  ) VALUES(
    'append_financial_fact_v3',$2,'financial_fact',v_id,
    encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
      ($1).stock_id,($1).fact_key,($1).period_start,($1).period_end,
      ($1).duration_kind,($1).value,($1).unit,($1).provider,($1).authority_tier,
      ($1).estimate_kind,($1).estimate_horizon,
      ($1).filing_published_at,($1).source_timestamp,($1).collected_at,
      ($1).filing_restatement_id,($1).source_ref
    )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex'),
    'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION append_price_authority_v3(
  input price_authority_input_v3,caller_principal uuid
) RETURNS TABLE(kind price_authority_kind_v3,observation_id uuid,snapshot_id uuid,reported_pe_id uuid,dataset_hash text,recorded_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_now timestamptz:=clock_timestamp();
  v_observation uuid;
  v_snapshot uuid;
  v_reported_pe uuid;
  v_hash text;
  v_feed public.corporate_action_feed_evidence_input_v3;
  v_event public.corporate_action_event_input_v3;
  v_i integer:=0;
  v_count integer;
  v_expected_provider text;
  v_expected_feeds text[];
  v_expected_event_feed text;
  v_feed_rows jsonb;
  v_event_rows jsonb;
  v_source_row_preimage jsonb;
  v_snapshot_preimage jsonb;
  v_input_hash text;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF ($1).kind='raw_price' THEN
    IF ($1).raw_price IS NULL OR ($1).corporate_action_snapshot IS NOT NULL OR ($1).exchange_reported_pe IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
    v_expected_provider:=CASE (($1).raw_price).exchange
      WHEN 'TWSE' THEN 'twse' ELSE 'tpex' END;
    IF (($1).raw_price).provider::text NOT IN (v_expected_provider,'finmind')
      OR (($1).raw_price).source_timestamp>(($1).raw_price).collected_at
      OR (($1).raw_price).collected_at>v_now
      OR NOT EXISTS (
        SELECT 1
        FROM public.tw_trading_sessions_v3 session
        WHERE session.session_authority_id=(($1).raw_price).session_authority_id
          AND session.session_id=(($1).raw_price).session_id
          AND session.market::text=(($1).raw_price).exchange::text
          AND session.status='completed'
          AND session.provider::text=v_expected_provider
      )
    THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_price_authority'; END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      (($1).raw_price).stock_id::text||'|'||(($1).raw_price).exchange::text||'|'||
      (($1).raw_price).session_id::text||'|'||(($1).raw_price).session_authority_id::text||'|'||
      (($1).raw_price).provider::text,0
    ));
    SELECT observation.observation_id INTO v_observation
    FROM public.opportunity_price_observations_v3 observation
    WHERE observation.stock_id=(($1).raw_price).stock_id
      AND observation.exchange=(($1).raw_price).exchange
      AND observation.session_id=(($1).raw_price).session_id
      AND observation.session_authority_id=(($1).raw_price).session_authority_id
      AND observation.provider=(($1).raw_price).provider
      AND observation.raw_open=(($1).raw_price).raw_open
      AND observation.raw_high=(($1).raw_price).raw_high
      AND observation.raw_low=(($1).raw_price).raw_low
      AND observation.raw_close=(($1).raw_price).raw_close
      AND observation.volume=(($1).raw_price).volume
      AND observation.turnover_twd=(($1).raw_price).turnover_twd
      AND observation.source_timestamp=(($1).raw_price).source_timestamp
      AND observation.collected_at=(($1).raw_price).collected_at
      AND observation.source_ref=(($1).raw_price).source_ref
    ORDER BY observation.observation_id
    LIMIT 1;
    IF v_observation IS NOT NULL THEN
      RETURN QUERY SELECT ($1).kind,v_observation,NULL::uuid,NULL::uuid,NULL::text,v_now;
      RETURN;
    END IF;
    SELECT count(*) INTO v_count FROM (
      SELECT 1
      FROM public.opportunity_price_observations_v3 observation
      WHERE observation.stock_id=(($1).raw_price).stock_id
        AND observation.exchange=(($1).raw_price).exchange
        AND observation.session_id=(($1).raw_price).session_id
        AND observation.session_authority_id=(($1).raw_price).session_authority_id
        AND observation.provider=(($1).raw_price).provider
      ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
        observation.recorded_at DESC,observation.source_ref,observation.observation_id
      LIMIT 65
    ) bounded_revisions;
    IF v_count>=64 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
    v_observation:=extensions.gen_random_uuid();
    INSERT INTO public.opportunity_price_observations_v3(
      observation_id,stock_id,exchange,session_id,session_authority_id,raw_open,raw_high,raw_low,raw_close,
      volume,turnover_twd,provider,source_timestamp,collected_at,source_ref,recorded_at
    ) VALUES(v_observation,(($1).raw_price).stock_id,(($1).raw_price).exchange,(($1).raw_price).session_id,
      (($1).raw_price).session_authority_id,(($1).raw_price).raw_open,(($1).raw_price).raw_high,
      (($1).raw_price).raw_low,(($1).raw_price).raw_close,(($1).raw_price).volume,
      (($1).raw_price).turnover_twd,(($1).raw_price).provider,(($1).raw_price).source_timestamp,
      (($1).raw_price).collected_at,(($1).raw_price).source_ref,v_now);
    v_input_hash:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
      'raw-price-authority-v3.1',(($1).raw_price).stock_id,(($1).raw_price).exchange,
      (($1).raw_price).session_id,(($1).raw_price).session_authority_id,
      (($1).raw_price).raw_open,(($1).raw_price).raw_high,(($1).raw_price).raw_low,
      (($1).raw_price).raw_close,(($1).raw_price).volume,(($1).raw_price).turnover_twd,
      (($1).raw_price).provider,(($1).raw_price).source_timestamp,
      (($1).raw_price).collected_at,(($1).raw_price).source_ref
    )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_price_authority_v3',$2,'price_observation',v_observation,v_input_hash,'appended',v_now
    );
  ELSIF ($1).kind='corporate_action_snapshot' THEN
    IF ($1).corporate_action_snapshot IS NULL OR ($1).raw_price IS NOT NULL OR ($1).exchange_reported_pe IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
    v_expected_provider:=CASE (($1).corporate_action_snapshot).exchange
      WHEN 'TWSE' THEN 'twse' ELSE 'tpex' END;
    v_expected_feeds:=CASE (($1).corporate_action_snapshot).exchange
      WHEN 'TWSE' THEN ARRAY[
        'twse:twt49u:v1','twse:twtauu:v1','twse:twtb8u:v1'
      ] ELSE ARRAY[
        'tpex:exright-cal:v1','tpex:reduction-reference:v1','tpex:change-reference:v1'
      ] END;
    IF (($1).corporate_action_snapshot).corporate_action_version<>'tw-corporate-action-v3.1'
      OR (($1).corporate_action_snapshot).provider::text<>v_expected_provider
      OR (($1).corporate_action_snapshot).collected_at>v_now
      OR cardinality((($1).corporate_action_snapshot).feed_evidence)<>3
      OR cardinality((($1).corporate_action_snapshot).events)
        <> (($1).corporate_action_snapshot).declared_event_count
      OR NOT EXISTS (
        SELECT 1
        FROM public.tw_trading_sessions_v3 session
        WHERE session.session_authority_id=(($1).corporate_action_snapshot).session_authority_id
          AND session.session_id=(($1).corporate_action_snapshot).session_id
          AND session.market::text=(($1).corporate_action_snapshot).exchange::text
          AND session.status='completed'
          AND session.provider::text=v_expected_provider
      )
    THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_corporate_action_authority'; END IF;
    FOR v_i IN 1..3 LOOP
      v_feed:=(($1).corporate_action_snapshot).feed_evidence[v_i];
      IF v_feed.feed_identity<>v_expected_feeds[v_i] THEN
        RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_corporate_action_feed'; END IF;
    END LOOP;
    IF (
      SELECT coalesce(sum(feed.parsed_row_count),0)
      FROM unnest((($1).corporate_action_snapshot).feed_evidence)
        feed(feed_identity,response_byte_count,response_sha256,parsed_row_count)
    ) <> (($1).corporate_action_snapshot).declared_event_count THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_corporate_action_feed';
    END IF;
    v_i:=0;
    FOREACH v_event IN ARRAY (($1).corporate_action_snapshot).events LOOP
      v_i:=v_i+1;
      v_expected_event_feed:=CASE v_event.event_kind
        WHEN 'ex_right_dividend' THEN (v_expected_feeds)[1]
        WHEN 'capital_reduction' THEN (v_expected_feeds)[2]
        ELSE (v_expected_feeds)[3] END;
      IF v_event.feed_identity<>v_expected_event_feed
        OR (v_i>1 AND v_event.symbol<=
          ((($1).corporate_action_snapshot).events[v_i-1]).symbol)
      THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='authority_conflict'; END IF;
      v_source_row_preimage:=jsonb_build_array(
        'corporate-action-source-row-v3.1',
        (($1).corporate_action_snapshot).exchange,
        (($1).corporate_action_snapshot).session_id,
        v_event.symbol,v_event.event_kind,v_event.pre_action_reference_price,
        v_event.post_action_reference_price,v_event.feed_identity
      );
      IF v_event.source_row_ref<>encode(extensions.digest(convert_to(
        regexp_replace(v_source_row_preimage::text,', ', ',', 'g'),'utf8'
      ),'sha256'),'hex') THEN
        RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_source_row_ref'; END IF;
    END LOOP;
    SELECT jsonb_agg(jsonb_build_array(
      feed.feed_identity,feed.response_byte_count,feed.response_sha256,feed.parsed_row_count
    ) ORDER BY feed.ordinality)
    INTO v_feed_rows
    FROM unnest((($1).corporate_action_snapshot).feed_evidence)
      WITH ORDINALITY feed(feed_identity,response_byte_count,response_sha256,parsed_row_count,ordinality);
    SELECT coalesce(jsonb_agg(jsonb_build_array(
      event.symbol,event.event_kind,event.pre_action_reference_price,
      event.post_action_reference_price,event.feed_identity,event.source_row_ref
    ) ORDER BY event.ordinality),'[]'::jsonb)
    INTO v_event_rows
    FROM unnest((($1).corporate_action_snapshot).events)
      WITH ORDINALITY event(symbol,event_kind,pre_action_reference_price,
        post_action_reference_price,feed_identity,source_row_ref,ordinality);
    v_snapshot_preimage:=jsonb_build_array(
      'corporate-action-snapshot-v3.1',
      (($1).corporate_action_snapshot).exchange,
      (($1).corporate_action_snapshot).session_id,
      (($1).corporate_action_snapshot).session_authority_id,
      (($1).corporate_action_snapshot).corporate_action_version,
      (($1).corporate_action_snapshot).provider,
      (($1).corporate_action_snapshot).collected_at,
      v_feed_rows,v_event_rows
    );
    v_hash:=encode(extensions.digest(convert_to(
      regexp_replace(v_snapshot_preimage::text,', ', ',', 'g'),'utf8'
    ),'sha256'),'hex');
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      (($1).corporate_action_snapshot).exchange::text||'|'||
      (($1).corporate_action_snapshot).session_id::text||'|'||
      (($1).corporate_action_snapshot).session_authority_id::text||'|'||
      (($1).corporate_action_snapshot).corporate_action_version,0
    ));
    SELECT snapshot.snapshot_id INTO v_snapshot
    FROM public.opportunity_corporate_action_snapshots_v3 snapshot
    WHERE snapshot.exchange=(($1).corporate_action_snapshot).exchange
      AND snapshot.session_id=(($1).corporate_action_snapshot).session_id
      AND snapshot.session_authority_id=(($1).corporate_action_snapshot).session_authority_id
      AND snapshot.corporate_action_version=(($1).corporate_action_snapshot).corporate_action_version
      AND snapshot.dataset_hash=v_hash
    ORDER BY snapshot.snapshot_id
    LIMIT 1;
    IF v_snapshot IS NOT NULL THEN
      RETURN QUERY SELECT ($1).kind,NULL::uuid,v_snapshot,NULL::uuid,v_hash,v_now;
      RETURN;
    END IF;
    SELECT count(*) INTO v_count FROM (
      SELECT 1
      FROM public.opportunity_corporate_action_snapshots_v3 snapshot
      WHERE snapshot.exchange=(($1).corporate_action_snapshot).exchange
        AND snapshot.session_id=(($1).corporate_action_snapshot).session_id
        AND snapshot.session_authority_id=(($1).corporate_action_snapshot).session_authority_id
        AND snapshot.corporate_action_version=(($1).corporate_action_snapshot).corporate_action_version
      ORDER BY snapshot.collected_at DESC,snapshot.recorded_at DESC,snapshot.snapshot_id
      LIMIT 65
    ) bounded_revisions;
    IF v_count>=64 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
    v_snapshot:=extensions.gen_random_uuid();
    INSERT INTO public.opportunity_corporate_action_snapshots_v3(
      snapshot_id,exchange,session_id,session_authority_id,corporate_action_version,provider,
      collected_at,declared_event_count,dataset_hash,recorded_at
    ) VALUES(v_snapshot,(($1).corporate_action_snapshot).exchange,(($1).corporate_action_snapshot).session_id,
      (($1).corporate_action_snapshot).session_authority_id,(($1).corporate_action_snapshot).corporate_action_version,
      (($1).corporate_action_snapshot).provider,(($1).corporate_action_snapshot).collected_at,
      (($1).corporate_action_snapshot).declared_event_count,v_hash,v_now);
    v_i:=0;
    FOREACH v_feed IN ARRAY (($1).corporate_action_snapshot).feed_evidence LOOP
      INSERT INTO public.opportunity_corporate_action_feed_evidence_v3(
        snapshot_id,feed_ordinal,feed_identity,response_byte_count,response_sha256,parsed_row_count,recorded_at
      ) VALUES(v_snapshot,v_i,v_feed.feed_identity,v_feed.response_byte_count,v_feed.response_sha256,v_feed.parsed_row_count,v_now);
      v_i:=v_i+1;
    END LOOP;
    v_i:=0;
    FOREACH v_event IN ARRAY (($1).corporate_action_snapshot).events LOOP
      INSERT INTO public.opportunity_corporate_action_events_v3(
        snapshot_id,event_ordinal,symbol,event_kind,pre_action_reference_price,post_action_reference_price,
        feed_identity,source_row_ref,recorded_at
      ) VALUES(v_snapshot,v_i,v_event.symbol,v_event.event_kind,v_event.pre_action_reference_price,
        v_event.post_action_reference_price,v_event.feed_identity,v_event.source_row_ref,v_now);
      v_i:=v_i+1;
    END LOOP;
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_price_authority_v3',$2,'price_observation',v_snapshot,v_hash,'appended',v_now
    );
  ELSE
    IF ($1).exchange_reported_pe IS NULL OR ($1).raw_price IS NOT NULL OR ($1).corporate_action_snapshot IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';END IF;
    v_expected_provider:=CASE (($1).exchange_reported_pe).exchange WHEN 'TWSE' THEN 'twse' ELSE 'tpex' END;
    IF (($1).exchange_reported_pe).close<=0
      OR (($1).exchange_reported_pe).close='Infinity'::double precision
      OR (($1).exchange_reported_pe).reported_pe IN ('Infinity'::double precision,'-Infinity'::double precision)
      OR (($1).exchange_reported_pe).source_ref NOT LIKE v_expected_provider||':%'
      OR (($1).exchange_reported_pe).published_at>(($1).exchange_reported_pe).source_timestamp
      OR (($1).exchange_reported_pe).source_timestamp>(($1).exchange_reported_pe).collected_at
      OR (($1).exchange_reported_pe).collected_at>v_now
      OR NOT EXISTS (
        SELECT 1 FROM public.tw_trading_sessions_v3 session
        WHERE session.session_id=(($1).exchange_reported_pe).session_date
          AND session.market::text=(($1).exchange_reported_pe).exchange::text
          AND session.provider::text=v_expected_provider AND session.status='completed'
      ) THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_price_authority';END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      (($1).exchange_reported_pe).stock_id::text||'|'||(($1).exchange_reported_pe).exchange::text||'|'||
      (($1).exchange_reported_pe).session_date::text,0));
    SELECT reported.reported_pe_id INTO v_reported_pe FROM public.opportunity_exchange_reported_pe_v3 reported
    WHERE reported.stock_id=(($1).exchange_reported_pe).stock_id AND reported.exchange=(($1).exchange_reported_pe).exchange
      AND reported.session_date=(($1).exchange_reported_pe).session_date AND reported.close=(($1).exchange_reported_pe).close
      AND reported.reported_pe=(($1).exchange_reported_pe).reported_pe AND reported.published_at=(($1).exchange_reported_pe).published_at
      AND reported.source_timestamp=(($1).exchange_reported_pe).source_timestamp AND reported.collected_at=(($1).exchange_reported_pe).collected_at
      AND reported.source_ref=(($1).exchange_reported_pe).source_ref ORDER BY reported.reported_pe_id LIMIT 1;
    IF v_reported_pe IS NOT NULL THEN RETURN QUERY SELECT ($1).kind,NULL::uuid,NULL::uuid,v_reported_pe,NULL::text,v_now;RETURN;END IF;
    v_reported_pe:=extensions.gen_random_uuid();
    INSERT INTO public.opportunity_exchange_reported_pe_v3(reported_pe_id,stock_id,exchange,session_date,close,reported_pe,published_at,source_timestamp,collected_at,source_ref,recorded_at)
    VALUES(v_reported_pe,(($1).exchange_reported_pe).stock_id,(($1).exchange_reported_pe).exchange,(($1).exchange_reported_pe).session_date,
      (($1).exchange_reported_pe).close,(($1).exchange_reported_pe).reported_pe,(($1).exchange_reported_pe).published_at,
      (($1).exchange_reported_pe).source_timestamp,(($1).exchange_reported_pe).collected_at,(($1).exchange_reported_pe).source_ref,v_now);
    v_input_hash:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array('exchange-reported-pe-v3.1',
      (($1).exchange_reported_pe).stock_id,(($1).exchange_reported_pe).exchange,(($1).exchange_reported_pe).session_date,
      (($1).exchange_reported_pe).close,(($1).exchange_reported_pe).reported_pe,(($1).exchange_reported_pe).published_at,
      (($1).exchange_reported_pe).source_timestamp,(($1).exchange_reported_pe).collected_at,(($1).exchange_reported_pe).source_ref
    )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');
    INSERT INTO public.opportunity_rpc_audit_v3(function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at)
    VALUES('append_price_authority_v3',$2,'exchange_reported_pe',v_reported_pe,v_input_hash,'appended',v_now);
  END IF;
  RETURN QUERY SELECT ($1).kind,v_observation,v_snapshot,v_reported_pe,v_hash,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION append_source_identity_authority_v3(
  input source_identity_authority_input_v3,caller_principal uuid
) RETURNS TABLE(authority_id uuid,recorded_at timestamptz)
