LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'model_reviewer',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  INSERT INTO public.opportunity_assistive_artifact_registrations_v3(
    registration_id,artifact_ref,artifact_hash,artifact_kind,license_id,license_evidence_ref,training_cutoff,
    evaluation_manifest_id,comparison_baseline_key,oos_precision_at_20,oos_ndcg_at_20,
    oos_worst_decile_mae20_pct,status,supersedes_registration_id,registered_by_principal_id,
    registered_at,recorded_at
  ) VALUES(v_id,($1).artifact_ref,($1).artifact_hash,($1).artifact_kind,($1).license_id,
    ($1).license_evidence_ref,($1).training_cutoff,($1).evaluation_manifest_id,
    ($1).comparison_baseline_key,($1).oos_precision_at_20,($1).oos_ndcg_at_20,
    ($1).oos_worst_decile_mae20_pct,($1).status,($1).supersedes_registration_id,$2,v_now,v_now);
  RETURN QUERY SELECT v_id,v_now,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION get_link_audit_assignment_v3(
  requested_sample_manifest_id uuid,requested_sample_id text,requested_role internal_principal_role_v3,
  caller_principal uuid,nonce text,request_timestamp timestamptz
) RETURNS TABLE(
  disposition link_audit_assignment_disposition_v3,sample_manifest_id uuid,sample_id text,
  review_source_key source_key_v3,evidence_ref text,review_context text,
  review_mention_start_offset integer,review_mention_end_offset integer,normalized_token text,
  link_mode opportunity_link_mode_v3,engine_outcome opportunity_mention_outcome_v3,
  engine_reason opportunity_mention_reason_v3,engine_canonical_symbol text,review_evidence_hash text,
  assigned_label_role link_audit_label_role_v3,own_canonical_symbol text,own_no_link boolean,
  reviewer_one_canonical_symbol text,reviewer_one_no_link boolean,
  reviewer_two_canonical_symbol text,reviewer_two_no_link boolean
)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_now timestamptz:=clock_timestamp(); v_sample public.opportunity_link_audit_samples%ROWTYPE;
  v_one public.opportunity_link_audit_labels%ROWTYPE; v_two public.opportunity_link_audit_labels%ROWTYPE;
  v_own public.opportunity_link_audit_labels%ROWTYPE;
  v_adjudication public.opportunity_link_audit_labels%ROWTYPE;
  v_disposition public.link_audit_assignment_disposition_v3;
  v_role public.link_audit_label_role_v3;
BEGIN
  IF $3 NOT IN ('link_reviewer','link_adjudicator') THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_requested_role'; END IF;
  IF $5 !~ '^[0-9a-f]{16,64}$' OR abs(extract(epoch FROM (v_now-$6)))>300 THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected'; END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($4,$3,v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  SELECT * INTO v_sample FROM public.opportunity_link_audit_samples s WHERE s.sample_manifest_id=$1 AND s.sample_id=$2 FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='assignment_unavailable'; END IF;
  IF v_sample.review_evidence_hash<>encode(extensions.digest(convert_to(
    jsonb_build_array(
      'link-audit-review-evidence-v3.0',v_sample.run_id,v_sample.claim_id,
      v_sample.mention_ordinal,jsonb_build_array(
        v_sample.connector,v_sample.evidence_ref,v_sample.review_context,
        v_sample.review_mention_start_offset,v_sample.review_mention_end_offset,
        v_sample.normalized_token,v_sample.link_mode,v_sample.engine_outcome,
        v_sample.engine_reason,v_sample.engine_canonical_symbol
      )
    )::text,'utf8'
  ),'sha256'),'hex') THEN
    RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='assignment_unavailable';
  END IF;
  INSERT INTO public.internal_principal_nonces_v3(principal_id,nonce,request_timestamp,recorded_at) VALUES($4,$5,$6,v_now);
  SELECT * INTO v_one FROM public.opportunity_link_audit_labels l WHERE l.sample_manifest_id=$1 AND l.sample_id=$2 AND l.label_role='reviewer_1';
  SELECT * INTO v_two FROM public.opportunity_link_audit_labels l WHERE l.sample_manifest_id=$1 AND l.sample_id=$2 AND l.label_role='reviewer_2';
  SELECT * INTO v_adjudication FROM public.opportunity_link_audit_labels l
    WHERE l.sample_manifest_id=$1 AND l.sample_id=$2 AND l.label_role='adjudicator';
  SELECT * INTO v_own FROM public.opportunity_link_audit_labels l WHERE l.sample_manifest_id=$1 AND l.sample_id=$2 AND l.reviewer_principal_id=$4;
  IF $3='link_reviewer' THEN
    IF v_own.label_role='adjudicator' THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='principal_already_other_branch'; END IF;
    IF v_own.label_role IN ('reviewer_1','reviewer_2') THEN v_role:=v_own.label_role;v_disposition:='reviewer_existing_label';
    ELSIF v_one.label_role IS NULL THEN v_role:='reviewer_1';v_disposition:='reviewer_open_slot';
    ELSIF v_two.label_role IS NULL THEN v_role:='reviewer_2';v_disposition:='reviewer_open_slot';
    ELSE v_role:=NULL;v_disposition:='reviewer_slots_full'; END IF;
  ELSE
    IF v_own.label_role IN ('reviewer_1','reviewer_2') THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='principal_not_distinct'; END IF;
    IF v_adjudication.label_role='adjudicator' AND
      v_adjudication.reviewer_principal_id<>$4
    THEN v_role:=NULL;v_disposition:='adjudication_completed';
    ELSIF v_adjudication.label_role='adjudicator' THEN
      v_role:='adjudicator';v_own:=v_adjudication;
      v_disposition:='adjudicator_existing_label';
    ELSIF v_one.label_role IS NULL OR v_two.label_role IS NULL THEN v_disposition:='adjudication_pending';
    ELSIF (v_one.canonical_symbol,v_one.no_link) IS NOT DISTINCT FROM (v_two.canonical_symbol,v_two.no_link) THEN v_disposition:='adjudication_not_required';
    ELSE v_role:='adjudicator';v_disposition:='adjudicator_open'; END IF;
  END IF;
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,
    input_hash,disposition,recorded_at
  ) VALUES(
    'get_link_audit_assignment_v3',$4,'link_label',$1,
    encode(extensions.digest(convert_to(
      jsonb_build_array($1,$2,$3,$6)::text,'utf8'
    ),'sha256'),'hex'),
    v_disposition::text::public.opportunity_rpc_audit_disposition_v3,v_now
  );
  RETURN QUERY SELECT v_disposition,$1,$2,
    v_sample.connector::public.source_key_v3,v_sample.evidence_ref,v_sample.review_context,
    v_sample.review_mention_start_offset,v_sample.review_mention_end_offset,v_sample.normalized_token,
    v_sample.link_mode,v_sample.engine_outcome,v_sample.engine_reason,v_sample.engine_canonical_symbol,
    v_sample.review_evidence_hash,v_role,
    CASE WHEN v_disposition IN ('reviewer_existing_label','adjudicator_existing_label')
      THEN v_own.canonical_symbol ELSE NULL END,
    CASE WHEN v_disposition IN ('reviewer_existing_label','adjudicator_existing_label')
      THEN v_own.no_link ELSE NULL END,
    CASE WHEN v_disposition IN ('adjudicator_open','adjudicator_existing_label')
      THEN v_one.canonical_symbol ELSE NULL END,
    CASE WHEN v_disposition IN ('adjudicator_open','adjudicator_existing_label')
      THEN v_one.no_link ELSE NULL END,
    CASE WHEN v_disposition IN ('adjudicator_open','adjudicator_existing_label')
      THEN v_two.canonical_symbol ELSE NULL END,
    CASE WHEN v_disposition IN ('adjudicator_open','adjudicator_existing_label')
      THEN v_two.no_link ELSE NULL END;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected';
END
$fn$;

CREATE OR REPLACE FUNCTION submit_link_audit_label_v3(
  requested_sample_manifest_id uuid,requested_sample_id text,requested_role internal_principal_role_v3,
  requested_label_role link_audit_label_role_v3,canonical_symbol_or_null text,no_link boolean,
  caller_principal uuid,nonce text,request_timestamp timestamptz
) RETURNS TABLE(sample_manifest_id uuid,sample_id text,label_role link_audit_label_role_v3,label_hash text,submitted_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_now timestamptz:=clock_timestamp(); v_hash text;
  v_sample public.opportunity_link_audit_samples%ROWTYPE;
  v_one public.opportunity_link_audit_labels%ROWTYPE;
  v_two public.opportunity_link_audit_labels%ROWTYPE;
  v_own public.opportunity_link_audit_labels%ROWTYPE;
  v_assigned_role public.link_audit_label_role_v3;
BEGIN
  IF (($3='link_reviewer' AND $4 NOT IN ('reviewer_1','reviewer_2')) OR ($3='link_adjudicator' AND $4<>'adjudicator'))
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_label_role'; END IF;
  IF (($6 AND $5 IS NOT NULL) OR (NOT $6 AND ($5 IS NULL OR $5 !~ '^[0-9]{4}$')))
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_label_value'; END IF;
  IF $8 !~ '^[0-9a-f]{16,64}$' OR abs(extract(epoch FROM (v_now-$9)))>300 THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected'; END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($7,$3,v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  SELECT * INTO v_sample
  FROM public.opportunity_link_audit_samples sample
  WHERE sample.sample_manifest_id=$1 AND sample.sample_id=$2
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='assignment_unavailable';
  END IF;
  INSERT INTO public.internal_principal_nonces_v3(principal_id,nonce,request_timestamp,recorded_at) VALUES($7,$8,$9,v_now);
  SELECT * INTO v_one FROM public.opportunity_link_audit_labels label
  WHERE label.sample_manifest_id=$1 AND label.sample_id=$2
    AND label.label_role='reviewer_1';
  SELECT * INTO v_two FROM public.opportunity_link_audit_labels label
  WHERE label.sample_manifest_id=$1 AND label.sample_id=$2
    AND label.label_role='reviewer_2';
  SELECT * INTO v_own FROM public.opportunity_link_audit_labels label
  WHERE label.sample_manifest_id=$1 AND label.sample_id=$2
    AND label.reviewer_principal_id=$7;
  IF $3='link_reviewer' AND v_own.label_role='adjudicator' THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='principal_already_other_branch';
  ELSIF $3='link_adjudicator' AND v_own.label_role IN ('reviewer_1','reviewer_2') THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='principal_not_distinct';
  END IF;
  IF v_own.label_role IS NOT NULL THEN
    IF v_own.label_role<>$4 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_not_assigned';
    ELSIF v_own.canonical_symbol IS DISTINCT FROM $5
      OR v_own.no_link IS DISTINCT FROM $6
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_conflict';
    END IF;
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,
      input_hash,disposition,recorded_at
    ) VALUES(
      'submit_link_audit_label_v3',$7,'link_label',$1,
      encode(extensions.digest(convert_to(jsonb_build_array(
        $1,$2,$3,$4,$5,$6,$9
      )::text,'utf8'),'sha256'),'hex'),
      'idempotent',v_now
    );
    RETURN QUERY SELECT $1,$2,v_own.label_role,v_own.label_hash,v_own.submitted_at;
    RETURN;
  END IF;
  IF $3='link_reviewer' THEN
    v_assigned_role:=CASE
      WHEN v_one.label_role IS NULL THEN 'reviewer_1'::public.link_audit_label_role_v3
      WHEN v_two.label_role IS NULL THEN 'reviewer_2'::public.link_audit_label_role_v3
      ELSE NULL END;
    IF v_assigned_role IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_unavailable';
    END IF;
    IF $4<>v_assigned_role THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_not_assigned';
    END IF;
  ELSE
    IF v_one.label_role IS NULL OR v_two.label_role IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='reviewer_pair_incomplete';
    END IF;
    IF (v_one.canonical_symbol,v_one.no_link)
      IS NOT DISTINCT FROM (v_two.canonical_symbol,v_two.no_link)
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='adjudication_not_required';
    END IF;
    IF $4<>'adjudicator' THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_not_assigned';
    END IF;
  END IF;
  IF NOT $6 AND NOT EXISTS (
    SELECT 1
    FROM public.opportunity_run_manifest_inputs binding
    JOIN public.opportunity_manifests_v3 manifest
      ON manifest.manifest_id=binding.manifest_id
      AND manifest.manifest_kind='instrument_roster'
      AND manifest.status='complete'
    JOIN public.opportunity_manifest_rows_v3 row
      ON row.manifest_id=manifest.manifest_id
      AND row.section_key='rows'
      AND row.payload_json->>2=$5
      AND row.payload_json->>4='common_stock'
      AND row.payload_json->>5='active'
    WHERE binding.run_id=v_sample.run_id
      AND binding.input_role='instrument_roster'
      AND binding.ordinal=0
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_symbol_unavailable';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_array('link-audit-label-v3.0',$1,$2,$4,$5,$6,$7,v_now)::text,'utf8'),'sha256'),'hex');
  INSERT INTO public.opportunity_link_audit_labels(sample_manifest_id,sample_id,label_role,canonical_symbol,no_link,
    reviewer_principal_id,submitted_at,label_hash,recorded_at)
  VALUES($1,$2,$4,$5,$6,$7,v_now,v_hash,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,
    input_hash,disposition,recorded_at
  ) VALUES(
    'submit_link_audit_label_v3',$7,'link_label',$1,
    encode(extensions.digest(convert_to(jsonb_build_array(
      $1,$2,$3,$4,$5,$6,$9
    )::text,'utf8'),'sha256'),'hex'),
    'submitted',v_now
  );
  RETURN QUERY SELECT $1,$2,$4,v_hash,v_now;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_unavailable';
END
$fn$;

CREATE OR REPLACE FUNCTION begin_opportunity_run_v3(
  mode opportunity_mode_v3,
  run_purpose opportunity_run_purpose_v3,
  source_cutoff timestamptz,
  expected_taiwan_session_authority_hash text,
  caller_principal uuid
) RETURNS TABLE(disposition opportunity_begin_disposition_v3, run_id uuid, attempt_run_id uuid, attempt integer, status opportunity_run_status_v3)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_preparation text;
  v_comparison text;
  v_cutoff_text text;
  v_evaluation_lock text;
  v_input_run_ids jsonb := '[]'::jsonb;
  v_static_identity_members jsonb := $identity$[
    ["acceptanceVersion","1.44.6"],
    ["analysisRevisionContractVersion","stock-analysis-revision-v3.11.2"],
    ["authoritySupersessionContractVersion","authority-supersession-v3.2"],
    ["controlPlaneContractVersion","opportunity-control-v3.3"],
    ["dataContractVersion","source-led-opportunity-v3.6"],
    ["decisionContractVersion","opportunity-decisions-v3.3"],
    ["detailContractVersion","opportunity-detail-v3.3"],
    ["discoveryCorrectnessContractVersion","stock-discovery-v3.11.1"],
    ["entityLinkContractVersion","entity-link-v3.1"],
    ["evaluationContractVersion","source-led-eval-v3.7"],
    ["factorCorrectnessContractVersion","opportunity-factor-correctness-v3.11.6"],
    ["featureScoringContractVersion","opportunity-features-v3.2"],
    ["financialInputContractVersion","opportunity-financial-inputs-v3.3"],
    ["hybridProductVersion","hybrid-product-v3.2"],
    ["instrumentRosterContractVersion","tw-instrument-roster-v3.0"],
    ["internalPrincipalContractVersion","internal-principal-v3.8"],
    ["jobGraphContractVersion","opportunity-job-graph-v3.15"],
    ["legacyCompatibilityContractVersion","legacy-compatibility-v3.2"],
    ["manifestStorageContractVersion","opportunity-manifest-storage-v3.10"],
    ["marketContextContractVersion","market-context-v3.6"],
    ["moverAuditPriceContractVersion","mover-audit-price-v3.3"],
    ["portfolioContextContractVersion","research-basket-v3.0"],
    ["postgresTypeContractVersion","opportunity-postgres-types-v3.21"],
    ["priceProviderAllowlistHash","48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e"],
    ["providerFieldAllowlistHash","fe78e0f8c5b0846f822f72c6b2356cac35ed5c00dd0bcd06f9a75b7c5b21d3f7"],
    ["publisherVerificationPolicyHash","2c4746cb02d98d402ecd1d0d980c91632b8105ab9fd2aec198e7789da603abba"],
    ["runtimeContractVersion","opportunity-runtime-v3.17"],
    ["sectorBenchmarkContractVersion","sector-benchmark-v3.1"],
    ["sectorCycleContractVersion","sector-cycle-v3.0"],
    ["sectorReferenceContractVersion","sector-reference-v3.1"],
    ["sectorTaxonomyContractVersion","tw-sector-taxonomy-v3.0"],
    ["sourceAdapterContractVersion","source-adapter-v3.3"],
    ["sourceAdapterRegistryHash","a14d4753f221a43fb0422710e705ee00f529d9f31653a142211fe94596da80fe"],
    ["sourceDatasetContractVersion","source-dataset-v3.3"],
    ["sourceFunnelContractVersion","source-funnel-v3.0"],
    ["sourceFunnelPolicyHash","6893fb5f265edc10eea8222a560f9afdcc4342f72b1d7d39d5723ec0056bc105"],
    ["storageContractVersion","opportunity-storage-v3.24"],
    ["taxonomyMapHash","6b28d85903d7a410eef29386de011c71aa789dc0ce3231df38cb4e085181060c"],
    ["technicalDecisionContractVersion","opportunity-technical-decision-v3.11.1"],
    ["tradingCalendarContractVersion","tw-trading-calendar-v3.4"],
    ["valuationContractVersion","opportunity-valuation-v3.4"]
  ]$identity$::jsonb;
  v_upstream_run_id uuid;
  v_label_input_ids uuid[] := '{}'::uuid[];
  v_evaluation_enrich_ids uuid[] := '{}'::uuid[];
  v_evaluation_outcome_ids uuid[] := '{}'::uuid[];
  v_calendar_resolution jsonb;
  v_input_count integer;
  v_raw_score_count integer := 0;
  v_terminal_outcome_count integer := 0;
  v_attempt integer := 1;
  v_existing public.opportunity_runs%ROWTYPE;
  v_run uuid := extensions.gen_random_uuid();
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal(caller_principal,'opportunity_runner',v_now) THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable';
  END IF;
  IF source_cutoff<>date_trunc('second',source_cutoff)
    OR NOT (
      (mode IN ('source_scan','enrich_rank')
        AND run_purpose IN ('ad_hoc_shadow','production_shadow_daily','backtest_daily_primary'))
      OR (mode='label_outcomes' AND run_purpose='outcome_label_daily')
      OR (mode='shadow_evaluate' AND run_purpose='shadow_evaluation_daily')
    )
  THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
  END IF;
  IF source_cutoff > v_now THEN
    RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'future_source_cutoff';
  END IF;
  IF expected_taiwan_session_authority_hash IS NOT NULL THEN
    WITH bounded AS MATERIALIZED (
      SELECT market.market,session.*
      FROM (VALUES
        ('TWSE'::public.tw_market_v3),('TPEX'::public.tw_market_v3)
      ) market(market)
      CROSS JOIN LATERAL (
        SELECT retained.session_authority_id,retained.open_at,retained.close_at,
          retained.status,retained.source_timestamp,retained.collected_at,
          retained.source_ref,retained.recorded_at
        FROM public.tw_trading_sessions_v3 retained
        WHERE retained.session_id=(source_cutoff AT TIME ZONE 'Asia/Taipei')::date
          AND retained.market=market.market
          AND retained.source_timestamp<=source_cutoff
          AND retained.collected_at<=source_cutoff
          AND retained.recorded_at<=source_cutoff
        ORDER BY retained.recorded_at DESC,retained.session_authority_id
        LIMIT 1025
      ) session
    ), stream_stats AS MATERIALIZED (
      SELECT bounded.market,count(*) AS retained_count,
        max(bounded.recorded_at) AS greatest_recorded_at
      FROM bounded GROUP BY bounded.market
    ), greatest AS MATERIALIZED (
      SELECT bounded.*
      FROM bounded JOIN stream_stats USING(market)
      WHERE bounded.recorded_at=stream_stats.greatest_recorded_at
    ), resolved AS MATERIALIZED (
      SELECT greatest.market,max(stream_stats.retained_count) AS retained_count,
        count(DISTINCT jsonb_build_array(
          greatest.open_at,greatest.close_at,greatest.status,
          CASE greatest.market WHEN 'TWSE' THEN 'twse' ELSE 'tpex' END,
          greatest.source_timestamp,greatest.collected_at,greatest.source_ref
        )) AS semantic_count,
        (array_agg(greatest.session_authority_id
          ORDER BY greatest.session_authority_id))[1] AS session_authority_id,
        min(greatest.open_at) AS open_at,min(greatest.close_at) AS close_at,
        min(greatest.status::text) AS status,
        min(greatest.source_timestamp) AS source_timestamp,
        min(greatest.collected_at) AS collected_at,
        min(greatest.source_ref) AS source_ref,
        min(greatest.recorded_at) AS recorded_at
      FROM greatest JOIN stream_stats USING(market)
      GROUP BY greatest.market
    )
    SELECT jsonb_build_object(
      'overflow',coalesce(bool_or(resolved.retained_count>1024),false),
      'conflict',coalesce(bool_or(resolved.semantic_count<>1),false),
      'memberCount',count(*),
      'completedCount',count(*) FILTER (WHERE resolved.status='completed'),
      'scheduleCount',count(DISTINCT jsonb_build_array(
        resolved.open_at,resolved.close_at
      )),
      'canonicalCutoffMatches',
        source_cutoff=(
          ((source_cutoff AT TIME ZONE 'Asia/Taipei')::date)::timestamp
            + time '16:00:00'
        ) AT TIME ZONE 'Asia/Taipei',
      'hash',CASE WHEN count(*)=2
          AND count(*) FILTER (WHERE resolved.status='completed')=2
          AND count(DISTINCT jsonb_build_array(
            resolved.open_at,resolved.close_at
          ))=1
        THEN encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
          'tw-trading-session-v3.0',
          jsonb_build_array(
            (source_cutoff AT TIME ZONE 'Asia/Taipei')::date,
            min(resolved.open_at),min(resolved.close_at),
            jsonb_build_array(
              (array_agg(
                resolved.session_authority_id ORDER BY resolved.session_authority_id
              ) FILTER (WHERE resolved.market='TWSE'))[1],
              min(resolved.source_timestamp) FILTER (WHERE resolved.market='TWSE'),
              min(resolved.collected_at) FILTER (WHERE resolved.market='TWSE'),
              min(resolved.source_ref) FILTER (WHERE resolved.market='TWSE'),
              min(resolved.recorded_at) FILTER (WHERE resolved.market='TWSE')
            ),
            jsonb_build_array(
              (array_agg(
                resolved.session_authority_id ORDER BY resolved.session_authority_id
              ) FILTER (WHERE resolved.market='TPEX'))[1],
              min(resolved.source_timestamp) FILTER (WHERE resolved.market='TPEX'),
              min(resolved.collected_at) FILTER (WHERE resolved.market='TPEX'),
              min(resolved.source_ref) FILTER (WHERE resolved.market='TPEX'),
              min(resolved.recorded_at) FILTER (WHERE resolved.market='TPEX')
            )
          )
        )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex')
        ELSE NULL END
    ) INTO v_calendar_resolution
    FROM resolved;
    IF coalesce((v_calendar_resolution->>'overflow')::boolean,false) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    ELSIF coalesce((v_calendar_resolution->>'conflict')::boolean,false) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='authority_revision_conflict';
    ELSIF NOT coalesce((v_calendar_resolution->>'canonicalCutoffMatches')::boolean,false)
      OR v_calendar_resolution->>'hash' IS DISTINCT FROM expected_taiwan_session_authority_hash
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='calendar_authority_mismatch';
    END IF;
  END IF;
  v_cutoff_text := to_char(source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
  v_evaluation_lock := CASE WHEN run_purpose='ad_hoc_shadow' THEN NULL
    ELSE encode(extensions.digest(convert_to('source-led-eval-v3.7','utf8'),'sha256'),'hex') END;
  v_comparison := encode(extensions.digest(convert_to(regexp_replace(
    jsonb_build_array(
      'opportunity-comparison-contract-v3.0',
      jsonb_build_array('staticIdentityMembers',v_static_identity_members)
    )::text, ', ', ',', 'g'
  ),'utf8'),'sha256'),'hex');
  IF v_comparison<>'ebaa6dbdaa7dd55bb261187008f51e930919e7c0cfe07732d531e01267e67c41'
    OR jsonb_array_length(v_static_identity_members)<>41
  THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(regexp_replace(jsonb_build_array(
    'opportunity-begin-lineage-v3.0',mode::text,run_purpose::text,v_cutoff_text
  )::text, ', ', ',', 'g'),0));
  IF mode='enrich_rank' THEN
    SELECT count(*) INTO v_input_count
    FROM public.opportunity_runs r
    WHERE r.mode='source_scan' AND r.run_purpose=$2
      AND r.source_cutoff=$3 AND r.status='success'
      AND r.comparison_contract_key=v_comparison
      AND r.evaluation_dataset_lock_hash IS NOT DISTINCT FROM v_evaluation_lock;
    IF v_input_count=0 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='missing_source_run';
    ELSIF v_input_count>1 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='multiple_source_runs';
    END IF;
    SELECT r.run_id INTO STRICT v_upstream_run_id
    FROM public.opportunity_runs r
    WHERE r.mode='source_scan' AND r.run_purpose=$2
      AND r.source_cutoff=$3 AND r.status='success'
      AND r.comparison_contract_key=v_comparison
      AND r.evaluation_dataset_lock_hash IS NOT DISTINCT FROM v_evaluation_lock;
    v_input_run_ids:=jsonb_build_array(v_upstream_run_id::text);
  ELSIF mode='label_outcomes' THEN
    WITH recent_sessions AS (
      SELECT session_id
      FROM public.opportunity_effective_taiwan_sessions_v3
      WHERE canonical_cutoff<=$3
      ORDER BY session_id DESC
      LIMIT 252
    ), raw_scores AS (
      SELECT r.run_id,r.trading_date,s.score_snapshot_id,s.horizon
      FROM public.opportunity_runs r
      JOIN recent_sessions session ON session.session_id=r.trading_date
      JOIN public.opportunity_score_snapshots s ON s.run_id=r.run_id
      WHERE r.mode='enrich_rank'
        AND r.run_purpose IN ('production_shadow_daily','backtest_daily_primary')
        AND r.status='success'
        AND r.terminal_at<=$3
        AND r.source_cutoff<=$3
        AND r.comparison_contract_key=v_comparison
        AND r.evaluation_dataset_lock_hash=v_evaluation_lock
      ORDER BY r.trading_date,r.run_purpose,r.run_id,s.score_snapshot_id,s.horizon
      LIMIT 30241
    )
    SELECT count(*) INTO v_raw_score_count FROM raw_scores;
    IF v_raw_score_count>30240 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    WITH recent_sessions AS (
      SELECT session_id
      FROM public.opportunity_effective_taiwan_sessions_v3
      WHERE canonical_cutoff<=$3
      ORDER BY session_id DESC
      LIMIT 252
    ), raw_scores AS (
      SELECT r.run_id,r.trading_date,s.score_snapshot_id,s.horizon
      FROM public.opportunity_runs r
      JOIN recent_sessions session ON session.session_id=r.trading_date
      JOIN public.opportunity_score_snapshots s ON s.run_id=r.run_id
      WHERE r.mode='enrich_rank'
        AND r.run_purpose IN ('production_shadow_daily','backtest_daily_primary')
        AND r.status='success'
        AND r.terminal_at<=$3
        AND r.source_cutoff<=$3
        AND r.comparison_contract_key=v_comparison
        AND r.evaluation_dataset_lock_hash=v_evaluation_lock
      ORDER BY r.trading_date,r.run_purpose,r.run_id,s.score_snapshot_id,s.horizon
      LIMIT 30241
    ), terminal_rows AS (
      SELECT raw.run_id,raw.score_snapshot_id,maturity.maturity_horizon
      FROM raw_scores raw
      CROSS JOIN (VALUES
        ('session_20'::public.opportunity_outcome_maturity_v3,20),
        ('session_60'::public.opportunity_outcome_maturity_v3,60),
        ('session_120'::public.opportunity_outcome_maturity_v3,120),
        ('session_250'::public.opportunity_outcome_maturity_v3,250)
      ) maturity(maturity_horizon,session_count)
      WHERE maturity.session_count<=(
        SELECT count(*) FROM recent_sessions session
        WHERE session.session_id>raw.trading_date
      )
        AND NOT EXISTS (
          SELECT 1 FROM public.opportunity_outcomes outcome
          WHERE outcome.score_snapshot_id=raw.score_snapshot_id
            AND outcome.maturity_horizon=maturity.maturity_horizon
        )
      ORDER BY raw.run_id,raw.score_snapshot_id,maturity.session_count
      LIMIT 20001
    )
    SELECT count(*),coalesce(array_agg(DISTINCT terminal_rows.run_id ORDER BY terminal_rows.run_id),'{}'::uuid[])
      INTO v_terminal_outcome_count,v_label_input_ids
    FROM terminal_rows;
    IF v_terminal_outcome_count>20000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    SELECT coalesce(jsonb_agg(input_id::text ORDER BY input_id),'[]'::jsonb)
      INTO v_input_run_ids
    FROM unnest(v_label_input_ids) input_id;
  ELSIF mode='shadow_evaluate' THEN
    IF (
      SELECT count(*) FROM public.opportunity_effective_taiwan_sessions_v3
      WHERE canonical_cutoff<=$3
    ) < 252 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='provider_unavailable';
    END IF;
    IF EXISTS (
      WITH recent_sessions AS (
        SELECT session_id
        FROM public.opportunity_effective_taiwan_sessions_v3
        WHERE canonical_cutoff<=$3
        ORDER BY session_id DESC
        LIMIT 252
      )
      SELECT 1
      FROM public.opportunity_runs r
      JOIN recent_sessions session ON session.session_id=r.trading_date
      WHERE r.mode='enrich_rank'
        AND r.run_purpose IN ('production_shadow_daily','backtest_daily_primary')
        AND r.status='success'
        AND r.terminal_at<=$3
        AND r.source_cutoff<=$3
        AND r.comparison_contract_key=v_comparison
        AND r.evaluation_dataset_lock_hash=v_evaluation_lock
      GROUP BY r.run_purpose,r.trading_date
      HAVING count(*)>1
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    SELECT coalesce(array_agg(candidate.run_id ORDER BY candidate.run_id),'{}'::uuid[])
      INTO v_evaluation_enrich_ids
    FROM (
      WITH recent_sessions AS (
        SELECT session_id
        FROM public.opportunity_effective_taiwan_sessions_v3
        WHERE canonical_cutoff<=$3
        ORDER BY session_id DESC
        LIMIT 252
      )
      SELECT r.run_id
      FROM public.opportunity_runs r
      JOIN recent_sessions session ON session.session_id=r.trading_date
      WHERE r.mode='enrich_rank'
        AND r.run_purpose IN ('production_shadow_daily','backtest_daily_primary')
        AND r.status='success'
        AND r.terminal_at<=$3
        AND r.source_cutoff<=$3
        AND r.comparison_contract_key=v_comparison
        AND r.evaluation_dataset_lock_hash=v_evaluation_lock
      ORDER BY r.trading_date DESC,r.run_purpose,r.run_id
      LIMIT 505
    ) candidate;
    IF cardinality(v_evaluation_enrich_ids)>504 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    SELECT coalesce(array_agg(candidate.run_id ORDER BY candidate.run_id),'{}'::uuid[])
      INTO v_evaluation_outcome_ids
    FROM (
      SELECT r.run_id
      FROM public.opportunity_runs r
      WHERE r.mode='label_outcomes'
        AND r.run_purpose='outcome_label_daily'
        AND r.status='success'
        AND r.terminal_at<=$3
        AND r.source_cutoff<=$3
        AND r.comparison_contract_key=v_comparison
        AND r.evaluation_dataset_lock_hash=v_evaluation_lock
      ORDER BY r.source_cutoff DESC,r.run_id
      LIMIT 253
    ) candidate;
    IF cardinality(v_evaluation_outcome_ids)>252 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    SELECT coalesce(jsonb_agg(input_id::text ORDER BY input_id),'[]'::jsonb)
      INTO v_input_run_ids
    FROM unnest(array_cat(v_evaluation_enrich_ids,v_evaluation_outcome_ids)) input_id;
  END IF;
  v_preparation := encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
    'opportunity-preparation-v3.0',
    jsonb_build_array('mode',mode::text),
    jsonb_build_array('runPurpose',run_purpose::text),
    jsonb_build_array('sourceCutoff',v_cutoff_text),
    jsonb_build_array('inputRunIds',v_input_run_ids),
    jsonb_build_array('comparisonContractKey',v_comparison),
    jsonb_build_array('evaluationDatasetLockHash',v_evaluation_lock),
    jsonb_build_array('staticIdentityMembers',v_static_identity_members)
  )::text, ', ', ',', 'g'), 'utf8'), 'sha256'), 'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(v_preparation,0));
  SELECT r.* INTO v_existing FROM public.opportunity_runs r
    WHERE r.preparation_key = v_preparation AND r.status IN ('preparing','running','success')
    ORDER BY r.created_at, r.run_id LIMIT 1;
  IF FOUND THEN
    RETURN QUERY SELECT
      CASE WHEN v_existing.status = 'success' THEN 'existing_success'::public.opportunity_begin_disposition_v3 ELSE 'existing_active'::public.opportunity_begin_disposition_v3 END,
      v_existing.run_id, v_existing.run_id, v_existing.attempt, v_existing.status;
    RETURN;
  END IF;
  SELECT coalesce(max(r.attempt),0)+1 INTO v_attempt
  FROM public.opportunity_runs r
  WHERE r.preparation_key=v_preparation;
  IF v_attempt NOT BETWEEN 1 AND 5 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
  END IF;
  INSERT INTO public.opportunity_runs (
    run_id, preparation_key, attempt, mode, run_purpose, source_cutoff,
    comparison_contract_key, evaluation_dataset_lock_hash, upstream_run_id, status
  ) VALUES (
    v_run, v_preparation, v_attempt, mode, run_purpose, source_cutoff,
    v_comparison,v_evaluation_lock,v_upstream_run_id,
    'preparing'
  );
  IF v_upstream_run_id IS NOT NULL THEN
    INSERT INTO public.opportunity_run_inputs(run_id,input_run_id,input_role)
    VALUES(v_run,v_upstream_run_id,'upstream_source_scan');
    INSERT INTO public.opportunity_run_manifest_inputs(run_id,manifest_id,input_role,ordinal)
    SELECT v_run,m.manifest_id,m.input_role,m.ordinal
    FROM public.opportunity_run_manifest_inputs m
    JOIN public.opportunity_manifests_v3 manifest ON manifest.manifest_id=m.manifest_id
    WHERE m.run_id=v_upstream_run_id
      AND m.input_role IN (
        'source_identity_allowlist','publisher_verification_allowlist','instrument_roster',
        'alias_authority','taxonomy_assignment','source_dataset'
      )
      AND m.ordinal=0 AND manifest.status='complete';
    IF (SELECT count(*) FROM public.opportunity_run_manifest_inputs m
        WHERE m.run_id=v_run AND m.input_role IN (
          'source_identity_allowlist','publisher_verification_allowlist','instrument_roster',
          'alias_authority','taxonomy_assignment','source_dataset'
        ))<>6
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
  END IF;
  IF mode='label_outcomes' THEN
    INSERT INTO public.opportunity_run_inputs(run_id,input_run_id,input_role)
    SELECT v_run,input_id,'outcome_enrich'::public.opportunity_run_input_role_v3
    FROM unnest(v_label_input_ids) input_id
    ORDER BY input_id;
  ELSIF mode='shadow_evaluate' THEN
    INSERT INTO public.opportunity_run_inputs(run_id,input_run_id,input_role)
    SELECT v_run,input_id,'evaluation_enrich'::public.opportunity_run_input_role_v3
    FROM unnest(v_evaluation_enrich_ids) input_id
    ORDER BY input_id;
    INSERT INTO public.opportunity_run_inputs(run_id,input_run_id,input_role)
    SELECT v_run,input_id,'evaluation_outcome'::public.opportunity_run_input_role_v3
    FROM unnest(v_evaluation_outcome_ids) input_id
    ORDER BY input_id;
  END IF;
  PERFORM public.enqueue_next_opportunity_job_v3_internal(v_run,NULL);
  RETURN QUERY SELECT 'created'::public.opportunity_begin_disposition_v3, v_run, v_run, v_attempt, 'preparing'::public.opportunity_run_status_v3;
END
$fn$;

CREATE OR REPLACE FUNCTION claim_opportunity_job_v3(run_id uuid,worker_principal uuid)
RETURNS TABLE(job_id uuid,stage opportunity_job_stage_v3,shard_key text,
  input_hash text,owner_token text,lease_expires_at timestamptz,
  payload_kind opportunity_job_payload_kind_v3,payload_canonical bytea,payload_json jsonb,payload_hash text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_job public.opportunity_run_jobs_v3%ROWTYPE;
  v_token text;
  v_claimed_at timestamptz := clock_timestamp();
  v_expires timestamptz := v_claimed_at + interval '90 seconds';
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_claimed_at) THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable';
  END IF;
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3
    WHERE opportunity_run_jobs_v3.run_id=$1 AND status IN ('queued','retryable') AND attempt < 5
    ORDER BY created_at, job_id FOR UPDATE SKIP LOCKED LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  UPDATE public.opportunity_run_jobs_v3 SET
    status='leased', attempt=attempt+1, owner_token_hash=encode(extensions.digest(convert_to(v_token,'utf8'),'sha256'),'hex'),
    attempt_started_at=v_claimed_at, heartbeat_at=v_claimed_at, lease_expires_at=v_expires
  WHERE opportunity_run_jobs_v3.job_id=v_job.job_id;
  RETURN QUERY SELECT v_job.job_id,v_job.stage,v_job.shard_key,v_job.input_hash,v_token,
    v_expires,p.payload_kind,p.payload_canonical,p.payload_json,p.payload_hash
    FROM public.opportunity_job_payloads_v3 p WHERE p.job_id=v_job.job_id;
END
$fn$;

CREATE OR REPLACE FUNCTION fail_opportunity_job_v3(
  job_id uuid, owner_token text, failure_code opportunity_failure_code_v3
) RETURNS TABLE(status opportunity_job_status_v3)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_attempt integer; v_run_id uuid; v_status public.opportunity_job_status_v3;
BEGIN
  UPDATE public.opportunity_run_jobs_v3 SET
    status=CASE WHEN $3 IN ('provider_unavailable','v3_service_role_unavailable') AND attempt < 5
      THEN 'retryable'::public.opportunity_job_status_v3 ELSE 'failed'::public.opportunity_job_status_v3 END,
    failure_code=$3, terminal_at=CASE WHEN attempt >= 5 OR $3 NOT IN ('provider_unavailable','v3_service_role_unavailable') THEN clock_timestamp() END,
    owner_token_hash=NULL, lease_expires_at=NULL, heartbeat_at=NULL
  WHERE opportunity_run_jobs_v3.job_id=$1 AND status='leased'
    AND owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
    AND lease_expires_at>=clock_timestamp()
  RETURNING attempt,run_id,status INTO v_attempt,v_run_id,v_status;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='data_integrity_failure'; END IF;
  IF v_status='failed' THEN
    UPDATE public.opportunity_runs
    SET status='failed',failure_code=$3,terminal_at=clock_timestamp()
    WHERE run_id=v_run_id AND status IN ('preparing','running');
  END IF;
  RETURN QUERY SELECT j.status FROM public.opportunity_run_jobs_v3 j WHERE j.job_id=$1;
END
$fn$;

CREATE OR REPLACE FUNCTION stage_opportunity_job_output_v3(
  job_id uuid,owner_token text,output_kind opportunity_job_output_kind_v3,
  output_canonical bytea,output_json jsonb,output_hash text,counts opportunity_job_counts_v3
) RETURNS TABLE(status opportunity_staging_status_v3,staged_hash text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_attempt integer;
  v_job public.opportunity_run_jobs_v3%ROWTYPE;
  v_payload public.opportunity_job_payloads_v3%ROWTYPE;
  v_expected_kind public.opportunity_job_output_kind_v3;
  v_decoded_output jsonb;
  v_candidate jsonb; v_decision jsonb; v_reason text; v_action text;
  v_reason_index integer; v_prior_reason_index integer; v_cutoff_text text;
BEGIN
  SELECT j.* INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased'
    AND j.lease_expires_at >= clock_timestamp()
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  v_attempt := v_job.attempt;
  SELECT p.* INTO STRICT v_payload FROM public.opportunity_job_payloads_v3 p
  WHERE p.job_id=$1 AND p.run_id=v_job.run_id;
  v_expected_kind := CASE v_payload.payload_kind
    WHEN 'source_parse_batch' THEN 'source_parse_batch'::public.opportunity_job_output_kind_v3
    WHEN 'source_connector_summary' THEN 'source_connector_summary'::public.opportunity_job_output_kind_v3
    WHEN 'market_context_snapshot' THEN 'market_context_snapshot'::public.opportunity_job_output_kind_v3
    WHEN 'shallow_candidate_batch' THEN 'shallow_candidate_batch'::public.opportunity_job_output_kind_v3
    WHEN 'sector_cycle_batch' THEN 'sector_cycle_batch'::public.opportunity_job_output_kind_v3
    WHEN 'deep_candidate_batch' THEN 'deep_candidate_batch'::public.opportunity_job_output_kind_v3
    WHEN 'portfolio_allocation_batch' THEN 'portfolio_allocation_batch'::public.opportunity_job_output_kind_v3
    WHEN 'projection_bundle' THEN 'projection_bundle'::public.opportunity_job_output_kind_v3
    WHEN 'outcome_batch' THEN 'outcome_batch'::public.opportunity_job_output_kind_v3
    WHEN 'evaluation_bundle' THEN 'evaluation_bundle'::public.opportunity_job_output_kind_v3
    ELSE NULL
  END;
  BEGIN
    v_decoded_output := convert_from($4,'utf8')::jsonb;
  EXCEPTION WHEN invalid_text_representation OR character_not_in_repertoire THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch';
  END;
  IF octet_length($4)>3145728 OR $6 !~ '^[0-9a-f]{64}$'
    OR encode(extensions.digest($4,'sha256'),'hex')<>$6
    OR v_expected_kind IS NULL OR $3<>v_expected_kind
    OR jsonb_typeof($5)<>'array' OR jsonb_array_length($5)<>7
    OR $5->>0<>'opportunity-job-output-v3.3'
    OR $5->>1<>$3::text
    OR $5->>2<>v_job.run_id::text
    OR $5->>3<>v_job.job_id::text
    OR $5->>4<>v_job.input_hash
    OR jsonb_typeof($5->6)<>'array'
    OR jsonb_array_length($5->6)>6
    OR (SELECT count(*)<>count(DISTINCT warning)
        FROM jsonb_array_elements_text($5->6) warning)
    OR v_decoded_output<>$5
    OR octet_length(convert_to($5::text,'utf8'))>3145728
  THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch';
  END IF;
  IF $3='source_connector_summary' AND (
    jsonb_typeof($5->5)<>'object' OR (SELECT count(*) FROM jsonb_object_keys($5->5))<>13
    OR ($5->5->>'sourceKey')::public.source_key_v3
      IS DISTINCT FROM (v_payload.payload_json->5->>1)::public.source_key_v3
    OR (SELECT count(*) FROM jsonb_object_keys($5->5->'documentOutcomes'))<>5
    OR (SELECT count(*) FROM jsonb_object_keys($5->5->'claimOutcomes'))<>2
    OR (SELECT count(*) FROM jsonb_object_keys($5->5->'mentionOutcomes'))<>6
    OR (SELECT count(*) FROM jsonb_object_keys($5->5->'mentionReasonCounts'))<>12
    OR ($5->5->>'selectedDocuments')::integer
       + ($5->5->>'deferredDueScanCap')::integer
       <> ($5->5->>'eligibleDocuments')::integer
    OR ($5->5->'documentOutcomes'->>'duplicate_document')::integer
       + ($5->5->'documentOutcomes'->>'expired_document')::integer
       + ($5->5->'documentOutcomes'->>'parse_failure')::integer
       + ($5->5->'documentOutcomes'->>'processed_no_claim')::integer
       + ($5->5->'documentOutcomes'->>'processed_with_claims')::integer
       <> ($5->5->>'selectedDocuments')::integer
    OR ($7).connector_accounting_count<>1
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  IF ($7).warning_count<>jsonb_array_length($5->6) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  IF $3='source_parse_batch' AND (
    jsonb_typeof($5->5)<>'array' OR jsonb_array_length($5->5)<>3
    OR jsonb_typeof($5->5->0)<>'array' OR jsonb_array_length($5->5->0)<>1
    OR jsonb_typeof($5->5->0->0)<>'array' OR jsonb_array_length($5->5->0->0)<>9
    OR jsonb_typeof($5->5->1)<>'array' OR jsonb_array_length($5->5->1)>200
    OR jsonb_typeof($5->5->2)<>'array' OR jsonb_array_length($5->5->2)>1000
    OR (($5->5->0->0->>5) IN ('duplicate_document','parse_failure') AND (
      jsonb_array_length($5->5->1)<>0 OR jsonb_array_length($5->5->2)<>0
    ))
    OR ($7).source_document_count<>jsonb_array_length($5->5->0)
    OR ($7).claim_count<>jsonb_array_length($5->5->1)
    OR ($7).mention_count<>jsonb_array_length($5->5->2)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  ELSIF $3='market_context_snapshot' AND (
    jsonb_typeof($5->5)<>'object' OR ($7).market_snapshot_count<>1
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  ELSIF $3='shallow_candidate_batch' AND (
    jsonb_typeof($5->5)<>'array' OR jsonb_array_length($5->5) NOT BETWEEN 1 AND 5
    OR ($7).candidate_count<>jsonb_array_length($5->5)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  ELSIF $3='sector_cycle_batch' AND (
    jsonb_typeof($5->5)<>'array' OR jsonb_array_length($5->5) NOT BETWEEN 1 AND 5
    OR ($7).sector_snapshot_count<>jsonb_array_length($5->5)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  ELSIF $3='deep_candidate_batch' AND (
    jsonb_typeof($5->5)<>'array' OR jsonb_array_length($5->5) NOT BETWEEN 1 AND 5
    OR ($7).candidate_count<>jsonb_array_length($5->5)
    OR ($7).deep_success_candidate_count+($7).deep_failure_candidate_count<>($7).candidate_count
    OR ($7).score_snapshot_count<>0
    OR EXISTS (
      SELECT 1 FROM jsonb_array_elements($5->5) candidate(value)
      WHERE jsonb_typeof(candidate.value)<>'array' OR jsonb_array_length(candidate.value)<>15
        OR CASE WHEN candidate.value->14='null'::jsonb THEN
          candidate.value->2<>'true'::jsonb OR candidate.value->>3<>'direct_candidate'
          OR jsonb_typeof(candidate.value->7)<>'object'
          OR jsonb_typeof(candidate.value->8)<>'object'
          OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(candidate.value->8) key)
            <>ARRAY['blockReasons','confidence','decisionAuthority','entryTrigger','existingPositionAction',
              'existingReason','existingTargetExposurePct','initialPositionPct','invalidation',
              'maximumPositionPct','newPositionAction','primaryHorizon','publicationEligible']::text[]
          OR candidate.value->8->>'decisionAuthority'<>'research_only'
          OR candidate.value->8->'publicationEligible'<>'false'::jsonb
          OR candidate.value->8->'initialPositionPct'<>candidate.value->9
          OR candidate.value->8->'maximumPositionPct'<>candidate.value->10
          OR jsonb_typeof(candidate.value->11)<>'array' OR jsonb_array_length(candidate.value->11)<>3
          OR jsonb_typeof(candidate.value->12)<>'array' OR jsonb_array_length(candidate.value->12)=0
          OR jsonb_typeof(candidate.value->13)<>'object'
        ELSE
          candidate.value->6<>'null'::jsonb OR candidate.value->7<>'null'::jsonb
          OR candidate.value->8<>'null'::jsonb OR candidate.value->9<>'null'::jsonb
          OR candidate.value->10<>'null'::jsonb OR candidate.value->11<>'null'::jsonb
          OR candidate.value->12<>'null'::jsonb OR candidate.value->13<>'null'::jsonb
        END
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  ELSIF $3='portfolio_allocation_batch' AND (
    jsonb_typeof($5->5)<>'array' OR jsonb_array_length($5->5)>20
    OR ($7).candidate_count<>jsonb_array_length($5->5)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  ELSIF $3='projection_bundle' AND (
    jsonb_typeof($5->5)<>'array' OR jsonb_array_length($5->5)<>3
    OR jsonb_typeof($5->5->0)<>'array' OR jsonb_array_length($5->5->0)>60
    OR jsonb_typeof($5->5->2)<>'array' OR jsonb_array_length($5->5->2)>20
    OR ($7).candidate_count<>jsonb_array_length($5->5->0)
    OR ($7).public_projection_count<>1
    OR ($7).detail_projection_count<>jsonb_array_length($5->5->2)
    OR ($7).score_snapshot_count<>3*jsonb_array_length($5->5->2)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  ELSIF $3='outcome_batch' AND (
    jsonb_typeof($5->5)<>'array' OR jsonb_array_length($5->5) NOT BETWEEN 1 AND 200
    OR ($7).outcome_count<>jsonb_array_length($5->5)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  ELSIF $3='evaluation_bundle' AND (
    jsonb_typeof($5->5)<>'object'
    OR jsonb_typeof($5->5->'strategyRows')<>'array'
    OR jsonb_array_length($5->5->'strategyRows')<>3
    OR $5->5->'strategyRows'->0->>'strategy'<>'official_only'
    OR $5->5->'strategyRows'->1->>'strategy'<>'source_led'
    OR $5->5->'strategyRows'->2->>'strategy'<>'hybrid'
    OR ($7).evaluation_result_count<>1
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  IF $3 IN ('deep_candidate_batch','portfolio_allocation_batch') THEN
    SELECT to_char(run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
    INTO STRICT v_cutoff_text FROM public.opportunity_runs run WHERE run.run_id=v_job.run_id;
    FOR v_candidate IN SELECT value FROM jsonb_array_elements($5->5) LOOP
      IF $3='deep_candidate_batch' AND v_candidate->14<>'null'::jsonb THEN CONTINUE; END IF;
      v_decision:=CASE WHEN $3='deep_candidate_batch' THEN v_candidate->8 ELSE v_candidate->1 END;
      IF jsonb_typeof(v_decision)<>'object'
        OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v_decision) key)
          <>ARRAY['blockReasons','confidence','decisionAuthority','entryTrigger','existingPositionAction',
            'existingReason','existingTargetExposurePct','initialPositionPct','invalidation',
            'maximumPositionPct','newPositionAction','primaryHorizon','publicationEligible']::text[]
        OR v_decision->>'decisionAuthority'<>'research_only'
        OR v_decision->'publicationEligible'<>'false'::jsonb
        OR v_decision->>'existingPositionAction'<>'no_position'
        OR v_decision->>'existingReason'<>'portfolio_context_unavailable'
        OR v_decision->'existingTargetExposurePct'<>'null'::jsonb
        OR jsonb_typeof(v_decision->'initialPositionPct')<>'number'
        OR jsonb_typeof(v_decision->'maximumPositionPct')<>'number'
        OR (v_decision->>'initialPositionPct')::numeric NOT BETWEEN 0 AND 5
        OR (v_decision->>'maximumPositionPct')::numeric NOT BETWEEN 0 AND 10
        OR (v_decision->>'initialPositionPct')::numeric>(v_decision->>'maximumPositionPct')::numeric
        OR jsonb_typeof(v_decision->'confidence')<>'number'
        OR (v_decision->>'confidence')::numeric NOT BETWEEN 0 AND 1
        OR NOT (v_decision->'primaryHorizon'='null'::jsonb
          OR v_decision->>'primaryHorizon' IN ('momentum_5_20d','swing_20_60d'))
        OR jsonb_typeof(v_decision->'blockReasons')<>'array'
        OR jsonb_array_length(v_decision->'blockReasons')>5
        OR NOT (v_decision->'entryTrigger'='null'::jsonb OR (
          jsonb_typeof(v_decision->'entryTrigger')='string'
          AND btrim(v_decision->>'entryTrigger')<>''
          AND char_length(v_decision->>'entryTrigger')<=160))
        OR jsonb_typeof(v_decision->'invalidation')<>'object'
        OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v_decision->'invalidation') key)
          <>ARRAY['code','evidenceExpiresAt','stopPrice']::text[]
      THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      v_prior_reason_index:=0;
      FOR v_reason IN SELECT value FROM jsonb_array_elements_text(v_decision->'blockReasons') LOOP
        v_reason_index:=array_position(ARRAY[
          'data_integrity','market_risk_off','capacity_exhausted','invalid_exposure_input',
          'score_below_threshold','confidence_below_threshold','valuation_unavailable',
          'valuation_reward_risk','entry_data_unavailable','entry_invalidated','entry_unconfirmed',
          'bias_observe_only','quality_insufficient','no_eligible_method','missing_required_inputs',
          'insufficient_series','insufficient_multiple_reference','cross_check_unavailable',
          'missing_financial_manifest','stale_financial_inputs','conflicting_point_in_time_fact',
          'invalid_unit','missing_bridge_inputs','nonconsecutive_quarters','operating_bridge_mismatch',
          'pretax_bridge_mismatch','net_income_bridge_mismatch','share_count_conflict',
          'reported_eps_mismatch','tax_rate_outlier','capital_structure_conflict','non_finite_bridge',
          'negative_equity_value','invalid_capital_structure','non_finite_distribution',
          'distribution_ordering','unverified_base_upside','unverified_scenario_upside',
          'consensus_divergence','method_divergence']::text[],v_reason);
        IF v_reason_index IS NULL OR v_reason_index<=v_prior_reason_index THEN
          RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END IF;
        v_prior_reason_index:=v_reason_index;
      END LOOP;
      v_action:=v_decision->>'newPositionAction';
      IF v_action NOT IN ('avoid','valuation_review','wait_trigger','event_starter','starter_now') THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      ELSIF v_decision->'primaryHorizon'='null'::jsonb AND NOT (
        v_action='avoid' AND v_decision->'blockReasons'='["data_integrity"]'::jsonb
      ) THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      ELSIF v_action='event_starter' AND v_decision->>'primaryHorizon'<>'momentum_5_20d' THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      ELSIF v_action IN ('starter_now','event_starter') THEN
        IF (v_decision->>'initialPositionPct')::numeric<=0
          OR (v_decision->>'maximumPositionPct')::numeric<>10
          OR jsonb_array_length(v_decision->'blockReasons')<>0
          OR jsonb_typeof(v_decision->'entryTrigger')<>'string'
          OR v_decision->'invalidation'->>'code'<>'price_stop_or_evidence_expiry'
          OR jsonb_typeof(v_decision->'invalidation'->'stopPrice')<>'number'
          OR (v_decision->'invalidation'->>'stopPrice')::numeric<=0
          OR (v_decision->'invalidation'->>'evidenceExpiresAt')
            !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$'
          OR v_decision->'invalidation'->>'evidenceExpiresAt'<=v_cutoff_text
        THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      ELSIF v_action='wait_trigger' THEN
        IF v_decision->'initialPositionPct'<>'0'::jsonb OR v_decision->'maximumPositionPct'<>'0'::jsonb
          OR v_decision->'blockReasons'<>'["entry_unconfirmed"]'::jsonb
          OR jsonb_typeof(v_decision->'entryTrigger')<>'string'
          OR v_decision->'invalidation'->>'code'<>'evidence_expiry_only'
          OR v_decision->'invalidation'->'stopPrice'<>'null'::jsonb
          OR (v_decision->'invalidation'->>'evidenceExpiresAt')
            !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$'
          OR v_decision->'invalidation'->>'evidenceExpiresAt'<=v_cutoff_text
        THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      ELSE
        IF v_decision->'initialPositionPct'<>'0'::jsonb OR v_decision->'maximumPositionPct'<>'0'::jsonb
          OR v_decision->'entryTrigger'<>'null'::jsonb
          OR jsonb_array_length(v_decision->'blockReasons')=0
          OR v_decision->'invalidation'->>'code'<>'data_integrity_review'
          OR v_decision->'invalidation'->'stopPrice'<>'null'::jsonb
          OR v_decision->'invalidation'->'evidenceExpiresAt'<>'null'::jsonb
          OR (v_action='avoid' AND (
            jsonb_array_length(v_decision->'blockReasons')<>1
            OR v_decision->'blockReasons'->>0 NOT IN ('data_integrity','market_risk_off',
              'capacity_exhausted','invalid_exposure_input','score_below_threshold',
              'confidence_below_threshold','valuation_reward_risk','entry_data_unavailable',
              'entry_invalidated','entry_unconfirmed','bias_observe_only','quality_insufficient')
          ))
          OR (v_action='valuation_review' AND EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(v_decision->'blockReasons') reason(value)
            WHERE reason.value NOT IN ('valuation_unavailable','no_eligible_method','missing_required_inputs',
              'insufficient_series','insufficient_multiple_reference','cross_check_unavailable',
              'missing_financial_manifest','stale_financial_inputs','conflicting_point_in_time_fact',
              'invalid_unit','missing_bridge_inputs','nonconsecutive_quarters','operating_bridge_mismatch',
              'pretax_bridge_mismatch','net_income_bridge_mismatch','share_count_conflict',
              'reported_eps_mismatch','tax_rate_outlier','capital_structure_conflict','non_finite_bridge',
              'negative_equity_value','invalid_capital_structure','non_finite_distribution',
              'distribution_ordering','unverified_base_upside','unverified_scenario_upside',
              'consensus_divergence','method_divergence')))
          OR (v_action='valuation_review'
            AND v_decision->'blockReasons' ? 'valuation_unavailable'
            AND jsonb_array_length(v_decision->'blockReasons')<>1)
        THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      END IF;
      IF $3='deep_candidate_batch' AND (
        v_decision->'initialPositionPct'<>v_candidate->9
        OR v_decision->'maximumPositionPct'<>v_candidate->10
      ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
    END LOOP;
  END IF;
  INSERT INTO public.opportunity_job_staging_v3(
    job_id,attempt,output_kind,output_canonical,output_json,output_hash,output_counts
  ) VALUES($1,v_attempt,$3,$4,$5,$6,$7)
  ON CONFLICT ON CONSTRAINT opportunity_job_staging_v3_pkey DO NOTHING;
  RETURN QUERY SELECT 'staged'::public.opportunity_staging_status_v3,$6;
END
$fn$;

CREATE OR REPLACE FUNCTION create_opportunity_manifest_v3(
  job_id uuid,owner_token text,requested_manifest_id uuid,
  manifest_kind opportunity_manifest_kind_v3,contract_version text,
  source_cutoff timestamptz,header_canonical bytea,header_json jsonb
) RETURNS TABLE(status opportunity_manifest_status_v3,manifest_id uuid)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_job public.opportunity_run_jobs_v3%ROWTYPE; v_now timestamptz:=clock_timestamp(); v_hash text; v_logical text;
BEGIN
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased' AND j.stage IN ('authority_manifest','input_manifest_pages')
    AND j.lease_expires_at>=v_now
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  IF octet_length($7)>3145728 THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
  v_hash:=encode(extensions.digest($7,'sha256'),'hex');
  v_logical:=encode(extensions.digest(convert_to(jsonb_build_array(
    'opportunity-manifest-logical-v3.8',v_job.run_id,$3,$4,$5,$6,v_hash
  )::text,'utf8'),'sha256'),'hex');
  INSERT INTO public.opportunity_manifests_v3(
    manifest_id,manifest_kind,contract_version,source_cutoff,header_canonical,header_json,
    status,created_at,recorded_at
  ) VALUES($3,$4,$5,$6,$7,$8,'building',v_now,v_now)
  ON CONFLICT ON CONSTRAINT opportunity_manifests_v3_pkey DO NOTHING;
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_manifests_v3 m
    WHERE m.manifest_id=$3 AND m.manifest_kind=$4 AND m.contract_version=$5
      AND m.source_cutoff IS NOT DISTINCT FROM $6 AND m.header_canonical=$7
      AND m.header_json=$8 AND m.status='building'
  ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  UPDATE public.opportunity_run_jobs_v3 SET output_manifest_id=$3
  WHERE opportunity_run_jobs_v3.job_id=$1;
  UPDATE public.opportunity_run_jobs_v3 SET status='succeeded',output_kind='manifest_header',
    output_hash=v_hash,terminal_at=v_now,owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
  WHERE opportunity_run_jobs_v3.job_id=$1;
  PERFORM public.enqueue_next_opportunity_job_v3_internal(v_job.run_id,$1);
  RETURN QUERY SELECT 'building'::public.opportunity_manifest_status_v3,$3;
END
$fn$;

CREATE OR REPLACE FUNCTION append_opportunity_manifest_page_v3(
  job_id uuid,owner_token text,requested_manifest_id uuid,
  section_key opportunity_manifest_section_key_v3,
  page_ordinal integer,first_row_ordinal bigint,
  page_canonical bytea,page_json jsonb,requested_page_hash text,
  rows opportunity_manifest_row_input_v3[]
) RETURNS TABLE(status opportunity_manifest_page_status_v3,page_id uuid,row_count integer,page_hash text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_job public.opportunity_run_jobs_v3%ROWTYPE; v_manifest public.opportunity_manifests_v3%ROWTYPE;
  v_now timestamptz:=clock_timestamp(); v_page uuid; v_descriptor jsonb; v_row public.opportunity_manifest_row_input_v3;
  v_count integer:=COALESCE(cardinality($10),0); v_expected bigint:=$6;
  v_payload jsonb; v_read jsonb; v_index integer:=0; v_expected_identity text;
  v_next_native jsonb; v_next_hash text; v_next_identity text; v_next_terminal text;
  v_candidate_page jsonb; v_first_identity text; v_last_identity text;
  v_lookup_symbol text; v_lookup_session date; v_entry_session date;
BEGIN
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased' AND j.lease_expires_at>=v_now
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  SELECT * INTO v_manifest FROM public.opportunity_manifests_v3 m
  WHERE m.manifest_id=$3 AND m.status='building' FOR UPDATE;
  SELECT p.payload_json->5 INTO v_payload
  FROM public.opportunity_job_payloads_v3 p
  WHERE p.job_id=$1 AND p.run_id=v_job.run_id AND p.payload_kind='manifest_page';
  SELECT u.read_json->5 INTO v_read
  FROM public.opportunity_worker_read_units_v3 u
  WHERE u.job_id=$1 AND u.input_hash=v_job.input_hash;
  IF v_job.job_id IS NULL OR v_manifest.manifest_id IS NULL OR v_count<1 OR v_count>2000
    OR octet_length($7)>786432 OR $9!~'^[0-9a-f]{64}$'
    OR encode(extensions.digest($7,'sha256'),'hex')<>$9
    OR $7<>convert_to(regexp_replace($8::text, ', ', ',', 'g'),'utf8')
    OR v_payload IS NULL OR v_read IS NULL
    OR (v_payload->>1)::uuid<>$3
    OR (v_payload->>5)::public.opportunity_manifest_section_key_v3<>$4
    OR (v_payload->>6)::integer<>$5 OR (v_payload->>7)::bigint<>$6
    OR jsonb_typeof(v_read->1)<>'array'
    OR jsonb_array_length(v_read->1) NOT BETWEEN v_count AND v_count+1
    OR v_count>least(2000,jsonb_array_length(v_read->1))
    OR jsonb_typeof($8)<>'array' OR jsonb_array_length($8)<>8
    OR $8->>0<>'opportunity-manifest-page-v3.3'
    OR $8->>1<>v_manifest.manifest_kind::text OR $8->>2<>v_manifest.contract_version
    OR ($8->>3)::timestamptz IS DISTINCT FROM v_manifest.source_cutoff
    OR ($8->>4)::public.opportunity_manifest_section_key_v3<>$4
    OR ($8->>5)::integer<>$5 OR ($8->>6)::bigint<>$6
    OR jsonb_typeof($8->7)<>'array' OR jsonb_array_length($8->7)<>v_count
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  IF v_count<least(2000,jsonb_array_length(v_read->1)) THEN
    v_next_native:=v_read->1->v_count;
    v_next_hash:=encode(extensions.digest(
      convert_to(regexp_replace(v_next_native::text, ', ', ',', 'g'),'utf8'),'sha256'
    ),'hex');
    v_next_identity:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
      'opportunity-manifest-row-identity-v3.3',v_manifest.manifest_kind,$4,$6+v_count,v_next_hash
    )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex');
    v_next_terminal:=CASE
      WHEN v_next_native @> '["active"]'::jsonb THEN 'effective_active'
      WHEN v_next_native @> '["inactive"]'::jsonb OR v_next_native @> '["delisted"]'::jsonb
        THEN 'revoked_or_expired'
      ELSE NULL
    END;
    v_candidate_page:=jsonb_set(
      $8,
      '{7}',
      ($8->7)||jsonb_build_array(jsonb_build_array(
        $6+v_count,v_next_identity,v_next_terminal,v_next_native
      )),
      false
    );
    IF octet_length(convert_to(
      regexp_replace(v_candidate_page::text, ', ', ',', 'g'),'utf8'
    ))<=786432 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
  END IF;
  IF $5=0 THEN
    IF v_payload->8<>'null'::jsonb OR v_payload->9<>'null'::jsonb OR v_payload->10<>'null'::jsonb
      OR v_read->0<>'null'::jsonb
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  ELSE
    IF NOT EXISTS (
      SELECT 1
      FROM public.opportunity_manifest_pages_v3 prior
      WHERE prior.manifest_id=$3 AND prior.section_key=$4 AND prior.page_ordinal=$5-1
        AND prior.page_id=(v_payload->>8)::uuid
        AND prior.page_hash=v_payload->>9
        AND prior.last_identity=v_payload->>10
    ) OR v_read->0->>0<>v_payload->>8 OR v_read->0->>1<>v_payload->>9
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  END IF;
  v_descriptor:=public.derive_manifest_page_descriptor_v3_internal($3,$4,$5,$6);
  v_page:=(v_descriptor->>0)::uuid;
  v_first_identity:=($10[1]).identity_key;
  v_last_identity:=($10[v_count]).identity_key;
  IF v_manifest.manifest_kind='sector_benchmark' THEN
    SELECT (pair->>1)::date INTO v_entry_session
    FROM jsonb_array_elements(v_manifest.header_json) pair
    WHERE pair->>0='entrySession';
  END IF;
  INSERT INTO public.opportunity_manifest_pages_v3(
    page_id,manifest_id,section_key,page_ordinal,first_row_ordinal,row_count,
    first_identity,last_identity,page_canonical,page_json,page_hash,recorded_at
  ) VALUES(
    v_page,$3,$4,$5,$6,v_count,v_first_identity,v_last_identity,$7,$8,$9,v_now
  );
  FOREACH v_row IN ARRAY $10 LOOP
    v_expected_identity:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
      'opportunity-manifest-row-identity-v3.3',v_manifest.manifest_kind,$4,v_expected,v_row.payload_hash
    )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex');
    IF v_row.row_ordinal<>v_expected OR v_row.payload_hash!~'^[0-9a-f]{64}$'
      OR encode(extensions.digest(v_row.payload_canonical,'sha256'),'hex')<>v_row.payload_hash
      OR v_row.payload_canonical<>convert_to(regexp_replace(v_row.payload_json::text, ', ', ',', 'g'),'utf8')
      OR v_row.payload_json IS DISTINCT FROM v_read->1->v_index
      OR v_row.identity_key<>v_expected_identity
      OR $8->7->v_index IS DISTINCT FROM jsonb_build_array(
        v_row.row_ordinal,v_row.identity_key,v_row.terminal_code,v_row.payload_json
      )
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch'; END IF;
    v_lookup_symbol:=NULL;
    v_lookup_session:=NULL;
    IF v_manifest.manifest_kind='sector_benchmark' AND $4='entry_rows' THEN
      v_lookup_symbol:=v_row.payload_json->>0;
      v_lookup_session:=v_entry_session;
    ELSIF v_manifest.manifest_kind='sector_benchmark' AND $4='evaluation_rows' THEN
      v_lookup_session:=(v_row.payload_json->>0)::date;
      v_lookup_symbol:=v_row.payload_json->>3;
    ELSIF v_manifest.manifest_kind='sector_benchmark' AND $4='session_conservation' THEN
      v_lookup_session:=(v_row.payload_json->>0)::date;
    END IF;
    INSERT INTO public.opportunity_manifest_rows_v3(
      manifest_id,page_id,section_key,row_ordinal,identity_key,terminal_code,
      lookup_symbol,lookup_session,payload_json,payload_canonical,payload_hash,recorded_at
    ) VALUES(
      $3,v_page,$4,v_row.row_ordinal,v_row.identity_key,v_row.terminal_code,
      v_lookup_symbol,v_lookup_session,v_row.payload_json,v_row.payload_canonical,
      v_row.payload_hash,v_now
    );
    v_expected:=v_expected+1;
    v_index:=v_index+1;
  END LOOP;
  UPDATE public.opportunity_run_jobs_v3 SET status='succeeded',output_kind='manifest_page',
    output_manifest_id=$3,output_hash=$9,terminal_at=v_now,
    owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
  WHERE opportunity_run_jobs_v3.job_id=$1;
  PERFORM public.enqueue_next_opportunity_job_v3_internal(v_job.run_id,$1);
  RETURN QUERY SELECT 'stored'::public.opportunity_manifest_page_status_v3,v_page,v_count,$9;
END
$fn$;

CREATE OR REPLACE FUNCTION complete_opportunity_manifest_v3(
  job_id uuid,owner_token text,requested_manifest_id uuid,requested_row_count bigint,
  root_canonical bytea,root_json jsonb,requested_manifest_hash text
) RETURNS TABLE(status opportunity_manifest_status_v3,manifest_hash text,row_count bigint,terminal_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_job public.opportunity_run_jobs_v3%ROWTYPE; v_now timestamptz:=clock_timestamp(); v_actual bigint;
  v_kind public.opportunity_manifest_kind_v3; v_ordinal integer;
  v_manifest public.opportunity_manifests_v3%ROWTYPE; v_read jsonb; v_expected_root jsonb;
  v_run public.opportunity_runs%ROWTYPE; v_header jsonb;
  v_audited_session date; v_audited_hash text; v_previous_hash text; v_plan_hash text;
  v_close timestamptz; v_source_dataset_id uuid; v_source_dataset_hash text;
  v_audit_id uuid; v_audit_name text; v_bytes bytea; v_hex text;
  v_mover_count integer; v_eligible_universe_count integer; v_later_mentioned_count integer;
  v_recall_pct double precision;
BEGIN
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased' AND j.lease_expires_at>=v_now
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  SELECT * INTO v_manifest FROM public.opportunity_manifests_v3 m
  WHERE m.manifest_id=$3 AND m.status='building' FOR UPDATE;
  SELECT read_json->5 INTO v_read
  FROM public.opportunity_worker_read_units_v3
  WHERE opportunity_worker_read_units_v3.job_id=$1
    AND input_hash=v_job.input_hash;
  IF v_manifest.manifest_id IS NOT NULL AND v_read IS NOT NULL THEN
    v_expected_root:=jsonb_build_array(
      'opportunity-manifest-root-v3.3',v_manifest.manifest_kind,v_manifest.contract_version,
      v_manifest.source_cutoff,v_read->0,v_read->1
    );
  END IF;
  SELECT count(*) INTO v_actual FROM public.opportunity_manifest_rows_v3 r WHERE r.manifest_id=$3;
  IF v_job.job_id IS NULL OR v_manifest.manifest_id IS NULL OR v_expected_root IS NULL
    OR v_actual<>$4 OR octet_length($5)>3145728
    OR $7!~'^[0-9a-f]{64}$' OR encode(extensions.digest($5,'sha256'),'hex')<>$7
    OR $6 IS DISTINCT FROM v_expected_root
    OR $5<>convert_to(regexp_replace($6::text, ', ', ',', 'g'),'utf8')
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch'; END IF;
  IF v_manifest.manifest_kind='evaluation_input' AND (
    (SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
      WHERE row.manifest_id=$3 AND row.section_key='attempt_roster')<>252
    OR (SELECT count(DISTINCT row.payload_json->>0)
      FROM public.opportunity_manifest_rows_v3 row
      WHERE row.manifest_id=$3 AND row.section_key='attempt_roster')<>252
    OR (SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
      WHERE row.manifest_id=$3 AND row.section_key='backtest_rows')
      <>coalesce((SELECT (pair->>1)::integer FROM jsonb_array_elements(v_manifest.header_json) pair
        WHERE pair->>0='backtestCount'),-1)
    OR (SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
      WHERE row.manifest_id=$3 AND row.section_key='live_rows')
      <>coalesce((SELECT (pair->>1)::integer FROM jsonb_array_elements(v_manifest.header_json) pair
        WHERE pair->>0='liveCount'),-1)
    OR (SELECT count(DISTINCT row.payload_json->>0)
      FROM public.opportunity_manifest_rows_v3 row
      WHERE row.manifest_id=$3 AND row.section_key='backtest_rows')
      <>(SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
        WHERE row.manifest_id=$3 AND row.section_key='backtest_rows')
    OR (SELECT count(DISTINCT row.payload_json->>0)
      FROM public.opportunity_manifest_rows_v3 row
      WHERE row.manifest_id=$3 AND row.section_key='live_rows')
      <>(SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
        WHERE row.manifest_id=$3 AND row.section_key='live_rows')
    OR (SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
      WHERE row.manifest_id=$3 AND row.section_key='conservation')
      <>(SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
        WHERE row.manifest_id=$3 AND row.section_key IN ('backtest_rows','live_rows'))
    OR EXISTS (
      SELECT 1
      FROM public.opportunity_manifest_rows_v3 conservation
      WHERE conservation.manifest_id=$3 AND conservation.section_key='conservation'
        AND (
          (conservation.payload_json->>2)::integer
            <>(conservation.payload_json->>3)::integer+(conservation.payload_json->>4)::integer
          OR (conservation.payload_json->>6)::boolean
            IS DISTINCT FROM ((conservation.payload_json->>3)::integer>=10)
        )
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  UPDATE public.opportunity_manifests_v3 m SET status='complete',row_count=$4,root_canonical=$5,
    root_json=$6,manifest_hash=$7,terminal_at=v_now
  WHERE m.manifest_id=$3 AND m.status='building';
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  UPDATE public.opportunity_run_jobs_v3 SET status='succeeded',output_manifest_id=$3,
    output_kind='manifest_reference',output_hash=$7,terminal_at=v_now,
    owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
  WHERE opportunity_run_jobs_v3.job_id=$1;
  SELECT m.manifest_kind,(p.payload_json->5->>0)::integer INTO v_kind,v_ordinal
  FROM public.opportunity_manifests_v3 m
  JOIN public.opportunity_job_payloads_v3 p ON p.job_id=$1
  WHERE m.manifest_id=$3;
  INSERT INTO public.opportunity_run_manifest_inputs(run_id,manifest_id,input_role,ordinal)
  VALUES(v_job.run_id,$3,v_kind,v_ordinal)
  ON CONFLICT(run_id,input_role,ordinal) DO NOTHING;
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_run_manifest_inputs
    WHERE run_id=v_job.run_id AND manifest_id=$3 AND input_role=v_kind AND ordinal=v_ordinal
  ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  IF v_kind='link_audit_sample' THEN
    INSERT INTO public.opportunity_link_audit_samples(
      sample_manifest_id,sample_id,run_id,claim_id,mention_id,connector,link_mode,
      outcome_family,mention_ordinal,selection_ordinal,selection_hash,evidence_ref,
      review_context,review_mention_start_offset,review_mention_end_offset,
      normalized_token,engine_outcome,engine_reason,engine_canonical_symbol,
      review_evidence_hash,recorded_at
    )
    SELECT
      $3,row.payload_json->>0,(row.payload_json->>4)::uuid,
      (row.payload_json->>5)::uuid,mention.mention_id,row.payload_json->>1,
      (row.payload_json->>2)::public.opportunity_link_mode_v3,
      (row.payload_json->>3)::public.opportunity_link_outcome_family_v3,
      (row.payload_json->>6)::integer,row.row_ordinal::integer,row.payload_json->>7,
      row.payload_json->8->>1,row.payload_json->8->>2,
      (row.payload_json->8->>3)::integer,(row.payload_json->8->>4)::integer,
      row.payload_json->8->>5,(row.payload_json->8->>7)::public.opportunity_mention_outcome_v3,
      (row.payload_json->8->>8)::public.opportunity_mention_reason_v3,
      row.payload_json->8->>9,row.payload_json->>9,v_now
    FROM public.opportunity_manifest_rows_v3 row
    JOIN public.opportunity_source_claims claim
      ON claim.claim_id=(row.payload_json->>5)::uuid
      AND claim.run_id=(row.payload_json->>4)::uuid
    JOIN public.opportunity_source_mentions mention
      ON mention.run_id=claim.run_id AND mention.revision_id=claim.revision_id
      AND mention.claim_ordinal=claim.claim_ordinal
      AND mention.mention_ordinal=(row.payload_json->>6)::integer
    WHERE row.manifest_id=$3 AND row.section_key='samples';
    IF (SELECT count(*) FROM public.opportunity_link_audit_samples sample
      WHERE sample.sample_manifest_id=$3) <> (
        SELECT count(*) FROM public.opportunity_manifest_rows_v3 row
        WHERE row.manifest_id=$3 AND row.section_key='samples'
      )
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
  END IF;
  IF v_kind='mover_price_reference' THEN
    SELECT * INTO STRICT v_run FROM public.opportunity_runs r
    WHERE r.run_id=v_job.run_id FOR UPDATE;
    SELECT m.header_json INTO STRICT v_header FROM public.opportunity_manifests_v3 m
    WHERE m.manifest_id=$3;
    SELECT (pair->>1)::date INTO STRICT v_audited_session
    FROM jsonb_array_elements(v_header) pair WHERE pair->>0='auditedSession';
    SELECT pair->>1 INTO STRICT v_audited_hash
    FROM jsonb_array_elements(v_header) pair WHERE pair->>0='auditedSessionAuthorityHash';
    SELECT pair->>1 INTO STRICT v_previous_hash
    FROM jsonb_array_elements(v_header) pair WHERE pair->>0='previousSessionAuthorityHash';
    SELECT pair->>1 INTO STRICT v_plan_hash
    FROM jsonb_array_elements(v_header) pair WHERE pair->>0='recentSessionPlanHash';
    SELECT s.canonical_cutoff INTO STRICT v_close
    FROM public.opportunity_effective_taiwan_sessions_v3 s
    WHERE s.session_id=v_audited_session
      AND s.taiwan_session_authority_hash=v_audited_hash;
    SELECT m.manifest_id,m.manifest_hash INTO STRICT v_source_dataset_id,v_source_dataset_hash
    FROM public.opportunity_run_manifest_inputs i
    JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
    WHERE i.run_id=v_job.run_id AND i.input_role='source_dataset' AND i.ordinal=0
      AND m.status='complete';
    v_audit_name:=regexp_replace(jsonb_build_array(
      'opportunity-mover-audit-v3.3',v_audited_session,v_audited_hash,v_previous_hash,
      v_plan_hash,to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      $7,v_source_dataset_hash
    )::text, ', ', ',', 'g');
    v_bytes:=substring(extensions.digest(
      decode(replace('0e7d59d4-cebe-5bb1-91b7-a737c0e709d8','-',''),'hex')
        ||convert_to(v_audit_name,'utf8'),'sha1') FROM 1 FOR 16);
    v_bytes:=set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
    v_bytes:=set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
    v_hex:=encode(v_bytes,'hex');
    v_audit_id:=(substr(v_hex,1,8)||'-'||substr(v_hex,9,4)||'-'||substr(v_hex,13,4)||'-'
      ||substr(v_hex,17,4)||'-'||substr(v_hex,21,12))::uuid;
    SELECT count(*)::integer,least(20,count(*))::integer
    INTO v_eligible_universe_count,v_mover_count
    FROM public.opportunity_manifest_rows_v3 mr
    WHERE mr.manifest_id=$3 AND mr.section_key='included_rows';
    SELECT count(*)::integer INTO v_later_mentioned_count
    FROM (
      SELECT ranked.symbol
      FROM (
        SELECT mr.payload_json->>0 AS symbol,
          row_number() OVER (
            ORDER BY (
              100*((mr.payload_json->>8)::double precision/(mr.payload_json->>9)::double precision-1)
            ) DESC,
            (mr.payload_json->>10)::double precision DESC,
            mr.payload_json->>0
          ) AS mover_rank
        FROM public.opportunity_manifest_rows_v3 mr
        WHERE mr.manifest_id=$3 AND mr.section_key='included_rows'
      ) ranked
      WHERE ranked.mover_rank<=20
        AND EXISTS (
          SELECT 1
          FROM public.opportunity_source_mentions sm
          JOIN public.source_document_revisions_v3 sr ON sr.revision_id=sm.revision_id
          WHERE sm.run_id=v_run.upstream_run_id
            AND sm.symbol=ranked.symbol
            AND sm.outcome IN ('linked_new','linked_refresh','linked_duplicate_claim')
            AND sr.published_at>v_close
            AND sr.collected_at>v_close
            AND sr.published_at<=least(v_run.source_cutoff,v_close+interval '72 hours')
            AND sr.collected_at<=least(v_run.source_cutoff,v_close+interval '72 hours')
        )
    ) later_mentions;
    v_recall_pct:=CASE
      WHEN v_run.source_cutoff<v_close+interval '72 hours' OR v_mover_count=0 THEN NULL
      ELSE 100.0*v_later_mentioned_count/v_mover_count
    END;
    INSERT INTO public.opportunity_mover_audits_v3(
      audit_id,session_id,audited_session_authority_hash,previous_session_authority_hash,
      recent_session_plan_hash,source_cutoff,audit_window_closes_at,source_collection_cutoff,
      status,mover_count,eligible_universe_count,recall_pct,price_manifest_id,
      source_dataset_manifest_id,upstream_source_run_id,recorded_at
    ) VALUES(
      v_audit_id,v_audited_session,v_audited_hash,v_previous_hash,v_plan_hash,v_run.source_cutoff,
      v_close+interval '72 hours',least(v_run.source_cutoff,v_close+interval '72 hours'),
      CASE WHEN v_run.source_cutoff<v_close+interval '72 hours'
        THEN 'pending'::public.opportunity_mover_audit_status_v3
        ELSE 'matured'::public.opportunity_mover_audit_status_v3 END,
      v_mover_count,v_eligible_universe_count,v_recall_pct,
      $3,v_source_dataset_id,v_run.upstream_run_id,v_now
    ) ON CONFLICT(audit_id) DO NOTHING;
    IF NOT EXISTS (
      SELECT 1 FROM public.opportunity_mover_audits_v3 a
      WHERE a.audit_id=v_audit_id AND a.price_manifest_id=$3
        AND a.source_dataset_manifest_id=v_source_dataset_id
        AND a.audited_session_authority_hash=v_audited_hash
        AND a.previous_session_authority_hash=v_previous_hash
        AND a.recent_session_plan_hash=v_plan_hash
    ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
    INSERT INTO public.opportunity_mover_audit_symbols_v3(
      audit_id,rank,stock_id,symbol,one_session_return_pct,turnover_twd,
      end_price_ref,prior_price_ref,corporate_action_version,later_mentioned,recorded_at
    )
    SELECT v_audit_id,ranked.mover_rank,ranked.stock_id,ranked.symbol,
      ranked.one_session_return_pct,ranked.turnover_twd,
      ranked.end_price_ref,ranked.prior_price_ref,ranked.corporate_action_version,
      EXISTS (
        SELECT 1
        FROM public.opportunity_source_mentions sm
        JOIN public.source_document_revisions_v3 sr ON sr.revision_id=sm.revision_id
        WHERE sm.run_id=v_run.upstream_run_id
          AND sm.symbol=ranked.symbol
          AND sm.outcome IN ('linked_new','linked_refresh','linked_duplicate_claim')
          AND sr.published_at>v_close
          AND sr.collected_at>v_close
          AND sr.published_at<=least(v_run.source_cutoff,v_close+interval '72 hours')
          AND sr.collected_at<=least(v_run.source_cutoff,v_close+interval '72 hours')
      ),
      v_now
    FROM (
      SELECT
        mr.payload_json->>0 AS symbol,
        (mr.payload_json->>1)::uuid AS stock_id,
        100*((mr.payload_json->>8)::double precision/(mr.payload_json->>9)::double precision-1)
          AS one_session_return_pct,
        (mr.payload_json->>10)::double precision AS turnover_twd,
        mr.payload_json->>13 AS end_price_ref,
        mr.payload_json->>14 AS prior_price_ref,
        mr.payload_json->>17 AS corporate_action_version,
        row_number() OVER (
          ORDER BY (
            100*((mr.payload_json->>8)::double precision/(mr.payload_json->>9)::double precision-1)
          ) DESC,
          (mr.payload_json->>10)::double precision DESC,
          mr.payload_json->>0
        )::integer AS mover_rank
      FROM public.opportunity_manifest_rows_v3 mr
      WHERE mr.manifest_id=$3 AND mr.section_key='included_rows'
    ) ranked
    WHERE ranked.mover_rank<=20
    ON CONFLICT(audit_id,rank) DO NOTHING;
    IF (SELECT count(*) FROM public.opportunity_mover_audit_symbols_v3 s
        WHERE s.audit_id=v_audit_id)<>v_mover_count
      OR EXISTS (
        SELECT 1
        FROM public.opportunity_mover_audit_symbols_v3 s
        WHERE s.audit_id=v_audit_id
          AND s.rank NOT BETWEEN 1 AND v_mover_count
      )
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
    IF v_ordinal=0 THEN
      UPDATE public.opportunity_runs SET selected_mover_audit_id=v_audit_id
      WHERE run_id=v_job.run_id AND selected_mover_audit_id IS NULL;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      END IF;
    ELSIF v_run.selected_mover_audit_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
  END IF;
  PERFORM public.enqueue_next_opportunity_job_v3_internal(v_job.run_id,$1);
  RETURN QUERY SELECT 'complete'::public.opportunity_manifest_status_v3,$7,$4,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION fail_opportunity_manifest_v3(
  job_id uuid,owner_token text,requested_manifest_id uuid,requested_failure_code opportunity_manifest_failure_code_v3
) RETURNS TABLE(status opportunity_manifest_status_v3,failure_code opportunity_manifest_failure_code_v3,terminal_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_job public.opportunity_run_jobs_v3%ROWTYPE; v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased'
    AND j.lease_expires_at >= v_now
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  UPDATE public.opportunity_manifests_v3 m SET status='failed',failure_code=$4,terminal_at=v_now
  WHERE m.manifest_id=$3 AND m.status='building';
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  UPDATE public.opportunity_run_jobs_v3 SET status='failed',failure_code=$4::text::public.opportunity_failure_code_v3,
    terminal_at=v_now,owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
  WHERE opportunity_run_jobs_v3.job_id=$1;
  UPDATE public.opportunity_runs SET status='failed',failure_code=$4::text::public.opportunity_failure_code_v3,terminal_at=v_now
  WHERE opportunity_runs.run_id=v_job.run_id AND status IN ('preparing','running');
  RETURN QUERY SELECT 'failed'::public.opportunity_manifest_status_v3,$4,v_now;
END
$fn$;

CREATE OR REPLACE FUNCTION complete_opportunity_job_v3(
  job_id uuid,owner_token text,output_hash text,counts opportunity_job_counts_v3
) RETURNS TABLE(status opportunity_job_status_v3)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_job public.opportunity_run_jobs_v3%ROWTYPE; v_stage public.opportunity_job_staging_v3%ROWTYPE;
  v_document jsonb; v_claim jsonb; v_mention jsonb; v_row jsonb; v_score jsonb;
  v_detail jsonb; v_warning jsonb; v_row_text text; v_row_hash text;
  v_ordinal integer := 0; v_success_count integer := 0; v_failure_count integer := 0;
  v_candidate jsonb; v_decision jsonb; v_reason text; v_action text;
  v_reason_index integer; v_prior_reason_index integer; v_cutoff_text text;
BEGIN
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased'
    AND j.lease_expires_at >= clock_timestamp()
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  SELECT * INTO v_stage FROM public.opportunity_job_staging_v3 s
  WHERE s.job_id=$1 AND s.attempt=v_job.attempt AND s.output_hash=$3;
  IF NOT FOUND OR v_stage.output_counts IS DISTINCT FROM $4 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_missing';
  END IF;
  IF v_stage.output_kind IN ('deep_candidate_batch','portfolio_allocation_batch') THEN
    SELECT to_char(run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
    INTO STRICT v_cutoff_text FROM public.opportunity_runs run WHERE run.run_id=v_job.run_id;
    FOR v_candidate IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5) LOOP
      IF v_stage.output_kind='deep_candidate_batch' AND v_candidate->14<>'null'::jsonb THEN CONTINUE; END IF;
      v_decision:=CASE WHEN v_stage.output_kind='deep_candidate_batch' THEN v_candidate->8 ELSE v_candidate->1 END;
      IF jsonb_typeof(v_decision)<>'object'
        OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v_decision) key)
          <>ARRAY['blockReasons','confidence','decisionAuthority','entryTrigger','existingPositionAction',
            'existingReason','existingTargetExposurePct','initialPositionPct','invalidation',
            'maximumPositionPct','newPositionAction','primaryHorizon','publicationEligible']::text[]
        OR v_decision->>'decisionAuthority'<>'research_only'
        OR v_decision->'publicationEligible'<>'false'::jsonb
        OR v_decision->>'existingPositionAction'<>'no_position'
        OR v_decision->>'existingReason'<>'portfolio_context_unavailable'
        OR v_decision->'existingTargetExposurePct'<>'null'::jsonb
        OR jsonb_typeof(v_decision->'initialPositionPct')<>'number'
        OR jsonb_typeof(v_decision->'maximumPositionPct')<>'number'
        OR (v_decision->>'initialPositionPct')::numeric NOT BETWEEN 0 AND 5
        OR (v_decision->>'maximumPositionPct')::numeric NOT BETWEEN 0 AND 10
        OR (v_decision->>'initialPositionPct')::numeric>(v_decision->>'maximumPositionPct')::numeric
        OR jsonb_typeof(v_decision->'confidence')<>'number'
        OR (v_decision->>'confidence')::numeric NOT BETWEEN 0 AND 1
        OR NOT (v_decision->'primaryHorizon'='null'::jsonb
          OR v_decision->>'primaryHorizon' IN ('momentum_5_20d','swing_20_60d'))
        OR jsonb_typeof(v_decision->'blockReasons')<>'array'
        OR jsonb_array_length(v_decision->'blockReasons')>5
        OR NOT (v_decision->'entryTrigger'='null'::jsonb OR (
          jsonb_typeof(v_decision->'entryTrigger')='string'
          AND btrim(v_decision->>'entryTrigger')<>''
          AND char_length(v_decision->>'entryTrigger')<=160))
        OR jsonb_typeof(v_decision->'invalidation')<>'object'
        OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v_decision->'invalidation') key)
          <>ARRAY['code','evidenceExpiresAt','stopPrice']::text[]
      THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      v_prior_reason_index:=0;
      FOR v_reason IN SELECT value FROM jsonb_array_elements_text(v_decision->'blockReasons') LOOP
        v_reason_index:=array_position(ARRAY[
          'data_integrity','market_risk_off','capacity_exhausted','invalid_exposure_input',
          'score_below_threshold','confidence_below_threshold','valuation_unavailable',
          'valuation_reward_risk','entry_data_unavailable','entry_invalidated','entry_unconfirmed',
          'bias_observe_only','quality_insufficient','no_eligible_method','missing_required_inputs',
          'insufficient_series','insufficient_multiple_reference','cross_check_unavailable',
          'missing_financial_manifest','stale_financial_inputs','conflicting_point_in_time_fact',
          'invalid_unit','missing_bridge_inputs','nonconsecutive_quarters','operating_bridge_mismatch',
          'pretax_bridge_mismatch','net_income_bridge_mismatch','share_count_conflict',
          'reported_eps_mismatch','tax_rate_outlier','capital_structure_conflict','non_finite_bridge',
          'negative_equity_value','invalid_capital_structure','non_finite_distribution',
          'distribution_ordering','unverified_base_upside','unverified_scenario_upside',
          'consensus_divergence','method_divergence']::text[],v_reason);
        IF v_reason_index IS NULL OR v_reason_index<=v_prior_reason_index THEN
          RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END IF;
        v_prior_reason_index:=v_reason_index;
      END LOOP;
      v_action:=v_decision->>'newPositionAction';
      IF v_action NOT IN ('avoid','valuation_review','wait_trigger','event_starter','starter_now') THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      ELSIF v_decision->'primaryHorizon'='null'::jsonb AND NOT (
        v_action='avoid' AND v_decision->'blockReasons'='["data_integrity"]'::jsonb
      ) THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      ELSIF v_action='event_starter' AND v_decision->>'primaryHorizon'<>'momentum_5_20d' THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      ELSIF v_action IN ('starter_now','event_starter') THEN
        IF (v_decision->>'initialPositionPct')::numeric<=0
          OR (v_decision->>'maximumPositionPct')::numeric<>10
          OR jsonb_array_length(v_decision->'blockReasons')<>0
          OR jsonb_typeof(v_decision->'entryTrigger')<>'string'
          OR v_decision->'invalidation'->>'code'<>'price_stop_or_evidence_expiry'
          OR jsonb_typeof(v_decision->'invalidation'->'stopPrice')<>'number'
          OR (v_decision->'invalidation'->>'stopPrice')::numeric<=0
          OR (v_decision->'invalidation'->>'evidenceExpiresAt')
            !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$'
          OR v_decision->'invalidation'->>'evidenceExpiresAt'<=v_cutoff_text
        THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      ELSIF v_action='wait_trigger' THEN
        IF v_decision->'initialPositionPct'<>'0'::jsonb OR v_decision->'maximumPositionPct'<>'0'::jsonb
          OR v_decision->'blockReasons'<>'["entry_unconfirmed"]'::jsonb
          OR jsonb_typeof(v_decision->'entryTrigger')<>'string'
          OR v_decision->'invalidation'->>'code'<>'evidence_expiry_only'
          OR v_decision->'invalidation'->'stopPrice'<>'null'::jsonb
          OR (v_decision->'invalidation'->>'evidenceExpiresAt')
            !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$'
          OR v_decision->'invalidation'->>'evidenceExpiresAt'<=v_cutoff_text
        THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      ELSE
        IF v_decision->'initialPositionPct'<>'0'::jsonb OR v_decision->'maximumPositionPct'<>'0'::jsonb
          OR v_decision->'entryTrigger'<>'null'::jsonb
          OR jsonb_array_length(v_decision->'blockReasons')=0
          OR v_decision->'invalidation'->>'code'<>'data_integrity_review'
          OR v_decision->'invalidation'->'stopPrice'<>'null'::jsonb
          OR v_decision->'invalidation'->'evidenceExpiresAt'<>'null'::jsonb
          OR (v_action='avoid' AND (
            jsonb_array_length(v_decision->'blockReasons')<>1
            OR v_decision->'blockReasons'->>0 NOT IN ('data_integrity','market_risk_off',
              'capacity_exhausted','invalid_exposure_input','score_below_threshold',
              'confidence_below_threshold','valuation_reward_risk','entry_data_unavailable',
              'entry_invalidated','entry_unconfirmed','bias_observe_only','quality_insufficient')
          ))
          OR (v_action='valuation_review' AND EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(v_decision->'blockReasons') reason(value)
            WHERE reason.value NOT IN ('valuation_unavailable','no_eligible_method','missing_required_inputs',
              'insufficient_series','insufficient_multiple_reference','cross_check_unavailable',
              'missing_financial_manifest','stale_financial_inputs','conflicting_point_in_time_fact',
              'invalid_unit','missing_bridge_inputs','nonconsecutive_quarters','operating_bridge_mismatch',
              'pretax_bridge_mismatch','net_income_bridge_mismatch','share_count_conflict',
              'reported_eps_mismatch','tax_rate_outlier','capital_structure_conflict','non_finite_bridge',
              'negative_equity_value','invalid_capital_structure','non_finite_distribution',
              'distribution_ordering','unverified_base_upside','unverified_scenario_upside',
              'consensus_divergence','method_divergence')))
          OR (v_action='valuation_review'
            AND v_decision->'blockReasons' ? 'valuation_unavailable'
            AND jsonb_array_length(v_decision->'blockReasons')<>1)
        THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      END IF;
      IF v_stage.output_kind='deep_candidate_batch' AND (
        v_decision->'initialPositionPct'<>v_candidate->9
        OR v_decision->'maximumPositionPct'<>v_candidate->10
      ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
    END LOOP;
  END IF;
  IF v_stage.output_kind='source_parse_batch' THEN
    v_document:=v_stage.output_json->5->0->0;
    IF jsonb_typeof(v_document)<>'array' OR jsonb_array_length(v_document)<>9 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    INSERT INTO public.opportunity_source_document_outcomes(
      run_id,source_key,revision_id,selection_ordinal,canonical_document_id,effective_at,
      outcome,content_hash,extracted_claim_count,raw_mention_count
    ) VALUES(
      v_job.run_id,(v_document->>0)::public.source_key_v3,(v_document->>1)::uuid,
      (v_document->>2)::integer,v_document->>3,(v_document->>4)::timestamptz,
      (v_document->>5)::public.opportunity_document_outcome_v3,v_document->>6,
      (v_document->>7)::integer,(v_document->>8)::integer
    );
    FOR v_claim IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5->1) LOOP
      IF jsonb_typeof(v_claim)<>'array' OR jsonb_array_length(v_claim)<>12
        OR (v_claim->>0)::uuid<>(v_document->>1)::uuid
      THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      INSERT INTO public.opportunity_source_claims(
        run_id,revision_id,claim_ordinal,canonical_claim_id,outcome,canonical_prior_claim_id,
        evidence_root_id,effective_at,claim_confidence,source_ref,verification_tier,claim_evidence_stance
      ) VALUES(
        v_job.run_id,(v_claim->>0)::uuid,(v_claim->>1)::integer,v_claim->>2,
        CASE WHEN EXISTS (
          SELECT 1 FROM public.opportunity_source_claims prior
          WHERE prior.canonical_claim_id=v_claim->>2
            AND prior.run_id=v_job.run_id
        ) THEN 'duplicate_claim'::public.opportunity_claim_outcome_v3
        ELSE (v_claim->>3)::public.opportunity_claim_outcome_v3 END,
        coalesce(
          CASE WHEN v_claim->>4 IS NULL THEN NULL ELSE (
            SELECT prior.claim_id FROM public.opportunity_source_claims prior
            WHERE prior.run_id=v_job.run_id
              AND prior.revision_id=(v_claim->>4)::uuid
              AND prior.claim_ordinal=(v_claim->>5)::integer
          ) END,
          (
            SELECT prior.claim_id FROM public.opportunity_source_claims prior
            JOIN public.opportunity_source_document_outcomes prior_document
              ON prior_document.run_id=prior.run_id
              AND prior_document.revision_id=prior.revision_id
            WHERE prior.canonical_claim_id=v_claim->>2
              AND prior.run_id=v_job.run_id
            ORDER BY prior.effective_at,prior_document.canonical_document_id,
              prior.claim_ordinal
            LIMIT 1
          )
        ),
        v_claim->>6,(v_claim->>7)::timestamptz,(v_claim->>8)::double precision,
        v_claim->>9,(v_claim->>10)::public.opportunity_evidence_verification_tier_v3,
        (v_claim->>11)::public.opportunity_claim_evidence_stance_v3
      );
    END LOOP;
    FOR v_mention IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5->2) LOOP
      IF jsonb_typeof(v_mention)<>'array' OR jsonb_array_length(v_mention)<>15
        OR (v_mention->>0)::uuid<>(v_document->>1)::uuid
      THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      INSERT INTO public.opportunity_source_mentions(
        run_id,revision_id,claim_ordinal,mention_ordinal,normalized_token,start_offset,end_offset,
        review_context,review_mention_start_offset,review_mention_end_offset,link_mode,stock_id,
        symbol,outcome,reason,confidence
      ) VALUES(
        v_job.run_id,(v_mention->>0)::uuid,(v_mention->>1)::integer,(v_mention->>2)::integer,
        v_mention->>3,(v_mention->>4)::integer,(v_mention->>5)::integer,v_mention->>6,
        (v_mention->>7)::integer,(v_mention->>8)::integer,
        (v_mention->>9)::public.opportunity_link_mode_v3,
        CASE WHEN v_mention->>10 IS NULL THEN NULL ELSE (v_mention->>10)::uuid END,
        v_mention->>11,
        CASE WHEN (v_mention->>12) IN ('linked_new','linked_refresh')
          AND EXISTS (
            SELECT 1 FROM public.opportunity_source_claims claim
            WHERE claim.run_id=v_job.run_id
              AND claim.revision_id=(v_mention->>0)::uuid
              AND claim.claim_ordinal=(v_mention->>1)::integer
              AND claim.outcome='duplicate_claim'
          )
          THEN 'linked_duplicate_claim'::public.opportunity_mention_outcome_v3
          WHEN (v_mention->>12)='linked_new'
            AND EXISTS (
              SELECT 1
              FROM public.opportunity_source_mentions prior
              JOIN public.opportunity_runs prior_run ON prior_run.run_id=prior.run_id
              WHERE prior.run_id<>v_job.run_id
                AND prior.stock_id=(v_mention->>10)::uuid
                AND prior.symbol=v_mention->>11
                AND prior.outcome IN (
                  'linked_new','linked_refresh','linked_duplicate_claim'
                )
                AND prior_run.source_cutoff<=(
                  SELECT current_run.source_cutoff
                  FROM public.opportunity_runs current_run
                  WHERE current_run.run_id=v_job.run_id
                )
            )
          THEN 'linked_refresh'::public.opportunity_mention_outcome_v3
          ELSE (v_mention->>12)::public.opportunity_mention_outcome_v3 END,
        CASE WHEN (v_mention->>12) IN ('linked_new','linked_refresh')
          AND EXISTS (
            SELECT 1 FROM public.opportunity_source_claims claim
            WHERE claim.run_id=v_job.run_id
              AND claim.revision_id=(v_mention->>0)::uuid
              AND claim.claim_ordinal=(v_mention->>1)::integer
              AND claim.outcome='duplicate_claim'
          )
          THEN 'duplicate_claim_link'::public.opportunity_mention_reason_v3
          ELSE (v_mention->>13)::public.opportunity_mention_reason_v3 END,
        (v_mention->>14)::double precision
      );
    END LOOP;
    IF (SELECT count(*) FROM public.opportunity_source_claims c
        WHERE c.run_id=v_job.run_id AND c.revision_id=(v_document->>1)::uuid)
        <>(v_document->>7)::integer
      OR (SELECT count(*) FROM public.opportunity_source_mentions m
        WHERE m.run_id=v_job.run_id AND m.revision_id=(v_document->>1)::uuid)
        <>(v_document->>8)::integer
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
    SELECT jsonb_build_array(
      (SELECT jsonb_agg(jsonb_build_array(
        document.source_key,document.revision_id,document.selection_ordinal,
        document.canonical_document_id,document.effective_at,document.outcome,
        document.content_hash,document.extracted_claim_count,document.raw_mention_count
      ) ORDER BY document.selection_ordinal)
      FROM public.opportunity_source_document_outcomes document
      WHERE document.run_id=v_job.run_id
        AND document.revision_id=(v_document->>1)::uuid),
      (SELECT coalesce(jsonb_agg(jsonb_build_array(
        claim.revision_id,claim.claim_ordinal,claim.canonical_claim_id,claim.outcome,
        prior.revision_id,prior.claim_ordinal,claim.evidence_root_id,claim.effective_at,
        claim.claim_confidence,claim.source_ref,claim.verification_tier,
        claim.claim_evidence_stance
      ) ORDER BY claim.claim_ordinal),'[]'::jsonb)
      FROM public.opportunity_source_claims claim
      LEFT JOIN public.opportunity_source_claims prior
        ON prior.claim_id=claim.canonical_prior_claim_id
      WHERE claim.run_id=v_job.run_id
        AND claim.revision_id=(v_document->>1)::uuid),
      (SELECT coalesce(jsonb_agg(jsonb_build_array(
        mention.revision_id,mention.claim_ordinal,mention.mention_ordinal,
        mention.normalized_token,mention.start_offset,mention.end_offset,
        mention.review_context,mention.review_mention_start_offset,
        mention.review_mention_end_offset,mention.link_mode,mention.stock_id,
        mention.symbol,mention.outcome,mention.reason,mention.confidence
      ) ORDER BY mention.claim_ordinal,mention.mention_ordinal),'[]'::jsonb)
      FROM public.opportunity_source_mentions mention
      WHERE mention.run_id=v_job.run_id
        AND mention.revision_id=(v_document->>1)::uuid)
    ) INTO v_row;
    v_stage.output_json:=jsonb_set(v_stage.output_json,'{5}',v_row,false);
    v_row_text:=regexp_replace(v_stage.output_json::text, ', ', ',', 'g');
    v_stage.output_canonical:=convert_to(v_row_text,'utf8');
    v_stage.output_hash:=encode(
      extensions.digest(v_stage.output_canonical,'sha256'),'hex'
    );
    UPDATE public.opportunity_job_staging_v3 staging SET
      output_canonical=v_stage.output_canonical,
      output_json=v_stage.output_json,
      output_hash=v_stage.output_hash
    WHERE staging.job_id=v_job.job_id AND staging.attempt=v_job.attempt;
  ELSIF v_stage.output_kind='source_connector_summary' THEN
    INSERT INTO public.opportunity_source_connector_accounting(
      run_id,source_key,eligible_document_count,selected_document_count,deferred_due_scan_cap_count,
      duplicate_document_count,expired_document_count,parse_failure_count,processed_no_claim_count,
      processed_with_claims_count,unique_claim_count,duplicate_claim_count,linked_new_count,
      linked_refresh_count,linked_duplicate_claim_count,ambiguous_symbol_count,
      rejected_low_confidence_count,unsupported_instrument_count,mention_reason_counts,
      linked_candidate_count,status,failure_reason
    ) VALUES(
      v_job.run_id,(v_stage.output_json->5->>'sourceKey')::public.source_key_v3,
      (v_stage.output_json->5->>'eligibleDocuments')::integer,
      (v_stage.output_json->5->>'selectedDocuments')::integer,
      (v_stage.output_json->5->>'deferredDueScanCap')::integer,
      (v_stage.output_json->5->'documentOutcomes'->>'duplicate_document')::integer,
      (v_stage.output_json->5->'documentOutcomes'->>'expired_document')::integer,
      (v_stage.output_json->5->'documentOutcomes'->>'parse_failure')::integer,
      (v_stage.output_json->5->'documentOutcomes'->>'processed_no_claim')::integer,
      (v_stage.output_json->5->'documentOutcomes'->>'processed_with_claims')::integer,
      (v_stage.output_json->5->'claimOutcomes'->>'unique_claim')::integer,
      (v_stage.output_json->5->'claimOutcomes'->>'duplicate_claim')::integer,
      (v_stage.output_json->5->'mentionOutcomes'->>'linked_new')::integer,
      (v_stage.output_json->5->'mentionOutcomes'->>'linked_refresh')::integer,
      (v_stage.output_json->5->'mentionOutcomes'->>'linked_duplicate_claim')::integer,
      (v_stage.output_json->5->'mentionOutcomes'->>'ambiguous_symbol')::integer,
      (v_stage.output_json->5->'mentionOutcomes'->>'rejected_low_confidence')::integer,
      (v_stage.output_json->5->'mentionOutcomes'->>'unsupported_instrument')::integer,
      v_stage.output_json->5->'mentionReasonCounts',
      (v_stage.output_json->5->>'linkedCandidateCount')::integer,
      (v_stage.output_json->5->>'status')::public.opportunity_source_connector_status_v3,
      CASE WHEN v_stage.output_json->5->>'failureReason' IS NULL THEN NULL
        ELSE (v_stage.output_json->5->>'failureReason')::public.opportunity_failure_code_v3 END
    );
  ELSIF v_stage.output_kind='market_context_snapshot' THEN
    v_row:=v_stage.output_json->5;
    v_row_text:=regexp_replace(v_row::text,', ', ',', 'g');
    v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
    INSERT INTO public.opportunity_market_context_snapshots(
      run_id,contract_version,payload_canonical,payload_json,payload_hash
    ) VALUES(
      v_job.run_id,'market-context-v3.6',convert_to(v_row_text,'utf8'),v_row,v_row_hash
    );
  ELSIF v_stage.output_kind='shallow_candidate_batch' THEN
    FOR v_row IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5) LOOP
      IF jsonb_typeof(v_row)<>'array' OR jsonb_array_length(v_row)<>13
        OR (v_row->>1) !~ '^[0-9]{4}$'
        OR (v_row->>5)::double precision NOT BETWEEN 0 AND 100
        OR (v_row->>6)::double precision NOT BETWEEN 0 AND 100
        OR (v_row->>7)::double precision NOT BETWEEN 0 AND 100
        OR (v_row->>8)::double precision NOT BETWEEN 0 AND 100
        OR jsonb_typeof(v_row->12)<>'array'
        OR jsonb_array_length(v_row->12)>12
        OR (
          ((v_row->>3)='direct_candidate') IS DISTINCT FROM (v_row->>2)::boolean
        )
        OR (
          (v_row->>3)='direct_candidate' AND v_row->4='null'::jsonb
        )
        OR (
          (v_row->>3)='comparison_only' AND v_row->4<>'null'::jsonb
        )
        OR (
          (v_row->>10)='failed' AND v_row->11='null'::jsonb
        )
        OR (
          (v_row->>10)<>'failed' AND v_row->11<>'null'::jsonb
        )
      THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      v_row_text:=regexp_replace(v_row::text,', ', ',', 'g');
      v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
      INSERT INTO public.opportunity_shallow_candidate_results_v3(
        job_id,run_id,candidate_ordinal,stock_id,symbol,direct_source,candidate_origin,
        anchor_claim_id,canonical_sector_key,shallow_status,failure_code,
        payload_canonical,payload_json,payload_hash
      ) VALUES(
        v_job.job_id,v_job.run_id,v_ordinal,(v_row->>0)::uuid,v_row->>1,
        (v_row->>2)::boolean,(v_row->>3)::public.opportunity_candidate_origin_v3,
        CASE WHEN v_row->4='null'::jsonb THEN NULL ELSE (v_row->>4)::uuid END,
        (v_row->>9)::public.canonical_sector_key_v3,
        (v_row->>10)::public.opportunity_shallow_status_v3,
        CASE WHEN v_row->11='null'::jsonb THEN NULL
          ELSE (v_row->>11)::public.opportunity_failure_code_v3 END,
        convert_to(v_row_text,'utf8'),v_row,v_row_hash
      );
      v_ordinal:=v_ordinal+1;
    END LOOP;
  ELSIF v_stage.output_kind='sector_cycle_batch' THEN
    FOR v_row IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5) LOOP
      IF jsonb_typeof(v_row)<>'array' OR jsonb_array_length(v_row)<>2 THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      END IF;
      v_row_text:=regexp_replace((v_row->1)::text,', ', ',', 'g');
      v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
      INSERT INTO public.opportunity_sector_cycle_snapshots(
        run_id,canonical_sector_key,contract_version,payload_canonical,payload_json,payload_hash
      ) VALUES(
        v_job.run_id,(v_row->>0)::public.canonical_sector_key_v3,'sector-cycle-v3.0',
        convert_to(v_row_text,'utf8'),v_row->1,v_row_hash
      );
    END LOOP;
  ELSIF v_stage.output_kind='deep_candidate_batch' THEN
    FOR v_row IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5) LOOP
      IF jsonb_typeof(v_row)<>'array' OR jsonb_array_length(v_row)<>15 THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      END IF;
      IF v_row->14='null'::jsonb AND (
        jsonb_typeof(v_row->8)<>'object'
        OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v_row->8) key)
          <>ARRAY['blockReasons','confidence','decisionAuthority','entryTrigger','existingPositionAction',
            'existingReason','existingTargetExposurePct','initialPositionPct','invalidation',
            'maximumPositionPct','newPositionAction','primaryHorizon','publicationEligible']::text[]
        OR v_row->8->'initialPositionPct'<>v_row->9
        OR v_row->8->'maximumPositionPct'<>v_row->10
      ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      v_row_text:=regexp_replace(v_row::text,', ', ',', 'g');
      v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
      INSERT INTO public.opportunity_deep_candidate_results_v3(
        job_id,run_id,candidate_ordinal,stock_id,symbol,anchor_claim_id,
        canonical_sector_key,deep_status,failure_code,payload_canonical,payload_json,payload_hash
      ) VALUES(
        v_job.job_id,v_job.run_id,v_ordinal,(v_row->>0)::uuid,v_row->>1,
        (v_row->>4)::uuid,(v_row->>5)::public.canonical_sector_key_v3,
        CASE WHEN v_row->14='null'::jsonb
          THEN 'succeeded'::public.opportunity_deep_status_v3
          ELSE 'failed'::public.opportunity_deep_status_v3 END,
        CASE WHEN v_row->14='null'::jsonb THEN NULL
          ELSE (v_row->>14)::public.opportunity_failure_code_v3 END,
        convert_to(v_row_text,'utf8'),v_row,v_row_hash
      );
      IF v_row->14='null'::jsonb THEN
        IF jsonb_typeof(v_row->13)<>'object' THEN
          RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END IF;
        v_success_count:=v_success_count+1;
        IF jsonb_typeof(v_row->11)<>'array' OR jsonb_array_length(v_row->11)<>3 THEN
          RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
        END IF;
        FOR v_score IN SELECT value FROM jsonb_array_elements(v_row->11) LOOP
          IF jsonb_typeof(v_score)<>'array' OR jsonb_array_length(v_score)<>6 THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
          END IF;
          IF (v_score->>0) NOT IN ('momentum_5_20d','swing_20_60d','thesis_120_250d')
            OR (v_score->>2)::double precision NOT BETWEEN 0 AND 100
            OR (v_score->>3)::double precision NOT BETWEEN 0 AND 1
            OR (v_score->>4)::double precision NOT BETWEEN 0 AND 100
          THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
        END LOOP;
      ELSE
        v_failure_count:=v_failure_count+1;
      END IF;
      v_ordinal:=v_ordinal+1;
    END LOOP;
    IF v_success_count<>(v_stage.output_counts).deep_success_candidate_count
      OR v_failure_count<>(v_stage.output_counts).deep_failure_candidate_count
      OR (v_stage.output_counts).score_snapshot_count<>0
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
  ELSIF v_stage.output_kind='portfolio_allocation_batch' THEN
    FOR v_row IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5) LOOP
      IF jsonb_typeof(v_row)<>'array' OR jsonb_array_length(v_row)<>2
        OR (v_row->>0) !~ '^[0-9]{4}$' OR jsonb_typeof(v_row->1)<>'object'
        OR NOT EXISTS (
          SELECT 1 FROM public.opportunity_deep_candidate_results_v3 d
          WHERE d.run_id=v_job.run_id AND d.symbol=v_row->>0 AND d.deep_status='succeeded'
        )
      THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
      v_row_text:=regexp_replace((v_row->1)::text,', ', ',', 'g');
      v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
      INSERT INTO public.opportunity_portfolio_allocations_v3(
        job_id,run_id,allocation_ordinal,symbol,payload_canonical,payload_json,payload_hash
      ) VALUES(
        v_job.job_id,v_job.run_id,v_ordinal,v_row->>0,
        convert_to(v_row_text,'utf8'),v_row->1,v_row_hash
      );
      v_ordinal:=v_ordinal+1;
    END LOOP;
    IF v_ordinal<>(
      SELECT count(*) FROM public.opportunity_deep_candidate_results_v3 d
      WHERE d.run_id=v_job.run_id AND d.deep_status='succeeded'
    ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
  ELSIF v_stage.output_kind='projection_bundle' THEN
    IF jsonb_array_length(v_stage.output_json->5)<>3 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    WITH score_source AS (
      SELECT deep.stock_id,deep.symbol,score.value,
        (score.value->>0)::public.opportunity_horizon_v3 AS horizon,
        (score.value->>2)::double precision AS score_value,
        (score.value->>3)::double precision AS confidence_value
      FROM public.opportunity_deep_candidate_results_v3 deep
      CROSS JOIN LATERAL jsonb_array_elements(deep.payload_json->11) score(value)
      WHERE deep.run_id=v_job.run_id AND deep.deep_status='succeeded'
    ), ranked AS (
      SELECT *,row_number() OVER(
        PARTITION BY horizon ORDER BY score_value DESC,confidence_value DESC,symbol ASC
      )::integer AS global_rank
      FROM score_source
    ), normalized AS (
      SELECT *,jsonb_build_array(
        value->0,to_jsonb(global_rank),value->2,value->3,value->4,value->5
      ) AS payload
      FROM ranked
    )
    INSERT INTO public.opportunity_score_snapshots(
      run_id,stock_id,symbol,horizon,rank,score,score_confidence,available_weight,
      payload_canonical,payload_json,payload_hash
    )
    SELECT v_job.run_id,stock_id,symbol,horizon,global_rank,score_value,confidence_value,
      (value->>4)::double precision,
      convert_to(regexp_replace(payload::text,', ', ',', 'g'),'utf8'),payload,
      encode(extensions.digest(convert_to(regexp_replace(payload::text,', ', ',', 'g'),'utf8'),'sha256'),'hex')
    FROM normalized;
    IF (SELECT count(*) FROM public.opportunity_score_snapshots WHERE run_id=v_job.run_id)
      <>3*(SELECT count(*) FROM public.opportunity_deep_candidate_results_v3
        WHERE run_id=v_job.run_id AND deep_status='succeeded')
      OR (v_stage.output_counts).score_snapshot_count
        <>3*(SELECT count(*) FROM public.opportunity_deep_candidate_results_v3
          WHERE run_id=v_job.run_id AND deep_status='succeeded')
      OR (v_stage.output_counts).score_snapshot_count
        <>3*jsonb_array_length(v_stage.output_json->5->2)
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
    FOR v_row IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5->0) LOOP
      IF jsonb_typeof(v_row)<>'array' OR jsonb_array_length(v_row)<>8 THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      END IF;
      v_row_text:=regexp_replace(v_row::text,', ', ',', 'g');
      v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
      INSERT INTO public.opportunity_candidate_snapshots(
        run_id,stock_id,symbol,direct_source,candidate_origin,anchor_claim_id,
        shallow_status,deep_status,payload_canonical,payload_json,payload_hash
      ) VALUES(
        v_job.run_id,(v_row->>0)::uuid,v_row->>1,(v_row->>2)::boolean,
        (v_row->>3)::public.opportunity_candidate_origin_v3,
        CASE WHEN v_row->>4 IS NULL THEN NULL ELSE (v_row->>4)::uuid END,
        CASE v_row->7->>'state'
          WHEN 'deferred_before_shallow' THEN 'deferred'::public.opportunity_shallow_status_v3
          WHEN 'shallow_failed' THEN 'failed'::public.opportunity_shallow_status_v3
          ELSE 'succeeded'::public.opportunity_shallow_status_v3 END,
        CASE v_row->7->>'state'
          WHEN 'deep_failed' THEN 'failed'::public.opportunity_deep_status_v3
          WHEN 'deep_succeeded' THEN 'succeeded'::public.opportunity_deep_status_v3
          ELSE 'not_reached'::public.opportunity_deep_status_v3 END,
        convert_to(v_row_text,'utf8'),v_row,v_row_hash
      );
    END LOOP;
    v_row:=v_stage.output_json->5->1;
    v_row_text:=regexp_replace(v_row::text,', ', ',', 'g');
    v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
    INSERT INTO public.opportunity_public_projections_v3(
      run_id,contract_version,acceptance_version,payload_canonical,payload_json,payload_hash
    ) VALUES(
      v_job.run_id,'source-led-opportunity-v3.6','1.44.6',
      convert_to(v_row_text,'utf8'),v_row,v_row_hash
    );
    FOR v_detail IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5->2) LOOP
      v_row_text:=regexp_replace(v_detail::text,', ', ',', 'g');
      v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
      INSERT INTO public.opportunity_detail_projections_v3(
        run_id,symbol,contract_version,payload_canonical,payload_json,payload_hash
      ) VALUES(
        v_job.run_id,v_detail->>'symbol','opportunity-detail-v3.3',
        convert_to(v_row_text,'utf8'),v_detail,v_row_hash
      );
    END LOOP;
  ELSIF v_stage.output_kind='outcome_batch' THEN
    FOR v_row IN SELECT value FROM jsonb_array_elements(v_stage.output_json->5) LOOP
      IF jsonb_typeof(v_row)<>'object' THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
      END IF;
      v_row_text:=regexp_replace(v_row::text,', ', ',', 'g');
      v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
      INSERT INTO public.opportunity_outcomes(
        score_snapshot_id,maturity_horizon,entry_session,entry_session_authority_hash,
        maturity_session,maturity_session_authority_hash,entry_price_ref,outcome_price_ref,
        sector_benchmark_manifest_id,return_pct,sector_relative_return_pct,mfe_pct,mae_pct,
        sector_relative_mfe_pct,payload_canonical,payload_json,payload_hash
      ) VALUES(
        (v_row->>'scoreSnapshotId')::uuid,(v_row->>'maturityHorizon')::public.opportunity_outcome_maturity_v3,
        (v_row->>'entrySession')::date,v_row->>'entrySessionAuthorityHash',
        (v_row->>'maturitySession')::date,v_row->>'maturitySessionAuthorityHash',
        v_row->>'entryPriceRef',v_row->>'outcomePriceRef',(v_row->>'sectorBenchmarkManifestId')::uuid,
        (v_row->>'returnPct')::double precision,(v_row->>'sectorRelativeReturnPct')::double precision,
        (v_row->>'mfePct')::double precision,(v_row->>'maePct')::double precision,
        CASE WHEN v_row->>'sectorRelativeMfePct' IS NULL THEN NULL
          ELSE (v_row->>'sectorRelativeMfePct')::double precision END,
        convert_to(v_row_text,'utf8'),v_row,v_row_hash
      );
    END LOOP;
  ELSIF v_stage.output_kind='evaluation_bundle' THEN
    v_row:=v_stage.output_json->5;
    IF jsonb_typeof(v_row)<>'object' OR v_row->>'status' NOT IN ('pass','fail')
      OR jsonb_typeof(v_row->'strategyRows')<>'array'
      OR jsonb_array_length(v_row->'strategyRows')<>3
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
    v_row_text:=regexp_replace(v_row::text,', ', ',', 'g');
    v_row_hash:=encode(extensions.digest(convert_to(v_row_text,'utf8'),'sha256'),'hex');
    INSERT INTO public.opportunity_evaluation_results_v3(
      run_id,job_id,status,payload_canonical,payload_json,payload_hash
    ) VALUES(
      v_job.run_id,v_job.job_id,v_row->>'status',
      convert_to(v_row_text,'utf8'),v_row,v_row_hash
    );
  END IF;
  FOR v_warning IN SELECT value FROM jsonb_array_elements(v_stage.output_json->6) LOOP
    INSERT INTO public.opportunity_run_warning_facts_v3(
      run_id,warning,producing_job_id,evidence_ref
    ) VALUES(
      v_job.run_id,(v_warning#>>'{}')::public.opportunity_engine_warning_v3,
      v_job.job_id,'job:'||v_job.job_id::text
    );
  END LOOP;
  INSERT INTO public.opportunity_job_results_v3(
    job_id,run_id,output_kind,output_canonical,output_json,output_hash,output_counts
  ) VALUES(v_job.job_id,v_job.run_id,v_stage.output_kind,v_stage.output_canonical,v_stage.output_json,v_stage.output_hash,v_stage.output_counts);
  UPDATE public.opportunity_run_jobs_v3 SET status='succeeded',output_kind=v_stage.output_kind,
    output_hash=v_stage.output_hash,output_counts=v_stage.output_counts,terminal_at=clock_timestamp(),
    owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
  WHERE opportunity_run_jobs_v3.job_id=$1;
  PERFORM public.enqueue_next_opportunity_job_v3_internal(v_job.run_id,$1);
  RETURN QUERY SELECT 'succeeded'::public.opportunity_job_status_v3;
END
$fn$;

CREATE OR REPLACE FUNCTION heartbeat_opportunity_job_v3(job_id uuid,owner_token text)
RETURNS TABLE(lease_expires_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_heartbeat_at timestamptz := clock_timestamp();
  v_expires timestamptz;
BEGIN
  SELECT LEAST(
    v_heartbeat_at + interval '90 seconds',
    j.attempt_started_at + interval '15 minutes'
  ) INTO v_expires
  FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased'
    AND j.lease_expires_at >= v_heartbeat_at
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
  END IF;
  UPDATE public.opportunity_run_jobs_v3
  SET heartbeat_at=v_heartbeat_at,lease_expires_at=v_expires
  WHERE opportunity_run_jobs_v3.job_id=$1;
  RETURN QUERY SELECT v_expires;
END
$fn$;

CREATE OR REPLACE FUNCTION seal_opportunity_run_inputs_v3(requested_run_id uuid,owner_token text)
RETURNS TABLE(disposition opportunity_seal_disposition_v3,run_id uuid,attempt_run_id uuid,logical_key text,status opportunity_run_status_v3)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_run public.opportunity_runs%ROWTYPE;
  v_job public.opportunity_run_jobs_v3%ROWTYPE;
  v_existing public.opportunity_runs%ROWTYPE;
  v_logical text;
  v_cutoff_text text;
  v_input_run_ids jsonb;
  v_manifest_bindings jsonb;
  v_calendar_bindings jsonb;
  v_static_identity_members jsonb := $identity$[
    ["acceptanceVersion","1.44.6"],
    ["analysisRevisionContractVersion","stock-analysis-revision-v3.11.2"],
    ["authoritySupersessionContractVersion","authority-supersession-v3.2"],
    ["controlPlaneContractVersion","opportunity-control-v3.3"],
    ["dataContractVersion","source-led-opportunity-v3.6"],
    ["decisionContractVersion","opportunity-decisions-v3.3"],
    ["detailContractVersion","opportunity-detail-v3.3"],
    ["discoveryCorrectnessContractVersion","stock-discovery-v3.11.1"],
    ["entityLinkContractVersion","entity-link-v3.1"],
    ["evaluationContractVersion","source-led-eval-v3.7"],
    ["factorCorrectnessContractVersion","opportunity-factor-correctness-v3.11.6"],
    ["featureScoringContractVersion","opportunity-features-v3.2"],
    ["financialInputContractVersion","opportunity-financial-inputs-v3.3"],
    ["hybridProductVersion","hybrid-product-v3.2"],
    ["instrumentRosterContractVersion","tw-instrument-roster-v3.0"],
    ["internalPrincipalContractVersion","internal-principal-v3.8"],
    ["jobGraphContractVersion","opportunity-job-graph-v3.15"],
    ["legacyCompatibilityContractVersion","legacy-compatibility-v3.2"],
    ["manifestStorageContractVersion","opportunity-manifest-storage-v3.10"],
    ["marketContextContractVersion","market-context-v3.6"],
    ["moverAuditPriceContractVersion","mover-audit-price-v3.3"],
    ["portfolioContextContractVersion","research-basket-v3.0"],
    ["postgresTypeContractVersion","opportunity-postgres-types-v3.21"],
    ["priceProviderAllowlistHash","48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e"],
    ["providerFieldAllowlistHash","fe78e0f8c5b0846f822f72c6b2356cac35ed5c00dd0bcd06f9a75b7c5b21d3f7"],
    ["publisherVerificationPolicyHash","2c4746cb02d98d402ecd1d0d980c91632b8105ab9fd2aec198e7789da603abba"],
    ["runtimeContractVersion","opportunity-runtime-v3.17"],
    ["sectorBenchmarkContractVersion","sector-benchmark-v3.1"],
    ["sectorCycleContractVersion","sector-cycle-v3.0"],
    ["sectorReferenceContractVersion","sector-reference-v3.1"],
    ["sectorTaxonomyContractVersion","tw-sector-taxonomy-v3.0"],
    ["sourceAdapterContractVersion","source-adapter-v3.3"],
    ["sourceAdapterRegistryHash","a14d4753f221a43fb0422710e705ee00f529d9f31653a142211fe94596da80fe"],
    ["sourceDatasetContractVersion","source-dataset-v3.3"],
    ["sourceFunnelContractVersion","source-funnel-v3.0"],
    ["sourceFunnelPolicyHash","6893fb5f265edc10eea8222a560f9afdcc4342f72b1d7d39d5723ec0056bc105"],
    ["storageContractVersion","opportunity-storage-v3.24"],
    ["taxonomyMapHash","6b28d85903d7a410eef29386de011c71aa789dc0ce3231df38cb4e085181060c"],
    ["technicalDecisionContractVersion","opportunity-technical-decision-v3.11.1"],
    ["tradingCalendarContractVersion","tw-trading-calendar-v3.4"],
    ["valuationContractVersion","opportunity-valuation-v3.4"]
  ]$identity$::jsonb;
BEGIN
  SELECT * INTO v_run FROM public.opportunity_runs r WHERE r.run_id=$1 FOR UPDATE;
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
    WHERE j.run_id=$1 AND j.stage='seal_inputs' AND j.status='leased'
      AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
      AND j.lease_expires_at >= clock_timestamp()
    FOR UPDATE;
  IF NOT FOUND OR v_run.status NOT IN ('preparing','running') THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.opportunity_run_manifest_inputs i
    JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
    WHERE i.run_id=$1 AND (m.status<>'complete' OR m.manifest_hash IS NULL)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch';
  END IF;
  v_cutoff_text := to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
  SELECT coalesce(jsonb_agg(i.input_run_id::text ORDER BY i.input_role,i.input_run_id),'[]'::jsonb)
    INTO v_input_run_ids
  FROM public.opportunity_run_inputs i
  WHERE i.run_id=$1;
  SELECT coalesce(jsonb_agg(
    jsonb_build_array(i.input_role::text,i.ordinal,m.manifest_hash)
    ORDER BY i.input_role,i.ordinal
  ),'[]'::jsonb)
    INTO v_manifest_bindings
  FROM public.opportunity_run_manifest_inputs i
  JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
  WHERE i.run_id=$1;
  SELECT coalesce(jsonb_agg(binding ORDER BY kind_order,ordinal),'[]'::jsonb)
    INTO v_calendar_bindings
  FROM (
    SELECT
      i.input_role AS kind_order,
      i.ordinal,
      jsonb_build_array(
        i.input_role::text,
        i.ordinal,
        coalesce((
          SELECT jsonb_agg(pair->1 ORDER BY pair->>0)
          FROM jsonb_array_elements(m.header_json) pair
          WHERE jsonb_typeof(pair)='array'
            AND jsonb_array_length(pair)=2
            AND pair->>0 ~ 'SessionAuthorityHash$'
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(pair->1 ORDER BY pair->>0)
          FROM jsonb_array_elements(m.header_json) pair
          WHERE jsonb_typeof(pair)='array'
            AND jsonb_array_length(pair)=2
            AND pair->>0 ~ 'CalendarWindowHash$'
        ),'[]'::jsonb),
        coalesce((
          SELECT jsonb_agg(pair->1 ORDER BY pair->>0)
          FROM jsonb_array_elements(m.header_json) pair
          WHERE jsonb_typeof(pair)='array'
            AND jsonb_array_length(pair)=2
            AND pair->>0 ~ 'RecentSessionPlanHash$'
        ),'[]'::jsonb)
      ) AS binding
    FROM public.opportunity_run_manifest_inputs i
    JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
    WHERE i.run_id=$1
  ) bindings;
  IF v_run.selected_mover_audit_id IS NOT NULL THEN
    SELECT v_calendar_bindings || jsonb_build_array(jsonb_build_array(
      'mover_audit',
      0,
      jsonb_build_array(a.audited_session_authority_hash,a.previous_session_authority_hash),
      '[]'::jsonb,
      jsonb_build_array(a.recent_session_plan_hash)
    ))
      INTO v_calendar_bindings
    FROM public.opportunity_mover_audits_v3 a
    WHERE a.audit_id=v_run.selected_mover_audit_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
  END IF;
  v_logical := encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
    'opportunity-logical-run-v3.0',
    jsonb_build_array('mode',v_run.mode::text),
    jsonb_build_array('runPurpose',v_run.run_purpose::text),
    jsonb_build_array('sourceCutoff',v_cutoff_text),
    jsonb_build_array('inputRunIds',v_input_run_ids),
    jsonb_build_array('comparisonContractKey',v_run.comparison_contract_key),
    jsonb_build_array('evaluationDatasetLockHash',v_run.evaluation_dataset_lock_hash),
    jsonb_build_array('staticIdentityMembers',v_static_identity_members),
    jsonb_build_array('manifestBindings',v_manifest_bindings),
    jsonb_build_array('calendarBindings',v_calendar_bindings),
    jsonb_build_array('selectedMoverAuditId',v_run.selected_mover_audit_id)
  )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(v_logical,0));
  SELECT r.* INTO v_existing
  FROM public.opportunity_runs r
  WHERE r.logical_key=v_logical AND r.status='success' AND r.run_id<>$1
  ORDER BY r.terminal_at DESC,r.run_id ASC
  LIMIT 1
  FOR SHARE;
  IF FOUND THEN
    UPDATE public.opportunity_runs
    SET logical_key=v_logical,status='converged',canonical_run_id=v_existing.run_id,
      sealed_at=COALESCE(sealed_at,clock_timestamp()),terminal_at=clock_timestamp()
    WHERE opportunity_runs.run_id=$1;
    UPDATE public.opportunity_run_jobs_v3
    SET status='succeeded',output_hash=v_logical,terminal_at=clock_timestamp(),
      owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
    WHERE opportunity_run_jobs_v3.job_id=v_job.job_id;
    RETURN QUERY SELECT
      'converged'::public.opportunity_seal_disposition_v3,
      v_existing.run_id,$1,v_logical,'converged'::public.opportunity_run_status_v3;
    RETURN;
  END IF;
  UPDATE public.opportunity_runs SET logical_key=v_logical,status='running',sealed_at=COALESCE(sealed_at,clock_timestamp())
    WHERE opportunity_runs.run_id=$1;
  UPDATE public.opportunity_run_jobs_v3
    SET status='succeeded',output_hash=v_logical,terminal_at=clock_timestamp(),
      owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
    WHERE opportunity_run_jobs_v3.job_id=v_job.job_id;
  PERFORM public.enqueue_next_opportunity_job_v3_internal($1,v_job.job_id);
  RETURN QUERY SELECT 'sealed'::public.opportunity_seal_disposition_v3,$1,$1,v_logical,'running'::public.opportunity_run_status_v3;
END
$fn$;

CREATE OR REPLACE FUNCTION reap_opportunity_jobs_v3(caller_principal uuid)
RETURNS TABLE(requeued integer,failed integer,runs_failed integer)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE
  v_requeued integer := 0;
  v_failed integer := 0;
  v_runs_failed integer := 0;
  v_orphaned integer := 0;
  v_reap_at timestamptz := clock_timestamp();
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($1,'opportunity_runner',v_reap_at) THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable';
  END IF;
  DELETE FROM public.opportunity_job_staging_v3 s
  USING public.opportunity_run_jobs_v3 j,public.opportunity_runs r
  WHERE s.job_id=j.job_id
    AND s.attempt=j.attempt
    AND j.run_id=r.run_id
    AND j.status='leased'
    AND j.lease_expires_at<v_reap_at
    AND r.status IN ('preparing','running');
  WITH updated AS (
    UPDATE public.opportunity_run_jobs_v3
    SET status=CASE WHEN attempt < 5 THEN 'retryable'::public.opportunity_job_status_v3 ELSE 'failed'::public.opportunity_job_status_v3 END,
      failure_code=CASE WHEN attempt < 5 THEN NULL ELSE 'job_attempts_exhausted'::public.opportunity_failure_code_v3 END,
      terminal_at=CASE WHEN attempt < 5 THEN NULL ELSE v_reap_at END,
      owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
    WHERE status='leased' AND lease_expires_at < v_reap_at
    RETURNING status,run_id
  )
  SELECT count(*) FILTER (WHERE status='retryable'),count(*) FILTER (WHERE status='failed')
  INTO v_requeued,v_failed FROM updated;
  WITH failed_runs AS (
    UPDATE public.opportunity_runs r SET status='failed',failure_code='job_attempts_exhausted',terminal_at=v_reap_at
    WHERE r.status IN ('preparing','running') AND EXISTS (
      SELECT 1 FROM public.opportunity_run_jobs_v3 j WHERE j.run_id=r.run_id AND j.status='failed'
    ) RETURNING 1
  ) SELECT count(*) INTO v_runs_failed FROM failed_runs;
  WITH orphaned_runs AS (
    UPDATE public.opportunity_runs r
    SET status='failed',failure_code='orphaned_run',terminal_at=v_reap_at
    WHERE r.status IN ('preparing','running')
      AND (
        EXISTS (
          SELECT 1
          FROM public.opportunity_run_jobs_v3 j
          LEFT JOIN public.opportunity_job_payloads_v3 p ON p.job_id=j.job_id
          WHERE j.run_id=r.run_id AND p.job_id IS NULL
        )
        OR NOT EXISTS (
          SELECT 1
          FROM public.opportunity_run_jobs_v3 j
          WHERE j.run_id=r.run_id AND j.status IN ('queued','retryable','leased')
        )
      )
    RETURNING 1
  )
  SELECT count(*) INTO v_orphaned FROM orphaned_runs;
  v_runs_failed := v_runs_failed + v_orphaned;
  RETURN QUERY SELECT v_requeued,v_failed,v_runs_failed;
END
$fn$;

CREATE OR REPLACE FUNCTION finalize_opportunity_run_v3(job_id uuid,owner_token text)
RETURNS TABLE(run_id uuid,status opportunity_run_status_v3,failure_code opportunity_failure_code_v3,terminal_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $fn$
DECLARE v_job public.opportunity_run_jobs_v3%ROWTYPE; v_terminal timestamptz := clock_timestamp();
  v_mode public.opportunity_mode_v3;
  v_failure public.opportunity_failure_code_v3;
BEGIN
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.stage='finalize' AND j.status='leased'
    AND j.lease_expires_at >= v_terminal
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
  END IF;
  BEGIN
    IF EXISTS (SELECT 1 FROM public.opportunity_run_jobs_v3 j WHERE j.run_id=v_job.run_id AND j.job_id<>v_job.job_id AND j.status NOT IN ('succeeded','cancelled')) THEN
      RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='conservation_failure';
    END IF;
    SELECT r.mode INTO STRICT v_mode FROM public.opportunity_runs r
    WHERE r.run_id=v_job.run_id AND r.status='running' FOR UPDATE;
    IF v_mode='source_scan' AND (
    (SELECT count(*) FROM public.opportunity_job_results_v3 r
      WHERE r.run_id=v_job.run_id AND r.output_kind='source_parse_batch')
      <>(SELECT coalesce(sum(a.selected_document_count),0)
        FROM public.opportunity_source_connector_accounting a WHERE a.run_id=v_job.run_id)
    OR (SELECT count(*) FROM public.opportunity_job_results_v3 r
      WHERE r.run_id=v_job.run_id AND r.output_kind='source_connector_summary')<>11
    OR (SELECT count(*) FROM public.opportunity_source_connector_accounting a
      WHERE a.run_id=v_job.run_id)<>11
    OR (SELECT coalesce(sum((r.output_counts).connector_accounting_count),0)
      FROM public.opportunity_job_results_v3 r WHERE r.run_id=v_job.run_id)<>11
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
    ELSIF v_mode='enrich_rank' AND (
    EXISTS (
      SELECT 1 FROM (VALUES
        ('market_context_snapshot'::public.opportunity_job_output_kind_v3),
        ('portfolio_allocation_batch'::public.opportunity_job_output_kind_v3),
        ('projection_bundle'::public.opportunity_job_output_kind_v3)
      ) required(kind)
      WHERE (SELECT count(*) FROM public.opportunity_job_results_v3 r
        WHERE r.run_id=v_job.run_id AND r.output_kind=required.kind)<>1
    )
    OR (SELECT count(*) FROM public.opportunity_job_results_v3 r
      WHERE r.run_id=v_job.run_id AND r.output_kind='shallow_candidate_batch')>6
    OR (SELECT count(*) FROM public.opportunity_job_results_v3 r
      WHERE r.run_id=v_job.run_id AND r.output_kind='deep_candidate_batch')>4
    OR (SELECT coalesce(sum((r.output_counts).public_projection_count),0)
      FROM public.opportunity_job_results_v3 r WHERE r.run_id=v_job.run_id)<>1
    OR (SELECT coalesce(sum((r.output_counts).candidate_count),0)
      FROM public.opportunity_job_results_v3 r
      WHERE r.run_id=v_job.run_id AND r.output_kind='deep_candidate_batch')
      > (SELECT coalesce(sum((r.output_counts).candidate_count),0)
        FROM public.opportunity_job_results_v3 r
        WHERE r.run_id=v_job.run_id AND r.output_kind='shallow_candidate_batch')
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
    ELSIF v_mode='label_outcomes' AND (
    SELECT coalesce(sum((r.output_counts).outcome_count),0)
      <>(SELECT count(*) FROM public.opportunity_manifest_rows_v3 mr
        JOIN public.opportunity_run_manifest_inputs i ON i.manifest_id=mr.manifest_id
        WHERE i.run_id=v_job.run_id AND i.input_role='outcome_input'
          AND mr.section_key='input_rows')
    FROM public.opportunity_job_results_v3 r
    WHERE r.run_id=v_job.run_id AND r.output_kind='outcome_batch'
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
    ELSIF v_mode='shadow_evaluate' AND (
    SELECT count(*)<>1 FROM public.opportunity_job_results_v3 r
    WHERE r.run_id=v_job.run_id AND r.output_kind='evaluation_bundle'
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
    END IF;
  EXCEPTION
    WHEN SQLSTATE 'PT409' OR no_data_found OR too_many_rows THEN
      v_failure := CASE
        WHEN SQLERRM='conservation_failure' THEN 'conservation_failure'::public.opportunity_failure_code_v3
        ELSE 'data_integrity_failure'::public.opportunity_failure_code_v3
      END;
      v_terminal := clock_timestamp();
      UPDATE public.opportunity_run_jobs_v3
      SET status='failed',failure_code=v_failure,terminal_at=v_terminal,
        owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
      WHERE opportunity_run_jobs_v3.job_id=v_job.job_id;
      UPDATE public.opportunity_runs
      SET status='failed',failure_code=v_failure,terminal_at=v_terminal
      WHERE opportunity_runs.run_id=v_job.run_id AND status='running';
      RETURN QUERY
      SELECT r.run_id,r.status,r.failure_code,r.terminal_at
      FROM public.opportunity_runs r WHERE r.run_id=v_job.run_id;
      RETURN;
  END;
  UPDATE public.opportunity_run_jobs_v3 SET status='succeeded',terminal_at=v_terminal,
    owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL WHERE opportunity_run_jobs_v3.job_id=v_job.job_id;
  UPDATE public.opportunity_runs SET status='success', terminal_at=v_terminal
    WHERE opportunity_runs.run_id=v_job.run_id AND opportunity_runs.status='running';
  RETURN QUERY SELECT r.run_id,r.status,r.failure_code,r.terminal_at FROM public.opportunity_runs r WHERE r.run_id=v_job.run_id;
END
$fn$;

