  END LOOP;
END
$rls$;

DO $binding_policy$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policy p
    JOIN pg_class c ON c.oid=p.polrelid
    JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='public' AND c.relname='internal_principal_role_bindings_v3'
      AND p.polname='opportunity_v3_rpc_owner_binding_select'
  ) THEN
    CREATE POLICY opportunity_v3_rpc_owner_binding_select
      ON public.internal_principal_role_bindings_v3
      FOR SELECT TO opportunity_v3_rpc_owner USING (true);
  END IF;
END
$binding_policy$;

