    'public.stage_opportunity_job_output_v3(uuid,text,opportunity_job_output_kind_v3,bytea,jsonb,text,opportunity_job_counts_v3)',
    'public.create_opportunity_manifest_v3(uuid,text,uuid,opportunity_manifest_kind_v3,text,timestamptz,bytea,jsonb)',
    'public.append_opportunity_manifest_page_v3(uuid,text,uuid,opportunity_manifest_section_key_v3,integer,bigint,bytea,jsonb,text,opportunity_manifest_row_input_v3[])',
    'public.complete_opportunity_manifest_v3(uuid,text,uuid,bigint,bytea,jsonb,text)',
    'public.fail_opportunity_manifest_v3(uuid,text,uuid,opportunity_manifest_failure_code_v3)',
    'public.complete_opportunity_job_v3(uuid,text,text,opportunity_job_counts_v3)',
    'public.fail_opportunity_job_v3(uuid,text,opportunity_failure_code_v3)',
    'public.reap_opportunity_jobs_v3(uuid)',
    'public.finalize_opportunity_run_v3(uuid,text)',
    'public.select_opportunity_public_projection_v3(timestamptz)'
  ] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO opportunity_v3_rpc_owner',signature);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',signature);
  END LOOP;
END
