-- V3.11 tracked legacy-correctness producer. This plane is deliberately separate
-- from the disabled V3 run graph and exposes mutation only through ten RPCs.
DO $legacy_correctness_owner$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='legacy_correctness_rpc_owner') THEN
    CREATE ROLE legacy_correctness_rpc_owner NOLOGIN NOBYPASSRLS;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='legacy_correctness_rpc_owner' AND (rolcanlogin OR rolbypassrls)) THEN
    RAISE EXCEPTION 'legacy correctness owner attributes invalid';
  END IF;
END
$legacy_correctness_owner$;
GRANT legacy_correctness_rpc_owner TO CURRENT_USER;
GRANT USAGE ON SCHEMA public,extensions TO legacy_correctness_rpc_owner;
GRANT CREATE ON SCHEMA public TO legacy_correctness_rpc_owner;
GRANT EXECUTE ON FUNCTION extensions.digest(bytea,text),extensions.gen_random_uuid() TO legacy_correctness_rpc_owner;

DO $legacy_correctness_types$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname='opportunity_candidate_discovery_disposition_v3_11') THEN
    CREATE TYPE opportunity_candidate_discovery_disposition_v3_11 AS ENUM ('promoted','refreshed','unchanged','rejected');
    CREATE TYPE opportunity_candidate_discovery_reason_v3_11 AS ENUM ('new_in_seed_symbol','new_out_of_seed_symbol','new_source_evidence','material_source_change','same_material_evidence','duplicate_claim','ambiguous_symbol','low_confidence','unsupported_instrument','missing_instrument_authority','source_unavailable','parse_failure','deferred_due_scan_cap','candidate_cap','shallow_cap');
    CREATE TYPE opportunity_candidate_research_disposition_v3_11 AS ENUM ('deep_researched','source_signal_only','not_selected');
    CREATE TYPE opportunity_candidate_research_reason_v3_11 AS ENUM ('candidate_cap','shallow_cap','deep_cap');
    CREATE TYPE opportunity_candidate_seed_membership_v3_11 AS ENUM ('in_seed','out_of_seed');
    CREATE TYPE opportunity_research_maturity_v3_11 AS ENUM ('source_signal','fundamental_review','decision_ready');
    CREATE TYPE opportunity_analysis_evaluation_disposition_v3_11 AS ENUM ('material_revision_created','no_material_change');
    CREATE TYPE opportunity_legacy_producer_stage_v3_11 AS ENUM ('source_sync','mention_claim_extraction','candidate_funnel','facts_refresh','analysis_revision','compact_radar_projection');
    CREATE TYPE opportunity_legacy_producer_job_kind_v3_11 AS ENUM ('stage_barrier','revision_shard');
    CREATE TYPE opportunity_legacy_authority_page_kind_v3_11 AS ENUM ('roster','alias','taxonomy','selected_revision');
    CREATE TYPE opportunity_legacy_producer_job_status_v3_11 AS ENUM ('queued','leased','retryable','succeeded','failed','cancelled');
    CREATE TYPE opportunity_legacy_producer_failure_code_v3_11 AS ENUM ('provider_unavailable','data_integrity_failure','job_attempts_exhausted','lease_expired','cancelled');
    CREATE TYPE candidate_discovery_input_v3_11 AS (
      source_run_id uuid,source_key source_key_v3,document_revision_id uuid,claim_id uuid,mention_id uuid,
      stock_id uuid,symbol text,disposition opportunity_candidate_discovery_disposition_v3_11,
      reason opportunity_candidate_discovery_reason_v3_11,research_disposition opportunity_candidate_research_disposition_v3_11,
      research_reason opportunity_candidate_research_reason_v3_11,material_evidence_hash text
    );
    CREATE TYPE analysis_revision_input_v3_11 AS (
      symbol text,source_cutoff timestamptz,material_change_hash text,prior_revision_id uuid,
      research_maturity opportunity_research_maturity_v3_11,formal_research_status text,new_position_action text,
      fundamental_snapshot_hash text,technical_decision_hash text,valuation_input_hash text,locked_claims jsonb,
      narrative_template_version text,sentence_claim_refs jsonb,narrative text,narrative_hash text,
      analysis_generated_at timestamptz,producer_commit_sha text
    );
    CREATE TYPE analysis_evaluation_input_v3_11 AS (
      symbol text,revision_id uuid,evaluated_material_change_hash text,disposition opportunity_analysis_evaluation_disposition_v3_11,
      evaluated_source_cutoff timestamptz,evaluated_price_session date,evaluated_adjusted_close double precision,
      evaluated_at timestamptz,trigger text
    );
    CREATE TYPE legacy_radar_projection_input_v3_11 AS (
      projection_key text,"window" text,as_of timestamptz,producer_commit_sha text,worker_sha256 text,
      material_change_root text,payload_canonical bytea,payload_json jsonb,payload_sha256 text
    );
    CREATE TYPE legacy_scheduled_occurrence_v3_11 AS (
      scheduled_occurrence_id text,source_cutoff timestamptz,trading_date date,trading_session_authority_hash text
    );
    CREATE TYPE legacy_producer_lease_v3_11 AS (
      run_id uuid,job_id uuid,disposition text,source_cutoff timestamptz,authority_hash text
    );
    CREATE TYPE legacy_producer_claim_v3_11 AS (
      run_id uuid,job_id uuid,stage opportunity_legacy_producer_stage_v3_11,job_kind opportunity_legacy_producer_job_kind_v3_11,
      stage_ordinal smallint,shard_ordinal integer,execution_ordinal integer,revision_id uuid,attempt smallint,
      payload_canonical bytea,payload_json jsonb,payload_hash text,predecessor_result_canonical bytea,
      predecessor_result_json jsonb,predecessor_result_hash text,authority_kind text,authority_canonical bytea,
      authority_json jsonb,authority_hash text,frozen_revision_canonical bytea,frozen_revision_json jsonb,
      frozen_revision_hash text,read_kind text,read_canonical bytea,read_json jsonb,read_hash text,
      read_row_count integer,lease_expires_at timestamptz
    );
    CREATE TYPE legacy_discovery_authority_page_v3_11 AS (
      page_kind opportunity_legacy_authority_page_kind_v3_11,page_ordinal integer,first_row_ordinal integer,row_count integer,
      page_canonical bytea,page_json jsonb,page_hash text,kind_row_count integer,kind_page_count integer,kind_root_hash text,
      authority_header_canonical bytea,authority_header_json jsonb,authority_header_hash text
    );
    CREATE TYPE legacy_frozen_revision_read_v3_11 AS (
      run_id uuid,job_id uuid,selection_ordinal integer,source_key source_key_v3,revision_id uuid,
      selected_revision_row_hash text,raw_field_payload jsonb,raw_code_point_count integer,
      raw_field_payload_algorithm_version text,ingestion_content_revision_sha256 text,
      canonical_content_algorithm_version text,ingestion_canonical_content_hash_v3 text
    );
  END IF;
END
$legacy_correctness_types$;

CREATE TABLE IF NOT EXISTS legacy_producer_runs_v3_11 (
  run_id uuid PRIMARY KEY,owner_label text NOT NULL CHECK(owner_label='com.stockinsider.auth-source-worker'),
  owner_token_hash text NOT NULL CHECK(owner_token_hash ~ '^[0-9a-f]{64}$'),producer_commit_sha text NOT NULL CHECK(producer_commit_sha ~ '^[0-9a-f]{40}$'),
  worker_sha256 text NOT NULL CHECK(worker_sha256 ~ '^[0-9a-f]{64}$'),scheduler_config_canonical bytea NOT NULL CHECK(octet_length(scheduler_config_canonical)=1226),
  scheduler_config_sha256 text NOT NULL CHECK(scheduler_config_sha256='1ead338d6a56194a51c64ac2adbf36551a410c327ce08ba18f9224e34471c3c2'),
  legacy_seed_symbols text[] NOT NULL CHECK(cardinality(legacy_seed_symbols)=30),legacy_seed_set_hash text NOT NULL CHECK(legacy_seed_set_hash='e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743'),
  scheduled_occurrence_id text NOT NULL,source_cutoff timestamptz NOT NULL,trading_date date,
  trading_session_authority_hash text,authority_canonical bytea NOT NULL,authority_json jsonb NOT NULL,
  authority_hash text NOT NULL CHECK(authority_hash ~ '^[0-9a-f]{64}$'),status text NOT NULL CHECK(status IN ('running','success','failed','cancelled')),
  started_at timestamptz NOT NULL,heartbeat_at timestamptz NOT NULL,lease_expires_at timestamptz NOT NULL,terminal_at timestamptz,
  failure_code opportunity_legacy_producer_failure_code_v3_11,logical_run_key text NOT NULL CHECK(logical_run_key ~ '^[0-9a-f]{64}$'),
  attempt smallint NOT NULL CHECK(attempt BETWEEN 1 AND 5),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(logical_run_key,attempt),CHECK((status='running' AND terminal_at IS NULL AND failure_code IS NULL) OR (status<>'running' AND terminal_at IS NOT NULL)),
  CHECK(terminal_at IS NULL OR terminal_at>=started_at),CHECK(convert_from(authority_canonical,'utf8')::jsonb=authority_json),
  CHECK(encode(extensions.digest(authority_canonical,'sha256'),'hex')=authority_hash)
);
CREATE UNIQUE INDEX IF NOT EXISTS legacy_producer_single_owner_v3_11 ON legacy_producer_runs_v3_11((owner_label)) WHERE status='running';

CREATE TABLE IF NOT EXISTS legacy_producer_authority_pages_v3_11 (
  run_id uuid NOT NULL REFERENCES legacy_producer_runs_v3_11(run_id) ON DELETE RESTRICT,page_kind opportunity_legacy_authority_page_kind_v3_11 NOT NULL,
  page_ordinal integer NOT NULL CHECK(page_ordinal>=0),first_row_ordinal integer NOT NULL CHECK(first_row_ordinal>=0),row_count integer NOT NULL CHECK(row_count BETWEEN 0 AND 500),
  page_canonical bytea NOT NULL CHECK(octet_length(page_canonical)<=3145728),page_json jsonb NOT NULL,page_hash text NOT NULL CHECK(page_hash ~ '^[0-9a-f]{64}$'),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(run_id,page_kind,page_ordinal),CHECK(convert_from(page_canonical,'utf8')::jsonb=page_json),
  CHECK(encode(extensions.digest(page_canonical,'sha256'),'hex')=page_hash),CHECK(page_kind<>'selected_revision' OR row_count<=200)
);
CREATE TABLE IF NOT EXISTS legacy_frozen_source_revisions_v3_11 (
  run_id uuid NOT NULL REFERENCES legacy_producer_runs_v3_11(run_id) ON DELETE RESTRICT,selection_ordinal integer NOT NULL CHECK(selection_ordinal>=0),
  source_key source_key_v3 NOT NULL,revision_id uuid NOT NULL REFERENCES source_document_revisions_v3(revision_id) ON DELETE RESTRICT,
  selected_revision_row_canonical bytea NOT NULL,selected_revision_row_json jsonb NOT NULL,selected_revision_row_hash text NOT NULL CHECK(selected_revision_row_hash ~ '^[0-9a-f]{64}$'),
  raw_field_payload_algorithm_version text NOT NULL,ingestion_content_revision_sha256 text NOT NULL,canonical_content_algorithm_version text NOT NULL,
  canonical_content_sha256 text,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(run_id,selection_ordinal),UNIQUE(run_id,revision_id),
  CHECK(convert_from(selected_revision_row_canonical,'utf8')::jsonb=selected_revision_row_json),
  CHECK(encode(extensions.digest(selected_revision_row_canonical,'sha256'),'hex')=selected_revision_row_hash),
  CHECK(canonical_content_sha256 IS NULL OR canonical_content_sha256 ~ '^[0-9a-f]{64}$')
);
CREATE TABLE IF NOT EXISTS legacy_producer_jobs_v3_11 (
  job_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES legacy_producer_runs_v3_11(run_id) ON DELETE RESTRICT,
  stage opportunity_legacy_producer_stage_v3_11 NOT NULL,job_kind opportunity_legacy_producer_job_kind_v3_11 NOT NULL,
  stage_ordinal smallint NOT NULL CHECK(stage_ordinal BETWEEN 0 AND 5),shard_ordinal integer,execution_ordinal integer NOT NULL CHECK(execution_ordinal>=0),
  revision_id uuid,predecessor_job_id uuid REFERENCES legacy_producer_jobs_v3_11(job_id) ON DELETE RESTRICT,
  input_hash text NOT NULL CHECK(input_hash ~ '^[0-9a-f]{64}$'),payload_hash text NOT NULL CHECK(payload_hash ~ '^[0-9a-f]{64}$'),
  status opportunity_legacy_producer_job_status_v3_11 NOT NULL,attempt smallint NOT NULL CHECK(attempt BETWEEN 0 AND 5),max_attempts smallint NOT NULL CHECK(max_attempts=5),
  owner_token_hash text,leased_at timestamptz,heartbeat_at timestamptz,lease_expires_at timestamptz,terminal_at timestamptz,
  failure_code opportunity_legacy_producer_failure_code_v3_11,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(run_id,execution_ordinal),UNIQUE(run_id,input_hash),CHECK((job_kind='revision_shard')=(stage='mention_claim_extraction' AND shard_ordinal IS NOT NULL AND revision_id IS NOT NULL)),
  CHECK((status='leased')=(owner_token_hash IS NOT NULL AND leased_at IS NOT NULL AND lease_expires_at IS NOT NULL)),
  CHECK((status IN ('succeeded','failed','cancelled'))=(terminal_at IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS legacy_producer_single_lease_v3_11 ON legacy_producer_jobs_v3_11(run_id) WHERE status='leased';
CREATE TABLE IF NOT EXISTS legacy_producer_job_payloads_v3_11 (
  job_id uuid PRIMARY KEY REFERENCES legacy_producer_jobs_v3_11(job_id) ON DELETE RESTRICT,payload_canonical bytea NOT NULL CHECK(octet_length(payload_canonical)<=3145728),
  payload_json jsonb NOT NULL,payload_hash text NOT NULL CHECK(payload_hash ~ '^[0-9a-f]{64}$'),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK(convert_from(payload_canonical,'utf8')::jsonb=payload_json),CHECK(encode(extensions.digest(payload_canonical,'sha256'),'hex')=payload_hash)
);
CREATE TABLE IF NOT EXISTS legacy_producer_job_results_v3_11 (
  job_id uuid PRIMARY KEY REFERENCES legacy_producer_jobs_v3_11(job_id) ON DELETE RESTRICT,result_canonical bytea NOT NULL CHECK(octet_length(result_canonical)<=3145728),
  result_json jsonb NOT NULL,result_hash text NOT NULL CHECK(result_hash ~ '^[0-9a-f]{64}$'),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK(convert_from(result_canonical,'utf8')::jsonb=result_json),CHECK(encode(extensions.digest(result_canonical,'sha256'),'hex')=result_hash)
);
CREATE TABLE IF NOT EXISTS legacy_candidate_discovery_ledger_v3_11 (
  discovery_id uuid PRIMARY KEY,source_run_id uuid NOT NULL REFERENCES legacy_producer_runs_v3_11(run_id) ON DELETE RESTRICT,source_key source_key_v3 NOT NULL,
  document_revision_id uuid,claim_id uuid,mention_id uuid,stock_id uuid,symbol text,disposition opportunity_candidate_discovery_disposition_v3_11 NOT NULL,
  reason opportunity_candidate_discovery_reason_v3_11 NOT NULL,research_disposition opportunity_candidate_research_disposition_v3_11 NOT NULL,
  research_reason opportunity_candidate_research_reason_v3_11,seed_membership opportunity_candidate_seed_membership_v3_11,legacy_seed_set_hash text,
  material_evidence_hash text NOT NULL CHECK(material_evidence_hash ~ '^[0-9a-f]{64}$'),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(source_run_id,source_key,document_revision_id,claim_id,mention_id,stock_id,reason),
  CHECK((stock_id IS NULL AND symbol IS NULL AND seed_membership IS NULL AND legacy_seed_set_hash IS NULL) OR (stock_id IS NOT NULL AND symbol IS NOT NULL AND seed_membership IS NOT NULL AND legacy_seed_set_hash IS NOT NULL))
);
CREATE TABLE IF NOT EXISTS legacy_analysis_revisions_v3_11 (
  revision_id uuid PRIMARY KEY,symbol text NOT NULL,source_cutoff timestamptz NOT NULL,material_change_hash text NOT NULL CHECK(material_change_hash ~ '^[0-9a-f]{64}$'),
  prior_revision_id uuid REFERENCES legacy_analysis_revisions_v3_11(revision_id) ON DELETE RESTRICT,research_maturity opportunity_research_maturity_v3_11 NOT NULL,
  formal_research_status text NOT NULL CHECK(formal_research_status IN ('normal','valuation_review')),
  new_position_action text NOT NULL CHECK(new_position_action IN ('avoid','valuation_review','wait_trigger','event_starter','starter_now')),
  fundamental_snapshot_hash text NOT NULL,technical_decision_hash text,valuation_input_hash text,
  locked_claims jsonb NOT NULL,narrative_template_version text NOT NULL,sentence_claim_refs jsonb NOT NULL,narrative text NOT NULL,narrative_hash text NOT NULL,
  analysis_generated_at timestamptz NOT NULL,producer_commit_sha text NOT NULL CHECK(producer_commit_sha ~ '^[0-9a-f]{40}$'),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(symbol,material_change_hash)
);
CREATE TABLE IF NOT EXISTS legacy_analysis_evaluations_v3_11 (
  evaluation_id uuid PRIMARY KEY,symbol text NOT NULL,revision_id uuid NOT NULL REFERENCES legacy_analysis_revisions_v3_11(revision_id) ON DELETE RESTRICT,
  evaluated_material_change_hash text NOT NULL,disposition opportunity_analysis_evaluation_disposition_v3_11 NOT NULL,evaluated_at timestamptz NOT NULL,
  evaluated_source_cutoff timestamptz NOT NULL,evaluated_price_session date,evaluated_adjusted_close double precision,trigger text NOT NULL,
  producer_run_id uuid NOT NULL REFERENCES legacy_producer_runs_v3_11(run_id) ON DELETE RESTRICT,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(producer_run_id,symbol),CHECK((evaluated_price_session IS NULL)=(evaluated_adjusted_close IS NULL)),CHECK(evaluated_adjusted_close IS NULL OR evaluated_adjusted_close>0)
);
CREATE TABLE IF NOT EXISTS legacy_radar_projections_v3_11 (
  projection_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),projection_key text UNIQUE NOT NULL,"window" text NOT NULL CHECK("window" IN ('daily','three_day','weekly','home')),
  as_of timestamptz NOT NULL,producer_commit_sha text NOT NULL CHECK(producer_commit_sha ~ '^[0-9a-f]{40}$'),worker_sha256 text NOT NULL CHECK(worker_sha256 ~ '^[0-9a-f]{64}$'),
  material_change_root text NOT NULL CHECK(material_change_root ~ '^[0-9a-f]{64}$'),payload_canonical bytea NOT NULL CHECK(octet_length(payload_canonical)<=150000),
  payload_json jsonb NOT NULL,payload_sha256 text NOT NULL CHECK(payload_sha256 ~ '^[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK(convert_from(payload_canonical,'utf8')::jsonb=payload_json),CHECK(encode(extensions.digest(payload_canonical,'sha256'),'hex')=payload_sha256)
);
CREATE INDEX IF NOT EXISTS legacy_radar_projections_v3_11_window_read_idx ON legacy_radar_projections_v3_11("window",as_of DESC,created_at DESC,projection_id ASC);
CREATE TABLE IF NOT EXISTS legacy_runtime_health_observations_v3_11 (
  observation_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),
  producer_commit_sha text NOT NULL CHECK(producer_commit_sha ~ '^[0-9a-f]{40}$'),
  worker_sha256 text NOT NULL CHECK(worker_sha256 ~ '^[0-9a-f]{64}$'),
  scheduler_config_sha256 text NOT NULL CHECK(scheduler_config_sha256 ~ '^[0-9a-f]{64}$'),
  observation_canonical bytea NOT NULL CHECK(octet_length(observation_canonical) BETWEEN 2 AND 65536),
  observation_json jsonb NOT NULL,observation_sha256 text NOT NULL CHECK(observation_sha256 ~ '^[0-9a-f]{64}$'),
  observed_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(producer_commit_sha,observation_sha256),
  CHECK(convert_from(observation_canonical,'utf8')::jsonb=observation_json),
  CHECK(encode(extensions.digest(observation_canonical,'sha256'),'hex')=observation_sha256),
  CHECK(observation_json->>'producerCommitSha'=producer_commit_sha),
  CHECK(observation_json->>'workerSha256'=worker_sha256),
  CHECK(observation_json->>'schedulerConfigSha256'=scheduler_config_sha256)
);
CREATE INDEX IF NOT EXISTS legacy_runtime_health_observations_v3_11_latest_idx
  ON legacy_runtime_health_observations_v3_11(recorded_at DESC,observation_id);

CREATE OR REPLACE FUNCTION legacy_correctness_immutable_v3_11() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
  IF TG_OP='DELETE' AND current_setting('stockinsider.legacy_projection_retention',true)='on' THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'legacy_correctness_immutable';
END $$;
DO $legacy_immutable_triggers$
DECLARE v_table text;
BEGIN
  FOREACH v_table IN ARRAY ARRAY['legacy_producer_authority_pages_v3_11','legacy_frozen_source_revisions_v3_11','legacy_producer_job_payloads_v3_11','legacy_producer_job_results_v3_11','legacy_candidate_discovery_ledger_v3_11','legacy_analysis_revisions_v3_11','legacy_analysis_evaluations_v3_11','legacy_radar_projections_v3_11','legacy_runtime_health_observations_v3_11'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname=v_table||'_immutable') THEN
      EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.legacy_correctness_immutable_v3_11()',v_table||'_immutable',v_table);
    END IF;
  END LOOP;
END
$legacy_immutable_triggers$;

CREATE OR REPLACE FUNCTION resolve_legacy_scheduled_occurrence_v3_11(p_owner_label text,p_config_hash text)
RETURNS legacy_scheduled_occurrence_v3_11 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE
  v_now timestamptz:=date_trunc('second',clock_timestamp());v_local timestamp;v_date date;
  v_cutoff timestamptz;v_material_recorded_at timestamptz;v_material_cutoff timestamptz;
  v_id text;v_session_hash text;v_occurrence_kind text:='scheduled';
BEGIN
  IF p_owner_label<>'com.stockinsider.auth-source-worker' OR p_config_hash<>'1ead338d6a56194a51c64ac2adbf36551a410c327ce08ba18f9224e34471c3c2' THEN RETURN NULL; END IF;
  v_local:=v_now AT TIME ZONE 'Asia/Taipei';v_date:=v_local::date;
  IF extract(isodow FROM v_date)>5 OR v_local::time<time '18:20:00' THEN v_date:=v_date-1;END IF;
  WHILE extract(isodow FROM v_date)>5 LOOP v_date:=v_date-1;END LOOP;
  v_cutoff:=(v_date+time '18:20:00') AT TIME ZONE 'Asia/Taipei';
  SELECT max(recorded_at) INTO v_material_recorded_at FROM (
    SELECT max(recorded_at) recorded_at FROM public.stock_instruments_v3
      WHERE instrument_type='common_stock' AND listing_status='active'
    UNION ALL SELECT max(recorded_at) FROM public.stock_aliases_v3 WHERE status='active'
    UNION ALL SELECT max(recorded_at) FROM public.stock_sector_assignments_v3 WHERE status='active'
    UNION ALL SELECT max(recorded_at) FROM public.source_identity_authorities_v3 WHERE status='active'
    UNION ALL SELECT max(recorded_at) FROM public.source_document_revisions_v3 WHERE acquisition_status='complete'
  ) material;
  v_material_cutoff:=date_trunc('second',v_material_recorded_at)+interval '1 second';
  IF v_material_recorded_at>v_cutoff AND v_material_cutoff<=v_now THEN
    v_cutoff:=v_material_cutoff;
    v_occurrence_kind:='material-authority-refresh';
  END IF;
  SELECT session.taiwan_session_authority_hash INTO v_session_hash
  FROM public.opportunity_effective_taiwan_sessions_v3 session
  WHERE session.session_id=v_date AND session.canonical_cutoff<=v_cutoff;
  v_id:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
    'legacy-producer-scheduled-occurrence-v2',p_owner_label,v_date,'18:20:00','Asia/Taipei',
    v_occurrence_kind,to_char(v_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),p_config_hash
  )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');
  RETURN ROW(v_id,v_cutoff,CASE WHEN v_session_hash IS NULL THEN NULL ELSE v_date END,v_session_hash)::public.legacy_scheduled_occurrence_v3_11;
END $$;
CREATE OR REPLACE FUNCTION read_legacy_discovery_authority_v3_11(uuid,text,text)
RETURNS SETOF legacy_discovery_authority_page_v3_11 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE
  v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_kind public.opportunity_legacy_authority_page_kind_v3_11;
  v_size integer;v_count integer;v_pages integer;v_page integer;v_rows jsonb;v_all jsonb;v_page_bytes bytea;v_header jsonb;v_header_bytes bytea;
BEGIN
  SELECT * INTO v_run FROM public.legacy_producer_runs_v3_11 r WHERE r.run_id=$1 AND r.producer_commit_sha=$2 AND r.scheduler_config_sha256=$3 AND r.status='running';
  IF NOT FOUND THEN RETURN;END IF;
  v_header:=jsonb_build_object('schema','legacy-discovery-authority-v1','runId',v_run.run_id,'scheduledOccurrenceId',v_run.scheduled_occurrence_id,'sourceCutoff',to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  v_header_bytes:=convert_to(v_header::text,'utf8');
  FOREACH v_kind IN ARRAY ARRAY['roster','alias','taxonomy','selected_revision']::public.opportunity_legacy_authority_page_kind_v3_11[] LOOP
    v_size:=CASE WHEN v_kind='selected_revision' THEN 200 ELSE 500 END;
    IF v_kind='roster' THEN
      SELECT coalesce(jsonb_agg(jsonb_build_array(stock_id,symbol,exchange,instrument_type,listing_status,official_legal_name,official_short_name) ORDER BY symbol,stock_id),'[]'::jsonb)
      INTO v_all FROM public.stock_instruments_v3 WHERE instrument_type='common_stock' AND listing_status='active'
        AND source_timestamp<=v_run.source_cutoff AND recorded_at<=v_run.source_cutoff
        AND valid_from<=v_run.source_cutoff AND (valid_to IS NULL OR valid_to>v_run.source_cutoff);
    ELSIF v_kind='alias' THEN
      SELECT coalesce(jsonb_agg(jsonb_build_array(stock_id,normalized_alias,source) ORDER BY normalized_alias,stock_id),'[]'::jsonb)
      INTO v_all FROM public.stock_aliases_v3 WHERE status='active'
        AND source_timestamp<=v_run.source_cutoff AND approved_at<=v_run.source_cutoff AND recorded_at<=v_run.source_cutoff
        AND valid_from<=v_run.source_cutoff AND (valid_to IS NULL OR valid_to>v_run.source_cutoff);
    ELSIF v_kind='taxonomy' THEN
      SELECT coalesce(jsonb_agg(jsonb_build_array(stock_id,market,official_industry_code,canonical_sector_key) ORDER BY stock_id,canonical_sector_key),'[]'::jsonb)
      INTO v_all FROM public.stock_sector_assignments_v3 WHERE status='active'
        AND source_timestamp<=v_run.source_cutoff AND recorded_at<=v_run.source_cutoff
        AND valid_from<=v_run.source_cutoff AND (valid_to IS NULL OR valid_to>v_run.source_cutoff);
    ELSE
      WITH family_heads AS (
        SELECT d.*,row_number() OVER(PARTITION BY d.source_key,d.revision_family_key ORDER BY d.collected_at DESC,d.recorded_at DESC,d.revision_id) AS family_rank
        FROM public.source_document_revisions_v3 d
        JOIN public.source_revision_family_registry_v3 registry ON registry.source_key=d.source_key AND registry.revision_family_key=d.revision_family_key
          AND registry.approved_source_identity_id=d.approved_source_identity_id AND registry.stable_connector_document_id=d.stable_connector_document_id
        JOIN public.source_identity_authorities_v3 authority ON authority.authority_id=d.source_identity_authority_id
          AND authority.source_identity_id=d.approved_source_identity_id AND authority.source_key=d.source_key
        WHERE d.acquisition_status='complete' AND (d.published_at IS NULL OR d.published_at<=d.collected_at)
          AND d.collected_at<=v_run.source_cutoff AND d.recorded_at<=v_run.source_cutoff
          AND authority.status='active' AND authority.approved_at<=v_run.source_cutoff AND authority.recorded_at<=v_run.source_cutoff
          AND authority.valid_from<=v_run.source_cutoff AND (authority.valid_to IS NULL OR authority.valid_to>v_run.source_cutoff)
      ), connector_bound AS (
        SELECT f.*,row_number() OVER(PARTITION BY f.source_key ORDER BY f.collected_at DESC,f.revision_family_key,f.revision_id) AS connector_rank
        FROM family_heads f WHERE f.family_rank=1
      )
      SELECT coalesce(jsonb_agg(jsonb_build_array(source_key,revision_id,revision_family_key,approved_source_identity_id,stable_connector_document_id,published_at,collected_at,
        raw_field_payload_algorithm_version,ingestion_content_revision_sha256,canonical_content_algorithm_version,ingestion_canonical_content_hash_v3)
      ORDER BY source_key,collected_at DESC,revision_family_key,revision_id),'[]'::jsonb) INTO v_all FROM connector_bound WHERE connector_rank<=1000;
      IF EXISTS(
        WITH family_heads AS (
          SELECT d.source_key,d.revision_family_key,d.collected_at,d.recorded_at,d.revision_id,
            row_number() OVER(PARTITION BY d.source_key,d.revision_family_key ORDER BY d.collected_at DESC,d.recorded_at DESC,d.revision_id) family_rank
          FROM public.source_document_revisions_v3 d
          JOIN public.source_identity_authorities_v3 authority ON authority.authority_id=d.source_identity_authority_id
          WHERE d.acquisition_status='complete' AND (d.published_at IS NULL OR d.published_at<=d.collected_at)
            AND d.collected_at<=v_run.source_cutoff AND d.recorded_at<=v_run.source_cutoff
            AND authority.status='active' AND authority.approved_at<=v_run.source_cutoff AND authority.recorded_at<=v_run.source_cutoff
            AND authority.valid_from<=v_run.source_cutoff AND (authority.valid_to IS NULL OR authority.valid_to>v_run.source_cutoff)
        ), connector_bound AS (
          SELECT row_number() OVER(PARTITION BY source_key ORDER BY collected_at DESC,revision_family_key,revision_id) connector_rank
          FROM family_heads WHERE family_rank=1
        ) SELECT 1 FROM connector_bound WHERE connector_rank>1000
      ) THEN RAISE EXCEPTION 'bound_violation';END IF;
    END IF;
    v_count:=jsonb_array_length(v_all);v_pages:=greatest(1,ceil(v_count::numeric/v_size)::integer);
    FOR v_page IN 0..v_pages-1 LOOP
      SELECT coalesce(jsonb_agg(value ORDER BY ordinal),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(v_all) WITH ORDINALITY item(value,ordinal) WHERE ordinal>v_page*v_size AND ordinal<=(v_page+1)*v_size;
      v_page_bytes:=convert_to(v_rows::text,'utf8');
      RETURN NEXT ROW(v_kind,v_page,v_page*v_size,jsonb_array_length(v_rows),v_page_bytes,v_rows,encode(extensions.digest(v_page_bytes,'sha256'),'hex'),v_count,v_pages,
        encode(extensions.digest(convert_to(v_all::text,'utf8'),'sha256'),'hex'),v_header_bytes,v_header,encode(extensions.digest(v_header_bytes,'sha256'),'hex'))::public.legacy_discovery_authority_page_v3_11;
    END LOOP;
  END LOOP;
END $$;
CREATE OR REPLACE FUNCTION read_legacy_frozen_revision_v3_11(uuid,uuid,text,uuid,text)
RETURNS legacy_frozen_revision_read_v3_11 LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
  SELECT ROW(f.run_id,j.job_id,f.selection_ordinal,f.source_key,f.revision_id,f.selected_revision_row_hash,d.raw_field_payload,d.raw_code_point_count,
    d.raw_field_payload_algorithm_version,d.ingestion_content_revision_sha256,d.canonical_content_algorithm_version,d.ingestion_canonical_content_hash_v3)::public.legacy_frozen_revision_read_v3_11
  FROM public.legacy_frozen_source_revisions_v3_11 f
  JOIN public.legacy_producer_jobs_v3_11 j ON j.run_id=f.run_id AND j.revision_id=f.revision_id
  JOIN public.legacy_producer_runs_v3_11 r ON r.run_id=f.run_id
  JOIN public.source_document_revisions_v3 d ON d.revision_id=f.revision_id
  WHERE f.run_id=$1 AND j.job_id=$2 AND j.owner_token_hash=$3 AND j.status='leased' AND j.stage='mention_claim_extraction'
    AND j.job_kind='revision_shard' AND f.revision_id=$4 AND f.selected_revision_row_hash=$5 AND r.status='running'
    AND d.ingestion_content_revision_sha256=f.ingestion_content_revision_sha256 AND d.raw_field_payload_algorithm_version=f.raw_field_payload_algorithm_version
$$;

CREATE OR REPLACE FUNCTION read_legacy_candidate_fact_plane_v3_11(
  p_source_cutoff timestamptz,p_candidate_result jsonb
) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_result jsonb;v_candidates jsonb:=coalesce(p_candidate_result->'candidates','[]'::jsonb);
BEGIN
  IF jsonb_typeof(v_candidates)<>'array' OR jsonb_array_length(v_candidates)>60
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_candidates) item(value)
      WHERE jsonb_typeof(value)<>'object' OR (value->>'stockId')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        OR (value->>'symbol')!~'^[0-9]{4}$')
  THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  WITH candidates AS MATERIALIZED (
    SELECT value->>'stockId' AS stock_id,value->>'symbol' AS symbol,ordinality::integer AS ordinal,
      (value->>'deepSelected')::boolean AS deep_selected,(value->>'shallowSelected')::boolean AS shallow_selected
    FROM jsonb_array_elements(v_candidates) WITH ORDINALITY item(value,ordinality)
  ), facts AS MATERIALIZED (
    SELECT candidate.ordinal,candidate.symbol,fact.fact_key,fact.period_start,fact.period_end,fact.duration_kind,
      fact.value,fact.unit,fact.authority_tier,fact.filing_published_at,fact.source_timestamp,
      fact.collected_at,fact.recorded_at,fact.source_ref,fact.estimate_kind,fact.estimate_horizon
    FROM candidates candidate JOIN LATERAL (
      SELECT selected.* FROM public.opportunity_financial_facts_v3 selected
      WHERE selected.stock_id=candidate.stock_id::uuid AND selected.recorded_at<=p_source_cutoff
        AND selected.filing_published_at<=p_source_cutoff AND selected.source_timestamp<=p_source_cutoff
        AND selected.collected_at<=p_source_cutoff
      ORDER BY selected.fact_key,selected.period_end DESC,selected.filing_published_at DESC,
        selected.source_timestamp DESC,selected.collected_at DESC,selected.recorded_at DESC,
        selected.source_ref,selected.fact_id LIMIT 256
    ) fact ON candidate.deep_selected
  ), selected_prices AS MATERIALIZED (
    SELECT candidate.ordinal,candidate.symbol,selected.observation_id,selected.session_id,selected.volume,
      max(selected.session_id) OVER (PARTITION BY candidate.stock_id) AS anchor_session
    FROM candidates candidate JOIN LATERAL (
      SELECT bounded.* FROM (
        SELECT DISTINCT ON (price.session_id) price.*
        FROM public.opportunity_price_observations_v3 price
        WHERE price.stock_id=candidate.stock_id::uuid AND price.recorded_at<=p_source_cutoff
          AND price.source_timestamp<=p_source_cutoff AND price.collected_at<=p_source_cutoff
        ORDER BY price.session_id DESC,price.source_timestamp DESC,price.collected_at DESC,
          price.recorded_at DESC,price.source_ref,price.observation_id LIMIT 251
      ) bounded ORDER BY bounded.session_id
    ) selected ON candidate.shallow_selected
  ), prices AS MATERIALIZED (
    SELECT selected_prices.ordinal,selected_prices.symbol,selected_prices.session_id,selected_prices.volume,adjusted.payload
    FROM selected_prices LEFT JOIN LATERAL (
      SELECT public.opportunity_adjusted_price_evidence_v3_internal(
        selected_prices.observation_id,selected_prices.anchor_session,p_source_cutoff) AS payload
    ) adjusted ON true
  ), benchmark_ranked AS MATERIALIZED (
    SELECT observation.session_id,observation.value,observation.source_ref,
      row_number() OVER (PARTITION BY observation.session_id ORDER BY observation.observed_at DESC,
        observation.collected_at DESC,observation.recorded_at DESC,observation.source_ref,observation.observation_id) AS precedence
    FROM public.opportunity_market_observations_v3 observation
    WHERE observation.fact_key='taiex_close' AND observation.scope_key='TAIEX'
      AND observation.session_id IS NOT NULL AND observation.recorded_at<=p_source_cutoff
      AND observation.observed_at<=p_source_cutoff AND observation.collected_at<=p_source_cutoff
  ), benchmark AS MATERIALIZED (
    SELECT * FROM benchmark_ranked WHERE precedence=1 ORDER BY session_id DESC LIMIT 251
  )
  SELECT jsonb_build_object(
    'candidateResult',p_candidate_result,
    'financialRows',coalesce((SELECT jsonb_agg(jsonb_build_array(symbol,fact_key,period_start,period_end,
      duration_kind,value,unit,authority_tier,filing_published_at,source_timestamp,collected_at,recorded_at,
      source_ref,estimate_kind,estimate_horizon) ORDER BY ordinal,fact_key,period_end DESC,source_timestamp DESC,source_ref) FROM facts),'[]'::jsonb),
    'priceRows',coalesce((SELECT jsonb_agg(jsonb_build_array(symbol,session_id,
      (payload#>>'{evidence,11}')::double precision,(payload#>>'{evidence,12}')::double precision,
      (payload#>>'{evidence,13}')::double precision,(payload#>>'{evidence,14}')::double precision,
      volume,payload->>'ref') ORDER BY ordinal,session_id)
      FROM prices WHERE payload IS NOT NULL),'[]'::jsonb),
    'benchmarkRows',coalesce((SELECT jsonb_agg(jsonb_build_array(session_id,value,source_ref) ORDER BY session_id)
      FROM benchmark),'[]'::jsonb),
    'sourceCutoff',to_char(p_source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  ) INTO v_result;
  IF octet_length(convert_to(v_result::text,'utf8'))>3145728 THEN RAISE EXCEPTION 'bound_violation';END IF;
  RETURN v_result;
END $$;

CREATE OR REPLACE FUNCTION acquire_legacy_producer_lease_v3_11(p_owner text,p_commit text,p_worker text,p_config bytea,p_config_hash text,p_token uuid,p_lease integer)
RETURNS legacy_producer_lease_v3_11 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_now timestamptz:=date_trunc('second',clock_timestamp());v_occ public.legacy_scheduled_occurrence_v3_11;v_run uuid;v_job uuid;v_authority bytea;v_authority_json jsonb;v_authority_hash text;v_payload bytea;v_payload_json jsonb;v_payload_hash text;v_page public.legacy_discovery_authority_page_v3_11;v_pages jsonb:='[]'::jsonb;v_selected jsonb;v_selected_ordinal bigint;v_selected_bytes bytea;v_logical_key text;v_attempt smallint;v_uuid_hash text;v_token_hash text;
BEGIN
  IF p_owner<>'com.stockinsider.auth-source-worker' OR p_commit!~'^[0-9a-f]{40}$' OR p_worker!~'^[0-9a-f]{64}$' OR p_lease<>120 OR octet_length(p_config)<>1226
    OR p_config_hash<>'1ead338d6a56194a51c64ac2adbf36551a410c327ce08ba18f9224e34471c3c2' OR encode(extensions.digest(p_config,'sha256'),'hex')<>p_config_hash THEN RAISE EXCEPTION 'data_integrity_failure'; END IF;
  v_token_hash:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');
  SELECT run_id INTO v_run FROM public.legacy_producer_runs_v3_11 WHERE status='running' ORDER BY started_at,run_id LIMIT 1 FOR UPDATE;
  IF v_run IS NOT NULL THEN
    IF (SELECT lease_expires_at>=v_now FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run) THEN
      RETURN ROW(NULL,NULL,'owner_already_leased',NULL,NULL)::public.legacy_producer_lease_v3_11;
    END IF;
    IF EXISTS(SELECT 1 FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run
      AND (producer_commit_sha<>p_commit OR worker_sha256<>p_worker OR scheduler_config_sha256<>p_config_hash)) THEN
      UPDATE public.legacy_producer_jobs_v3_11 SET status='cancelled',terminal_at=v_now,failure_code='cancelled',
        owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL
        WHERE run_id=v_run AND status IN ('queued','leased','retryable');
      UPDATE public.legacy_producer_runs_v3_11 SET status='cancelled',terminal_at=v_now,failure_code='cancelled',
        heartbeat_at=v_now,lease_expires_at=v_now WHERE run_id=v_run;
      v_run:=NULL;
    ELSE
      UPDATE public.legacy_producer_jobs_v3_11 SET status='retryable',owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL
        WHERE run_id=v_run AND status='leased' AND lease_expires_at<v_now;
      UPDATE public.legacy_producer_runs_v3_11 SET owner_token_hash=v_token_hash,heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE run_id=v_run;
      SELECT job_id INTO v_job FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_run AND status IN ('queued','retryable') ORDER BY execution_ordinal LIMIT 1;
      RETURN ROW(v_run,v_job,'resumed',
        (SELECT source_cutoff FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run),
        (SELECT authority_hash FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run))::public.legacy_producer_lease_v3_11;
    END IF;
  END IF;
  v_occ:=public.resolve_legacy_scheduled_occurrence_v3_11(p_owner,p_config_hash);
  v_logical_key:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
    'legacy-producer-run-v3',v_occ.scheduled_occurrence_id,to_char(v_occ.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    v_occ.trading_date,v_occ.trading_session_authority_hash,p_commit,p_worker,p_config_hash,
    'e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743'
  )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');
  v_authority_json:=jsonb_build_object('schema','legacy-discovery-authority-v1','scheduledOccurrenceId',v_occ.scheduled_occurrence_id,'sourceCutoff',to_char(v_occ.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  v_authority:=convert_to(v_authority_json::text,'utf8');v_authority_hash:=encode(extensions.digest(v_authority,'sha256'),'hex');
  SELECT run_id INTO v_run FROM public.legacy_producer_runs_v3_11 WHERE logical_run_key=v_logical_key AND status='success' ORDER BY attempt DESC LIMIT 1;
  IF v_run IS NOT NULL THEN RETURN ROW(v_run,NULL,'retained_success',v_occ.source_cutoff,v_authority_hash)::public.legacy_producer_lease_v3_11; END IF;
  SELECT coalesce(max(attempt),0)+1 INTO v_attempt FROM public.legacy_producer_runs_v3_11 WHERE logical_run_key=v_logical_key;
  IF v_attempt>5 THEN RETURN ROW(NULL,NULL,'attempts_exhausted',v_occ.source_cutoff,v_authority_hash)::public.legacy_producer_lease_v3_11;END IF;
  v_uuid_hash:=encode(extensions.digest(convert_to('legacy-run:'||v_logical_key||':'||v_attempt,'utf8'),'sha256'),'hex');
  v_run:=(substr(v_uuid_hash,1,8)||'-'||substr(v_uuid_hash,9,4)||'-'||substr(v_uuid_hash,13,4)||'-'||substr(v_uuid_hash,17,4)||'-'||substr(v_uuid_hash,21,12))::uuid;
  v_uuid_hash:=encode(extensions.digest(convert_to('legacy-job:'||v_run::text||':0','utf8'),'sha256'),'hex');
  v_job:=(substr(v_uuid_hash,1,8)||'-'||substr(v_uuid_hash,9,4)||'-'||substr(v_uuid_hash,13,4)||'-'||substr(v_uuid_hash,17,4)||'-'||substr(v_uuid_hash,21,12))::uuid;
  INSERT INTO public.legacy_producer_runs_v3_11 VALUES(v_run,p_owner,encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex'),p_commit,p_worker,p_config,p_config_hash,
    ARRAY['2301','2303','2308','2330','2337','2344','2345','2356','2379','2382','2408','2421','2449','2454','3008','3017','3034','3037','3189','3231','3324','3533','3711','4958','5347','5388','6230','6285','6415','6669'],
    'e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743',v_occ.scheduled_occurrence_id,v_occ.source_cutoff,v_occ.trading_date,v_occ.trading_session_authority_hash,
    v_authority,v_authority_json,v_authority_hash,'running',v_now,v_now,v_now+interval '120 seconds',NULL,NULL,v_logical_key,v_attempt,v_now);
  FOR v_page IN SELECT * FROM public.read_legacy_discovery_authority_v3_11(v_run,p_commit,p_config_hash) LOOP
    INSERT INTO public.legacy_producer_authority_pages_v3_11 VALUES(v_run,v_page.page_kind,v_page.page_ordinal,v_page.first_row_ordinal,v_page.row_count,v_page.page_canonical,v_page.page_json,v_page.page_hash,v_now);
    v_pages:=v_pages||jsonb_build_array(jsonb_build_array(v_page.page_kind,v_page.page_ordinal,v_page.row_count,v_page.page_hash,v_page.kind_row_count,v_page.kind_page_count,v_page.kind_root_hash));
    IF v_page.page_kind='selected_revision' THEN
      FOR v_selected,v_selected_ordinal IN SELECT value,ordinality FROM jsonb_array_elements(v_page.page_json) WITH ORDINALITY AS selected(value,ordinality) LOOP
        IF jsonb_typeof(v_selected)<>'array' OR jsonb_array_length(v_selected)<>11 THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
        v_selected_bytes:=convert_to(v_selected::text,'utf8');
        INSERT INTO public.legacy_frozen_source_revisions_v3_11(run_id,selection_ordinal,source_key,revision_id,selected_revision_row_canonical,selected_revision_row_json,selected_revision_row_hash,raw_field_payload_algorithm_version,ingestion_content_revision_sha256,canonical_content_algorithm_version,canonical_content_sha256,recorded_at)
        VALUES(v_run,v_page.first_row_ordinal+v_selected_ordinal-1,(v_selected->>0)::public.source_key_v3,(v_selected->>1)::uuid,v_selected_bytes,v_selected,encode(extensions.digest(v_selected_bytes,'sha256'),'hex'),v_selected->>7,v_selected->>8,v_selected->>9,v_selected->>10,v_now);
      END LOOP;
    END IF;
  END LOOP;
  IF (SELECT count(DISTINCT page_kind) FROM public.legacy_producer_authority_pages_v3_11 WHERE run_id=v_run)<>4 THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  v_authority_json:=jsonb_build_object('schema','legacy-discovery-authority-v1','scheduledOccurrenceId',v_occ.scheduled_occurrence_id,'sourceCutoff',to_char(v_occ.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'pages',v_pages);
  v_authority:=convert_to(v_authority_json::text,'utf8');v_authority_hash:=encode(extensions.digest(v_authority,'sha256'),'hex');
  UPDATE public.legacy_producer_runs_v3_11 SET authority_canonical=v_authority,authority_json=v_authority_json,authority_hash=v_authority_hash WHERE run_id=v_run;
  v_payload_json:=jsonb_build_array('e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743',v_run,v_occ.scheduled_occurrence_id,to_char(v_occ.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),v_occ.trading_date,v_occ.trading_session_authority_hash,v_authority_hash);
  v_payload:=convert_to(v_payload_json::text,'utf8');v_payload_hash:=encode(extensions.digest(v_payload,'sha256'),'hex');
  INSERT INTO public.legacy_producer_jobs_v3_11 VALUES(v_job,v_run,'source_sync','stage_barrier',0,NULL,0,NULL,NULL,v_payload_hash,v_payload_hash,'queued',0,5,NULL,NULL,NULL,NULL,NULL,NULL,v_now);
  INSERT INTO public.legacy_producer_job_payloads_v3_11 VALUES(v_job,v_payload,v_payload_json,v_payload_hash,v_now);
  RETURN ROW(v_run,v_job,'created',v_occ.source_cutoff,v_authority_hash)::public.legacy_producer_lease_v3_11;
END $$;

CREATE OR REPLACE FUNCTION claim_legacy_producer_job_v3_11(p_run uuid,p_job uuid,p_token uuid,p_lease integer)
RETURNS legacy_producer_claim_v3_11 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_job public.legacy_producer_jobs_v3_11%ROWTYPE;v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_payload public.legacy_producer_job_payloads_v3_11%ROWTYPE;v_prior public.legacy_producer_job_results_v3_11%ROWTYPE;v_source_result public.legacy_producer_job_results_v3_11%ROWTYPE;v_frozen public.legacy_frozen_revision_read_v3_11;v_frozen_json jsonb;v_frozen_bytes bytea;v_frozen_hash text;v_now timestamptz:=date_trunc('second',clock_timestamp());v_hash text;v_selected_hash text;v_source_published_at timestamptz;v_source_collected_at timestamptz;v_read_kind text;v_read_json jsonb;v_read_bytes bytea;v_read_hash text;v_read_count integer;v_include_authority boolean:=false;
BEGIN
  IF p_lease<>120 THEN RETURN NULL; END IF;v_hash:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');
  SELECT * INTO v_run FROM public.legacy_producer_runs_v3_11 WHERE run_id=p_run AND status='running' AND owner_token_hash=v_hash AND lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO v_job FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job AND run_id=p_run AND status IN ('queued','retryable') FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  UPDATE public.legacy_producer_jobs_v3_11 SET status='leased',attempt=attempt+1,owner_token_hash=v_hash,leased_at=v_now,heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE job_id=p_job RETURNING * INTO v_job;
  UPDATE public.legacy_producer_runs_v3_11 SET heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE run_id=p_run;
  SELECT * INTO v_payload FROM public.legacy_producer_job_payloads_v3_11 WHERE job_id=p_job;
  IF v_job.predecessor_job_id IS NOT NULL THEN SELECT * INTO v_prior FROM public.legacy_producer_job_results_v3_11 WHERE job_id=v_job.predecessor_job_id; END IF;
  IF v_job.job_kind='revision_shard' THEN
    SELECT selected_revision_row_hash,
      CASE WHEN jsonb_array_length(selected_revision_row_json)=11 THEN (selected_revision_row_json->>5)::timestamptz ELSE NULL END,
      CASE WHEN jsonb_array_length(selected_revision_row_json)=11 THEN (selected_revision_row_json->>6)::timestamptz ELSE (selected_revision_row_json->>5)::timestamptz END
    INTO v_selected_hash,v_source_published_at,v_source_collected_at FROM public.legacy_frozen_source_revisions_v3_11 WHERE run_id=p_run AND revision_id=v_job.revision_id;
    v_frozen:=public.read_legacy_frozen_revision_v3_11(p_run,p_job,v_hash,v_job.revision_id,v_selected_hash);
    IF v_frozen IS NULL THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
    v_frozen_json:=jsonb_build_object('runId',(v_frozen).run_id,'jobId',(v_frozen).job_id,'selectionOrdinal',(v_frozen).selection_ordinal,'sourceKey',(v_frozen).source_key,'revisionId',(v_frozen).revision_id,'sourcePublishedAt',CASE WHEN v_source_published_at IS NULL THEN NULL ELSE to_char(v_source_published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') END,'sourceCollectedAt',to_char(v_source_collected_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'selectedRevisionRowHash',(v_frozen).selected_revision_row_hash,'rawFieldPayload',(v_frozen).raw_field_payload,'rawCodePointCount',(v_frozen).raw_code_point_count,'rawFieldPayloadAlgorithmVersion',(v_frozen).raw_field_payload_algorithm_version,'ingestionContentRevisionSha256',(v_frozen).ingestion_content_revision_sha256,'canonicalContentAlgorithmVersion',(v_frozen).canonical_content_algorithm_version,'ingestionCanonicalContentHashV3',(v_frozen).ingestion_canonical_content_hash_v3);
    v_frozen_bytes:=convert_to(v_frozen_json::text,'utf8');v_frozen_hash:=encode(extensions.digest(v_frozen_bytes,'sha256'),'hex');
  END IF;
  IF v_job.stage<>'source_sync' THEN
    IF v_job.job_kind='revision_shard' THEN
      v_read_kind:='frozen_revision_authority';
      v_include_authority:=current_setting('stockinsider.legacy_authority_hash',true) IS DISTINCT FROM v_run.authority_hash;
      IF v_include_authority THEN
        SELECT jsonb_build_object(
          'authorityHash',v_run.authority_hash,
          'authorityPages',coalesce(jsonb_agg(jsonb_build_array(page_kind,page_ordinal,page_hash,page_json)
            ORDER BY page_kind,page_ordinal),'[]'::jsonb),
          'frozenRevision',v_frozen_json
        ),coalesce(sum(row_count),0)::integer
        INTO v_read_json,v_read_count
        FROM public.legacy_producer_authority_pages_v3_11 WHERE run_id=p_run;
      ELSE
        v_read_json:=jsonb_build_object('authorityHash',v_run.authority_hash,'authorityPages','[]'::jsonb,
          'frozenRevision',v_frozen_json);
        v_read_count:=1;
      END IF;
    ELSIF v_job.stage='mention_claim_extraction' THEN
      v_read_kind:='mention_shard_results';
      SELECT jsonb_build_object('results',coalesce(jsonb_agg(result.result_json ORDER BY job.shard_ordinal),'[]'::jsonb)),count(*)::integer
      INTO v_read_json,v_read_count
      FROM public.legacy_producer_jobs_v3_11 job JOIN public.legacy_producer_job_results_v3_11 result ON result.job_id=job.job_id
      WHERE job.run_id=p_run AND job.stage='mention_claim_extraction' AND job.job_kind='revision_shard' AND job.status='succeeded';
    ELSIF v_job.stage='candidate_funnel' THEN
      v_read_kind:='candidate_funnel_input';
      v_read_json:=jsonb_build_object(
        'mentionResult',v_prior.result_json,
        'seedSymbols',to_jsonb(v_run.legacy_seed_symbols),
        'priorLedger',coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'stockId',prior.stock_id,'symbol',prior.symbol,'materialEvidenceHash',prior.material_evidence_hash,
            'disposition',prior.disposition,'sourceCutoff',prior.source_cutoff
          ) ORDER BY prior.stock_id)
          FROM (
            WITH prior_success AS (
              SELECT prior_run.run_id,prior_run.source_cutoff
              FROM public.legacy_producer_runs_v3_11 prior_run
              WHERE prior_run.status='success' AND prior_run.source_cutoff<v_run.source_cutoff
              ORDER BY prior_run.source_cutoff DESC,prior_run.terminal_at DESC,prior_run.run_id LIMIT 1
            )
            SELECT DISTINCT ON (ledger.stock_id) ledger.stock_id,ledger.symbol,ledger.material_evidence_hash,
              ledger.disposition,prior_success.source_cutoff
            FROM prior_success JOIN public.legacy_candidate_discovery_ledger_v3_11 ledger
              ON ledger.source_run_id=prior_success.run_id
            WHERE ledger.stock_id IS NOT NULL
            ORDER BY ledger.stock_id,ledger.recorded_at DESC,ledger.discovery_id
            LIMIT 60
          ) prior
        ),'[]'::jsonb)
      );v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'candidates'),0);
    ELSIF v_job.stage='facts_refresh' THEN
      v_read_kind:='candidate_fact_plane';
      v_read_json:=public.read_legacy_candidate_fact_plane_v3_11(v_run.source_cutoff,v_prior.result_json);
      v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'candidates'),0);
    ELSIF v_job.stage='analysis_revision' THEN
      v_read_kind:='analysis_revision_input';
      v_read_json:=jsonb_build_object(
        'factsResult',v_prior.result_json,
        'sourceCutoff',to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'producerCommitSha',v_run.producer_commit_sha,
        'priorRevisions',coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'symbol',prior.symbol,'revisionId',prior.revision_id,'materialChangeHash',prior.material_change_hash,
            'analysisGeneratedAt',to_char(prior.analysis_generated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
          ) ORDER BY prior.symbol)
          FROM (
            SELECT DISTINCT ON (revision.symbol) revision.symbol,revision.revision_id,
              revision.material_change_hash,revision.analysis_generated_at,revision.source_cutoff
            FROM public.legacy_analysis_revisions_v3_11 revision
            WHERE revision.symbol IN (
              SELECT decision.value->>'symbol' FROM jsonb_array_elements(coalesce(v_prior.result_json->'decisions','[]'::jsonb)) decision(value)
            ) AND revision.source_cutoff<v_run.source_cutoff
            ORDER BY revision.symbol,revision.source_cutoff DESC,revision.recorded_at DESC,revision.revision_id
          ) prior
        ),'[]'::jsonb)
      );v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'decisions'),0);
    ELSE
      SELECT result.* INTO STRICT v_source_result
      FROM public.legacy_producer_jobs_v3_11 source_job
      JOIN public.legacy_producer_job_results_v3_11 result ON result.job_id=source_job.job_id
      WHERE source_job.run_id=p_run AND source_job.stage='source_sync'
        AND source_job.job_kind='stage_barrier' AND source_job.status='succeeded';
      IF jsonb_typeof(v_source_result.result_json->'legacyPayloads')<>'object'
        OR jsonb_typeof(v_source_result.result_json->'legacyPayloadHashes')<>'object'
      THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      v_read_kind:='compact_projection_input';v_read_json:=jsonb_build_object('analysisResult',v_prior.result_json,'sourceCutoff',to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'producerCommitSha',v_run.producer_commit_sha,'workerSha256',v_run.worker_sha256,'legacyPayloads',v_source_result.result_json->'legacyPayloads','legacyPayloadHashes',v_source_result.result_json->'legacyPayloadHashes','legacySourceResultHash',v_source_result.result_hash);v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'decisions'),0);
    END IF;
    v_read_bytes:=convert_to(v_read_json::text,'utf8');v_read_hash:=encode(extensions.digest(v_read_bytes,'sha256'),'hex');
    IF octet_length(v_read_bytes)>3145728 OR v_read_count>20000 THEN RAISE EXCEPTION 'bound_violation';END IF;
  END IF;
  RETURN ROW(v_job.run_id,v_job.job_id,v_job.stage,v_job.job_kind,v_job.stage_ordinal,v_job.shard_ordinal,v_job.execution_ordinal,v_job.revision_id,v_job.attempt,
    v_payload.payload_canonical,v_payload.payload_json,v_payload.payload_hash,v_prior.result_canonical,v_prior.result_json,v_prior.result_hash,
    CASE WHEN v_job.stage='source_sync' THEN 'legacy-discovery-authority-v1' ELSE NULL END,CASE WHEN v_job.stage='source_sync' THEN v_run.authority_canonical ELSE NULL END,
    CASE WHEN v_job.stage='source_sync' THEN v_run.authority_json ELSE NULL END,CASE WHEN v_job.stage='source_sync' THEN v_run.authority_hash ELSE NULL END,v_frozen_bytes,v_frozen_json,v_frozen_hash,
    v_read_kind,v_read_bytes,v_read_json,v_read_hash,v_read_count,v_job.lease_expires_at)::public.legacy_producer_claim_v3_11;
END $$;
CREATE OR REPLACE FUNCTION heartbeat_legacy_producer_job_v3_11(p_run uuid,p_job uuid,p_token uuid,p_lease integer)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_now timestamptz:=date_trunc('second',clock_timestamp());
BEGIN
  IF p_lease<>120 THEN RETURN false; END IF;
  PERFORM 1 FROM public.legacy_producer_runs_v3_11
  WHERE run_id=p_run AND status='running' AND owner_token_hash=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex')
    AND lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11
  WHERE run_id=p_run AND job_id=p_job AND status='leased' AND owner_token_hash=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex')
    AND lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  UPDATE public.legacy_producer_runs_v3_11 SET heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE run_id=p_run;
  UPDATE public.legacy_producer_jobs_v3_11 SET heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE run_id=p_run AND job_id=p_job;
  RETURN true;
END $$;
CREATE OR REPLACE FUNCTION complete_legacy_producer_job_v3_11(p_run uuid,p_job uuid,p_token uuid,p_result bytea,p_json jsonb,p_hash text)
RETURNS TABLE(status text,next_job jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_job public.legacy_producer_jobs_v3_11%ROWTYPE;v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_frozen public.legacy_frozen_source_revisions_v3_11%ROWTYPE;v_now timestamptz:=date_trunc('second',clock_timestamp());v_next uuid;v_stage public.opportunity_legacy_producer_stage_v3_11;v_kind public.opportunity_legacy_producer_job_kind_v3_11:='stage_barrier';v_payload bytea;v_payload_json jsonb;v_payload_hash text;v_shard integer;v_revision uuid;v_item jsonb;v_revision_id uuid;v_prior_revision_id uuid;v_revision_created boolean;v_projection jsonb;v_projection_bytes bytea;v_uuid_hash text;v_prior_json jsonb;v_expected_symbols text[];v_actual_symbols text[];v_expected_deep text[];v_actual_deep text[];v_expected_shallow text[];v_actual_shallow text[];v_expected_source text[];v_actual_source text[];
BEGIN
  IF octet_length(p_result)>3145728 OR convert_from(p_result,'utf8')::jsonb<>p_json OR encode(extensions.digest(p_result,'sha256'),'hex')<>p_hash THEN RAISE EXCEPTION 'data_integrity_failure'; END IF;
  SELECT run.* INTO v_run FROM public.legacy_producer_runs_v3_11 run WHERE run.run_id=p_run AND run.status='running'
    AND run.owner_token_hash=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex')
    AND run.lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT job.* INTO v_job FROM public.legacy_producer_jobs_v3_11 job WHERE job.run_id=p_run AND job.job_id=p_job AND job.status='leased'
    AND job.owner_token_hash=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex')
    AND job.lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_job.predecessor_job_id IS NOT NULL THEN
    SELECT result_json INTO STRICT v_prior_json FROM public.legacy_producer_job_results_v3_11 WHERE job_id=v_job.predecessor_job_id;
  END IF;
  IF (v_job.stage='source_sync' AND p_json->>'schema'<>'legacy-source-sync-result-v3.11')
    OR (v_job.stage='mention_claim_extraction' AND v_job.job_kind='revision_shard' AND p_json->>'schema'<>'legacy-mention-claim-result-v3.11')
    OR (v_job.stage='mention_claim_extraction' AND v_job.job_kind='stage_barrier' AND p_json->>'schema'<>'legacy-mention-barrier-result-v3.11')
    OR (v_job.stage='candidate_funnel' AND p_json->>'schema'<>'legacy-candidate-funnel-result-v3.11')
    OR (v_job.stage='facts_refresh' AND p_json->>'schema'<>'legacy-facts-refresh-result-v3.11')
    OR (v_job.stage='analysis_revision' AND p_json->>'schema'<>'legacy-analysis-revision-result-v3.11')
    OR (v_job.stage='compact_radar_projection' AND p_json->>'schema'<>'legacy-compact-projection-result-v3.11')
  THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  IF v_job.stage='candidate_funnel' THEN
    IF jsonb_array_length(coalesce(p_json->'candidates','[]'::jsonb))>60 THEN RAISE EXCEPTION 'bound_violation';END IF;
    FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_json->'candidates','[]'::jsonb)) item(value) LOOP
      INSERT INTO public.legacy_candidate_discovery_ledger_v3_11(
        discovery_id,source_run_id,source_key,document_revision_id,claim_id,mention_id,stock_id,symbol,
        disposition,reason,research_disposition,research_reason,seed_membership,legacy_seed_set_hash,
        material_evidence_hash,recorded_at
      ) VALUES(extensions.gen_random_uuid(),p_run,(v_item->>'sourceKey')::public.source_key_v3,
        NULLIF(v_item->>'revisionId','')::uuid,NULLIF(v_item->>'claimId','')::uuid,NULLIF(v_item->>'mentionId','')::uuid,(v_item->>'stockId')::uuid,v_item->>'symbol',
        (v_item->>'disposition')::public.opportunity_candidate_discovery_disposition_v3_11,
        (v_item->>'reason')::public.opportunity_candidate_discovery_reason_v3_11,
        (v_item->>'researchDisposition')::public.opportunity_candidate_research_disposition_v3_11,
        NULLIF(v_item->>'researchReason','')::public.opportunity_candidate_research_reason_v3_11,
        (v_item->>'seedMembership')::public.opportunity_candidate_seed_membership_v3_11,
        v_run.legacy_seed_set_hash,v_item->>'materialEvidenceHash',v_now)
      ON CONFLICT(source_run_id,source_key,document_revision_id,claim_id,mention_id,stock_id,reason) DO NOTHING;
    END LOOP;
  ELSIF v_job.stage='facts_refresh' THEN
    IF jsonb_array_length(coalesce(p_json->'decisions','[]'::jsonb))>20
      OR jsonb_array_length(coalesce(p_json->'shallowObservations','[]'::jsonb))>10
      OR jsonb_array_length(coalesce(p_json->'sourceCandidates','[]'::jsonb))>40
    THEN RAISE EXCEPTION 'bound_violation';END IF;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_symbols
      FROM jsonb_array_elements(coalesce(v_prior_json->'candidates','[]'::jsonb)) item(value);
    SELECT array_agg(symbol ORDER BY symbol) INTO v_actual_symbols FROM (
      SELECT value->>'symbol' symbol FROM jsonb_array_elements(coalesce(p_json->'decisions','[]'::jsonb)) item(value)
      UNION ALL SELECT value->>'symbol' FROM jsonb_array_elements(coalesce(p_json->'sourceCandidates','[]'::jsonb)) item(value)
    ) actual;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_deep
      FROM jsonb_array_elements(coalesce(v_prior_json->'candidates','[]'::jsonb)) item(value) WHERE (value->>'deepSelected')::boolean;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_actual_deep FROM jsonb_array_elements(coalesce(p_json->'decisions','[]'::jsonb)) item(value);
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_shallow
      FROM jsonb_array_elements(coalesce(v_prior_json->'candidates','[]'::jsonb)) item(value) WHERE (value->>'shallowSelected')::boolean AND NOT (value->>'deepSelected')::boolean;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_actual_shallow FROM jsonb_array_elements(coalesce(p_json->'shallowObservations','[]'::jsonb)) item(value);
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_source
      FROM jsonb_array_elements(coalesce(v_prior_json->'candidates','[]'::jsonb)) item(value) WHERE NOT (value->>'deepSelected')::boolean;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_actual_source FROM jsonb_array_elements(coalesce(p_json->'sourceCandidates','[]'::jsonb)) item(value);
    IF coalesce(v_expected_symbols,ARRAY[]::text[])<>coalesce(v_actual_symbols,ARRAY[]::text[])
      OR cardinality(coalesce(v_actual_symbols,ARRAY[]::text[]))<>cardinality(ARRAY(SELECT DISTINCT unnest(coalesce(v_actual_symbols,ARRAY[]::text[]))))
      OR coalesce(v_expected_deep,ARRAY[]::text[])<>coalesce(v_actual_deep,ARRAY[]::text[])
      OR coalesce(v_expected_shallow,ARRAY[]::text[])<>coalesce(v_actual_shallow,ARRAY[]::text[])
      OR coalesce(v_expected_source,ARRAY[]::text[])<>coalesce(v_actual_source,ARRAY[]::text[])
    THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  ELSIF v_job.stage='analysis_revision' THEN
    IF jsonb_array_length(coalesce(p_json->'decisions','[]'::jsonb))>60 THEN RAISE EXCEPTION 'bound_violation';END IF;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_symbols
      FROM jsonb_array_elements(coalesce(v_prior_json->'decisions','[]'::jsonb)) item(value);
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_actual_symbols
      FROM jsonb_array_elements(coalesce(p_json->'decisions','[]'::jsonb)) item(value);
    IF coalesce(v_expected_symbols,ARRAY[]::text[])<>coalesce(v_actual_symbols,ARRAY[]::text[])
      OR cardinality(coalesce(v_actual_symbols,ARRAY[]::text[]))<>cardinality(ARRAY(SELECT DISTINCT unnest(coalesce(v_actual_symbols,ARRAY[]::text[]))))
    THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
    FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_json->'decisions','[]'::jsonb)) item(value) LOOP
      v_revision_created:=false;v_prior_revision_id:=NULL;
      SELECT revision_id INTO v_revision_id FROM public.legacy_analysis_revisions_v3_11
      WHERE symbol=v_item->>'symbol' AND material_change_hash=v_item->>'materialChangeHash';
      IF v_revision_id IS NULL THEN
        SELECT revision_id INTO v_prior_revision_id FROM public.legacy_analysis_revisions_v3_11
        WHERE symbol=v_item->>'symbol' AND source_cutoff<v_run.source_cutoff
        ORDER BY source_cutoff DESC,recorded_at DESC,revision_id LIMIT 1;
        v_revision_id:=extensions.gen_random_uuid();
        INSERT INTO public.legacy_analysis_revisions_v3_11 VALUES(
          v_revision_id,v_item->>'symbol',v_run.source_cutoff,v_item->>'materialChangeHash',v_prior_revision_id,
          (v_item->>'researchMaturity')::public.opportunity_research_maturity_v3_11,
          CASE WHEN v_item->'valuation'->>'status'='normal' THEN 'normal' ELSE 'valuation_review' END,
          CASE WHEN v_item->>'action' IN ('avoid','valuation_review','wait_trigger','event_starter','starter_now') THEN v_item->>'action' ELSE 'valuation_review' END,
          encode(extensions.digest(convert_to(coalesce((v_item->'fundamental')::text,'null'),'utf8'),'sha256'),'hex'),
          CASE WHEN v_item->'technical' IS NULL THEN NULL ELSE encode(extensions.digest(convert_to((v_item->'technical')::text,'utf8'),'sha256'),'hex') END,
          CASE WHEN v_item->'valuation' IS NULL THEN NULL ELSE encode(extensions.digest(convert_to((v_item->'valuation')::text,'utf8'),'sha256'),'hex') END,
          jsonb_build_array(v_item->>'claimId'),'legacy-structured-narrative-v3.11',jsonb_build_array(v_item->>'claimId'),
          '來源訊號已重新檢查；估值與技術證據完整前不形成買進建議。',
          encode(extensions.digest(convert_to('來源訊號已重新檢查；估值與技術證據完整前不形成買進建議。','utf8'),'sha256'),'hex'),
          coalesce(NULLIF(v_item->>'analysisGeneratedAt','')::timestamptz,v_run.source_cutoff),v_run.producer_commit_sha,v_now);
        v_revision_created:=true;
      END IF;
      INSERT INTO public.legacy_analysis_evaluations_v3_11 VALUES(
        extensions.gen_random_uuid(),v_item->>'symbol',v_revision_id,v_item->>'materialChangeHash',
        CASE
          WHEN v_revision_created THEN 'material_revision_created'::public.opportunity_analysis_evaluation_disposition_v3_11
          ELSE 'no_material_change'::public.opportunity_analysis_evaluation_disposition_v3_11
        END,
        v_run.source_cutoff,v_run.source_cutoff,NULL,NULL,'scheduled_material_check',p_run,v_now)
      ON CONFLICT(producer_run_id,symbol) DO NOTHING;
    END LOOP;
  ELSIF v_job.stage='compact_radar_projection' THEN
    IF jsonb_array_length(coalesce(p_json->'projections','[]'::jsonb))<>4
      OR (SELECT array_agg(value->>'storageWindow' ORDER BY value->>'storageWindow')
          FROM jsonb_array_elements(p_json->'projections') item(value))
        <>ARRAY['daily','home','three_day','weekly']::text[]
    THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
    FOR v_projection IN SELECT value FROM jsonb_array_elements(p_json->'projections') item(value) LOOP
      v_projection_bytes:=convert_to(v_projection#>>'{bundle,canonical}','utf8');
      IF convert_from(v_projection_bytes,'utf8')::jsonb<>v_projection->'payload'
        OR encode(extensions.digest(v_projection_bytes,'sha256'),'hex')<>v_projection->>'payloadChecksum'
      THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      INSERT INTO public.legacy_radar_projections_v3_11(
        projection_key,"window",as_of,producer_commit_sha,worker_sha256,material_change_root,
        payload_canonical,payload_json,payload_sha256
      ) VALUES(v_projection->>'projectionKey',v_projection->>'storageWindow',v_run.source_cutoff,
        v_run.producer_commit_sha,v_run.worker_sha256,
        encode(extensions.digest(convert_to(coalesce((p_json->'projections')::text,'[]'),'utf8'),'sha256'),'hex'),
        v_projection_bytes,v_projection->'payload',v_projection->>'payloadChecksum')
      ON CONFLICT(projection_key) DO NOTHING;
    END LOOP;
  END IF;
  INSERT INTO public.legacy_producer_job_results_v3_11 VALUES(p_job,p_result,p_json,p_hash,v_now) ON CONFLICT(job_id) DO NOTHING;
  UPDATE public.legacy_producer_jobs_v3_11 SET status='succeeded',terminal_at=v_now,owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL WHERE job_id=p_job;
  IF v_job.stage_ordinal=5 THEN UPDATE public.legacy_producer_runs_v3_11 SET status='success',terminal_at=v_now,heartbeat_at=v_now,lease_expires_at=v_now WHERE run_id=p_run;status:='success';next_job:=NULL;RETURN NEXT;RETURN; END IF;
  IF v_job.stage='source_sync' OR v_job.job_kind='revision_shard' THEN
    SELECT * INTO v_frozen FROM public.legacy_frozen_source_revisions_v3_11 WHERE run_id=p_run AND selection_ordinal>coalesce(v_job.shard_ordinal,-1) ORDER BY selection_ordinal LIMIT 1;
    v_stage:='mention_claim_extraction';
    IF FOUND THEN v_kind:='revision_shard';v_shard:=v_frozen.selection_ordinal;v_revision:=v_frozen.revision_id;
    ELSE v_kind:='stage_barrier';v_shard:=NULL;v_revision:=NULL;END IF;
  ELSE
    v_stage:=(ARRAY['source_sync','mention_claim_extraction','candidate_funnel','facts_refresh','analysis_revision','compact_radar_projection']::public.opportunity_legacy_producer_stage_v3_11[])[v_job.stage_ordinal+2];
  END IF;
  v_uuid_hash:=encode(extensions.digest(convert_to('legacy-job:'||p_run::text||':'||(v_job.execution_ordinal+1)::text,'utf8'),'sha256'),'hex');
  v_next:=(substr(v_uuid_hash,1,8)||'-'||substr(v_uuid_hash,9,4)||'-'||substr(v_uuid_hash,13,4)||'-'||substr(v_uuid_hash,17,4)||'-'||substr(v_uuid_hash,21,12))::uuid;
  v_payload_json:=jsonb_build_array('e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743',p_hash,v_stage::text,v_kind::text,v_shard,v_revision);v_payload:=convert_to(v_payload_json::text,'utf8');v_payload_hash:=encode(extensions.digest(v_payload,'sha256'),'hex');
  INSERT INTO public.legacy_producer_jobs_v3_11 VALUES(v_next,p_run,v_stage,v_kind,CASE WHEN v_stage='mention_claim_extraction' THEN 1 ELSE v_job.stage_ordinal+1 END,v_shard,v_job.execution_ordinal+1,v_revision,p_job,v_payload_hash,v_payload_hash,'queued',0,5,NULL,NULL,NULL,NULL,NULL,NULL,v_now);
  INSERT INTO public.legacy_producer_job_payloads_v3_11 VALUES(v_next,v_payload,v_payload_json,v_payload_hash,v_now);
  status:='running';next_job:=jsonb_build_object('jobId',v_next,'stage',v_stage);RETURN NEXT;
END $$;
CREATE OR REPLACE FUNCTION fail_legacy_producer_job_v3_11(p_run uuid,p_job uuid,p_token uuid,p_failure opportunity_legacy_producer_failure_code_v3_11)
RETURNS TABLE(status text) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_job public.legacy_producer_jobs_v3_11%ROWTYPE;v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_now timestamptz:=date_trunc('second',clock_timestamp());v_token_hash text:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');
BEGIN
  SELECT run.* INTO v_run FROM public.legacy_producer_runs_v3_11 run WHERE run.run_id=p_run AND run.status='running'
    AND run.owner_token_hash=v_token_hash AND run.lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT job.* INTO v_job FROM public.legacy_producer_jobs_v3_11 job WHERE job.run_id=p_run AND job.job_id=p_job AND job.status='leased'
    AND job.owner_token_hash=v_token_hash AND job.lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  IF p_failure='provider_unavailable' AND v_job.attempt<5 THEN UPDATE public.legacy_producer_jobs_v3_11 SET status='retryable',owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL WHERE job_id=p_job;status:='running';
  ELSE UPDATE public.legacy_producer_jobs_v3_11 SET status=CASE
      WHEN p_failure='cancelled' THEN 'cancelled'::public.opportunity_legacy_producer_job_status_v3_11
      ELSE 'failed'::public.opportunity_legacy_producer_job_status_v3_11
    END,terminal_at=v_now,failure_code=p_failure,owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL WHERE job_id=p_job;
    UPDATE public.legacy_producer_runs_v3_11 SET status=CASE WHEN p_failure='cancelled' THEN 'cancelled' ELSE 'failed' END,terminal_at=v_now,failure_code=p_failure,heartbeat_at=v_now,lease_expires_at=v_now WHERE run_id=p_run;status:=CASE WHEN p_failure='cancelled' THEN 'cancelled' ELSE 'failed' END;END IF;RETURN NEXT;
END $$;
CREATE OR REPLACE FUNCTION reap_legacy_producer_jobs_v3_11(p_limit integer)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_count integer:=0;v_row record;v_attempt smallint;
BEGIN
  IF p_limit<1 OR p_limit>1000 THEN RAISE EXCEPTION 'invalid reap limit'; END IF;
  FOR v_row IN SELECT run_id,job_id FROM public.legacy_producer_jobs_v3_11 WHERE status='leased' AND lease_expires_at<clock_timestamp() ORDER BY lease_expires_at LIMIT p_limit LOOP
    PERFORM 1 FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_row.run_id FOR UPDATE;
    SELECT attempt INTO v_attempt FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_row.run_id AND job_id=v_row.job_id AND status='leased' AND lease_expires_at<clock_timestamp() FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN CONTINUE;END IF;
    UPDATE public.legacy_producer_jobs_v3_11 SET status=CASE
        WHEN v_attempt<5 THEN 'retryable'::public.opportunity_legacy_producer_job_status_v3_11
        ELSE 'failed'::public.opportunity_legacy_producer_job_status_v3_11
      END,failure_code=CASE WHEN v_attempt<5 THEN NULL ELSE 'job_attempts_exhausted'::public.opportunity_legacy_producer_failure_code_v3_11 END,
      terminal_at=CASE WHEN v_attempt<5 THEN NULL ELSE date_trunc('second',clock_timestamp()) END,owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL WHERE job_id=v_row.job_id;
    IF v_attempt>=5 THEN UPDATE public.legacy_producer_runs_v3_11 SET status='failed',failure_code='job_attempts_exhausted',terminal_at=date_trunc('second',clock_timestamp()) WHERE run_id=v_row.run_id;END IF;v_count:=v_count+1;
  END LOOP;RETURN v_count;
END $$;

CREATE OR REPLACE FUNCTION append_legacy_candidate_discovery_v3_11(p_input candidate_discovery_input_v3_11,p_job uuid,p_token uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_id uuid;v_seed public.opportunity_candidate_seed_membership_v3_11;v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_token_hash text:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT * INTO v_run FROM public.legacy_producer_runs_v3_11 WHERE run_id=(p_input).source_run_id AND status='running' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure'; END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_run.run_id AND job_id=p_job AND stage='candidate_funnel' AND status='leased' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND OR (p_input).material_evidence_hash!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'data_integrity_failure'; END IF;
  IF (p_input).stock_id IS NOT NULL THEN v_seed:=CASE WHEN (p_input).symbol=ANY(v_run.legacy_seed_symbols) THEN 'in_seed' ELSE 'out_of_seed' END;END IF;
  SELECT discovery_id INTO v_id FROM public.legacy_candidate_discovery_ledger_v3_11 WHERE source_run_id=(p_input).source_run_id AND source_key=(p_input).source_key AND document_revision_id IS NOT DISTINCT FROM (p_input).document_revision_id AND claim_id IS NOT DISTINCT FROM (p_input).claim_id AND mention_id IS NOT DISTINCT FROM (p_input).mention_id AND stock_id IS NOT DISTINCT FROM (p_input).stock_id AND reason=(p_input).reason;
  IF v_id IS NOT NULL THEN RETURN v_id;END IF;v_id:=extensions.gen_random_uuid();
  INSERT INTO public.legacy_candidate_discovery_ledger_v3_11 VALUES(v_id,(p_input).source_run_id,(p_input).source_key,(p_input).document_revision_id,(p_input).claim_id,(p_input).mention_id,(p_input).stock_id,(p_input).symbol,(p_input).disposition,(p_input).reason,(p_input).research_disposition,(p_input).research_reason,v_seed,CASE WHEN v_seed IS NULL THEN NULL ELSE v_run.legacy_seed_set_hash END,(p_input).material_evidence_hash,clock_timestamp());RETURN v_id;
END $$;
CREATE OR REPLACE FUNCTION append_legacy_analysis_revision_v3_11(p_input analysis_revision_input_v3_11,p_job uuid,p_token uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_id uuid;v_run uuid;v_token_hash text:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT run_id INTO v_run FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job;
  PERFORM 1 FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run AND status='running' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_run AND job_id=p_job AND stage='analysis_revision' AND status='leased' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  SELECT revision_id INTO v_id FROM public.legacy_analysis_revisions_v3_11 WHERE symbol=(p_input).symbol AND material_change_hash=(p_input).material_change_hash;IF v_id IS NOT NULL THEN RETURN v_id;END IF;v_id:=extensions.gen_random_uuid();
  INSERT INTO public.legacy_analysis_revisions_v3_11 VALUES(v_id,(p_input).symbol,(p_input).source_cutoff,(p_input).material_change_hash,(p_input).prior_revision_id,(p_input).research_maturity,(p_input).formal_research_status,(p_input).new_position_action,(p_input).fundamental_snapshot_hash,(p_input).technical_decision_hash,(p_input).valuation_input_hash,(p_input).locked_claims,(p_input).narrative_template_version,(p_input).sentence_claim_refs,(p_input).narrative,(p_input).narrative_hash,(p_input).analysis_generated_at,(p_input).producer_commit_sha,clock_timestamp());RETURN v_id;
END $$;
CREATE OR REPLACE FUNCTION append_legacy_analysis_evaluation_v3_11(p_input analysis_evaluation_input_v3_11,p_job uuid,p_token uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_id uuid;v_run uuid;v_token_hash text:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT run_id INTO v_run FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job;
  PERFORM 1 FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run AND status='running' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_run AND job_id=p_job AND stage='analysis_revision' AND status='leased' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  SELECT evaluation_id INTO v_id FROM public.legacy_analysis_evaluations_v3_11 WHERE producer_run_id=v_run AND symbol=(p_input).symbol;IF v_id IS NOT NULL THEN RETURN v_id;END IF;v_id:=extensions.gen_random_uuid();
  INSERT INTO public.legacy_analysis_evaluations_v3_11 VALUES(v_id,(p_input).symbol,(p_input).revision_id,(p_input).evaluated_material_change_hash,(p_input).disposition,(p_input).evaluated_at,(p_input).evaluated_source_cutoff,(p_input).evaluated_price_session,(p_input).evaluated_adjusted_close,(p_input).trigger,v_run,clock_timestamp());RETURN v_id;
END $$;
CREATE OR REPLACE FUNCTION append_legacy_radar_projection_v3_11(p_input legacy_radar_projection_input_v3_11,p_job uuid,p_token uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_id uuid;v_run uuid;v_token_hash text:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT run_id INTO v_run FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job;
  PERFORM 1 FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run AND status='running' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now AND producer_commit_sha=(p_input).producer_commit_sha AND worker_sha256=(p_input).worker_sha256 FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_run AND job_id=p_job AND stage='compact_radar_projection' AND status='leased' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  IF (p_input)."window" NOT IN ('daily','three_day','weekly','home') OR (p_input).payload_sha256<>encode(extensions.digest((p_input).payload_canonical,'sha256'),'hex') OR convert_from((p_input).payload_canonical,'utf8')::jsonb<>(p_input).payload_json OR (p_input).projection_key<>'legacy-radar-v3.11:'||(p_input)."window"||':'||to_char((p_input).as_of AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')||':'||(p_input).payload_sha256 THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended((p_input)."window",0));SELECT projection_id INTO v_id FROM public.legacy_radar_projections_v3_11 WHERE projection_key=(p_input).projection_key;
  IF v_id IS NULL THEN v_id:=extensions.gen_random_uuid();INSERT INTO public.legacy_radar_projections_v3_11(projection_id,projection_key,"window",as_of,producer_commit_sha,worker_sha256,material_change_root,payload_canonical,payload_json,payload_sha256) VALUES(v_id,(p_input).projection_key,(p_input)."window",(p_input).as_of,(p_input).producer_commit_sha,(p_input).worker_sha256,(p_input).material_change_root,(p_input).payload_canonical,(p_input).payload_json,(p_input).payload_sha256);END IF;
  PERFORM set_config('stockinsider.legacy_projection_retention','on',true);DELETE FROM public.legacy_radar_projections_v3_11 WHERE projection_id IN (SELECT projection_id FROM public.legacy_radar_projections_v3_11 WHERE "window"=(p_input)."window" ORDER BY as_of DESC,created_at DESC,projection_id ASC OFFSET 1500);RETURN v_id;
END $$;

DO $legacy_correctness_security$
DECLARE v_table text;v_signature text;
BEGIN
  FOREACH v_table IN ARRAY ARRAY['legacy_producer_runs_v3_11','legacy_producer_authority_pages_v3_11','legacy_frozen_source_revisions_v3_11','legacy_producer_jobs_v3_11','legacy_producer_job_payloads_v3_11','legacy_producer_job_results_v3_11','legacy_candidate_discovery_ledger_v3_11','legacy_analysis_revisions_v3_11','legacy_analysis_evaluations_v3_11','legacy_radar_projections_v3_11','legacy_runtime_health_observations_v3_11'] LOOP
    EXECUTE format('ALTER TABLE public.%I OWNER TO legacy_correctness_rpc_owner',v_table);EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',v_table);EXECUTE format('ALTER TABLE public.%I NO FORCE ROW LEVEL SECURITY',v_table);EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated,service_role',v_table);
  END LOOP;
  ALTER FUNCTION public.legacy_correctness_immutable_v3_11() OWNER TO legacy_correctness_rpc_owner;
  FOREACH v_signature IN ARRAY ARRAY[
    'public.acquire_legacy_producer_lease_v3_11(text,text,text,bytea,text,uuid,integer)','public.claim_legacy_producer_job_v3_11(uuid,uuid,uuid,integer)',
    'public.heartbeat_legacy_producer_job_v3_11(uuid,uuid,uuid,integer)','public.complete_legacy_producer_job_v3_11(uuid,uuid,uuid,bytea,jsonb,text)',
    'public.fail_legacy_producer_job_v3_11(uuid,uuid,uuid,opportunity_legacy_producer_failure_code_v3_11)','public.reap_legacy_producer_jobs_v3_11(integer)',
    'public.append_legacy_candidate_discovery_v3_11(candidate_discovery_input_v3_11,uuid,uuid)','public.append_legacy_analysis_revision_v3_11(analysis_revision_input_v3_11,uuid,uuid)',
    'public.append_legacy_analysis_evaluation_v3_11(analysis_evaluation_input_v3_11,uuid,uuid)','public.append_legacy_radar_projection_v3_11(legacy_radar_projection_input_v3_11,uuid,uuid)'] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO legacy_correctness_rpc_owner',v_signature);EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',v_signature);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',v_signature);
  END LOOP;
END
$legacy_correctness_security$;
DO $legacy_helper_read_policies$
DECLARE v_table text;v_policy text;
BEGIN
  FOREACH v_table IN ARRAY ARRAY['legacy_producer_runs_v3_11','legacy_producer_jobs_v3_11','legacy_frozen_source_revisions_v3_11'] LOOP
    v_policy:=v_table||'_opportunity_helper_read';
    IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename=v_table AND policyname=v_policy) THEN
      EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO opportunity_v3_rpc_owner USING (true)',v_policy,v_table);
    END IF;
  END LOOP;
END
$legacy_helper_read_policies$;
GRANT SELECT ON TABLE public.legacy_radar_projections_v3_11 TO service_role;
GRANT SELECT ON TABLE public.legacy_runtime_health_observations_v3_11 TO service_role;
GRANT SELECT ON TABLE public.legacy_producer_runs_v3_11,public.legacy_producer_jobs_v3_11,public.legacy_frozen_source_revisions_v3_11 TO opportunity_v3_rpc_owner;
ALTER FUNCTION public.resolve_legacy_scheduled_occurrence_v3_11(text,text) OWNER TO opportunity_v3_rpc_owner;
ALTER FUNCTION public.read_legacy_discovery_authority_v3_11(uuid,text,text) OWNER TO opportunity_v3_rpc_owner;
ALTER FUNCTION public.read_legacy_frozen_revision_v3_11(uuid,uuid,text,uuid,text) OWNER TO opportunity_v3_rpc_owner;
ALTER FUNCTION public.read_legacy_candidate_fact_plane_v3_11(timestamptz,jsonb) OWNER TO opportunity_v3_rpc_owner;
REVOKE ALL ON FUNCTION public.resolve_legacy_scheduled_occurrence_v3_11(text,text),public.read_legacy_discovery_authority_v3_11(uuid,text,text),public.read_legacy_frozen_revision_v3_11(uuid,uuid,text,uuid,text),public.read_legacy_candidate_fact_plane_v3_11(timestamptz,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.resolve_legacy_scheduled_occurrence_v3_11(text,text),public.read_legacy_discovery_authority_v3_11(uuid,text,text),public.read_legacy_frozen_revision_v3_11(uuid,uuid,text,uuid,text),public.read_legacy_candidate_fact_plane_v3_11(timestamptz,jsonb) TO legacy_correctness_rpc_owner;

REVOKE CREATE ON SCHEMA public FROM legacy_correctness_rpc_owner,opportunity_v3_rpc_owner;

COMMIT;
